(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("plut-lives-2-e", [{"sp": "HDR", "t": "Βίοι Παράλληλοι"}, {"sp": "HDR", "t": "Ἀλκιβιάδης"}, {"sp": "N", "t": "τὸ Ἀλκιβιάδου γένος ἄνωθεν Εὐρυσάκην τὸν Αἴαντος ἀρχηγὸν ἔχειν δοκεῖ, πρὸς δὲ μητρὸς Ἀλκμαιωνίδης ἦν, ἐκ Δεινομάχης γεγονὼς τῆς Μεγακλέους. ὁ δὲ πατὴρ αὐτοῦ Κλεινίας ἰδιοστόλῳ τριήρει περὶ Ἀρτεμίσιον ἐνδόξως ἐναυμάχησεν, ὕστερον δὲ Βοιωτοῖς μαχόμενος περὶ Κορώνειαν ἀπέθανε. τοῦ δὲ Ἀλκιβιάδου Περικλῆς καὶ Ἀρίφρων οἱ Ξανθίππου, προσήκοντες κατὰ γένος, ἐπετρόπευον.", "st": "Alc. 1.1"}, {"sp": "N", "t": "λέγεται δ’ οὐ κακῶς ὅτι τῆς Σωκράτους πρὸς αὐτὸν εὐνοίας καὶ φιλανθρωπίας οὐ μικρὰ πρὸς δόξαν ἀπέλαυσεν, εἴγε Νικίου μὲν καὶ Δημοσθένους καὶ Λαμάχου καὶ Φορμίωνος Θρασυβούλου τε καὶ Θηραμένους, ἐπιφανῶν ἀνδρῶν γενομένων κατ’ αὐτόν, οὐδενὸς οὐδ’ ἡ μήτηρ ὀνόματος τετύχηκεν, Ἀλκιβιάδου δὲ καὶ τίτθην, γένος Λάκαιναν, Ἀμύκλαν ὄνομα, καὶ Ζώπυρον παιδαγωγὸν ἴσμεν, ὧν τὸ μὲν Ἀντισθένης, τὸ δὲ Πλάτων ἱστόρηκε.", "st": "Alc. 1.2"}, {"sp": "N", "t": "περὶ μὲν οὖν τοῦ κάλλους Ἀλκιβιάδου οὐδὲν ἴσως δεῖ λέγειν, πλὴν ὅτι καὶ παῖδα καὶ μειράκιον καὶ ἄνδρα πάσῃ συνανθῆσαν τῇ ἡλικίᾳ καὶ ὥρᾳ τοῦ σώματος ἐράσμιον καὶ ἡδὺν παρέσχεν. οὐ γάρ, ὡς Εὐριπίδης ἔλεγε, πάντων τῶν καλῶν καὶ τὸ μετόπωρον καλόν ἐστιν, ἀλλὰ τοῦτο Ἀλκιβιάδῃ μετ’ ὀλίγων ἄλλων δι’ εὐφυΐαν καὶ ἀρετὴν σώματος ὑπῆρξε. τῇ δὲ φωνῇ καὶ τὴν τραυλότητα ἐμπρέψαι λέγουσι καὶ τῷ λάλῳ πιθανότητα παρασχεῖν χάριν ἐπιτελοῦσαν. μέμνηται δὲ καὶ Ἀριστοφάνης αὐτοῦ τῆς τραυλότητος ἐν οἷς ἐπισκώπτει Θέωρον·", "st": "Alc. 1.3"}, {"sp": "N", "t": "εἶτ’ Ἀλκιβιάδης εἶπε πρός με τραυλίσας·<br>ὁλᾷς Θέωλον; τὴν κεφαλὴν κόλακος ἔχει.<br>ὀρθῶς γε τοῦτ’ Ἀλκιβιάδης ἐτραύλισεν.", "st": "Alc. 1.3b"}, {"sp": "N", "t": "καὶ Ἄρχιππος τὸν υἱὸν τοῦ Ἀλκιβιάδου σκώπτων· βαδίζει, φησί, διακεχλιδώς, θοἰμάτιον ἕλκων, ὅπως ἐμφερὴς μάλιστα τῷ πατρὶ δόξειεν εἶναι,", "st": "Alc. 1.3c"}, {"sp": "N", "t": "κλασαυχενεύεταί τε καὶ τραυλίζεται.", "st": "Alc. 1.3d"}, {"sp": "N", "t": "τὸ δ’ ἦθος αὐτοῦ πολλὰς μὲν ὕστερον, ὡς εἰκὸς ἐν πράγμασι μεγάλοις καὶ τύχαις πολυτρόποις, ἀνομοιότητας πρὸς αὑτὸ καὶ μεταβολὰς ἐπεδείξατο. φύσει δὲ πολλῶν ὄντων καὶ μεγάλων παθῶν ἐν αὐτῷ, τὸ φιλόνεικον ἰσχυρότατον ἦν καὶ τὸ φιλόπρωτον, ὡς δῆλόν ἐστι τοῖς παιδικοῖς ἀπομνημονεύμασιν.", "st": "Alc. 2.1"}, {"sp": "N", "t": "ἐν μὲν γὰρ τῷ παλαίειν πιεζούμενος, ὑπὲρ τοῦ μὴ πεσεῖν ἀναγαγὼν πρὸς τὸ στόμα τὰ ἅμματα τοῦ πιεζοῦντος, οἷος ἦν διαφαγεῖν τὰς χεῖρας. ἀφέντος δὲ τὴν λαβὴν ἐκείνου καὶ εἰπόντος· δάκνεις, ὦ Ἀλκιβιάδη, καθάπερ αἱ γυναῖκες, οὐκ ἔγωγε, εἶπεν, ἀλλ’ ὡς οἱ λέοντες.", "st": "Alc. 2.2"}, {"sp": "N", "t": "ἔτι δὲ μικρὸς ὢν ἔπαιζεν ἀστραγάλοις ἐν τῷ στενωπῷ, τῆς δὲ βολῆς καθηκούσης εἰς αὐτὸν ἅμαξα φορτίων ἐπῄει. πρῶτον μὲν οὖν ἐκέλευε περιμεῖναι τὸν ἄγοντα τὸ ζεῦγος· ὑπέπιπτε γὰρ ἡ βολὴ τῇ παρόδῳ τῆς ἁμάξης· μὴ πειθομένου δὲ δι’ ἀγροικίαν, ἀλλ’ ἐπάγοντος, οἱ μὲν ἄλλοι παῖδες διέσχον, ὁ δ’ Ἀλκιβιάδης καταβαλὼν ἐπὶ στόμα πρὸ τοῦ ζεύγους καὶ παρατείνας ἑαυτόν, ἐκέλευεν οὕτως, εἰ βούλεται, διεξελθεῖν, ὥστε τὸν μὲν ἄνθρωπον ἀνακροῦσαι τὸ ζεῦγος ὀπίσω δείσαντα, τοὺς δ’ ἰδόντας ἐκπλαγῆναι καὶ μετὰ βοῆς συνδραμεῖν πρὸς αὐτόν.", "st": "Alc. 2.3"}, {"sp": "N", "t": "ἐπεὶ δὲ εἰς τὸ μανθάνειν ἧκε, τοῖς μὲν ἄλλοις ὑπήκουε διδασκάλοις ἐπιεικῶς, τὸ δ’ αὐλεῖν ἔφευγεν ὡς ἀγεννὲς καὶ ἀνελεύθερον· πλήκτρου μὲν γὰρ καὶ λύρας χρῆσιν οὐδὲν οὔτε σχήματος οὔτε μορφῆς ἐλευθέρῳ πρεπούσης διαφθείρειν, αὐλοὺς δὲ φυσῶντος ἀνθρώπου στόματι καὶ τοὺς συνήθεις ἂν πάνυ μόλις διαγνῶναι τὸ πρόσωπον. ἔτι δὲ τὴν μὲν λύραν τῷ χρωμένῳ συμφθέγγεσθαι καὶ συνᾴδειν, τὸν δ’ αὐλὸν ἐπιστομίζειν καὶ ἀποφράττειν ἕκαστον τήν τε φωνὴν καὶ τὸν λόγον ἀφαιρούμενον. αὐλείτωσαν οὖν, ἔφη, Θηβαίων παῖδες· οὐ γὰρ ἴσασι διαλέγεσθαι· ἡμῖν δὲ τοῖς Ἀθηναίοις, ὡς οἱ πατέρες λέγουσιν, ἀρχηγέτις Ἀθηνᾶ καὶ πατρῷος Ἀπόλλων ἐστίν, ὧν ἡ μὲν ἔρριψε τὸν αὐλόν, ὁ δὲ καὶ τὸν αὐλητὴν ἐξέδειρεν. τοιαῦτα παίζων ἅμα καὶ σπουδάζων ὁ Ἀλκιβιάδης αὑτόν τε τοῦ μαθήματος ἀπέστησε καὶ τοὺς ἄλλους. ταχὺ γὰρ διῆλθε λόγος εἰς τοὺς παῖδας ὡς εὖ ποιῶν ὁ Ἀλκιβιάδης βδελύττοιτο τὴν αὐλητικὴν καὶ χλευάζοι τοὺς μανθάνοντας. ὅθεν ἐξέπεσε κομιδῇ τῶν ἐλευθέρων διατριβῶν καὶ προεπηλακίσθη παντάπασιν ὁ αὐλός.", "st": "Alc. 2.4"}, {"sp": "N", "t": "ἐν δὲ ταῖς Ἀντιφῶντος λοιδορίαις γέγραπται ὅτι παῖς ὤν, ἐκ τῆς οἰκίας ἀπέδρα πρὸς Δημοκράτη τινὰ τῶν ἐραστῶν· βουλομένου δ’ αὐτὸν ἀποκηρύττειν Ἀρίφρονος, Περικλῆς οὐκ εἴασεν, εἰπών· εἰ μὲν τέθνηκεν, ἡμέρᾳ μιᾷ διὰ τὸ κήρυγμα φανεῖσθαι πρότερον, εἰ δὲ σῶς ἐστιν, ἄσωστον αὐτῷ τὸν λοιπὸν βίον ἔσεσθαι· καὶ ὅτι τῶν ἀκολουθούντων τινὰ κτείνειεν ἐν τῇ Σιβυρτίου παλαίστρᾳ ξύλῳ πατάξας. ἀλλὰ τούτοις μὲν οὐκ ἄξιον ἴσως πιστεύειν, ἅ γε λοιδορεῖσθαί τις αὐτῷ δι’ ἔχθραν ὁμολογῶν εἶπεν.", "st": "Alc. 3.1"}, {"sp": "N", "t": "ἤδη δὲ πολλῶν καὶ γενναίων ἀθροιζομένων καὶ περιεπόντων, οἱ μὲν ἄλλοι καταφανεῖς ἦσαν τὴν λαμπρότητα τῆς ὥρας ἐκπεπληγμένοι καὶ θεραπεύοντες, ὁ δὲ Σωκράτους ἔρως μέγα μαρτύριον ἦν τῆς ἀρετῆς καὶ εὐφυΐας τοῦ παιδός, ἣν ἐμφαινομένην τῷ εἴδει καὶ διαλάμπουσαν ἐνορῶν, φοβούμενος δὲ τὸν πλοῦτον καὶ τὸ ἀξίωμα καὶ τὸν προκαταλαμβάνοντα κολακείαις καὶ χάρισιν ἀστῶν καὶ ξένων καὶ συμμάχων ὄχλον, οἷος ἦν ἀμύνειν καὶ μὴ περιορᾶν ὡς φυτὸν ἐν ἄνθει τὸν οἰκεῖον καρπὸν ἀποβάλλον καὶ διαφθεῖρον. οὐδένα γὰρ ἡ τύχη περιέσχεν ἔξωθεν καὶ περιέφραξε τοῖς λεγομένοις ἀγαθοῖς τοσοῦτον ὥστ’ ἄτρωτον ὑπὸ φιλοσοφίας γενέσθαι, καὶ λόγοις ἀπρόσιτον παρρησίαν καὶ δηγμὸν ἔχουσιν· ὡς Ἀλκιβιάδης εὐθὺς ἐξ ἀρχῆς θρυπτόμενος καὶ ἀποκλειόμενος ὑπὸ τῶν πρὸς χάριν ἐξομιλούντων εἰσακοῦσαι τοῦ νουθετοῦντος καὶ παιδεύοντος, ὅμως ὑπ’ εὐφυΐας ἐγνώρισε Σωκράτη καὶ προσήκατο, διασχὼν τοὺς πλουσίους καὶ ἐνδόξους ἐραστάς. ταχὺ δὲ ποιησάμενος συνήθη, καὶ λόγων ἀκούσας οὐχ ἡδονὴν ἄνανδρον ἐραστοῦ θηρεύοντος, οὐδὲ φιλημάτων καὶ ψαύσεως προσαιτοῦντος, ἀλλ’ ἐλέγχοντος τὸ σαθρὸν τῆς ψυχῆς αὐτοῦ καὶ πιεζοῦντος τὸν κενὸν καὶ ἀνόητον τῦφον,", "st": "Alc. 4.1"}, {"sp": "N", "t": "ἔπτηξ’ ἀλέκτωρ δοῦλος ὣς κλίνας πτερόν.", "st": "Alc. 4.1b"}, {"sp": "N", "t": "καὶ τὸ μὲν Σωκράτους ἡγήσατο πρᾶγμα τῷ ὄντι θεῶν ὑπηρεσίαν εἰς νέων ἐπιμέλειαν εἶναι καὶ σωτηρίαν· καταφρονῶν δ’ αὐτὸς ἑαυτοῦ, θαυμάζων δ’ ἐκεῖνον, ἀγαπῶν δὲ τὴν φιλοφροσύνην, αἰσχυνόμενος δὲ τὴν ἀρετήν, ἐλάνθανεν εἴδωλον ἔρωτος, ὥς φησιν ὁ Πλάτων, ἀντέρωτα κτώμενος, ὥστε θαυμάζειν ἅπαντας ὁρῶντας αὐτὸν Σωκράτει μὲν συνδειπνοῦντα καὶ συμπαλαίοντα καὶ συσκηνοῦντα, τοῖς δ’ ἄλλοις ἐρασταῖς χαλεπὸν ὄντα καὶ δυσχείρωτον, ἐνίοις δὲ καὶ παντάπασι σοβαρῶς προσφερόμενον, ὥσπερ Ἀνύτῳ τῷ Ἀνθεμίωνος.", "st": "Alc. 4.4"}, {"sp": "N", "t": "ἐτύγχανε μὲν γὰρ ἐρῶν τοῦ Ἀλκιβιάδου, ξένους δέ τινας ἑστιῶν ἐκάλει κἀκεῖνον ἐπὶ τὸ δεῖπνον. ὁ δὲ τὴν μὲν κλῆσιν ἀπείπατο, μεθυσθεὶς δ’ οἴκοι μετὰ τῶν ἑταίρων ἐκώμασε πρὸς τὸν Ἄνυτον, καὶ ταῖς θύραις ἐπιστὰς τοῦ ἀνδρῶνος καὶ θεασάμενος ἀργυρῶν ἐκπωμάτων καὶ χρυσῶν πλήρεις τὰς τραπέζας, ἐκέλευσε τοὺς παῖδας τὰ ἡμίση λαβόντας οἴκαδε κομίζειν πρὸς αὐτόν, εἰσελθεῖν δ’ οὐκ ἠξίωσεν, ἀλλὰ ταῦτα πράξας ἀπῆλθε. τῶν οὖν ξένων δυσχεραινόντων καὶ λεγόντων ὡς ὑβριστικῶς καὶ ὑπερηφάνως εἴη τῷ Ἀνύτῳ κεχρημένος ὁ Ἀλκιβιάδης, ἐπιεικῶς μὲν οὖν, ὁ Ἄνοτος ἔφη, καὶ φιλανθρώπως· ἃ γὰρ ἐξῆν αὐτῷ λαβεῖν ἅπαντα, τούτων ἡμῖν τὰ μέρη καταλέλοιπεν.", "st": "Alc. 4.5"}, {"sp": "N", "t": "οὕτω δὲ καὶ τοῖς ἄλλοις ἐρασταῖς ἐχρῆτο· πλὴν ἕν μετοικικὸν ἄνθρωπον, ὥς φασιν, οὐ πολλὰ κεκτημένον, ἀποδόμενον δὲ πάντα καὶ τὸ συναχθὲν εἰς ἑκατὸν στατῆρας τῷ Ἀλκιβιάδῃ προσφέροντα καὶ δεόμενον λαβεῖν, γελάσας καὶ ἡσθεὶς ἐκάλεσεν ἐπὶ δεῖπνον. ἑστιάσας δὲ καὶ φιλοφρονηθεὶς τό τε χρυσίον ἀπέδωκεν αὐτῷ, καὶ προσέταξε τῇ ὑστεραίᾳ τοὺς ὠνουμένους τά τέλη τὰ δημόσια ταῖς τιμαῖς ὑπερβάλλειν ἀντωνούμενον. παραιτουμένου δὲ τοῦ ἀνθρώπου διὰ τὸ πολλῶν ταλάντων εἶναι τὴν ὠνήν, ἠπείλησε μαστιγώσειν εἰ μὴ ταῦτα πράττοι· καὶ γὰρ ἐτύγχανεν ἐγκαλῶν τι τοῖς τελώναις ἴδιον. ἕωθεν οὖν προελθὼν μέτοικος εἰς ἀγορὰν ἐπέθηκε τῇ ὠνῇ τάλαντον. ἐπεὶ δ’ οἱ τελῶναι συστρεφόμενοι καὶ ἀγανακτοῦντες ἐκέλευον ὀνομάζειν ἐγγυητήν, ὡς οὐκ ἂν εὑρόντος, θορυβουμένου τοῦ ἀνθρώπου καὶ ἀναχωροῦντος, ἑστὼς ὁ Ἀλκιβιάδης ἄπωθεν πρὸς τοὺς ἄρχοντας, ἐμὲ γράψατ’, ἔφη, ἐμὸς φίλος ἐστίν, ἐγγυῶμαι. ταῦτ’ ἀκούσαντες οἱ τελῶναι ἐξηπορήθησαν. εἰωθότες γὰρ ἀεὶ ταῖς δευτέραις ὠναῖς χρεωλυτεῖν τὰς πρώτας, οὐχ ἑώρων ἀπαλλαγὴν αὑτοῖς οὖσαν τοῦ πράγματος. ἐδέοντο δὴ τοῦ ἀνθρώπου ἀργύριον διδόντες· ὁ δ’ Ἀλκιβιάδης οὐκ εἴα λαβεῖν ἔλαττον ταλάντου. διδόντων δὲ τὸ τάλαντον ἐκέλευσεν ἀποστῆναι λαβόντα. κἀκεῖνον μὲν οὕτως ὠφέλησεν.", "st": "Alc. 5.1"}, {"sp": "N", "t": "ὁ δὲ Σωκράτους ἔρως πολλοὺς ἔχων καὶ μεγάλους ἀνταγωνιστὰς πῇ μὲν ἐκράτει τοῦ Ἀλκιβιάδου, δι’ εὐφυΐαν ἁπτομένων τῶν λόγων αὐτοῦ καὶ τὴν καρδίαν στρεφόντων καὶ δάκρυα ἐκχεόντων, ἔστι δ’ ὅτε καὶ τοῖς κόλαξι πολλὰς ἡδονὰς ὑποβάλλουσιν ἐνδιδοὺς ἑαυτόν, ἀπωλίσθαινε τοῦ Σωκράτους καὶ δραπετεύων ἀτεχνῶς ἐκυνηγεῖτο, πρὸς μόνον ἐκεῖνον ἔχων τὸ αἰδεῖσθαι καὶ τὸ φοβεῖσθαι, τῶν δ’ ἄλλων ὑπερορῶν.", "st": "Alc. 6.1"}, {"sp": "N", "t": "ὁ μὲν οὖν Κλεάνθης ἔλεγε τὸν ἐρώμενον ὑφ’ ἑαυτοῦ μὲν ἐκ τῶν ὤτων κρατεῖσθαι, τοῖς δ’ ἀντερασταῖς πολλὰς λαβὰς παρέχειν ἀθίκτους ἑαυτῷ, τὴν γαστέρα λέγων καὶ τὰ αἰδοῖα καὶ τὸν λαιμόν· Ἀλκιβιάδης δ’ ἦν μὲν ἀμέλει καὶ πρὸς ἡδονὰς ἀγώγιμος· ἡ γὰρ ὑπὸ Θουκυδίδου λεγομένη παρανομία εἰς τὸ σῶμα τῆς διαίτης ὑποψίαν τοιαύτην δίδωσιν. οὐ μὴν ἀλλὰ μᾶλλον αὐτοῦ τῆς φιλοτιμίας ἐπιλαμβανόμενοι καὶ τῆς φιλοδοξίας οἱ διαφθείροντες ἐνέβαλλον οὐ καθ’ ὥραν εἰς μεγαλοπραγμοσύνην, ἀναπείθοντες ὡς, ὅταν πρῶτον ἄρξηται τὰ δημόσια πράττειν, οὐ μόνον ἀμαυρώσοντα τοὺς ἄλλους στρατηγοὺς καὶ δημαγωγοὺς εὐθύς, ἀλλὰ καὶ τὴν Περικλέους δύναμιν ἐν τοῖς Ἕλλησι καὶ δόξαν ὑπερβαλούμενον. ὥσπερ οὖν ὁ σίδηρος ἐν τῷ πυρὶ μαλασσόμενος αὖθις ὑπὸ τοῦ ψυχροῦ πυκνοῦται καὶ σύνεισι τοῖς μορίοις εἰς αὑτόν, οὕτως ἐκεῖνον ὁ Σωκράτης θρύψεως διάπλεων καὶ χαυνότητος ὁσάκις ἂν λάβοι, πιέζων τῷ λόγῳ καὶ συστέλλων ταπεινὸν ἐποίει καὶ ἄτολμον, ἡλίκων ἐνδεής ἐστι καὶ ἀτελὴς πρὸς ἀρετὴν μανθάνοντα.", "st": "Alc. 6.2"}, {"sp": "N", "t": "τὴν δὲ παιδικὴν ἡλικίαν παραλλάσσων ἐπέστη γραμματοδιδασκάλῳ καὶ βιβλίον ᾔτησεν Ὁμηρικόν. εἰπόντος δὲ τοῦ διδασκάλου μηδὲν ἔχειν Ὁμήρου, κονδύλῳ καθικόμενος αὐτοῦ παρῆλθεν. ἑτέρου δὲ φήσαντος ἔχειν Ὅμηρον ὑφ’ αὑτοῦ διωρθωμένον, εἶτ’, ἔφη, γράμματα διδάσκεις, Ὅμηρον ἐπανορθοῦν ἱκανὸς ὤν; οὐχὶ τοὺς νέους παιδεύεις;", "st": "Alc. 7.1"}, {"sp": "N", "t": "Περικλεῖ δὲ βουλόμενος ἐντυχεῖν ἐπὶ θύρας ἦλθεν αὐτοῦ. πυθόμενος δὲ μὴ σχολάζειν, ἀλλὰ σκοπεῖν καθ’ ἑαυτὸν ὅπως ἀποδώσει λόγον Ἀθηναίοις, ἀπιὼν ὁ Ἀλκιβιάδης, εἶτα, ἔφη, βέλτιον οὐκ ἦν σκοπεῖν αὐτὸν ὅπως οὐκ ἀποδώσει λόγον Ἀθηναίοις;", "st": "Alc. 7.2"}, {"sp": "N", "t": "ἔτι δὲ μειράκιον ὢν ἐστρατεύσατο τὴν εἰς Ποτίδαιαν στρατείαν, καὶ Σωκράτη σύσκηνον εἶχε καὶ παραστάτην ἐν τοῖς ἀγῶσιν. ἰσχυρᾶς δὲ γενομένης μάχης ἠρίστευσαν μὲν ἀμφότεροι, τοῦ δ’ Ἀλκιβιάδου τραύματι περιπεσόντος ὁ Σωκράτης προέστη καὶ ἤμυνε καὶ μάλιστα δὴ προδήλως ἔσωσεν αὐτὸν μετὰ τῶν ὅπλων. ἐγίνετο μὲν οὖν τῷ δικαιοτάτῳ λόγῳ Σωκράτους τὸ ἀριστεῖον· ἐπεὶ δ’ οἱ στρατηγοὶ διὰ τὸ ἀξίωμα τῷ Ἀλκιβιάδῃ σπουδάζοντες ἐφαίνοντο περιθεῖναι τὴν δόξαν, ὁ Σωκράτης βουλόμενος αὔξεσθαι τὸ φιλότιμον ἐν τοῖς καλοῖς αὐτοῦ πρῶτος ἐμαρτύρει καὶ παρεκάλει στεφανοῦν ἐκεῖνον καὶ διδόναι τὴν πανοπλίαν.", "st": "Alc. 7.3"}, {"sp": "N", "t": "ἔτι δὲ τῆς ἐπὶ Δηλίῳ μάχης γενομένης καὶ φευγόντων Ἀθηναίων, ἔχων ἵππον ὁ Ἀλκιβιάδης, τοῦ δὲ Σωκράτους πεζῇ μετ’ ὀλίγων ἀποχωροῦντος, οὐ παρήλασεν ἰδών, ἀλλὰ παρέπεμψε καὶ περιήμυνεν, ἐπικειμένων τῶν πολεμίων καὶ πολλοὺς ἀναιρούντων. καὶ ταῦτα μὲν ὕστερον ἐπράχθη.", "st": "Alc. 7.4"}, {"sp": "N", "t": "Ἱππονίκῳ δὲ τῷ Καλλίου πατρί, καὶ δόξαν ἔχοντι μεγάλην καὶ δύναμιν ἀπὸ πλούτου καὶ γένους, ἐνέτριψε κόνδυλον, οὐχ ὑπ’ ὀργῆς ἢ διαφορᾶς τινος προαχθείς, ἀλλ’ ἐπὶ γέλωτι, συνθέμενος πρὸς τοὺς ἑταίρους. περιβοήτου δὲ τῆς ἀσελγείας ἐν τῇ πόλει γενομένης καὶ συναγανακτούντων, ὥσπερ εἰκός, ἁπάντων, ἅμ’ ἡμέρᾳ παρῆν ὁ Ἀλκιβιάδης ἐπὶ τὴν οἰκίαν τοῦ Ἱππονίκου, καὶ τὴν θύραν κόψας εἰσῆλθε πρὸς αὐτὸν καὶ θεὶς τὸ ἱμάτιον παρεδίδου τὸ σῶμα, μαστιγοῦν καὶ κολάζειν κελεύων. ὁ δὲ συνέγνω καὶ τὴν ὀργὴν ἀφῆκεν, ὕστερον δὲ τῆς θυγατρὸς Ἱππαρέτης ἐποιήσατο νυμφίον.", "st": "Alc. 8.1"}, {"sp": "N", "t": "ἔνιοι δέ φασιν, οὐχ Ἱππόνικον, ἀλλὰ Καλλίαν, τὸν υἱὸν αὐτοῦ, δοῦναι τῷ Ἀλκιβιάδῃ τὴν Ἱππαρέτην ἐπὶ δέκα ταλάντοις· εἶτα μέντοι τεκούσης ἄλλα πάλιν δέκα προσεισπρᾶξαι τὸν Ἀλκιβιάδην, ὡς τοῦτο συνθέμενον εἰ γένοιντο παῖδες. ὁ δὲ Καλλίας ἐπιβουλὴν δεδοικὼς προσῆλθε τῷ δήμῳ τὰ χρήματα διδοὺς καὶ τὸν οἶκον, ἄνπερ αὐτῷ συμπέσῃ μὴ καταλιπόντι γενεὰν ἀποθανεῖν.", "st": "Alc. 8.1b"}, {"sp": "N", "t": "εὔτακτος δ’ οὖσα καὶ φίλανδρος ἡ Ἱππαρέτη, λυπουμένη δ’ ὑπ’ αὐτοῦ περὶ τὸν γάμον ἑταίραις ξέναις καὶ ἀσταῖς συνόντος, ἐκ τῆς οἰκίας ἀπιοῦσα πρὸς τὸν ἀδελφὸν ᾤχετο. τοῦ δ’ Ἀλκιβιάδου μὴ φροντίζοντος, ἀλλὰ τρυφῶντος, ἔδει τὸ τῆς ἀπολείψεως γράμμα παρὰ τῷ ἄρχοντι θέσθαι, μὴ δι’ ἑτέρων, ἀλλ’ αὐτὴν παροῦσαν. ὡς οὖν παρῆν τοῦτο πράξουσα κατὰ τὸν νόμον, ἐπελθὼν ὁ Ἀλκιβιάδης καὶ συναρπάσας αὐτὴν ἀπῆλθε δι’ ἀγορᾶς οἴκαδε κομίζων, μηδενὸς ἐναντιωθῆναι μηδ’ ἀφελέσθαι τολμήσαντος. ἔμεινε μέντοι παρ’ αὐτῷ μέχρι τελευτῆς, ἐτελεύτησε δὲ μετ’ οὐ πολὺν χρόνον εἰς Ἔφεσον τοῦ Ἀλκιβιάδου πλεύσαντος.", "st": "Alc. 8.3"}, {"sp": "N", "t": "αὕτη μὲν οὖν οὐ παντελῶς ἔδοξεν ἡ βία παράνομος οὐδ’ ἀπάνθρωπος εἶναι· καὶ γὰρ ὁ νόμος δοκεῖ διὰ τοῦτο προάγειν τὴν ἀπολείπουσαν εἰς τὸ δημόσιον αὐτήν, ὅπως ἐγγένηται τῷ ἀνδρὶ συμβῆναι καὶ κατασχεῖν.", "st": "Alc. 8.5"}, {"sp": "N", "t": "ὄντος δὲ κυνὸς αὐτῷ θαυμαστοῦ τὸ μέγεθος καὶ τὸ εἶδος, ὃν ἑβδομήκοντα μνῶν ἐωνημένος ἐτύγχανεν, ἀπέκοψε τὴν οὐρὰν πάγκαλον οὖσαν. ἐπιτιμώντων δὲ τῶν συνήθων καὶ λεγόντων ὅτι πάντες ἐπὶ τῷ κυνὶ δάκνονται καὶ λοιδοροῦσιν αὐτόν, ἐπιγελάσας, γίνεται τοίνυν, εἶπεν, ὃ βούλομαι· βούλομαι γὰρ Ἀθηναίους τοῦτο λαλεῖν, ἵνα μή τι χεῖρον περὶ ἐμοῦ λέγωσι.", "st": "Alc. 9.1"}, {"sp": "N", "t": "πρώτην δ’ αὐτῷ πάροδον εἰς τὸ δημόσιον γενέσθαι λέγουσι μετὰ χρημάτων ἐπιδόσεως, οὐκ ἐκ παρασκευῆς, ἀλλὰ παριόντα θορυβούντων Ἀθηναίων ἐρέσθαι τὴν αἰτίαν τοῦ θορύβου, πυθόμενον δὲ χρημάτων ἐπίδοσιν γίνεσθαι παρελθεῖν καὶ ἐπιδοῦναι· τοῦ δὲ δήμου κροτοῦντος καὶ βοῶντος ὑφ’ ἡδονῆς, ἐπιλαθέσθαι τοῦ ὄρτυγος ὃν ἐτύγχανεν ἔχων ἐν τῷ ἱματίῳ· πτοηθέντος οὖν καὶ διαφυγόντος ἔτι μᾶλλον ἐκβοῆσαι τοὺς Ἀθηναίους, πολλοὺς δὲ συνθηρᾶν ἀναστάντας, λαβεῖν δ’ αὐτὸν Ἀντίοχον τὸν κυβερνήτην καὶ ἀποδοῦναι· διὸ προσφιλέστατον τῷ Ἀλκιβιάδῃ γενέσθαι.", "st": "Alc. 10.1"}, {"sp": "N", "t": "μεγάλας δ’ αὐτῷ κλεισιάδας ἐπὶ τὴν πολιτείαν ἀνοίγοντος τοῦ τε γένους καὶ τοῦ πλούτου τῆς τε περὶ τὰς μάχας ἀνδραγαθίας, φίλων τε πολλῶν καὶ οἰκείων ὑπαρχόντων, ἀπ’ οὐδενὸς ἠξίου μᾶλλον ἢ τῆς τοῦ λόγου χάριτος ἰσχύειν ἐν τοῖς πολλοῖς. καὶ ὅτι μὲν δυνατὸς ἦν εἰπεῖν, οἵ τε κωμικοὶ μαρτυροῦσι καὶ τῶν ῥητόρων ὁ δυνατώτατος ἐν τῷ κατὰ Μειδίου, λέγων τὸν Ἀλκιβιάδην καὶ δεινότατον εἰπεῖν γενέσθαι πρὸς τοῖς ἄλλοις. εἰ δὲ Θεοφράστῳ πιστεύομεν, ἀνδρὶ φιληκόῳ καὶ ἱστορικῷ παρ’ ὁντινοῦν τῶν φιλοσόφων, εὑρεῖν μὲν ἦν τὰ δέοντα καὶ νοῆσαι πάντων ἱκανώτατος ὁ Ἀλκιβιάδης, ζητῶν δὲ μὴ μόνον ἃ δεῖ λέγειν, ἀλλὰ καὶ ὡς δεῖ τοῖς ὀνόμασι καὶ τοῖς ῥήμασιν, οὐκ εὐπορῶν δέ, πολλάκις ἐσφάλλετο καὶ μεταξὺ λέγων ἀπεσιώπα καὶ διέλειπε, λέξεως διαφυγούσης αὐτόν, ἀναλαμβάνων καὶ διασκοπούμενος.", "st": "Alc. 10.2"}, {"sp": "N", "t": "αἱ δ’ ἱπποτροφίαι περιβόητοι μὲν ἐγένοντο καὶ τῷ πλήθει τῶν ἁρμάτων· ἑπτὰ γὰρ ἄλλος οὐδεὶς καθῆκεν Ὀλυμπίασιν ἰδιώτης οὐδὲ βασιλεύς, μόνος δὲ ἐκεῖνος. καὶ τὸ νικῆσαι δὲ καὶ δεύτερον γενέσθαι καὶ τέταρτον, ὡς Θουκυδίδης φησίν, ὁ δ’ Εὐριπίδης τρίτον, ὑπερβάλλει λαμπρότητι καὶ δόξῃ πᾶσαν τὴν ἐν τούτοις φιλοτιμίαν. λέγει δ’ ὁ Εὐριπίδης ἐν τῷ ᾄσματι ταῦτα·", "st": "Alc. 11.1"}, {"sp": "N", "t": "σὲ δ’ ἀείσομαι, ὦ Κλεινίου παῖ.<br>καλὸν ἁ νίκα· κάλλιστον δ’, ὃ μηδεὶς ἄλλος Ἑλλάνων,<br>ἅρματι πρῶτα δραμεῖν καὶ δεύτερα καὶ τρίτα,<br>βῆναί τ’ ἀπονητί, Διὸς στεφθέντα τ’ ἐλαία<br>κάρυκι βοᾶν παραδοῦναι·", "st": "Alc. 11.1b"}, {"sp": "N", "t": "τοῦτο μέντοι τὸ λαμπρὸν ἐπιφανέστερον ἐποίησεν ἡ τῶν πόλεων φιλοτιμία. σκηνὴν μὲν γὰρ αὐτῷ κεκοσμημένην διαπρεπῶς ἔστησαν Ἐφέσιοι, τροφὰς δὲ ἵπποις καὶ πλῆθος ἱερείων παρεῖχεν ἡ Χίων πόλις, οἶνον δὲ Λέσβιοι καὶ τὴν ἄλλην ὑποδοχὴν ἀφειδῶς ἑστιῶντι πολλούς. οὐ μὴν ἀλλὰ καὶ διαβολή τις ἢ κακοήθεια γενομένη περὶ τὴν φιλοτιμίαν ἐκείνην πλείονα λόγον παρέσχε.", "st": "Alc. 12.1"}, {"sp": "N", "t": "λέγεται γὰρ ὡς ἦν Ἀθήνησι Διομήδης, ἀνὴρ οὐ πονηρός, Ἀλκιβιάδου φίλος, ἐπιθυμῶν δὲ νίκην Ὀλυμπικὴν αὐτῷ γενέσθαι· καὶ πυνθανόμενος ἅρμα δημόσιον Ἀργείοις εἶναι, τὸν Ἀλκιβιάδην εἰδὼς ἐν Ἄργει μέγα δυνάμενον καὶ φίλους ἔχοντα πολλούς, ἔπεισεν αὐτῷ πρίασθαι τὸ ἅρμα. πριάμενος δὲ ὁ Ἀλκιβιάδης ἴδιον ἀπεγράψατο, τὸν δὲ Διομήδη χαίρειν εἴασε χαλεπῶς φέροντα καὶ μαρτυρόμενον θεοὺς καὶ ἀνθρώπους. φαίνεται δὲ καὶ δίκη συστᾶσα περὶ τούτου, καὶ λόγος Ἰσοκράτει γέγραπται περὶ τοῦ ζεύγους ὑπὲρ τοῦ Ἀλκιβιάδου παιδός, ἐν ᾧ Τισίας ἐστίν, οὐ Διομήδης, ὁ δικασάμενος.", "st": "Alc. 12.2"}, {"sp": "N", "t": "ἐπεὶ δ’ ἀφῆκεν αὑτὸν εἰς τὴν πολιτείαν ἔτι μειράκιον ὤν, τοὺς μὲν ἄλλους εὐθὺς ἐταπείνωσε δημαγωγούς, ἀγῶνα δ’ εἶχε πρός τε Φαίακα τὸν Ἐρασιστράτου καὶ Νικίαν τὸν Νικηράτου, τὸν μὲν ἤδη καθ’ ἡλικίαν προήκοντα καὶ στρατηγὸν ἄριστον εἶναι δοκοῦντα, Φαίακα δ’ ἀρχόμενον, ὥσπερ αὐτός, αὐξάνεσθαι τότε καὶ γνωρίμων ὄντα πατέρων, ἐλαττούμενον δὲ τοῖς τε ἄλλοις καὶ περὶ τὸν λόγον. ἐντευκτικὸς γὰρ ἰδίᾳ καὶ πιθανὸς ἐδόκει μᾶλλον ἢ φέρειν ἀγῶνας ἐν δήμῳ δυνατός. ἦν γάρ, ὡς Εὔπολίς φησι,", "st": "Alc. 13.1"}, {"sp": "N", "t": "λαλεῖν ἄριστος, ἀδυνατώτατος λέγειν.", "st": "Alc. 13.1b"}, {"sp": "N", "t": "φέρεται δὲ καὶ λόγος τις κατ’ Ἀλκιβιάδου ὑπὸ Φαίακος γεγραμμένος, ἐν ᾧ μετὰ τῶν ἄλλων γέγραπται καὶ ὅτι τῆς πόλεως πολλὰ πομπεῖα χρυσᾶ καὶ ἀργυρᾶ κεκτημένης Ἀλκιβιάδης ἐχρῆτο πᾶσιν αὐτοῖς ὥσπερ ἰδίοις πρὸς τὴν καθ’ ἡμέραν δίαιταν.", "st": "Alc. 13.1c"}, {"sp": "N", "t": "ἦν δέ τις Ὑπέρβολος Περιθοίδης, οὗ μέμνηται μὲν ὡς ἀνθρώπου πονηροῦ καὶ Θουκυδίδης, τοῖς δὲ κωμικοῖς ὁμοῦ τι πᾶσι διατριβὴν ἀεὶ σκωπτόμενος ἐν τοῖς θεάτροις παρεῖχεν. ἄτρεπτος δὲ πρὸς τὸ κακῶς ἀκούειν καὶ ἀπαθὴς ὢν ὀλιγωρίᾳ δόξης, ἣν ἀναισχυντίαν καὶ ἀπόνοιαν οὖσαν εὐτολμίαν ἔνιοι καὶ ἀνδρείαν καλοῦσιν, οὐδενὶ μὲν ἤρεσκεν, ἐχρῆτο δ’ αὐτῷ πολλάκις ὁ δῆμος ἐπιθυμῶν προπηλακίζειν τοὺς ἐν ἀξιώματι καὶ συκοφαντεῖν. ἀναπεισθεὶς οὖν ὑπ’ αὐτοῦ τότε τὸ ὄστρακον ἐπιφέρειν ἔμελλεν, ᾧ κολούοντες ἀεὶ τὸν προὔχοντα δόξῃ καὶ δυνάμει τῶν πολιτῶν ἐλαύνουσι, παραμυθούμενοι τὸν φθόνον μᾶλλον ἢ τὸν φόβον. ἐπεὶ δὲ δῆλον ἦν ὅτι ἑνὶ τῶν τριῶν τὸ ὄστρακον ἐποίσουσι, συνήγαγε τὰς στάσεις εἰς ταὐτὸν ὁ Ἀλκιβιάδης, καὶ διαλεχθεὶς πρὸς τὸν Νικίαν κατὰ τοῦ Ὑπερβόλου τὴν ὀστρακοφορίαν ἔτρεψεν.", "st": "Alc. 13.3"}, {"sp": "N", "t": "ὡς δ’ ἔνιοί φασιν, οὐ πρὸς Νικίαν, ἀλλὰ πρὸς Φαίακα διαλεχθεὶς καὶ τὴν ἐκείνου προσλαβὼν ἑταιρίαν ἐξήλασε τὸν Ὑπέρβολον οὐδ’ ἂν προσδοκήσαντα. φαῦλος γὰρ οὐδεὶς ἐνέπιπτεν εἰς τοῦτον τὸν κολασμὸν οὐδ’ ἄδοξος, ὥς που καὶ Πλάτων ὁ κωμικὸς εἴρηκε τοῦ Ὑπερβόλου μνησθείς,", "st": "Alc. 13.5"}, {"sp": "N", "t": "καίτοι πέπραχε τῶν προτέρων μὲν ἄξια,<br>αὑτοῦ δὲ καὶ τῶν στιγμάτων ἀνάξια.", "st": "Alc. 13.5b"}, {"sp": "N", "t": "οὐ γὰρ τοιούτων εἵνεκ’ ὄστραχ’ εὑρέθη.", "st": "Alc. 13.5c"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων ἐν ἑτέροις μᾶλλον εἴρηται τὰ ἱστορούμενα.", "st": "Alc. 13.5d"}, {"sp": "N", "t": "τὸν δ’ Ἀλκιβιάδην ὁ Νικίας οὐχ ἧττον ἠνία θαυμαζόμενος ὑπὸ τῶν πολεμίων ἢ τιμώμενος ὑπὸ τῶν πολιτῶν. πρόξενος μὲν γὰρ ἦν ὁ Ἀλκιβιάδης τῶν Λακεδαιμονίων, καὶ τοὺς ἁλόντας αὐτῶν περὶ Πύλον ἄνδρας ἐθεράπευσεν· ἐπεὶ δ’ ἐκεῖνοί τε διὰ Νικίου μάλιστα τῆς εἰρήνης τυχόντες καὶ τοὺς ἄνδρας ἀπολαβόντες ὑπερηγάπων αὐτόν, ἔν τε τοῖς Ἕλλησι λόγος ἦν ὡς Περικλέους μὲν συνάψαντος αὐτοῖς, Νικίου δὲ λύσαντος τὸν πόλεμον, οἵ τε πλεῖστοι τὴν εἰρήνην Νικίειον ὠνόμαζον, οὐ μετρίως ἀνιώμενος ὁ Ἀλκιβιάδης καὶ φθονῶν ἐβούλευε σύγχυσιν ὁρκίων. καὶ πρῶτον μὲν Ἀργείους αἰσθανόμενος μίσει καὶ φόβῳ τῶν Σπαρτιατῶν ζητοῦντας ἀποστροφήν, ἐλπίδας αὐτοῖς ἐνεδίδου κρύφα τῆς Ἀθηναίων συμμαχίας, καὶ παρεθάρρυνε πέμπων καὶ διαλεγόμενος τοῖς προεστῶσι τοῦ δήμου μὴ δεδιέναι μηδ’ ὑπείκειν Λακεδαιμονίοις, ἀλλὰ πρὸς Ἀθηναίους τρέπεσθαι καὶ περιμένειν ὅσον οὐδέπω μεταμελομένους καὶ τὴν εἰρήνην ἀφιέντας.", "st": "Alc. 14.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Λακεδαιμόνιοι πρός τε τοὺς Βοιωτοὺς ἐποιήσαντο συμμαχίαν καὶ Πάνακτον οὐχ ἑστός, ὥσπερ ἔδει, τοῖς Ἀθηναίοις παρέδωκαν, ἀλλὰ καταλύσαντες, ὀργιζομένους λαβὼν τοὺς Ἀθηναίους ἔτι μᾶλλον ἐξετράχυνε, καὶ τὸν Νικίαν ἐθορύβει καὶ διέβαλλεν εἰκότα κατηγορῶν, ὅτι τοὺς ἐν Σφακτηρίᾳ τῶν πολεμίων ἀποληφθέντας αὐτὸς μὲν ἐξελεῖν οὐκ ἠθέλησεν στρατηγῶν, ἑτέρων δ’ ἐξελόντων ἀφῆκε καὶ ἀπέδωκε χαριζόμενος Λακεδαιμονίοις· εἶτ’ ἐκείνους μὲν οὐκ ἔπεισε φίλος ὢν Βοιωτοῖς μὴ συνόμνυσθαι μηδὲ Κορινθίοις, Ἀθηναίοις δὲ κωλύει τὸν βουλόμενον τῶν Ἑλλήνων φίλον εἶναι καὶ σύμμαχον, εἰ μὴ δόξειε Λακεδαιμονίοις.", "st": "Alc. 14.4"}, {"sp": "N", "t": "ἐκ δὲ τούτου κακῶς φερομένῳ τῷ Νικίᾳ παρῆσαν ὥσπερ κατὰ τύχην πρέσβεις ἀπὸ τῆς Λακεδαίμονος, αὐτόθεν τε λόγους ἐπιεικεῖς ἔχοντες καὶ πρὸς πᾶν τὸ συμβιβαστικὸν καὶ δίκαιον αὐτοκράτορες ἥκειν φάσκοντες. ἀποδεξαμένης δὲ τῆς βουλῆς, τοῦ δὲ δήμου τῇ ὑστεραίᾳ μέλλοντος ἐκκλησιάζειν, δείσας ὁ Ἀλκιβιάδης διεπράξατο τοὺς πρέσβεις ἐν λόγοις γενέσθαι πρὸς αὐτόν. ὡς δὲ συνῆλθον ἔλεγε· τί πεπόνθατε, ἄνδρες Σπαρτιᾶται; πῶς ἔλαθεν ὑμᾶς ὅτι τὰ τῆς βουλῆς ἀεὶ μέτρια καὶ φιλάνθρωπα πρὸς τοὺς ἐντυγχάνοντάς ἐστιν, ὁ δὲ δῆμος μέγα φρονεῖ καὶ μεγάλων ὀρέγεται; κἂν φάσκητε κύριοι πάντων ἀφῖχθαι, προστάττων καὶ βιαζόμενος ἀγνωμονήσει. φέρε δή, τὴν εὐήθειαν ταύτην ἀφέντες, εἰ βούλεσθε χρήσασθαι μετρίοις Ἀθηναίοις καὶ μηδὲν ἐκβιασθῆναι παρὰ γνώμην, οὕτω διαλέγεσθε περὶ τῶν δικαίων ὡς οὐκ ὄντες αὐτοκράτορες. συμπράξομεν δ’ ἡμεῖς Λακεδαιμονίοις χαριζόμενοι. ταῦτα δ’ εἰπὼν ὅρκους ἔδωκεν αὐτοῖς καὶ μετέστησεν ἀπὸ τοῦ Νικίου, παντάπασι πιστεύοντας αὐτῷ καὶ θαυμάζοντας ἅμα τὴν δεινότητα καὶ σύνεσιν, ὡς οὐ τοῦ τυχόντος ἀνδρὸς οὖσαν.", "st": "Alc. 14.6"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ συνήχθη μὲν ὁ δῆμος, εἰσῆλθον δ’ οἱ πρέσβεις. ἐρωτώμενοι δ’ ὑπὸ τοῦ Ἀλκιβιάδου πάνυ φιλανθρώπως ἐφ’ οἷς ἀφιγμένοι τυγχάνουσιν, οὐκ ἔφασαν ἥκειν αὐτοκράτορες. εὐθὺς οὖν ὁ Ἀλκιβιάδης ἐνέκειτο μετὰ κραυγῆς καὶ ὀργῆς, ὥσπερ οὐκ ἀδικῶν, ἀλλ’ ἀδικούμενος, ἀπίστους καὶ παλιμβόλους ἀποκαλῶν καὶ μηδὲν ὑγιὲς μήτε πρᾶξαι μήτ’ εἰπεῖν ἥκοντας, ἐπηγανάκτει δ’ ἡ βουλή, καὶ ὁ δῆμος ἐχαλέπαινε, τὸν δὲ Νικίαν ἔκπληξις εἶχε καὶ κατήφεια τῶν ἀνδρῶν τῆς μεταβολῆς, ἀγνοοῦντα τὴν ἀπάτην καὶ τὸν δόλον.", "st": "Alc. 14.9"}, {"sp": "N", "t": "οὕτω δὲ τῶν Λακεδαιμονίων ἐκπεσόντων, στρατηγὸς ἀποδειχθεὶς ὁ Ἀλκιβιάδης εὐθὺς Ἀργείους καὶ Μαντινεῖς καὶ Ἠλείους συμμάχους ἐποίησε τοῖς Ἀθηναίοις. καὶ τὸν μὲν τρόπον οὐδεὶς τῆς πράξεως ἐπῄνει, μέγα δ’ ἦν τὸ πεπραγμένον ὑπ’ αὐτοῦ, διαστῆσαι καὶ κραδᾶναι Πελοπόννησον ὀλίγου δεῖν ἅπασαν, καὶ τοσαύτας ἀσπίδας ἐν ἡμέρᾳ μιᾷ περὶ Μαντίνειαν ἀντιτάξαι Λακεδαιμονίοις, καὶ πορρωτάτω τῶν Ἀθηνῶν ἀγῶνα κατασκευάσαι καὶ κίνδυνον αὐτοῖς, ἐν ᾧ μέγα μὲν οὐδὲν ἡ νίκη προσέθηκε κρατήσασιν, εἰ δ’ ἐσφάλησαν, ἔργον ἦν τὴν Λακεδαίμονα περιγενέσθαι.", "st": "Alc. 15.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην εὐθὺς ἐπέθεντο καταλύειν ἐν Ἄργει τὸν δῆμον οἱ χίλιοι καὶ τὴν πόλιν ὑπήκοον ποιεῖν· Λακεδαιμόνιοι δὲ παραγενόμενοι κατέλυσαν τὴν δημοκρατίαν. αὖθις δὲ τῶν πολλῶν ἐξενεγκαμένων τὰ ὅπλα καὶ κρατησάντων, ἐπελθὼν ὁ Ἀλκιβιάδης τήν τε νίκην ἐβεβαίωσε τῷ δήμῳ, καὶ τὰ μακρὰ τείχη συνέπεισε καθεῖναι καὶ προσμίξαντας τῇ θαλάσσῃ τὴν πόλιν ἐξάψαι παντάπασι τῆς Ἀθηναίων δυνάμεως. καὶ τέκτονας καὶ λιθουργοὺς ἐκ τῶν Ἀθηνῶν ἐκόμισε καὶ πᾶσαν ἐνεδείκνυτο προθυμίαν, οὐχ ἧττον ἑαυτῷ κτώμενος ἢ τῇ πόλει χάριν καὶ ἰσχύν. ἔπεισε δὲ καὶ Πατρεῖς ὁμοίως τείχεσι μακροῖς συνάψαι τῇ θαλάσσῃ τὴν πόλιν. εἰπόντος δέ τινος τοῖς Πατρεῦσιν ὅτι καταπιοῦνται ὑμᾶς Ἀθηναῖοι· ἴσως, εἶπεν ὁ Ἀλκιβιάδης, κατὰ μικρὸν καὶ κατὰ τοὺς πόδας, Λακεδαιμόνιοι δὲ κατὰ τὴν κεφαλὴν καὶ ἀθρόως.", "st": "Alc. 15.2"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τῆς γῆς συνεβούλευεν ἀντέχεσθαι τοῖς Ἀθηναίοις, καὶ τὸν ἐν Ἀγραύλου προβαλλόμενον ἀεὶ τοῖς ἐφήβοις ὅρκον ἔργῳ βεβαιοῦν. ὀμνύουσι γὰρ ὅροις χρήσασθαι τῆς Ἀττικῆς πυροῖς, κριθαῖς, ἀμπέλοις, ἐλαίαις, οἰκείαν ποιεῖσθαι διδασκόμενοι τὴν ἥμερον καὶ καρποφόρον.", "st": "Alc. 15.4"}, {"sp": "N", "t": "ἐν δὲ τοιούτοις πολιτεύμασι καὶ λόγοις καὶ φρονήματι καὶ δεινότητι πολλὴν αὖ πάλιν τὴν τρυφὴν τῆς διαίτης καὶ περὶ πότους καὶ ἔρωτας ὑβρίσματα, καὶ θηλύτητας ἐσθήτων ἁλουργῶν ἑλκομένων δι’ ἀγορᾶς, καὶ πολυτέλειαν ὑπερήφανον, ἐκτομάς τε καταστρωμάτων ἐν ταῖς τριήρεσιν, ὅπως μαλακώτερον ἐγκαθεύδοι, κειρίαις, ἀλλὰ μὴ σανίσι, τῶν στρωμάτων ἐπιβαλλομένων, ἀσπίδος τε διαχρύσου ποίησιν οὐδὲν ἐπίσημον τῶν πατρίων ἔχουσαν, ἀλλ’ Ἔρωτα κεραυνοφόρον, ἅπερ ὁρῶντες οἱ μὲν ἔνδοξοι μετὰ τοῦ βδελύττεσθαι καὶ δυσχεραίνειν ἐφοβοῦντο τὴν ὀλιγωρίαν αὐτοῦ καὶ παρανομίαν, ὡς τυραννικὰ καὶ ἀλλόκοτα, τοῦ δὲ δήμου τὸ πάθος τὸ πρὸς αὐτὸν οὐ κακῶς ἐξηγούμενος ὁ Ἀριστοφάνης ταῦτ’ εἴρηκε·", "st": "Alc. 16.1"}, {"sp": "N", "t": "ποθεῖ μέν, ἐχθαίρει δέ, βούλεται δ’ ἔχειν,<br>ἔτι δὲ μᾶλλον τῇ ὑπονοίᾳ πιέζων·<br>μάλιστα μὲν λέοντα μὴ ν’ πόλει τρέφειν·<br>ἢν δ’ ἐκτρέφῃ τις, τοῖς τρόποις ὑπηρετεῖν.", "st": "Alc. 16.1b"}, {"sp": "N", "t": "ἐπιδόσεις γὰρ καὶ χορηγίαι καὶ φιλοτιμήματα πρὸς τὴν πόλιν ὑπερβολὴν μὴ ἀπολείποντα καὶ δόξα προγόνων καὶ λόγου δύναμις καὶ σώματος εὐπρέπεια καὶ ῥώμη μετ’ ἐμπειρίας τῶν πολεμικῶν καὶ ἀλκῆς πάντα τἆλλα συγχωρεῖν ἐποίει καὶ φέρειν μετρίως τοὺς Ἀθηναίους, ἀεὶ τὰ πρᾳότατα τῶν ὀνομάτων τοῖς ἁμαρτήμασι τιθεμένους, παιδιὰς καὶ φιλοτιμίας.", "st": "Alc. 16.3"}, {"sp": "N", "t": "οἷον ἦν καὶ τὸ Ἀγάθαρχον εἷρξαι τὸν ζωγράφον, εἶτα γράψαντα τὴν οἰκίαν ἀφεῖναι δωρησάμενον· καὶ Ταυρέαν ἀντιχορηγοῦντα ῥαπίσαι φιλοτιμούμενον ὑπὲρ τῆς νίκης· καὶ τὸ Μηλίαν γυναῖκα ἐκ τῶν αἰχμαλώτων ἐξελόμενον καὶ συνόντα θρέψαι παιδάριον ἐξ αὐτῆς. καὶ γὰρ τοῦτο φιλάνθρωπον ἐκάλουν· πλὴν ὅτι τοὺς Μηλίους ἡβηδὸν ἀποσφαγῆναι τὴν πλείστην αἰτίαν ἔσχε, τῷ ψηφίσματι συνειπών.", "st": "Alc. 16.4"}, {"sp": "N", "t": "Ἀριστοφῶντος δὲ Νεμέαν γράψαντος ἐν ταῖς ἀγκάλαις αὑτῆς καθήμενον Ἀλκιβιάδην ἔχουσαν, ἐθεῶντο καὶ συνέτρεχον χαίροντες. οἱ δὲ πρεσβύτεροι καὶ τούτοις ἐδυσχέραινον ὡς τυραννικοῖς καὶ παρανόμοις. ἐδόκει δὲ καὶ Ἀρχέστρατος οὐκ ἀπὸ τρόπου λέγειν ὡς ἡ Ἑλλὰς οὐκ ἂν ἤνεγκε δύο Ἀλκιβιάδας.", "st": "Alc. 16.4b"}, {"sp": "N", "t": "ἐπεὶ δὲ Τίμων ὁ μισάνθρωπος εὐημερήσαντα τὸν Ἀλκιβιάδην καὶ προπεμπόμενον ἀπὸ τῆς ἐκκλησίας ἐπιφανῶς οὐ παρῆλθεν οὐδ’ ἐξέκλινεν, ὥσπερ εἰώθει τοὺς ἄλλους, ἀλλ’ ἀπαντήσας καὶ δεξιωσάμενος, εὖ γ’, ἔφη, ποιεῖς αὐξόμενος, ὦ παῖ· μέγα γὰρ αὔξῃ κακὸν ἅπασι τούτοις, οἱ μὲν ἐγέλων, οἱ δ’ ἐβλασφήμουν, ἐνίους δὲ καὶ πάνυ τὸ λεχθὲν ἐπέστρεφεν. οὕτως ἄκριτος ἦν ἡ δόξα περὶ αὐτοῦ διὰ τὴν τῆς φύσεως ἀνωμαλίαν.", "st": "Alc. 16.6"}, {"sp": "N", "t": "Σικελίας δὲ καὶ Περικλέους ἔτι ζῶντος ἐπεθύμουν Ἀθηναῖοι, καὶ τελευτήσαντος ἥπτοντο, καὶ τὰς λεγομένας βοηθείας καὶ συμμαχίας ἔπεμπον ἑκάστοτε τοῖς ἀδικουμένοις ὑπὸ Συρακουσίων ἐπιβάθρας τῆς μείζονος στρατείας τιθέντες. ὁ δὲ παντάπασι τὸν ἔρωτα τοῦτον ἀναφλέξας αὐτῶν, καὶ πείσας μὴ κατὰ μέρος μηδὲ κατὰ μικρόν, ἀλλὰ μεγάλῳ στόλῳ πλεύσαντας ἐπιχειρεῖν καὶ καταστρέφεσθαι τὴν νῆσον, Ἀλκιβιάδης ἦν, τόν τε δῆμον μεγάλα πείσας ἐλπίζειν, αὐτός τε μειζόνων ὀρεγόμενος. ἀρχὴν γὰρ εἶναι, πρὸς ἃ ἠλπίκει, διενοεῖτο τῆς στρατείας, οὐ τέλος, ὥσπερ οἱ λοιποί, Σικελίαν. καὶ Νικίας μὲν ὡς χαλεπὸν ἔργον ὂν τὰς Συρακούσας ἑλεῖν ἀπέτρεπε τὸν δῆμον, Ἀλκιβιάδης δὲ Καρχηδόνα καὶ Λιβύην ὀνειροπολῶν, ἐκ δὲ τούτων προσγενομένων Ἰταλίαν καὶ Πελοπόννησον ἤδη περιβαλλόμενος, ὀλίγου δεῖν ἐφόδια τοῦ πολέμου Σικελίαν ἐποιεῖτο. καὶ τοὺς μὲν νέους αὐτόθεν εἶχεν ἤδη ταῖς ἐλπίσιν ἐπηρμένους, τῶν δὲ πρεσβυτέρων ἠκροῶντο πολλὰ θαυμάσια περὶ τῆς στρατείας περαινόντων, ὥστε πολλοὺς ἐν ταῖς παλαίστραις καὶ τοῖς ἡμικυκλίοις καθέζεσθαι τῆς τε νήσου τὸ σχῆμα καὶ θέσιν Λιβύης καὶ Καρχηδόνος ὑπογράφοντας.", "st": "Alc. 17.1"}, {"sp": "N", "t": "Σωκράτη μέντοι τὸν φιλόσοφον καὶ Μέτωνα τὸν ἀστρολόγον οὐδὲν ἐλπίσαι τῇ πόλει χρηστὸν ἀπὸ τῆς στρατείας ἐκείνης λέγουσιν, ὁ μέν, ὡς ἔοικε, τοῦ συνήθους δαιμονίου γενομένου καὶ προσημαίνοντος, ὁ δὲ Μέτων εἴτε δείσας ἐκ λογισμοῦ τὸ μέλλον εἴτε μαντικῆς τινι τρόπῳ χρησάμενος ἐσκήψατο μεμηνέναι, καὶ λαβὼν δᾷδα καιομένην οἷος ἦν αὑτοῦ τὴν οἰκίαν ὑφάπτειν. ἔνιοι δέ φασι προσποίημα μὲν μανίας μηδὲν ἐσκευάσθαι τὸν Μέτωνα, καταπρῆσαι δὲ τὴν οἰκίαν νύκτωρ, εἶθ’ ἕωθεν προελθόντα δεῖσθαι καὶ ἀντιβολεῖν ἐπὶ συμφορᾷ τηλικαύτῃ τὸν υἱὸν αὐτῷ παρεθῆναι τῆς στρατείας. ἐκεῖνος μὲν οὖν ἔτυχεν ὧν ἠξίου, παρακρουσάμενος τοὺς πολίτας.", "st": "Alc. 17.4"}, {"sp": "N", "t": "ὁ δὲ Νικίας ἄκων μὲν ᾑρέθη στρατηγός, οὐχ ἥκιστα τὴν ἀρχὴν καὶ διὰ τὸν συνάρχοντα φεύγων· ἐφαίνετο γὰρ τοῖς Ἀθηναίοις τὰ τοῦ πολέμου βέλτιον ἕξειν μὴ προεμένοις τὸν Ἀλκιβιάδην ἄκρατον, ἀλλὰ μιχθείσης πρὸς τὴν τόλμαν αὐτοῦ τῆς Νικίου προνοίας· καὶ γὰρ ὁ τρίτος στρατηγὸς Λάμαχος ἡλικίᾳ προήκων ὅμως ἐδόκει μηδὲν ἧττον εἶναι τοῦ Ἀλκιβιάδου διάπυρος καὶ φιλοκίνδυνος ἐν τοῖς ἀγῶσι· βουλευομένων δὲ περὶ πλήθους καὶ τρόπου παρασκευῆς ἐπεχείρησεν αὖθις ὁ Νικίας ἐνίστασθαι καὶ καταπαύειν τὸν πόλεμον. ἀντειπόντος δὲ τοῦ Ἀλκιβιάδου καὶ κρατήσαντος, ἔγραψε τῶν ῥητόρων Δημόστρατος καὶ εἶπεν ὡς χρὴ τοὺς στρατηγοὺς αὐτοκράτορας εἶναι καὶ τῆς παρασκευῆς καὶ τοῦ πολέμου παντός.", "st": "Alc. 18.1"}, {"sp": "N", "t": "ἐπιψηφισαμένου δὲ τοῦ δήμου καὶ γενομένων ἑτοίμων πάντων πρὸς τὸν ἔκπλουν, οὐ χρηστὰ παρῆν οὐδὲ τὰ τῆς ἑορτῆς. Ἀδωνίων γὰρ εἰς τὰς ἡμέρας ἐκείνας καθηκόντων εἴδωλα πολλαχοῦ νεκροῖς ἐκκομιζομένοις ὅμοια προὔκειντο ταῖς γυναιξί, καὶ ταφὰς ἐμιμοῦντο κοπτόμεναι, καὶ θρήνους ᾖδον. ἡ μέντοι τῶν Ἑρμῶν περικοπή, μιᾷ νυκτὶ τῶν πλείστων ἀκρωτηριασθέντων τὰ πρόσωπα, πολλοὺς καὶ τῶν περιφρονούντων τὰ τοιαῦτα διετάραξεν. ἐλέχθη μὲν οὖν ὅτι Κορίνθιοι διὰ τοὺς Συρακουσίους ἀποίκους ὄντας, ὡς ἐπισχέσεως ἐσομένης πρὸς τῶν οἰωνῶν ἢ μεταγνώσεως τοῦ πολέμου, ταῦτα δράσειαν. οὐ μὴν ἥπτετό γε τῶν πολλῶν οὔθ’ οὗτος ὁ λόγος οὔθ’ ὁ τῶν σημεῖον δεινὸν εἶναι μηδὲν οἰομένων, ἀλλ’ οἷα φιλεῖ φέρειν ἄκρατος ἀκολάστων νέων εἰς ὕβριν ἐκ παιδιᾶς ὑποφερομένων· ὀργῇ δ’ ἅμα καὶ φόβῳ τὸ γεγονὸς λαμβάνοντες ὡς ἀπὸ συνωμοσίας ἐπὶ πράγμασι μεγάλοις τετολμημένον, ἅπασαν ἐξήταζον ὑπόνοιαν πικρῶς ἥ τε βουλὴ συνιοῦσα περὶ τούτων καὶ ὁ δῆμος ἐν ὀλίγαις ἡμέραις πολλάκις.", "st": "Alc. 18.3"}, {"sp": "N", "t": "ἐν δὲ τούτῳ δούλους τινὰς καὶ μετοίκους προήγαγεν Ἀνδροκλῆς ὁ δημαγωγὸς ἄλλων τε ἀγαλμάτων περικοπὰς καὶ μυστηρίων παρ’ οἶνον ἀπομιμήσεις τοῦ Ἀλκιβιάδου καὶ τῶν φίλων κατηγοροῦντας. ἔλεγον δὲ Θεόδωρον μέν τινα δρᾶν τὰ τοῦ κήρυκος, Πουλυτίωνα δὲ τὰ τοῦ δᾳδούχου, τὰ δὲ τοῦ ἱεροφάντου τὸν Ἀλκιβιάδην, τοὺς δ’ ἄλλους ἑταίρους παρεῖναι καὶ μυεῖσθαι μύστας προσαγορευομένους. ταῦτα γὰρ ἐν τῇ εἰσαγγελίᾳ γέγραπται Θεσσαλοῦ τοῦ Κίμωνος εἰσαγγείλαντος Ἀλκιβιάδην ἀσεβεῖν περὶ τὼ θεώ. τραχυνομένου δὲ τοῦ δήμου καὶ πικρῶς πρὸς Ἀλκιβιάδην ἔχοντος, καὶ τοῦ Ἀνδροκλέους (ἦν γὰρ οὗτος ἐχθρὸς ἐν τοῖς μάλιστα τοῦ Ἀλκιβιάδου) παροξύνοντος, ἐν ἀρχῇ μὲν ἐταράχθησαν οἱ περὶ τὸν Ἀλκιβιάδην. αἰσθόμενοι δὲ τούς τε ναύτας, ὅσοι πλεῖν ἔμελλον εἰς Σικελίαν, εὔνους ὄντας αὐτοῖς καὶ τὸ στρατιωτικόν, Ἀργείων δὲ καὶ Μαντινέων χιλίων ὄντων ὁπλιτῶν ἀκούοντες ἀναφανδὸν λεγόντων ὡς δι’ Ἀλκιβιάδην στρατεύοιντο διαπόντιον καὶ μακρὰν στρατείαν, ἐὰν δέ τις ἀγνωμονῇ περὶ τοῦτον, εὐθὺς ἀποστήσεσθαι, ἀνεθάρρουν καὶ παρίσταντο τῷ καιρῷ πρὸς τὴν ἀπολογίαν, ὥστε τοὺς ἐχθροὺς πάλιν ἀθυμεῖν καὶ φοβεῖσθαι μὴ περὶ τὴν κρίσιν ὁ δῆμος ἀμβλύτερος αὐτῷ γένηται διὰ τὴν χρείαν.", "st": "Alc. 19.1"}, {"sp": "N", "t": "πρὸς ταῦτ’ οὖν τεχνάζουσι τῶν ῥητόρων τοὺς οὐ δοκοῦντας ἐχθροὺς τοῦ Ἀλκιβιάδου, μισοῦντας δὲ αὐτὸν οὐχ ἧττον τῶν ὁμολογούντων, ἀνισταμένους ἐν τῷ δήμῳ λέγειν ὡς ἄτοπόν ἐστιν αὐτοκράτορι στρατηγῷ τηλικαύτης ἀποδεδειγμένῳ δυνάμεως, ἠθροισμένης στρατιᾶς καὶ τῶν συμμάχων, μεταξὺ κληροῦντας δικαστήριον καὶ ὕδωρ διαμετροῦντας ἀπολλύναι τὸν καιρόν· ἀλλὰ νῦν μὲν ἀγαθῇ τύχῃ πλεέτω, τοῦ δὲ πολέμου διαπραχθέντος ἐπὶ τοῖς αὐτοῖς νόμοις ἀπολογείσθω παρών. οὐκ ἐλάνθανε μὲν οὖν ἡ κακοήθεια τῆς ἀναβολῆς τὸν Ἀλκιβιάδην, ἀλλ’ ἔλεγε παριὼν ὡς δεινόν ἐστιν αἰτίας ἀπολιπόντα καθ’ ἑαυτοῦ καὶ διαβολὰς ἐκπέμπεσθαι μετέωρον ἐπὶ τοσαύτης δυνάμεως· ἀποθανεῖν γὰρ προσήκειν μὴ λύσαντι τὰς κατηγορίας, λύσαντι δὲ καὶ φανέντι καθαρῷ τρέπεσθαι πρὸς τοὺς πολεμίους μὴ δεδοικότι τοὺς συκοφάντας.", "st": "Alc. 19.4"}, {"sp": "N", "t": "ἐπεὶ δ’ οὐκ ἔπειθεν, ἀλλὰ πλεῖν ἐκέλευον αὐτόν, ἀνήχθη μετὰ τῶν συστρατήγων ἔχων τριήρεις μὲν οὐ πολλῷ τῶν τεσσαράκοντα καὶ ἑκατὸν ἀποδεούσας, ὁπλίτας δὲ πεντακισχιλίους καὶ ἑκατόν, τοξότας δὲ καὶ σφενδονήτας καὶ ψιλοὺς περὶ τριακοσίους καὶ χιλίους, καὶ τὴν ἄλλην παρασκευὴν ἀξιόλογον. προσβαλὼν δ’ Ἰταλία καὶ Ῥήγιον ἑλών, εἰσηγήσατο γνώμην ὅτῳ τρόπῳ πολεμητέον ἐστί. καὶ Νικίου μὲν ἀντιλέγοντος, Λαμάχου δὲ προσθεμένου, πλεύσας εἰς Σικελίαν προσηγάγετο Κατάνην, ἄλλο δὲ οὐδὲν ἔπραξε μετάπεμπτος ὑπὸ τῶν Ἀθηναίων ἐπὶ τὴν κρίσιν εὐθὺς γενόμενος.", "st": "Alc. 20.1"}, {"sp": "N", "t": "πρῶτον μὲν γάρ, ὥσπερ εἴρηται, ψυχραί τινες ὑποψίαι καὶ διαβολαὶ κατὰ τοῦ Ἀλκιβιάδου προσέπιπτον ἀπὸ δούλων καὶ μετοίκων· ἔπειτα τῶν ἐχθρῶν ἀπόντος αὐτοῦ καθαπτομένων σφοδρότερον, καὶ τοῖς περὶ τοὺς Ἑρμᾶς ὑβρίσμασι καὶ τὰ μυστικὰ συμπλεκόντων, ὡς ἀπὸ μιᾶς ἐπὶ νεωτερισμῷ συνωμοσίας πεπραγμένα, τοὺς μὲν ὁπωσοῦν ἐπαιτιαθέντας ἐνέβαλλον ἀκρίτους εἰς τὸ δεσμωτήριον, ἤχθοντο δὲ τὸν Ἀλκιβιάδην μὴ λαβόντες ὑπὸ τὰς ψήφους τότε μηδὲ κρίναντες ἐπ’ αἰτίαις τηλικαύταις. ὁ δὲ τῇ πρὸς ἐκεῖνον ὀργῇ παραπεσὼν οἰκεῖος ἢ φίλος ἢ συνήθης χαλεπωτέροις αὐτοῖς ἐχρήσατο. τοὺς δὲ μηνύσαντας ὁ μὲν Θουκυδίδης ὀνομάσαι παρῆκεν, ἄλλοι δ’ ὀνομάζουσι Διοκλείδαν καὶ Τεῦκρον, ὧν καὶ Φρύνιχός ἐστιν ὁ κωμικὸς ταυτὶ πεποιηκώς·", "st": "Alc. 20.3"}, {"sp": "N", "t": "ὦ φίλταθ’ Ἑρμῆ, καὶ φυλάσσου, μὴ πεσὼν<br>αὑτὸν παρακρούσῃ καὶ παράσχῃς διαβολὴν<br>ἑτέρῳ Διοκλείδᾳ βουλομένῳ κακόν τι δρᾶν.", "st": "Alc. 20.3b"}, {"sp": "N", "t": "καί·<br>φυλάξομαι· Τεύκρῳ γὰρ οὐχὶ βούλομαι<br>μήνυτρα δοῦναι, τῷ παλαμναίῳ ξένῳ.", "st": "Alc. 20.3c"}, {"sp": "N", "t": "καίτοι βέβαιον οὐδὲν οὐδ’ ἰσχυρὸν οἱ μηνύοντες ἐδείκνυσαν. εἷς δ’ αὐτῶν ἐρωτώμενος ὅπως τὰ πρόσωπα τῶν Ἑρμοκοπιδῶν γνωρίσειε, καὶ ἀποκρινάμενος ὅτι πρὸς τὴν σελήνην, ἐσφάλη τοῦ παντός, ἕνης καὶ νέας οὔσης ὅτε ταῦτ’ ἐδρᾶτο· ὃ θόρυβον μὲν παρέσχε τοῖς νοῦν ἔχουσι, τὸν δῆμον δ’ οὐδὲ τοῦτο μαλακώτερον ἐποίησε πρὸς τὰς διαβολάς, ἀλλ’ ὥσπερ ὥρμησεν ἐξ ἀρχῆς, οὐκ ἐπαύσατο φέρων καὶ ἐμβάλλων εἰς τὸ δεσμωτήριον οὗ τις κατείποι.", "st": "Alc. 20.5"}, {"sp": "N", "t": "τῶν οὖν δεθέντων καὶ φυλαττομένων ἐπὶ κρίσει τότε καὶ Ἀνδοκίδης ἦν ὁ ῥήτωρ, ὃν Ἑλλάνικος ὁ συγγραφεὺς εἰς τοὺς Ὀδυσσέως ἀπογόνους ἀνήγαγεν. ἐδόκει δὲ μισόδημος καὶ ὀλιγαρχικὸς ὁ Ἀνδοκίδης, ὕποπτον δὲ οὐχ ἥκιστα τῆς τῶν Ἑρμῶν περικοπῆς ἐποίησεν ὁ μέγας Ἑρμῆς, ὁ πλησίον αὐτοῦ τῆς οἰκίας ἀνάθημα τῆς Αἰγηΐδος φυλῆς ἱδρυμένος· ἐν γὰρ ὀλίγοις πάνυ τῶν ἐπιφανῶν μόνος σχεδὸν ἀκέραιος ἔμεινε· διὸ καὶ νῦν Ἀνδοκίδου καλεῖται, καὶ πάντες οὕτως ὀνομάζουσι τῆς ἐπιγραφῆς ἀντιμαρτυρούσης.", "st": "Alc. 21.1"}, {"sp": "N", "t": "συνέβη δὲ τῷ Ἀνδοκίδῃ μάλιστα τῶν τὴν αὐτὴν αἰτίαν ἐχόντων ἐν τῷ δεσμωτηρίῳ γενέσθαι συνήθη καὶ φίλον ἔνδοξον μὲν οὐχ ὁμοίως ἐκείνῳ, συνέσει δὲ καὶ τόλμῃ περιττόν, ὄνομα Τίμαιον. οὗτος ἀναπείθει τὸν Ἀνδοκίδην ἑαυτοῦ κατήγορον καί τινων ἄλλων γενέσθαι μὴ πολλῶν· ὁμολογήσαντι γὰρ ἄδειαν εἶναι κατὰ ψήφισμα τοῦ δήμου, τὰ δὲ τῆς κρίσεως ἄδηλα πᾶσι, τοῖς δὲ δυνατοῖς φοβερώτατα· βέλτιον δὲ σωθῆναι ψευδόμενον ἢ μετὰ τῆς αὐτῆς αἰτίας ἀποθανεῖν ἀδόξως, καὶ τὸ κοινῇ σκοποῦντι συμφέρον ὑπάρχειν, ὀλίγους καὶ ἀμφιβόλους προέμενον, πολλοὺς καὶ ἀγαθοὺς ἐξελέσθαι τῆς ὀργῆς. ταῦτα τοῦ Τιμαίου λέγοντος καὶ διδάσκοντος ὁ Ἀνδοκίδης ἐπείσθη, καὶ γενόμενος μηνυτὴς καθ’ αὑτοῦ καὶ καθ’ ἑτέρων ἔσχε τὴν ἐκ τοῦ ψηφίσματος ἄδειαν αὐτός· οὓς δ’ ὠνόμασε πάντες πλὴν τῶν φυγόντων ἀπώλοντο. καὶ πίστεως ἕνεκα προσέθηκεν αὐτοῖς οἰκέτας ἰδίους ὁ Ἀνδοκίδης.", "st": "Alc. 21.3"}, {"sp": "N", "t": "οὐ μὴν ὅ γε δῆμος τὴν ὀργὴν ἅπασαν ἀφῆκεν ἐνταῦθα, ἀλλὰ μᾶλλον ἀπαλλαγεὶς τῶν Ἑρμοκοπιδῶν ὥσπερ σχολάζοντι τῷ θυμῷ πρὸς τὸν Ἀλκιβιάδην ὅλος ἐρρύη, καὶ τέλος ἀπέστειλε τὴν Σαλαμινίαν ἐπ’ αὐτόν, οὐ φαύλως αὐτό γε τοῦτο προστάξας, μὴ βιάζεσθαι μηδ’ ἅπτεσθαι τοῦ σώματος, ἀλλὰ τῷ μετρίῳ λόγῳ χρῆσθαι κελεύοντας ἀκολουθεῖν ἐπὶ κρίσιν καὶ πείθειν τὸν δῆμον. ἐφοβοῦντο γὰρ ταραχὰς τοῦ στρατεύματος ἐν πολεμίᾳ γῇ καὶ στάσιν, ὃ ῥᾳδίως ἂν ἐξειργάσατο βουληθεὶς ὁ Ἀλκιβιάδης. καὶ γὰρ ἠθύμουν ἀπιόντος αὐτοῦ, καὶ πολλὴν τριβὴν προσεδόκων καὶ μῆκος ἀργὸν ἐν τῷ Νικίᾳ τὸν πόλεμον ἕξειν, καθάπερ μύωπος ἀφῃρημένου τῶν πράξεων. ὁ γὰρ Λάμαχος ἦν μὲν πολεμικὸς καὶ ἀνδρώδης, ἀξίωμα δ’ οὐ προσῆν οὐδ’ ὄγκος αὐτῷ διὰ πενίαν.", "st": "Alc. 21.5"}, {"sp": "N", "t": "εὐθὺς μὲν οὖν ἀποπλέων ὁ Ἀλκιβιάδης ἀφείλετο Μεσσήνην Ἀθηναίους. ἦσαν γὰρ οἱ μέλλοντες ἐνδιδόναι τὴν πόλιν, οὓς ἐκεῖνος εἰδὼς σαφέστατα τοῖς Συρακουσίων φίλοις ἐμήνυσε καὶ διέφθειρε τὴν πρᾶξιν. ἐν δὲ Θουρίοις γενόμενος καὶ ἀποβὰς τῆς τριήρους ἔκρυψεν ἑαυτὸν καὶ διέφυγε τοὺς ζητοῦντας. ἐπιγνόντος δέ τινος καὶ εἰπόντος· οὐ πιστεύεις, ὦ Ἀλκιβιάδη, τῇ πατρίδι; τὰ μὲν ἄλλ’, ἔφη, πάντα· περὶ δὲ τῆς ψυχῆς τῆς ἐμῆς οὐδὲ τῇ μητρί, μήπως ἀγνοήσασα τὴν μέλαιναν ἀντὶ τῆς λευκῆς ἐπενέγκῃ ψῆφον. ὕστερον δ’ ἀκούσας ὅτι θάνατον αὐτοῦ κατέγνωκεν ἡ πόλις· ἀλλ’ ἐγώ, εἶπε, δείξω αὐτοῖς ὅτι ζῶ.", "st": "Alc. 22.1"}, {"sp": "N", "t": "τὴν μὲν οὖν εἰσαγγελίαν οὕτως ἔχουσαν ἀναγράφουσι· Θεσσαλὸς Κίμωνος Λακιάδης Ἀλκιβιάδην Κλεινίου Σκαμβωνίδην εἰσήγγειλεν ἀδικεῖν περὶ τὼ θεώ, τὴν Δήμητραν καὶ τὴν Κόρην, ἀπομιμούμενον τὰ μυστήρια καὶ δεικνύοντα τοῖς αὑτοῦ ἑταίροις ἐν τῇ οἰκίᾳ τῇ ἑαυτοῦ, ἔχοντα στολὴν οἵανπερ ὁ ἱεροφάντης ἔχων δεικνύει τὰ ἱερά, καὶ ὀνομάζοντα αὑτὸν μὲν ἱεροφάντην, Πουλυτίωνα δὲ δᾳδοῦχον, κήρυκα δὲ Θεόδωρον Φηγαιᾶ, τοὺς δ’ ἄλλους ἑταίρους μύστας προσαγορεύοντα καὶ ἐπόπτας παρὰ τὰ νόμιμα καὶ τὰ καθεστηκότα ὑπό τε Εὐμολπιδῶν καὶ Κηρύκων καὶ τῶν ἱερέων τῶν ἐξ Ἐλευσῖνος. ἐρήμην δ’ αὐτοῦ καταγνόντες καὶ τὰ χρήματα δημεύσαντες ἔτι καταρᾶσθαι προσεψηφίσαντο πάντας ἱερεῖς καὶ ἱερείας, ὧν μόνην φασὶ Θεανὼ τὴν Μένωνος Ἀγραυλῆθεν ἀντειπεῖν πρὸς τὸ ψήφισμα, φάσκουσαν εὐχῶν, οὐ καταρῶν ἱέρειαν γεγονέναι.", "st": "Alc. 22.3"}, {"sp": "N", "t": "τοσούτων δὲ κατεψηφισμένων Ἀλκιβιάδου καὶ κατεγνωσμένων, ἐτύγχανε μὲν ἐν Ἄργει διατρίβων, ὡς τὸ πρῶτον ἐκ Θουρίων ἀποδρὰς εἰς Πελοπόννησον διεκομίσθη, φοβούμενος δὲ τοὺς ἐχθροὺς καὶ παντάπασι τῆς πατρίδος ἀπεγνωκὼς ἔπεμψεν εἰς Σπάρτην, ἀξιῶν ἄδειαν αὐτῷ γενέσθαι καὶ πίστιν ἐπὶ μείζοσι χρείαις καὶ ὠφελείαις ὧν πρότερον αὐτοὺς ἀμυνόμενος ἔβλαψε. δόντων δὲ τῶν Σπαρτιατῶν καὶ δεξαμένων, παραγενόμενος προθύμως ἓν μὲν εὐθὺς ἐξειργάσατο, μέλλοντας καὶ ἀναβαλλομένους βοηθεῖν Συρακουσίοις ἐγείρας καὶ παροξύνας πέμψαι Γύλιππον ἄρχοντα καὶ θραῦσαι τὴν ἐκεῖ τῶν Ἀθηναίων δύναμιν· ἕτερον δέ, κινεῖν τὸν αὐτόθεν πόλεμον ἐπὶ τοὺς Ἀθηναίους· τὸ δὲ τρίτον καὶ μέγιστον, ἐπιτειχίσαι Δεκέλειαν, οὗ μᾶλλον οὐδὲν διειργάσατο καὶ κατοικοφθόρησε τὴν πόλιν.", "st": "Alc. 23.1"}, {"sp": "N", "t": "εὐδοκιμῶν δὲ δημοσίᾳ καὶ θαυμαζόμενος οὐχ ἧττον ἰδίᾳ τοὺς πολλοὺς κατεδημαγώγει καὶ κατεγοήτευε τῇ διαίτῃ λακωνίζων, ὥσθ’ ὁρῶντας ἐν χρῷ κουριῶντα καὶ ψυχρολουτοῦντα καὶ μάζῃ συνόντα καὶ ζωμῷ μέλανι χρώμενον ἀπιστεῖν καὶ διαπορεῖν, εἴ ποτε μάγειρον ἐπὶ τῆς οἰκίας οὗτος ἀνὴρ ἔσχεν ἢ προσέβλεψε μυρεψὸν ἢ Μιλησίας ἠνέσχετο θιγεῖν χλανίδος. ἦν γάρ, ὥς φασι, μία δεινότης αὕτη τῶν πολλῶν ἐν αὐτῷ καὶ μηχανὴ θήρας ἀνθρώπων, συνεξομοιοῦσθαι καὶ συνομοπαθεῖν τοῖς ἐπιτηδεύμασι καὶ ταῖς διαίταις, ὀξυτέρας τρεπομένῳ τροπὰς τοῦ χαμαιλέοντος. πλὴν ἐκεῖνος μέν, ὡς λέγεται, πρὸς ἓν ἐξαδυνατεῖ χρῶμα τὸ λευκὸν ἀφομοιοῦν ἑαυτόν· Ἀλκιβιάδῃ δὲ διὰ χρηστῶν ἰόντι καὶ πονηρῶν ὁμοίως οὐδὲν ἦν ἀμίμητον οὐδ’ ἀνεπιτήδευτον, ἀλλ’ ἐν Σπάρτῃ γυμναστικός, εὐτελής, σκυθρωπός, ἐν Ἰωνίᾳ χλιδανός, ἐπιτερπής, ῥᾴθυμος, ἐν Θράκῃ μεθυστικός, ἐν Θετταλοῖς ἱππαστικός, Τισαφέρνῃ δὲ τῷ σατράπῃ συνὼν ὑπερέβαλεν ὄγκῳ καὶ πολυτελείᾳ τὴν Περσικὴν μεγαλοπρέπειαν, οὐχ αὑτὸν ἐξιστὰς οὕτω ῥᾳδίως εἰς ἕτερον ἐξ ἑτέρου τρόπον, οὐδὲ πᾶσαν δεχόμενος τῷ ἤθει μεταβολήν, ἀλλ’ ὅτι τῇ φύσει χρώμενος ἔμελλε λυπεῖν τοὺς ἐντυγχάνοντας, εἰς πᾶν ἀεὶ τὸ πρόσφορον ἐκείνοις σχῆμα καὶ πλάσμα κατεδύετο καὶ κατέφευγεν. ἐν γοῦν τῇ Λακεδαίμονι πρὸς τὰ ἔξωθεν ἦν εἰπεῖν· οὐ παῖς Ἀχιλλέως, ἀλλ’ ἐκεῖνος εἴη ἂν αὐτός, οἷον Λυκοῦργος ἐπαίδευσε· τοῖς δ’ ἀληθινοῖς ἄν τις ἐπεφώνησεν αὐτοῦ πάθεσι καὶ πράγμασιν· ἔστιν ἡ πάλαι γυνή.", "st": "Alc. 23.3"}, {"sp": "N", "t": "Τιμαίαν γὰρ τὴν Ἄγιδος γυναῖκα τοῦ βασιλέως στρατευομένου καὶ ἀποδημοῦντος οὕτω διέφθειρεν ὥστε καὶ κύειν ἐξ Ἀλκιβιάδου καὶ μὴ ἀρνεῖσθαι, καὶ τεκούσης παιδάριον ἄρρεν ἔξω μὲν Λεωτυχίδην καλεῖσθαι, τὸ δ’ ἐντὸς αὐτοῦ ψιθυριζόμενον ὄνομα πρὸς τὰς φίλας καὶ τὰς ὀπαδοὺς ὑπὸ τῆς μητρὸς Ἀλκιβιάδην εἶναι· τοσοῦτος ἔρως κατεῖχε τὴν ἄνθρωπον. ὁ δ’ ἐντρυφῶν ἔλεγεν οὐχ ὕβρει τοῦτο πράττειν οὐδὲ κρατούμενος ὑφ’ ἡδονῆς, ἀλλ’ ὅπως Λακεδαιμονίων βασιλεύσωσιν οἱ ἐξ αὐτοῦ γεγονότες. οὕτω πραττόμενα ταῦτα πολλοὶ κατηγόρουν πρὸς τὸν Ἆγιν. ἐπίστευσε δὲ τῷ χρόνῳ μάλιστα, ὅτι σεισμοῦ γενομένου φοβηθεὶς ἐξέδραμε τοῦ θαλάμου παρὰ τῆς γυναικός, εἶτα δέκα μηνῶν οὐκέτι συνῆλθεν αὐτῇ, μεθ’ οὓς γενόμενον τὸν Λεωτυχίδην ἀπέφησεν ἐξ αὐτοῦ μὴ γεγονέναι. καὶ διὰ τοῦτο τῆς βασιλείας ἐξέπεσεν ὕστερον ὁ Λεωτυχίδης.", "st": "Alc. 23.7"}, {"sp": "N", "t": "μετὰ δὲ τὴν ἐν Σικελίᾳ τῶν Ἀθηναίων δυστυχίαν ἐπρέσβευσαν εἰς Σπάρτην ἅμα Χῖοι καὶ Λέσβιοι καὶ Κυζικηνοὶ περὶ ἀποστάσεως. πραττόντων δὲ Βοιωτῶν μὲν Λεσβίοις, Φαρναβάζου δὲ Κυζικηνοῖς, Ἀλκιβιάδῃ πεισθέντες εἵλοντο Χίοις πρὸ πάντων βοηθεῖν. ἐκπλεύσας δὲ καὶ αὐτὸς ἀπέστησεν ὀλίγου δεῖν ἅπασαν Ἰωνίαν, καὶ πολλὰ συνὼν τοῖς τῶν Λακεδαιμονίων στρατηγοῖς ἔβλαπτε τοὺς Ἀθηναίους. ὁ δ’ Ἆγις ἐχθρὸς μὲν ὑπῆρχεν αὐτῷ διὰ τὴν γυναῖκα κακῶς πεπονθώς, ἤχθετο δὲ καὶ τῇ δόξῃ· τὰ γὰρ πλεῖστα γίνεσθαι καὶ προχωρεῖν δι’ Ἀλκιβιάδην λόγος ἦν· τῶν δ’ ἄλλων Σπαρτιατῶν οἱ δυνατώτατοι καὶ φιλοτιμότατοι τὸν Ἀλκιβιάδην ἤδη ἐβαρύνοντο διὰ φθόνον. ἴσχυσαν οὖν καὶ διεπράξαντο τοὺς οἴκοθεν ἄρχοντας ἐπιστεῖλαι πρὸς Ἰωνίαν ὅπως ἀποκτείνωσιν αὐτόν.", "st": "Alc. 24.1"}, {"sp": "N", "t": "ὁ δ’ ἡσυχῆ προγνοὺς καὶ φοβηθεὶς τῶν μὲν πράξεων πασῶν ἐκοινώνει τοῖς Λακεδαιμονίοις, τὸ δ’ εἰς χεῖρας ἰέναι παντάπασιν ἔφευγε, Τισαφέρνῃ δέ, τῷ βασιλέως σατράπῃ, δοὺς ἑαυτὸν ὑπὲρ ἀσφαλείας εὐθὺς ἦν παρ’ αὐτῷ πρῶτος καὶ μέγιστος. τὸ μὲν γὰρ πολύτροπον καὶ περιττὸν αὐτοῦ τῆς δεινότητος οὐκ ὢν ἁπλοῦς, ἀλλὰ κακοήθης καὶ φιλοπόνηρος, ἐθαύμαζεν ὁ βάρβαρος· ταῖς δὲ καθ’ ἡμέραν ἐν τῷ συσχολάζειν καὶ συνδιαιτᾶσθαι χάρισιν οὐδὲν ἦν ἄτεγκτον ἦθος οὐδὲ φύσις ἀνάλωτος, ἀλλὰ καὶ δεδιόσι καὶ φθονοῦσιν ὅμως τὸ συγγενέσθαι καὶ προσιδεῖν ἐκεῖνον ἡδονήν τινα καὶ φιλοφροσύνην παρεῖχε. τἆλλ’ οὖν ὢν καὶ μισέλλην ἐν τοῖς μάλιστα Περσῶν ὁ Τισαφέρνης, οὕτως ἐνεδίδου τῷ Ἀλκιβιάδῃ κολακευόμενος ὥσθ’ ὑπερβάλλειν αὐτὸν ἀντικολακεύων ἐκεῖνος. ὧν γὰρ ἐκέκτητο παραδείσων τὸν κάλλιστον καὶ ὑδάτων καὶ λειμώνων ὑγιεινῶν ἕνεκεν, διατριβὰς ἔχοντα καὶ καταφυγὰς ἠσκημένας βασιλικῶς καὶ περιττῶς, Ἀλκιβιάδην καλεῖν ἔθετο· καὶ πάντες οὕτω καλοῦντες καὶ προσαγορεύοντες διετέλουν.", "st": "Alc. 24.3"}, {"sp": "N", "t": "ἀπογνοὺς οὖν ὁ Ἀλκιβιάδης τὰ τῶν Σπαρτιατῶν ὡς ἄπιστα, καὶ φοβούμενος τὸν Ἆγιν, ἐκάκου καὶ διέβαλλε πρὸς τὸν Τισαφέρνην, οὐκ ἐῶν βοηθεῖν αὐτοῖς προθύμως οὐδὲ καταλύειν τοὺς Ἀθηναίους, ἀλλὰ γλίσχρως χορηγοῦντα θλίβειν καὶ ἀποκναίειν ἀτρέμα καὶ ποιεῖν ἀμφοτέρους βασιλεῖ χειροήθεις καὶ καταπόνους ὑπ’ ἀλλήλων. ὁ δ’ ἐπείθετο ῥᾳδίως καὶ δῆλος ἦν ἀγαπῶν καὶ θαυμάζων, ὥστ’ ἀποβλέπεσθαι τὸν Ἀλκιβιάδην ἑκατέρωθεν ὑπὸ τῶν Ἑλλήνων, τοὺς δ’ Ἀθηναίους μεταμέλεσθαι τοῖς γνωσθεῖσι περὶ αὐτοῦ κακῶς πάσχοντας, ἄχθεσθαι δὲ κἀκεῖνον ἤδη καὶ φοβεῖσθαι μὴ παντάπασι τῆς πόλεως ἀναιρεθείσης ὑπὸ Λακεδαιμονίοις γένηται μισούμενος.", "st": "Alc. 25.1"}, {"sp": "N", "t": "ἐν δὲ τῇ Σάμῳ τότε πάντα τὰ πράγματα τοῖς Ἀθηναίοις σχεδὸν ὑπῆρχε· κἀκεῖθεν ὁρμώμενοι τῇ ναυτικῇ δυνάμει τὰ μὲν ἀνεκτῶντο τῶν ἀφεστώτων, τὰ δ’ ἐφύλαττον ἁμῶς γέ πως ἔτι τοῖς πολεμίοις κατὰ θάλατταν ὄντες ἀξιόμαχοι, Τισαφέρνην δὲ φοβούμενοι καὶ τὰς λεγομένας ὅσον οὔπω παρεῖναι Φοινίσσας τριήρεις πεντήκοντα καὶ ἑκατὸν οὔσας, ὧν ἀφικομένων οὐδεμία σωτηρίας ἐλπὶς ὑπελείπετο τῇ πόλει. ταῦτα δ’ εἰδὼς Ἀλκιβιάδης ἔπεμπε κρύφα πρὸς τοὺς ἐν Σάμῳ δυνατοὺς τῶν Ἀθηναίων, ἐλπίδας ἐνδιδοὺς παρέξειν τὸν Τισαφέρνην φίλον, οὐ τοῖς πολλοῖς χαριζόμενος οὐδὲ πιστεύων ἐκείνοις, ἀλλὰ τοῖς ἀρίστοις, εἰ τολμήσειαν ἄνδρες ἀγαθοὶ γενόμενοι καὶ παύσαντες ὑβρίζοντα τὸν δῆμον αὐτοὶ δι’ ἑαυτῶν σώζειν τὰ πράγματα καὶ τὴν πόλιν.", "st": "Alc. 25.3"}, {"sp": "N", "t": "οἱ μὲν οὖν ἄλλοι σφόδρα προσεῖχον τῷ Ἀλκιβιάδῃ· τῶν δὲ στρατηγῶν εἷς, Φρύνιχος ὁ Δειραδιώτης, ὑποπτεύσας, ὅπερ ἦν, τὸν Ἀλκιβιάδην οὐδέν τι μᾶλλον ὀλιγαρχίας ἢ δημοκρατίας δεόμενον, ζητοῦντα δὲ πάντως κατελθεῖν, ἐκ διαβολῆς τοῦ δήμου προθεραπεύειν καὶ ὑποδύεσθαι τοὺς δυνατούς, ἀνθίστατο. κρατούμενος δὲ τῇ γνώμῃ καὶ φανερῶς ἤδη τοῦ Ἀλκιβιάδου γεγονὼς ἐχθρός, ἐξήγγειλε κρύφα πρὸς Ἀστύοχον τὸν τῶν πολεμίων ναύαρχον, ἐγκελευόμενος φυλάττεσθαι καὶ συλλαμβάνειν ὡς ἐπαμφοτερίζοντα τὸν Ἀλκιβιάδην. ἐλελήθει δ’ ἄρα προδότης προδότῃ διαλεγόμενος. τὸν γὰρ Τισαφέρνην ἐκπεπληγμένος ὁ Ἀστύοχος, καὶ τὸν Ἀλκιβιάδην ὁρῶν παρ’ αὐτῷ μέγαν ὄντα, κατεμήνυσε τὰ τοῦ Φρυνίχου πρὸς αὐτούς. ὁ δ’ Ἀλκιβιάδης εὐθὺς εἰς Σάμον ἔπεμψε τοὺς τοῦ Φρυνίχου κατηγορήσοντας. ἀγανακτούντων δὲ πάντων καὶ συνισταμένων ἐπὶ τὸν Φρύνιχον, οὐχ ὁρῶν ἑτέραν διαφυγὴν ἐκ τῶν παρόντων ἐπεχείρησεν ἰάσασθαι μείζονι κακῷ τὸ κακόν. αὖθις γὰρ ἔπεμψε πρὸς τὸν Ἀστύοχον, ἐγκαλῶν μὲν ὑπὲρ τῆς μηνύσεως, ἐπαγγελλόμενος δὲ τὰς ναῦς καὶ τὸ στρατόπεδον τῶν Ἀθηναίων ὑποχείριον αὐτῷ παρέξειν.", "st": "Alc. 25.5"}, {"sp": "N", "t": "οὐ μὴν ἔβλαψέ γε τοὺς Ἀθηναίους ἡ τοῦ Φρυνίχου προδοσία διὰ τὴν Ἀστυόχου παλιμπροδοσίαν. καὶ γὰρ ταῦτα κατεῖπε τοῦ Φρυνίχου πρὸς τοὺς περὶ τὸν Ἀλκιβιάδην. ὁ δὲ Φρύνιχος προαισθόμενος καὶ προσδεχόμενος δευτέραν κατηγορίαν παρὰ τοῦ Ἀλκιβιάδου, φθάσας αὐτὸς προεῖπε τοῖς Ἀθηναίοις ὅτι μέλλουσιν ἐπιπλεῖν οἱ πολέμιοι, καὶ παρῄνεσε πρὸς ταῖς ναυσὶν εἶναι καὶ περιτειχίσαι τὸ στρατόπεδον. ἐπεὶ δὲ πραττόντων ταῦτα τῶν Ἀθηναίων ἧκε γράμματα πάλιν παρὰ τοῦ Ἀλκιβιάδου, φυλάττεσθαι κελεύοντος τὸν Φρύνιχον ὡς προδιδόντα τοῖς πολεμίοις τὸν ναύσταθμον, ἠπίστησαν οἰόμενοι τὸν Ἀλκιβιάδην εἰδότα σαφῶς τὴν τῶν πολεμίων παρασκευὴν καὶ διάνοιαν ἀποχρῆσθαι πρὸς τὴν τοῦ Φρυνίχου διαβολὴν οὐκ ἀληθῶς. ὕστερον μέντοι τὸν Φρύνιχον ἑνὸς τῶν περιπόλων Ἕρμωνος ἐν ἀγορᾷ πατάξαντος ἐγχειριδίῳ καὶ διαφθείραντος, οἱ Ἀθηναῖοι δίκης γενομένης τοῦ μὲν Φρυνίχου προδοσίαν κατεψηφίσαντο τεθνηκότος, τὸν δ’ Ἕρμωνα καὶ τοὺς μετ’ αὐτοῦ συστάντας ἐστεφάνωσαν.", "st": "Alc. 25.8"}, {"sp": "N", "t": "ἐν δὲ τῇ Σάμῳ τότε κρατήσαντες οἱ Ἀλκιβιάδου φίλοι πέμπουσι Πείσανδρον εἰς ἄστυ κινήσοντα τὴν πολιτείαν καὶ παραθαρρυνοῦντα τοὺς δυνατοὺς τῶν πραγμάτων ἀντιλαμβάνεσθαι καὶ καταλύειν τὸν δῆμον, ὡς ἐπὶ τούτοις τοῦ Ἀλκιβιάδου Τισαφέρνην αὐτοῖς φίλον καὶ σύμμαχον παρέξοντος. αὕτη γὰρ ἦν πρόφασις καὶ τοῦτο πρόσχημα τοῖς καθιστᾶσι τὴν ὀλιγαρχίαν. ἐπεὶ δ’ ἴσχυσαν καὶ παρέλαβον τὰ πράγματα οἱ πεντακισχίλιοι λεγόμενοι, τετρακόσιοι δὲ ὄντες, ἐλάχιστα τῷ Ἀλκιβιάδῃ προσεῖχον ἤδη καὶ μαλακώτερον ἥπτοντο τοῦ πολέμου, τὰ μὲν ἀπιστοῦντες ἔτι πρὸς τὴν μεταβολὴν ξενοπαθοῦσι τοῖς πολίταις, τὰ δ’ οἰόμενοι μᾶλλον ἐνδώσειν αὐτοῖς Λακεδαιμονίους ἀεὶ πρὸς ὀλιγαρχίαν ἐπιτηδείως ἔχοντας. ὁ μὲν οὖν κατὰ τὴν πόλιν δῆμος ἄκων ὑπὸ δέους ἡσυχίαν ἦγε· καὶ γὰρ ἀπεσφάγησαν οὐκ ὀλίγοι τῶν ἐναντιουμένων φανερῶς τοῖς τετρακοσίοις· οἱ δ’ ἐν Σάμῳ ταῦτα πυνθανόμενοι καὶ ἀγανακτοῦντες ὥρμηντο πλεῖν εὐθὺς ἐπὶ τὸν Πειραιᾶ, καὶ μεταπεμψάμενοι τὸν Ἀλκιβιάδην καὶ στρατηγὸν ἀποδείξαντες ἐκέλευον ἡγεῖσθαι καὶ καταλύειν τοὺς τυράννους.", "st": "Alc. 26.1"}, {"sp": "N", "t": "ὁ δ’ οὐχ οἷον ἄν τις ἐξαίφνης χάριτι τῶν πολλῶν μέγας γεγονὼς ἔπαθε καὶ ἠγάπησε, πάντα δεῖν εὐθὺς οἰόμενος χαρίζεσθαι καὶ μηδὲν ἀντιλέγειν τοῖς ἐκ πλάνητος καὶ φυγάδος αὐτὸν νεῶν τοσούτων καὶ στρατοπέδου καὶ δυνάμεως τηλικαύτης ἀποδείξασιν ἡγεμόνα καὶ στρατηγόν, ἀλλ’ ὅπερ ἦν ἄρχοντι μεγάλῳ προσῆκον, ἀνθίστασθαι φερομένοις ὑπ’ ὀργῆς, κωλύσας ἐξαμαρτεῖν, τότε γοῦν τὰ πράγματα τῇ πόλει περιφανῶς ἔσωσεν. εἰ γὰρ ἄραντες ἀπέπλευσαν οἴκαδε, τοῖς μὲν πολεμίοις εὐθὺς ἔχειν ὑπῆρχεν Ἰωνίαν ἅπασαν, καὶ τὸν Ἑλλήσποντον ἀμαχεί, καὶ τὰς νήσους, Ἀθηναίοις δὲ πρὸς Ἀθηναίους μάχεσθαι τὸν πόλεμον εἰς τὴν πόλιν ἐμβαλόντας· ὃν μόνος μάλιστα μὴ γενέσθαι διεκώλυσεν ὁ Ἀλκιβιάδης, οὐ μόνον πείθων καὶ διδάσκων τὸ πλῆθος, ἀλλὰ καὶ καθ’ ἕνα τοὺς μὲν ἀντιβολῶν, τῶν δ’ ἐπιλαμβανόμενος. συνέπραττε δ’ αὐτῷ καὶ Θρασύβουλος ὁ Στειριεὺς ἅμα παρὼν καὶ κεκραγώς· ἦν γάρ, ὡς λέγεται, μεγαλοφωνότατος Ἀθηναίων.", "st": "Alc. 26.4"}, {"sp": "N", "t": "ἐκεῖνό τε δὴ καλὸν τοῦ Ἀλκιβιάδου καὶ δεύτερον, ὅτι ὑποσχόμενος τὰς Φοινίσσας ναῦς, ἃς προσεδέχοντο Λακεδαιμόνιοι βασιλέως πέμψαντος, ἢ μεταστήσειν πρὸς αὐτοὺς ἢ διαπράξεσθαι μηδὲ πρὸς ἐκείνους κομισθῆναι, διὰ ταχέων ἐξέπλευσε. καὶ τὰς μὲν ναῦς ἐκφανείσας περὶ Ἄσπενδον οὐκ ἤγαγεν ὁ Τισαφέρνης, ἀλλ’ ἐψεύσατο τοὺς Λακεδαιμονίους, τὴν δ’ αἰτίαν τοῦ ἀποτρέψαι παρ’ ἀμφοτέροις ὁ Ἀλκιβιάδης εἶχε, καὶ μᾶλλον ἔτι παρὰ τοῖς Λακεδαιμονίοις, ὡς διδάσκων τὸν βάρβαρον αὐτοὺς ὑφ’ αὑτῶν περιορᾶν ἀπολλυμένους τοὺς Ἕλληνας. οὐ γὰρ ἦν ἄδηλον ὅτι τοῖς ἑτέροις δύναμις τοσαύτη προσγενομένη τοὺς ἑτέρους ἀφῃρεῖτο κομιδῇ τὸ κράτος τῆς θαλάττης.", "st": "Alc. 26.7"}, {"sp": "N", "t": "ἐκ τούτου κατελύθησαν μὲν οἱ τετρακόσιοι, τῶν Ἀλκιβιάδου φίλων προθύμως συλλαμβανομένων τοῖς τὰ δήμου φρονοῦσι· βουλομένων δὲ τῶν ἐν ἄστει καὶ κελευόντων κατιέναι τὸν Ἀλκιβιάδην αὐτὸς ᾤετο δεῖν μὴ κεναῖς χερσὶ μηδὲ ἀπράκτοις, οἴκτῳ καὶ χάριτι τῶν πολλῶν, ἀλλ’ ἐνδόξως κατελθεῖν. διὸ πρῶτον μὲν ὀλίγαις ναυσὶν ἐκ Σάμου περιέπλει τὴν Κνιδίων καὶ Κῴων θάλασσαν· ἐκεῖ δ’ ἀκούσας Μίνδαρον τὸν Σπαρτιάτην εἰς Ἑλλήσποντον ἀναπλεῖν τῷ στόλῳ παντὶ καὶ τοὺς Ἀθηναίους ἐπακολουθεῖν, ἠπείγετο βοηθῆσαι τοῖς στρατηγοῖς. καὶ κατὰ τύχην εἰς τοῦτο καιροῦ συνήνυσε πλέων ὀκτωκαίδεκα τριήρεσιν, ἐν ᾧ πάσαις ὁμοῦ ταῖς ναυσὶ συμπεσόντες εἰς τὸ αὐτὸ καὶ διαναυμαχοῦντες περὶ Ἄβυδον ἀμφότεροι τοῖς μὲν ἡττώμενοι μέρεσι, τοῖς δὲ νικῶντες ἄχρι δείλης ἀγῶνι μεγάλῳ συνείχοντο. καὶ παρέσχε μὲν ἐναντίαν δόξαν ἀμφοτέροις ἐπιφανείς, ὥστε θαρρεῖν μὲν τοὺς πολεμίους, θορυβεῖσθαι δὲ τοὺς Ἀθηναίους. ταχὺ δὲ σημεῖον ἄρας ἀπὸ τῆς ναυαρχίδος φίλιον ὥρμησεν εὐθὺς ἐπὶ τοὺς κρατοῦντας καὶ διώκοντας τῶν Πελοποννησίων. τρεψάμενος δ’ αὐτοὺς ἐξέωσεν εἰς τὴν γῆν, καὶ προσκείμενος ἔκοπτε τὰς ναῦς καὶ συνετίτρωσκε, τῶν ἀνδρῶν ἐκνεόντων καὶ Φαρνμβάζου πεζῇ προσβοηθοῦντος αὐτοῖς καὶ μαχομένου παρὰ τὴν θάλατταν ὑπὲρ τῶν νεῶν. τέλος δὲ τῶν μὲν πολεμίων τριάκοντα λαβόντες, ἀνασώσαντες δὲ τὰς αὑτῶν, τρόπαιον ἔστησαν.", "st": "Alc. 27.1"}, {"sp": "N", "t": "οὕτω δὲ λαμπρᾷ χρησάμενος εὐτυχίᾳ, καὶ φιλοτιμούμενος εὐθὺς ἐγκαλλωπίσασθαι τῷ Τισαφέρνῃ, ξένια καὶ δῶρα παρασκευασάμενος καὶ θεραπείαν ἔχων ἡγεμονικὴν ἐπορεύετο πρὸς αὐτόν. οὐ μὴν ἔτυχεν ὧν προσεδόκησεν, ἀλλὰ πάλαι κακῶς ἀκούων ὁ Τισαφέρνης ὑπὸ τῶν Λακεδαιμονίων, καὶ φοβούμενος αἰτίαν λαβεῖν ἐκ βασιλέως, ἔδοξεν ἐν καιρῷ τὸν Ἀλκιβιάδην ἀφῖχθαι, καὶ συλλαβὼν αὐτὸν εἷρξεν ἐν Ξάρδεσιν ὡς λύσιν ἐκείνης τῆς διαβολῆς τὴν ἀδικίαν ταύτην ἐσομένην.", "st": "Alc. 27.5"}, {"sp": "N", "t": "τριάκοντα δ’ ἡμερῶν διαγενομένων ὁ Ἀλκιβιάδης ἵππου ποθὲν εὐπορήσας καὶ ἀποδρὰς τοὺς φύλακας εἰς Κλαζομενὰς διέφυγε. καὶ τὸν μὲν Τισαφέρνην προσδιέβαλλεν ὡς ὑπ’ ἐκείνου μεθειμένος, αὐτὸς δὲ πλεύσας εἰς τὸ στρατόπεδον τῶν Ἀθηναίων καὶ πυθόμενος Μίνδαρον ὁμοῦ καὶ Φαρνάβαζον ἐν Κυζίκῳ γεγονέναι, τοὺς μὲν στρατιώτας παρώρμησεν, ὡς ἀνάγκην οὖσαν αὐτοῖς καὶ ναυμαχεῖν καὶ πεζομαχεῖν καὶ νὴ Δία τειχομαχεῖν πρὸς τοὺς πολεμίους· χρήματα γὰρ οὐκ εἶναι μὴ πάντη κρατοῦσι· πληρώσας δὲ τὰς ναῦς καὶ κατάρας εἰς Προικόννησον ἐκέλευσεν ἐντὸς περιβάλλειν τὰ λεπτὰ πλοῖα καὶ παραφυλάσσειν, ὅπως μηδεμία τοῖς πολεμίοις ἐπιπλέοντος αὐτοῦ γένοιτο μηδαμόθεν προαίσθησις.", "st": "Alc. 28.1"}, {"sp": "N", "t": "ἔτυχε δὲ καὶ πολὺν ὄμβρον ἐξαίφνης ἐπιπεσόντα καὶ βροντὰς καὶ ζόφον συνεργῆσαι καὶ συνεπικρύψαι τὴν παρασκευήν. οὐ γὰρ μόνον τοὺς πολεμίους ἔλαθεν, ἀλλὰ καὶ τοὺς Ἀθηναίους ἀπεγνωκότας ἤδη ἐμβῆναι κελεύσας ἀνήχθη. καὶ μετὰ μικρὸν ὅ τε ζόφος διελύθη καὶ κατώφθησαν αἱ τῶν Πελοποννησίων νῆες αἰωρούμεναι πρὸ τοῦ λιμένος τῶν Κυζικηνῶν. δείσας οὖν ὁ Ἀλκιβιάδης μὴ διὰ τὸ πλῆθος αὐτὸν προϊδόντες εἰς τὴν γῆν καταφύγωσι, τοὺς μὲν στρατηγοὺς ἐκέλευσεν ἡσυχῇ πλέοντας ὑπολείπεσθαι, αὐτὸς δὲ τετταράκοντα ναῦς ἔχων ἐφαίνετο καὶ προὐκαλεῖτο τοὺς πολεμίους. ἐπεὶ δ’ ἐξηπάτηντο καὶ καταφρονήσαντες ὡς ἐπὶ τοσαύτας ἀντεξήλασαν, αὐτοὶ μὲν εὐθὺς ἐξήπτοντο καὶ συνεπλέκοντο, τῶν δ’ ἄλλων ἤδη μαχομένοις ἐπιφερομένων ἐκπλαγέντες ἔφευγον.", "st": "Alc. 28.3"}, {"sp": "N", "t": "ὁ δ’ Ἀλκιβιάδης εἴκοσι ταῖς ἀρίσταις διεκπλεύσας καὶ προσβαλὼν τῇ γῇ καὶ ἀποβάς, ἐνέκειτο τοῖς φεύγουσιν ἐκ τῶν νεῶν καὶ πολλοὺς ἔφθειρε· Μινδάρου δὲ καὶ Φαρναβάζου προσβοηθούντων κρατήσας, τὸν μὲν Μίνδαρον ἀνεῖλεν ἐρρωμένως ἀγωνιζόμενον, ὁ δὲ Φαρνάβαζος ἔφυγε. πολλῶν δὲ καὶ νεκρῶν καὶ ὅπλων κρατήσαντες τάς τε ναῦς ἁπάσας ἔλαβον, χειρωσάμενοι δὲ καὶ Κύζικον, ἐκλιπόντος τοῦ Φαρναβάζου καὶ τῶν Πελοποννησίων διαφθαρέντων, οὐ μόνον τὸν Ἑλλήσποντον εἶχον βεβαίως, ἀλλὰ καὶ τῆς ἄλλης θαλάττης ἐξήλασαν κατὰ κράτος τοὺς Λακεδαιμονίους. ἑάλω δὲ καὶ γράμματα λακωνικῶς φράζοντα τοῖς Ἐφόροις τὴν γεγενημένην ἀτυχίαν· ἔρρει τὰ κᾶλα· Μίνδαρος ἀπεσσούα· πεινῶντι τὦνδρες· ἀπορίομες τί χρὴ δρᾶν.", "st": "Alc. 28.5"}, {"sp": "N", "t": "οὕτω δ’ ἐπήρθησαν οἱ μετὰ τοῦ Ἀλκιβιάδου στρατευσάμενοι καὶ τοσοῦτον ἐφρόνησαν ὥστ’ ἀπαξιοῦν ἔτι τοῖς ἄλλοις καταμιγνύναι στρατιώταις ἑαυτοὺς πολλάκις ἡττημένοις ἀηττήτους ὄντας. καὶ γὰρ οὐ πολλῷ πρότερον συνεβεβήκει πταίσαντος περὶ Ἔφεσον τοῦ Θρασύλλου τὸ χαλκοῦν ἀνεστάναι τρόπαιον ὑπὸ τῶν Ἐφεσίων ἐπ’ αἰσχύνῃ τῶν Ἀθηναίων. ταῦτ’ οὖν ὠνείδιζον οἱ μετὰ τοῦ Ἀλκιβιάδου τοῖς μετὰ τοῦ Θρασύλλου, μεγαλύνοντες αὑτοὺς καὶ τὸν στρατηγόν, ἐκείνοις δὲ μήτε γυμνασίων μήτε χώρας ἐν στρατοπέδῳ κοινωνεῖν ἐθέλοντες. ἐπεὶ δὲ Φαρνάβαζος ἱππέας τε πολλοὺς ἔχων καὶ πεζοὺς ἐπῆλθεν αὐτοῖς ἐμβεβληκόσιν εἰς τὴν Ἀβυδηνῶν, ὁ δ’ Ἀλκιβιάδης ἐκβοηθήσας ἐπ’ αὐτὸν ἐτρέψατο καὶ κατεδίωξεν ἄχρι σκότους μετὰ τοῦ Θρασύλλου, καὶ ἀνεμίγνυντο καὶ κοινῇ φιλοφρονούμενοι καὶ χαίροντες ἐπανῄεσαν εἰς τὸ στρατόπεδον.", "st": "Alc. 29.1"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ στήσας τρόπαιον ἐλεηλάτει τὴν Φαρναβάζου χώραν οὐδενὸς ἀμύνεσθαι τολμῶντος. ἱερεῖς μέντοι καὶ ἱερείας ἔλαβε μέν, ἀλλ’ ἀφῆκεν ἄνευ λύτρων. Χαλκηδονίοις δ’ ἀφεστῶσι καὶ δεδεγμένοις φρουρὰν καὶ ἁρμοστὴν Λακεδαιμονίων ὡρμημένος πολεμεῖν, ἀκούσας δ’ ὅτι τὴν λείαν πᾶσαν ἐκ τῆς χώρας συναγαγόντες εἰς Βιθυνοὺς ὑπεκτίθενται φίλους ὄντας, ἧκεν ἐπὶ τοὺς ὅρους ἄγων τὸ στράτευμα, καὶ κήρυκα προπέμψας ἐνεκάλει τοῖς Βιθυνοῖς. οἱ δὲ δείσαντες τήν τε λείαν ἀπέδοσαν αὐτῷ καὶ φιλίαν ὡμολόγησαν.", "st": "Alc. 29.3"}, {"sp": "N", "t": "ἀποτειχιζομένης δὲ τῆς Χαλκηδόνος ἐκ θαλάττης εἰς θάλατταν, ὁ Φαρνάβαζος ἧκεν ὡς λύσων τὴν πολιορκίαν, καὶ Ἱπποκράτης ὁ ἁρμοστὴς ἐκ τῆς πόλεως ἐξαγαγὼν τὴν σὺν αὑτῷ δύναμιν ἐπεχείρει τοῖς Ἀθηναίοις. ὁ δ’ Ἀλκιβιάδης ἅμα πρὸς ἀμφοτέρους ἀντιτάξας τὸ στράτευμα, τὸν μὲν Φαρνάβαζον αἰσχρῶς φεύγειν ἠνάγκασε, τὸν δ’ Ἱπποκράτη διέφθειρε καὶ συχνοὺς τῶν περὶ αὐτὸν ἡττηθέντας.", "st": "Alc. 30.1"}, {"sp": "N", "t": "εἶτ’ αὐτὸς μὲν ἐκπλεύσας εἰς τὸν Ἑλλήσποντον ἠργυρολόγει καὶ Σηλυβρίαν εἷλεν, ἀφειδήσας ἑαυτοῦ παρὰ τὸν καιρόν. οἱ γὰρ ἐνδιδόντες τὴν πόλιν συνέθεντο μὲν ἀνασχήσειν πυρσὸν αὐτῷ μεσούσης νυκτός, ἠναγκάσθησαν δὲ τοῦτο ποιῆσαι πρὸ τοῦ καιροῦ, τῶν συνωμοτῶν τινα φοβηθέντες ἐξαίφνης μεταβαλόμενον. ἀρθέντος οὖν τοῦ πυρσοῦ μηδέπω τῆς στρατιᾶς οὔσης ἑτοίμης, ἀναλαβὼν ὅσον τριάκοντα περὶ αὑτὸν ἐπείγετο δρόμῳ πρὸς τὰ τείχη, τοὺς ἄλλους ἕπεσθαι κατὰ τάχος κελεύσας. ἀνοιχθείσης δὲ τῆς πύλης αὐτῷ καὶ προσγενομένων τοῖς τριάκοντα πελταστῶν εἴκοσι παρεισπεσὼν εὐθὺς ᾔσθετο τοὺς Σηλυβριανοὺς ἐξ ἐναντίας μετὰ τῶν ὅπλων ἐπιφερομένους. ἐπεὶ δ’ ὑποστάντι μὲν οὐκ ἐφαίνετο σωτηρία, πρὸς δὲ τὸ φυγεῖν, ἀήττητος ἄχρι τῆς ἡμέρας ἐκείνης ἐν ταῖς στρατηγίαις γεγονώς, φιλονεικότερον εἶχε, τῇ σάλπιγγι σημήνας σιωπὴν ἐκέλευσεν ἕνα τῶν παρόντων ἀνειπεῖν Σηλυβριανοῖς Ἀθηναίους ἐναντία ὅπλα μὴ τίθεσθαι. τοῦτο τὸ κήρυγμα τοὺς μὲν ἀμβλυτέρους ἐποίησε πρὸς τὴν μάχην, ὡς τῶν πολεμίων ἔνδον ὄντων ἁπάντων, οἱ δὲ ταῖς ἐλπίσιν ἡδίους ἐγένοντο πρὸς τὰς διαλύσεις. ἐν ᾧ δὲ συστάντες ἀλλήλοις ἐδίδοσαν λόγον, ἐπῆλθεν ἡ στρατιὰ τῷ Ἀλκιβιάδῃ, καὶ τεκμαιρόμενος, ὅπερ ἦν, εἰρηνικὰ φρονεῖν τοὺς Σηλυβριανούς, ἔδεισε μὴ τὴν πόλιν οἱ Θρᾷκες διαρπάσωσιν. ἦσαν δὲ πολλοί, χάριτι τοῦ Ἀλκιβιάδου καὶ δι’ εὔνοιαν στρατευόμενοι προθύμως. ἀπέπεμψεν οὖν τούτους ἅπαντας ἐκ τῆς πόλεως, τοὺς δὲ Σηλυβριανοὺς δεηθέντας οὐδὲν ἠδίκησεν, ἀλλὰ χρήματα λαβὼν καὶ φρουρὰν ἐγκαταστήσας ἀπῆλθεν.", "st": "Alc. 30.2"}, {"sp": "N", "t": "οἱ δὲ πολιορκοῦντες τὴν Χαλκηδόνα στρατηγοὶ σπονδὰς ἐποιήσαντο πρὸς Θαρνάβαζον ἐπὶ τῷ χρήματα λαβεῖν καὶ Χαλκηδονίους ὑπηκόους πάλιν Ἀθηναίοις εἶναι, τὴν δὲ Φαρναβάζου χώραν μὴ ἀδικεῖν, Φαρνάβαζον δὲ πρέσβεσιν Ἀθηναίων πρὸς βασιλέα πομπὴν μετ’ ἀσφαλείας παρασχεῖν. ὡς οὖν ἐπανελθόντα τὸν Ἀλκιβιάδην ὁ Φαρνάβαζος ἠξίου καὶ αὐτὸν ὀμόσαι περὶ τῶν ὡμολογημένων, οὐκ ἔφη πρότερον ἢ ἐκεῖνον αὐτοῖς ὀμόσαι.", "st": "Alc. 31.1"}, {"sp": "N", "t": "γενομένων δὲ τῶν ὅρκων ἐπὶ Βυζαντίους ἀφεστῶτας ἦλθε καὶ περιετείχιζε τὴν πόλιν. Ἀναξιλάου δὲ καὶ Λυκούργου καί τινων ἄλλων συνθεμένων ἐπὶ σωτηρίᾳ παραδώσειν τὴν πόλιν, διαδοὺς λόγον ὡς ἀνίστησιν αὐτοὺς πράγματα νεώτερα συνιστάμενα περὶ τὴν Ἰωνίαν, ἡμέρας ἀπέπλει ταῖς ναυσὶ πάσαις, νυκτὸς δ’ ὑποστρέψας αὐτὸς μὲν ἀπέβη μετὰ τῶν ὁπλιτῶν καὶ προσελθὼν τοῖς τείχεσιν ἡσυχίαν ἦγεν, αἱ δὲ νῆες ἐπὶ τὸν λιμένα πλεύσασαι καὶ βιαζόμεναι κραυγῇ τε πολλῇ καὶ θορύβοις καὶ ψόφοις ἅμα μὲν ἐξέπληττον τῷ ἀπροσδοκήτῳ τοὺς Βυζαντίους, ἅμα δὲ τοῖς ἀττικίζουσι παρεῖχον ἐπ’ ἀδείας τὸν Ἀλκιβιάδην δέχεσθαι, πάντων ἐπὶ τὸν λιμένα καὶ τὰς ναῦς βοηθούντων. οὐ μὴν ἀμαχεὶ προσεχώρησαν· οἱ γὰρ παρόντες ἐν τῷ Βυζαντίῳ Πελοποννήσιοι καὶ Βοιωτοὶ καὶ Μεγαρεῖς τοὺς μὲν ἀπὸ τῶν νεῶν ἐτρέψαντο καὶ καθεῖρξαν εἰς τὰς ναῦς πάλιν, τοὺς δ’ Ἀθηναίους ἔνδον ὄντας αἰσθόμενοι καὶ συντάξαντες ἑαυτοὺς ἐχώρουν ὁμόσε. καρτερᾶς δὲ μάχης γενομένης ἐνίκησεν Ἀλκιβιάδης τὸ δεξιὸν κέρας ἔχων, Θηραμένης δὲ τὸ εὐώνυμον, καὶ τῶν πολεμίων τοὺς περιγενομένους ὅσον τριακοσίους ζῶντας ἔλαβε.", "st": "Alc. 31.3"}, {"sp": "N", "t": "Βυζαντίων δὲ μετὰ τὴν μάχην οὐδεὶς ἀπέθανεν οὐδ’ ἔφυγεν. ἐπὶ τούτοις γὰρ οἱ ἄνδρες παρέδοσαν τὴν πόλιν καὶ ταῦτα συνέθεντο, μηδὲν αὑτοῖς ἴδιον ὑπεξελόμενοι. διὸ καὶ δίκην προδοσίας ἐν Λακεδαίμονι φεύγων ὁ Ἀναξίλαος ἐφάνη τῷ λόγῳ τὸ ἔργον οὐκ αἰσχύνων. ἔφη γὰρ οὐκ ὢν Λακεδαιμόνιος, ἀλλὰ Βυζάντιος, οὐδὲ τὴν Σπάρτην κινδυνεύουσαν, ἀλλὰ τὸ Βυζάντιον ὁρῶν, τῆς μὲν πόλεως ἀποτετειχισμένης, μηδενὸς δ’ εἰσαγομένου, τὸν δ’ ὄντα σῖτον ἐν τῇ πόλει Πελοποννησίων καὶ Βοιωτῶν ἐσθιόντων, Βυζαντίων δὲ πεινώντων σὺν τέκνοις καὶ γυναιξίν, οὐ προδοῦναι τοῖς πολεμίοις, ἀλλὰ πολέμων καὶ κακῶν ἀπαλλάξαι τὴν πόλιν, μιμούμενος τοὺς ἀρίστους Λακεδαιμονίων, οἷς ἓν καλὸν ἁπλῶς καὶ δίκαιόν ἐστι τὸ τῆς πατρίδος συμφέρον. οἱ μὲν οὖν Λακεδαιμόνιοι ταῦτ’ ἀκούσαντες ᾐδέσθησαν καὶ ἀπέλυσαν τοὺς ἄνδρας.", "st": "Alc. 31.5"}, {"sp": "N", "t": "ὁ δ’ Ἀλκιβιάδης ἰδεῖν τε ποθῶν ἤδη τὰ οἴκοι, καὶ ἔτι μᾶλλον ὀφθῆναι βουλόμενος τοῖς πολίταις νενικηκὼς τοὺς πολεμίους τοσαυτάκις, ἀνήχθη, πολλαῖς μὲν ἀσπίσι καὶ λαφύροις κύκλῳ κεκοσμημένων τῶν Ἀττικῶν τριήρων, πολλὰς δ’ ἐφελκόμενος αἰχμαλώτους, ἔτι δὲ πλείω κομίζων ἀκροστόλια τῶν διεφθαρμένων ὑπ’ αὐτοῦ καὶ κεκρατημένων. ἦσαν γὰρ οὐκ ἐλάττους συναμφότεραι διακοσίων.", "st": "Alc. 32.1"}, {"sp": "N", "t": "ἃ δὲ Δοῦρις ὁ Σάμιος Ἀλκιβιάδου φάσκων ἀπόγονος εἶναι προστίθησι τούτοις, αὐλεῖν μὲν εἰρεσίαν τοῖς ἐλαύνουσι Χρυσόγονον τὸν πυθιονίκην, κελεύειν δὲ Καλλιππίδην τὸν τῶν τραγῳδιῶν ὑποκριτήν, στατοὺς καὶ ξυστίδας καὶ τὸν ἄλλον ἐναγώνιον ἀμπεχομένους κόσμον, ἱστίῳ δ’ ἁλουργῷ τὴν ναυαρχίδα προσφέρεσθαι τοῖς λιμέσιν, ὥσπερ ἐκ μέθης ἐπικωμάζοντος, οὔτε Θεόπομπος οὔτ’ Ἔφορος οὔτε Ξενοφῶν γέγραφεν, οὔτ’ εἰκὸς ἦν οὕτως ἐντρυφῆσαι τοῖς Ἀθηναίοις μετὰ φυγὴν καὶ συμφορὰς τοσαύτας κατερχόμενον, ἀλλ’ ἐκεῖνος καὶ δεδιὼς κατήγετο, καὶ καταχθεὶς οὐ πρότερον ἀπέβη τῆς τριήρους, πρὶν στὰς ἐπὶ τοῦ καταστρώματος ἰδεῖν Εὐρυπτόλεμόν τε τὸν ἀνεψιὸν παρόντα καὶ τῶν ἄλλων φίλων καὶ οἰκείων συχνοὺς ἐκδεχομένους καὶ παρακαλοῦντας.", "st": "Alc. 32.2"}, {"sp": "N", "t": "ἐπεὶ δ’ ἀπέβη, τοὺς μὲν ἄλλους στρατηγοὺς οὐδ’ ὁρᾶν ἐδόκουν ἀπαντῶντες οἱ ἄνθρωποι, πρὸς δ’ ἐκεῖνον συντρέχοντες ἐβόων, ἠσπάζοντο, παρέπεμπον, ἐστεφάνουν προσιόντες, οἱ δὲ μὴ δυνάμενοι προσελθεῖν ἄπωθεν ἐθεῶντο, καὶ τοῖς νέοις ἐδείκνυσαν οἱ πρεσβύτεροι. πολὺ δὲ καὶ δάκρυον τῷ χαίροντι τῆς πόλεως ἀνεκέκρατο, καὶ μνήμη πρὸς τὴν παροῦσαν εὐτυχίαν τῶν πρόσθεν ἀτυχημάτων, λογιζομένοις ὡς οὔτ’ ἂν Σικελίας διήμαρτον οὔτ’ ἄλλο τι τῶν προσδοκηθέντων ἐξέφυγεν αὐτοὺς ἐάσαντας Ἀλκιβιάδην ἐπὶ τῶν τότε πραγμάτων καὶ τῆς δυνάμεως ἐκείνης, εἰ νῦν τὴν πόλιν παραλαβὼν ὀλίγου δέουσαν ἐκπεπτωκέναι τῆς θαλάττης, κατὰ γῆν δὲ μόλις τῶν προαστείων κρατοῦσαν, αὐτὴν δὲ πρὸς ἑαυτὴν στασιάζουσαν, ἐκ λυπρῶν ἔτι λειψάνων καὶ ταπεινῶν ἀναστήσας οὐ μόνον τῆς θαλάττης τὸ κράτος ἀποδέδωκεν, ἀλλὰ καὶ πεζῇ νικῶσαν ἀποδείκνυσι πανταχοῦ τοὺς πολεμίους.", "st": "Alc. 32.4"}, {"sp": "N", "t": "τὸ μὲν οὖν ψήφισμα τῆς καθόδου πρότερον ἐκεκύρωτο, Κριτίου τοῦ Καλλαίσχρου γράψαντος, ὡς αὐτὸς ἐν ταῖς ἐλεγείαις πεποίηκεν, ὑπομιμνήσκων τὸν Ἀλκιβιάδην τῆς χάριτος ἐν τούτοις·", "st": "Alc. 33.1"}, {"sp": "N", "t": "γνώμη δ’ ἥ σε κατήγαγ’, ἐγὼ ταύτην ἐν ἅπασιν<br>εἶπον, καὶ γράψας τοὖργον ἔδρασα τόδε.<br>σφραγὶς δ’ ἡμετέρης γλώττης ἐπὶ τοῖσδεσι<br>κεῖται·", "st": "Alc. 33.1b"}, {"sp": "N", "t": "τότε δὲ τοῦ δήμου συνελθόντος εἰς τὴν ἐκκλησίαν παρελθὼν ὁ Ἀλκιβιάδης, καὶ τὰ μὲν αὑτοῦ πάθη κλαύσας καὶ ὀλοφυράμενος, ἐγκαλέσας δὲ μικρὰ καὶ μέτρια τῷ δήμῳ, τὸ δὲ σύμπαν ἀναθεὶς αὑτοῦ τινι τύχῃ πονηρᾷ καὶ φθονερῷ δαίμονι, πλεῖστα δ’ εἰς ἐλπίδας τῶν πολεμίων καὶ πρὸς τὸ θαρρεῖν διαλεχθεὶς καὶ παρορμήσας, στεφάνοις μὲν ἐστεφανώθη χρυσοῖς, ᾑρέθη δ’ ἅμα καὶ κατὰ γῆν καὶ κατὰ θάλασσαν αὐτοκράτωρ στρατηγός. ἐψηφίσαντο δὲ τὴν οὐσίαν ἀποδοῦναι αὐτῷ, καὶ τὰς ἀρὰς ἀφοσιώσασθαι πάλιν Εὐμολπίδας καὶ Κήρυκας, ἃς ἐποιήσαντο τοῦ δήμου προστάξαντος. ἀφοσιουμένων δὲ τῶν ἄλλων, Θεόδωρος ὁ ἱεροφάντης ἀλλ’ ἐγώ, εἶπεν, οὐδὲ κατηρασάμην αὐτῷ κακὸν οὐδέν, εἰ μηδὲν ἀδικεῖ τὴν πόλιν.", "st": "Alc. 33.2"}, {"sp": "N", "t": "οὕτω δὲ τοῦ Ἀλκιβιάδου λαμπρῶς εὐημεροῦντος ὑπέθραττεν ἐνίους ὅμως ὁ τῆς καθόδου καιρός. ᾗ γὰρ ἡμέρᾳ κατέπλευσεν, ἐδρᾶτο τὰ Πλυντήρια τῇ θεῷ. δρῶσι δὲ τὰ ὄργια Πραξιεργίδαι Θαργηλιῶνος ἕκτῃ φθίνοντος ἀπόρρητα, τόν τε κόσμον καθελόντες καὶ τὸ ἕδος κατακαλύψαντες. ὅθεν ἐν ταῖς μάλιστα τῶν ἀποφράδων τὴν ἡμέραν ταύτην ἄπρακτον Ἀθηναῖοι νομίζουσιν. οὐ φιλοφρόνως οὖν οὐδ’ εὐμενῶς ἐδόκει προσδεχομένη τὸν Ἀλκιβιάδην ἡ θεὸς παρακαλύπτεσθαι καὶ ἀπελαύνειν ἑαυτῆς. οὐ μὴν ἀλλὰ πάντων γεγονότων τῷ Ἀλκιβιάδῃ κατὰ γνώμην, καὶ πληρουμένων ἑκατὸν τριήρων αἷς αὖθις ἐκπλεῖν ἔμελλε, φιλοτιμία τις οὐκ ἀγεννὴς προσπεσοῦσα κατέσχεν αὐτὸν ἄχρι μυστηρίων.", "st": "Alc. 34.1"}, {"sp": "N", "t": "ἀφ’ οὗ γὰρ ἐπετειχίσθη Δεκέλεια καὶ τῶν εἰς Ἐλευσῖνα παρόδων ἐκράτουν οἱ πολέμιοι παρόντες, οὐδένα κόσμον εἶχεν ἡ τελετὴ πεμπομένη κατὰ θάλατταν, ἀλλὰ καὶ θυσίαι καὶ χορεῖαι καὶ πολλὰ τῶν δρωμένων καθ’ ὁδὸν ἱερῶν, ὅταν ἐξελαύνωσι τὸν Ἴακχον, ὑπ’ ἀνάγκης ἐξελείπετο. καλὸν οὖν ἐφαίνετο τῷ Ἀλκιβιάδῃ καὶ πρὸς θεῶν ὁσιότητα καὶ πρὸς ἀνθρώπων δόξαν ἀποδοῦναι τὸ πάτριον σχῆμα τοῖς ἱεροῖς, παραπέμψαντα πεζῇ τὴν τελετὴν καὶ δορυφορήσαντα παρὰ τοὺς πολεμίους· ἢ γὰρ ἀτρεμήσαντα κομιδῇ κολούσειν καὶ ταπεινώσειν τὸν Ἆγιν, ἢ μάχην ἱερὰν καὶ θεοφιλῆ περὶ τῶν ἁγιωτάτων καὶ μεγίστων ἐν ὄψει τῆς πατρίδος μαχεῖσθαι, καὶ πάντας ἕξειν μάρτυρας τοὺς πολίτας τῆς ἀνδραγαθίας.", "st": "Alc. 34.3"}, {"sp": "N", "t": "ὡς δὲ ταῦτ’ ἔγνω καὶ προεῖπεν Εὐμολπίδαις καὶ Κήρυξι, σκοποὺς μὲν ἐπὶ τῶν ἄκρων ἐκάθισε καὶ προδρόμους τινὰς ἅμ’ ἡμέρᾳ προεξέπεμψεν, ἱερεῖς δὲ καὶ μύστας καὶ μυσταγωγοὺς ἀναλαβὼν καὶ τοῖς ὅπλοις περικαλύψας ἦγεν ἐν κόσμῳ καὶ μετὰ σιωπῆς, θέαμα σεμνὸν καὶ θεοπρεπὲς τὴν στρατηγίαν ἐκείνην ἐπιδεικνύμενος, ὑπὸ τῶν μὴ φθονούντων ἱεροφαντίαν καὶ μυσταγωγίαν προσαγορευομένην. μηδενὸς δὲ τῶν πολεμίων ἐπιθέσθαι τολμήσαντος ἀσφαλῶς ἐπαναγαγὼν εἰς τὴν πόλιν, ἤρθη μὲν αὐτὸς τῷ φρονήματι καὶ τὴν στρατιὰν ἐπῆρεν ὡς ἄμαχον καὶ ἀήττητον οὖσαν ἐκείνου στρατηγοῦντος, τοὺς δὲ φορτικοὺς καὶ πένητας οὕτως ἐδημαγώγησεν ὥστ’ ἐρᾶν ἔρωτα θαυμαστὸν ὑπ’ ἐκείνου τυραννεῖσθαι, καὶ λέγειν ἐνίους καὶ προσιέναι παρακελευομένους ὅπως τοῦ φθόνου κρείττων γενόμενος καὶ καταβαλὼν ψηφίσματα καὶ νόμους καὶ φλυάρους ἀπολλύντας τὴν πόλιν ὡς ἂν πράξῃ καὶ χρήσηται τοῖς πράγμασι, μὴ δεδιὼς τοὺς συκοφάντας.", "st": "Alc. 34.5"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν ἐκεῖνος ἣν εἶχε διάνοιαν περὶ τῆς τυραννίδος ἄδηλόν ἐστιν· οἱ δὲ δυνατώτατοι τῶν πολιτῶν φοβηθέντες ἐσπούδασαν αὐτὸν ἐκπλεῦσαι τὴν ταχίστην, τά τ’ ἄλλα ψηφισάμενοι καὶ συνάρχοντας οὓς ἐκεῖνος ἠθέλησεν. ἐκπλεύσας δὲ ταῖς ἑκατὸν ναυσὶ καὶ προσβαλὼν Ἄνδρῳ, μάχῃ μὲν ἐκράτησεν αὐτῶν καὶ Λακεδαιμονίων ὅσοι παρῆσαν, οὐχ εἷλε δὲ τὴν πόλιν, ἀλλὰ τοῦτο τῶν καινῶν ἐγκλημάτων πρῶτον ὑπῆρξε κατ’ αὐτοῦ τοῖς ἐχθροῖς.", "st": "Alc. 35.1"}, {"sp": "N", "t": "ἔοικε δ’, εἴ τις ἄλλος, ὑπὸ τῆς αὑτοῦ δόξης καταλυθῆναι καὶ Ἀλκιβιάδης. μεγάλη γὰρ οὖσα καὶ τόλμης καὶ συνέσεως γέμουσα ἀφ’ ὧν κατώρθωσεν, ὕποπτον αὐτοῦ τὸ ἐλλεῖπον, ὡς οὐ σπουδάσαντος, ἀπιστίᾳ τοῦ μὴ δυνηθῆναι παρεῖχε· σπουδάσαντα γὰρ οὐδὲν ἂν διαφυγεῖν. ἤλπιζον δὲ καὶ Χίους ἑαλωκότας ἀκούσεσθαι καὶ τὴν ἄλλην Ἰωνίαν. ὅθεν ἠγανάκτουν μὴ ταχὺ πάντα μηδ’ εὐθέως, ὡς ἐβούλοντο, πυνθανόμενοι διαπεπραγμένον, οὐχ ὑπολογιζόμενοι τὴν ἀχρηματίαν, ἀφ’ ἧς πολεμῶν πρὸς ἀνθρώπους βασιλέα μέγαν χορηγὸν ἔχοντας ἠναγκάζετο πολλάκις ἐκπλέων καὶ ἀπολείπων τὸ στρατόπεδον μισθοὺς καὶ τροφὰς πορίζειν. καὶ γὰρ τὸ τελευταῖον ἔγκλημα διὰ ταύτην ἔλαβε τὴν αἰτίαν.", "st": "Alc. 35.2"}, {"sp": "N", "t": "Λυσάνδρου γὰρ ἐπὶ τὴν ναυαρχίαν ἀποσταλέντος ὑπὸ Λακεδαιμονίων, καὶ τετρώβολον ἀντὶ τριωβόλου τῷ ναύτῃ διδόντος ἐξ ὧν ἔλαβε παρὰ Κύρου χρημάτων, αὐτὸς ἤδη γλίσχρως χορηγῶν καὶ τὸ τριώβολον ἀπῆρεν ἀργυρολογήσων ἐπὶ Καρίας. ὁ δ’ ἀπολειφθεὶς ἐπὶ τῶν νεῶν ἐπιμελητὴς Ἀντίοχος ἀγαθὸς μὲν ἦν κυβερνήτης, ἀνόητος δὲ τἆλλα καὶ φορτικός· ἔχων δὲ πρόσταγμα παρὰ τοῦ Ἀλκιβιάδου μηδ’ ἂν ἐπιπλέωσιν οἱ πολέμιοι διαναυμαχεῖν, οὕτως ἐξύβρισε καὶ κατεφρόνησεν ὥστε τὴν αὑτοῦ πληρωσάμενος τριήρη καὶ τῶν ἄλλων μίαν ἐπιπλεῦσαι τῇ Ἐφέσῳ καὶ παρὰ τὰς πρῴρας τῶν πολεμίων νεῶν πολλὰ καὶ πράττων καὶ φθεγγόμενος ἀκόλαστα καὶ βωμολόχα παρεξελαύνειν. τὸ μὲν οὖν πρῶτον Λύσανδρος ὀλίγαις ναυσὶν ἐπαναχθεὶς ἐδίωκεν αὐτόν, τῶν δ’ Ἀθηναίων ἐπιβοηθούντων πάσαις ἀναχθεὶς καὶ κρατήσας αὐτόν τε διέφθειρε τὸν Ἀντίοχον καὶ ναῦς ἔλαβε πολλὰς καὶ ἀνθρώπους καὶ τρόπαιον ἔστησεν. ὡς δὲ ταῦτ’ ἤκουσεν ὁ Ἀλκιβιάδης ἐπανελθὼν εἰς Σάμον, ἀνήχθη παντὶ τῷ στόλῳ καὶ προὐκαλεῖτο τὸν Λύσανδρον. ὁ δ’ ἠγάπα νενικηκὼς καὶ οὐκ ἀντανήγετο.", "st": "Alc. 35.4"}, {"sp": "N", "t": "τῶν δὲ μισούντων τὸν Ἀλκιβιάδην ἐν τῷ στρατοπέδῳ Θρασύβουλος ὁ Θράσωνος ἐχθρὸς ὢν ἀπῆρεν εἰς Ἀθήνας κατηγορήσων. καὶ τοὺς ἐκεῖ παροξύνας ἔλεγε πρὸς τὸν δῆμον ὡς Ἀλκιβιάδης διέφθαρκε τὰ πράγματα καὶ τὰς ναῦς ἀπολώλεκεν, ἐντρυφῶν τῇ ἀρχῇ καὶ παραδιδοὺς τὴν στρατηγίαν ἀνθρώποις ἐκ πότων καὶ ναυτικῆς σπερμολογίας δυναμένοις παρ’ αὐτῷ μέγιστον, ὅπως αὐτὸς ἐπ’ ἀδείας χρηματίζηται περιπλέων καὶ ἀκολασταίνῃ μεθυσκόμενος καὶ συνὼν ἑταίραις Ἀβυδηναῖς καὶ Ἰωνίσιν, ἐφορμούντων δι’ ὀλίγου τῶν πολεμίων. ἐνεκάλουν δ’ αὐτῷ καὶ τὴν τῶν τειχῶν κατασκευήν, ἃ κατεσκεύασεν ἐν Θρᾴκῃ περὶ Βισάνθην αὑτῷ καταφυγὴν ὡς ἐν τῇ πατρίδι μὴ δυνάμενος βιοῦν ἢ μὴ βουλόμενος. οἱ δ’ Ἀθηναῖοι πεισθέντες ἑτέρους εἵλοντο στρατηγούς, ἐνδεικνύμενοι τὴν πρὸς ἐκεῖνον ὀργὴν καὶ κακόνοιαν. ἃ δὴ πυνθανόμενος ὁ Ἀλκιβιάδης καὶ δεδοικὼς ἀπῆλθεν ἐκ τοῦ στρατοπέδου παντάπασι, καὶ συναγαγὼν ξένους ἐπολέμει τοῖς ἀβασιλεύτοις Θρᾳξὶν ἰδίᾳ, καὶ πολλὰ χρήματα συνήγαγεν ἀπὸ τῶν ἁλισκομένων, καὶ τοῖς Ἕλλησιν ἅμα τοῖς προσοικοῦσιν ἄδειαν ἀπὸ τῶν βαρβάρων παρεῖχεν.", "st": "Alc. 36.1"}, {"sp": "N", "t": "ἐπεὶ δ’ οἱ περὶ Τυδέα καὶ Μένανδρον καὶ Ἀδείμαντον στρατηγοί, πάσας ὁμοῦ τὰς ὑπαρχούσας τότε ναῦς τοῖς Ἀθηναίοις ἔχοντες ἐν Αἰγὸς ποταμοῖς, εἰώθεσαν ἐπιπλεῖν τῷ Λυσάνδρῳ ναυλοχοῦντι περὶ Λάμψακον ἅμ’ ἡμέρᾳ προκαλούμενοι καὶ πάλιν ἀναστρέφειν ὀπίσω καὶ διημερεύειν ἀτάκτως καὶ ἀμελῶς, ἅτε δὴ καταφρονοῦντες, ἐγγὺς ὢν ὁ Ἀλκιβιάδης οὐ περιεῖδεν οὐδ’ ἠμέλησεν, ἀλλ’ ἵππῳ προσελάσας ἐδίδασκε τοὺς στρατηγοὺς ὅτι κακῶς ὁρμοῦσιν ἐν χωρίοις ἀλιμένοις καὶ πόλιν οὐκ ἔχουσιν, ἀλλὰ πόρρωθεν ἐκ Σηστοῦ τὰ ἐπιτήδεια λαμβάνοντες, καὶ περιορῶντες τὸ ναυτικόν, ὅταν ἐπὶ τῆς γῆς γένηται, πλανώμενον ὅποι τις θέλοι καὶ διασπειρόμενον, ἀντεφορμοῦντος αὐτοῖς στόλου πρὸς ἐπίταγμα μοναρχικὸν εἰθισμένου σιωπῇ πάντα ποιεῖν.", "st": "Alc. 36.4"}, {"sp": "N", "t": "ταῦτα δὲ λέγοντος τοῦ Ἀλκιβιάδου, καὶ παραινοῦντος εἰς Σηστὸν μεθορμίσαι τὸν στόλον, οὐ προσεῖχον οἱ στρατηγοί· Τυδεὺς δὲ καὶ πρὸς ὕβριν ἐκέλευσεν ἀποχωρεῖν, οὐ γὰρ ἐκεῖνον, ἀλλ’ ἑτέρους στρατηγεῖν. ὁ δ’ Ἀλκιβιάδης ὑπονοήσας τι καὶ προδοσίας ἐν αὐτοῖς ἀπῄει, καὶ τοῖς προπέμπουσι τῶν ἀπὸ τοῦ στρατοπέδου γνωρίμων ἔλεγεν ὅτι μὴ προπηλακισθεὶς οὕτως ὑπὸ τῶν στρατηγῶν ὀλίγαις ἂν ἡμέραις ἠνάγκασε Λακεδαιμονίους διαναυμαχεῖν αὐτοῖς ἄκοντας ἢ τὰς ναῦς ἀπολιπεῖν. ἐδόκει δὲ τοῖς μὲν ἀλαζονεύεσθαι, τοῖς δ’ εἰκότα λέγειν, εἰ Θρᾷκας ἐκ γῆς ἐπαγαγὼν πολλοὺς ἀκοντιστὰς καὶ ἱππεῖς προσμάχοιτο καὶ διαταράττοι τὸ στρατόπεδον αὐτῶν.", "st": "Alc. 37.1"}, {"sp": "N", "t": "ὅτι μέντοι τὰς ἁμαρτίας τῶν Ἀθηναίων ὀρθῶς συνεῖδε, ταχὺ τὸ ἔργον ἐμαρτύρησεν. ἄφνω γὰρ αὐτοῖς καὶ ἀπροσδοκήτως τοῦ Λυσάνδρου προσπεσόντος, ὀκτὼ μόναι τριήρεις ἐξέφυγον μετὰ Κόνωνος, αἱ δ’ ἄλλαι μικρὸν ἀπολείπουσαι διακοσίων ἀπήχθησαν αἰχμάλωτοι. τῶν δ’ ἀνθρώπων τρισχιλίους ἑλὼν ζῶντας ἀπέσφαξεν ὁ Λύσανδρος. ἔλαβε δὲ καὶ τὰς Ἀθήνας ὀλίγῳ χρόνῳ καὶ τὰς ναῦς ἐνέπρησε καὶ τὰ μακρὰ τείχη καθεῖλεν.", "st": "Alc. 37.3"}, {"sp": "N", "t": "ἐκ δὲ τούτου φοβηθεὶς ὁ Ἀλκιβιάδης ἄρχοντας ἤδη καὶ γῆς καὶ θαλάττης τοὺς Λακεδαιμονίους εἰς Βιθυνίαν μετέστη, πολλὰ μὲν ἄγων χρήματα, πολλὰ δὲ κομίζων, ἔτι δὲ πλείω καταλιπὼν ἐν οἷς ᾤκει τείχεσιν. ἐν δὲ Βιθυνίᾳ πάλιν οὐκ ὀλίγα τῶν ἰδίων ἀπολέσας καὶ περικοπεὶς ὑπὸ τῶν ἐκεῖ Θρᾳκῶν, ἔγνω μὲν ἀναβαίνειν πρὸς Ἀρταξέρξην, ἑαυτόν τε μὴ χείρονα Θεμιστοκλέους πειρωμένῳ βασιλεῖ φανεῖσθαι νομίζων, καὶ κρείττονα τὴν πρόφασιν· οὐ γὰρ ἐπὶ τοὺς πολίτας, ὡς ἐκεῖνον, ἀλλ’ ὑπὲρ τῆς πατρίδος ἐπὶ τοὺς πολεμίους ὑπουργήσειν καὶ δεήσεσθαι τῆς βασιλέως δυνάμεως· εὐπορίαν δὲ τῆς ἀνόδου μετὰ ἀσφαλείας μάλιστα Φαρνάβαζον οἰόμενος παρέξειν, ᾤχετο πρὸς αὐτὸν εἰς Φρυγίαν, καὶ συνδιῆγε θεραπεύων ἅμα καὶ τιμώμενος.", "st": "Alc. 37.4"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ χαλεπῶς μὲν ἔφερον καὶ τῆς ἡγεμονίας ἀποστερηθέντες· ἐπεὶ δὲ καὶ τὴν ἐλευθερίαν ἀφελόμενος αὐτῶν ὁ Λύσανδρος ἀνδράσι τριάκοντα παρέδωκε τὴν πόλιν, οἷς οὐκ ἐχρήσαντο σώζεσθαι δυνάμενοι λογισμοῖς, ἀπολωλότων ἤδη τῶν πραγμάτων, συνίεσαν, ὀλοφυρόμενοι καὶ διεξιόντες τὰς ἁμαρτίας αὑτῶν καὶ ἀγνοίας, ὧν μεγίστην ἐποιοῦντο τὴν δευτέραν πρὸς Ἀλκιβιάδην ὀργήν. ἀπερρίφη γὰρ οὐδὲν ἀδικῶν αὐτός, ἀλλ’ ὑπηρέτῃ χαλεπήναντες ὀλίγας ἀποβαλόντι ναῦς αἰσχρῶς, αἴσχιον αὐτοὶ τὸν κράτιστον καὶ πολεμικώτατον ἀφείλοντο τῆς πόλεως στρατηγόν. ἔτι δ’ οὖν ὅμως ἐκ τῶν παρόντων ἀνέφερέ τις ἐλπὶς ἀμυδρὰ μὴ παντάπασιν ἔρρειν τὰ πράγματα τῶν Ἀθηναίων Ἀλκιβιάδου περιόντος· οὔτε γὰρ πρότερον ἠγάπησε φεύγων ἀπραγμόνως ζῆν καὶ μεθ’ ἡσυχίας, οὔτε νῦν, εἰ τὰ καθ’ ἑαυτὸν ἱκανῶς ἔχει, περιόψεται Λακεδαιμονίους ὑβρίζοντας καὶ τοὺς τριάκοντα παροινοῦντας.", "st": "Alc. 38.1"}, {"sp": "N", "t": "ταῦτα δ’ οὐκ ἦν ἄλογον οὕτως ὀνειροπολεῖν τοὺς πολλούς, ὁπότε καὶ τοῖς τριάκοντα φροντίζειν ἐπῄει καὶ διαπυνθάνεσθαι καὶ λόγον ἔχειν πλεῖστον ὧν ἐκεῖνος ἔπραττε καὶ διενοεῖτο. τέλος δὲ Κριτίας ἐδίδασκε Λύσανδρον ὡς Ἀθηναίων οὐκ ἔστι δημοκρατουμένων ἀσφαλῶς ἄρχειν Λακεδαιμονίοις τῆς Ἑλλάδος· Ἀθηναίους δέ, κἂν πρᾴως πάνυ καὶ καλῶς πρὸς ὀλιγαρχίαν ἔχωσιν, οὐκ ἐάσει ζῶν Ἀλκιβιάδης ἀτρεμεῖν ἐπὶ τῶν καθεστώτων. οὐ μὴν ἐπείσθη γε πρότερον τούτοις ὁ Λύσανδρος ἢ παρὰ τῶν οἴκοι τελῶν σκυτάλην ἐλθεῖν κελεύουσαν ἐκ ποδῶν ποιήσασθαι τὸν Ἀλκιβιάδην, εἴτε κἀκείνων φοβηθέντων τὴν ὀξύτητα καὶ μεγαλοπραγμοσύνην τοῦ ἀνδρός, εἴτε τῷ Ἄγιδι χαριζομένων.", "st": "Alc. 38.3"}, {"sp": "N", "t": "ὡς οὖν ὁ Λύσανδρος ἔπεμψε πρὸς τὸν Φαρνάβαζον ταῦτα πράττειν κελεύων, ὁ δὲ Μαγαίῳ τε τῷ ἀδελφῷ καὶ Σουσαμίθρῃ τῷ θείῳ προσέταξε τὸ ἔργον, ἔτυχε μὲν ἐν κώμῃ τινὶ τῆς Φρυγίας ὁ Ἀλκιβιάδης τότε διαιτώμενος, ἔχων Τιμάνδραν μεθ’ αὑτοῦ τὴν ἑταίραν, ὄψιν δὲ κατὰ τοὺς ὕπνους εἶδε τοιαύτην· ἐδόκει περικεῖσθαι μὲν αὐτὸς τὴν ἐσθῆτα τῆς ἑταίρας, ἐκείνην δὲ τὴν κεφαλὴν ἐν ταῖς ἀγκάλαις ἔχουσαν αὐτοῦ κοσμεῖν τὸ πρόσωπον ὥσπερ γυναικὸς ὑπογράφουσαν καὶ ψιμυθιοῦσαν. ἕτεροι δέ φασιν ἰδεῖν τὴν κεφαλὴν ἀποτέμνοντας αὐτοῦ τοὺς περὶ τὸν Μαγαῖον ἐν τοῖς ὕπνοις καὶ τὸ σῶμα καιόμενον. ἀλλὰ τὴν μὲν ὄψιν οὐ πολὺ γενέσθαι λέγουσι πρὸ τῆς τελευτῆς.", "st": "Alc. 39.1"}, {"sp": "N", "t": "οἱ δὲ πεμφθέντες πρὸς αὐτὸν οὐκ ἐτόλμησαν εἰσελθεῖν, ἀλλὰ κύκλῳ τὴν οἰκίαν περιστάντες ἐνεπίμπρασαν. αἰσθόμενος δ’ ὁ Ἀλκιβιάδης τῶν μὲν ἱματίων τὰ πλεῖστα καὶ τῶν στρωμάτων συναγαγὼν ἐπέρριψε τῷ πυρί, τῇ δ’ ἀριστερᾷ χειρὶ τὴν ἑαυτοῦ χλαμύδα περιελίξας, τῇ δεξιᾷ σπασάμενος τὸ ἐγχειρίδιον ἐξέπεσεν ἀπαθὴς ὑπὸ τοῦ πυρὸς πρὶν ἢ διαφλέγεσθαι τὰ ἱμάτια, καὶ τοὺς βαρβάρους ὀφθεὶς διεσκέδασεν. οὐδεὶς γὰρ ὑπέμεινεν αὐτὸν οὐδ’ εἰς χεῖρας συνῆλθεν, ἀλλ’ ἀποστάντες ἔβαλλον ἀκοντίοις καὶ τοξεύμασιν. οὕτω δ’ αὐτοῦ πεσόντος καὶ τῶν βαρβάρων ἀπελθόντων, ἡ Τιμάνδρα τὸν νεκρὸν ἀνείλετο, καὶ τοῖς αὑτῆς περιβαλοῦσα καὶ περικαλύψασα χιτωνίσκοις, ἐκ τῶν παρόντων ἐκήδευσε λαμπρῶς καὶ φιλοτίμως.", "st": "Alc. 39.3"}, {"sp": "N", "t": "ταύτης λέγουσι θυγατέρα γενέσθαι Λαΐδα τὴν Κορινθίαν μὲν προσαγορευθεῖσαν, ἐκ δὲ Ὑκκάρων, Σικελικοῦ πολίσματος, αἰχμάλωτον γενομένην. ἔνιοι δὲ τὰ μὲν ἄλλα περὶ τῆς Ἀλκιβιάδου τελευτῆς ὁμολογοῦσι τούτοις, αἰτίαν δέ φασιν οὐ Φαρνάβαζον οὐδὲ Λύσανδρον οὐδὲ Λακεδαιμονίους παρασχεῖν, αὐτὸν δὲ τὸν Ἀλκιβιάδην γνωρίμων τινῶν διεφθαρκότα γύναιον ἔχειν σὺν αὑτῷ, τοὺς δ’ ἀδελφοὺς τοῦ γυναίου τὴν ὕβριν οὐ μετρίως φέροντας ἐμπρῆσαί τε τὴν οἰκίαν νύκτωρ, ἐν ᾗ διαιτώμενος ἐτύγχανεν ὁ Ἀλκιβιάδης, καὶ καταβαλεῖν αὐτόν, ὥσπερ εἴρηται, διὰ τοῦ πυρὸς ἐξαλλόμενον.", "st": "Alc. 39.5"}, {"sp": "HDR", "t": "Γάϊος Μάρκιος"}, {"sp": "N", "t": "ὁ Μαρκίων οἶκος ἐν Ῥώμῃ τῶν πατρικίων πολλοὺς παρέσχεν ἐνδόξους ἄνδρας, ὧν καὶ Μάρκιος ἦν Ἄγκος, ὁ Νομᾶ θυγατριδοῦς καὶ μετὰ Τύλλον Ὁστίλιον βασιλεὺς γενόμενος. Μάρκιοι δ’ ἦσαν καὶ Πόπλιος καὶ Κόιντος οἱ πλεῖστον ὕδωρ καὶ κάλλιστον ἐν Ῥώμῃ καταγαγόντες, καὶ Κηνσωρῖνος, ὃν δὶς ἀπέδειξε τιμητὴν ὁ Ῥωμαίων δῆμος, εἶτα ὑπ’ αὐτοῦ πεισθεὶς ἐκείνου νόμον ἔθετο καὶ ἐψηφίσατο μηδενὶ τὴν ἀρχὴν δὶς ἐξεῖναι μετελθεῖν. Γάϊος δὲ Μάρκιος, ὑπὲρ οὗ τάδε γέγραπται, τραφεὶς ὑπὸ μητρὶ χήρᾳ πατρὸς ὀρφανός, ἀπέδειξε τὴν ὀρφανίαν ἄλλα μὲν ἔχουσαν κακά, πρὸς δὲ τὸ γενέσθαι σπουδαῖον ἄνδρα καὶ διαφέροντα τῶν πολλῶν οὐδὲν ἐμποδὼν οὖσαν, ἄλλως δὲ τοῖς φαύλοις αἰτιᾶσθαι καὶ ψέγειν παρέχουσαν αὑτὴν ὡς ἀμελείᾳ διαφθείρουσαν. ὁ δ’ αὐτὸς ἀνὴρ ἐμαρτύρησε καὶ τοῖς τὴν φύσιν ἡγουμένοις, ἐὰν οὖσα γενναία καὶ ἀγαθὴ παιδείας ἐνδεὴς γένηται, πολλὰ τοῖς χρηστοῖς ὁμοῦ φαῦλα συναποτίκτειν, ὥσπερ εὐγενῆ χώραν ἐν γεωργίᾳ θεραπείας μὴ τυχοῦσαν. τὸ γὰρ ἰσχυρὸν αὐτοῦ πρὸς ἅπαντα τῆς γνώμης καὶ καρτερὸν ὁρμάς τε μεγάλας καὶ τελεσιουργοὺς τῶν καλῶν ἐξέφερε, θυμοῖς τε αὖ πάλιν χρώμενον ἀκράτοις καὶ φιλονεικίαις ἀτρέπτοις οὐ ῥᾴδιον οὐδ’ εὐάρμοστον ἀνθρώποις συνεῖναι παρεῖχεν, ἀλλὰ τὴν ἐν ἡδοναῖς καὶ πόνοις καὶ ὑπὸ χρημάτων ἀπάθειαν αὐτοῦ θαυμάζοντες καὶ ὀνομάζοντες ἐγκράτειαν καὶ δικαιοσύνην καὶ ἀνδρείαν, ἐν ταῖς πολιτικαῖς αὖ πάλιν ὁμιλίαις ὡς ἐπαχθῆ καὶ ἄχαριν καὶ ὀλιγαρχικὴν ἐδυσχέραινον. οὐδὲν γὰρ ἄλλο Μουσῶν εὐμενείας ἀπολαύουσιν ἄνθρωποι τοσοῦτον ὅσον ἐξημερῶσαι τὴν φύσιν ὑπὸ λόγου καὶ παιδείας, τῷ λόγῳ δεξαμένην τὸ μέτριον καὶ τὸ ἄγαν ἀποβαλοῦσαν. ὅλως μὲν οὖν ἐν τοῖς τότε χρόνοις ἡ Ῥώμη μάλιστα τῆς ἀρετῆς τὸ περὶ τὰς πολεμικὰς καὶ στρατιωτικὰς ἐκύδαινε πράξεις, καὶ μαρτυρεῖ τὸ τὴν ἀρετὴν ὑπ’ αὐτῶν ἑνὶ τῷ τῆς ἀνδρείας ὀνόματι προσαγορεύεσθαι, καὶ τοῦτο τοῦ γένους ὄνομα κοινὸν ὑπάρχειν ᾧ τὴν ἀνδρείαν ἰδίᾳ καλοῦσιν.", "st": "Cor. 1.1"}, {"sp": "N", "t": "ὁ δὲ Μάρκιος ἑτέρων μᾶλλον ἐμπαθὴς γεγονὼς πρὸς τοὺς πολεμικοὺς ἀγῶνας, εὐθὺς ἐκ παιδὸς τὰ ὅπλα διὰ χειρὸς εἶχε, καὶ τῶν ἐπικτήτων οὐδὲν ἔργον οἰόμενος εἶναι τοῖς μὴ τὸ σύμφυτον ὅπλον καὶ συγγενὲς ἐξηρτυμένον ἔχουσι καὶ παρεσκευασμένον, οὕτως ἤσκησε τὸ σῶμα πρὸς ἅπασαν ἰδέαν μάχης ὥστε καὶ θεῖν ἐλαφρὸν εἶναι καὶ βάρος ἔχειν ἐν λαβαῖς καὶ ἐν διαπάλαις πολέμου δυσεκβίαστον. οἱ γοῦν ἔριν ἔχοντες εὐψυχίας ἀεὶ καὶ ἀρετῆς πρὸς αὐτόν, ἐν οἷς ἐλείποντο, τὴν τοῦ σώματος ᾐτιῶντο ῥώμην ἄτρεπτον οὖσαν καὶ πρὸς μηδένα πόνον ἀπαγορεύουσαν.", "st": "Cor. 2.1"}, {"sp": "N", "t": "ἐστρατεύσατο δὲ πρώτην στρατείαν ἔτι μειράκιον, ὅτε Ταρκυνίῳ τῷ βασιλεύσαντι τῆς Ῥώμης, εἶτα ἐκπεσόντι, μετὰ πολλὰς μάχας καὶ ἥττας ὥσπερ ἔσχατον κύβον ἀφιέντι πλεῖστοι μὲν Λατίνων, πολλοὶ δὲ καὶ τῶν ἄλλων Ἰταλιωτῶν συνελάμβανον καὶ συγκατῆγον ἐπὶ τὴν Ῥώμην, οὐκ ἐκείνῳ χαριζόμενοι μᾶλλον ἢ φόβῳ τὰ Ῥωμαίων αὐξόμενα καὶ φθόνῳ καταβάλλοντες. ἐν ταύτῃ τῇ μάχῃ πολλὰς τροπὰς ἐπ’ ἀμφότερα λαμβανούσῃ Μάρκιος ἀγωνιζόμενος εὐρώστως ἐν ὄψει τοῦ δικτάτορος, ἄνδρα Ῥωμαῖον πεσόντα πλησίον ἰδών οὐκ ἠμέλησεν, ἀλλ’ ἔστη πρὸ αὐτοῦ καὶ τὸν ἐπιφερόμενον τῶν πολεμίων ἀμυνόμενος ἀπέκτεινεν. ὡς οὖν ἐκράτησεν ὁ στρατηγός, ἐν πρώτοις ἐκεῖνον ἐστεφάνωσε δρυὸς στεφάνῳ.", "st": "Cor. 3.1"}, {"sp": "N", "t": "τοῦτον γὰρ ὁ νόμος τῷ πολίτην ὑπερασπίσαντι τὸν στέφανον ἀποδέδωκεν, εἴτε δὴ μάλιστα τιμήσας δι’ Ἀρκάδας τὴν δρῦν βαλανηφάγους ὑπὸ τοῦ θεοῦ χρησμῷ προσαγορευθέντας, εἴτε ὡς ταχὺ καὶ πανταχοῦ δρυὸς οὖσαν εὐπορίαν στρατευομένοις, εἴτε Διὸς Πολιέως ἱερὸν ὄντα τὸν τῆς δρυὸς στέφανον οἰόμενος ἐπὶ σωτηρίᾳ πολίτου δίδοσθαι πρεπόντως. ἔστι δὲ ἡ δρῦς τῶν μὲν ἀγρίων καλλικαρπότατον, τῶν δὲ τιθασῶν ἰσχυρότατον. ἦν δὲ καὶ σιτίον ἀπ’ αὐτῆς ἡ βάλανος καὶ ποτὸν τὸ μελίτειον, ὄψον δὲ παρεῖχε τὰ πλεῖστα τῶν νεμομένων τε καὶ πτηνῶν, θήρας ὄργανον φέρουσα τὸν ἰξόν.", "st": "Cor. 3.3"}, {"sp": "N", "t": "ἐν ἐκείνῃ δὲ τῇ μάχῃ καὶ τοὺς Διοσκούρους ἐπιφανῆναι λέγουσι, καὶ μετὰ τὴν μάχην εὐθὺς ὀφθῆναι ῥεομένοις ἱδρῶτι τοῖς ἵπποις ἐν ἀγορᾷ τὴν νίκην ἀπαγγέλλοντας, οὗ νῦν παρὰ τὴν κρήνην νεώς ἐστιν αὐτοῖς ἱδρυμένος, ὅθεν καὶ τὴν ἡμέραν ἐπινίκιον οὖσαν, ἐν τῷ Ἰουλίῳ μηνὶ τὰς εἰδούς, Διοσκούροις ἀνιερώκασι.", "st": "Cor. 3.3b"}, {"sp": "N", "t": "νέων δέ, ὡς ἔοικεν, ἀνδρῶν ἐπιφάνεια καὶ τιμὴ τὰς μὲν ἐλαφρῶς φιλοτίμους φύσεις πρωιαίτερον παραγενομένη σβέννυσι, καὶ ἀποπίμπλησι ταχὺ τὸ διψῶδες αὐτῶν καὶ ἁψίκορον τὰ δ’ ἐμβριθῆ καὶ βέβαια φρονήματα αὔξουσιν αἱ τιμαὶ καὶ λαμπρύνουσιν ὥσπερ ὑπὸ πνεύματος ἐγειρόμενα πρὸς τὸ φαινόμενον καλόν, οὐ γὰρ ὡς μισθὸν ἀπολαμβάνοντες, ἀλλ’ ὡς ἐνέχυρον διδόντες αἰσχύνονται τὴν δόξαν καταλιπεῖν καὶ μὴ τοῖς αὐτοῖς ἔργοις ὑπερβαλέσθαι. τοῦτο παθὼν καὶ ὁ Μάρκιος αὐτὸς αὑτῷ ζῆλον ἀνδραγαθίας προὔθηκε, καινός τε ἀεὶ βουλόμενος εἶναι ταῖς πράξεσιν ἀριστείαις ἀριστείας συνῆπτε καὶ λάφυρα λαφύροις ἐπέφερε, καὶ τοῖς προτέροις ἀεὶ τοὺς ὑστέρους ἡγεμόνας εἶχε περὶ τῆς ἐκείνου τιμῆς ἐρίζοντας, καὶ μαρτυρίας ὑπερβαλέσθαι. πολλῶν γέ τοι τότε Ῥωμαίοις ἀγώνων καὶ πολέμων γενομένων, ἐξ οὐδενὸς ἀστεφάνωτος ἦλθεν οὐδ’ ἀγέραστος.", "st": "Cor. 4.1"}, {"sp": "N", "t": "ἦν δὲ τοῖς μὲν ἄλλοις ἡ δόξα τῆς ἀρετῆς τέλος, ἐκείνῳ δὲ τῆς δόξης ἡ τῆς μητρὸς εὐφροσύνη, τὸ γὰρ ἐκείνην ἐπαινούμενον ἀκοῦσαι καὶ στεφανούμενον ἰδεῖν καὶ περιβαλεῖν δακρύουσαν ὑφ’ ἡδονῆς ἐντιμότατον αὑτὸν ἐνόμιζε ποιεῖν καὶ μακαριώτατον. τοῦτο δ’ ἀμέλει καὶ τὸν Ἐπαμεινώνδαν φασὶν ἐξομολογήσασθαι τὸ πάθος, εὐτυχίαν ποιούμενον αὑτοῦ μεγίστην ὅτι τὴν ἐν Λεύκτροις στρατηγίαν αὐτοῦ καὶ νίκην ὁ πατὴρ καὶ ἡ μήτηρ ἔτι ζῶντες ἐπεῖδον. ἀλλ’ ἐκεῖνος μὲν ἀμφοτέρων ἀπέλαυσε τῶν γονέων συνηδομένων καὶ συνευημερούντων, Μάρκιος δὲ τῇ μητρὶ καὶ τὰς τοῦ πατρὸς ὀφείλειν χάριτας οἰόμενος οὐκ ἐνεπίμπλατο τὴν Οὐολουμνίαν εὐφραίνων καὶ τιμῶν, ἀλλὰ καὶ γυναῖκα βουλομένης καὶ δεομένης ἐκείνης, ἔγημε καὶ τὴν οἰκίαν ᾤκει γενομένων παίδων ὁμοῦ μετὰ τῆς μητρός.", "st": "Cor. 4.3"}, {"sp": "N", "t": "ἤδη δὲ καί δόξαν αὐτοῦ καί δύναμιν ἀπὸ τῆς ἀρετῆς ἐν τῇ πόλει μεγάλην ἔχοντος, ἡ βουλὴ τοῖς πλουσίοις ἀμύνουσα πρὸς τὸν δῆμον ἐστασίασε πολλὰ καί δεινὰ πάσχειν ὑπὸ τῶν δανειστῶν δοκοῦντα. τοὺς μὲν γὰρ κεκτημένους μέτρια πάντων ἀφῃροῦντο τῶν ὄντων ἐνεχυρασμοῖς καί πράσεσι, τοὺς δὲ παντελῶς ἀπόρους αὐτοὺς ἀπῆγον καί τὰ σώματα καθείργνυσαν αὐτῶν, ὠτειλὰς ἔχοντα τετρωμένων πολλὰς καί πεπονηκότων ἐν ταῖς ὑπὲρ τῆς πατρίδος στρατείαις, ὧν τὴν τελευταίαν ἐδέξαντο πρὸς Σαβίνους, τῶν τε πλουσιωτάτων ἐπαγγειλαμένων μετριάσειν καί τῆς βουλῆς τὸν ἄρχοντα Μάρκον Οὐαλλέριον ἐγγυήσασθαι ψηφισαμένης. ἐπεὶ δὲ κἀκείνην ἀγωνισαμένοις τὴν μάχην προθύμως καί κρατήσασι τῶν πολεμίων οὐδὲν ἐγίνετο παρὰ τῶν δανειστῶν ἐπιεικές, οὐδ’ ἡ βουλὴ προσεποιεῖτο μεμνῆσθαι τῶν ὡμολογημένων, ἀλλ’ ἀγομένους πάλιν περιεώρα καί ῥυσιαζομένους, θόρυβοι δὲ καί συστάσεις ἦσαν ἐν τῇ πόλει πονηραί, καί τοὺς πολεμίους οὐκ ἔλαθε ταραχωδῶς ἔχων ὁ δῆμος, ἀλλ’ ἐμβαλόντες ἐπυρπόλουν τὴν χώραν, τῶν δ’ ἀρχόντων εἰς τὰ ὅπλα τοὺς ἐν ἡλικίᾳ καλούντων οὐδεὶς ὑπήκουεν, οὕτω διέστησαν αἱ γνῶμαι πάλιν τῶν ἐν τέλει. καί τινες μὲν ᾤοντο δεῖν ὑφίεσθαι τοῖς πένησι καί χαλάσαι τὸ σύντονον ἄγαν καί νόμιμον, ἔνιοι δ’ ἀντέτεινον, ὧν ἦν καὶ Μάρκιος, οὐ τὸ τῶν χρημάτων μέγιστον ἡγούμενος, ἀρχὴν δὲ καί πεῖραν ὕβρεως ὄχλου καὶ θρασύτητος ἐπανισταμένου τοῖς νόμοις, εἰ σωφρονοῦσι, παύειν καί σβεννύειν παρακελευόμενος.", "st": "Cor. 5.1"}, {"sp": "N", "t": "συνιούσης δὲ περὶ τούτων πολλάκις ἐν ὀλίγῳ χρόνῳ τῆς βουλῆς καὶ μηδὲν τέλος ἐκφερούσης, συστάντες οἱ πένητες ἄφνω καὶ παρακαλέσαντες ἀλλήλους ἀπέλιπον τὴν πόλιν, καὶ καταλαβόντες ὄρος ὃ νῦν ἱερὸν καλεῖται, παρὰ τὸν Ἀνίωνα ποταμὸν ἐκαθέζοντο, πράττοντες μὲν οὐδὲν βίαιον οὐδὲ στασιαστικόν, ἐκπεπτωκέναι δὲ τῆς πόλεως ὑπὸ τῶν πλουσίων πάλαι βοῶντες, ἀέρα δὲ καὶ ὕδωρ καὶ τόπον ἐνταφῆναι πανταχοῦ τὴν Ἰταλίαν αὐτοῖς παρέξειν, ὧν πλέον οὐδὲν οἰκοῦσι τὴν Ῥώμην ὑπάρχειν αὐτοῖς, ἀλλ’ ἢ τιτρώσκεσθαι καὶ ἀποθνῄσκειν ὑπὲρ τῶν πλουσίων στρατευομένοις.", "st": "Cor. 6.1"}, {"sp": "N", "t": "ταῦτ’ ἔδεισεν ἡ βουλή, καὶ τοὺς ἐπιεικεῖς μάλιστα καὶ δημοτικοὺς τῶν πρεσβυτέρων ἐξαπέστειλε, προηγόρει δὲ Μενήνιος Ἀγρίππας· καὶ πολλὰ μὲν τοῦ δήμου δεόμενος, πολλὰ δ’ ὑπὲρ τῆς βουλῆς παρρησιαζόμενος τελευτῶντι τῷ λόγῳ περιῆλθεν εἰς σχῆμα μύθου διαμνημονευόμενον. ἔφη γὰρ τοῦ ἀνθρώπου τὰ μέλη πάντα πρὸς τὴν γαστέρα στασιάσαι, καὶ κατηγορεῖν αὑτῆς ὡς μόνης ἀργοῦ καὶ ἀσυμβόλου καθεζομένης ἐν τῷ σώματι, τῶν δ’ ἄλλων εἰς τὰς ἐκείνης ὀρέξεις πόνους τε μεγάλους καὶ λειτουργίας ὑπομενόντων τὴν δὲ γαστέρα τῆς εὐηθείας αὐτῶν καταγελᾶν, ἀγνοούντων ὅτι τὴν τροφὴν ὑπολαμβάνει μὲν εἰς ἑαυτὴν ἅπασαν, ἀναπέμπει δ’ αὖθις ἐξ αὑτῆς καὶ διανέμει τοῖς ἄλλοις. οὕτως οὖν, ἔφη, καὶ τῆς συγκλήτου λόγος ἐστὶν, ὦ πολῖται, πρὸς ὑμᾶς· τὰ γὰρ ἐκεῖ τυγχάνοντα τῆς προσηκούσης ἐπιμελείας καὶ οἰκονομίας βουλεύματα καὶ πράγματα πᾶσιν ὑμῖν ἐπιφέρει καὶ διανέμει τὸ χρήσιμον καὶ ὠφέλιμον.", "st": "Cor. 6.3"}, {"sp": "N", "t": "ἐκ τούτου διηλλάγησαν, αἰτησάμενοι παρὰ τῆς βουλῆς καὶ τυχόντες ἄνδρας αἱρεῖσθαι πέντε προστάτας τῶν δεομένων βοηθείας, τοὺς νῦν δημάρχους καλουμένους, εἵλοντο δὲ πρώτους, οἷς ἐχρήσαντο καὶ τῆς ἀποστάσεως ἡγεμόσι, τοὺς περὶ Βροῦτον Ἰούνιον καὶ Σικίννιον Βέλλουτον. ἐπεὶ δ’ ἡ πόλις εἰς ἓν ἦλθεν, εὐθὺς ἐν τοῖς ὅπλοις ἦσαν οἱ πολλοὶ, καὶ παρεῖχον αὑτοὺς τοῖς ἄρχουσι χρῆσθαι προθύμως ἐπὶ τὸν πόλεμον.", "st": "Cor. 7.1"}, {"sp": "N", "t": "ὁ δὲ Μάρκιος οὔτ’ αὐτὸς ἡδόμενος οἷς ὁ δῆμος ἴσχυεν ἐνδούσης τῆς ἀριστοκρατίας, καὶ τῶν ἄλλων πατρικίων πολλοὺς ὁρῶν τὸ αὐτὸ πεπονθότας, ὅμως παρεκάλει μὴ ἀπολείπεσθαι τῶν δημοτικῶν ἐν τοῖς περὶ τῆς πατρίδος ἀγῶσιν, ἀλλὰ τῇ ἀρετῇ μᾶλλον ἢ τῇ δυνάμει φαίνεσθαι διαφέροντας αὐτῶν.", "st": "Cor. 7.2"}, {"sp": "N", "t": "ἐν δὲ τῷ Οὐολούσκων ἔθνει, πρὸς οὓς ἐπολέμουν, ἡ Κοριολανῶν πόλις ἀξίωμα μέγιστον εἶχε. ταύτην οὖν τοῦ ὑπάτου Κομινίου περιστρατοπεδεύσαντος, οἱ λοιποὶ Οὐολοῦσκοι δείσαντες ἐπὶ τοὺς Ῥωμαίους συνεβοήθουν πανταχόθεν, ὡς πρὸς τῇ πόλει ποιησόμενοι μάχην καὶ διχόθεν ἐπιχειρήσοντες αὐτοῖς. ἐπεὶ δ’ ὁ Κομίνιος διελὼν τὴν δύναμιν αὐτὸς μὲν ἀπήντα τοῖς ἔξωθεν ἐπιοῦσι τῶν Οὐολούσκων, Λάρκιον δὲ Τίτον, ἄνδρα Ῥωμαίων ἐν τοῖς ἀρίστοις, ἐπὶ τῆς πολιορκίας ἀπέλιπε, καταφρονήσαντες οἱ Κοριολανοὶ τῶν παρόντων ἐπεξῆλθον, καὶ προσμαχόμενοι τὸ πρῶτον ἐκράτουν καὶ κατεδίωκον εἰς τὸν χάρακα τοὺς Ῥωμαίους. ἔνθα δὴ Μάρκιος ἐκδραμὼν σὺν ὀλίγοις καὶ καταβαλὼν τοὺς προσμίξαντας αὐτῷ μάλιστα, τοὺς δ’ ἄλλους στήσας ἐπιφερομένους, ἀνεκαλεῖτο μεγάλῃ βοῇ τοὺς Ῥωμαίους, καὶ γὰρ ἦν, ὥσπερ ἠξίου τὸν στρατιώτην ὁ Κάτων, οὐ χειρὶ καὶ πληγῇ μόνον, ἀλλὰ καὶ τόνῳ φωνῆς καὶ ὄψει προσώπου φοβερὸς ἐντυχεῖν πολεμίῳ καὶ δυσυπόστατος. ἀθροιζομένων δὲ πολλῶν καὶ συνισταμένων περὶ αὐτόν ἀπεχώρουν οἱ πολέμιοι δείσαντες. ὁ δ’ οὐκ ἠγάπησεν, ἀλλ’ ἐπηκολούθει καὶ συνήλαυνεν ἤδη προτροπάδην φεύγοντας ἄχρι τῶν πυλῶν. ἐκεῖ δ’ ὁρῶν ἀποτρεπομένους τοῦ διώκειν τοὺς Ῥωμαίους, πολλῶν μὲν ἀπὸ τοῦ τείχους βελῶν προσφερομένων, τὸ δὲ συνεισπεσεῖν τοῖς φεύγουσιν εἰς πόλιν ἀνδρῶν πολεμικῶν γέμουσαν ἐν τοῖς ὅπλοις ὄντων οὐδενὸς εἰς νοῦν ἐμβαλέσθαι τολμῶντος, ὅμως ἐπιστὰς παρεκάλει καὶ παρεθάρρυνεν, ἀνεῷχθαι βοῶν ὑπὸ τῆς τύχης τοῖς διώκουσι μᾶλλον ἢ τοῖς φεύγουσι τὴν πόλιν. οὐ πολλῶν δὲ βουλομένων ἐπακολουθεῖν, ὠσάμενος διὰ τῶν πολεμίων ἐνήλατο ταῖς πύλαις καὶ συνεισέπεσε, μηδενὸς τὸ πρῶτον ἀντισχεῖν μηδ’ ὑποστῆναι τολμήσαντος, ἔπειτα δέ, ὡς κατεῖδον ὀλίγους παντάπασιν ἔνδον ὄντας, συμβοηθούντων καὶ προσμαχομένων, ἀναμεμιγμένος ὁμοῦ φίλοις καὶ πολεμίοις ἄπιστον ἀγῶνα λέγεται καὶ χειρὸς ἔργοις καὶ ποδῶν τάχει καὶ τολμήμασι ψυχῆς ἀγωνιζόμενος ἐν τῇ πόλει, καὶ κρατῶν ἁπάντων πρὸς οὓς ὀρούσειε, τοὺς μὲν ἐξῶσαι πρὸς τὰ ἔσχατα μέρη, τῶν δ’ ἀπειπαμένων καὶ καταβαλόντων τὰ ὅπλα πολλὴν ἄδειαν τῷ Λαρκίῳ παρασχεῖν ἔξωθεν ἐπάγοντι τοὺς Ῥωμαίους.", "st": "Cor. 8.1"}, {"sp": "N", "t": "οὕτω δὲ τῆς πόλεως ἁλούσης καὶ τῶν πλείστων ἐν ἁρπαγαῖς ὄντων καὶ διαφορήσεσι χρημάτων, ὁ Μάρκιος ἠγανάκτει καὶ ἐβόα, δεινὸν ἡγούμενος, τοῦ ὑπάτου καὶ τῶν σὺν ἐκείνῳ πολιτῶν τάχα που συμπεπτωκότων τοῖς πολεμίοις καὶ διαμαχομένων, αὐτοὺς χρηματίζεσθαι περιιόντας ἢ προφάσει χρηματισμοῦ τὸν κίνδυνον ἀποδιδράσκειν. ἐπεὶ δ’ οὐ πολλοὶ προσεῖχον αὐτῷ, τοὺς βουλομένους ἀναλαβὼν ἐβάδιζε τὴν ὁδὸν ᾗ τὸ στράτευμα προκεχωρηκὸς ᾔσθετο, πολλάκις μὲν ἐποτρύνων τοὺς σὺν αὐτῷ καὶ παρακαλῶν μὴ ἐνδιδόναι, πολλάκις δὲ τοῖς θεοῖς εὐχόμενος μὴ ἀπολειφθῆναι τῆς μάχης, ἀλλ’ εἰς καιρὸν ἐλθεῖν ἐν ᾧ συναγωνιεῖται καὶ συγκινδυνεύσει τοῖς πολίταις.", "st": "Cor. 9.1"}, {"sp": "N", "t": "ἦν δὲ τότε τοῖς Ῥωμαίοις ἔθος εἰς τάξιν καθισταμένοις καὶ μέλλουσι τοὺς θυρεοὺς ἀναλαμβάνειν καὶ περιζώννυσθαι τὴν τήβεννον ἅμα καὶ διαθήκας ἀγράφους γίνεσθαι, τριῶν ἢ τεττάρων ἐπακουόντων ὀνομάζοντας τὸν κληρονόμον. ταῦτα δὴ πράττοντας ἤδη τοὺς στρατιώτας Μάρκιος ἐν ὄψει τῶν πολεμίων ὄντων κατελάμβανε, καὶ τὸ μὲν πρῶτον ἐνίους διετάραξεν ὀφθεὶς μετ’ ὀλίγων, αἵματος περίπλεως καὶ ἱδρῶτος ἐπεὶ δὲ προσδραμὼν τῷ ὑπάτῳ περιχαρὴς τὴν δεξιὰν ἐνέβαλε καὶ τῆς πόλεως ἀπήγγειλε τὴν ἅλωσιν, ὁ δὲ Κομίνιος περιεπτύξατο αὐτὸν καὶ κατησπάσατο, τοῖς μὲν πυθομένοις τὸ γεγενημένον κατόρθωμα, τοῖς δ’ εἰκάσασι θάρσος παρέστη, καὶ βοῇ παρεκάλουν ἄγειν καὶ συνάπτειν. ὁ δὲ Μάρκιος ἠρώτησε τὸν Κομίνιον πῶς διακεκόσμηται τὰ τῶν πολεμίων ὅπλα καὶ ποῦ τέτακται τὸ μαχιμώτατον. ἐκείνου δὲ φήσαντος οἴεσθαι τὰς κατὰ μέσον σπείρας Ἀντιατῶν εἶναι, πολεμικωτάτων καὶ μηδενὶ φρονήματος ὑφιεμένων, ἀξιῶ σε τοίνυν, ὁ Μάρκιος ἔφη, καὶ αἰτοῦμαι, κατὰ τούτους τάξον ἡμᾶς τοὺς ἄνδρας. ἔδωκεν οὖν ὁ ὕπατος, θαυμάσας αὐτοῦ τὸ πρόθυμον.", "st": "Cor. 9.2"}, {"sp": "N", "t": "ὡς δ’ ἦσαν ἐμβολαὶ δοράτων, καὶ τοῦ Μαρκίου προεκδραμόντος οὐκ ἀντέσχον οἱ κατὰ στόμα τῶν Οὐολούσκων, ἀλλ’ ᾧ προσέμιξε μέρει τῆς φάλαγγος εὐθὺς διεκέκοπτο, τῶν δ’ ἑκατέρωθεν ἐπιστρεφόντων καὶ περιλαμβανόντων τοῖς ὅπλοις τὸν ἄνδρα, δείσας ὁ ὕπατος τοὺς κρατίστους τῶν περὶ αὑτὸν ἐξέπεμπεν. ἰσχυρᾶς δὲ περὶ τὸν Μάρκιον μάχης γενομένης καὶ πολλῶν ἐν ὀλίγῳ νεκρῶν πεσόντων, ἐγκείμενοι καὶ καταβιαζόμενοι τοὺς πολεμίους ἐώσαντο, καὶ τρεπόμενοι πρὸς δίωξιν αὐτῶν τὸν Μάρκιον ἠξίουν ὑπό τε καμάτου βαρὺν ὄντα καὶ τραυμάτων ἀναχωρεῖν ἐπὶ τὸ στρατόπεδον. εἰπὼν δ’ ἐκεῖνος ὅτι νικώντων οὐκ ἔστι τὸ κάμνειν, ἐφείπετο τοῖς φεύγουσιν. ἡττήθη δὲ καὶ τὸ λοιπὸν στράτευμα, πολλῶν μὲν διαφθαρέντων, πολλῶν δὲ ἁλόντων.", "st": "Cor. 9.5"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ τοῦ Λαρκίου παραγενομένου καὶ τῶν ἄλλων ἀθροιζομένων πρὸς τὸν ὕπατον, ἀναβὰς ἐπὶ τὸ βῆμα, καὶ τοῖς θεοῖς τὴν πρέπουσαν ἀποδοὺς ἐπὶ τηλικούτοις κατορθώμασιν εὐφημίαν, πρὸς τὸν Μάρκιον τρέπεται, καὶ πρῶτον μὲν αὐτοῦ θαυμαστὸν ἔπαινον εἶπε, τῶν μὲν αὐτὸς ἐν τῇ μάχῃ γεγονὼς θεατής, τὰ δὲ τοῦ Λαρκίου μαρτυροῦντος. ἔπειτα, πολλῶν χρημάτων καὶ ἵππων γεγονότων αἰχμαλώτων καὶ ἀνθρώπων, ἐκέλευσεν αὐτὸν ἐξελέσθαι δέκα πάντα πρὸ τοῦ νέμειν τοῖς ἄλλοις, ἄνευ δὲ ἐκείνων ἀριστεῖον αὐτῷ κεκοσμημένον ἵππον ἐδωρήσατο. τῶν δὲ Ῥωμαίων ἐπαινεσάντων ὁ Μάρκιος προελθών τὸν μὲν ἵππον ἔφη δέχεσθαι καὶ χαίρειν τοῖς ἐπαίνοις τοῦ ἄρχοντος, τὰ δὲ ἄλλα μισθόν, οὐ τιμὴν ἡγούμενος ἐᾶν, καὶ ἀγαπήσειν ὡς εἷς ἕκαστος τὴν νέμησιν. ἐξαίρετον δὲ μίαν αἰτοῦμαι χάριν, ἔφη, καὶ δέομαι λαβεῖν. ἦν μοι ξένος ἐν Οὐολούσκοις καὶ φίλος, ἀνὴρ ἐπιεικὴς καὶ μέτριος· οὗτος ἑάλωκε νῦν καὶ γέγονεν ἐκ πλουσίου καὶ μακαρίου δοῦλος, πολλῶν οὖν αὐτῷ κακῶν παρόντων ἓν ἀφελεῖν ἀρκεῖ, τὴν πρᾶσιν.", "st": "Cor. 10.1"}, {"sp": "N", "t": "ἐπὶ τούτοις λεχθεῖσι βοή τε μείζων ἀπήντησε τῷ Μαρκίῳ, καὶ πλείονες οἱ θαυμάζοντες ἐγένοντο τὸ μὴ κρατούμενον ὑπὸ χρημάτων τἀνδρὸς ἢ τὴν ἐν τοῖς πολέμοις ἀνδραγαθίαν. καὶ γὰρ οἷς φθόνου τι καὶ ζήλου πρὸς αὐτὸν ὑπέκειτο τιμώμενον ἐκπρεπῶς, κἀκείνοις τότε τοῦ λαβεῖν μεγάλα τῷ μὴ λαβεῖν ἄξιος ἔδοξε, καὶ μᾶλλον αὐτοῦ τὴν ἀρετὴν ἠγάπησαν, ἀφ’ ἧς κατεφρόνει τηλικούτων, ἢ δι’ ὧν ἠξιοῦτο. τὸ μὲν γὰρ εὖ χρῆσθαι χρήμασι κάλλιόν ἐστιν ἢ ὅπλοις, τοῦ δὲ χρῆσθαι τὸ μὴ δεῖσθαι χρημάτων σεμνότερον.", "st": "Cor. 10.4"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐπαύσατο βοῆς καὶ θορύβου τὸ πλῆθος, ὑπολαβὼν ὁ Κομίνιος, ἀλλ’ ἐκείνας μέν, εἶπεν, ὦ συστρατιῶται, τὰς δωρεὰς οὐ δύνασθε βιάζεσθαι μὴ δεχόμενον τὸν ἄνδρα μηδὲ βουλόμενον λαβεῖν ἣν δὲ οὐκ ἐστιν ἐπὶ τούτῳ διδομένην ἀπώσασθαι, δῶμεν αὐτῷ καὶ ψηφισώμεθα καλεῖσθαι Κοριολανόν, εἰ μὴ καὶ πρὸ ἡμῶν ἡ πρᾶξις αὐτὴ τοῦτο δέδωκεν. ἐκ τούτου τρίτον ἔσχεν ὄνομα τὸν Κοριολανόν.", "st": "Cor. 11.1"}, {"sp": "N", "t": "ωι καὶ μάλιστα δῆλόν ἐστιν ὅτι τῶν ὀνομάτων ἴδιον ἦν ὁ Γάϊος, τὸ δὲ δεύτερον οἰκίας ἢ γένους κοινὸν ὁ Μάρκιος, τῷ δὲ τρίτῳ ὕστερον ἐχρήσαντο πράξεώς τινος ἢ τύχης ἢ ἰδέας ἢ ἀρετῆς ἐπιθέτῳ, καθάπερ Ἕλληνες ἐτίθεντο πράξεώς μὲν ἐπώνυμον τὸν Σωτῆρα καὶ τὸν Καλλίνικον, ἰδέας δὲ τὸν Φύσκωνα καὶ τὸν Γρυπόν, ἀρετῆς δὲ τὸν Εὐεργέτην καὶ τὸν Φιλάδελφον, εὐτυχίας δὲ τὸν Εὐδαίμονα τῷ δευτέρῳ τῶν Βάττων. ἐνίοις δὲ τῶν βασιλέων καὶ σκώμματα παρέσχεν ἐπικλήσεις, ὡς Ἀντιγόνῳ τὸν Δώσωνα καὶ Πτολεμαίῳ τὸν Λάθυρον. ἐπὶ πλέον δὲ τῷ γένει τούτῳ καὶ Ῥωμαῖοι κέχρηνται, Διαδήματόν τινα τῶν Μετέλλων καλέσαντες, ὅτι πολὺν χρόνον ἕλκος ἔχων περιενόστει διαδεδεμένος τὸ μέτωπον, ἕτερον δὲ Κέλερα σπεύσαντα μεθ’ ἡμέρας ὀλίγας τῆς τοῦ πατρὸς τελευτῆς ἐπιταφίους μονομάχων ἀγῶνας παρασχεῖν, τὸ τάχος καὶ τὴν ὀξύτητα τῆς παρασκευῆς θαυμάσαντες. ἐνίους δὲ συντυχίᾳ γενέσεως μέχρι νῦν καλοῦσι, Πρόκλον μέν, ἐὰν ἀποδημοῦντος πατρὸς γένηται, καὶ Πόστουμον, ἂν τεθνηκότος· ᾧ δ’ ἂν διδύμῳ γενομένῳ συμβῇ περιβιῶναι, θατέρου τελευτήσαντος, Οὐοπίσκον. τῶν δὲ σωματικῶν οὐ μόνον Σύλλας οὐδὲ Νίγρους οὐδὲ Ῥούφους, ἀλλὰ καὶ Καίκους καὶ Κλωδίους ἐπωνυμίας τίθενται, καλῶς ἐθίζοντες μήτε τυφλότητα μήτ’ ἄλλην τινὰ σωματικὴν ἀτυχίαν ὄνειδος ἡγεῖσθαι μηδὲ λοιδορίαν, ἀλλ’ ὡς οἰκείοις ὑπακούειν ὀνόμασιν. ἀλλὰ ταῦτα μὲν ἑτέρῳ γένει γραφῆς προσήκει.", "st": "Cor. 11.2"}, {"sp": "N", "t": "παυσαμένῳ δὲ τῷ πολέμῳ τὴν στάσιν ἐπήγειρον αὖθις οἱ δημαγωγοί, καινὴν μὲν οὐδεμίαν αἰτίαν ἔχοντες οὐδ’ ἔγκλημα δίκαιον, ἃ δὲ ταῖς προτέραις αὐτῶν διαφοραῖς καὶ ταραχαῖς ἀναγκαίως ἐπηκολούθησε κακά, ταῦτα ποιούμενοι πρόφασιν ἐπὶ τοὺς πατρικίους, ἄσπορος γὰρ ἡ πλείστη καὶ ἀγεώργητος ἀπελείφθη τῆς χώρας, ἀγορᾶς δ’ ἐπεισάκτου παρασκευὴν διὰ τὸν πόλεμον ὁ καιρὸς οὐκ ἔδωκεν. ἰσχυρᾶς οὖν ἀπορίας γενομένης, ὁρῶντες οἱ δημαγωγοὶ μήτ’ ἀγορὰν ἔχοντα μήτ’, εἰ παρῆν ἀγορά, χρημάτων εὐποροῦντα τὸν δῆμον, ἐνέβαλλον λόγους καὶ διαβολὰς κατὰ τῶν πλουσίων, ὡς ἐκεῖνοι τὸν λιμὸν ἐπάγοιεν αὐτοῖς ὑπὸ μνησικακίας.", "st": "Cor. 12.1"}, {"sp": "N", "t": "ἐκ δὲ τῶν Οὐελιτρανῶν ἧκε πρεσβεία τὴν πόλιν παραδιδόντων καὶ δεομένων ἀποίκους ἀποστέλλειν. νόσος γὰρ ἐμπεσοῦσα λοιμώδης αὐτοῖς τοσοῦτον ὄλεθρον καὶ φθορὰν ἀπειργάσατο τῶν ἀνθρώπων ὥστε μόλις τὸ δέκατον τοῦ παντὸς ἀπολειφθῆναι μέρος. ἔδοξεν οὖν τοῖς νοῦν ἔχουσιν εἰς δέον γεγονέναι καὶ κατὰ καιρὸν ἡ χρεία τῶν Οὐελιτρανῶν διά τε τὴν ἀπορίαν κουφισμοῦ δεομένοις, καὶ τὴν στάσιν ἅμα σκεδάσειν ἤλπιζον, εἰ τὸ θορυβοῦν μάλιστα καὶ συνεπηρμένον τοῖς δημαγωγοῖς ὥσπερ περίττωμα τῆς πόλεως νοσερὸν καὶ ταραχῶδες ἀποκαθαρθείη. τούτους τε δὴ καταλέγοντες εἰς τὴν ἀποικίαν ἐξέπεμπον οἱ ὕπατοι, καὶ στρατείαν ἐπήγγελλον ἑτέροις ἐπὶ τοὺς Οὐολούσκους, ἀσχολίαν τε τῶν ἐμφυλίων μηχανώμενοι θορύβων, καὶ νομίζοντες ἐν ὅπλοις καὶ στρατοπέδῳ καὶ κοινοῖς ἀγῶσιν αὖθις γενομένους πλουσίους ὁμοῦ καὶ πένητας καὶ δημοτικοὺς καὶ πατρικίους, ἡμερώτερον ἂν διατεθῆναι πρὸς ἀλλήλους καὶ ἥδιον.", "st": "Cor. 12.3"}, {"sp": "N", "t": "ἐνίσταντο δὲ λοιπὸν οἱ περὶ Σικίννιον καὶ Βροῦτον δημαγωγοί, βοῶντες ἔργον ὠμότατον αὐτοὺς τῷ πρᾳοτάτῳ τῶν ὀνομάτων ἀποικίαν προσαγορεύσαντας ἀνθρώπους πένητας ὥσπερ εἰς βάραθρον ὠθεῖν, ἐκπέμποντας εἰς πόλιν ἀέρος τε νοσεροῦ καὶ νεκρῶν ἀτάφων γέμουσαν, ἀλλοτρίῳ δαίμονι καὶ παλαμναίῳ συνοικιζομένους· εἶτα ὥσπερ οὐκ ἀρκουμένους τούς μὲν ὑπὸ λιμοῦ διολλύναι τῶν πολιτῶν, τούς δὲ λοιμῷ προσβάλλειν, ἔτι καὶ πόλεμον αὐθαίρετον ἐπάγειν, ὅπως μηδὲν κακὸν ἀπῇ τῆς πόλεως, ὅτι δουλεύουσα τοῖς πλουσίοις ἀπεῖπε. τοιούτων ἀναπιμπλάμενος λόγων ὁ δῆμος οὔτε τῷ καταλόγῳ προσῄει τῶν ὑπάτων πρός τε τὴν ἀποικίαν διεβέβλητο.", "st": "Cor. 13.1"}, {"sp": "N", "t": "τῆς δὲ βουλῆς διαπορουμένης ὁ Μάρκιος, ἤδη μεστὸς ὢν ὄγκου καὶ μέγας γεγονὼς τῷ φρονήματι καὶ θαυμαζόμενος ὑπὸ τῶν κρατίστων, φανερὸς ἦν μάλιστα τοῖς δημαγωγοῖς ἀνθιστάμενος, καὶ τὴν μὲν ἀποικίαν ἀπέστειλαν, ἐπιτιμίοις μεγάλοις τούς λαχόντας ἐξελθεῖν ἀναγκάσαντες· πρός δὲ τὴν στρατείαν παντάπασιν ἀπαγορευόντων, αὐτὸς ὁ Μάρκιος τούς τε πελάτας ἀναλαβὼν καὶ τῶν ἄλλων ὅσους ἔπεισε, κατέδραμε τὴν Ἀντιατῶν χώραν. καὶ πολὺν μὲν σῖτον εὑρών, πολλῇ δὲ λείᾳ θρεμμάτων καὶ ἀνδραπόδων περιτυχών, αὑτῷ μὲν οὐδὲν ἐξείλετο, τούς δὲ στρατευσαμένους πολλὰ μὲν ἄγοντας ἔχων, πολλὰ δὲ φέροντας, ἐπανῆλθεν εἰς τὴν Ῥώμην, ὥστε τούς ἄλλους μεταμελομένους καὶ φθονήσαντας τοῖς εὐπορήσασιν ἄχθεσθαι τῷ Μαρκίῳ καὶ βαρύνεσθαι τὴν δόξαν αὐτοῦ καὶ τὴν δύναμιν, ὡς ἐπὶ τὸν δῆμον αὐξομένην.", "st": "Cor. 13.3"}, {"sp": "N", "t": "ὀλίγου δὲ χρόνου μετῄει μὲν ὑπατείαν ὁ Μάρκιος, ἐκάμπτοντο δὲ οἱ πολλοί, καὶ τὸν δῆμον αἰδώς τις εἶχεν ἄνδρα καὶ γένει καὶ ἀρετῇ πρῶτον ἀτιμάσαι καὶ καταβαλεῖν ἐπὶ τοσούτοις καὶ τηλικούτοις εὐεργετήμασι. καὶ γὰρ ἔθος ἦν τοῖς μετιοῦσι τὴν ἀρχὴν παρακαλεῖν καὶ δεξιοῦσθαι τοὺς πολίτας ἐν ἱματίῳ κατιόντας εἰς τὴν ἀγορὰν ἄνευ χιτῶνος, εἴτε μᾶλλον ἐκταπεινοῦντας ἑαυτοὺς τῷ σχήματι πρὸς τὴν δέησιν, εἴτε δεικνύντας οἷς ἦσαν ὠτειλαί προφανῆ τὰ σύμβολα τῆς ἀνδρείας. οὐ γὰρ ὑποψίᾳ δήπου διανομῆς ἀργυρίου καὶ δεκασμῶν ἄζωστον ἐβούλοντο προσιέναι καὶ ἀχίτωνα τοῖς πολίταις τὸν δεόμενον αὐτῶν ὀψὲ γὰρ μετὰ πολὺν χρόνον ὠνὴ καὶ πρᾶσις ἐπεισῆλθε, καὶ συνεμίγη ταῖς ἐκκλησιαστικαῖς ψήφοις ἀργύριον. ἐκ δὲ τούτου καὶ δικαστῶν θιγοῦσα καὶ στρατοπέδων ἡ δωροδοκία περιέστησεν εἰς μοναρχίαν τὴν πόλιν, ἐξανδραποδισαμένη τὰ ὅπλα τοῖς χρήμασιν. οὐ γὰρ κακῶς ἔοικεν εἰπεῖν ὁ εἰπὼν ὅτι πρῶτος κατέλυσε τὸν δῆμον ὁ πρῶτος ἑστιάσας καὶ δεκάσας. φαίνεται δὲ κρύφα καὶ κατὰ μικρὸν ὑπορρέον οὐκ εὐθὺς ἔκδηλον ἐν Ῥώμῃ γενέσθαι τὸ κακόν. οὐ γὰρ ἴσμεν ὅστις ἦν ὁ δεκάσας πρῶτος ἐν Ῥώμῃ δῆμον ἢ δικαστήριον· Ἀθήνησι δὲ λέγεται πρῶτος ἀργύριον δοῦναι δικασταῖς Ἄνυτος ὁ Ἀνθεμίωνος, προδοσίας περὶ Πύλου κρινόμενος, ἐν τοῖς Πελοποννησιακοῖς ἤδη τελευτῶσιν, ὁπηνίκα τὸ χρυσοῦν ἔτι γένος καὶ ἀκήρατον ἐν Ῥώμῃ τὴν ἀγορὰν κατεῖχεν.", "st": "Cor. 14.1"}, {"sp": "N", "t": "ἀλλὰ τοῦ γε Μαρκίου πολλὰς ὑποφαίνοντος ὠτειλὰς ἀπὸ πολλῶν ἀγώνων, ἐν οἷς ἐπρώτευσεν ἑπτακαίδεκα ἔτη συνεχῶς στρατευόμενος, ἐδυσωποῦντο τὴν ἀρετὴν, καὶ λόγον ἀλλήλοις ἐδίδοσαν ὡς ἐκεῖνον ἀποδείξοντες. ἐπεὶ δέ, τῆς ἡμέρας ἐν ᾗ τὴν ψῆφον ἔδει φέρειν ἐνστάσης, ὁ Μάρκιος εἰς ἀγορὰν ἐνέβαλε σοβαρῶς ὑπὸ τῆς βουλῆς προπεμπόμενος, καὶ πάντες οἱ πατρίκιοι περὶ αὐτὸν ἐγένοντο φανεροὶ πρὸς μηδέν’ οὕτω μηδέποτε σπουδάσαντες, ἐξέπεσον αὖθις οἱ πολλοὶ τῆς πρὸς αὐτὸν εὐνοίας, εἰς τὸ νεμεσᾶν καὶ φθονεῖν ὑποφερόμενοι. προσῆν δὲ τῷ πάθει τούτῳ καὶ δέος, εἰ γένοιτο τῆς ἀρχῆς κύριος ἀνὴρ ἀριστοκρατικὸς καὶ τοσοῦτον ἔχων ἐν τοῖς πατρικίοις ἀξίωμα, μὴ παντάπασιν ἀφέλοιτο τοῦ δήμου τὴν ἐλευθερίαν.", "st": "Cor. 15.1"}, {"sp": "N", "t": "οὕτω δὴ φρονήσαντες ἀπεψηφίσαντο τὸν Μάρκιον, ὡς δ’ ἀνηγορεύθησαν ἕτεροι, βαρέως μὲν ἤνεγκεν ἡ βουλή δοκοῦσα προπεπηλακίσθαι μᾶλλον ἑαυτὴν ἢ τὸν Μάρκιον, αὐτὸς δ’ ἐκεῖνος οὐ μετρίως ἔσχεν οὐδ’ ἐπιεικῶς πρὸς τὸ συμβεβηκός, ἅτε δὴ πλεῖστα τῷ θυμοειδεῖ καὶ φιλονείκῳ μέρει τῆς ψυχῆς, ὡς ἔχοντι μέγεθος καὶ φρόνημα, κεχρημένος, τὸ δ’ ἐμβριθὲς καὶ τὸ πρᾷον, οὗ τὸ πλεῖστον ἀρετῇ πολιτικῇ μέτεστιν, ἐγκεκραμένον οὐκ ἔχων ὑπὸ λόγου καὶ παιδείας, οὐδὲ τὴν ἐρημίᾳ ξύνοικον, ὡς Πλάτων ἔλεγεν, αὐθάδειαν εἰδὼς ὅτι δεῖ μάλιστα διαφεύγειν ἐπιχειροῦντα πράγμασι κοινοῖς καὶ ἀνθρώποις ὁμιλεῖν, καὶ γενέσθαι τῆς πολλὰ γελωμένης ὑπ’ ἐνίων ἀνεξικακίας ἐραστήν. ἀλλ’ ἁπλοῦς τις ὢν ἀεὶ καὶ ἀτενής, καὶ τὸ νικᾶν καὶ κρατεῖν ἁπάντων πάντως ἀνδρείας ἔργον ἡγούμενος, οὐκ ἀσθενείας καὶ μαλακίας, ἐκ τοῦ πονοῦντος καὶ πεπονθότος μάλιστα τῆς ψυχῆς, ὥσπερ οἴδημα, τὸν θυμὸν ἀναδιδούσης, ἀπῄει ταραχῆς μεστὸς ὢν καὶ πικρίας πρὸς τὸν δῆμον. οἱ δ’ ἐν ἡλικίᾳ τῶν πατρικίων, ὅ τι περ ἦν ἐν τῇ πόλει μάλιστα γαυρούμενον εὐγενείᾳ καὶ ἀνθοῦν, ἀεί τε θαυμαστῶς ἐσπουδάκεσαν περὶ τὸν ἄνδρα, καὶ τότε προσκείμενοι καὶ παρόντες οὐκ ἐπ’ ἀγαθῷ τὸν θυμὸν ἐξερρίπιζον αὐτοῦ τῷ συναγανακτεῖν καὶ συναλγεῖν. ἦν γὰρ ἡγεμὼν αὐτοῖς καὶ διδάσκαλος εὐμενὴς τῶν πολεμικῶν ἐν ταῖς στρατείαις, καὶ ζῆλον ἀρετῆς ἄνευ φθόνου πρὸς ἀλλήλους γαυρῶσαι τοὺς κατορθοῦντας.", "st": "Cor. 15.3"}, {"sp": "N", "t": "ἐν τούτῳ δὲ σῖτος ἧκεν εἰς Ῥώμην, πολὺς μέν ὠνητὸς ἐξ Ἰταλίας, οὐκ ἐλάττων δὲ δωρητὸς ἐκ Συρακουσῶν, Γέλωνος τοῦ τυράννου πέμψαντος· ὥστε τοὺς πλείστους ἐν ἐλπίσι γενέσθαι χρησταῖς, ἅμα τῆς ἀπορίας καὶ τῆς διαφορᾶς τὴν πόλιν ἀπαλλαγήσεσθαι προσδοκῶντας, εὐθὺς οὖν βουλῆς ἀθροισθείσης περιχυθεὶς ὁ δῆμος ἔξωθεν ἐκαραδόκει τό τέλος, ἐλπίζων ἀγορᾷ τε χρήσεσθαι φιλανθρώπῳ καὶ προῖκα τὰς δωρεὰς νεμήσεσθαι. καὶ γὰρ ἔνδον ἦσαν οἱ ταῦτα τὴν βουλὴν πείθοντες. ὁ μέντοι Μάρκιος ἀναστὰς σφόδρα καθήψατο τῶν χαριζομένων τοῖς πολλοῖς, δημαγωγοὺς καὶ προδότας ἀποκαλῶν τῆς ἀριστοκρατίας καὶ σπέρματα πονηρὰ θρασύτητος καὶ ὕβρεως εἰς ὄχλον ἀφειμένα τρέφοντας καθ’ αὑτῶν, ἃ καλῶς μέν εἶχε μὴ περιιδεῖν ἐν ἀρχῇ φυόμενα μηδ’ ἰσχυρὸν ἀρχῇ τηλικαύτῃ ποιῆσαι τὸν δῆμον, ἤδη δὲ καὶ φοβερὸν εἶναι τῷ πάντα βουλομένοις αὐτοῖς ὑπάρχειν καὶ μηδὲν ἄκοντας βιάζεσθαι, μηδὲ πείθεσθαι τοῖς ὑπάτοις, ἀλλ’ ἀναρχίας ἔχοντας ἡγεμόνας ἰδίους ἄρχοντας προσαγορεύειν. ἐπιδόσεις μέν οὖν καὶ διανομάς, ὥσπερ Ἑλλήνων οἱ κράτιστα δημοκρατούμενοι, καθέζεσθαι ψηφιζομένους ἔφη παντελῶς εἰς κοινὸν ὄλεθρον τὴν ἀπείθειαν αὑτῶν ἐφοδιάζειν. οὐ γὰρ χάριν γε δήπου φήσουσιν ἀπολαμβάνειν τῶν στρατειῶν ἃς ἐγκατέλιπον, καὶ τῶν ἀποστάσεων αἷς προήκαντο τὴν πατρίδα, καὶ τῶν διαβολῶν ἃς ἐδέξαντο κατὰ τῆς βουλῆς· ἀλλ’ ὑφιεμένους διὰ φόβον καὶ κολακεύοντας ὑμᾶς ταῦτα διδόναι καὶ συγχωρεῖν ἐλπίσαντες, οὐδὲν ἕξουσι πέρας ἀπειθείας, οὐδὲ παύσονται διαφερόμενοι καὶ στασιάζοντες. ὥστε τοῦτο μέν ἐστι κομιδῇ μανικόν· εἰ δὲ σωφρονοῦμεν, ἀφαιρησόμεθα τὴν δημαρχίαν αὑτῶν, ἀναίρεσιν οὖσαν ὑπατείας καὶ διάστασιν τῆς πόλεως, οὐκέτι μιᾶς, ὡς πρότερον, οὔσης, ἀλλὰ δεδεγμένης τομήν μηδέποτε συμφῦναι μηδ’ ὁμοφρονῆσαι μηδὲ παύσασθαι νοσοῦντας ἡμᾶς καὶ ταραττομένους ὑπ’ ἀλλήλων ἐάσουσαν.", "st": "Cor. 16.1"}, {"sp": "N", "t": "πολλὰ τοιαῦτα λέγων ὁ Μάρκιος ὑπερφυῶς εἶχε τοὺς νέους συνενθουσιῶντας αὐτῷ καὶ τοὺς πλουσίους ὀλίγου δεῖν ἅπαντας, μόνον ἐκεῖνον ἄνδρα τὴν πόλιν ἔχειν ἀήττητον καὶ ἀκολάκευτον βοῶντας, ἔνιοι δὲ τῶν πρεσβυτέρων ἠναντιοῦντο, ὑφορώμενοι τὸ ἀποβησόμενον. ἀπέβη δὲ χρηστὸν οὐδέν. οἱ γὰρ δήμαρχοι παρόντες, ὡς ᾔσθοντο τῇ γνώμῃ κρατοῦντα τὸν Μάρκιον, ἐξέδραμον εἰς τὸν ὄχλον μετὰ βοῆς παρακελευόμενοι συνίστασθαι καὶ βοηθεῖν αὐτοῖς τοὺς πολλούς. ἐκκλησίας δὲ θορυβώδους γενομένης, καὶ τῶν λόγων οὓς ὁ Μάρκιος εἶπεν ἀναγορευθέντων, ὀλίγον ἐδέησεν ἐμπεσεῖν ὑπ’ ὀργῆς φερόμενος εἰς τὴν βουλὴν ὁ δῆμος· οἱ δὲ δήμαρχοι τοῦ Μαρκίου τὴν αἰτίαν ἐποιοῦντο, καὶ πέμποντες ἐκάλουν αὐτὸν ἀπολογησόμενον. ὡς δὲ πρὸς ὕβριν τοὺς πεμφθέντας ἐξήλασεν ὑπηρέτας, αὐτοὶ μετὰ τῶν ἀγορανόμων ἧκον ἄξοντες βίᾳ τὸν ἄνδρα, καὶ τοῦ σώματος ἐπελαμβάνοντο. συστάντες δ’ οἱ πατρίκιοι τοὺς μὲν δημάρχους ἀπετρίψαντο, τοῖς δ’ ἀγορανόμοις καὶ πληγὰς ἐνέβαλον.", "st": "Cor. 17.1"}, {"sp": "N", "t": "τότε μὲν οὖν ἑσπέρα καταλαβοῦσα τὴν ταραχὴν διέλυσεν· ἅμα δὲ’ ἡμέρᾳ τὸν δῆμον ἐξηγριωμένον ὁρῶντες οἱ ὕπατοι καὶ συντρέχοντα πανταχόθεν εἰς τὴν ἀγοράν ἔδεισαν ὑπὲρ τῆς πόλεως, καὶ τὴν βουλὴν ἀθροίσαντες ἐκέλευον σκοπεῖν ὅπως ἐπιεικέσι λόγοις καὶ δόγμασι χρηστοῖς πραΰνωσι καὶ καταστήσωσι τοὺς πολλούς, ὡς οὐ φιλοτιμίας οὖσαν ὥραν, οὐδ’ ὑπὲρ δόξης ἅμιλλαν, εἰ σωφρονοῦσιν, ἀλλὰ καιρὸν ἐπισφαλῆ καὶ ὀξὺν, εὐγνώμονος πολιτείας καὶ φιλανθρώπου δεόμενον. εἰξάντων δὲ τῶν πλείστων προελθόντες ὡς ἐνῆν μάλιστα τῷ δήμῳ διελέγοντο καὶ κατεπράϋνον, ἀπολυόμενοί τε τὰς διαβολὰς ἐπιεικῶς καὶ τῷ νουθετοῦντι καὶ δάκνοντι μετρίως χρώμενοι, περὶ δὲ τιμῆς ὠνίων καὶ ἀγορᾶς οὐδὲν διοίσεσθαι πρὸς αὐτοὺς φάσκοντες.", "st": "Cor. 17.3"}, {"sp": "N", "t": "ὡς οὖν ἐνεδίδου τὸ πολὺ τοῦ δήμου καὶ φανερὸν ἦν τῷ κοσμίως καὶ σωφρόνως ἀκούειν ἀγόμενον καὶ κηλούμενον, ἀνέστησαν οἱ δήμαρχοι, τῇ μὲν βουλῇ σωφρονούσῃ τὸν δῆμον ἀνθυπείξειν ὅσα καλῶς ἔχει φάσκοντες, τὸν δὲ Μάρκιον ἀπολογεῖσθαι κελεύοντες, εἰ μή φησιν ἐπὶ συγχύσει τῆς πολιτείας καὶ καταλύσει τοῦ δήμου τήν τε βουλὴν παροξύνειν καὶ καλούμενος ὑπ’ αὐτῶν ἀπειθῆσαι, τέλος δὲ τοὺς ἀγορανόμους τύπτων ἐν ἀγορᾷ καὶ προπηλακίζων ἐμφύλιον, ὅσον ἐπ’ αὐτῷ, πόλεμον ἐξεργάσασθαι καὶ προαγαγεῖν εἰς ὅπλα τοὺς πολίτας. ἔλεγον δὲ ταῦτα βουλόμενοι τὸν Μάρκιον ἢ ταπεινὸν ἀποδεῖξαι, παρὰ φύσιν ὑφέντα τὸ φρόνημα καὶ θεραπεύοντα τὸν δῆμον, τῇ φύσει χρώμενον ἀνήκεστον ἀπεργάσασθαι τὴν πρὸς αὑτὸν ὀργήν ὃ μᾶλλον ἤλπιζον, ὀρθῶς στοχαζόμενοι τοῦ ἀνδρός.", "st": "Cor. 18.1"}, {"sp": "N", "t": "ἔστη μὲν γὰρ ὡς ἀπολογησόμενος, καὶ παρέσχεν αὐτῷ σιωπὴν καὶ ἡσυχίαν ὁ δῆμος· ὡς δ’ ἤρξατο πρὸς τοὺς ἀνθρώπους δεητικόν τινα λόγον προσδεχομένους οὐ μόνον ἐπαχθεῖ παρρησίᾳ χρῆσθαι καὶ πλείονι κατηγορίᾳ τῆς παρρησίας, ἀλλὰ καὶ τόνῳ φωνῆς καὶ διαθέσει προσώπου τήν ἐγγὺς ὑπεροψίας καὶ ὀλιγωρίας ἀφοβίαν ἐπιδεικνύμενος, ὁ μὲν δῆμος ἐξετραχύνθη καὶ φανερὸς ἦν δυσανασχετῶν καὶ βαρυνόμενος τοῖς λεγομένοις, τῶν δὲ δημάρχων ὁ θρασύτατος Σικίννιος μικρὰ τοῖς συνάρχουσι διαλεχθείς, εἶτ’ εἰς μέσον ἀναγορεύσας ὡς θάνατος ὑπὸ τῶν δημάρχων τοῦ Μαρκίου κατέγνωσται, προσέταξε τοῖς ἀγορανόμοις ἀναγαγόντας αὐτὸν ἐπὶ τήν ἄκραν εὐθὺς ὦσαι κατὰ τῆς ὑποκειμένης φάραγγος. ἁπτομένων δὲ τῶν ἀγορανόμων τοῦ σώματος ἔδοξε μὲν καὶ τῶν δημοτῶν πολλοῖς φρικτὸν εἶναι τὸ γιγνόμενον καὶ ὑπερήφανον, οἱ δὲ πατρίκιοι παντάπασιν ἐκστάντες καὶ περιπαθήσαντες ὥρμησαν ἀπὸ κραυγῆς βοηθεῖν, οἱ δὲ καὶ χερσὶ τοὺς ἐπιλαμβανομένους ἀνείργοντες καὶ καταμιγνύντες ἑαυτοῖς τὸν Μάρκιον· ἔνιοι δὲ καὶ τὰς χεῖρας ὀρέγοντες ἐδέοντο τῶν πολλῶν, ἐπειδὴ λόγου τε καὶ φωνῆς οὐδὲν ἔργον ἦν ἐν ἀκοσμίᾳ τοσαύτῃ καὶ θορύβοις, ἄχρι οὗ συμφρονήσαντες οἱ φίλοι καὶ οἰκεῖοι τῶν δημάρχων ὡς ἄνευ φόνου πολλοῦ τῶν πατρικίων οὐκ ἔστιν ἐξαγαγεῖν οὐδὲ κολάσαι τὸν Μάρκιον, ἔπεισαν αὐτοὺς ἀφελεῖν τῆς τιμωρίας τὸ ἀλλόκοτον καὶ βαρύ, μὴ βίᾳ μηδ’ ἄκριτον ἀποκτιννύντας, ἀλλὰ τῷ δήμῳ ψῆφον ἐπενεγκεῖν ἀποδόντας. ἐκ τούτου καταστὰς ὁ Σικίννιος ἠρώτα τοὺς πατρικίους τί βουλόμενοι τὸν Μάρκιον ἀφαιροῦνται τοῦ δήμου βουλομένου κολάζειν. ἐκείνων δὲ πάλιν ἀντερωτώντων τί μὲν οὖν διανοεῖσθε καὶ τί βούλεσθε ὑμεῖς, ἄνδρα Ῥωμαίων ἐν τοῖς ἀρίστοις ἄνευ κρίσεως ἐπὶ τιμωρίαν ὠμὴν καὶ παράνομον οὕτως ἄγοντες; ἀλλὰ ταύτην μέν. εἶπεν ὁ Σικίννιος, ὑμεῖς μὴ ποιεῖσθε πρόφασιν διαφορᾶς καὶ στάσεως πρὸς τὸν δῆμον ὃ γὰρ ἀξιοῦτε, δίδωσιν ὑμῖν, κριθῆναι τὸν ἄνδρα, σοὶ δέ, Μάρκιε, προαγορεύομεν εἰς τρίτην ἀγορὰν παρεῖναι καὶ πείθειν τοὺς πολίτας, εἰ μηδὲν ἀδικεῖς, ὡς ψήφῳ κρινοῦντας.", "st": "Cor. 18.3"}, {"sp": "N", "t": "τότε μὲν οὖν ἠγάπησαν οἱ πατρίκιοι τήν διάλυσιν, καὶ τόν Μάρκιον ἀσμένως ἔχοντες ἀπῆλθον. ἐν δὲ τῷ μεταξὺ χρόνῳ τῆς τρίτης ἀγορᾶς (ἀγορᾶς δὲ ποιοῦσι Ῥωμαῖοι δι’ ἡμέρας ἐνάτης, νουνδίνας καλοῦντες) ἐλπίδα μὲν αὐτοῖς παρέσχε διακρούσεως στρατεία γενομένη πρὸς Ἀντιάτας, ὡς μῆκος ἕξουσα καὶ χρόνον ἐν ᾧ χειροήθης ὁ δῆμος ἔσται, τῆς ὀργῆς ἀπομαρανθείσης ἢ παντελῶς ἐκπεσούσης δι’ ἀσχολίαν καὶ πόλεμον· ἔπειτα δέ, ὡς ταχὺ διαλυσάμενοι πρὸς τοὺς Ἀντιάτας ἐπανῆλθον, ἐγίνοντο σύνοδοι τῶν πατρικίων πολλάκις, δεδιότων καὶ σκοπούντων ὅπως τόν τε Μάρκιον οὐ προήσονται τόν τε δῆμον αὖθις οὐ παρέξουσιν ἐκταράττειν τοῖς δημαγωγοῖς Ἄππιος μὲν οὖν Κλαύδιος αἰτίαν ἔχων ἐν τοῖς μάλιστα μισόδημος εἶναι διεμαρτύρετο, λέγων τήν τε βουλὴν αὐτοὺς ἀναιρήσειν καὶ προήσεσθαι παντάπασι τήν πολιτείαν, εἰ κύριον τῆς ψήφου κατὰ τῶν πατρικίων δέξονται γενόμενον τόν δῆμον· οἱ δὲ πρεσβύτατοι καὶ δημοτικώτατοι τοὐναντίον ἠξίουν οὐ χαλεπὸν οὐδὲ βαρύν, ἀλλὰ πρᾷον καὶ φιλάνθρωπον ὑπὸ τῆς ἐξουσίας ἔσεσθαι τόν δῆμον· οὐ γὰρ καταφρονοῦντι τῆς βουλῆς, ἀλλ’ οἰομένῳ καταφρονεῖσθαι τιμὴν καὶ παραμυθίαν γενήσεσθαι τήν κρίσιν, ὥσθ’ ἅμα τήν ψῆφον λαβόντας ἀποθήσεσθαι τήν ὀργήν.", "st": "Cor. 19.1"}, {"sp": "N", "t": "ὁρῶν οὖν ὁ Μάρκιος εὐνοίᾳ μὲν αὐτοῦ, φόβῳ δὲ τοῦ δήμου τὴν σύγκλητον ἀπορουμένην, ἠρώτησε τοὺς δημάρχους τί κατηγοροῦσιν αὑτοῦ καὶ περί τίνος κριθησόμενον ἐπὶ τὸν δῆμον ἐξάγουσιν. εἰπόντων δ’ ἐκείνων ὅτι τυραννίς ἐστὶ τὸ ἔγκλημα καὶ τυραννεῖν διανοούμενον ἀποδείξουσιν αὐτόν, οὕτως ἐξαναστὰς αὐτὸς ἔφη πρὸς τὸν δῆμον ἤδη βαδίζειν ἀπολογησόμενος καὶ μηδένα τρόπον κρίσεως μηδέ, ἂν ἁλῷ, κολάσεως παραιτεῖσθαι· μόνον ὅπως, ἔφη, τοῦτο κατηγορήσητε καὶ μὴ ψεύσησθε τὴν βουλήν. ὡς δ’ ὡμολόγησαν, ἐπὶ τούτοις ἡ κρίσις ἐγίνετο.", "st": "Cor. 20.1"}, {"sp": "N", "t": "συνελθόντος δὲ τοῦ δῆμον πρῶτον μὲν οὐ κατὰ λόχους, ἀλλὰ κατὰ φυλὰς ἐβιάζοντο γίνεσθαι τὴν ψηφοφορίαν, τῶν εὐπόρων καὶ γνωρίμων καὶ στρατευομένων τὸν ἄπορον καὶ πολυπράγμονα καὶ τὸν καλοῦ φροντίζοντα μηδὲν ὄχλον ἐπίπροσθεν ταῖς ψήφοις ποιοῦντες. ἔπειτα τὴν τυραννίδος ἀφέντες αἰτίαν ἀναπόδεικτον οὖσαν, ἐκείνων πάλιν ἐμέμνηντο τῶν λόγων οὓς ὁ Μάρκιος πρότερον εἶπεν ἐν τῇ βουλῇ, κωλύων μὲν ἐπευωνίσαι τὴν ἀγοράν, ἀφελέσθαι δὲ τὴν δημαρχίαν τοῦ δῆμον κελεύων. καινὸν δὲ κατηγόρησαν αὑτοῦ κατηγόρημα τὴν διανομὴν τῶν λαφύρων, ἃ λαβὼν ἐκ τῆς Ἀντιατῶν χώρας οὐκ ἀνήνεγκεν εἰς τὸ δημόσιον, ἀλλὰ διένειμε τοῖς μεθ’ αὑτοῦ στρατευομένοις· ὑφ’ οὗ δὴ καὶ μάλιστα λέγεται διαταραχθῆναι τὸν Μάρκιον. οὐ γὰρ προσεδόκησεν οὐδ’ εὐπόρησε πρὸς τὸν ὄχλον ἐκ τοῦ παραυτίκα λόγων πιθανῶν, ἀλλ’ ἐπαινοῦντι τοὺς στρατευσαμένους ἐθορύβησαν αὐτῷ πλείονες ὄντες οἱ μὴ στρατευσάμενοι. τέλος δ’ οὖν ταῖς φυλαῖς τῆς ψήφου δοθείσης αἱ καθαιροῦσαι τρεῖς ἐγένοντο. ἦν δὲ τίμημα τῆς καταδίκης ἀίδιος φυγή. μετὰ δὲ τὴν ἀναγόρευσιν ὁ μὲν δῆμος οὐδέποτε νικήσας μάχῃ πολεμίους τοσοῦτον ἐφρόνησεν ὅσον τότε φρονῶν καὶ γεγηθὼς ἀπῄει, τὴν δὲ βουλὴν ἄχος ἔσχε καὶ κατήφεια δεινή, μεταμελομένην καὶ δυσφοροῦσαν ἐπὶ τῷ μὴ πάντα ποιῆσαι καὶ παθεῖν πρότερον ἢ περιιδεῖν ὑβρίσαντα καὶ χρησάμενον ἐξουσίᾳ τοσαύτῃ τὸν δῆμον. οὐδὲν δ’ ἔδει τότε πρὸς διάγνωσιν ἐσθῆτος ἢ παρασήμων ἑτέρων, ἀλλ’ εὐθὺς ἦν δῆλος ὅτι δημότης ὁ χαίρων καὶ ὁ δυσφορῶν ὅτι πατρίκιος.", "st": "Cor. 20.2"}, {"sp": "N", "t": "πλὴν αὐτὸς ὁ Μάρκιος, ἀνέκπληκτος καὶ ἀταπείνωτος, καὶ σχήματι καὶ βαδίσματι καὶ προσώπῳ καθεστηκὼς, ἐν πᾶσι τοῖς ἄλλοις ἐφαίνετο πεπονθόσιν ἀσυμπαθὴς ἑαυτῷ μόνος, οὐχ ὑπὸ λογισμοῦ καὶ πρᾳότητος, οὐδὲ τῷ φέρειν μετρίως τὸ συμβεβηκός, ἀλλ’ ἐμπαθὴς ὢν ὑπ’ ὀργῆς καὶ βαρυφροσύνης, ὅπερ ἀγνοοῦσιν οἱ πολλοὶ λύπην οὖσαν. ὅταν γὰρ εἰς θυμὸν μεταβάλῃ, καθάπερ ἐκπυρωθεῖσα τὸ ταπεινὸν ἀποβάλλει καὶ ἀργόν· ᾗ καὶ δοκεῖ δραστικὸς ὁ θυμούμενος ὡς θερμὸς ὁ πυρέττων, οἷον ἐν σφυγμῷ καὶ διατάσει καὶ ὄγκῳ γενομένης τῆς ψυχῆς, Ἐδήλωσε δὲ τοῖς ἔργοις αὐτίκα μάλα τὴν διάθεσιν ταύτην ὁ Μάρκιος.", "st": "Cor. 21.1"}, {"sp": "N", "t": "εἰσελθὼν γὰρ οἴκαδε, καὶ τὴν μητέρα καὶ τὴν γυναῖκα μετὰ κλαυθμοῦ καὶ βοῆς ὀλοφυρομένας ἀσπασάμενος καὶ κελεύσας μετρίως φέρειν τὸ συμβεβηκός, εὐθὺς ἀπιὼν ἐβάδιζεν ἐπὶ τὰς πύλας. ἐκεῖ δὲ τῶν πατρικίων ὁμοῦ πάντων προπεμπόντων αὐτὸν οὔτε τι λαβὼν οὔτε τινὸς δεηθεὶς ἀπηλλάττετο, τρεῖς ἢ τέτταρας πελάτας ἔχων περὶ αὑτόν. ἡμέρας δ’ ὀλίγας ἔν τισιν ἀγροῖς αὐτὸς καθ’ ἑαυτὸν ὑπὸ πολλῶν διενεχθεὶς διαλογισμῶν, οἵους ὁ θυμὸς ὑπέβαλλεν, ὥστ’ οὔτ’ εἰς καλὸν οὔτε συμφέρον οὐδὲν, ἀλλ’ ἢ τὸ Ῥωμαίους μετελθεῖν, ἐγίνωσκε πόλεμόν τινα βαρὺν καὶ ὅμορον ἀναστῆσαι ἐπ’ αὐτούς, ὥρμησεν οὖν διαπειρᾶσθαι πρῶτον Οὐολούσκων, ἀκμάζοντας μὲν εἰδὼς ἔτι καὶ σώμασι καὶ χρήμασι, ταῖς δὲ γεγενημέναις ἔναγχος ἥτταις οὐ τοσοῦτον ἀπολωλέναι τῆς δυνάμεως ὅσον ἐγγεγονέναι φιλονεικίας αὐτοῖς καὶ ὀργῆς οἰόμενος.", "st": "Cor. 21.3"}, {"sp": "N", "t": "ἦν δέ τις ἀνὴρ ἐξ Ἀντίου πόλεως διά τε πλοῦτον καὶ ἀνδρείαν καὶ γένους ἐπιφάνειαν ἀξίωμα βασιλικὸν ἔχων ἐν πᾶσιν Οὐολούσκοις, ὄνομα Τύλλος Ἀμφίδιος. ὑπὸ τούτου μισούμενον Μάρκιος ἑαυτὸν ὡς οὐδένα Ῥωμαίων ἐγίνωσκε· πολλάκις γὰρ ἐν ἀπειλαῖς καὶ προκλήσεσι κατὰ τὰς μάχας γενόμενοι, καὶ κομπάσαντες διά τὸ ἐνάμιλλον οἷα νεανιῶν πολεμικῶν φιλοτιμίαι καὶ ζῆλοι φέρουσιν, ἴδιον προσεκτήσαντο τῷ κοινῷ τὸ κατ’ ἀλλήλων ἔχθος. οὐ μὴν ἀλλὰ μέγεθός τι φρονήματος ἔχοντα τὸν Τύλλον ὁρῶν, καὶ μάλιστα δὴ Οὐολούσκων ἐπιθυμοῦντα Ῥωμαίους λαβὴν παρασχόντας ἐν μέρει κολοῦσαι, μαρτυρίαν ἀπέλιπε τῷ εἰπόντι· θυμῷ μάχεσθαι χαλεπόν ὃ γὰρ ἂν θέλῃ, ψυχῆς ὠνεῖται. λαβὼν γὰρ ἐσθῆτα καὶ σκευὴν ἐν ᾗ μάλιστα μὴ δόξειν ὃς ἦν ἔμελλεν ὁρώμενος, ὥσπερ Ὀδυσσεὺς,", "st": "Cor. 22.1"}, {"sp": "N", "t": "ἀνδρῶν δυσμενέων κατέδυ πόλιν.", "st": "Cor. 22.1b"}, {"sp": "N", "t": "ἦν δ’ ἑσπέρα, καὶ πολλοὶ μὲν αὐτῷ προσετύγχανον, ἐγνώριζε δ’ οὐδείς. ἐβάδιζεν οὖν ἐπὶ τὴν οἰκίαν τοῦ Τύλλου, καὶ παρεισελθὼν ἄφνω πρὸς τὴν ἑστίαν ἐκάθισε σιωπῇ, καὶ τὴν κεφαλὴν ἐγκαλυψάμενος ἡσυχίαν ἦγεν. οἱ δὲ κατὰ τὴν οἰκίαν θαυμάσαντες ἀναστῆσαι μὲν οὐκ ἐτόλμησαν ἦν γάρ τι καὶ περὶ αὐτὸν ἀξίωμα καὶ τοῦ σχήματος καὶ τῆς σιωπῆς, ἔφρασαν δὲ τῷ Τύλλῳ περὶ δεῖπνον ὄντι τὴν ἀτοπίαν τοῦ πράγματος. ὁ δ’ ἐξαναστὰς ἧκε πρὸς αὐτὸν, καὶ ἀνέκρινε τίς ὢν ἀφῖκται καὶ τίνων δεόμενος. οὕτως οὖν ὁ Μάρκιος ἀποκαλυψάμενος καὶ μικρὸν ἀνασχών, εἰ μήπω με γινώσκεις, ὦ Τύλλε, εἶπεν, ἀλλ’ ὁρῶν ἀπιστεῖς, ἀνάγκη με κατήγορον ἐμαυτοῦ γενέσθαι. γάιός εἰμι Μάρκιος, ὁ πλεῖστα σὲ καὶ Οὐολούσκους ἐργασάμενος κακά, καὶ τὴν οὐκ ἐῶσαν ἀρνεῖσθαι ταῦτα περιφέρων προσηγορίαν τὸν Κοριολανόν. οὐδὲν γὰρ ἄλλο τῶν πολλῶν πόνων καὶ κινδύνων ἐκείνων ἐκτησάμην ἔπαθλον ἢ τὸ παράσημον ὄνομα τῆς πρὸς ὑμᾶς ἔχθρας, καὶ τοῦτό μοι περίεστιν ἀναφαίρετον τὰ δ’ ἄλλα ὁμοῦ πάντα φθόνῳ δήμου καὶ ὕβρει, μαλακίᾳ δὲ καὶ προδοσίᾳ τῶν ἐν τέλει καὶ ἰσοτίμων ἀπεστέρημαι, καὶ φυγὰς ἐλήλαμαι, καὶ γέγονα τῆς ἑστίας τῆς σῆς ἱκέτης, οὐχ ὑπὲρ ἀδείας καὶ σωτηρίας τί γὰρ ἔδει με δεῦρο ἥκειν φοβούμενον ἀποθανεῖν;’ ἀλλὰ δίκας λαβεῖν χρῄζων, καὶ λαμβάνων ἤδη παρὰ τῶν ἐκβαλλόντων τῷ σὲ ποιεῖν ἐμαυτοῦ κύριον. εἰ μὲν οὖν ἐστί σοὶ θυμὸς ἐπιχειρεῖν τοῖς πολεμίοις, ἴθι, ταῖς ἐμαῖς συμφοραῖς, ὦ γενναῖε, χρῆσαι, καὶ κοινὸν εὐτύχημα ποίησον Οὐολούσκων τὴν ἐμὴν ἀτυχίαν, τοσούτῳ βέλτιον ὑπὲρ ὑμῶν πολεμήσοντος ἢ πρὸς ὑμᾶς, ὅσῳ πολεμοῦσι βέλτιον οἱ γινώσκοντες τὰ παρὰ τοῖς πολεμίοις τῶν ἀγνοούντων. εἰ δ’ ἀπείρηκας, οὔτ’ ἐγὼ βούλομαι ζῆν οὔτε σοὶ καλῶς ἔχει σῴζειν πάλαι μὲν ἐχθρὸν ἄνδρα καὶ πολέμιον, νῦν δ’ ἀνωφελῆ καὶ ἄχρηστον.", "st": "Cor. 23.1"}, {"sp": "N", "t": "ὡς οὖν ταῦτα ὁ Τύλλος ἤκουσεν, ἥσθη τε θαυμαστῶς καὶ τὴν δεξιὰν ἐμβαλών, ἀνίστασο, εἶπεν, ὦ Μάρκιε, καὶ θάρρει. μέγα γὰρ ἡμῖν ἀγαθὸν ἥκεις διδοὺς σεαυτόν, ἔλπιζε δὲ μείζονα παρὰ Οὐολούσκων. καὶ τότε μὲν εἱστία φιλοφρονούμενος τὸν Μάρκιον, ἐν δὲ ταῖς ἐπιούσαις ἡμέραις ἐβουλεύοντο περὶ τοῦ πολέμου καθ’ ἑαυτούς.", "st": "Cor. 23.5"}, {"sp": "N", "t": "τὴν δὲ Ῥώμην ἥ τε τῶν πατρικίων δυσμένεια πρὸς τὸν δῆμον, οὐχ ἥκιστα τὴν τοῦ Μαρκίου καταδίκην αἰτίαν ἐχόντων, ἐτάραττε, καὶ πολλὰ δαιμόνια μάντεις καὶ ἱερεῖς καὶ ἰδιῶται προσήγγελλον ἄξια φροντίδος. ἓν δὲ λέγεται τοιοῦτό τι γενέσθαι. Τίτος ἦν Λατῖνος, ἀνὴρ οὐκ ἄγαν ἐπιφανής, ἀπράγμων δὲ καὶ μέτριος ἄλλως καὶ καθαρὸς δεισιδαιμονίας, ἔτι δὲ μᾶλλον ἀλαζονείας. οὗτος ὄναρ εἶδεν ὡς τοῦ Διὸς εἰς ὄψιν ἥκοντος αὐτῷ καὶ κελεύοντος εἰπεῖν πρὸς τὴν σύγκλητον ὅτι κακὸν τὸν ὀρχηστὴν ἔστειλαν αὐτῷ πρὸ τῆς πομπῆς καὶ ἀτερπέστατον. ἰδὼν δὲ τὴν ὄψιν ἔλεγε μὴ πάνυ φροντίσαι τὸ πρῶτον ὡς δὲ καὶ δεύτερον ἰδὼν καὶ τρίτον ἠμέλησε, παιδός τε χρηστοῦ θάνατον ἐπιδεῖν καὶ τοῦ σώματος ἄφνω παρεθέντος ἀκρατὴς γενέσθαι. ταῦτα δ’ ἐν κλινιδίῳ φοράδην κομισθεὶς εἰς τὴν σύγκλητον ἀπήγγειλεν. ἀπαγγείλας δ’, ὥς φασιν, εὐθὺς ᾔσθετο ῥωννύμενον αὑτοῦ τὸ σῶμα, καὶ ἀναστὰς ἀπῄει δι’ αὑτοῦ βαδίζων, θαυμάσαντες οὖν οἱ βουλευταὶ πολλὴν ἐποιήσαντο τοῦ πράγματος ζήτησιν.", "st": "Cor. 24.1"}, {"sp": "N", "t": "ἦν δὲ τοιοῦτον· οἰκέτην τις αὑτοῦ παραδοὺς οἰκέταις ἑτέροις ἐκέλευσεν ἐξάγειν δι’ ἀγορᾶς μαστιγοῦντας, εἶτ’ ἀποκτεῖναι. ταῦτα πράττουσιν αὐτοῖς καὶ τὸν ἄνθρωπον αἰκιζομένοις, στροφάς τε παντοδαπὰς ὑπ’ ὀδύνης στρεφόμενον καὶ κινήσεις ἄλλας ἀτερπεῖς τῷ περιπαθεῖν κινούμενον, ἡ πομπὴ κατὰ τύχην ἠκολουθήκει. καὶ πολλοὶ μὲν ἐδυσχέραινον τῶν παρόντων, οὔτε ὄψιν ἱλαρὰν ὁρῶντες οὔτε κινήσεις πρεπούσας, οὐδεὶς δ’ ἐπεξῆλθεν, ἀλλὰ λοιδορίαι μόνον ἐγένοντο καὶ κατάραι τῷ πικρῶς οὕτως κολάζοντι. καὶ γὰρ ἐχρῶντο πολλῇ πρὸς τοὺς οἰκέτας ἐπιεικείᾳ τότε, διὰ αὐτουργίαν καὶ τὸ κοινωνεῖν διαίτης ἡμερώτερον ἔχοντες πρὸς αὐτοὺς καὶ συνηθέστερον. ἦν δὲ μεγάλη κόλασις οἰκέτου πλημμελήσαντος, εἰ ξύλον ἁμάξης, ᾧ τὸν ῥυμὸν ὑπερείδουσιν, ἀράμενος διεξέλθοι παρὰ τὴν γειτνίασιν γὰρ τοῦτο παθὼν καὶ ὀφθεὶς παρὰ τῶν συνοίκων καὶ γειτόνων οὐκέτι πίστιν εἶχεν. ἐκαλεῖτο δὲ φούρκιφερ· ὃ γὰρ οἱ Ἕλληνες ὑποστάτην καὶ στήριγμα, τοῦτο Ῥωμαῖοι φοῦρκαν ὀνομάζουσιν.", "st": "Cor. 24.4"}, {"sp": "N", "t": "ὡς οὖν ὁ Λατῖνος ἀπήγγειλε τὴν ὄψιν αὐτοῖς καὶ διηπόρουν ὅστις ἦν ὁ τῆς πομπῆς τότε προηγούμενος ἀτερπὴς καὶ κακὸς ὀρχηστής, ἀνεμνήσθησαν ἔνιοι διὰ τὴν ἀτοπίαν τῆς τιμωρίας ἐκείνου τοῦ θεράποντος, ὃν μαστιγοῦντες ἐξήγαγον δι’ ἀγορᾶς, εἶτ’ ἐθανάτωσαν. συμφωνησάντων οὖν τῶν ἱερέων ὅ τε δεσπότης δίκην ἔδωκε, καὶ τῷ θεῷ τὴν πομπὴν καὶ τὰς θέας αὖθις ἐξ ἀρχῆς ἐπετέλουν.", "st": "Cor. 25.1"}, {"sp": "N", "t": "ἔοικεν οὖν ὁ Νομᾶς τά τ’ ἄλλα τῶν ἱερῶν σοφώτατος ἐξηγητὴς γεγονέναι, καὶ τοῦτο παγκάλως γε νομοθετῆσαι πρὸς εὐλάβειαν αὐτοῖς. ὅταν γὰρ ἄρχοντες ἢ ἱερεῖς πράττωσί τι τῶν θείων, ὁ κῆρυξ πρόεισι μεγάλῃ φωνῇ βοῶν, Ὃκ ἄγε. σημαίνει δ’ ἡ φωνή, τοῦτο πρᾶττε, προσέχειν κελεύουσα τοῖς ἱεροῖς καὶ μηδὲν ἔργον ἐμβαλεῖν μεταξὺ μηδὲ χρείαν ἀσχολίας, ὡς τὰ πλεῖστα τῶν ἀνθρωπίνων ἀναγκαίῳ τινὶ τρόπῳ καὶ διὰ βίας περαινόμενα. θυσίας δὲ καὶ πομπὰς καὶ θέας οὐ μόνον ἐξ αἰτίας τηλικαύτης, ἀλλὰ καὶ διὰ μικρὰς Ῥωμαίοις ἔθος ἐστὶν ἀναλαμβάνειν, ἵππου τε γὰρ ἑνὸς τῶν ἀγόντων τὰς καλουμένας θήσσας ἀτονήσαντος, καὶ πάλιν τοῦ ἡνιόχου τῇ ἀριστερᾷ χειρὶ τὰς ἡνίας συλλαβόντος, αὖθις ἐψηφίσαντο τὴν πομπὴν ἐπιτελεῖν. ἐν δὲ τοῖς κάτω χρόνοις μίαν θυσίαν τριακοντάκις ἐποίησαν, ἀεί τινος ἐλλείμματος ἢ προσκρούσματος γίνεσθαι δοκοῦντος. τοιαύτη μὲν εὐλάβεια πρὸς τὸ θεῖον Ῥωμαίων.", "st": "Cor. 25.2"}, {"sp": "N", "t": "ὁ δὲ Μάρκιος καὶ Τύλλος ἐν Ἀντίῳ τοῖς δυνατωτάτοις κρύφα διελέγοντο, καὶ παρεκάλουν, ἕως στασιάζουσιν οἱ Ῥωμαῖοι πρὸς ἀλλήλους, τὸν πόλεμον ἐξενεγκεῖν. τῶν δὲ δυσωπουμένων, ὅτι σπονδαὶ διέτεις ἦσαν αὐτοῖς καὶ ἀνοχαὶ γεγενημέναι, πρόφασιν αὐτοὶ Ῥωμαῖοι παρέσχον, ἔκ τινος ὑποψίας ἢ διαβολῆς ἐν θέαις καὶ ἀγῶσι κηρύξαντες ἀπιέναι Οὐολούσκους πρὸ ἡλίου δύνοντος ἐκ τῆς πόλεως. ἔνιοι δέ φασιν ἀπάτῃ τοῦ Μαρκίου καὶ δόλῳ γενέσθαι τοῦτο, πέμψαντος εἰς Ῥώμην πρὸς τοὺς ἄρχοντας οὐκ ἀληθῆ κατήγορον τῶν Οὐολούσκων, ὡς ἐν ταῖς θέαις διανοουμένων ἐπιθέσθαι τοῖς Ῥωμαίοις καὶ τὴν πόλιν ἐμπιπρᾶν. πάντας μὲν γὰρ αὐτοὺς τὸ κήρυγμα τοῦτο δυσμενεστέρους ἐποίησε τοῖς Ῥωμαίοις· ὁ δὲ Τύλλος ἐπὶ μεῖζον αἴρων τὸ πρᾶγμα καὶ παροξύνων τέλος ἔπεισε πέμψαντας εἰς Ῥώμην τήν τε χώραν ἀπαιτεῖν καὶ τὰς πόλεις, ὅσας ἀφῄρηνται πολέμῳ τῶν Οὐολούσκων. οἱ δὲ Ῥωμαῖοι τῶν πρέσβεων ἀκούσαντες ἠγανάκτησαν, καὶ ἀπεκρίναντο προτέρους μὲν ἀναλήψεσθαι τὰ ὅπλα τοὺς Οὐολούσκους, ὑστέρους δὲ καταθήσεσθαι Ῥωμαίους. ἐκ τούτου συναγαγὼν ἐκκλησίαν πάνδημον ὁ Τύλλος, ἐπεὶ τὸν πόλεμον ἐψηφίσαντο, συνεβούλευε τὸν Μάρκιον καλέσαι, μηδὲν αὐτῷ μνησικακοῦντας, ἀλλὰ πιστεύσαντας ὅτι συμμαχῶν ὠφελήσει ὅσα πολεμῶν οὐκ ἔβλαψεν.", "st": "Cor. 26.1"}, {"sp": "N", "t": "ἐπεὶ δὲ κληθεὶς ὁ Μάρκιος καὶ διαλεχθεὶς πρὸς τὸ πλῆθος οὐχ ἧττον ἀπὸ τῶν λόγων ἢ τῶν ὅπλων ἀνὴρ δεινὸς ἐφάνη καὶ πολεμικὸς καὶ τὸ φρονεῖν καὶ τολμᾶν περιττός, ἀποδείκνυται μετὰ Τύλλου στρατηγὸς αὐτοκράτωρ τοῦ πολέμου. δεδιὼς δὲ τὸν χρόνον ἐν ᾧ παρασκευάσασθαι τοὺς Οὐολούσκους ἔδει, μὴ πολὺς γενόμενος τὸν καιρὸν ἀφέληται τῆς πράξεως, τὰ μὲν ἄλλα τοὺς κατὰ πόλιν δυνατοὺς καὶ ἄρχοντας ἐκέλευε συνάγειν καὶ πορίζειν, αὐτὸς δὲ τοὺς προθυμοτάτους ἄνευ καταλόγου πείσας ἑκόντας αὐτῷ συνεξελθεῖν, ἐνέβαλεν εἰς τὴν τῶν Ῥωμαίων ἄφνω καὶ μηδενὸς προσδοκῶντος. ὅθεν ηὐπόρησε λείας τοσαύτης ὅσην ἄγοντας καὶ φέροντας καὶ χρωμένους ἐν τῷ στρατοπέδῳ τοὺς Οὐολούσκους ἀπειπεῖν, ἦν δὲ μικρότατον ἔργον αὐτῷ τῆς στρατείας ἐκείνης ἡ εὐπορία καὶ τὸ πολλὰ βλάψαι καὶ κακῶσαι τὴν χώραν οὗ δ’ ἕνεκα ταῦτ’ ἔπραττε, μέγα, τὸ τοὺς πατρικίους προσδιαβαλεῖν τῷ δήμῳ. τὰ γὰρ ἄλλα πάντα λυμαινόμενος καὶ διαφθείρων, τοὺς ἐκείνων ἀγροὺς ἰσχυρῶς ἐφύλαττε, καὶ οὐκ εἴα κακουργεῖν οὐδὲ λαμβάνειν ἐξ ἐκείνων οὐδέν. ὅθεν ἐν διαβολαῖς ἔτι μᾶλλον ἐγένοντο καὶ ταραχαῖς πρὸς ἀλλήλους, οἱ μὲν πατρίκιοι τοῖς πολλοῖς ἐγκαλοῦντες ὡς ἄνδρα δυνατὸν ἀδίκως ἐκβαλοῦσιν, ὁ δὲ δῆμος ἐκείνους ᾐτιᾶτο διὰ μνησικακίαν ἐπάγειν τὸν Μάρκιον, εἶτα πολεμουμένων ἑτέρων θεατὰς καθῆσθαι, φύλακα τοῦ πλούτου καὶ τῶν χρημάτων ἔξω τὸν πόλεμον αὐτὸν ἔχοντας, ταῦτα διαπραξάμενος ὁ Μάρκιος, καὶ μεγάλα πρὸς τὸ θαρρεῖν καὶ καταφρονεῖν τῶν πολεμίων τοὺς Οὐολούσκους ὠφελήσας, ἀπήγαγεν ἀσφαλῶς.", "st": "Cor. 27.1"}, {"sp": "N", "t": "ἐπεὶ δὲ πᾶσα ταχὺ καὶ προθύμως ἡ τῶν Οὐολούσκων δύναμις ἠθροίσθη πολλὴ φανεῖσα, μέρος μὲν ἔγνωσαν ὑπολιπεῖν ταῖς πόλεσιν ὑπὲρ ἀσφαλείας, μέρει δὲ στρατεύειν ἐπὶ τοὺς Ῥωμαίους· ἑλέσθαι δὲ τῶν ἡγεμονιῶν ὁ Μάρκιος ἔδωκε τῷ Τύλλῳ τὴν ἑτέραν. ὁ δὲ Τύλλος, εἰπὼν ὡς οὐδὲν ἀρετῇ λειπόμενον αὑτοῦ τὸν Μάρκιον ὁρᾷ, τύχῃ δὲ βελτίονι κεχρημένον ἐν ταῖς μάχαις ἁπάσαις, ἐκέλευσεν ἡγεῖσθαι τῶν ἐξιόντων, αὐτὸς δὲ τάς τε πόλεις ὑπομένων φυλάξειν καὶ τοῖς στρατευομένοις ὑπουργήσειν τὰ πρόσφορα. μᾶλλον οὖν ἐπιρρωσθεὶς ὁ Μάρκιος ἐχώρει πρῶτον ἐπὶ Κίρκαιον, πόλιν ἀποικίδα Ῥωμαίων, καὶ ταύτην ἐνδοῦσαν ἑκουσίως οὐδὲν ἠδίκησε. μετὰ δὲ ταύτην ἐπόρθει τὴν Λατίνων χώραν, ἐνταῦθα προσμαχεῖσθαι προσδεχόμενος αὐτῷ τοὺς Ῥωμαίους ὑπὲρ τῶν Λατίνων συμμάχων ὄντων καὶ πολλάκις αὐτοὺς ἐπικαλουμένων. ἐπεὶ δὲ καὶ τὸ πλῆθος ἀπρόθυμον ἐγένετο καὶ τοῖς ὑπάτοις ὀλίγος ἔτι περιῆν τῆς ἀρχῆς χρόνος, ἐν ᾧ κινδυνεύειν οὐκ ἐβούλοντο, καὶ διὰ ταῦτα τοὺς Λατίνους ἀπέπεμψαν, οὕτως ὁ Μάρκιος ἐπ’ αὐτὰς τάς πόλεις ἦγε, καὶ Τολερίνους καὶ Λαουικανοὺς καὶ Πεδανούς, ἔτι δὲ Βωλανοὺς ἀντιστάντας αὐτῷ κατὰ κράτος ἑλών, τά τε σώματα λείαν ἐποιήσατο καὶ τὰ χρήματα διήρπασε. τῶν δὲ προστιθεμένων ἐπιμέλειαν ἐποιεῖτο πολλήν, ὅπως μηδ’ ἄκοντος αὐτοῦ βλάπτοιντο, πορρωτάτω στρατοπεδεύων καὶ τῆς χώρας ἀπεχόμενος.", "st": "Cor. 28.1"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ Βόλλας πόλιν οὐ πλείους σταδίους ἑκατὸν ἀπέχουσαν τῆς Ῥώμης ἑλὼν χρημάτων πολλῶν ἐκράτησε καὶ πάντας ὀλίγου δεῖν τοὺς ἐν ἡλικίᾳ διέφθειρε, τῶν δὲ Οὐολούσκων οὐδ’ οἱ μένειν ἐν ταῖς πόλεσι ταχθέντες ἐκαρτέρουν, ἀλλ’ ἐφέροντο σὺν τοῖς ὅπλοις πρὸς τὸν Μάρκιον, ἕνα στρατηγὸν καὶ μόνον ἄρχοντα ἑαυτῶν γινώσκειν ἐκεῖνον εἶναι λέγοντες, ἦν ὄνομα κατὰ πᾶσαν αὐτοῦ τὴν Ἰταλίαν μέγα καὶ δόξα θαυμαστὴ, τῆς ἀρετῆς ἑνὸς σώματος μεταθέσει τοσοῦτον ἀπεργασαμένης τὸ παράλογον ἐν τοῖς πράγμασι.", "st": "Cor. 29.1"}, {"sp": "N", "t": "τὰ δὲ τῶν Ῥωμαίων οὐδένα κόσμον εἶχε, μάχεσθαι μὲν ἀπεγνωκότων, ἐν δὲ συστάσεσι καὶ λόγοις στασιαστικοῖς ὁσημέραι πρὸς ἀλλήλους ὄντων, ἄχρι οὗ Λαουΐνιον ἀπηγγέλθη περιτειχιζόμενον ὑπὸ τῶν πολεμίων, ὅπου καὶ θεῶν ἱερὰ Ῥωμαίοις πατρῴων ἀπέκειτο, καὶ τοῦ γένους ἦσαν αὐτοῖς ἀρχαὶ, διὰ τὸ πρώτην πόλιν ἐκείνην κτίσαι τὸν Αἰνείαν. ἐκ δὲ τούτου θαυμαστὴ μὲν ἔσχε καὶ ἀθρόα μεταβολὴ γνώμης τὸν δῆμον, ἄτοπος δὲ κομιδῇ καὶ παράλογος τοὺς πατρικίους, ὁ μὲν γὰρ δῆμος ὥρμησε λύειν τὴν τοῦ Μαρκίου καταδίκην καὶ καλεῖν αὐτὸν εἰς τὴν πόλιν, ἡ δὲ βουλὴ συναχθεῖσα καὶ σκοποῦσα περὶ τοῦ βουλεύματος ἀπέγνω καὶ διεκώλυσεν, εἴτε πάντως ἐνίστασθαι φιλονεικοῦσα πᾶσιν οἷς ὁ δῆμος ἐσπούδαζεν, εἴτ’ ἄλλως χάριτι τοῦ δήμου τὸν ἄνδρα μὴ βουλομένη κατελθεῖν, εἴτε κἀκεῖνον αὐτὸν ἤδη πεποιημένη δι’ ὀργῆς, ὅτι πάντας ἐποίει κακῶς οὐχ ὑπὸ πάντων ἀγνωμονηθείς, καὶ τῆς πατρίδος αὑτὸν ἔδειξεν ἐχθρόν, ἐν ᾗ τὸ κυριώτατον καὶ κράτιστον μέρος ἐγίνωσκε συμπαθοῦν αὐτῷ καὶ συναδικούμενον. ἐξενεχθείσης δὲ τῆς γνώμης εἰς τοὺς πολλούς, ὁ μὲν δῆμος ἄκυρος ἦν τοῦ ψήφῳ καὶ νόμῳ τι ποιεῖν ἄνευ προβουλεύματος.", "st": "Cor. 29.2"}, {"sp": "N", "t": "ὁ δὲ Μάρκιος ἀκούσας ἔτι μᾶλλον ἐξετραχύνθη, καὶ τὴν πολιορκίαν ἀπολιπὼν ἐπὶ τὴν πόλιν ὑπ’ ὀργῆς ἐχώρει, καὶ περὶ τὰς λεγομένας Κλοιλίας τάφρους κατεστρατοπέδευσε τεσσαράκοντα τῆς πόλεως σταδίους ἀφεστώς. ὀφθεὶς δὲ φοβερὸς καὶ πολὺν θόρυβον παρασχών, ὅμως ἐν τῷ παρόντι τὴν στάσιν ἔπαυσεν· οὐδεὶς γὰρ ἔτι τοῖς πολλοῖς ἐτόλμησεν ἀντειπεῖν οὔτ’ ἄρχων οὔτε βουλευτὴς περὶ τοῦ τὸν Μάρκιον κατάγειν, ἀλλ’ ὁρῶντες ἐν τῇ πόλει διαδρομὰς γυναικῶν καὶ πρὸς ἱεροῖς ἱκεσίας καὶ δάκρυα πρεσβυτῶν καὶ δεήσεις, πάντα δ’ ἐνδεᾶ τόλμης καὶ σωτηρίων λογισμῶν, συνέγνωσαν ὀρθῶς τὸν δῆμον ἐπὶ τὰς διαλλαγὰς τοῦ Μαρκίου τραπέσθαι, τὴν δὲ βουλὴν τοῦ παντὸς ἁμαρτάνειν, ὅτε παύσασθαι καλῶς εἶχεν ὀργῆς καὶ μνησικακίας, ἀρχομένην. ἔδοξεν οὖν πᾶσι πρέσβεις ἀποστεῖλαι πρὸς τὸν Μάρκιον ἐκείνῳ τε κάθοδον διδόντας εἰς τὴν πατρίδα καὶ τὸν πόλεμον αὐτοῖς λῦσαι δεομένους. οἱ δὲ πεμφθέντες ἀπὸ βουλῆς ἦσαν μὲν ἐπιτήδειοι τῷ Μαρκίῳ, προσεδέχοντο δὲ πολλὴν περί γε τὰς πρώτας ἀπαντήσεις φιλοφροσύνην παρ’ ἀνδρὸς οἰκείου καὶ συνήθους, ἐγίνετο τοιοῦτον οὐδέν, ἀλλὰ διὰ τοῦ στρατοπέδου τῶν πολεμίων ἀχθέντες ἐνετύγχανον αὐτῷ μετ’ ὄγκου καθεζομένῳ καὶ βαρύτητος οὐκ ἀνεκτῆς. ἔχων δὲ τοὺς πρώτους τῶν Οὐολούσκων περί αὑτόν, ἐκέλευε λέγειν ὧν δεόμενοι τυγχάνουσιν. εἰπόντων δὲ λόγους ἐπιεικεῖς καὶ φιλανθρώπους ἐν ἤθει τῷ πρέποντι καὶ παυσαμένων, ἀπεκρίνατο τὰ μὲν πικρῶς ὑπὲρ αὑτοῦ καὶ πρὸς ὀργὴν ὧν ἔπαθε, τὰ δ’ ὑπὲρ τῶν Οὐολούσκων ὡς στρατηγός, ἀποδοῦναι τὰς πόλεις καὶ τὴν χώραν, ὅσην ἀπετέμοντο πολέμῳ, κελεύων, καὶ ψηφίσασθαι Οὐολούσκοις ἰσοπολιτείαν ἥνπερ Λατίνοις· ἄλλην γὰρ οὐκ εἶναι βέβαιον ἢ τὴν ἐπὶ τοῖς ἴσοις καὶ δικαίοις ἀπαλλαγὴν τοῦ πολέμου, χρόνον δὲ βουλῆς ἔδωκεν αὐτοῖς ἡμέρας τριάκοντα· καὶ τῶν πρέσβεων ἀπελθόντων εὐθὺς ἀνέζευξεν ἐκ τῆς χώρας.", "st": "Cor. 30.1"}, {"sp": "N", "t": "τοῦτο δὴ πρῶτον αἰτίαμα τῶν Οὐολούσκων οἱ πάλαι βαρυνόμενοι τὴν δύναμιν αὐτὸν καὶ φθονοῦντες ἐλάμβανον· ὧν ἦν καὶ ὁ Τύλλος, ἰδίᾳ μὲν ὑπὸ τοῦ Μαρκίου μηδὲν ἀδικούμενος, ἐν δ’ ἀνθρωπίνῳ πάθει γεγονώς. ἤχθετο γὰρ ἠμαυρωμένος παντάπασι τῇ δόξῃ καὶ παρορώμενος ὑπὸ τῶν Οὐολούσκων, πάντα μόνον ἡγουμένων αὐτοῖς εἶναι τὸν Μάρκιον, τοὺς δὲ ἄλλους ἀξιούντων, ὅσον ἐκεῖνος αὐτοῖς μεταδώσει δυνάμεως καὶ ἀρχῆς, ἀγαπᾶν ἔχοντας. ὅθεν αἱ πρῶται κατηγορίαι κρύφα διεσπείροντο, καὶ συνιστάμενοι πρὸς ἀλλήλους ἠγανάκτουν, καὶ προδοσίαν ἐκάλουν τὴν ἀνάζευξιν, οὐ τειχῶν οὐδ’ ὅπλων, ἀλλὰ καιρῶν, οἷς καὶ τἆλλα πάντα σῴζεσθαι καὶ πάλιν ἀπόλλυσθαι πέφυκεν, ἡμερῶν τριάκοντα τῷ πολέμῳ δεδομένων, οὗ μείζονας οὐδὲν ἐν ἐλάττονι χρόνῳ λαμβάνειν μεταβολάς.", "st": "Cor. 31.1"}, {"sp": "N", "t": "καίτοι τὸν χρόνον τοῦτον ὁ Μάρκιος οὐκ ἀργὸν διῆγεν, ἀλλὰ τοὺς συμμάχους τῶν πολεμίων ἔφθειρεν ἐπιὼν καὶ περιέκοπτε καὶ πόλεις ἑπτὰ μεγάλας καὶ πολυανθρώπους ἔλαβεν. οἱ δὲ Ῥωμαῖοι βοηθεῖν μὲν οὐκ ἐτόλμων, ἀλλ’ ὄκνου πλήρεις ἦσαν αὐτῶν αἱ ψυχαί, καὶ τοῖς ἐκνεναρκηκόσι κομιδῇ καὶ παραλελυμένοις σώμασιν ὁμοίως διέκειντο πρὸς τὸν πόλεμον. ἐπεὶ δ’ ὁ χρόνος διῆλθε καὶ παρῆν αὖθις ὁ Μάρκιος μετὰ τῆς δυνάμεως ἁπάσης, ἐκπέμπουσι πρεσβείαν πάλιν τοῦ Μαρκίου δεησομένην ὑφέσθαι τῆς ὀργῆς καὶ τοὺς Οὐολούσκους ἐκ τῆς χώρας ἀπαγαγόντα πράττειν καὶ λέγειν ὅ τι ἂν ἀμφοτέροις οἴηται βέλτιον εἶναι· φόβῳ μὲν γὰρ οὐδὲν ἐνδώσειν Ῥωμαίους, ἐὰν δέ τινος τῶν φιλανθρώπων οἴηται δεῖν τυχεῖν τοὺς Οὐολούσκους, ἅπαν αὐτοῖς γενήσεσθαι τὰ ὅπλα καταθεμένοις. πρὸς ταῦθ’ ὁ Μάρκιος ἔφη μηδὲν ὡς Οὐολούσκων ἀποκρίνεσθαι στρατηγός, ὡς δὲ Ῥωμαίων ἔτι πολίτης παραινεῖν καὶ παρακαλεῖν μετριώτερα φρονήσαντας ἐπὶ τοῖς δικαίοις ἥκειν πρὸς αὐτὸν ἐν ἡμέραις τρισίν, ἃ προκαλεῖται ψηφισαμένους· εἰ δ’ ἕτερα δόξειε, γιγνώσκειν οὐκ οὖσαν αὐτοῖς ἄδειαν αὖθις μετὰ λόγων κενῶν βαδίζουσιν εἰς τὸ στρατόπεδον.", "st": "Cor. 31.3"}, {"sp": "N", "t": "ἐπανελθόντων δὲ τῶν πρέσβεων ἀκούσασα ἡ βουλή, καθάπερ ἐν χειμῶνι πολλῷ καὶ κλύδωνι τῆς πόλεως, ἄρασα τὴν ἀφ’· ἱερᾶς ἀφῆκεν. ὅσοι γὰρ ἦσαν ἱερεῖς θεῶν ἢ μυστηρίων ὀργιασταὶ ἢ φύλακες ἢ τὴν ἀπ’ οἰωνῶν πάτριον οὖσαν ἐκ παλαιῶν μαντικὴν ἔχοντες, τούτους πάντας ἀπιέναι πρὸς τὸν Μάρκιον ἐψηφίσαντο, κεκοσμημένους ὡς ἦν ἑκάστῳ νόμος ἐν ταῖς ἱερουργίαις· λέγειν δὲ ταὐτὰ, καὶ παρακαλεῖν ὅπως ἀπαλλάξας τὸν πόλεμον οὕτω διαλέγηται περὶ τῶν Οὐολούσκων τοῖς πολίταις. ἐδέξατο μὲν οὖν εἰς τὸ στρατόπεδον τοὺς ἄνδρας, ἄλλο δ’ οὐδὲν ἔδωκεν οὐδ’ ἔπραξεν οὐδ’ εἶπε μαλακώτερον, ἀλλ’ ἐφ’ οἷς πρότερον ἐκέλευε ποιεῖσθαι τὰς διαλύσεις ἢ δέχεσθαι τὸν πόλεμον. ἐπανελθόντων οὖν τῶν ἱερέων ἔδοξεν ἀτρεμοῦντας ἐν τῇ πόλει τὰ τείχη φυλάττειν καὶ προσβάλλοντας ἀποκρούεσθαι τοὺς πολεμίους, ἐν τῷ χρόνῳ μάλιστα καὶ τοῖς ἀπὸ τῆς τύχης παραλόγοις τιθεμένοις τὰς ἐλπίδας, ἐπεὶ δι’ αὑτῶν γε σωτήριον οὐδὲν ἠπίσταντο πράττοντες, ἀλλὰ ταραχὴ καὶ πτοία καὶ φήμη πονηρὰ τὴν πόλιν κατεῖχεν, ἄχρι οὗ συνέβη τι πρᾶγμα τῷ πολλάκις ὑφ’ Ὁμήρου λεγομένῳ, μὴ τάνυ δὲ πείθοντι τοὺς πολλούς, ὅμοιον. λέγοντος γὰρ αὐτοῦ καὶ ἀναφωνοῦντος ἐπὶ ταῖς μεγάλαις πράξεσι καὶ παραλόγοις·", "st": "Cor. 32.1"}, {"sp": "N", "t": "τῷ δ’ ἄρ’ ἐπὶ φρεσὶ θῆκε θεὰ γλαυκῶπις Ἀθήνη·<br>καὶ τὸ<br>ἀλλά τις ἀθανάτων τρέψεν φρένας, ὅς γ’ ἐνὶ θυμῷ<br>δήμου θῆκε φάτιν·<br>καὶ τὸ<br>ἤ τι ὀϊσσάμενος ἢ καὶ θεὸς ὣς ἐκέλευε·", "st": "Cor. 32.1b"}, {"sp": "N", "t": "καταφρονοῦσιν ὡς ἀδυνάτοις πράγμασι καὶ μυθεύμασιν ἀπίστοις τὸν ἑκάστου λογισμὸν τῆς προαιρέσεως ἄπιστον καθιστάντος. οὐ ποιεῖ δὲ τοῦτο Ὅμηρος, ἀλλὰ τὰ μὲν εἰκότα καὶ συνήθη καὶ κατὰ λόγον περαινόμενα τῷ ἐφ’ ἡμῖν ἀποδίδωσι, καὶ λέγει δήπου πολλάκις·<br>αὐτὰρ ἐγὼ βούλευσα κατὰ μεγαλήτορα θυμόν·", "st": "Cor. 32.5"}, {"sp": "N", "t": "καὶ,<br>ὣς φάτο, Πηλείωνι δ’ ἄχος γένετ’, ἐν δέ οἱ ἦτορ<br>στήθεσσιν λασίοισι διάνδιχα μερμήριζεν·<br>καὶ πάλιν,", "st": "Cor. 32.5b"}, {"sp": "N", "t": "ἀλλὰ τὸν οὔ τι", "st": "Cor. 32.5c"}, {"sp": "N", "t": "πεῖθ’ ἀγαθὰ φρονέοντα, δαΐφρονα Βελλεροφόντην·", "st": "Cor. 32.5d"}, {"sp": "N", "t": "ἐν δὲ ταῖς ἀτόποις καὶ παραβόλοις πράξεσι καὶ φορᾶς τινος ἐνθουσιώδους καὶ παραστάσεως δεομέναις οὐκ ἀναιροῦντα ποιεῖ τὸν θεόν, ἀλλὰ κινοῦντα τὴν προαίρεσιν, οὐδ’ ὁρμὰς ἐνεργαζόμενον, ἀλλὰ φαντασίας ὁρμῶν ἀγωγούς, αἷς οὐδὲ ποιεῖ τὴν πρᾶξιν ἀκούσιον, ἀλλὰ τῷ ἑκουσίῳ δίδωσιν ἀρχήν, καὶ τὸ θαρρεῖν καὶ τὸ ἐλπίζειν προστίθησιν. ἢ γὰρ ἀπαλλακτέον ὅλως τὰ θεῖα πάσης αἰτίας καὶ ἀρχῆς τῶν καθ’ ἡμᾶς, ἤ τις ἂν ἄλλος εἴη τρόπος ᾧ βοηθοῦσιν ἀνθρώποις καὶ συνεργοῦσιν; οὐ τὸ σῶμα δήπου πλάττοντες ἡμῶν, οὐδὲ τὰς χεῖρας, ὡς δεῖ, μετατιθέντες αὐτοὶ καὶ τοὺς πόδας, ἀλλὰ τῆς ψυχῆς τὸ πρακτικὸν καὶ προαιρετικὸν ἀρχαῖς τισι καὶ φαντασίαις καὶ ἐπινοίαις ἐγείροντες ἢ τοὐναντίον ἀποστρέφοντες καὶ ἱστάντες.", "st": "Cor. 32.6"}, {"sp": "N", "t": "ἐν δὲ τῇ Ῥώμῃ τότε τῶν γυναικῶν ἄλλαι μὲν πρὸς ἄλλοις ἱεροῖς, αἱ δὲ πλεῖσται καὶ δοκιμώταται περὶ τὸν τοῦ Καπιτωλίου Διὸς βωμὸν ἱκέτευον. ἐν δὲ ταύταις ἦν ἡ Ποπλικόλα τοῦ μεγάλα καὶ πολλὰ Ῥωμαίους ἔν τε πολέμοις καὶ πολιτείαις ὠφελήσαντος ἀδελφὴ Οὐαλερία. Ποπλικόλας μὲν οὖν ἐτεθνήκει πρότερον, ὡς ἐν τοῖς περὶ ἐκείνου γεγραμμένοις ἱστορήκαμεν, ἡ δὲ Οὐαλερία δόξαν εἶχεν ἐν τῇ πόλει καὶ τιμήν, δοκοῦσα τῷ βίῳ μὴ καταισχύνειν τὸ γένος. ὅπερ οὖν λέγω πάθος ἐξαπίνης παθοῦσα, καὶ κατ’ ἐπίνοιαν οὐκ ἀθείαστον ἁψαμένη τοῦ συμφέροντος, αὐτή τε ἀνέστη καὶ τὰς ἄλλας ἀναστήσασα πάσας ἧκεν ἐπὶ τὴν οἰκίαν τῆς τοῦ Μαρκίου μητρὸς Οὐολουμνίας. ὡς δ’ εἰσῆλθε καὶ κατέλαβε μετὰ τῆς νυοῦ καθεζομένην καὶ τὰ παιδία τοῦ Μαρκίου πρὸς τοῖς κόλποις ἔχουσαν, ἐν κύκλῳ περιστήσασα τὰς γυναῖκας αὐτῆς· αὐταί γε ἡμεῖς, εἶπεν, ὦ Οὐολουμνία, καὶ σύ, Οὐεργιλία, γυναῖκες ἥκομεν πρὸς γυναῖκας, οὔτε βουλῆς ψηφισαμένης οὔτ’ ἄρχοντος κελεύσαντος, ἀλλ’ ὁ θεὸς ἡμῶν, ὡς ἔοικεν, οἰκτείρας τὴν ἱκετείαν, ὁρμὴν παρέστησε δευρὶ τραπέσθαι πρὸς ὑμᾶς καὶ δεηθῆναι σωτηρίαν μὲν αὑταῖς καὶ τοῖς ἄλλοις πολίταις, ὑμῖν δὲ πεισθείσαις ἐπιφανεστέραν φέροντα δόξαν ἧς αἱ Σαβίνων θυγατέρες ἔσχον, εἰς φιλίαν καὶ εἰρήνην ἐκ πολέμων συναγαγοῦσαι πατέρας καὶ ἄνδρας. δεῦτε πρὸς Μάρκιον ἰοῦσαι μεθ’ ἡμῶν συνάψασθε τῆς ἱκετηρίας, καὶ μαρτυρήσατε τῇ πατρίδι μαρτυρίαν ἀληθῆ καὶ δικαίαν, ὅτι πολλὰ πάσχουσα κακῶς οὐδὲν οὔτ’ ἔπραξε δεινὸν οὔτ’ ἐβούλευσε περὶ ὑμῶν δι’ ὀργήν, ἀλλ’ ἀποδίδωσιν ὑμᾶς ἐκείνῳ κἂν μηδενὸς τυγχάνειν μέλλῃ τῶν ἐπιεικῶν.", "st": "Cor. 33.1"}, {"sp": "N", "t": "ταῦτα τῆς Οὐαλερίας εἰπούσης ἀνεβόησαν αἱ λοιπαὶ γυναῖκες, ἠμείψατο δὲ ἡ Οὐολουμνία· καὶ τῶν κοινῶν ἡμῖν συμφορῶν, ὦ γυναῖκες, ἴσον μέτεστι, καὶ ἰδίᾳ πράττομεν κακῶς ἀπολέσασαι τὴν Μαρκίου δόξαν καὶ ἀρετήν, τὸ σῶμα δ’ αὐτοῦ τοῖς τῶν πολεμίων ὅπλοις φρουρούμενον μᾶλλον ἢ σῳζόμενον ἐφορῶσαι. μέγιστον δ’ ἡμῖν τῶν ἀτυχημάτων ἐστίν, εἰ τὰ τῆς πατρίδος οὕτως ἐξησθένηκεν ὥστ’ ἐν ἡμῖν ἔχειν τὰς ἐλπίδας. οὐκ οἶδα γὰρ εἴ τινα ποιήσεται λόγον ἡμῶν ἐκεῖνος, εἴ γε μηδένα ποιεῖται τῆς πατρίδος, ἣν καὶ μητρὸς καὶ γυναικὸς καὶ τέκνων προετίμησεν. οὐ μὴν ἀλλὰ χρῆσθε ἡμῖν λαβοῦσαι καὶ κομίζετε πρὸς ἐκεῖνον, εἰ μηδὲν ἄλλο, ταῖς ὑπὲρ τῆς πατρίδος ἱκεσίαις ἐναποπνεῦσαι δυναμένας.", "st": "Cor. 33.5"}, {"sp": "N", "t": "ἐκ τούτου τά τε παιδία καὶ τὴν Οὐεργιλίαν ἀναστήσασα μετὰ τῶν ἄλλων γυναικῶν ἐβάδιζεν εἰς τὸ στρατόπεδον τῶν Οὐολούσκων. ἡ δ’ ὄψις αὐτῶν τό τ’ οἰκτρὸν καὶ τοῖς πολεμίοις ἐνεποίησεν αἰδῶ καὶ σιωπήν. ἔτυχε δ’ ὁ Μάρκιος ἐπὶ βήματος καθεζόμενος μετὰ τῶν ἡγεμονικῶν. ὡς οὖν εἶδε προσιούσας τὰς γυναῖκας, ἐθαύμασεν ἐπιγνοὺς δὲ τὴν μητέρα πρώτην βαδίζουσαν ἐβούλετο μὲν ἐμμένειν τοῖς ἀτρέπτοις ἐκείνοις καὶ ἀπαραιτήτοις λογισμοῖς, γενόμενος δὲ τοῦ πάθους ἐλάττων καὶ συνταραχθεὶς πρὸς τὴν ὄψιν οὐκ ἔτλη καθεζομένῳ προσελθεῖν, ἀλλὰ καταβὰς θᾶττον ἢ βάδην καὶ ἀπαντήσας πρώτην μὲν ἠσπάσατο τὴν μητέρα καὶ πλεῖστον χρόνον, εἶτα δὲ τὴν γυναῖκα καὶ τὰ τέκνα, μήτε δακρύων ἔτι μήτε τοῦ φιλοφρονεῖσθαι φειδόμενος, ἀλλ’ ὥσπερ ὑπὸ ῥεύματος φέρεσθαι τοῦ πάθους ἑαυτὸν ἐνδεδωκώς.", "st": "Cor. 34.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τούτων ἄδην εἶχε καὶ τὴν μητέρα βουλομένην ἤδη λόγων ἄρχειν ᾔσθετο, τοὺς τῶν Οὐολούσκων προβούλους παραστησάμενος ἤκουσε τῆς Οὐολουμνίας τοιαῦτα λεγούσης ὁρᾷς μὲν, ὦ παῖ, κἂν αὐταὶ μὴ λέγωμεν, ἐσθῆτι καὶ μορφῇ τῶν ἀθλίων σωμάτων τεκμαιρόμενος, οἵαν οἰκουρίαν ἡμῖν ἡ σὴ φυγὴ περιεποιήσατο· λόγισαι δὲ νῦν ὡς ἀτυχέσταται πασῶν ἀφίγμεθα γυναικῶν, αἷς τὸ ἥδιστον θέαμα φοβερώτατον ἡ τύχη πεποίηκεν, ἐμοὶ μὲν υἱόν, ταύτῃ δ’ ἄνδρα τοῖς τῆς πατρίδος τείχεσιν ἰδεῖν ἀντικαθήμενον. ὃ δ’ ἔστι τοῖς ἄλλοις ἀτυχίας πάσης καὶ κακοπραγίας παραμύθιον, εὔχεσθαι θεοῖς, ἡμῖν ἀπορώτατον γέγονεν. οὐ γὰρ οἷόν τε καὶ τῇ πατρίδι νίκην ἅμα καὶ σοὶ σωτηρίαν αἰτεῖσθαι παρὰ τῶν θεῶν, ἀλλ’ ἅ τις ἂν ἡμῖν καταράσαιτο τῶν ἐχθρῶν, ταῦτα ταῖς ἡμετέραις ἔνεστιν εὐχαῖς. ἀνάγκη γὰρ ἢ τῆς πατρίδος ἢ σοῦ στέρεσθαι γυναικὶ σῇ καὶ τέκνοις, ἐγὼ δ’ οὐ περιμενῶ ταύτην μοι διαιτῆσαι τὴν τύχην ζώσῃ τὸν πόλεμον, ἀλλ’ εἰ μή σε πείσαιμι φιλίαν καὶ ὁμόνοιαν ἀντὶ διαφορᾶς καὶ κακῶν θέμενον ἀμφοτέρων εὐεργέτην γενέσθαι μᾶλλον ἢ λυμεῶνα τῶν ἑτέρων, οὕτω διανοοῦ καὶ παρασκεύαζε σεαυτὸν ὡς τῇ πατρίδι μὴ προσμῖξαι δυνάμενος πρὶν ἢ νεκρὰν ὑπερβῆναι τὴν τεκοῦσαν. οὐ γὰρ ἐκείνην με δεῖ τὴν ἡμέραν ἀναμένειν ἐν ᾗ τὸν υἱὸν ἐπόψομαι θριαμβευόμενον ὑπὸ τῶν πολιτῶν ἢ θριαμβεύοντα κατὰ τῆς πατρίδος. εἰ μὲν οὖν ἀξιῶ σε τὴν πατρίδα σῶσαι Οὐολούσκους ἀπολέσαντα, χαλεπή σοὶ καὶ δυσδιαίτητος, ὦ παῖ, πρόκειται σκέψις· οὔτε γὰρ διαφθεῖραι τοὺς πολίτας καλόν, οὔτε τοὺς πεπιστευκότας προδοῦναι δίκαιον νῦν δ’ ἀπαλλαγὴν κακῶν αἰτούμεθα, σωτήριον μὲν ἀμφοτέροις ὁμοίως, ἔνδοξον δὲ καὶ καλὴν μᾶλλον Οὐολούσκοις, ὅτι τῷ κρατεῖν δόξουσι διδόναι τὰ μέγιστα τῶν ἀγαθῶν, οὐχ ἧττον λαμβάνοντες, εἰρήνην καὶ φιλίαν, ὧν μάλιστα μὲν αἴτιος ἔσῃ γινομένων, μὴ γινομένων δὲ μόνος αἰτίαν ἕξεις παρ’ ἀμφοτέροις. ἄδηλος δ’ ὢν ὁ πόλεμος τοῦτ’ ἔχει πρόδηλον, ὅτι σοὶ νικῶντι μὲν ἀλάστορι τῆς πατρίδος εἶναι περίεστιν, ἡττώμενος δὲ δόξεις ὑπ’ ὀργῆς εὐεργέταις ἀνδράσι καὶ φίλοις τῶν μεγίστων συμφορῶν αἴτιος γεγονέναι.", "st": "Cor. 35.1"}, {"sp": "N", "t": "ταῦτα τῆς Οὐολουμνίας λεγούσης ὁ Μάρκιος ἠκροᾶτο μηδὲν ἀποκρινόμενος, ἐπεὶ δὲ καὶ παυσαμένης εἱστήκει σιωπῶν πολὺν χρόνον, αὖθις ἡ Οὐολουμνία· τί σιγᾷς, εἶπεν, ὦ παῖ; πότερον ὀργῇ καὶ μνησικακίᾳ πάντα συγχωρεῖν καλόν, οὐ καλὸν δὲ μητρὶ χαρίσασθαι δεομένῃ περὶ τηλικούτων; ἡ τὸ μεμνῆσθαι πεπονθότα κακῶς ἀνδρὶ μεγάλῳ προσήκει, τὸ δ’ εὐεργεσίας, αἷς εὐεργετοῦνται παῖδες ὑπὸ τῶν τεκόντων, σέβεσθαι καὶ τιμᾶν οὐκ ἀνδρὸς ἔργον ἐστὶ μεγάλου καὶ ἀγαθοῦ; καὶ μὴν οὐδενὶ μᾶλλον ἔπρεπε τηρεῖν χάριν ὡς σοί, πικρῶς οὕτως ἀχαριστίαν ἐπεξιόντι. καίτοι παρὰ τῆς πατρίδος ἤδη μεγάλας δίκας ἀπείληφας, τῇ μητρὶ δ’ οὐδεμίαν χάριν ἀποδέδωκας. ἦν μὲν οὖν ὁσιώτατον ἄνευ τινὸς ἀνάγκης τυχεῖν με παρὰ σοῦ δεομένην οὕτω καλῶν καὶ δικαίων μὴ πείθουσα δὲ τί φείδομαι τῆς ἐσχάτης ἐλπίδος; καὶ ταῦτ’ εἰποῦσα προσπίπτει τοῖς ποσὶν αὐτοῦ μετὰ τῆς γυναικὸς ἅμα καὶ τῶν τέκνων. ὁ δὲ Μάρκιος ἀναβοήσας· οἷα εἴργασαί με, ὦ μῆτερ, ἐξανίστησιν αὐτὴν, καὶ τὴν δεξιὰν πιέσας σφόδρα· νενίκηκας, εἶπεν, εὐτυχῆ μὲν τῇ πατρίδι νίκην, ἐμοὶ δ’ ὀλέθριον· ἄπειμι γὰρ ὑπὸ σοῦ μόνης ἡττώμενος. τοῦτο δ’ εἰπὼν, καὶ βραχέα τῇ μητρὶ καὶ τῇ γυναικὶ διαλεχθεὶς ἰδίᾳ, τὰς μὲν ἀπέπεμψεν εἰς Ῥώμην πάλιν αὐτὰς δεομένας, τῆς δὲ νυκτὸς παρελθούσης ἀπήγαγεν Οὐολούσκους, οὐ τὸν αὐτὸν τρόπον οὐδ’ ὁμοίως διακειμένους ἅπαντας. οἱ μὲν γὰρ ἐμέμφοντο καὶ τὸν ἄνδρα καὶ τὴν πρᾶξιν, οἱ δὲ οὐδέτερα, πρὸς διάλυσιν καὶ εἰρήνην οἰκείως ἔχοντες, ἔνιοι δὲ δυσχεραίνοντες τὰ πραττόμενα τὸν Μάρκιον ὅμως οὐ πονηρὸν ἐνόμιζον, ἀλλὰ συγγνωστόν ἐπικλασθέντα τηλικαύταις ἀνάγκαις. ἀντεῖπε δ’ οὐδείς, ἀλλὰ πάντες εἵποντο, τὴν ἀρετὴν μᾶλλον αὐτοῦ θαυμάζοντες ἢ τὴν ἐξουσίαν.", "st": "Cor. 36.1"}, {"sp": "N", "t": "ὁ δὲ Ῥωμαίων δῆμος ἐν ὅσῳ φόβῳ καί κινδύνῳ καθειστήκει τοῦ πολέμου παρόντος, αἴσθησιν παρέσχε μᾶλλον λυθέντος. ἅμα γὰρ ἀφεώρων τοὺς Οὐολούσκους ἀναζευγνύοντας οἱ περὶ τὰ τείχη, καί πᾶν εὐθὺς ἱερὸν ἀνεῴγει στεφανηφορούντων ὥσπερ ἐπὶ νίκῃ καί θυόντων. μάλιστα δὲ τῇ περὶ τὰς γυναῖκας ἀγαπήσει καί τιμῇ τῆς τε βουλῆς τοῦ τε πλήθους ἅπαντος ἔνδηλος ἦν ἡ χαρὰ τῆς πόλεως, καί λεγόντων καί νομιζόντων γεγονέναι τῆς σωτηρίας περιφανῶς ἐκείνας αἰτίας. ψηφισαμένης δὲ τῆς βουλῆς, ὅ τι ἂν αὑταῖς ἀξιώσωσι γενέσθαι πρὸς δόξαν ἢ χάριν, τοῦτο ποιῆσαι καί παρασχεῖν τοὺς ἄρχοντας, οὐδὲν ἠξίωσαν ἄλλο ἢ Τύχης γυναικείας ἱερὸν ἱδρύσασθαι, τὸ μὲν ἀνάλωμα συμβαλόμεναι παρ’ αὑτῶν, ἱερουργίας δὲ καί τιμὰς, ὅσαι θεοῖς πρέπουσι, δημοσίᾳ τῆς πόλεως ἀναλαβούσης. ἐπεὶ δὲ ἡ βουλὴ τὴν μὲν φιλοτιμίαν ἐπῄνεσε, δημοσίαις δὲ δαπάναις ἐποιήσατο τὸν νεὼν καί τὸ ἕδος, οὐδὲν ἧττον αὐταὶ χρήματα συνεισενεγκοῦσαι δεύτερον ἄγαλμα κατεσκεύασαν, ὃ δὴ καί φασι Ῥωμαῖοι καθιστάμενον ἐν τῷ ἱερῷ φθέγξασθαί τι τοιοῦτον· θεοφιλεῖ με θεσμῷ γυναῖκες δεδώκατε.", "st": "Cor. 37.1"}, {"sp": "N", "t": "ταύτην καὶ δὶς γενέσθαι τὴν φωνὴν μυθολογοῦσιν, ἀγενήτοις ὅμοια καὶ χαλεπὰ πεισθῆναι πείθοντες ἡμᾶς. ἰδίοντα μὲν γὰρ ἀγάλματα φανῆναι καὶ δακρυρροοῦντα καί τινας μεθιέντα νοτίδας αἱματώδεις οὐκ ἀδύνατόν ἐστι καὶ γὰρ ξύλα καὶ λίθοι πολλάκις μὲν εὐρῶτα συνάγουσι γόνιμον ὑγρότητος, πολλὰς δὲ χροιὰς ἀνιᾶσιν ἐξ ἑαυτῶν, καὶ δέχονται βαφὰς ἐκ τοῦ περιέχοντος, οἷς ἔνια σημαίνειν τὸ δαιμόνιον οὐδὲν ἂν δόξειε κωλύειν. δυνατὸν δὲ καὶ μυγμῷ καὶ στεναγμῷ ψόφον ὅμοιον ἐκβάλλειν ἀγάλματα κατὰ ῥῆξιν ἢ διάστασιν μορίων βιαιοτέραν ἐν βάθει γενομένην ἔναρθρον δὲ φωνὴν καὶ διάλεκτον οὕτω σαφῆ καὶ περιττὴν καὶ ἀρτίστομον ἐν ἀψύχῳ γενέσθαι παντάπασιν ἀμήχανον, εἰ μηδὲ τὴν ψυχὴν καὶ τὸν θεὸν ἄνευ σώματος ὀργανικοῦ καὶ διηρμοσμένου μέρεσι λογικοῖς γέγονεν ἠχεῖν καὶ διαλέγεσθαι. ὅπου δ’ ἡμᾶς ἡ ἱστορία πολλοῖς ἀποβιάζεται καὶ πιθανοῖς μάρτυσιν, ἀνόμοιον αἰσθήσει πάθος ἐγγινόμενον τῷ φανταστικῷ τῆς ψυχῆς συναναπείθει τὸ δόξαν, ὥσπερ ἐν ὕπνοις ἀκούειν οὐκ ἀκούοντες καὶ βλέπειν οὐ βλέποντες δοκοῦμεν. οὐ μὴν ἀλλὰ τοῖς ὑπ’ εὐνοίας καὶ φιλίας πρὸς τὸν θεὸν ἄγαν ἐμπαθῶς ἔχουσι, καὶ μηδὲν ἀθετεῖν μηδ’ ἀναίνεσθαι τῶν τοιούτων δυναμένοις, μέγα πρὸς πίστιν ἐστὶ τὸ θαυμάσιον καὶ μὴ καθ’ ἡμᾶς τῆς τοῦ θεοῦ δυνάμεως. οὐδὲν γὰρ οὐδαμῶς ἀνθρωπίνῳ προσέοικεν οὔτε φύσιν οὔτε κίνησιν οὔτε τέχνην οὔτ’ ἰσχύν, οὐδ’ εἴ τι ποιεῖ τῶν ἡμῖν ἀποιήτων καὶ μηχανᾶται τῶν ἀμηχάνων, παράλογόν ἐστιν, ἀλλὰ μᾶλλον ἐν πᾶσι διαφέρων πολύ μάλιστα τοῖς ἔργοις ἀνόμοιός ἐστι καὶ παρηλλαγμένος. ἀλλὰ τῶν μὲν θείων τὰ πολλά, καθ’ Ἡράκλειτον, ἀπιστίῃ διαφυγγάνει μὴ γινώσκεσθαι.", "st": "Cor. 38.1"}, {"sp": "N", "t": "τὸν δὲ Μάρκιον, ὡς ἐπανῆλθεν εἰς τὸ Ἄντιον ἀπὸ τῆς στρατείας, μισῶν πάλαι καὶ βαρυνόμενος διὰ φθόνον ὁ Τύλλος ἐπεβούλευεν ἀνελεῖν εὐθύς, ὡς εἰ νῦν διαφύγοι, λαβὴν ἑτέραν οὐ παρέξοντα. πολλοὺς δὲ συστήσας καὶ παρασκευάσας ἐπ’ αὐτόν ἐκέλευσεν εὐθύνας ὑποσχεῖν τοῖς Οὐολούσκοις, ἀποδόντα τὴν ἀρχήν. ὁ δὲ φοβούμενος ἰδιώτης γενέσθαι τοῦ Τύλλου στρατηγοῦντος καὶ δυναμένου μέγιστον ἐν τοῖς ἑαυτοῦ πολίταις, ἔλεγε τὴν ἀρχὴν ἀποδώσειν Οὐολούσκοις, ἐὰν κελεύωσι, καὶ γὰρ λαβεῖν πάντων κελευόντων, εὐθύνας δὲ διδόναι καὶ λόγον οὐδὲ νῦν παραιτεῖσθαι τοῖς βουλομένοις Ἀντιατῶν. γενομένης οὖν ἐκκλησίας, οἱ παρεσκευασμένοι τῶν δημαγωγῶν ἀνιστάμενοι παρώξυνον τὸ πλῆθος. ἐπεὶ δ’ ἀναστάντι τῷ Μαρκίῳ τὸ μὲν ἄγαν θορυβοῦν ὑπ’ αἰδοῦς ἐνεδίδου καὶ παρεῖχεν ἀδεῶς λέγειν, οἱ δὲ βέλτιστοι καὶ μάλιστα χαίροντες εἰρήνῃ τῶν Ἀντιατῶν ἐγένοντο φανεροὶ μετ’ εὐνοίας ἀκουσόμενοι καὶ δικαίως κρινοῦντες, ἔδεισεν ὁ Τύλλος τὴν ἀπολογίαν τοῦ ἀνδρός. ἦν γὰρ ἐν τοῖς μάλιστα δεινὸς εἰπεῖν, καὶ τὰ πρόσθεν ἔργα μείζονα τὴν χάριν εἶχε τῆς ὕστερον αἰτίας, μᾶλλον δ’ ὅλως τὸ ἔγκλημα τοῦ μεγέθους τῆς χάριτος ἦν μαρτύριον. οὐ γὰρ ἂν ἔδοξαν ἀδικεῖσθαι τὴν Ῥώμην ὑποχείριον μὴ λαβόντες, εἰ μὴ τοῦ λαβεῖν ἐγγὺς ἐγένοντο διὰ Μάρκιον.", "st": "Cor. 39.1"}, {"sp": "N", "t": "οὐκέτ’ οὖν ἔδοξε διαμέλλειν οὐδὲ πειρᾶσθαι τῶν πολλῶν, ἀλλ’ ἐγκραγόντες οἱ θρασύτατοι τῶν συνεστώτων ὡς οὐκ ἔστιν ἀκουστέον οὐδὲ περιοπτέον Οὐολούσκοις τὸν προδότην τυραννοῦντα καὶ μὴ κατατιθέμενον τὴν ἀρχήν, προσπεσόντες ἀθρόοι διέφθειραν αὐτόν, καὶ προσήμυνεν οὐδεὶς τῶν παρόντων. ὅτι δὲ τοῖς πλείστοις οὐκ ἐπράχθη κατὰ γνώμην, ἐδήλωσαν αὐτίκα συνδραμόντες ἐκ τῶν πόλεων ἐπὶ τὸ σῶμα καὶ θάψαντες ἐντίμως καὶ τὸν τάφον ὅπλοις καὶ λαφύροις κοσμήσαντες ὡς ἀριστέως καὶ στρατηγοῦ. Ῥωμαῖοι δὲ τὴν τελευτὴν πυθόμενοι, ἄλλο μὲν οὐδὲν ἀπεδείξαντο σημεῖον οὔτε τιμῆς οὔτ’ ὀργῆς πρὸς αὐτόν, αἰτησαμέναις δὲ ταῖς γυναιξὶν ἐπέτρεψαν ἀποπενθῆσαι δέκα μῆνας, ὥσπερ ἔθος ἦν ἑκάστῃ πατέρα καὶ παῖδα καὶ ἀδελφόν. οὗτος γὰρ ἦν ὅρος τοῦ μακροτάτου πένθους, ὃν ὥρισε Νομᾶς Πομπίλιος, ὡς ἐν τοῖς περὶ ἐκείνου γεγραμμένοις δεδήλωται.", "st": "Cor. 39.5"}, {"sp": "N", "t": "τὸν δὲ Μάρκιον εὐθὺς ἐπόθει τὰ Οὐολούσκων πράγματα, πρῶτον μὲν γὰρ στασιάσαντες πρὸς Αἰκανοὺς συμμάχους καὶ φίλους ὄντας ὑπὲρ ἡγεμονίας, ἄχρι τραυμάτων καὶ φόνων προῆλθον ἔπειτα μάχῃ κρατηθέντες ὑπὸ Ῥωμαίων, ἐν ᾗ Τύλλος ἀπέθανε καὶ τὸ ἀνθοῦν μάλιστα τῆς δυνάμεως διεφθάρη, διαλύσεις αἰσχίστας ἠγάπησαν ὑπήκοοι γενόμενοι, καὶ τὸ προσταττόμενον αὐτοῖς ποιήσειν ὁμολογήσαντες.", "st": "Cor. 39.6"}, {"sp": "HDR", "t": "Ἀλκιβιάδου καὶ Κοριολάνου σύγκρισις"}, {"sp": "N", "t": "ἐκκειμένων δὲ τῶν πράξεων, ὅσας ἡγούμεθα λόγου καὶ μνήμης ἀξίας εἶναι, τὰς μὲν πολεμικὰς ἐπ’ οὐδέτερον ποιούσας ῥοπὴν μεγάλην ὁρᾶν ἐστιν, ὁμαλῶς γὰρ ἀμφότεροι πολλὰ μὲν στρατιωτικῆς ἔργα τόλμης καὶ ἀνδρείας, πολλὰ δὲ καὶ τέχνης καὶ προνοίας στρατηγοῦντες ἐπεδείξαντο, πλὴν εἰ μή τις θέλοι τὸν Ἀλκιβιάδην, ὅτι καὶ κατὰ γῆν καὶ κατὰ θάλατταν ἐν πολλοῖς ἀγῶσι νικῶν καὶ κατορθῶν διετέλεσεν, ἀποφαίνειν τελειότερον στρατηγόν ἐπεὶ τό γε παρόντας καὶ ἄρχοντας ὀρθοῦν ἀεὶ προδήλως τὰ οἰκεῖα καὶ προδηλότερον αὖ πάλιν βλάπτειν μεθισταμένους ἀμφοτέροις ὑπῆρξε. πολιτείαν δὲ τὴν μὲν Ἀλκιβιάδου τὴν ἄγαν λαμυρὰν καὶ τὸ μὴ καθαρεῦον ἀναγωγίας καὶ βωμολοχίας ἐν τῷ πρὸς χάριν ὁμιλεῖν τοῖς πολλοῖς οἱ σώφρονες ἐβδελύττοντο, τὴν δὲ Μαρκίου παντάπασιν ἄχαριν καὶ ὑπερήφανον καὶ ὀλιγαρχικὴν γενομένην ἐμίσησεν ὁ Ῥωμαίων δῆμος. οὐδετέραν μὲν οὖν ἐπαινετέον ὁ δὲ δημαγωγῶν καὶ χαριζόμενος τῶν ὅπως οὐ δόξουσι δημαγωγεῖν προπηλακιζόντων τοὺς πολλοὺς ἀμεμπτότερος· αἰσχρὸν μὲν γὰρ τὸ κολακεύειν δῆμον ἐπὶ τῷ δύνασθαι, τὸ δ’ ἰσχύειν ἐκ τοῦ φοβερὸν εἶναι καὶ κακοῦν καὶ πιέζειν πρὸς τῷ αἰσχρῷ καὶ ἄδικόν ἐστιν.", "st": "Comp. Alc.–Cor. 1.1"}, {"sp": "N", "t": "ὅτι τοίνυν ἁπλοῦς τις ὁ Μάρκιος ὑπείληπται τῷ τρόπῳ γεγονέναι καὶ αὐθέκαστος, ὁ δὲ Ἀλκιβιάδης πανοῦργος ἐν τῇ πολιτείᾳ καὶ ἀναλήθης, οὐκ ἄδηλόν ἐστι. μάλιστα δὲ κατηγοροῦσιν αὐτοῦ κακοήθειαν καὶ ἀπάτην, ᾗ τοὺς Λακεδαιμονίων πρέσβεις παρακρουσάμενος, ὡς Θουκυδίδης ἱστόρηκε, τὴν εἰρήνην ἔλυσεν. ἀλλ’ αὕτη μὲν ἡ πολιτείᾳ, καίπερ εἰς πόλεμον αὖθις ἐμβαλοῦσα τὴν πόλιν, ἰσχυρὰν ἐποίησε καὶ φοβερὰν, τῆς Μαντινέων καὶ Ἀργείων συμμαχίας δι’ Ἀλκιβιάδου προσγενομένης· Μάρκιος δ’ ὅτι μὲν ἀπάτῃ καὶ αὐτὸς ἐξεπολέμωσε Ῥωμαίους καὶ Οὐολούσκους διαβαλὼν ψευδῶς τοὺς ἥκοντας ἐπὶ τὴν θέαν, Διονύσιος ἱστόρηκεν ἡ δ’ αἰτία φαυλότερον ποιεῖ τὸ ἔργον. οὐ γὰρ ἐκ φιλονεικίας οὐδὲ πολιτικῆς μάχης ἢ ἁμίλλης, ὡς ἐκεῖνος, ἀλλ’ ὀργῇ χαριζόμενος, παρ’ ἧς οὐδένα φησὶν ὁ Δίων ἀπολαβεῖν χάριν, πολλὰ τῆς Ἰταλίας μέρη συνετάραξε καὶ πολλὰς πόλεις οὐδὲν ἀδικούσας τῷ πρὸς τὴν πατρίδα θυμῷ παρανάλωσε.", "st": "Comp. Alc.–Cor. 2.1"}, {"sp": "N", "t": "καίτοι καὶ Ἀλκιβιάδης δι’ ὀργὴν μεγάλων αἴτιος συμφορῶν κατέστη τοῖς πολίταις. ἀλλ’ ὅτε πρῶτον ἔγνω μεταμελομένους, εὐγνωμόνησε, καὶ πάλιν ἀπορριφείς οὐκ ἐφήσθη τοῖς στρατηγοῖς ἁμαρτάνουσιν οὐδὲ παρεῖδε κακῶς βουλευομένους καὶ κινδυνεύοντας, ἀλλ’, ὅπερ Ἀριστείδης ἐπαινεῖται μάλιστα πράξας πρὸς Θεμιστοκλέα, τοῦτ’ ἐποίησε, πρὸς τοὺς τότ’ ἄρχοντας οὐ φίλους ὄντας ἐλθὼν καὶ φράσας τὸ δέον καὶ διδάξας. Μάρκιος δὲ πρῶτον μὲν ὅλην κακῶς ἐποίει τὴν πόλιν οὐχ ὑφ’ ὅλης παθών, ἀλλὰ τοῦ βελτίστου καὶ κρατίστου μέρους συναδικηθέντος αὐτῷ καὶ συναλγήσαντος· ἔπειτα πολλαῖς πρεσβείαις καὶ δεήσεσι μίαν ἰωμένων ὀργὴν καὶ ἄγνοιαν οὐ τεγχθεὶς οὐδ’ εἴξας ἐδήλωσεν ἐπὶ τῷ διαφθεῖραι τὴν πατρίδα καὶ καταβαλεῖν, οὐχ ὅπως ἀπολάβῃ καὶ κατέλθῃ, βαρὺν πόλεμον καὶ ἄσπονδον ἐπανῃρημένος. τούτῳ δὲ φήσει τις διαφέρειν Ἀλκιβιάδην μὲν γὰρ ἐπιβουλευόμενον ὑπὸ Σπαρτιατῶν διὰ δέος ἅμα καὶ μῖσος αὐτῶν μεταστῆναι πρὸς Ἀθηναίους, Μαρκίῳ δὲ πάντα δίκαια ποιοῦντας Οὐολούσκους οὐ καλῶς εἶχεν ἐγκαταλιπεῖν. καὶ γὰρ ἡγεμὼν ἀποδέδεικτο καὶ μεγίστην πίστιν εἶχε μετὰ δυνάμεως, οὐχ ὡς ἐκεῖνος, ἀποχρωμένων μᾶλλον ἢ χρωμένων αὐτῷ Λακεδαιμονίων, ἐν τῇ πόλει περιιών καὶ κυλινδούμενος αὖθις ἐν τῷ στρατοπέδῳ τέλος εἰς τὰς Τισαφέρνου χεῖρας ἀφῆκεν αὑτόν· εἰ μὴ νὴ Δία μὴ φθαρῆναι τὰς Ἀθήνας παντάπασι ποθῶν κατελθεῖν ἐθεράπευε.", "st": "Comp. Alc.–Cor. 2.4"}, {"sp": "N", "t": "χρήματα τοίνυν ὁ μέν Ἀλκιβιάδης καὶ λαβεῖν οὐκ εὖ πολλάκις ἐκ δωροδοκιῶν καὶ διαθέσθαι κακῶς εἰς τρυφὴν καὶ ἀκολασίαν ἱστόρηται· Μάρκιον δὲ σὺν τιμῇ διδόντες οἱ στρατηγοὶ λαβεῖν οὐκ ἔπεισαν. διὸ καὶ μάλιστα τοῖς πολλοῖς ἐπαχθὴς ἦν ἐν ταῖς περὶ χρεῶν διαφοραῖς πρὸς τὸν δῆμον, ὡς οὐκ ἐπὶ κέρδεσιν, ἀλλὰ δι’ ὕβριν καὶ περιφροσύνην τοῖς πένησιν ἐπηρεάζων.", "st": "Comp. Alc.–Cor. 3.1"}, {"sp": "N", "t": "Ἀντίπατρος μέν οὖν ἐν ἐπιστολῇ τινι γράφων περὶ τῆς Ἀριστοτέλους τοῦ φιλοσόφου τελευτῆς, πρὸς τοῖς ἄλλοις, φησὶν, ὁ ἀνὴρ καὶ τὸ πείθειν εἶχε. τὰς δὲ Μαρκίου πράξεις καὶ ἀρετὰς τοῦτο μὴ προσὸν ἐπαχθεῖς ἐποίησεν αὐτοῖς τοῖς εὖ παθοῦσι, τὸν ὄγκον αὐτοῦ καὶ τὴν ἐρημίᾳ σύνοικον, ὡς Πλάτων εἶπεν, αὐθάδειαν μὴ ὑπομείναντας … τοῦ δ’ Ἀλκιβιάδου τοὐναντίον ἐπισταμένου χρῆσθαι τοῖς προστυγχάνουσιν οἰκείως, οὐδὲν θαυμαστὸν ἐν οἷς κατώρθου τὴν δόξαν ἀνθεῖν μετ’ εὐνοίας καὶ τιμῆς εὐημεροῦσαν, ὅπου καὶ τῶν ἁμαρτημάτων ἔνια πολλάκις χάριν εἶχε καὶ ὥραν. ὅθεν οὗτος μέν οὐ μικρὰ βλάψας οὐδ’ ὀλίγα τὴν πόλιν ὅμως ἀπεδείκνυτο πολλάκις ἡγεμὼν καὶ στρατηγός, ἐκεῖνος δὲ μετιὼν ἐπὶ πολλαῖς ἀριστείαις καὶ ἀνδραγαθίαις ἀρχὴν προσήκουσαν ἐξέπεσεν. οὕτω τὸν μέν οὐδὲ πάσχοντες κακῶς ἐδύναντο μισεῖν οἱ πολῖται, τῷ δὲ περιῆν θαυμαζομένῳ μὴ φιλεῖσθαι.", "st": "Comp. Alc.–Cor. 3.2"}, {"sp": "N", "t": "καὶ γάρ τοι Μάρκιος μὲν οὐδὲν ἀπεδείξατο τῇ πόλει στρατηγῶν, ἀλλά τοῖς πολεμίοις κατὰ τῆς πατρίδος· Ἀλκιβιάδου δὲ καὶ στρατευομένου πολλάκις καὶ στρατηγοῦντος ἀπέλαυσαν οἱ Ἀθηναῖοι καὶ παρὼν ἐκράτει τῶν ἐχθρῶν ὅσον ἐβούλετο, καὶ μὴ παρόντος ἴσχυσαν αἱ διαβολαί· Μάρκιος δὲ παρὼν ὑπὸ Ῥωμαίων κατεδικάσθη, παρόντα δὲ Οὐολοῦσκοι διέφθειραν, οὐ δικαίως μὲν οὐδ’ ὁσίως, αἰτίαν δὲ τοῦ εὐλόγου παρέσχεν αὐτός, ὅτι δημοσίᾳ τὰς διαλύσεις μὴ προσδεξάμενος, ἰδίᾳ δὲ πεισθεὶς ὑπὸ τῶν γυναικῶν οὐκ ἔλυσε τὴν ἔχθραν, ἀλλὰ τοῦ πολέμου μένοντος ἀπώλεσε τὸν καιρὸν καὶ διέφθειρε. πείσαντα γὰρ ἔδει τοὺς πεπιστευκότας ἀπελθεῖν, εἰ τοῦ πρὸς ἐκείνους δικαίου πλεῖστον ἐποιεῖτο λόγον. εἰ δὲ μηδὲν ἐφρόντιζεν Οὐολούσκων, ἀλλὰ τὴν ὀργὴν ἐμπλῆσαι τὴν ἑαυτοῦ βουλόμενος ἐνῆγε τὸν πόλεμον, εἶτ’ ἔληξεν, οὐ διὰ τὴν μητέρα καλῶς εἶχε φείσασθαι τῆς πατρίδος, ἀλλὰ σὺν τῇ πατρίδι τῆς μητρός· μέρος γὰρ ἦν καὶ ἡ μήτηρ καὶ ἡ γυνὴ τῆς πατρίδος ἦν ἐπολιόρκει. τὸ δὲ δημοσίαις ἱκεσίαις καὶ δεήσει πρέσβεων καὶ λιταῖς ἱερέων ἀπηνῶς χρησάμενον εἶτα χαρίσασθαι τῇ μητρὶ τὴν ἀναχώρησιν, οὐ τῆς μητρὸς ἦν τιμὴ, ἀλλ’ ἀτιμία τῆς πατρίδος, οἴκτῳ καὶ παραιτήσει διὰ μίαν γυναῖκα σῳζομένης, ὡς οὐκ ἀξίας σῴζεσθαι δι’ αὑτήν, ἐπίφθονος γὰρ ἡ χάρις καὶ ὠμὴ καὶ ἀχάριστος ἀληθῶς καὶ πρὸς οὐδετέρους ἔχουσα τὸ εὔγνωμον· ἀνεχώρησε γὰρ μήτε πεισθεὶς ὑπὸ τῶν πολεμουμένων μήτε πείσας τοὺς συμπολεμοῦντας.", "st": "Comp. Alc.–Cor. 4.1"}, {"sp": "N", "t": "ὧν αἴτιον ἁπάντων τὸ ἀνομίλητον τοῦ τρόπου καὶ λίαν ὑπερήφανον καὶ αὔθαδες, ὃ καθ’ αὑτὸ μὲν ἐπαχθές ἐστι τοῖς πολλοῖς, τῷ δὲ φιλοτίμῳ προσὸν γίνεται παντάπασιν ἄγριον καὶ ἀπαραίτητον. οὐ γὰρ θεραπεύουσι τοὺς πολλοὺς ὡς μὴ δεόμενοι τιμῆς, εἶτα χαλεπαίνουσι μὴ τυγχάνοντες. ἐπεὶ τό γε μὴ λιπαρῆ μηδὲ θεραπευτικὸν ὄχλων εἶναι καὶ Μέτελλος εἶχε καὶ Ἀριστείδης καὶ Ἐπαμεινώνδας· ἀλλὰ τῷ καταφρονεῖν ἀληθῶς ὧν δῆμός ἐστι καὶ δοῦναι καὶ ἀφελέσθαι κύριος, ἐξοστρακιζόμενοι καὶ ἀποχειροτονούμενοι καὶ καταδικαζόμενοι πολλάκις οὐκ ὠργίζοντο τοῖς πολίταις ἀγνωμονοῦσιν, ἀλλ’ ἠγάπων αὖθις μεταμελομένους καὶ διηλλάττοντο παρακαλούντων. τὸν γὰρ ἥκιστα θεραπευτικὸν ἥκιστα πρέπει τιμωρητικὸν εἶναι τῶν πολλῶν, ὡς τὸ χαλεπαίνειν μάλιστα μὴ τυγχάνοντα τῆς τιμῆς ἐκ τοῦ σφόδρα γλίχεσθαι φυόμενον.", "st": "Comp. Alc.–Cor. 4.5"}, {"sp": "N", "t": "Ἀλκιβιάδης μὲν οὖν οὐκ ἠρνεῖτο τιμώμενος χαίρειν καὶ δυσφορεῖν παρορώμενος, ὅθεν ἐπειρᾶτο προσφιλὴς εἶναι τοῖς παροῦσι καὶ κεχαρισμένος· Μάρκιον δὲ θεραπεύειν μὲν οὐκ εἴα τοὺς τιμᾶν δυναμένους καὶ αὔξειν τὸ ὑπερήφανον, ὀργὴν δὲ καὶ λύπην ἀμελουμένῳ τὸ φιλότιμον παρεῖχε. καὶ ταῦτ’ ἔστιν ἅ τις ἂν αἰτιάσαιτο τοῦ ἀνδρός· τὰ δ’ ἄλλα πάντα λαμπρά, σωφροσύνης δὲ καὶ χρημάτων ἐγκρατείας ἕνεκα τοῖς ἀρίστοις καὶ καθαρωτάτοις τῶν Ἑλλήνων ἄξιον αὐτὸν παραβάλλειν, οὐκ Ἀλκιβιάδῃ μὰ Δία τῷ θρασυτάτῳ περὶ ταῦτα καὶ ὀλιγωροτάτῳ τοῦ καλοῦ γενομένῳ.", "st": "Comp. Alc.–Cor. 5.1"}, {"sp": "HDR", "t": "Τιμολέων"}, {"sp": "N", "t": "ἐμοὶ τῆς τῶν βίων ἅψασθαι μὲν γραφῆς συνέβη δι’ ἑτέρους, ἐπιμένειν δὲ καὶ φιλοχωρεῖν ἤδη καὶ δι’ ἐμαυτόν, ὥσπερ ἐν ἐσόπτρῳ τῇ ἱστορίᾳ πειρώμενον ἁμῶς γέ πως κοσμεῖν καὶ ἀφομοιοῦν πρὸς τὰς ἐκείνων ἀρετὰς τὸν βίον. οὐδὲν γὰρ ἀλλ’ ἢ συνδιαιτήσει καὶ συμβιώσει τὸ γινόμενον ἔοικεν, ὅταν ὥσπερ ἐπιξενούμενον ἕκαστον αὐτῶν ἐν μέρει διὰ τῆς ἱστορίας ὑποδεχόμενοι καὶ παραλαμβάνοντες ἀναθεωρῶμεν ὅσσος ἔην οἷός τε, τὰ κυριώτατα καὶ κάλλιστα πρὸς γνῶσιν ἀπὸ τῶν πράξεων λαμβάνοντες.", "st": "Tim. pr. 1"}, {"sp": "N", "t": "φεῦ, φεῦ· τί τούτου χάρμα μεῖζον ἂν λάβοις,<br>καὶ πρὸς ἐπανόρθωσιν ἠθῶν ἐνεργότερον;", "st": "Tim. pr. 3"}, {"sp": "N", "t": "Δημόκριτος μὲν γὰρ εὔχεσθαί φησι δεῖν ὅπως εὐλόγχων εἰδώλων τυγχάνωμεν καὶ τὰ σύμφυλα καὶ τὰ χρηστὰ μᾶλλον ἡμῖν ἐκ τοῦ περιέχοντος ἢ τὰ φαῦλα καὶ τὰ σκαιὰ συμφέρηται, λόγον οὔτ’ ἀληθῆ καὶ πρὸς ἀπεράντους ἐκφέροντα δεισιδαιμονίας εἰς φιλοσοφίαν καταβάλλων· ἡμεῖς δὲ τῇ περὶ τὴν ἱστορίαν διατριβῇ καὶ τῆς γραφῆς τῇ συνηθείᾳ παρασκευάζομεν ἑαυτούς, τὰς τῶν ἀρίστων καὶ δοκιμωτάτων μνήμας ὑποδεχομένους ἀεὶ ταῖς ψυχαῖς, εἴ τι φαῦλον ἢ κακόηθες ἢ ἀγεννὲς αἱ τῶν συνόντων ἐξ ἀνάγκης ὁμιλίαι προσβάλλουσιν, ἐκκρούειν καὶ διωθεῖσθαι, πρὸς τὰ κάλλιστα τῶν παραδειγμάτων ἵλεω καὶ πρᾳεῖαν ἀποστρέφοντες τὴν διάνοιαν. ὧν ἐν τῷ παρόντι προκεχειρίσμεθά σοι τὸν Τιμολέοντος τοῦ Κορινθίου καὶ τὸν Αἰμιλίου Παύλου βίον, ἀνδρῶν οὐ μόνον ταῖς αἱρέσεσιν, ἀλλὰ καὶ ταῖς τύχαις ἀγαθαῖς ὁμοίως κεχρημένων ἐπὶ τὰ πράγματα, καὶ διαμφισβήτησιν παρεξόντων πότερον εὐποτμίᾳ, μᾶλλον ἢ φρονήσει τὰ μέγιστα τῶν πεπραγμένων κατώρθωσαν.", "st": "Tim. pr. 4"}, {"sp": "N", "t": "τὰ μὲν Συρακοσίων πράγματα πρὸ τῆς Τιμολέοντος εἰς Σικελίαν ἀποστολῆς οὕτως εἶχεν. ἐπεὶ Δίων μὲν ἐξελάσας Διονύσιον τὸν τύραννον εὐθὺς ἀνῃρέθη δόλῳ καὶ διέστησαν οἱ σὺν Δίωνι Συρακοσίους ἐλευθερώσαντες, ἡ δὲ πόλις ἄλλον ἐξ ἄλλου μεταβάλλουσα συνεχῶς τύραννον ὑπὸ πλήθους κακῶν μικρὸν ἀπέλειπεν ἔρημος εἶναι, τῆς δ’ ἄλλης Σικελίας ἡ μὲν ἀνάστατος καὶ ἄπολις παντάπασιν ἤδη διὰ τοὺς πολέμους ὑπῆρχεν, αἱ δὲ πλεῖσται πόλεις ὑπὸ βαρβάρων μιγάδων καὶ στρατιωτῶν ἀμίσθων κατείχοντο, ῥᾳδίως προσιεμένων τὰς μεταβολὰς τῶν δυναστειῶν, Διονύσιος ἔτει δεκάτῳ ξένους συναγαγὼν καὶ τὸν τότε κρατοῦντα τῶν Συρακοσίων Νυσαῖον ἐξελάσας, ἀνέλαβε τὰ πράγματα πάλιν καὶ καθειστήκει τύραννος ἐξ ἀρχῆς, παραλόγως μὲν ὑπὸ μικρᾶς δυνάμεως τὴν μεγίστην τῶν πώποτε τυραννίδων ἀπολέσας, παραλογώτερον δ’ αὖθις ἐκ φυγάδος καὶ ταπεινοῦ τῶν ἐκβαλόντων κύριος γενόμενος. οἱ μὲν οὖν ὑπομείναντες ἐν τῇ πόλει τῶν Συρακοσίων ἐδούλευον οὔτ’ ἄλλως ἐπιεικεῖ τυράννῳ καὶ τότε παντάπασιν ὑπὸ συμφορῶν ἀπηγριωμένῳ τὴν ψυχήν, οἱ δὲ βέλτιστοι καὶ γνωριμώτατοι πρὸς Ἱκέτην τραπέντες τὸν δυναστεύοντα τῶν Λεοντίνων ἐπέτρεψαν αὑτοὺς ἐκείνῳ καὶ στρατηγὸν εἵλοντο τοῦ πολέμου, βελτίω μὲν οὐδενὸς ὄντα τῶν ὁμολογουμένως τυράννων, ἑτέραν δ’ οὐκ ἔχοντες ἀποστροφὴν, καὶ πιστεύσαντες Συρακουσίῳ τὸ γένος ὄντι καὶ κεκτημένῳ δύναμιν ἀξιόμαχον πρὸς τὸν τύραννον.", "st": "Tim. 1.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Καρχηδονίων στόλῳ μεγάλῳ παραγενομένων εἰς Σικελίαν καὶ τοῖς πράγμασιν ἐπαιωρουμένων φοβηθέντες οἱ Σικελιῶται πρεσβείαν ἐβούλοντο πέμπειν εἰς τὴν Ἑλλάδα καὶ παρὰ Κορινθίων βοήθειαν αἰτεῖν, οὐ μόνον διὰ τὴν συγγένειαν οὐδ’ ἀφ’ ὧν ἤδη πολλάκις εὐεργέτηντο πιστεύοντες ἐκείνοις, ἀλλὰ καὶ καθόλου τὴν πόλιν ὁρῶντες φιλελεύθερον καὶ μισοτύραννον οὖσαν ἀεί, καὶ τῶν πολέμων τοὺς πλείστους καὶ μεγίστους πεπολεμηκυῖαν οὐχ ὑπὲρ ἡγεμονίας καὶ πλεονεξίας, ἀλλ’ ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας. ὁ δ’ Ἱκέτης, ἅτε δὴ τῆς στρατηγίας ὑπόθεσιν τὴν τυραννίδα πεποιημένος, οὐ τὴν Συρακουσίων ἐλευθερίαν, κρύφα μὲν ἤδη πρὸς τοὺς Καρχηδονίους διείλεκτο, φανερῶς δὲ τοὺς Συρακουσίους ἐπῄνει καὶ τοὺς πρέσβεις εἰς Πελοπόννησον συνεξέπεμψεν, οὐ βουλόμενος ἐλθεῖν συμμαχίαν ἐκεῖθεν, ἀλλ’ ἐάν, ὅπερ εἰκὸς ἦν, οἱ Κορίνθιοι διὰ τὰς Ἑλληνικὰς ταραχὰς καὶ ἀσχολίας ἀπείπωσι τὴν βοήθειαν, ἐλπίζων ῥᾷον ἐπὶ τοὺς Καρχηδονίους τὰ πράγματα μετάξειν καὶ χρήσεσθαι συμμάχοις καὶ συναγωνισταῖς ἐκείνοις ἐπὶ τοὺς Συρακουσίους ἢ κατὰ τοῦ τυράννου, ταῦτα μὲν οὖν ὀλίγον ὕστερον ἐξηλέγχθη.", "st": "Tim. 2.1"}, {"sp": "N", "t": "τῶν δὲ πρέσβεων παραγενομένων, οἱ Κορίνθιοι, κήδεσθαι μὲν ἀεὶ τῶν ἀποικίδων πόλεων καὶ μάλιστα τῆς Συρακουσίων εἰωθότες, οὐδενὸς δ’ αὐτοὺς τότε τῶν Ἑλληνικῶν κατὰ τύχην παρενοχλοῦντος, ἀλλ’ ἐν εἰρήνῃ καὶ σχολῇ διάγοντες, ἐψηφίσαντο προθύμως βοηθεῖν. ζητουμένου δὲ στρατηγοῦ καὶ τῶν ἀρχόντων γραφόντων καὶ προβαλλομένων τοὺς εὐδοκιμεῖν ἐν τῇ πόλει σπουδάζοντας, εἷς ἐκ τῶν πολλῶν ἀναστὰς ὠνόμασε Τιμολέοντα τὸν Τιμοδήμου, μήτε προσιόντα τοῖς κοινοῖς ἔτι μήτε ἐλπίδος τοιαύτης γενόμενον ἢ προαιρέσεως, ἀλλὰ θεοῦ τινος, ὡς ἔοικεν, εἷς νοῦν ἐμβαλόντος τῷ ἀνθρώπῳ· τοσαύτη καὶ περὶ τὴν αἵρεσιν εὐθὺς ἔλαμψε τύχης εὐμένεια καὶ ταῖς ἄλλαις πράξεσιν ἐπηκολούθησε χάρις ἐπικοσμοῦσα τὴν ἀρετὴν τοῦ ἀνδρός.", "st": "Tim. 3.1"}, {"sp": "N", "t": "ἦν μὲν οὖν γονέων ἐπιφανῶν ἐν τῇ πόλει, Τιμοδήμου καὶ Δημαρίστης, φιλόπατρις δὲ καὶ πρᾷος διαφερόντως ὅσα μὴ σφόδρα μισοτύραννος εἶναι καὶ μισοπόνηρος. ἐν δὲ τοῖς πολέμοις οὕτω καλῶς καὶ ὁμαλῶς ἐκέκρατο τὴν φύσιν ὥστε πολλὴν μὲν ἐν νέῳ σύνεσιν, οὐκ ἐλάττω δὲ γηρῶντος ἀνδρείαν ἐπιφαίνεσθαι ταῖς πράξεσιν. ἀδελφὸν δ’ εἶχε Τιμοφάνην, πρεσβύτερον, οὐδὲν αὐτῷ προσόμοιον, ἀλλ’ ἔμπληκτον καὶ διεφθαρμένον ἔρωτι μοναρχίας ὑπὸ φίλων φαύλων καὶ ξένων στρατιωτικῶν ἀεὶ περὶ αὐτὸν ὄντων, ἔχειν τι δοκοῦντα ῥαγδαῖον ἐν ταῖς στρατείαις καὶ φιλοκίνδυνον. ᾧ καὶ τοὺς πολίτας προσαγόμενος ὡς ἀνὴρ πολεμικὸς καὶ δραστήριος ἐφ’ ἡγεμονιῶν ἐτάττετο. καὶ πρὸς ταῦτα Τιμολέων αὐτῷ συνήργει, τὰ μὲν ἁμαρτήματα παντάπασιν ἀποκρύπτων ἢ μικρὰ φαίνεσθαι ποιῶν, ἃ δ’ ἡ φύσις ἐξέφερεν ἀστεῖα κατακοσμῶν καὶ συναύξων.", "st": "Tim. 3.4"}, {"sp": "N", "t": "ἐν δὲ τῇ πρὸς Ἀργείους καὶ Κλεωναίους μάχῃ τῶν Κορινθίων ὁ μὲν Τιμολέων ἔτυχεν ἐν τοῖς ὁπλίταις τεταγμένος, τὸν δὲ Τιμοφάνην τῶν ἱππέων ἡγούμενον καταλαμβάνει κίνδυνος ὀξύς. ὁ γὰρ ἵππος αὐτὸν ἀπεσείσατο πληγῇ περιπεσὼν εἰς τοὺς πολεμίους, καὶ τῶν ἑταίρων οἱ μὲν εὐθὺς ἐσκορπίσθησαν φοβηθέντες, οἱ δὲ παραμείναντες ὀλίγοι πρὸς πολλοὺς μαχόμενοι χαλεπῶς ἀντεῖχον. ὡς οὖν ὁ Τιμολέων κατεῖδε τὸ συμβεβηκός, δρόμῳ προσβοηθήσας καὶ τὴν ἀσπίδα τοῦ Τιμοφάνους κειμένου προθέμενος, καὶ πολλὰ μὲν ἀκοντίσματα, πολλὰς δὲ πληγὰς ἐκ χειρὸς ἀναδεξάμενος εἰς τὸ σῶμα καὶ τὰ ὅπλα, μόλις ἐώσατο τοὺς πολεμίους καὶ διέσωσε τὸν ἀδελφόν.", "st": "Tim. 4.1"}, {"sp": "N", "t": "ἐπεὶ δ’ οἱ Κορίνθιοι δεδιότες μὴ πάθοιεν οἷα καὶ πρότερον ὑπὸ τῶν συμμάχων ἀποβαλόντες τὴν πόλιν, ἐψηφίσαντο τρέφειν ξένους τετρακοσίους καὶ τούτων ἄρχοντα Τιμοφάνην κατέστησαν, ὁ δὲ τῶν καλῶν καὶ δικαίων ὑπεριδὼν εὐθὺς ἐπέραινεν ἐξ ὧν ποιήσεται τὴν πόλιν ὑφ’ αὐτῷ, καὶ συχνοὺς ἀνελὼν ἀκρίτους τῶν πρώτων πολιτῶν ἀνέδειξεν αὐτὸς ἑαυτὸν τύραννον, βαρέως φέρων ὁ Τιμολέων, καὶ συμφορὰν ποιούμενος ἑαυτοῦ τὴν ἐκείνου κακίαν, ἐπεχείρησε μὲν αὐτῷ διαλέγεσθαι καὶ παρακαλεῖν ἀφέντα τὴν μανίαν καὶ δυστυχίαν τῆς ἐπιθυμίας ἐκείνης ζητεῖν τινα τῶν ἡμαρτημένων ἐπανόρθωσιν πρὸς τοὺς πολίτας, ἀπωσαμένου δ’ ἐκείνου καὶ καταφρονήσαντος, οὕτω παραλαβὼν τῶν μὲν οἰκείων Αἰσχύλον, ἀδελφόν ὄντα τῆς Τιμοφάνους γυναικός, τῶν δὲ φίλων τὸν μάντιν ὃν Σάτυρον μὲν Θεόπομπος, Ἔφορος δὲ καὶ Τίμαιος Ὀρθαγόραν ὀνομάζουσι, καὶ διαλιπὼν ἡμέρας ὀλίγας αὖθις ἀνέβη πρὸς τὸν ἀδελφόν· καὶ περιστάντες αὐτὸν οἱ τρεῖς καθικέτευον ἀλλὰ νῦν γε χρησάμενον λογισμῷ μεταβαλέσθαι. τοῦ δὲ Τιμοφάνους πρῶτον μὲν αὐτῶν καταγελῶντος, ἔπειτα δὲ πρὸς ὀργὴν ἐκφερομένου καὶ χαλεπαίνοντος, ὁ μὲν Τιμολέων ἀποχωρήσας μικρὸν αὐτοῦ καὶ συγκαλυψάμενος εἱστήκει δακρύων, ἐκεῖνοι δὲ τὰ ξίφη σπασάμενοι ταχὺ διαφθείρουσιν αὐτόν.", "st": "Tim. 4.4"}, {"sp": "N", "t": "τῆς δὲ πράξεως διαβοηθείσης οἱ μὲν κράτιστοι τῶν Κορινθίων ἐπῄνουν τὴν μισοπονηρίαν καὶ μεγαλοψυχίαν τοῦ Τιμολέοντος, ὅτι χρηστὸς ὢν καὶ φιλοίκειος ὅμως τὴν πατρίδα τῆς οἰκίας καὶ τὸ καλὸν καὶ δίκαιον προετίμησε τοῦ συμφέροντος, ἀριστεύοντα μὲν ὑπὲρ τῆς πατρίδος διασώσας τὸν ἀδελφόν, ἐπιβουλεύσαντα δὲ αὐτῇ καὶ καταδουλωσάμενον ἀποκτείνας. οἱ δὲ μὴ δυνάμενοι ζῆν ἐν τῇ δημοκρατίᾳ καὶ πρὸς τοὺς δυνάστας ἀποβλέπειν εἰωθότες τῷ μὲν θανάτῳ τοῦ τυράννου προσεποιοῦντο χαίρειν, τὸν δὲ Τιμολέοντα λοιδοροῦντες ὡς ἀσεβὲς ἐξειργασμένον καὶ μυσῶδες ἔργον εἰς ἀθυμίαν περιέστησαν. ἐπεὶ δὲ καὶ τὴν μητέρα δυσφορεῖν πυθόμενος καὶ φωνάς τε δεινὰς καὶ κατάρας ἐπ’ αὐτὸν ἀρᾶσθαι φρικώδεις ἐβάδιζε παραμυθησόμενος, ἡ δὲ προσιδεῖν οὐχ ὑπέμεινε τὴν ὄψιν, ἀλλὰ τὴν οἰκίαν ἀπέκλεισε, τότε δὴ παντάπασι περίλυπος γενόμενος καὶ συνταραχθεὶς τὴν διάνοιαν ὥρμησε μὲν ὡς διαφθερῶν ἑαυτὸν ἀπέχεσθαι τροφῆς, τῶν δὲ φίλων οὐ περιϊδόντων, ἀλλὰ πᾶσαν δέησιν καὶ πᾶσαν ἀνάγκην προσενεγκαμένων ἔγνω ζῆν καθ’ ἑαυτὸν, ἐκ μέσου γενόμενος· καὶ πολιτείαν μὲν ἅπασαν ἀφῆκε, τοὺς δὲ πρώτους χρόνους οὐδὲ κατιὼν εἰς πόλιν, ἀλλ’ ἀδημονῶν καὶ πλανώμενος ἐν τοῖς ἐρημοτάτοις τῶν ἀγρῶν διέτριβεν.", "st": "Tim. 5.1"}, {"sp": "N", "t": "οὕτως αἱ κρίσεις, ἂν μὴ βεβαιότητα καὶ ῥώμην ἐκ λόγου καὶ φιλοσοφίας προσλάβωσιν ἐπὶ τὰς πράξεις, σείονται καὶ παραφέρονται ῥᾳδίως ὑπὸ τῶν τυχόντων ἐπαίνων καὶ ψόγων, ἐκκρουόμεναι τῶν οἰκείων λογισμῶν, δεῖ γὰρ οὐ μόνον, ὡς ἔοικε, τὴν πρᾶξιν καλὴν εἶναι καὶ δικαίαν, ἀλλὰ καὶ τὴν δόξαν, ἀφ’ ἧς πράττεται, μόνιμον καὶ ἀμετάπτωτον, ἵνα πράττωμεν δοκιμάσαντες, μηδ’ ὥσπερ οἱ λίχνοι τὰ πλήσμια τῶν ἐδεσμάτων ὀξυτάτῃ διώκοντες ἐπιθυμίᾳ τάχιστα δυσχεραίνουσιν ἐμπλησθέντες, οὕτως ἡμεῖς ἐπὶ ταῖς πράξεσι συντελεσθείσαις ἀθυμῶμεν δι’ ἀσθένειαν ἀπομαραινομένης τῆς τοῦ καλοῦ φαντασίας. αἰσχρὸν γὰρ ἡ μετάνοια ποιεῖ καὶ τὸ καλῶς πεπραγμένον, ἡ δ’ ἐξ ἐπιστήμης ὡρμημένη καὶ λογισμοῦ προαίρεσις οὐδ’ ἂν πταίσωσιν αἱ πράξεις μεταβάλλεται. διὸ Φωκίων μὲν ὁ Ἀθηναῖος τοῖς ὑπὸ Λεωσθένους πραττομένοις ἐναντιωθείς, ἐπειδὴ κατορθοῦν ἐκεῖνος ἐδόκει καὶ θύοντας ἑώρα καὶ μεγαλαυχουμένους τῇ νίκῃ τοὺς Ἀθηναίους, εἶπεν ὡς ἐβούλετο ἂν αὑτῷ ταῦτα μὲν πραχθῆναι, βεβουλεῦσθαι δ’ ἐκεῖνα· σφοδρότερον δ’ Ἀριστείδης ὁ Λοκρός, εἷς ὢν τῶν Πλάτωνος ἑταίρων, αἰτοῦντος μὲν αὐτὸν γυναῖκα Διονυσίου τοῦ πρεσβυτέρου μίαν τῶν θυγατέρων, ἥδιον ἂν ἔφη νεκρὰν ἰδεῖν τὴν κόρην ἢ τυράννῳ συνοικοῦσαν, ἀποκτείναντος δὲ τοὺς παῖδας αὐτοῦ μετ’ ὀλίγον χρόνον τοῦ Διονυσίου καὶ πυθομένου πρὸς ὕβριν εἰ τὴν αὐτὴν ἔτι γνώμην ἔχοι περὶ τῆς ἐκδόσεως τῶν θυγατέρων, ἀπεκρίνατο τοῖς μὲν γεγενημένοις λυπεῖσθαι, τοῖς δ’ εἰρημένοις μὴ μεταμέλεσθαι. ταῦτα μὲν οὖν ἴσως μείζονος καὶ τελειοτέρας ἀρετῆς ἐστι.", "st": "Tim. 6.1"}, {"sp": "N", "t": "τὸ δὲ Τιμολέοντος ἐπὶ τοῖς πεπραγμένοις πάθος, εἴτ’ οἶκτος ἦν τοῦ τεθνηκότος εἴτε τῆς μητρὸς αἰδώς, οὕτω κατέκλασε καί συνέτριψεν αὐτοῦ τὴν διάνοιαν ὥστ’ εἴκοσι σχεδὸν ἐτῶν διαγενομένων μηδεμιᾶς ἐπιφανοῦς μηδὲ πολιτικῆς ἅψασθαι πράξεως, ἀναγορευθέντος οὖν αὐτοῦ, καί τὸν δήμου προθύμως δεξαμένου καί χειροτονήσαντος, ἀναστὰς Τηλεκλείδης ὁ τότε καί δυνάμει καί δόξῃ πρωτεύων ἐν τῇ πόλει, παρεκάλει τὸν Τιμολέοντα περὶ τὰς πράξεις ἀγαθὸν ἄνδρα εἶναι καί γενναῖον. ἂν μὲν γὰρ ἔφη, καλῶς ἀγωνίσῃ, τύραννον ἀνῃρηκέναι δόξομεν, ἂν δὲ φαύλως, ἀδελφόν.", "st": "Tim. 7.1"}, {"sp": "N", "t": "παρασκευαζομένου δὲ τοῦ Τιμολέοντος τὸν ἔκπλουν καί στρατιώτας συνάγοντος, ἐκομίσθη γράμματα πρὸς τοὺς Κορινθίους παρ’ Ἱκέτου μηνύοντα τὴν μεταβολὴν αὐτοῦ καί προδοσίαν. ὡς γὰρ τάχιστα τοὺς πρέσβεις ἐξέπεμψε, τοῖς Καρχηδονίοις προσθέμενος ἀναφανδὸν ἔπραττε μετ’ ἐκείνων ὅπως Διονύσιον ἐκβαλὼν Συρακουσῶν αὐτὸς ἔσται τύραννος. καί δεδοικώς μὴ πρότερον ἐλθούσης ἐκ Κορίνθου δυνάμεως καί στρατηγοῦ διαφύγωσιν αἱ πράξεις αὐτόν, ἔπεμψεν ἐπιστολὴν τοῖς Κορινθίοις φράζουσαν ὡς οὐδὲν δέον πράγματα καί δαπάνας ἔχειν αὐτούς πλέοντας εἰς Σικελίαν καί κινδυνεύοντας, ἄλλως τε καί Καρχηδονίων ἀπαγορευόντων καί παραφυλαττομένων ναυσὶ πολλαῖς τὸν στόλον, οὓς αὐτὸς ἀναγκασθεὶς ἐκείνων βραδυνόντων ποιήσαιτο συμμάχους ἐπὶ τὸν τύραννον. τούτων δὲ τῶν γραμμάτων ἀναγνωσθέντων, εἰ καί τις ἠπίως εἶχε πρότερον τῶν Κορινθίων πρὸς τὴν στρατείαν, τότε πάντας ἡ πρὸς τὸν Ἱκέτην ὀργὴ παρώξυνεν, ὥστε συγχορηγῆσαι προθύμως τῷ Τιμολέοντι καί συμπαρασκευάσαι τὸν ἔκπλουν.", "st": "Tim. 7.3"}, {"sp": "N", "t": "γενομένων δὲ τῶν νεῶν ἑτοίμων, καὶ τοῖς στρατιώταις ὧν ἔδει πορισθέντων, αἱ μὲν ἱέρειαι τῆς Κόρης ὄναρ ἔδοξαν ἰδεῖν τὰς θεὰς πρὸς ἀποδημίαν τινὰ στελλομένας καὶ λεγούσας ὡς Τιμολέοντι μέλλουσι συμπλεῖν εἰς Σικελίαν. διὸ καὶ τριήρη κατασκευάσαντες ἱερὰν οἱ Κορίνθιοι ταῖν θεαῖν ἐπωνόμασαν. αὐτὸς δ’ ἐκεῖνος εἰς Δελφοὺς πορευθεὶς ἔθυσε τῷ θεῷ, καὶ καταβαίνοντος εἰς τὸ μαντεῖον αὐτὸν γίνεται σημεῖον. ἐκ γὰρ τῶν κρεμαμένων ἀναθημάτων ταινία τις ἀπορρυεῖσα καὶ φερομένη, στεφάνους ἔχουσα καὶ Νίκας ἐμπεποικιλμένας, περιέπεσε τῇ κεφαλῇ τοῦ Τιμολέοντος, ὡς δοκεῖν αὐτὸν ὑπὸ τοῦ θεοῦ στεφανούμενον ἐπὶ τὰς πράξεις προπέμπεσθαι.", "st": "Tim. 8.1"}, {"sp": "N", "t": "ναῦς δὲ Κορινθίας μὲν ἔχων ἑπτά. Κερκυραίας δὲ δύο, καὶ τὴν δεκάτην Λευκαδίων προσπαρασχόντων, ἀνήχθη. καὶ νυκτὸς ἐμβαλὼν εἰς τὸ πέλαγος καὶ πνεύματι καλῷ χρώμενος ἔδοξεν αἰφνιδίως ῥαγέντα τὸν οὐρανὸν ὑπὲρ τῆς νεὼς ἐκχέαι πολὺ καὶ περιφανὲς πῦρ. ἐκ δὲ τούτου λαμπὰς ἀρθεῖσα ταῖς μυστικαῖς ἐμφερὴς καὶ συμπαραθέουσα τὸν αὐτὸν δρόμον, ᾗ μάλιστα τῆς Ἰταλίας ἐπεῖχον οἱ κυβερνῆται, κατέσκηψεν. οἱ δὲ μάντεις τὸ φάσμα τοῖς ὀνείρασι τῶν ἱερειῶν μαρτυρεῖν ἀπεφαίνοντο, καὶ τὰς θεὰς συνεφαπτομένας τῆς στρατείας προφαίνειν ἐξ οὐρανοῦ τὸ σέλας· εἶναι γὰρ ἱερὰν τῆς Κόρης τὴν Σικελίαν, ἐπεὶ καὶ τὰ περὶ τὴν ἁρπαγὴν αὐτόθι μυθολογοῦσι γενέσθαι καὶ τὴν νῆσον ἐν τοῖς γάμοις ἀνακαλυπτήριον αὐτῇ δοθῆναι.", "st": "Tim. 8.4"}, {"sp": "N", "t": "τὰ μὲν οὖν παρὰ τῶν θεῶν οὕτω τὸν στόλον ἐθάρρυνε καὶ σπεύδοντες, ὡς τὸ πέλαγος διαπλέοντες, ἐκομίζοντο παρὰ τὴν Ἰταλίαν. τὰ δ’ ἀπὸ τῆς Σικελίας ἀγγελλόμενα πολλὴν ἀπορίαν τῷ Τιμολέοντι καὶ δυσθυμίαν τοῖς στρατιώταις παρεῖχεν. ὁ γὰρ Ἱκέτης μάχῃ νενικηκὼς Διονύσιον καὶ τὰ πλεῖστα μέρη τῶν Συρακουσῶν κατειληφώς ἐκεῖνον μὲν εἰς τὴν ἀκρόπολιν καὶ τὴν καλουμένην Νῆσον συνεσταλμένον αὐτὸς συνεπολιόρκει καὶ συμπεριετείχιζε, Καρχηδονίους δὲ φροντίζειν ἐκέλευεν ὅπως οὐκ ἐπιβήσοιτο Τιμολέων Σικελίας, ἀλλ’ ἀπωσθέντων ἐκείνων αὐτοὶ καθ’ ἡσυχίαν διανεμοῦνται πρὸς ἀλλήλους τὴν νῆσον. οἱ δὲ πέμπουσιν εἴκοσι τριήρεις εἰς Ῥήγιον, ἐφ’ ὧν ἐπέπλεον πρεσβευταὶ παρ’ αὐτοῦ πρὸς Τιμολέοντα κομίζοντες λόγους τοῖς πραττομένοις ὁμοίους. παραγωγαὶ γὰρ εὐπρεπεῖς καὶ προφάσεις ἦσαν ἐπὶ μοχθηροῖς βουλεύμασιν, ἀξιούντων αὐτὸν μὲν, εἰ βούλοιτο, Τιμολέοντα σύμβουλον ἥκειν παρ’ Ἱκέτην καὶ κοινωνὸν εὖ διαπεπραγμένων ἁπάντων, τὰς δὲ ναῦς καὶ τοὺς στρατιώτας ἀποστέλλειν εἰς Κόρινθον, ὡς τοῦ πολέμου μικρὸν ἀπολείποντος συνῃρῆσθαι, Καρχηδονίων δὲ κωλύειν τὴν διάβασιν καὶ μάχεσθαι πρὸς βιαζομένους ἑτοίμων ὄντων. ὡς οὖν καταπλεύσαντες εἰς τὸ Ῥήγιον οἱ Κορίνθιοι τοῖς τε πρεσβεύμασι τούτοις ἐνέτυχον καὶ τοὺς Φοίνικας οὐ πρόσω ναυλοχοῦντας κατεῖδον, ἤχθοντο μὲν ὑβρισμένοι, καὶ παρίστατο πᾶσιν ὀργὴ πρὸς τὸν Ἱκέτην καὶ δέος ὑπὲρ Σικελιωτῶν, οὓς σαφῶς ἑώρων ἆθλα λειπομένους καὶ μισθόν Ἱκέτῃ μὲν προδοσίας, Καρχηδονίοις δὲ τυραννίδος, ἐδόκει δ’ ἀμήχανον ὑπερβαλέσθαι καὶ τὰς αὐτόθι τῶν βαρβάρων ναῦς διπλασίας ἐφορμούσας καὶ τὴν ἐκεῖ μεθ’ Ἱκέτου δύναμιν, ᾗ στρατηγήσοντες ἥκοιεν.", "st": "Tim. 9.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὁ Τιμολέων τοῖς πρεσβευταῖς καὶ τοῖς ἄρχουσι τῶν Καρχηδονίων ἐντυχὼν ἐπιεικῶς ἔφη πείθεσθαι μὲν οἷς κελεύουσι τί γὰρ ἂν καὶ περαίνειν ἀπειθῶν, ἐθέλειν δὲ ταῦτα πόλεως Ἑλληνίδος καὶ φίλης κοινῆς τῆς Ῥηγίνων ἐναντίον ἀκούσας καὶ εἰπὼν ἀπαλλάττεσθαι· καὶ γὰρ αὐτῷ τοῦτο πρὸς ἀσφάλειαν διαφέρειν, κἀκείνους ἐμμενεῖν βεβαιότερον οἷς ἐπαγγέλλονται περὶ Συρακουσίων δήμῳ μάρτυρι τὰς ὁμολογίας παρακαταθεμένους. ταῦτα δ’ ὑπέτεινεν αὐτοῖς ἀπάτην ἐπὶ τῇ διαβάσει τεχνάζων, καὶ συνετέχναζον οἱ τῶν Ῥηγίνων στρατηγοὶ, πάντες ἐπιθυμοῦντες ἐν Κορινθίοις τὰ πράγματα τῶν Σικελιωτῶν γενέσθαι, καὶ φοβούμενοι τὴν τῶν βαρβάρων γειτνίασιν. διὸ συνῆγον ἐκκλησίαν καὶ τὰς πύλας ἀπέκλειον, ὡς μὴ πρὸς ἄλλο τι τρέπεσθαι τοὺς πολίτας, καὶ παρελθόντες εἰς τὸ πλῆθος ἐχρῶντο μήκει λόγων, ἕτερος ἑτέρῳ παραδιδοὺς τὴν αὐτὴν ὑπόθεσιν πρὸς οὐδὲν τέλος, ἀλλὰ διάγοντες ἄλλως τὸν χρόνον, ἕως ἀναχθῶσιν αἱ τῶν Κορινθίων τριήρεις, καὶ Καρχηδονίους ἐπὶ τῆς ἐκκλησίας κατέχοντες ἀνυπόπτως, ἅτε καὶ τοῦ Τιμολέοντος παρόντος καὶ παρέχοντος δόκησιν ὅσον οὔπω πρὸς τὸν λόγον ἀνίστασθαι καὶ δημηγορεῖν. ὡς δ’ ἀπήγγειλέ τις αὐτῷ κρύφα τὰς μὲν ἄλλας τριήρεις ἀνῆχθαι, μίαν δὲ τὴν ἐκείνου περιμένειν ὑπολελειμμένην, διεκδὺς τὸν ὄχλον, ἅμα τῶν περὶ τὸ βῆμα Ῥηγίνων συνεπικρυπτόντων, καὶ καταβὰς ἐπὶ τὴν θάλατταν ἐξέπλευσε διὰ ταχέων. καὶ κατήχθησαν εἰς Ταυρομένιον τῆς Σικελίας, ὑποδεχομένου καὶ καλοῦντος αὐτοὺς ἔτι πάλαι προθύμως Ἀνδρομάχου τοῦ τὴν πόλιν ἔχοντος καὶ δυναστεύοντος. οὗτος ἦν πατὴρ Τιμαίου τοῦ ἱστορικοῦ, καὶ πολὺ κράτιστος τῶν τότε δυναστευόντων ἐν Σικελίᾳ, γενόμενος τῶν τε ἑαυτοῦ πολιτῶν ἡγεῖτο νομίμως καὶ δικαίως, καὶ πρὸς τοὺς τυράννους φανερὸς ἦν ἀεὶ διακείμενος ἀπεχθῶς καὶ ἀλλοτρίως. διὸ καὶ Τιμολέοντι τότε τὴν πόλιν ὁρμητήριον παρέσχε, καὶ τοὺς πολίτας ἔπεισε συναγωνίζεσθαι τοῖς Κορινθίοις καὶ συνελευθεροῦν τὴν Σικελίαν.", "st": "Tim. 10.1"}, {"sp": "N", "t": "οἱ δ’ ἐν τῷ Ῥηγίῳ Καρχηδόνιοι τοῦ Τιμολέοντος ἀνηγμένου καὶ τῆς ἐκκλησίας διαλυθείσης χαλεπῶς φέροντες, ἐν τῷ κατεστρατηγῆσθαι διατριβὴν τοῖς Ῥηγίνοις παρεῖχον, εἰ Φοίνικες ὄντες οὐκ ἀρέσκοιντο τοῖς δι’ ἀπάτης πραττομένοις. πέμπουσι δ’ οὖν εἰς τὸ Ταυρομένιον πρεσβευτὴν ἐπὶ τριήρους, ὃς πολλὰ διαλεχθεὶς πρὸς τὸν Ἀνδρόμαχον, ἐπαχθῶς καὶ βαρβαρικῶς ἀνατεινάμενος εἰ μὴ τὴν ταχίστην ἐκβάλλει τοὺς Κορινθίους, τέλος ὑπτίαν τὴν χεῖρα δείξας, εἶτ’ αὖθις καταστρέψας ἠπείλησε τοιαύτην οὖσαν αὐτῷ τὴν πόλιν τοιαύτην ποιήσειν. γελάσας δ’ ὁ Ἀνδρόμαχος ἄλλο μὲν οὐδὲν ἀπεκρίνατο, τὴν δὲ χεῖρα νῦν μὲν ὑπτίαν, ὡς ἐκεῖνος, νῦν δὲ πρηνῆ προτείνας ἐκέλευσεν ἀποπλεῖν αὐτόν, εἰ μὴ βούλοιτο τὴν ναῦν ἀντὶ τοιαύτης γενέσθαι τοιαύτην.", "st": "Tim. 11.1"}, {"sp": "N", "t": "ὁ δ’ Ἱκέτης πυθόμενος τὴν τοῦ Τιμολέοντος διάβασιν καὶ φοβηθείς μετεπέμψατο πολλὰς τῶν Καρχηδονίων τριήρεις. ὅτε καὶ παντάπασι συνέβη τοὺς Συρακουσίους ἀπογνῶναι τὴν σωτηρίαν, ὁρῶντας τοῦ μὲν λιμένος αὐτῶν Καρχηδονίους κρατοῦντας, τὴν δὲ πόλιν Ἱκέτην ἔχοντα, τῆς δ’ ἄκρας κυριεύοντα Διονύσιον, Τιμολέοντα δὲ ὥσπερ ἐκ κρασπέδου τινὸς λεπτοῦ τῆς Ταυρομενιτῶν πολίχνης τῇ Σικελίᾳ προσηρτημένον ἐπ’ ἐλπίδος ἀσθενοῦς καὶ βραχείας δυνάμεως· χιλίων γὰρ αὐτῷ στρατιωτῶν καὶ τροφῆς τούτοις ἀναγκαίας πλέον οὐδὲν ὑπῆρχεν. οὐδ’ ἐπίστευον αἱ πόλεις διάπλεαι κακῶν οὖσαι καὶ πρὸς ἅπαντας ἀπηγριωμέναι τοὺς ἡγουμένους στρατοπέδων, μάλιστα διὰ τὴν Καλλίππου καὶ Φάρακος ἀπιστίαν, ὧν ὁ μὲν Ἀθηναῖος ὤν, ὁ δὲ Λακεδαιμόνιος, ἀμφότεροι δὲ φάσκοντες ὑπὲρ τῆς ἐλευθερίας ἥκειν καὶ καταλύειν τοὺς μονάρχους, χρυσὸν ἀπέδειξαν τῇ Σικελίᾳ τὰς ἐν τῇ τυραννίδι συμφοράς καὶ μακαριωτέρους δοκεῖν ἐποίησαν τοὺς καταστρέψαντας ἐν τῇ δουλείᾳ τῶν ἐπιδόντων τὴν αὐτονομίαν.", "st": "Tim. 11.4"}, {"sp": "N", "t": "οὐδὲν οὖν ἐκείνων βελτίονα τὸν Κορίνθιον ἔσεσθαι προσδοκῶντες, ἀλλὰ ταῦτα πάλιν ἥκειν πρὸς αὐτοὺς σοφίσματα καί δελεάσματα, μετ’ ἐλπίδων χρηστῶν καί φιλανθρώπων ὑποσχέσεων εἰς μεταβολὴν δεσπότου καινοῦ τιθασευομένους, ὑπώπτευον καί διεκρούοντο τὰς τῶν Κορινθίων προκλήσεις πλὴν Ἀδρανιτῶν, οἳ πόλιν μικρὰν μέν, ἱερὰν δ’ οὖσαν Ἀδρανοῦ, θεοῦ τινος τιμωμένου διαφερόντως ἐν ὅλῃ Σικελίᾳ, κατοικοῦντες ἐστασίασαν πρὸς ἀλλήλους, οἱ μὲν Ἱκέτην προσαγόμενοι καί Καρχηδονίους, οἱ δὲ πρὸς Τιμολέοντα διαπεμπόμενοι. καί πως ἀπ’ αὐτομάτου συνέτυχε σπευδόντων ἀμφοτέρων εἰς ἕνα καιρὸν ἀμφοτέροις γενέσθαι τὴν παρουσίαν. ἀλλ’ Ἱκέτης μὲν ἧκε πεντακισχιλίους στρατιώτας ἔχων, Τιμολέοντι δὲ οἱ σύμπαντες ἦσαν οὐ πλείους χιλίων διακοσίων· οὓς ἀναλαβὼν ἐκ τοῦ Ταυρομενίου, σταδίων πρὸς τὸ Ἀδρανὸν ὄντων τετταράκοντα καί τριακοσίων, τῇ μὲν πρώτῃ τῶν ἡμερῶν οὐ πολὺ μέρος τῆς ὁδοῦ προέλαβε καί κατηυλίσατο, τῇ δ’ ὑστεραίᾳ συντόνως ὁδεύσας καί χαλεπὰ χωρία διελθών ἤδη τῆς ἡμέρας καταφερομένης ἤκουσεν ἄρτι προσμιγνύναι τὸν Ἱκέτην τῷ πολιχνίῳ καί καταστρατοπεδεύειν. οἱ μὲν οὖν λοχαγοὶ καί ταξίαρχοι τοὺς πρώτους ἐπέστησαν ὡς ἐμφαγοῦσι καί διαναπαυσαμένοις χρησόμενοι προθυμοτέροις, ὁ δὲ Τιμολέων ἐπιπορευόμενος ἐδεῖτο ταῦτα μὴ ποιεῖν, ἀλλ’ ἄγειν κατὰ τάχος καί συνάπτειν τοῖς πολεμίοις ἀσυντάκτοις οὖσιν, ὡς εἰκὸς ἄρτι παυομένους ὁδοιπορίας καί περὶ σκηνὰς καί δεῖπνον ἀσχόλους ὄντας. καί λέγων ἅμα ταῦτα, τὴν ἀσπίδα λαβὼν ἡγεῖτο πρῶτος ὥσπερ ἐπὶ νίκην πρόδηλον. οἱ δ’ εἵποντο τεθαρρηκότες, ἔλαττον ἢ τριάκοντα σταδίους ἔτι τῶν πολεμίων ἀπέχοντες. ὡς δὲ καί τούτους διῆλθον, ἐπιπίπτουσιν αὐτοῖς ταραττομένοις καί φεύγουσιν ὡς πρῶτον ᾔσθοντο προσιόντας, ὅθεν ἀνῃρέθησαν μὲν οὐ πολλῷ πλείους τριακοσίων, ἑάλωσαν δὲ δὶς τοσοῦτοι ζῶντες, ἐλήφθη δὲ τὸ στρατόπεδον. οἱ δ’ Ἀδρανῖται τὰς πύλας ἀνοίξαντες προσέθεντο τῷ Τιμολέοντι, μετὰ φρίκης καί θαύματος ἀπαγγέλλοντες ὡς ἐνισταμένης τῆς μάχης οἱ μὲν ἱεροὶ τοῦ νεὼ πυλῶνες αὐτόματοι διανοιχθεῖεν, ὀφθείη δὲ τοῦ θεοῦ τὸ μὲν δόρυ σειόμενον ἐκ τῆς αἰχμῆς ἄκρας, τὸ δὲ πρόσωπον ἱδρῶτι πολλῷ ῥεόμενον.", "st": "Tim. 12.1"}, {"sp": "N", "t": "ταῦτα δ’, ὡς ἔοικεν, οὐ τὴν τότε νίκην ἐσήμαινε μόνον, ἀλλὰ καὶ τὰς μετὰ ταῦτα πράξεις, αἷς ἐκεῖνος ὁ ἀγὼν ἀρχὴν εὐτυχῆ παρέσχε. καὶ γὰρ πόλεις εὐθὺς ἐπιπρεσβευόμεναι προσετίθεντο τῷ Τιμολέοντι, καὶ Μάμερκος ὁ Κατάνης τύραννος, πολεμιστὴς ἀνὴρ καὶ χρήμασιν ἐρρωμένος, ἔδωκεν αὑτὸν εἰς συμμαχίαν. τὸ δὲ μέγιστον, αὐτὸς Διονύσιος ἀπειρηκὼς ἤδη ταῖς ἐλπίσι καὶ μικρὸν ἀπολείπων ἐκπολιορκεῖσθαι τοῦ μὲν Ἱκέτου κατεφρόνησεν αἰσχρῶς ἡττημένου, τὸν δὲ Τιμολέοντα θαυμάζων ἔπεμψεν ἐκείνῳ καὶ Κορινθίοις παραδιδοὺς αὑτὸν καὶ τὴν ἀκρόπολιν. δεξάμενος δ’ ὁ Τιμολέων τὴν ἀνέλπιστον εὐτυχίαν, ἀποστέλλει τοὺς περὶ Εὐκλείδην καὶ Τηλέμαχον, ἄνδρας Κορινθίους, εἰς τὴν ἀκρόπολιν, καὶ στρατιώτας τετρακοσίους, οὐχ ὁμοῦ πάντας οὐδὲ φανερῶς, ἀδύνατον γὰρ ἦν ἐφορμούν· τῶν πολεμίων, ἀλλὰ κρύφα καὶ κατ’ ὀλίγους παρεισπεσόντας. οἱ μὲν οὖν στρατιῶται παρέλαβον τὴν ἀκρόπολιν καὶ τὰ τυραννεῖα μετὰ τῆς παρασκευῆς καὶ τῶν χρησίμων πρὸς τὸν πόλεμον· ἵπποι τε γὰρ ἐνῆσαν οὐκ ὀλίγοι καὶ πᾶσα μηχανημάτων ἰδέα καὶ βελῶν πλῆθος, ὅπλων δ’ ἀπέκειντο μυριάδες ἑπτὰ τεθησαυρισμένων ἐκ παλαιοῦ, στρατιῶται δὲ δισχίλιοι τῷ Διονυσίῳ παρῆσαν, οὓς ἐκεῖνος, ὡς τἆλλα, τῷ Τιμολέοντι παρέδωκεν, αὐτὸς δὲ χρήματα λαβὼν καὶ τῶν φίλων οὐ πολλοὺς ἔλαθεν ἐκπλεύσας τὸν Ἱκέτην. καὶ κομισθεὶς εἰς τὸ τοῦ Τιμολέοντος στρατόπεδον, τότε πρῶτον ἰδιώτης καὶ ταπεινὸς ὀφθείς, ἐπὶ μιᾶς νεὼς καὶ χρημάτων ὀλίγων εἰς Κόρινθον ἀπεστάλη, γεννηθεὶς μὲν καὶ τραφεὶς ἐν τυραννίδι τῇ πασῶν ἐπιφανεστάτῃ καὶ μεγίστῃ, κατασχὼν δὲ ταύτην ἔτη δέκα, δώδεκα δ’ ἄλλα μετὰ τὴν Δίωνος στρατείαν ἐν ἀγῶσι καὶ πολέμοις διαφορηθείς, ἃ δ’ ἔπραξε τυραννῶν οἷς ἔπαθεν ὑπερβαλόμενος, καὶ γὰρ υἱῶν ἐνηλίκων θανάτους καὶ θυγατέρων καταπορνεύσεις παρθένων ἐπεῖδε, καὶ τὴν αὐτὴν ἀδελφὴν καὶ γυναῖκα ζῶσαν μὲν εἰς τὸ σῶμα ταῖς ἀσελγεστάταις ὑπὸ τῶν πολεμίων ἡδοναῖς παρανομηθεῖσαν, βίᾳ δ’ ἀποθανοῦσαν μετὰ τῶν τέκνων, καταποντισθεῖσαν εἰς τὸ πέλαγος, ταῦτα μὲν οὖν ἐν τοῖς περὶ Δίωνος ἀκριβῶς γέγραπται.", "st": "Tim. 13.1"}, {"sp": "N", "t": "τοῦ δὲ Διονυσίου καταπλεύσαντος εἰς Κόρινθον, οὐδεὶς ἦν Ἑλλήνων ὃς οὐχὶ θεάσασθαι καὶ προσειπεῖν ἐπόθησεν αὐτόν. ἀλλ’ οἵ τε χαίροντες ἐπὶ ταῖς συμφοραῖς διὰ μῖσος ἄσμενοι συνῆλθον οἷον ἐρριμμένον ὑπὸ τῆς τύχης πατήσοντες, οἵ τε πρὸς τὴν μεταβολὴν τρεπόμενοι καὶ συμπαθοῦντες ἐθεῶντο πολλὴν ἐν ἀσθενέσι τοῖς ἀνθρωπίνοις καὶ προδήλοις τὴν τῶν ἀδήλων αἰτιῶν καὶ θείων δύναμιν. οὐδὲν γὰρ οὔτε φύσεως ὁ τότε καιρὸς οὔτε τέχνης ὅσον ἐκεῖνο τύχης ἔργον ἐπεδείξατο, τὸν Σικελίας ὀλίγον ἔμπροσθεν τύραννον ἐν Κορίνθῳ διατρίβοντα περὶ τὴν ὀψόπωλιν ἢ καθήμενον ἐν μυροπωλίῳ, πίνοντα κεκραμένον ἀπὸ τῶν καπηλείων καὶ διαπληκτιζόμενον ἐν μέσῳ τοῖς ἀφ’ ὥρας ἐργαζομένοις γυναίοις, τὰς δὲ μουσουργοὺς ἐν ταῖς ᾠδαῖς διδάσκοντα, καὶ περὶ θεατρικῶν ᾀσμάτων ἐρίζειν σπουδάζοντα πρὸς ἐκείνας καὶ περὶ μέλους ἁρμονίας, ταῦτα δ’ οἱ μὲν ἄλλως ἀλύοντα καὶ φύσει ῥᾴθυμον ὄντα καὶ φιλακόλαστον ᾤοντο ποιεῖν τὸν Διονύσιον, οἱ δ’ ὑπὲρ τοῦ καταφρονεῖσθαι καὶ μὴ φοβερὸν εἶναι τοῖς Κορινθίοις, μηδ’ ὕποπτον ὡς βαρυνόμενον τὴν μεταβολὴν τοῦ βίου καὶ πραγμάτων ἐφιέμενον, ἐπιτηδεύειν καὶ ὑποκρίνεσθαι παρὰ φύσιν, πολλὴν ἀβελτερίαν ἐπιδεικνύμενον ἐν τῷ σχολάζειν.", "st": "Tim. 14.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καί λόγοι τινὲς αὐτοῦ μνημονεύονται, δι’ ὧν ἐδόκει συμφέρεσθαι τοῖς παροῦσιν οὐκ ἀγεννῶς. τοῦτο μὲν γὰρ εἰς Λευκάδα καταχθείς, πόλιν ἀπῳκισμένην ὑπὸ Κορινθίων ὥσπερ τὴν Συρακουσίων, ταὐτὸν ἔφη πεπονθέναι τοῖς ἐν ἁμαρτήμασι γενομένοις τῶν νεανίσκων· ὡς γὰρ ἐκεῖνοι τοῖς μὲν ἀδελφοῖς ἱλαρῶς συνδιατρίβουσι, τοὺς δὲ πατέρας αἰσχυνόμενοι φεύγουσιν, οὕτως αὐτὸς αἰδούμενος τὴν μητρόπολιν ἡδέως ἂν αὐτόθι μετ’ ἐκείνων κατοικεῖν. τοῦτο δ’ ἐν Κορίνθῳ ξένου τινὸς ἀγροικότερον εἰς τὰς μετὰ τῶν φιλοσόφων διατριβὰς, αἷς τυραννῶν ἔχαιρε, χλευάζοντος αὐτὸν, καί τέλος ἐρωτῶντος τί δὴ τῆς Πλάτωνος ἀπολαύσειε σοφίας, οὐδὲν, ἔφη, σοὶ δοκοῦμεν ὑπὸ Πλάτωνος ὠφελῆσθαι, τύχης μεταβολὴν οὕτω φέροντες; πρὸς δὲ τὸν μουσικὸν Ἀριστόξενον καί τινας ἄλλους πυνθανομένους ὁπόθεν αὐτῷ καί τίς ἡ πρὸς Πλάτωνα γένοιτο μέμψις, πολλῶν ἔφη κακῶν τὴν τυραννίδα μεστὴν οὖσαν οὐδὲν ἔχειν τηλικοῦτον ἡλίκον τὸ μηδένα τῶν λεγομένων φίλων μετὰ παρρησίας διαλέγεσθαι· καί γὰρ αὐτὸς ὑπ’ ἐκείνων ἀποστερηθῆναι τῆς Πλάτωνος εὐνοίας. ἐπεὶ δὲ τῶν βουλομένων τις εὐφυῶν εἶναι σκώπτων τὸν Διονύσιον ἐξέσειε τὸ ἱμάτιον εἰσιὼν πρὸς αὐτὸν, ὡς δὴ πρὸς τύραννον, ἀντισκώπτων ἐκεῖνος ἐκέλευε τοῦτο ποιεῖν ὅταν ἐξίῃ παρ’ αὐτοῦ, μή τι τῶν ἔνδον ἔχων ἀπέλθῃ. Φιλίππου δὲ τοῦ Μακεδόνος παρὰ πότον τινὰ λόγον μετὰ εἰρωνείας ἐμβαλόντος περὶ τῶν μελῶν καὶ τῶν τραγῳδιῶν ἃς ὁ πρεσβύτερος Διονύσιος κατέλιπε, καί προσποιουμένου διαπορεῖν ἐν τίνι χρόνῳ ταῦτα ποιεῖν ἐκεῖνος ἐσχόλαζεν, οὐ φαύλως ἀπήντησεν ὁ Διονύσιος εἰπών ἐν ᾧ σὺ κἀγὼ καί πάντες οἱ μακάριοι δοκοῦντες εἶναι περὶ κώθωνα διατρίβομεν.", "st": "Tim. 15.1"}, {"sp": "N", "t": "Πλάτων μὲν οὖν οὐκ ἐπεῖδεν ἐν Κορίνθῳ Διονύσιον, ἀλλ’ ἔτυχεν ἤδη τεθνηκώς, ὁ δὲ Σινωπεὺς Διογένης ἀπαντήσας αὐτῷ πρῶτον, ὡς ἀναξίως, ἔφη, Διονύσιε, ζῇς. ἐπιστάντος δ’ ἐκείνου καὶ εἰπόντος· εὖ ποιεῖς, ὦ Διόγενες, συναχθόμενος ἡμῖν ἠτυχηκόσι, τί γὰρ; εἶπεν ὁ Διογένης, οἴει μέ σοὶ συναλγεῖν, οὐ διαγανακτεῖν ὅτι τοιοῦτον ἀνδράποδον ὤν, καί τοῖς τυραννείοις, ὥσπερ ὁ πατὴρ, ἐπιτήδειος ἐγγηράσας ἀποθανεῖν, ἐνταῦθα παίζων καί τρυφῶν διάγεις μεθ’ ἡμῶν; ὥστε μοι παραβάλλοντι τούτοις τὰς Φιλίστου φωνάς, ἃς ἀφίησι περὶ τῶν Λεπτίνου θυγατέρων ὀλοφυρόμενος, ὡς ἐκ μεγάλων ἀγαθῶν τῶν τῆς τυραννίδος εἰς ταπεινὴν ἀφιγμένων δίαιταν, φαίνεσθαι θρήνους γυναικὸς ἀλαβάστους καί πορφύρας καί χρυσία ποθούσης.", "st": "Tim. 15.8"}, {"sp": "N", "t": "ταῦτα μὲν οὖν οὐκ ἀλλότρια τῆς τῶν βίων ἀναγραφῆς οὐδὲ ἄχρηστα δόξειν οἰόμεθα μὴ σπεύδουσι μηδὲ ἀσχολουμένοις ἀκροαταῖς.", "st": "Tim. 15.11"}, {"sp": "N", "t": "τῆς δὲ Διονυσίου δυστυχίας παραλόγου φανείσης οὐχ ἧττον ἡ Τιμολέοντος εὐτυχία τὸ θαυμαστὸν ἔσχεν. ἐπιβὰς γὰρ Σικελίας ἐν ἡμέραις πεντήκοντα τήν τ’ ἀκρόπολιν τῶν Συρακουσῶν παρέλαβε καὶ Διονύσιον εἰς Πελοπόννησον ἐξέπεμψεν. ὅθεν ἐπιρρωσθέντες οἱ Κορίνθιοι πέμπουσιν αὐτῷ δισχιλίους ὁπλίτας καὶ διακοσίους ἱππεῖς, οἳ κομισθέντες ἄχρι Θουρίων τήν ἐκεῖθεν περαίωσιν ὑπὸ Καρχηδονίων πολλαῖς ναυσὶ κατεχομένης τῆς θαλάττης ἄπορον ὁρῶντες, ὡς ἦν ἀνάγκη καιρὸν περιμένοντας ἀτρεμεῖν αὐτόθι, πρὸς κάλλιστον ἔργον ἀπεχρήσαντο τῇ σχολῇ. Θουρίων γὰρ ἐπὶ Βρεττίους στρατευόντων τήν πόλιν παραλαβόντες ὥσπερ πατρίδα καθαρῶς καὶ πιστῶς διεφύλαξαν.", "st": "Tim. 16.1"}, {"sp": "N", "t": "ὁ δ’ Ἱκέτης τήν μὲν ἀκρόπολιν τῶν Συρακουσῶν ἐπολιόρκει καὶ σῖτον ἐκώλυεν εἰσπλεῖν τοῖς Κορινθίοις, Τιμολέοντι δὲ δύο ξένους παρασκευάσας δολοφονήσοντας αὐτὸν ὑπέπεμψεν εἰς Ἀδρανόν, οὔτε ἄλλως περὶ τὸ σῶμα συντεταγμένην ἔχοντι φυλακήν, καὶ τότε παντάπασι διὰ τὸν θεὸν ἀνειμένως καὶ ἀνυπόπτως σχολάζοντι μετὰ τῶν Ἀδρανιτῶν. οἱ δὲ πεμφθέντες κατὰ τύχην πυθόμενοι μέλλοντα θύειν αὐτόν, ἧκον εἰς τὸ ἱερόν ὑπὸ τοῖς ἱματίοις ἐγχειρίδια κομίζοντες, καὶ τοῖς περιεστῶσι τὸν βωμὸν ἀναμιχθέντες, ἐγγυτέρω κατὰ μικρὸν ἐπεχείρουν. καὶ ὅσον οὔπω παρακελευομένων ἀλλήλοις ἐνάρχεσθαι παίει τις αὐτῶν τὸν ἕτερον κατὰ τῆς κεφαλῆς ξίφει, καὶ πεσόντος οὔθ’ ὁ παίσας ἔμεινεν οὔδ’ ὁ μετὰ τοῦ πληγέντος ἥκων, ἀλλ’ ἐκεῖνος μὲν, ὥσπερ εἶχε τὸ ξίφος, φεύγων πρός τινα πέτραν ὑψηλὴν ἀνεπήδησεν, ἅτερος δὲ τοῦ βωμοῦ λαβόμενος ἄδειαν ᾐτεῖτο παρὰ τοῦ Τιμολέοντος ἐπὶ τῷ πάντα μηνῦσαι. καὶ λαβὼν ἐμήνυσε καθ’ αὑτοῦ καὶ κατὰ τοῦ τεθνηκότος ὡς πεμφθεῖεν ἐκεῖνον ἀποκτενοῦντες. ἐν τούτῳ δὲ καὶ τὸν ἀπὸ τῆς πέτρας κατῆγον ἕτεροι, βοῶντα μηδὲν ἀδικεῖν, ἀλλ’ ἀνῃρηκέναι δικαίως τὸν ἄνθρωπον ὑπὲρ πατρὸς τεθνηκότος, ὃν ἐκεῖνος ἀπεκτονήκοι πρότερον ἐν Λεοντίνοις. καὶ μαρτυροῦντας εἶχεν ἐνίους τῶν παρόντων, θαυμάζοντας ἅμα τῆς τύχης τήν εὐμηχανίαν, ὡς δι’ ἑτέρων ἕτερα κινοῦσα καὶ συνάγουσα πάντα πόρρωθεν καὶ συγκαταπλέκουσα τοῖς πλεῖστον διαφέρειν δοκοῦσι καὶ μηδὲν ἔχειν πρὸς ἄλληλα κοινόν ἀεὶ τοῖς ἀλλήλων χρῆται καὶ τέλεσι καὶ ἀρχαῖς.", "st": "Tim. 16.5"}, {"sp": "N", "t": "τὸν μὲν οὖν ἄνθρωπον ἐστεφάνωσαν οἱ Κορίνθιοι δέκα μναῖς, ὅτι τῷ φυλάττοντι δαίμονι τὸν Τιμολέοντα πάθος ἔχρησε δίκαιον καὶ τὸν ἐκ πολλοῦ παρόντα θυμὸν αὐτῷ πρότερον οὐ κατανάλωσεν, ἀλλὰ μετ’ αἰτίας ἰδίας πρὸς τήν ἐκείνου σωτηρίαν ἀπὸ τύχης διετήρησεν. ἡ δ’ εἰς τὸν παρόντα καιρὸν εὐτυχία καὶ πρὸς τὰ μέλλοντα ταῖς ἐλπίσιν ἐπῆρεν ὁρῶντας ὡς ἱερὸν ἄνδρα καὶ σὺν θεῷ τιμωρὸν ἥκοντα τῇ Σικελίᾳ, τὸν Τιμολέοντα σέβεσθαι καὶ φυλάττειν.", "st": "Tim. 16.11"}, {"sp": "N", "t": "ὡς δὲ ταύτης διήμαρτε τῆς πείρας ὁ Ἱκέτης καὶ πρὸς Τιμολέοντα πολλοὺς ἑώρα συνισταμένους, μεμψάμενος αὐτὸς ἑαυτόν ὅτι τηλικαύτης παρούσης τῆς Καρχηδονίων δυνάμεως ὥσπερ αἰσχυνόμενος αὐτῇ κατὰ μικρὰ χρῆται καὶ λάθρα, κλέπτων καὶ παρεισάγων τὴν συμμαχίαν, μετεπέμπετο Μάγωνα τὸν στρατηγὸν αὐτῶν μετὰ τοῦ στόλου παντός, ὁ δὲ εἰσέπλει φοβερός ναυσὶ πεντήκοντα καὶ ἑκατὸν καταλαμβάνων τὸν λιμένα, πεζῶν δὲ μυριάδας ἓξ ἀποβιβάζων καὶ καταστρατοπεδεύων ἐν τῇ πόλει τῶν Συρακουσίων, ὥστε πάντας οἴεσθαι τὴν πάλαι λεγομένην καὶ προσδοκωμένην ἐκβαρβάρωσιν ἥκειν ἐπὶ τὴν Σικελίαν. οὐδέποτε γὰρ Καρχηδονίοις ὑπῆρξε πρότερον μυρίους πολεμήσασι πολέμους ἐν Σικελίᾳ λαβεῖν τὰς Συρακούσας, ἀλλὰ τότε δεξαμένου τοῦ Ἱκέτου καὶ παραδόντος ἦν ὁρᾶν τὴν πόλιν στρατόπεδον βαρβάρων οὖσαν. οἱ δὲ τὴν ἀκρόπολιν τῶν Κορινθίων κατέχοντες ἐπισφαλῶς καὶ χαλεπῶς ἀπήλλαττον, τροφῆς μὲν ἱκανῆς οὐκέτι παρούσης, ἀλλ’ ἐνδεόμενοι διὰ τὸ φρουρεῖσθαι τοὺς λιμένας, ἀεὶ δὲ ἐν ἀγῶσι καὶ μάχαις περὶ τὰ τείχη καὶ πρὸς πᾶν μηχάνημα καὶ πρὸς πᾶσαν ἰδέαν πολιορκίας μερίζοντες αὑτούς.", "st": "Tim. 17.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὁ Τιμολέων παρεβοήθει σῖτον ἐκ Κατάνης μικραῖς ἁλιάσι καὶ λεπτοῖς ἀκατίοις ἀποστέλλων, ἃ μάλιστα χειμῶνι παρεισέπιπτε διὰ τῶν βαρβαρικῶν τριήρων ὑποπορευόμενα, πρὸς τὸν κλύδωνα καὶ τὸν σάλον ἐκείνων διϊσταμένων. ἃ δὴ συνορῶντες οἱ περὶ τὸν Μάγωνα καὶ τὸν Ἱκέτην ἐβούλοντο τὴν Κατάνην ἑλεῖν, ἐξ ἧς εἰσέπλει τὰ ἐπιτήδεια τοῖς πολιορκουμένοις καὶ λαβόντες τῆς δυνάμεως τὴν μαχιμωτάτην ἐξέπλευσαν ἐκ τῶν Συρακουσῶν. ὁ δὲ Κορίνθιος Νέων οὗτος γὰρ ἦν ἄρχων τῶν πολιορκουμένων κατιδὼν ἀπὸ τῆς ἄκρας τοὺς ὑπολελειμμένους τῶν πολεμίων ἀργῶς καὶ ἀμελῶς φυλάττοντας ἐξαίφνης ἐπέπεσε διεσπαρμένοις αὐτοῖς· καὶ τοὺς μὲν ἀνελών, τοὺς δὲ τρεψάμενος, ἐκράτησε καὶ κατέσχε τὴν λεγομένην Ἀχραδινήν, ὃ κράτιστον ἐδόκει καὶ ἀθραυστότατον ὑπάρχειν τῆς Συρακουσίων μέρος πόλεως, τρόπον τινὰ συγκειμένης καὶ συνηρμοσμένης ἐκ πλειόνων πόλεων. εὐπορήσας δὲ καὶ σίτου καὶ χρημάτων οὐκ ἀφῆκε τὸν τόπον, οὐδ’ ἀνεχώρησε πάλιν ἐπὶ τὴν ἄκραν, ἀλλὰ φραξάμενος τὸν περίβολον τῆς Ἀχραδινῆς καὶ συνάψας τοῖς ἐρύμασι πρὸς τὴν ἀκρόπολιν διεφύλαττε. τοὺς δὲ περὶ τὸν Μάγωνα καὶ τὸν Ἱκέτην ἐγγὺς ἤδη τῆς Κατάνης ὄντας ἱππεὺς ἐκ Συρακουσῶν καταλαβὼν ἀπήγγειλε τὴν ἅλωσιν τῆς Ἀχραδινῆς. καὶ συνταραχθέντες ἀνεχώρησαν διὰ ταχέων, οὔτε λαβόντες ἐφ’ ἣν ἐξῆλθον οὔτε φυλάξαντες ἣν εἶχον.", "st": "Tim. 18.1"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἔτι τῇ προνοίᾳ καὶ ἀρετῇ δίδωσί τινα πρὸς τὴν τύχην ἀμφισβήτησιν τὸ δ’ ἐπὶ τούτοις γενόμενον παντάπασιν ἔοικε συμβῆναι κατ’ εὐτυχίαν. οἱ γὰρ ἐν τοῖς Θουρίοις διατρίβοντες στρατιῶται τῶν Κορινθίων ἅμα μὲν δεδιότες τὰς Καρχηδονίων τριήρεις, αἳ παρεφύλαττον αὐτοὺς μετὰ Ἄννωνος, ἅμα δ’ ἐφ’ ἡμέρας πολλὰς ἐξηγριωμένης ὑπὸ πνεύματος τῆς θαλάττης, πεζῇ διὰ Βρεττίων ὥρμησαν πορεύεσθαι· καὶ τὰ μὲν πείθοντες, τὰ δὲ βιαζόμενοι τοὺς βαρβάρους εἰς Ῥήγιον κατέβαινον ἔτι πολὺν χειμῶνα τοῦ πελάγους ἔχοντος. ὁ δὲ τῶν Καρχηδονίων ναύαρχος, ὡς οὐ προσεδόκα τοὺς Κορινθίους καὶ μάτην ᾤετο καθῆσθαι, πείσας αὐτὸς ἑαυτὸν νενοηκέναι τι τῶν σοφῶν καὶ πανούργων πρὸς ἀπάτην, στεφανώσασθαι τοὺς ναύτας κελεύσας καὶ κοσμήσας τὰς τριήρεις ἀσπίσιν Ἑλληνικαῖς καὶ φοινικίσιν, ἔπλει πρὸς τὰς Συρακούσας. καὶ παρὰ τὴν ἀκρόπολιν χρώμενος ῥοθίῳ μετὰ κρότου καὶ γέλωτος ἐβόα τοὺς Κορινθίους ἥκειν νενικηκὼς καὶ κεχειρωμένος, ἐν τῇ θαλάττῃ λαβὼν διαπλέοντας, ὡς δή τινα δυσθυμίαν τοῖς πολιορκουμένοις παρέξων. ἐκείνου δὲ ταῦτα ληροῦντος καὶ φενακίζοντος ἐκ τῶν Βρεττίων καταβεβηκότες οἱ Κορίνθιοι εἰς τὸ Ῥήγιον, ὡς οὐδεὶς παρεφύλαττε καὶ τὸ πνεῦμα κατεσβεσμένον παραλόγως ἀκύμονα τὸν πόρον ἰδεῖν καὶ λεῖον παρεῖχε, ταχὺ πληρώσαντες τὰ πορθμεῖα καὶ τὰς ἁλιάδας τὰς παρούσας ἀνήγοντο καὶ διεκομίζοντο πρὸς τὴν Σικελίαν, οὕτως ἀσφαλῶς καὶ διὰ τοσαύτης γαλήνης ὥστε τοὺς ἵππους παρὰ τὰ πλοῖα παρανηχομένους ἐκ ῥυτήρων ἐφέλκεσθαι.", "st": "Tim. 19.1"}, {"sp": "N", "t": "περαιωθέντων δὲ πάντων ὁ Τιμολέων δεξάμενος αὐτοὺς τήν τε Μεσσήνην εὐθὺς εἶχε, καὶ συνταξάμενος ἐβάδιζεν ἐπὶ τὰς Συρακούσας, οἷς εὐτύχει καὶ κατώρθου μᾶλλον ἢ τῇ δυνάμει πεποιθώς· οὐ γὰρ ἦσαν οἱ σὺν αὐτῷ πλείους τετρακισχιλίων. ἀγγελλομένης δὲ τῆς ἐφόδου τῷ Μάγωνι θορυβούμενος καὶ δεδοικὼς ἔτι μᾶλλον εἰς ὑποψίαν ἦλθεν ἐκ τοιαύτης προφάσεως. ἐν τοῖς περὶ τήν πόλιν τενάγεσι, πολὺ μὲν ἐκ κρηνῶν πότιμον ὕδωρ, πολὺ δ’ ἐξ ἑλῶν καὶ ποταμῶν καταρρεόντων εἰς τήν θάλατταν δεχομένοις, πλῆθος ἐγχέλεων νέμεται, καὶ δαψίλεια τῆς ἄγρας τοῖς βουλομένοις ἀεὶ πάρεστι. ταύτας οἱ παρ’ ἀμφοτέρων μισθοῦ στρατευόμενοι σχολῆς οὔσης καὶ ἀνοχῶν συνεθήρευον. οἷα δ’ Ἕλληνες ὄντες καὶ πρὸς ἀλλήλους οὐκ ἔχοντες ἰδίων ἀπεχθειῶν πρόφασιν, ἐν μὲν ταῖς μάχαις διεκινδύνευον εὐρώστως, ἐν δὲ ταῖς ἀνοχαῖς προσφοιτῶντες ἀλλήλοις διελέγοντο. καὶ τότε κοινὸν περὶ τήν ἁλιείαν ἔχοντες ἔργον ἐν λόγοις ἦσαν, θαυμάζοντες τῆς θαλάσσης τήν εὐφυΐαν καὶ τῶν χωρίων τήν κατασκευήν. καὶ τις εἶπε τῶν παρὰ τοῖς Κορινθίοις στρατευομένων τοσαύτην μέντοι πόλιν τὸ μέγεθος καὶ τοσούτοις ἐξησκημένην καλοῖς ὑμεῖς Ἕλληνες ὄντες ἐκβαρβαρῶσαι προθυμεῖσθε, τοὺς κακίστους καὶ φονικωτάτους Καρχηδονίους ἐγγυτέρω κατοικίζοντες ἡμῶν, πρὸς οὓς ἔδει πολλὰς εὔχεσθαι Σικελίας προκεῖσθαι τῆς Ἑλλάδος· ἢ δοκεῖτε τούτους στρατὸν ἀγείραντας ἀπὸ στηλῶν Ἡρακλείων καὶ τῆς Ἀτλαντικῆς ἥκειν θαλάττης δεῦρο κινδυνεύσοντας ὑπὲρ τῆς Ἱκέτου δυναστείας; ὃς εἰ λογισμὸν εἶχεν ἡγεμόνος, οὐκ ἂν ἐξέβαλλε τοὺς πατέρας οὐδ’ ἐπῆγε τῇ πατρίδι τοὺς πολεμίους, ἀλλὰ καὶ τιμῆς καὶ δυνάμεως ἐτύγχανεν ὅσης πρέπει, Κορινθίους καὶ Τιμολέοντα πείσας. τούτους τοὺς λόγους οἱ μισθοφόροι διεθρόησαν ἐν τῷ στρατοπέδῳ, καὶ παρέσχον ὑποψίαν τῷ Μάγωνι προδίδοσθαι, χρῄζοντι πάλαι προφάσεως. διὸ καὶ δεομένου τοῦ Ἱκέτου παραμένειν καὶ διδάσκοντος ὅσῳ βελτίονές εἰσι τῶν πολεμίων, μᾶλλον οἰόμενος ἀρετῇ καὶ τύχῃ λείπεσθαι Τιμολέοντος ἢ πλήθει δυνάμεως ὑπερβάλλειν, ἄρας εὐθὺς ἀπέπλευσεν εἰς Λιβύην, αἰσχρῶς κατ’ οὐδένα λογισμὸν ἀνθρώπινον ἐκ τῶν χειρῶν ἀφεὶς Σικελίαν.", "st": "Tim. 20.1"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ παρῆν ὁ Τιμολέων ἐπὶ μάχην συντεταγμένος· ὡς δὲ τὴν φυγὴν ἐπυνθάνοντο καὶ τὴν ἐρημίαν ἑώρων τῶν νεωρίων, γελᾶν αὐτοῖς ἐπῄει τὴν ἀνανδρίαν τοῦ Μάγωνος, καὶ περιϊόντες ἐκήρυττον ἐν τῇ πόλει μήνυτρα τῷ φράσαντι τὸν Καρχηδονίων στόλον ὅπῃ σφᾶς ἀποδέδρακεν. οὐ μὴν ἀλλὰ τοῦ Ἱκέτου φιλομαχοῦντος ἔτι καὶ τὴν λαβὴν οὐ προϊεμένου τῆς πόλεως, ἀλλὰ ἐμπεφυκότος οἷς κατεῖχε μέρεσι καρτεροῖς οὖσι καὶ δυσπροσμάχοις, διελὼν ὁ Τιμολέων τὴν δύναμιν αὐτὸς μὲν ᾗ βιαιότατον ἦν παρὰ τὸ ῥεῖθρον τοῦ Ἀνάπου προσέβαλλεν, ἄλλους δ’ ἐκ τῆς Ἀχραδινῆς ἐκέλευεν ἐπιχειρεῖν, ὧν Ἰσίας ἡγεῖτο ὁ Κορίνθιος, τοὺς δὲ τρίτους ἐπῆγον ἐπὶ τὰς Ἐπιπολὰς Δείναρχος καὶ Δημάρετος, οἱ τὴν ὑστέραν ἀγαγόντες ἐκ Κορίνθου βοήθειαν. ἅμα δὲ καὶ πανταχόθεν τῆς ἐφόδου γενομένης καὶ τῶν περὶ τὸν Ἱκέτην ἀνατραπέντων καὶ φευγόντων, τὸ μὲν ἁλῶναι τὴν πόλιν κατ’ ἄκρας καὶ γενέσθαι ταχέως ὑποχείριον ἐκπεσόντων τῶν πολεμίων δίκαιον ἀναθεῖναι τῇ τῶν μαχομένων ἀνδραγαθίᾳ καὶ τῇ δεινότητι τοῦ στρατηγοῦ, τὸ δὲ μὴ ἀποθανεῖν τινα μηδὲ τρωθῆναι τῶν Κορινθίων ἴδιον ἔργον αὑτῆς ἡ Τιμολέοντος ἐπεδείξατο τύχη, καθάπερ διαμιλλωμένη πρὸς τὴν ἀρετὴν τοῦ ἀνδρός, ἵνα τῶν ἐπαινουμένων αὐτοῦ τὰ μακαριζόμενα μᾶλλον οἱ πυνθανόμενοι θαυμάζωσιν. οὐ γὰρ μόνον Σικελίαν πᾶσαν οὐδ’ Ἰταλίαν εὐθὺς ἡ φήμη κατέσχεν, ἀλλ’ ἡμερῶν ὀλίγων ᾗ Ἑλλὰς διήχει τὸ μέγεθος τοῦ κατορθώματος, ὥστε τὴν τῶν Κορινθίων πόλιν ἀπιστοῦσαν εἰ διαπέπλευκεν ὁ στόλος, ὁμοῦ καὶ σεσῳσμένους καὶ νενικηκότας ἀκούειν τοὺς ἄνδρας. οὕτως εὐρόησαν αἱ πράξεις, καὶ τοσοῦτο τῷ κάλλει τῶν ἔργων τὸ τάχος ἡ τύχη προσέθηκεν.", "st": "Tim. 21.1"}, {"sp": "N", "t": "γενόμενος δὲ τῆς ἄκρας κύριος οὐκ ἔπαθε Δίωνι ταὐτὸ πάθος, οὐδ’ ἐφείσατο τοῦ τόπου διὰ τὸ κάλλος καὶ τὴν πολυτέλειαν τῆς κατασκευῆς, ἀλλὰ τὴν ἐκεῖνον διαβαλοῦσαν, εἶτ’ ἀπολέσασαν ὑποψίαν φυλαξάμενος ἐκήρυξε τῶν Συρακοσίων τὸν βουλόμενον παρεῖναι μετὰ σιδήρου καὶ συνεφάπτεσθαι κατασκαπτομένων τῶν τυραννικῶν ἐρυμάτων. ὡς δὲ πάντες ἀνέβησαν, ἀρχὴν ἐλευθερίας ποιησάμενοι βεβαιοτάτην τὸ κήρυγμα καὶ τὴν ἡμέραν ἐκείνην, οὐ μόνον τὴν ἄκραν, ἀλλὰ καὶ τὰς οἰκίας καὶ τὰ μνήματα τῶν τυράννων ἀνέτρεψαν καὶ κατέσκαψαν. εὐθὺς δὲ τὸν τόπον συνομαλύνας ἐνῳκοδόμησε τὰ δικαστήρια, χαριζόμενος τοῖς πολίταις καὶ τῆς τυραννίδος ὑπερτέραν ποιῶν τὴν δημοκρατίαν.", "st": "Tim. 22.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τὴν πόλιν ἑλὼν οὐκ εἶχε πολίτας, ἀλλὰ τῶν μὲν ἐν τοῖς πολέμοις καὶ ταῖς στάσεσι διαφθαρέντων, τῶν δὲ τὰς τυραννίδας φυγόντων, ἡ μὲν ἐν Συρακούσαις ἀγορὰ δι’ ἐρημίαν οὕτω πολλὴν καὶ βαθεῖαν ἐξέφυσεν ὕλην ὥστε τοὺς ἵππους ἐν αὐτῇ κατανέμεσθαι, τῶν ἱπποκόμων ἐν τῇ χλόῃ κατακειμένων, αἱ δὲ ἄλλαι πόλεις πλὴν παντελῶς ὀλίγων ἐλάφων ἐγένοντο μεσταὶ καὶ συῶν ἀγρίων, ἐν δὲ τοῖς προαστείοις καὶ περὶ τὰ τείχη πολλάκις οἱ σχολὴν ἄγοντες ἐκυνηγέτουν, ὑπήκουε δ’ οὐδεὶς τῶν ἐν τοῖς ἐρύμασι καὶ φρουρίοις κατοικούντων, οὐδὲ κατέβαινον εἰς τὴν πόλιν, ἀλλὰ φρίκη καὶ μῖσος εἶχε πάντας ἀγορᾶς καὶ πολιτείας καὶ βήματος, ἐξ ὧν ἀνέφυσαν αὐτοῖς οἱ πλεῖστοι τῶν τυράννων, ἔδοξε τῷ Τιμολέοντι καὶ τοῖς Συρακουσίοις γράψαι πρὸς τοὺς Κορινθίους ὅπως πέμψωσιν οἰκήτορας εἰς τὰς Συρακούσας ἐκ τῆς Ἑλλάδος, ἥ τε γὰρ χώρα σχολάζειν ἔμελλε, καὶ πολὺν πόλεμον ἐκ Λιβύης προσεδέχοντο, πυνθανόμενοι τοὺς Καρχηδονίους τοῦ μὲν Μάγωνος ἑαυτὸν ἀνελόντος ἀνεσταυρωκέναι τὸ σῶμα διὰ τὴν στρατηγίαν ὀργισθέντας, αὐτοὺς δὲ συνάγειν μεγάλην δύναμιν ὡς ἔτους ὥρᾳ διαβησομένους εἰς Σικελίαν.", "st": "Tim. 22.4"}, {"sp": "N", "t": "τῶν δὲ γραμμάτων τούτων παρὰ τοῦ Τιμολέοντος κομισθέντων, καὶ πρέσβεων ἅμα παρόντων Συρακουσίων καὶ δεομένων ἐπιμεληθῆναι τῆς πόλεως καὶ γενέσθαι πάλιν ἐξ ὑπαρχῆς οἰκιστάς, οὐχ ἥρπασαν οἱ Κορίνθιοι τὴν πλεονεξίαν, οὐδὲ προσεποίησαν αὑτοῖς τὴν πόλιν, ἀλλὰ πρῶτον μὲν ἐπιόντες τοὺς ἱεροὺς ἀγῶνας ἐν τῇ Ἑλλάδι καὶ τὰς μεγίστας τῶν πανηγύρεων ἀνηγόρευον ὑπὸ κηρύκων ὅτι Κορίνθιοι καταλελυκότες τὴν ἐν Συρακούσαις τυραννίδα, καὶ τὸν τύραννον ἐξεληλακότες, καλοῦσι Συρακουσίους καὶ τῶν ἄλλων Σικελιωτῶν τὸν βουλόμενον οἰκεῖν τὴν πόλιν ἐλευθέρους καὶ αὐτονόμους, ἐπ’ ἴσοις καὶ δικαίοις τὴν χώραν διαλαχόντας· ἔπειτα διαπέμποντες ἀγγέλους εἰς τὴν Ἀσίαν καὶ τὰς νήσους, ὅπου πλείστους ἐπυνθάνοντο τῶν φυγάδων διεσπαρμένους κατοικεῖν, παρεκάλουν ἰέναι πάντας εἰς Κόρινθον, ὡς Κορινθίων ἀσφαλῆ πομπὴν καὶ πλοῖα καὶ στρατηγοὺς παρεξόντων ἰδίοις τέλεσιν εἰς Συρακούσας. κηρυσσομένων δὲ τούτων ἡ μὲν πόλις τὸν δικαιότατον καὶ κάλλιστον ἀπελάμβανεν ἔπαινον καὶ ζῆλον, ἐλευθεροῦσα μὲν ἀπὸ τῶν τυράννων, σῴζουσα δ’ ἀπὸ τῶν βαρβάρων, ἀποδιδοῦσα δὲ τοῖς πολίταις τὴν χώραν.", "st": "Tim. 23.1"}, {"sp": "N", "t": "οἱ δὲ συνελθόντες εἰς Κόρινθον οὐκ ὄντες ἱκανοὶ τὸ πλῆθος ἐδεήθησαν ἐκ Κορίνθου καὶ τῆς ἄλλης Ἑλλάδος παραλαβεῖν συνοίκους· καὶ γενόμενοι μυρίων οὐκ ἐλάττους κατέπλευσαν εἰς Συρακούσας. ἤδη δὲ καὶ τῶν ἐξ Ἰταλίας καὶ Σικελίας πολλοὶ τῷ Τιμολέοντι συνεληλύθεισαν καὶ γενομένοις αὐτοῖς ἑξακισμυρίοις τὸ πλῆθος, ὡς Ἄθανις εἴρηκε, τὴν μὲν χώραν διένειμε, τὰς δὲ οἰκίας ἀπέδοτο χιλίων ταλάντων, ἅμα μὲν ὑπολειπόμενος τοῖς ἀρχαίοις Συρακουσίοις ἐξωνεῖσθαι τὰς αὑτῶν, ἅμα δὲ χρημάτων εὐπορίαν τῷ δήμῳ μηχανώμενος οὕτως πενομένῳ καὶ πρὸς τἆλλα καὶ πρὸς τὸν πόλεμον ὥστε καὶ τοὺς ἀνδριάντας ἀποδόσθαι, ψήφου διαφερομένης ὑπὲρ ἑκάστου καὶ γινομένης κατηγορίας, ὥσπερ ἀνθρώπων εὐθύνας διδόντων· ὅτε δή φασι τὸν Γέλωνος ἀνδριάντα τοῦ παλαιοῦ τυράννου διατηρῆσαι τοὺς Συρακουσίους, καταχειροτονουμένων τῶν ἄλλων, ἀγαμένους καὶ τιμῶντας τὸν ἄνδρα τῆς νίκης ἣν πρὸς Ἱμέρᾳ Καρχηδονίους ἐνίκησεν.", "st": "Tim. 23.5"}, {"sp": "N", "t": "οὕτω δὲ τῆς πόλεως ἀναζωπυρούσης καὶ πληρουμένης, ἐπιρρεόντων πανταχόθεν εἰς αὐτὴν τῶν πολιτῶν, βουλόμενος ὁ Τιμολέων καὶ τὰς ἄλλας πόλεις ἐλευθερῶσαι καὶ παντάπασιν ἐκκόψαι τῆς Σικελίας τὰς τυραννίδας, ἐπὶ τὰς χώρας αὐτῶν στρατεύων Ἱκέτην μὲν ἠνάγκασεν ἀποστάντα Καρχηδονίων ὁμολογῆσαι τὰς ἀκροπόλεις κατασκάψειν καὶ βιοτεύσειν ἰδιώτην ἐν Λεοντίνοις, Λεπτίνου δὲ τοῦ τυραννοῦντος Ἀπολλωνίας καὶ συχνῶν ἄλλων πολιχνίων, ὡς ἐκινδύνευε κατὰ κράτος ἁλῶναι, παραδόντος αὑτόν φεισάμενος εἰς Κόρινθον ἀπέστειλε, καλὸν ἡγούμενος ἐν τῇ μητροπόλει τοὺς τῆς Σικελίας τυράννους ὑπὸ τῶν Ἑλλήνων ἀποθεωρεῖσθαι φυγαδικῶς καὶ ταπεινῶς ζῶντας. τοὺς δὲ μισθοφόρους βουλόμενος ἐκ τῆς πολεμίας ὠφελεῖσθαι καὶ μὴ σχολάζειν, αὐτὸς μὲν εἰς τὰς Συρακούσας ἐπανῆλθε τῇ καταστάσει τῆς πολιτείας προσέξων καὶ τοῖς ἥκουσιν ἐκ Κορίνθου νομοθέταις Κεφάλῳ καὶ Διονυσίῳ τὰ κυριώτατα καὶ κάλλιστα συνδιαθήσων, τοὺς δὲ περὶ Δείναρχον καὶ Δημάρετον εἰς τὴν τῶν Καρχηδονίων ἐξέπεμψεν ἐπικράτειαν, οἳ πόλεις πολλὰς ἀφιστάντες τῶν βαρβάρων οὐ μόνον αὐτοὶ διῆγον ἐν ἀφθόνοις, ἀλλὰ καὶ χρήματα παρεσκεύαζον εἰς τὸν πόλεμον ἀπὸ τῶν ἁλισκομένων.", "st": "Tim. 24.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Καρχηδόνιοι καταπλέουσιν εἰς τὸ Λιλύβαιον ἄγοντες ἑπτὰ μυριάδας στρατοῦ καὶ τριήρεις διακοσίας καὶ πλοῖα χίλια κομίζοντα μηχανὰς καὶ τέθριππα καὶ σῖτον ἄφθονον καὶ τὴν ἄλλην παρασκευήν, ὡς οὐκέτι ποιησόμενοι κατὰ μέρος τὸν πόλεμον, ἀλλ’ ὁμοῦ πάσης Σικελίας ἐξελάσοντες τοὺς Ἕλληνας· ἦν γὰρ ἡ δύναμις ἐπαρκοῦσα καὶ μὴ νοσοῦντας μηδὲ διεφθαρμένους ὑπ’ ἀλλήλων συλλαβέσθαι Σικελιώτας. πυθόμενοι δὲ πορθεῖσθαι τὴν ἐπικράτειαν αὐτῶν, εὐθὺς ὀργῇ πρὸς τοὺς Κορινθίους ἐχώρουν Ἀσδρούβα τε καὶ Ἀμίλκα στρατηγούντων. τῆς δὲ ἀγγελίας ὀξέως εἰς Συρακούσας ἀφικομένης οὕτω κατεπλάγησαν οἱ Συρακούσιοι πρὸς τὸ μέγεθος τῆς δυνάμεως ὥστε μόλις τῷ Τιμολέοντι τρισχιλίους ἀπὸ τοσούτων μυριάδων ὅπλα λαβόντας τολμῆσαι συνεξελθεῖν. οἱ δὲ μισθοφόροι τετρακισχίλιοι τὸ πλῆθος ἦσαν καὶ τούτων αὖθις ὅσον χίλιοι καθ’ ὁδὸν ἀποδειλιάσαντες ἀνεχώρησαν, ὡς οὐχ ὑγιαίνοντος τοῦ Τιμολέοντος, ἀλλὰ μαινομένου παρ’ ἡλικίαν καὶ πρὸς ἑπτὰ μυριάδας πολεμίων μετὰ πεντακισχιλίων πεζῶν καὶ χιλίων ἱππέων βαδίζοντος, καὶ διαρτῶντος ὁδὸν ἡμερῶν ὀκτὼ τὴν δύναμιν ἀπὸ τῶν Συρακουσῶν, ὅθεν οὔτε σωθῆναι τοῖς φεύγουσιν οὔτε ταφῆναι τοῖς πεσοῦσιν αὐτῶν ὑπάρξει, τούτους μὲν οὖν Τιμολέων κέρδος ἡγεῖτο πρὸ τῆς μάχης φανεροὺς γεγονότας, τοὺς δὲ ἄλλους ἐπιρρώσας κατὰ τάχος ἦγε πρὸς τὸν Κρίμησον ποταμόν, ὅπου καὶ τοὺς Καρχηδονίους ἤκουσε συνάπτειν.", "st": "Tim. 25.1"}, {"sp": "N", "t": "ἀναβαίνοντι δὲ αὐτῷ πρὸς λόφον, ὃν ὑπερβαλόντες ἔμελλον κατόψεσθαι τὸ στράτευμα καὶ τὴν δύναμιν τῶν πολεμίων, ἐμβάλλουσιν ἡμίονοι σέλινα κομίζοντες· καὶ τοῖς στρατιώταις εἰσῆλθε πονηρὸν εἶναι τὸ σημεῖον, ὅτι τὰ μνήματα τῶν νεκρῶν εἰώθαμεν ἐπιεικῶς στεφανοῦν σελίνοις· καὶ παροιμία τις ἐκ τούτου γέγονε, τὸν ἐπισφαλῶς νοσοῦντα δεῖσθαι σελίνου. βουλόμενος οὖν αὐτοὺς ἀπαλλάξαι τῆς δεισιδαιμονίας καὶ τὴν δυσελπιστίαν ἀφελεῖν ὁ Τιμολέων, ἐπιστήσας τὴν πορείαν ἄλλα τε πρέποντα τῷ καιρῷ διελέχθη, καὶ τὸν στέφανον αὐτοῖς ἔφη πρὸ τῆς νίκης κομιζόμενον αὐτομάτως εἰς τὰς χεῖρας ἥκειν, ᾧ Κορίνθιοι στεφανοῦσι τοὺς Ἴσθμια νικῶντας, ἱερὸν καὶ πάτριον τὸ στέμμα τοῦ σελίνου νομίζοντες. ἔτι γὰρ τότε τῶν Ἰσθμίων, ὥσπερ νῦν τῶν Νεμείων, τὸ σέλινον ἦν στέφανος, οὐ πάλαι δὲ ἡ πίτυς γέγονεν. ἐντυχὼν οὖν ὁ Τιμολέων, ὥσπερ εἴρηται, τοῖς στρατιώταις καὶ λαβὼν τῶν σελίνων κατεστέψατο πρῶτος αὐτός, εἶτα οἱ περὶ αὐτὸν ἡγεμόνες καὶ τὸ πλῆθος. οἱ δὲ μάντεις κατιδόντες ἀετοὺς δύο προσφερομένους, ὧν ὁ μὲν δράκοντα τοῖς ὄνυξιν ἔφερε διαπεπαρμένον, ὁ δὲ ἵπτατο κεκλαγὼς μέγα καὶ θαρραλέον, ἐπεδείκνυον τοῖς στρατιώταις, καὶ πρὸς εὐχὰς θεῶν καὶ ἀνακλήσεις ἐτράποντο πάντες.", "st": "Tim. 26.1"}, {"sp": "N", "t": "τὸ μὲν οὖν ἔτος ἱσταμένου θέρους εἶχεν ὥραν, καὶ λήγοντι μηνὶ Θαργηλιῶνι πρὸς τὰς τροπὰς ἤδη συνῆπτε τὸν καιρόν· ὁμίχλην δὲ τοῦ ποταμοῦ πολλὴν ἀναδιδόντος πρῶτον μὲν ἀπεκρύπτετο ζόφῳ τὸ πεδίον, καὶ σύνοπτον οὐδὲν ἦν ἀπὸ τῶν πολεμίων, πλὴν ἠχή τις ἄκριτος καὶ συμμιγὴς ἄνω πρὸς τὸν λόφον ἐχώρει πρόσωθεν ἀνισταμένης στρατιᾶς τοσαύτης. ὡς δ’ ἀναβάντες ἐπὶ τὸν λόφον ἔστησαν οἱ Κορίνθιοι καὶ θέμενοι τὰς ἀσπίδας διανεπαύοντο, τοῦ ἡλίου περιφερομένου καὶ μετεωρίζοντος τὴν ἀναθυμίασιν, ὁ μὲν θολερὸς ἀὴρ ἀθροιζόμενος πρὸς τὰ ὑψηλὰ καὶ συνιστάμενος κατενέφωσε τὰς ἀκρωρείας, τῶν δὲ ὑπὸ πόδας τόπων ἀνακαθαιρομένων ὅ τε Κρίμησος ἐξεφάνη καὶ διαβαίνοντες αὑτὸν ὤφθησαν οἱ πολέμιοι, πρώτοις μὲν τοῖς τεθρίπποις ἐκπληκτικῶς πρὸς ἀγῶνα κατεσκευασμένοις, κατόπιν δὲ τούτων μυρίοις ὁπλίταις λευκάσπισι. τούτους ἐτεκμαίροντο Καρχηδονίους εἶναι τῇ λαμπρότητι τῆς σκευῆς καὶ τῇ βραδυτῆτι καὶ τάξει τῆς πορείας. μετὰ δὲ τούτους τῶν λοιπῶν ἐθνῶν ἐπιρρεόντων καὶ τὴν διάβασιν μετ’ ὠθισμοῦ καὶ ταραχῆς ποιουμένων, συνιδὼν ὁ Τιμολέων τὸν ποταμὸν αὐτοῖς ταμιεύοντα τοῦ πλήθους τῶν πολεμίων ἀπολαβεῖν ὅσοις ἐθέλοιεν αὐτοὶ μάχεσθαι, καὶ τοὺς στρατιώτας καθορᾶν κελεύσας τὴν φάλαγγα τῷ ῥείθρῳ διαλελυμένην καὶ τοὺς μὲν ἤδη διαβεβηκότας, τοὺς δὲ μέλλοντας, προσέταξε Δημαρέτῳ λαβόντι τοὺς ἱππεῖς ἐμβαλεῖν εἰς τοὺς Καρχηδονίους καὶ συνταράξαι τὸν διάκοσμον αὐτῶν τῆς παρατάξεως οὔπω καθεστώσης. αὐτὸς δὲ καταβὰς εἰς τὸ πεδίον τὰ μὲν κέρατα τοῖς ἄλλοις Σικελιώταις ἀπέδωκεν, ἀναμίξας ἑκατέρῳ τῶν ξένων οὐ πολλούς, ἐν μέσῳ δὲ περὶ αὑτὸν λαβὼν τοὺς Συρακουσίους καὶ τὸ μαχιμώτατον τῶν μισθοφόρων βραχὺν μὲν χρόνον ἐπέσχε τὸ τῶν ἱππέων ἀποθεωρῶν ἔργον, ὡς δὲ ἐκείνους εἶδεν ὑπὸ τῶν ἁρμάτων πρὸ τῆς τάξεως διαθεόντων εἰς χεῖρας ἐλθεῖν τοῖς Καρχηδονίοις οὐ δυναμένους, ἀλλ’ ὅπως μὴ συνταραχθεῖεν ἀναγκαζομένους ἐξελίττειν συνεχῶς καὶ πυκνὰς ἐξ ἐπιστροφῆς ποιεῖσθαι τὰς ἐπελάσεις, ἀναλαβὼν τὴν ἀσπίδα καὶ βοήσας ἕπεσθαι καὶ θαρρεῖν τοῖς πεζοῖς ἔδοξεν ὑπερφυεῖ φωνῇ καὶ μείζονι κεχρῆσθαι τῆς συνήθους, εἴτε τῷ πάθει παρὰ τὸν ἀγῶνα καὶ τὸν ἐνθουσιασμὸν οὕτω διατεινάμενος, εἴτε δαιμονίου τινός, ὡς τοῖς πολλοῖς τότε παρέστη, συνεπιφθεγξαμένου. ταχὺ δὲ τὴν κραυγὴν ἀνταποδόντων, καὶ παρεγγυώντων ἄγειν καὶ μὴ μέλλειν, τοῖς μὲν ἱππόταις ἐσήμανεν ἔξω παρὰ τὴν τάξιν τῶν ἁρμάτων παρελάσαι καὶ κατὰ κέρας προσφέρεσθαι τοῖς πολεμίοις, αὐτὸς δὲ τοὺς προμάχους πυκνώσας τῷ συνασπισμῷ, καὶ τὴν σάλπιγγα κελεύσας ἐπιφθέγξασθαι, προσέβαλε τοῖς Καρχηδονίοις.", "st": "Tim. 27.1"}, {"sp": "N", "t": "οἱ δὲ τὴν μὲν πρώτην ἐπιδρομὴν ὑπέστησαν ἐρρωμένως, καὶ τῷ καταπεφράχθαι τὰ σώματα σιδηροῖς θώραξι καὶ χαλκοῖς κράνεσιν ἀσπίδας τε μεγάλας προβεβλῆσθαι διεκρούοντο τὸν δορατισμόν. ἐπεὶ δὲ εἰς ξίφη συνῆλθεν ὁ ἀγών καί τέχνης οὐχ ἧττον ἢ ῥώμης ἐγεγόνει τὸ ἔργον, ἐξαίφνης ἀπὸ τῶν ὀρῶν βρονταί τε φοβεραὶ κατερρήγνυντο καὶ πυρώδεις ἀστραπαὶ συνεξέπιπτον. εἶτα ὁ περὶ τοὺς λόφους καὶ τὰς ἀκρωρείας ζόφος ἐπὶ τὴν μάχην κατιών, ὄμβρῳ καὶ πνεύματι καὶ χαλάζῃ συμμεμιγμένος, τοῖς μὲν Ἕλλησιν ἐξόπισθεν καὶ κατὰ νώτου περιεχεῖτο, τῶν δὲ βαρβάρων ἔτυπτε τὰ πρόσωπα καὶ κατήστραπτε τὰς ὄψεις, ἅμα λαίλαπος ὑγρᾶς καὶ φλογὸς συνεχοῦς ἐκ τῶν νεφῶν φερομένης. ἐν οἷς πολλὰ μὲν ἦν τὰ λυποῦντα, καὶ μάλιστα τοὺς ἀπείρους, οὐχ ἥκιστα δὲ βλάψαι δοκοῦσιν αἱ βρονταί καὶ τῶν ὅπλων ὁ πάταγος κοπτομένων ὕδατι ῥαγδαίῳ καὶ χαλάζῃ, κωλύων ἀκούεσθαι τὰ προστάγματα τῶν ἡγεμόνων. τοῖς δὲ Καρχηδονίοις οὐκ οὖσιν εὐζώνοις τὸν ὁπλισμόν, ἀλλ’, ὥσπερ εἴρηται, καταπεφραγμένοις, ὅ τε πηλὸς ἐμπόδιος ἦν οἵ τε κόλποι πληρούμενοι τῶν χιτώνων ὕδατος, ὥσθ’ αὑτοῖς μὲν εἰς τὸν ἀγῶνα χρῆσθαι βαρεῖς ἦσαν καὶ δύσεργοι, ῥᾴδιοι δὲ τοῖς Ἕλλησι περιτρέπεσθαι, καὶ πεσόντες ἀμήχανοι πάλιν ἐκ πηλοῦ μετὰ τῶν ὅπλων ἀναστῆναι. καὶ γὰρ ὁ Κρίμησος ὑπὸ τῶν διαβαινόντων ἐκλύσθη μέγας ἤδη τοῖς ὄμβροις ηὐξημένος, καὶ τὸ πεδίον τὸ περὶ αὐτόν ὑπὸ πολλὰς συναγκείας καὶ φάραγγας ὑποκείμενον ἐπίμπλατο ῥευμάτων οὐ κατὰ πόρον φερομένων, οἷς οἱ Καρχηδόνιοι καλινδούμενοι χαλεπῶς ἀπήλλαττον. τέλος δὲ τοῦ χειμῶνος ἐπικειμένου, καὶ τῶν Ἑλλήνων τὴν πρώτην τάξιν αὐτῶν, ἄνδρας τετρακοσίους, καταβαλόντων, ἐτράπη τὸ πλῆθος εἰς φυγήν. καὶ πολλοὶ μὲν ἐν τῷ πεδίῳ καταλαμβανόμενοι διεφθείροντο, πολλοὺς δὲ ὁ ποταμὸς τοῖς ἔτι περαιουμένοις συμπίπτοντας ἐμβάλλων καὶ παραφέρων ἀπώλλυε, πλείστους δὲ τῶν λόφων ἐφιεμένους ἐπιθέοντες οἱ ψιλοὶ κατειργάσαντο. λέγονται γοῦν ἐν μυρίοις νεκροῖς τρισχίλιοι Καρχηδονίων γενέσθαι, μέγα τῇ πόλει πένθος. οὔτε γὰρ γένεσιν οὔτε πλούτοις οὔτε δόξαις ἕτεροι βελτίονες ἦσαν ἐκείνων, οὔτε ἀποθανόντας ποτὲ μιᾷ μάχῃ πρότερον ἐξ αὐτῶν Καρχηδονίων τοσούτους μνημονεύουσιν, ἀλλὰ Λίβυσι τὰ πολλὰ καὶ Ἴβηρσι καὶ Νομάσι χρώμενοι πρὸς τὰς μάχας ἀλλοτρίαις βλάβαις ἀνεδέχοντο τὰς ἥττας.", "st": "Tim. 28.1"}, {"sp": "N", "t": "ἐγνώσθη δὲ τοῖς Ἕλλησιν ἡ δόξα τῶν πεσόντων ἀπὸ τῶν λαφύρων, ἐλάχιστος γὰρ ἦν χαλκῶν καὶ σιδηρῶν τοῖς σκυλεύουσι λόγος· οὕτως ἄφθονος μὲν ἦν ἄργυρος, ἄφθονος δὲ χρυσός, καὶ γὰρ τὸ στρατόπεδον μετὰ τῶν ὑποζυγίων διαβάντες ἔλαβον. τῶν δ’ αἰχμαλώτων οἱ μὲν πολλοὶ διεκλάπησαν ὑπὸ τῶν στρατιωτῶν, εἰς δὲ κοινὸν ἀπεδείχθησαν πεντακισχίλιοι τὸ πλῆθος· ἥλω δὲ καὶ διακόσια τῶν τεθρίππων. καλλίστην δὲ καὶ μεγαλοπρεπεστάτην ὄψιν ἡ Τιμολέοντος ἐπεδείκνυτο σκηνή περισωρευθεῖσα παντοδαποῖς λαφύροις, ἐν οἷς χίλιοι μὲν θώρακες ἐργασίᾳ, καὶ κάλλει διαφέροντες, μύριαι δὲ ἀσπίδες προετέθησαν. ὀλίγοι δὲ πολλοὺς σκυλεύοντες καὶ μεγάλαις ἐντυγχάνοντες ὠφελείαις τρίτῃ μόλις ἡμέρᾳ μετὰ τὴν μάχην ἔστησαν τρόπαιον.", "st": "Tim. 29.1"}, {"sp": "N", "t": "ἅμα δὲ τῇ φήμῃ τῆς νίκης ὁ Τιμολέων εἰς Κόρινθον ἔπεμψε τὰ κάλλιστα τῶν αἰχμαλώτων ὅπλων, βουλόμενος αὐτοῦ τὴν πατρίδα πᾶσιν ἀνθρώποις ζηλωτὴν εἶναι, θεωμένοις ἐν ἐκείνῃ μόνῃ τῶν Ἑλληνικῶν πόλεων τοὺς ἐπιφανεστάτους ναοὺς οὐχ Ἑλληνικοῖς κεκοσμημένους λαφύροις οὐδ’ ἀπὸ συγγενῶν φόνου καὶ ὁμοφύλων ἀναθημάτων μνήμας ἀτερπεῖς ἔχοντας, ἀλλὰ βαρβαρικὰ σκῦλα καλλίσταις ἐπιγραφαῖς δηλοῦντα μετὰ τῆς ἀνδρείας τῶν νενικηκότων τὴν δικαιοσύνην, ὅτι Κορίνθιοι καὶ Τιμολέων ὁ στρατηγός ἐλευθερώσαντες τοὺς Σικελίαν οἰκοῦντας Ἕλληνας ἀπὸ Καρχηδονίων χαριστήρια θεοῖς ἀνέθηκαν.", "st": "Tim. 29.5"}, {"sp": "N", "t": "ἐκ τούτου καταλιπὼν ἐν τῇ πολεμίᾳ τοὺς μισθοφόρους ἄγοντας καὶ φέροντας τὴν τῶν Καρχηδονίων ἐπικράτειαν, αὐτὸς ἧκεν εἰς Συρακούσας· καὶ τοὺς χιλίους μισθοφόρους ἐκείνους, ὑφ’ ὧν ἐγκατελείφθη πρὸ τῆς μάχης, ἐξεκήρυξε τῆς Σικελίας, καὶ πρὶν ἢ δῦναι τὸν ἥλιον ἠνάγκασεν ἐκ Συρακουσῶν ἀπελθεῖν. οὗτοι μὲν οὖν διαπλεύσαντες εἰς Ἰταλίαν ἀπώλοντο παρασπονδηθέντες ὑπὸ Βρεττίων, καὶ δίκην ταύτην τὸ δαιμόνιον αὐτοῖς τῆς προδοσίας ἐπέθηκε. τῶν δὲ περὶ τὸν Μάμερκον, τὸν Κατάνης τύραννον, καὶ Ἱκέτην, εἴτε φθόνῳ τῶν κατορθουμένων ὑπὸ Τιμολέοντος, εἴτε φοβουμένων αὐτὸν ὡς ἄπιστον καὶ ἄσπονδον πρὸς τοὺς τυράννους, συμμαχίαν ποιησαμένων πρὸς τοὺς Καρχηδονίους καὶ κελευσάντων πέμπειν δύναμιν καὶ στρατηγόν, εἰ μὴ παντάπασι βούλονται Σικελίας ἐκπεσεῖν, ἔπλευσε Γέσκων ναῦς μὲν ἔχων ἑβδομήκοντα, μισθοφόρους δὲ προσλαβὼν Ἕλληνας, οὔπω πρότερον Ἕλλησι χρησαμένων Καρχηδονίων, ἀλλὰ τότε θαυμασάντων ὡς ἀνυποστάτους καὶ μαχιμωτάτους ἀνθρώπων ἁπάντων. συστάντες δὲ κοινῇ μετ’ ἀλλήλων ἅπαντες ἐν τῇ Μεσσηνίᾳ τετρακοσίους τῶν παρὰ Τιμολέοντος ξένων ἐπικούρους πεμφθέντας ἀπέκτειναν, ἐν δὲ τῇ Καρχηδονίων ἐπικρατείᾳ περὶ τὰς καλουμένας Ἱερὰς ἐνεδρεύσαντες τοὺς μετ’ Εὐθύμου τοῦ Λευκαδίου μισθοφόρους διέφθειραν. ἐξ ὧν καὶ μάλιστα τὴν Τιμολέοντος εὐτυχίαν συνέβη γενέσθαι διώνυμον. ἦσαν μὲν γὰρ οὗτοι τῶν μετὰ Φιλομήλου τοῦ Φωκέως καὶ Ὀνομάρχου Δελφοὺς καταλαβόντων καὶ μετασχόντων ἐκείνοις τῆς ἱεροσυλίας. μισούντων δὲ πάντων αὐτοὺς καὶ φυλαττομένων ἐπαράτους γεγονότας, πλανώμενοι περὶ τὴν Πελοπόννησον ὑπὸ Τιμολέοντος ἐλήφθησαν ἑτέρων στρατιωτῶν οὐκ εὐποροῦντος. ἀφικόμενοι δὲ εἰς Σικελίαν ὅσας μὲν ἐκείνῳ συνηγωνίσαντο μάχας πάσας ἐνίκων, τῶν δὲ πλείστων καὶ μεγίστων ἀγώνων τέλος ἐχόντων ἐκπεμπόμενοι πρὸς ἑτέρας ὑπ’ αὐτοῦ βοηθείας ἀπώλοντο καὶ καταναλώθησαν, οὐχ ὁμοῦ πάντες, ἀλλὰ κατὰ μέρος, τῆς δίκης αὐτοῖς ἀπολογουμένης τῇ Τιμολέοντος εὐτυχίᾳ ἐπιτιθεμένης ὅπως μηδεμία τοῖς ἀγαθοῖς ἀπὸ τῆς τῶν κακῶν κολάσεως βλάβη γένηται. τὴν μὲν οὖν πρὸς Τιμολέοντα τῶν θεῶν εὐμένειαν οὐχ ἧττον ἐν αἷς προσέκρουσε πράξεσιν ἢ περὶ ἃς κατώρθου θαυμάζεσθαι συνέβαινεν.", "st": "Tim. 30.1"}, {"sp": "N", "t": "οἱ δὲ πολλοὶ τῶν Συρακουσίων ἐχαλέπαινον ὑπὸ τῶν τυράννων προπηλακιζόμενοι. καὶ γὰρ ὁ Μάμερκος ἐπὶ τῷ ποιήματα γράφειν καὶ τραγῳδίας μέγα φρονῶν ἐκόμπαζε νικήσας τοὺς μισθοφόρους, καὶ τὰς ἀσπίδας ἀναθεὶς τοῖς θεοῖς ἐλεγεῖον ὑβριστικὸν ἐπέγραψε·", "st": "Tim. 31.1"}, {"sp": "N", "t": "τάσδ’ ὀστρειογραφεῖς καὶ χρυσελεφαντηλέκτρους ἀσπίδας ἀσπιδίοις εἵλομεν εὐτελέσι.", "st": "Tim. 31.1b"}, {"sp": "N", "t": "γενομένων δὲ τούτων καὶ τοῦ Τιμολέοντος εἰς Καλαυρίαν στρατεύσαντος, ὁ Ἱκέτης ἐμβαλὼν εἰς τὴν Συρακουσίαν λείαν τε συχνὴν ἔλαβε καὶ πολλὰ λυ μηνάμενος καὶ καθυβρίσας ἀπηλλάττετο παρ’ αὐτὴν τὴν Καλαυρίαν, καταφρονῶν τοῦ Τιμολέοντος ὀλίγους στρατιώτας ἔχοντος. ἐκεῖνος δὲ προλαβεῖν ἐάσας ἐδίωκεν ἱππεῖς ἔχων καὶ ψιλούς, αἰσθόμενος δὲ ὁ Ἱκέτης τὸν Δαμυρίαν διαβεβηκώς ὑπέστη παρὰ τὸν ποταμὸν ὡς ἀμυνούμενος· καὶ γὰρ αὐτῷ θάρσος ἥ τε τοῦ πόρου χαλεπότης καὶ τὸ κρημνῶδες τῆς ἑκατέρωθεν ὄχθης παρεῖχε, τοῖς δὲ μετὰ τοῦ Τιμολέοντος ἰλάρχαις ἔρις ἐμπεσοῦσα θαυμαστὴ καὶ φιλονεικία διατριβὴν ἐποίει τῆς μάχης. οὐδεὶς γὰρ ἦν ὁ βουλόμενος ἑτέρου διαβαίνειν ὕστερος ἐπὶ τοὺς πολεμίους, ἀλλ’ αὐτὸς ἕκαστος ἠξίου πρωταγωνιστεῖν, καὶ κόσμον οὐκ εἶχεν ἡ διάβασις ἐξωθούντων καὶ παρατρεχόντων ἀλλήλους. βουλόμενος οὖν ὁ Τιμολέων κληρῶσαι τοὺς ἡγεμόνας ἔλαβε παρ’ ἑκάστου δακτύλιον· ἐμβαλὼν δὲ πάντας εἰς τὴν ἑαυτοῦ χλαμύδα καὶ μίξας ἔδειξε τὸν πρῶτον κατὰ τύχην γλυφὴν ἔχοντα τῆς σφραγῖδος τρόπαιον. ὡς δὲ τοῦτον εἶδον οἱ νεανίσκοι, μετὰ χαρᾶς ἀνακραγόντες οὐκέτι τὸν ἄλλον ὑπέμειναν κλῆρον, ἀλλ’ ὡς ἕκαστος τάχους εἶχε τὸν ποταμὸν διεξελάσαντες ἐν χερσὶν ἦσαν τοῖς πολεμίοις. οἱ δὲ οὐκ ἐδέξαντο τὴν βίαν αὐτῶν, ἀλλὰ φεύγοντες τῶν μὲν ὅπλων ἅπαντες ὁμαλῶς ἐστερήθησαν, χιλίους δὲ ἀπέβαλον πεσόντας.", "st": "Tim. 31.2"}, {"sp": "N", "t": "οὐ πολλῷ δὲ ὕστερον εἰς τὴν Λεοντίνων στρατεύσας ὁ Τιμολέων λαμβάνει τὸν Ἱκέτην ζῶντα καὶ τὸν υἱὸν Εὐπόλεμον καὶ τὸν ἱππάρχην Εὔθυμον, ὑπὸ τῶν στρατιωτῶν συνδεθέντας καὶ κομισθέντας πρὸς αὐτόν. ὁ μὲν οὖν Ἱκέτης καὶ τὸ μειράκιον ὡς τύραννοι καὶ προδόται κολασθέντες ἀπέθνῃσκον, ὁ δ’ Εὔθυμος, ἀνὴρ ἀγαθὸς ὢν πρὸς τοὺς ἀγῶνας καὶ τόλμῃ διαφέρων, οὐκ ἔτυχεν οἴκτου διὰ βλασφημίαν τινὰ πρὸς τοὺς Κορινθίους κατηγορηθεῖσαν αὐτοῦ, λέγεται γὰρ ὅτι τῶν Κορινθίων ἐκστρατευσαμένων ἐπ’ αὐτούς δημηγορῶν ἐν τοῖς Λεοντίνοις οὐδὲν ἔφη γεγονέναι φοβερὸν οὐδὲ δεινόν, εἰ", "st": "Tim. 32.1"}, {"sp": "N", "t": "Κορίνθιαι γυναῖκες ἐξῆλθον δόμων.", "st": "Tim. 32.1b"}, {"sp": "N", "t": "οὕτως ὑπὸ λόγων μᾶλλον ἢ πράξεων πονηρῶν ἀνιᾶσθαι πεφύκασιν οἱ πολλοί· χαλεπώτερον γὰρ ὕβριν ἢ βλάβην φέρουσι. καὶ τὸ μὲν ἀμύνεσθαι δι’ ἔργων ὡς ἀναγκαῖον δέδοται τοῖς πολεμοῦσιν, αἱ δὲ βλασφημίαι περιουσίᾳ μίσους ἢ κακίας γίνεσθαι δοκοῦσιν.", "st": "Tim. 32.4"}, {"sp": "N", "t": "ἐπανελθόντος δὲ τοῦ Τιμολέοντος οἱ Συρακούσιοι τὰς γυναῖκας τῶν περὶ τὸν Ἱκέτην καὶ τὰς θυγατέρας ἐν ἐκκλησίᾳ καταστήσαντες εἰς κρίσιν ἀπέκτειναν. καὶ δοκεῖ τοῦτο τῶν Τιμολέοντος ἔργων ἀχαριστότατον γενέσθαι· μὴ γὰρ ἂν ἐκείνου κωλύοντος οὕτως τὰς ἀνθρώπους ἀποθανεῖν. δοκεῖ δὲ αὐτὰς ὑπεριδεῖν καὶ προέσθαι τῷ θυμῷ τῶν πολιτῶν δίκην λαμβανόντων ὑπὲρ Δίωνος τοῦ Διονύσιον ἐκβαλόντος. Ἱκέτης γάρ ἐστιν ὁ τὴν γυναῖκα τοῦ Δίωνος Ἀρετὴν καὶ τὴν ἀδελφὴν Ἀριστομάχην καὶ τὸν υἱὸν ἔτι παῖδα καταποντίσας ζῶντας, περὶ ὧν ἐν τῷ Δίωνος γέγραπται βίῳ.", "st": "Tim. 33.1"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα στρατεύσας ἐπὶ Μάμερκον εἰς Κατάνην καὶ περὶ τὸ ῥεῦμα τὴν Ἄβολον ἐκ παρατάξεως ὑποστάντα νικήσας καὶ τρεψάμενος ὑπὲρ δισχιλίους ἀνεῖλεν, ὧν μέρος οὐκ ὀλίγον ἦσαν οἱ πεμφθέντες ὑπὸ Γέσκωνος ἐπίκουροι Φοίνικες. ἐκ δὲ τούτου Καρχηδόνιοι μέν εἰρήνην ἐποιήσαντο πρὸς αὐτὸν δεηθέντες, ὥστε τὴν ἐντὸς τοῦ Λύκου χώραν ἔχειν, καὶ τοῖς βουλομένοις ἐξ αὐτῆς μετοικεῖν πρὸς Συρακουσίους χρήματα καὶ γενεὰς ἀποδιδόντες, καὶ τοῖς τυράννοις ἀπειπάμενοι τὴν συμμαχίαν. Μάμερκος δὲ δυσθυμῶν ταῖς ἐλπίσιν ἔπλει μέν εἰς Ἰταλίαν ὡς Λευκανοὺς ἐπάξων Τιμολέοντι καὶ Συρακουσίοις, ἐπεὶ δὲ ἀποστρέψαντες οἱ σὺν αὐτῷ τὰς τριήρεις καὶ πλεύσαντες εἰς Σικελίαν τῷ Τιμολέοντι τὴν Κατάνην παρέδωκαν, ἀναγκασθεὶς καὶ αὐτὸς εἰς Μεσσήνην κατέφυγε πρός Ἵππωνα τὸν τυραννοῦντα τῆς πόλεως, ἐπελθόντος δὲ τοῦ Τιμολέοντος αὐτοῖς καὶ πολιορκοῦντος ἔκ τε γῆς καὶ θαλάττης, ὁ μέν Ἵππων ἀποδιδράσκων ἐπὶ νεὼς ἥλω, καὶ παραλαβόντες αὐτὸν οἱ Μεσσήνιοι, καὶ τοὺς παῖδας ἐκ τῶν διδασκαλείων ὡς ἐπὶ θέαμα κάλλιστον τὴν τοῦ τυράννου τιμωρίαν ἀγαγόντες εἰς θέατρον, ᾐκίσαντο καὶ διέφθειραν· ὁ δὲ Μάμερκος ἑαυτὸν Τιμολέοντι παρέδωκεν ἐπὶ τῷ δίκην ὑποσχεῖν ἐν Συρακουσίοις μὴ κατηγοροῦντος Τιμολέοντος. ἀχθεὶς δὲ εἰς τὰς Συρακούσας, παρελθὼν εἰς τὸν δῆμον ἐπεχείρει μέν τινα συγκείμενον ἐκ παλαιοῦ λόγον ὑπ’ αὐτοῦ διεξιέναι, θορύβοις δὲ περιπίπτων καὶ τὴν ἐκκλησίαν ὁρῶν ἀπαραίτητον ἔθει ῥίψας τὸ ἱμάτιον διὰ μέσου τοῦ θεάτρου, καὶ πρός τι τῶν βάθρων δρόμῳ φερόμενος συνέρρηξε τὴν κεφαλὴν ὡς ἀποθανούμενος. οὐ μὴν ἔτυχέ γε ταύτης τῆς τελευτῆς, ἀλλ’ ἔτι ζῶν ἀπαχθεὶς ἥνπερ οἱ λῃσταὶ δίκην ἔδωκε.", "st": "Tim. 34.1"}, {"sp": "N", "t": "τὰς μὲν οὖν τυραννίδας ὁ Τιμολέων τοῦτον τὸν τρόπον ἐξέκοψε καὶ τοὺς πολέμους ἔλυσε· τὴν δὲ ὅλην νῆσον ἐξηγριωμένην ὑπὸ κακῶν καὶ διαμεμισημένην ὑπὸ τῶν οἰκητόρων παραλαβών οὕτως ἐξημέρωσε καὶ ποθεινὴν ἐποίησε πᾶσιν ὥστε πλεῖν οἰκήσοντας ἑτέρους ὅθεν οἱ πολῖται πρότερον ἀπεδίδρασκον. καὶ γὰρ Ἀκράγαντα καὶ Γέλαν, πόλεις μεγάλας μετὰ τὸν Ἀττικὸν πόλεμον ὑπὸ Καρχηδονίων ἀναστάτους γεγενημένας, τότε κατῴκισαν, τὴν μὲν οἱ περὶ Μέγελλον καὶ Φέριστον ἐξ Ἐλέας, τὴν δὲ οἱ περὶ Γόργον ἐκ Κέω πλεύσαντες καὶ συναγαγόντες τοὺς ἀρχαίους πολίτας· οἷς οὐ μόνον ἀσφάλειαν ἐκ πολέμου τοσούτου καὶ γαλήνην ἱδρυομένοις παρασχών, ἀλλὰ καὶ τἆλλα παρασκευάσας καὶ συμπροθυμηθείς ὥσπερ οἰκιστὴς ἠγαπᾶτο. καὶ τῶν ἄλλων δὲ διακειμένων ὁμοίως ἁπάντων πρὸς αὐτόν, οὐ πολέμου τις λύσις, οὐ νόμων θέσις, οὐ χώρας κατοικισμός, οὐ πολιτείας διάταξις ἐδόκει καλῶς ἔχειν, ἧς ἐκεῖνος μὴ προσάψαιτο μηδὲ κατακοσμήσειεν, ὥσπερ ἔργῳ συντελουμένῳ δημιουργὸς ἐπιθείς τινα χάριν θεοφιλῆ καὶ πρέπουσαν.", "st": "Tim. 35.1"}, {"sp": "N", "t": "πολλῶν γοῦν κατ’ αὐτὸν Ἑλλήνων μεγάλων γενομένων καὶ μεγάλα κατεργασαμένων, ὧν καὶ Τιμόθεος ἦν καὶ Ἀγησίλαος καὶ Πελοπίδας καὶ ὁ μάλιστα ζηλωθεὶς ὑπὸ Τιμολέοντος Ἐπαμεινώνδας, αἱ μὲν ἐκείνων πράξεις βίᾳ τινὶ καὶ πόνῳ τὸ λαμπρὸν ἐξενηνόχασι μεμιγμένον, ὥστε καὶ μέμψιν ἐνίαις ἐπιγίνεσθαι καὶ μετάνοιαν, τῶν δὲ Τιμολέοντος ἔργων, ἔξω λόγου θεμένοις τὴν περὶ τὸν ἀδελφὸν ἀνάγκην, οὐδέν ἐστιν ᾧ μὴ τὰ τοῦ Σοφοκλέους, ὥς φησι Τίμαιος, ἐπιφωνεῖν ἔπρεπεν", "st": "Tim. 36.1"}, {"sp": "N", "t": "ὦ θεοί, τίς ἆρα Κύπρις ἢ τίς Ἵμερος<br>τοῦδε ξυνήψατο;", "st": "Tim. 36.1b"}, {"sp": "N", "t": "καθάπερ γὰρ ἡ μὲν Ἀντιμάχου ποίησις καὶ τὰ Διονυσίου ζῳγραφήματα, τῶν Κολοφωνίων, ἰσχὺν ἔχοντα καὶ τόνον ἐκβεβιασμένοις καὶ καταπόνοις ἔοικε, ταῖς δὲ Νικομάχου γραφαῖς καὶ τοῖς Ὁμήρου στίχοις μετὰ τῆς ἄλλης δυνάμεως καὶ χάριτος πρόσεστι τὸ δοκεῖν εὐχερῶς καὶ ῥᾳδίως ἀπειργάσθαι, οὕτως παρὰ τὴν Ἐπαμεινώνδου στρατηγίαν καὶ τὴν Ἀγησιλάου, πολυπόνους γενομένας καὶ δυσάγωνας, ἡ Τιμολέοντος ἀντεξεταζομένη, καὶ μετὰ τοῦ καλοῦ πολὺ τὸ ῥᾴδιον ἔχουσα, φαίνεται τοῖς εὖ καὶ δικαίως λογιζομένοις οὐ τύχης ἔργον, ἀλλ’ ἀρετῆς εὐτυχούσης. καίτοι πάντα γ’ ἐκεῖνος εἰς τὴν τύχην ἀνῆπτε τὰ καταρθούμενα· καὶ γὰρ γράφων τοῖς οἴκοι φίλοις καὶ δημηγορῶν πρὸς τοὺς Συρακουσίους πολλάκις ἔφη τῷ θεῷ χάριν ἔχειν ὅτι βουλόμενος σῶσαι Σικελίαν ἐπεγράψατο τὴν αὐτοῦ προσηγορίαν. ἐπὶ δὲ τῆς οἰκίας ἱερὸν ἱδρυσάμενος Αὐτοματίας ἔθυεν, αὐτὴν δὲ τὴν οἰκίαν Ἱερῷ δαίμονι καθιέρωσεν. ᾤκει δὲ οἰκίαν ἣν ἐξεῖλον αὐτῷ στρατηγίας ἀριστεῖον οἱ Συρακούσιοι, καὶ τῶν ἀγρῶν τὸν ἥδιστον καὶ κάλλιστον ἐν ᾧ καὶ τὸ πλεῖστον τοῦ χρόνου κατεσχόλαζε, μεταπεμψάμενος οἴκοθεν τὴν γυναῖκα καὶ τοὺς παῖδας. οὐ γὰρ ἐπανῆλθεν εἰς Κόρινθον, οὐδὲ κατέμιξε τοῖς Ἑλληνικοῖς θορύβοις ἑαυτὸν οὐδὲ τῷ πολιτικῷ φθόνῳ παρέδωκεν, εἰς ὃν οἱ πλεῖστοι τῶν στρατηγῶν ἀπληστίᾳ τιμῶν καὶ δυνάμεως ἐξοκέλλουσιν, ἀλλ’ ἐκεῖ κατέμεινε τοῖς ὑφ’ ἑαυτοῦ μεμηχανημένοις ἀγαθοῖς χρώμενος· ὧν μέγιστον ἦν τὸ πόλεις τοσαύτας καὶ μυριάδας ἀνθρώπων δι’ ἑαυτὸν ἐφορᾶν εὐδαιμονούσας.", "st": "Tim. 36.3"}, {"sp": "N", "t": "ἐπεὶ δὲ χρῆν, ὡς ἔοικεν, οὐ μόνον πᾶσι κορυδαλλοῖς λόφον ἐγγίγνεσθαι, κατὰ Σιμωνίδην, ἀλλὰ καὶ πάσῃ δημοκρατίᾳ συκοφάντην, ἐπεχείρησαν καὶ Τιμολέοντι δύο τῶν δημαγωγῶν, Λαφύστιος καὶ Δημαίνετος. ὧν Λαφυστίου μὲν αὑτὸν πρός τινα δίκην κατεγγυῶντος οὐκ εἴα θορυβεῖν οὐδὲ κωλύειν τοὺς πολίτας· ἑκὼν γὰρ αὐτὸς ὑπομεῖναι τοσούτους πόνους καὶ κινδύνους ὑπὲρ τοῦ τοῖς νόμοις χρῆσθαι τὸν βουλόμενον Συρακουσίων· τοῦ δὲ Δημαινέτου πολλὰ κατηγορήσαντος ἐν ἐκκλησίᾳ τῆς στρατηγίας, πρός ἐκεῖνον μὲν οὐδὲν ἀντεῖπε, τοῖς δὲ θεοῖς ἔφη χάριν ὀφείλειν, οἷς εὔξατο Συρακουσίους ἐπιδεῖν τῆς παρρησίας κυρίους γενομένους.", "st": "Tim. 37.1"}, {"sp": "N", "t": "μέγιστα δ’ οὖν καὶ κάλλιστα τῶν καθ’ αὑτὸν Ἑλλήνων ὁμολογουμένως διαπραξάμενος ἔργα, καὶ μόνος, ἐφ’ ἃς οἱ σοφισταὶ διὰ τῶν λόγων τῶν πανηγυρικῶν ἀεὶ παρεκάλουν πράξεις τοὺς Ἕλληνας, ἐν ταύταις ἀριστεύσας, καὶ τῶν μὲν αὐτόθι κακῶν, ἃ τὴν ἀρχαίαν Ἑλλάδα κατέσχεν, ὑπὸ τῆς τύχης προεκκομισθεὶς ἀναίμακτος καὶ καθαρός, ἐπιδειξάμενος δὲ δεινότητα μὲν καὶ ἀνδρείαν τοῖς βαρβάροις καὶ τοῖς τυράννοις, δικαιοσύνην δὲ καὶ πρᾳότητα τοῖς Ἕλλησι καὶ τοῖς φίλοις, τὰ δὲ πλεῖστα τρόπαια τῶν ἀγώνων ἀδάκρυτα καὶ ἀπενθῆ τοῖς πολίταις καταστήσας, καθαρὰν δὲ τὴν Σικελίαν ἐν οὐδ’ ὅλοις ἔτεσιν ὀκτὼ ἀϊδίων καὶ συνοίκων κακῶν καὶ νοσημάτων παραδοὺς τοῖς κατοικοῦσιν, ἤδη πρεσβύτερος ὢν ἀπημβλύνθη τὴν ὄψιν, εἶτα τελέως ἐπηρώθη μετ’ ὀλίγον, οὔτε αὐτὸς ἑαυτῷ πρόφασιν παρασχών οὔτε παροινηθεὶς ὑπὸ τῆς τύχης, ἀλλὰ συγγενικῆς τινος, ὡς ἔοικεν, αἰτίας καὶ καταβολῆς ἅμα τῷ χρόνῳ συνεπιθεμένης· λέγονται γὰρ οὐκ ὀλίγοι τῶν κατὰ γένος αὐτῷ προσηκόντων ὁμοίως ἀποβαλεῖν τὴν ὄψιν ὑπὸ γήρως ἀπομαρανθεῖσαν. ὁ δὲ Ἄθανις ἔτι συνεστῶτος τοῦ πρός Ἵππωνα πολέμου καὶ Μάμερκον, ἐν Μυλαῖς ἐπὶ στρατοπέδου φησὶν ἀπογλαυκωθῆναι τὴν ὄψιν αὐτοῦ, καὶ πᾶσι φανερὰν γενέσθαι τὴν πήρωσιν, οὐ μὴν ἀποστῆναι διὰ τοῦτο τῆς πολιορκίας, ἀλλ’ ἐμμείναντα τῷ πολέμῳ λαβεῖν τοὺς τυράννους· ὡς δὲ ἐπανῆλθεν εἰς Συρακούσας, εὐθὺς ἀποθέσθαι τὴν μοναρχίαν καὶ παραιτεῖσθαι τοὺς πολίτας, τῶν πραγμάτων εἰς τὸ κάλλιστον ἡκόντων τέλος.", "st": "Tim. 37.4"}, {"sp": "N", "t": "ἐκεῖνον μὲν οὖν αὐτὸν ὑπομείναντα τὴν συμφορὰν ἀλύπως ἧττον ἄν τις θαυμάσειε· τῶν δὲ Συρακουσίων ἄξιον ἄγασθαι τὴν πρὸς τὸν ἄνδρα τιμὴν καὶ χάριν ἣν ἐπεδείξαντο πεπηρωμένῳ, φοιτῶντες ἐπὶ θύρας αὐτοὶ καὶ τῶν ξένων τοὺς παρεπιδημοῦντας ἄγοντες εἰς τὴν οἰκίαν καὶ τὸ χωρίον, ὅπως θεάσαιντο τὸν εὐεργέτην αὑτῶν, ἀγαλλόμενοι καὶ μέγα φρονοῦντες ὅτι παρ’ αὐτοῖς εἵλετο καταζῆσαι τὸν βίον, οὕτω λαμπρᾶς ἐπανόδου τῆς εἰς τὴν Ἑλλάδα παρεσκευασμένης αὐτῷ διὰ τῶν εὐτυχημάτων καταφρονήσας. πολλῶν δὲ καὶ μεγάλων εἰς τὴν ἐκείνου τιμὴν γραφομένων καὶ πραττομένων οὐδενὸς ἧττον ἦν τὸ ψηφίσασθαι τὸν τῶν Συρακουσίων δῆμον, ὁσάκις συμπέσοι πόλεμος αὐτοῖς πρὸς ἀλλοφύλους, Κορινθίῳ χρῆσθαι στρατηγῷ. καλὴν δὲ καὶ τὸ περὶ τὰς ἐκκλησίας γινόμενον ὄψιν εἰς τιμὴν αὐτοῦ παρεῖχε· τὰ γὰρ ἄλλα δι’ αὑτῶν κρίνοντες ἐπὶ τὰς μείζονας διασκέψεις ἐκεῖνον ἐκάλουν. ὁ δὲ κομιζόμενος δι’ ἀγορᾶς ἐπὶ ζεύγους πρὸς τὸ θέατρον ἐπορεύετο καὶ τῆς ἀπήνης, ὥσπερ ἐτύγχανε καθήμενος, εἰσαγομένης, ὁ μὲν δῆμος ἠσπάζετο μιᾷ φωνῇ προσαγορεύων αὐτόν, ὁ δ’ ἀντασπασάμενος καὶ χρόνον τινὰ δοὺς ταῖς εὐφημίαις καὶ τοῖς ἐπαίνοις, εἶτα διακούσας τὸ ζητούμενον, ἀπεφαίνετο γνώμην. ἐπιχειροτονηθείσης δὲ ταύτης οἱ μὲν ὑπηρέται πάλιν ἀπῆγον διὰ τοῦ θεάτρου τὸ ζεῦγος, οἱ δὲ πολῖται βοῇ καὶ κρότῳ προπέμψαντες ἐκεῖνον ἤδη τὰ λοιπὰ τῶν δημοσίων καθ’ αὑτοὺς ἐχρημάτιζον.", "st": "Tim. 38.1"}, {"sp": "N", "t": "ἐν τοιαύτῃ δὲ γηροτροφούμενος τιμῇ μετ’ εὐνοίας, ὥσπερ πατὴρ κοινός, ἐκ μικρᾶς προφάσεως τῷ χρόνῳ συνεφαψαμένης ἐτελεύτησεν. ἡμερῶν δὲ δοθεισῶν τοῖς μὲν Συρακουσίοις εἰς τὸ παρασκευάσαι τὰ περὶ τὴν ταφήν, τοῖς δὲ περιοίκοις καὶ ξένοις εἰς τὸ συνελθεῖν, τά τ’ ἄλλα λαμπρᾶς χορηγίας ἔτυχε, καὶ τὸ λέχος οἱ ψήφῳ τῶν νεανίσκων προκριθέντες ἔφερον κεκοσμημένον διὰ τῶν Διονυσίου τυραννείων τότε κατεσκαμμένων. προὔπεμπον δὲ πολλαὶ μυριάδες ἀνδρῶν καὶ γυναικῶν, ὧν ὄψις μὲν ἦν ἑορτῇ πρέπουσα, πάντων ἐστεφανωμένων καὶ καθαρὰς ἐσθῆτας φορούντων, φωναὶ δὲ καὶ δάκρυα συγκεκραμένα τῷ μακαρισμῷ τοῦ τεθνηκότος οὐ τιμῆς ἀφοσίωσιν οὐδὲ λειτουργίαν ἐκ προβουλεύματος, ἀλλὰ πόθον δίκαιον ἐπεδείκνυντο καὶ χάριν ἀληθινῆς εὐνοίας. τέλος δὲ τῆς κλίνης ἐπὶ τὴν πυρὰν τεθείσης Δημήτριος, ὃς ἦν μεγαλοφωνότατος τῶν τότε κηρύκων, γεγραμμένον ἀνεῖπε κήρυγμα τοιοῦτον·", "st": "Tim. 39.1"}, {"sp": "N", "t": "ὁ δῆμος ὁ Συρακουσίων Τιμολέοντα Τιμοδήμου Κορίνθιον τόνδε θάπτει μὲν διακοσίων μνῶν, ἐτίμησε δ’ εἰς τὸν ἅπαντα χρόνον ἀγῶσι μουσικοῖς, ἱππικοῖς, γυμνικοῖς, ὅτι τοὺς τυράννους καταλύσας καὶ τοὺς βαρβάρους καταπολεμήσας καὶ τὰς μεγίστας τῶν ἀναστάτων πόλεων οἰκίσας ἀπέδωκε τοὺς νόμους τοῖς Σικελιώταις.", "st": "Tim. 39.5"}, {"sp": "N", "t": "ἐποιήσαντο δὲ τὴν ταφὴν τοῦ σώματος ἐν ἀγορᾷ, καὶ στοὰς ὕστερον περιβαλόντες καὶ παλαίστρας ἐνοικοδομήσαντες γυμνάσιον τοῖς νέοις ἀνῆκαν καὶ Τιμολεόντειον προσηγόρευσαν. αὐτοὶ δὲ χρώμενοι πολιτείᾳ καὶ νόμοις οὓς ἐκεῖνος κατέστησεν, ἐπὶ πολὺν χρόνον εὐδαιμονοῦντες διετέλεσαν.", "st": "Tim. 39.6"}, {"sp": "HDR", "t": "Αἰμίλιος Παῦλος"}, {"sp": "N", "t": "ἐμοὶ τῆς τῶν βίων ἅψασθαι μὲν γραφῆς συνέβη δι’ ἑτέρους, ἐπιμένειν δὲ καὶ φιλοχωρεῖν ἤδη καὶ δι’ ἐμαυτόν, ὥσπερ ἐν ἐσόπτρῳ τῇ ἱστορίᾳ πειρώμενον ἁμῶς γέ πως κοσμεῖν καὶ ἀφομοιοῦν πρὸς τὰς ἐκείνων ἀρετὰς τὸν βίον. οὐδὲν γὰρ ἀλλ’ ἢ συνδιαιτήσει καὶ συμβιώσει τὸ γινόμενον ἔοικεν, ὅταν ὥσπερ ἐπιξενούμενον ἕκαστον αὐτῶν ἐν μέρει διὰ τῆς ἱστορίας ὑποδεχόμενοι καὶ παραλαμβάνοντες ἀναθεωρῶμεν ὅσσος ἔην οἷός τε, τὰ κυριώτατα καὶ κάλλιστα πρὸς γνῶσιν ἀπὸ τῶν πράξεων λαμβάνοντες.", "st": "Aem. 1.1"}, {"sp": "N", "t": "φεῦ, φεῦ· τί τούτου χάρμα μεῖζον ἂν λάβοις,", "st": "Aem. 1.3"}, {"sp": "N", "t": "καὶ πρὸς ἐπανόρθωσιν ἠθῶν ἐνεργότερον; Δημόκριτος μὲν γὰρ εὔχεσθαί φησι δεῖν ὅπως εὐλόγχων εἰδώλων τυγχάνωμεν καὶ τὰ σύμφυλα καὶ τὰ χρηστὰ μᾶλλον ἡμῖν ἐκ τοῦ περιέχοντος ἢ τὰ φαῦλα καὶ τὰ σκαιὰ συμφέρηται, λόγον οὔτ’ ἀληθῆ καὶ πρὸς ἀπεράντους ἐκφέροντα δεισιδαιμονίας εἰς φιλοσοφίαν καταβάλλων· ἡμεῖς δὲ τῇ περὶ τὴν ἱστορίαν διατριβῇ καὶ τῆς γραφῆς τῇ συνηθείᾳ παρασκευάζομεν ἑαυτούς, τὰς τῶν ἀρίστων καὶ δοκιμωτάτων μνήμας ὑποδεχομένους ἀεὶ ταῖς ψυχαῖς, εἴ τι φαῦλον ἢ κακόηθες ἢ ἀγεννὲς αἱ τῶν συνόντων ἐξ ἀνάγκης ὁμιλίαι προσβάλλουσιν, ἐκκρούειν καὶ διωθεῖσθαι, πρὸς τὰ κάλλιστα τῶν παραδειγμάτων ἵλεω καὶ πρᾳεῖαν ἀποστρέφοντες τὴν διάνοιαν. ὧν ἐν τῷ παρόντι προκεχειρίσμεθά σοι τὸν Τιμολέοντος τοῦ Κορινθίου καὶ τὸν Αἰμιλίου Παύλου βίον, ἀνδρῶν οὐ μόνον ταῖς αἱρέσεσιν, ἀλλὰ καὶ ταῖς τύχαις ἀγαθαῖς ὁμοίως κεχρημένων ἐπὶ τὰ πράγματα, καὶ διαμφισβήτησιν παρεξόντων πότερον εὐποτμίᾳ, μᾶλλον ἢ φρονήσει τὰ μέγιστα τῶν πεπραγμένων κατώρθωσαν.", "st": "Aem. 1.4"}, {"sp": "N", "t": "τὸν Αἰμιλίων οἶκον ἐν Ῥώμῃ τῶν εὐπατριδῶν γεγονέναι καὶ παλαιῶν οἱ πλεῖστοι συγγραφεῖς ὁμολογοῦσιν. ὅτι δ’ ὁ πρῶτος αὐτῶν καὶ τῷ γένει τήν ἐπωνυμίαν ἀπολιπὼν Μάμερκος ἦν, Πυθαγόρου παῖς τοῦ σοφοῦ, δι’ αἱμυλίαν λόγου καὶ χάριν Αἰμίλιος προσαγορευθείς, εἰρήκασιν ἔνιοι τῶν Πυθαγόρᾳ τήν Νομᾶ τοῦ βασιλέως παίδευσιν ἀναθέντων. οἱ μὲν οὖν πλεῖστοι τῶν εἰς δόξαν ἀπὸ τῆς οἰκίας ταύτης προελθόντων δι’ ἀρετὴν, ἣν ἐζήλωσαν, εὐτύχησαν, Λευκίου δὲ Παύλου τὸ περὶ Κάννας ἀτύχημα τήν τε φρόνησιν ἅμα καὶ τήν ἀνδρείαν ἔδειξεν. ὡς γὰρ οὐκ ἔπεισε τὸν συνάρχοντα κωλύων μάχεσθαι, τοῦ μὲν ἀγῶνος ἄκων μετέσχεν αὐτῷ, τῆς δὲ φυγῆς οὐκ ἐκοινώνησεν, ἀλλὰ τοῦ συνάψαντος τὸν κίνδυνον ἐγκαταλιπόντος αὐτὸς ἑστὼς καὶ μαχόμενος τοῖς πολεμίοις ἐτελεύτησε.", "st": "Aem. 2.1"}, {"sp": "N", "t": "τούτου θυγάτηρ μὲν Αἰμιλία Σκηπίωνι τῷ μεγάλῳ συνῴκησεν, υἱὸς δὲ Παῦλος Αἰμίλιος, περὶ οὗ τάδε γράφεται, γεγονὼς ἐν ἡλικίᾳ κατὰ καιρὸν ἀνθοῦντα δόξαις καὶ ἀρεταῖς ἐπιφανεστάτων ἀνδρῶν καὶ μεγίστων, διέλαμψεν, οὐ ταὐτὰ τοῖς εὐδοκιμοῦσι τότε νέοις ἐπιτηδεύματα ζηλώσας, οὐδὲ τήν αὐτὴν ὁδὸν ἀπ’ ἀρχῆς πορευθείς. οὔτε γὰρ λόγον ἤσκει περὶ δίκας, ἀσπασμούς τε καὶ δεξιώσεις καὶ φιλοφροσύνας, αἷς ὑποτρέχοντες οἱ πολλοὶ τὸν δῆμον ἐκτῶντο θεραπευτικοὶ καὶ σπουδαῖοι γενόμενοι, παντάπασιν ἐξέλιπε, πρὸς οὐδέτερον ἀφυῶς ἔχων, ὡς δ’ ἑκατέρου κρείττονα τήν ἀπ’ ἀνδρείας καὶ δικαιοσύνης καὶ πίστεως δόξαν αὑτῷ περιποιούμενος, οἷς εὐθὺς διέφερε τῶν καθ’ ἡλικίαν.", "st": "Aem. 2.5"}, {"sp": "N", "t": "πρώτην γοῦν τῶν ἐπιφανῶν ἀρχῶν ἀγορανομίαν μετελθών προεκρίθη δεκαδυοῖν ἀνδρῶν συναπογραψαμένων, οὓς ὕστερον ἅπαντας ὑπατεῦσαι λέγουσι. γενόμενος δ’ ἱερεὺς τῶν αὐγούρων προσαγορευομένων, οὓς τῆς ἀπ’ ὀρνίθων καὶ διοσημειῶν ἀποδεικνύουσι Ῥωμαῖοι μαντικῆς ἐπισκόπους καὶ φύλακας, οὕτω προσέσχε τοῖς πατρῴοις ἔθεσι καὶ κατενόησε τὴν τῶν παλαιῶν περὶ τὸ θεῖον εὐλάβειαν ὥστε τιμήν τινα δοκοῦσαν εἶναι καὶ ζηλουμένην ἄλλως ἕνεκα δόξης τὴν ἱερωσύνην τῶν ἀκροτάτων μίαν ἀποφῆναι τεχνῶν, καὶ μαρτυρῆσαι τοῖς φιλοσόφοις, ὅσοι τὴν εὐσέβειαν ὡρίσαντο θεραπείας θεῶν ἐπιστήμην εἶναι. πάντα γὰρ ἐδρᾶτο μετ’ ἐμπειρίας ὑπ’ αὐτοῦ καὶ σπουδῆς, σχολὴν τῶν ἄλλων ἄγοντος ὅτε γίγνοιτο πρὸς τούτῳ, καὶ παραλείποντος οὐδὲν οὐδὲ καινοτομοῦντος, ἀλλὰ καὶ τοῖς συνιερεῦσιν ἀεὶ καὶ περὶ τῶν μικρῶν διαφερομένου, καὶ διδάσκοντος ὡς εἰ τὸ θεῖον εὔκολόν τις ἡγεῖται καὶ ἀμεμφὲς εἶναι τῶν ἀμελειῶν, ἀλλὰ τῇ γε πόλει χαλεπὸν ἡ περὶ ταῦτα συγγνώμη καὶ παρόρασις· οὐδεὶς γὰρ ἐξ ἀρχῆς εὐθὺς μεγάλῳ παρανομήματι κινεῖ πολιτείαν, ἀλλὰ καὶ τὴν τῶν μειζόνων φρουρὰν καταλύουσιν οἱ προϊέμενοι τὴν ἐν τοῖς μικροῖς ἀκρίβειαν.", "st": "Aem. 3.1"}, {"sp": "N", "t": "ὅμοιον δὲ καὶ τῶν στρατιωτικῶν ἐθῶν τε καὶ πατρίων ἐξεταστὴν καὶ φύλακα παρεῖχεν ἑαυτόν, οὐ δημαγωγῶν ἐν τῷ στρατηγεῖν, οὐδ’, ὥσπερ οἱ πλεῖστοι τότε, δευτέρας ἀρχὰς ταῖς πρώταις μνώμενος διὰ τοῦ χαρίζεσθαι καὶ πρᾷος εἶναι τοῖς ἀρχομένοις, ἀλλ’ ὥσπερ ἱερεὺς ἄλλων ὀργίων δεινῶν, τῶν περὶ τὰς στρατείας ἐθῶν ἐξηγούμενος ἕκαστα, καὶ φοβερὸς ὢν τοῖς ἀπειθοῦσι καὶ παραβαίνουσιν, ὤρθου τὴν πατρίδα, μικροῦ δεῖν πάρεργον ἡγούμενος τὸ νικᾶν τοὺς πολεμίους τοῦ παιδεύειν τοὺς πολίτας.", "st": "Aem. 3.6"}, {"sp": "N", "t": "συστάντος δὲ τοῦ πρὸς Ἀντίοχον τὸν μέγαν πολέμου τοῖς Ῥωμαίοις, καὶ τῶν ἡγεμονικωτάτων ἀνδρῶν τετραμμένων πρὸς ἐκεῖνον, ἄλλος ἀπὸ τῆς ἑσπέρας ἀνέστη πόλεμος, ἐν Ἰβηρίᾳ, κινημάτων μεγάλων γενομένων. ἐπὶ τοῦτον ὁ Αἰμίλιος ἐξεπέμφθη στρατηγός, οὐχ ἓξ ἔχων πελέκεις, ὅσους ἔχουσιν οἱ στρατηγοῦντες, ἀλλὰ προσλαβὼν ἑτέρους τοσούτους, ὥστε τῆς ἀρχῆς ὑπατικὸν γενέσθαι τὸ ἀξίωμα, μάχῃ μὲν οὖν δὶς ἐκ παρατάξεως ἐνίκησε τοὺς βαρβάρους, περὶ τρισμυρίους ἀνελών, καὶ δοκεῖ τὸ κατόρθωμα τῆς στρατηγίας περιφανῶς γενέσθαι, χωρίων εὐφυΐᾳ καὶ ποταμοῦ τινος διαβάσει ῥᾳστώνην παρασχόντος αὐτοῦ πρὸς τὸ νίκημα τοῖς στρατιώταις· πόλεις δὲ πεντήκοντα καὶ διακοσίας ἐχειρώσατο δεξαμένας αὐτὸν ἑκουσίως, εἰρήνῃ δὲ καὶ πίστει συνηρμοσμένην ἀπολιπὼν τὴν ἐπαρχίαν εἰς Ῥώμην ἐπανῆλθεν, οὐδὲ δραχμῇ μιᾷ γεγονὼς εὐπορώτερος ἀπὸ τῆς στρατείας. ἦν δὲ καὶ περὶ τἆλλα χρηματιστὴς ἀργότερος, εὐδάπανος δὲ καὶ ἀφειδὴς ἐκ τῶν ὑπαρχόντων, οὐ πολλὰ δ’ ἦν, ἀλλὰ καὶ φερνῆς ὀφειλομένης τῇ γυναικὶ μετὰ τὸν θάνατον αὐτοῦ γλίσχρως ἐξήρκεσεν.", "st": "Aem. 4.1"}, {"sp": "N", "t": "ἔγημε δὲ Παπιρίαν, ἀνδρὸς ὑπατικοῦ Μάσωνος θυγατέρα, καὶ χρόνον συνοικήσας πολὺν ἀφῆκε τὸν γάμον, καίπερ ἐξ αὐτῆς καλλιτεκνότατος γενόμενος· αὕτη γὰρ ἦν ἡ τὸν κλεινότατον αὐτῷ Σκηπίωνα τεκοῦσα καὶ Μάξιμον Φάβιον. αἰτία δὲ γεγραμμένη τῆς διαστάσεως οὐκ ἦλθεν εἰς ἡμᾶς, ἀλλ’ ἔοικεν ἀληθής τις εἶναι λόγος περὶ γάμου λύσεως γενόμενος, ὡς ἀνὴρ Ῥωμαῖος ἀπεπέμπετο γυναῖκα, τῶν δὲ φίλων νουθετούντων αὐτόν, οὐχὶ σώφρων; οὐκ εὔμορφος; οὐχὶ παιδοποιός; προτείνας τὸ ὑπόδημα (κάλτιον αὐτὸ Ῥωμαῖοι καλοῦσιν) εἶπεν· οὐκ εὐπρεπὴς οὗτος; οὐ νεουργής; ἀλλ’ οὐκ ἂν εἰδείη τις ὑμῶν καθ’ ὅ τι θλίβεται μέρος οὑμὸς πούς. τῷ γὰρ ὄντι μεγάλαι μὲν ἁμαρτίαι καὶ ἀναπεπταμέναι γυναῖκας ἀνδρῶν ἄλλας ἀπήλλαξαν, τὰ δ’ ἔκ τινος ἀηδίας καὶ δυσαρμοστίας ἠθῶν μικρὰ καὶ πυκνὰ προσκρούσματα, λανθάνοντα τοὺς ἄλλους, ἀπεργάζεται τὰς ἀνηκέστους ἐν ταῖς συμβιώσεσιν ἀλλοτριότητας.", "st": "Aem. 5.1"}, {"sp": "N", "t": "ὁ δὲ οὖν Αἰμίλιος ἀπαλλαγεὶς τῆς Παπιρίας ἑτέραν ἠγάγετο· καὶ δύο παῖδας ἄρρενας τεκούσης τούτους μὲν ἐπὶ τῆς οἰκίας εἶχε, τοὺς δὲ προτέρους εἰσεποίησεν οἴκοις τοῖς μεγίστοις καὶ γένεσι τοῖς ἐπιφανεστάτοις, τὸν μὲν πρεσβύτερον τῷ Μαξίμου Φαβίου τοῦ πεντάκις ὑπατεύσαντος, τὸν δὲ νεώτερον Ἀφρικανοῦ Σκηπίωνος υἱὸς ἀνεψιὸν ὄντα θέμενος Σκηπίωνα προσηγόρευσε. τῶν δὲ θυγατέρων τῶν Αἰμιλίου τὴν μὲν ὁ Κάτωνος υἱὸς ἔγημε, τὴν δὲ Αἴλιος Τουβέρων, ἀνὴρ ἄριστος καὶ μεγαλοπρεπέστατα Ῥωμαίων πενίᾳ χρησάμενος. ἦσαν γὰρ ἑκκαίδεκα συγγενεῖς, Αἴλιοι πάντες· οἰκίδιον δὲ πάνυ μικρὸν ἦν αὐτοῖς, καὶ χωρίδιον ἓν ἤρκει πᾶσι, μίαν ἑστίαν νέμουσι μετὰ παίδων πολλῶν καὶ γυναικῶν, ἐν αἷς καὶ ἡ Αἰμιλίου τοῦδε θυγάτηρ ἦν δὶς ὑπατεύσαντος καὶ δὶς θριαμβεύσαντος, οὐκ αἰσχυνομένη τὴν πενίαν τοῦ ἀνδρός, ἀλλὰ θαυμάζουσα τὴν ἀρετὴν δι’ ἣν πένης ἦν. οἱ δὲ νῦν ἀδελφοὶ καὶ συγγενεῖς, ἂν μὴ κλίμασι καὶ ποταμοῖς καὶ διατειχίσμασιν ὁρίσωσι τὰ κοινά καὶ πολλὴν εὐρυχωρίαν ἒν μέσῳ λάβωσιν ἀπ’ ἀλλήλων, οὐ παύονται διαφερόμενοι. ταῦτα μὲν οὖν ἡ ἱστορία λογίζεσθαι καὶ παρεπισκοπεῖν δίδωσι τοῖς σῴζεσθαι βουλομένοις.", "st": "Aem. 5.5"}, {"sp": "N", "t": "ὁ δὲ Αἰμίλιος ὕπατος ἀποδειχθεὶς ἐστράτευσεν ἐπὶ τοὺς παραλπίους Λίγυας, οὓς ἔνιοι καί Λιγυστίνους ὀνομάζουσι, μάχιμον καί θυμοειδὲς ἔθνος, ἐμπείρως δὲ πολεμεῖν διδασκόμενον ὑπὸ Ῥωμαίων διὰ τὴν γειτνίασιν. τὰ γὰρ ἔσχατα τῆς Ἰταλίας καί καταλήγοντα πρὸς τάς Ἄλπεις αὐτῶν τε τῶν Ἄλπεων τὰ κλυζόμενα τῷ Τυρρηνικῷ πελάγει καί πρὸς τὴν Λιβύην ἀνταίροντα νέμονται, μεμιγμένοι Γαλάταις καί τοῖς παραλίοις Ἰβήρων. τότε δὲ καί τῆς θαλάττης ἁψάμενοι σκάφεσι πειρατικοῖς ἀφῃροῦντο καί περιέκοπτον τάς ἐμπορίας, ἄχρι στηλῶν Ἡρακλείων ἀναπλέοντες. ἐπιόντος οὖν τοῦ Αἰμιλίου τετρακισμύριοι γενόμενοι τὸ πλῆθος ὑπέστησαν ὁ δὲ τοὺς σύμπαντας ὀκτακισχιλίους ἔχων πενταπλασίοις οὖσιν αὐτοῖς συνέβαλε, καί τρεψάμενος καί κατακλείσας εἰς τὰ τείχη διέδωκε λόγον φιλάνθρωπον καί συμβατικόν· οὐ γὰρ ἦν βουλομένοις τοῖς Ῥωμαίοις παντάπασιν ἐκκόψαι τὸ Λιγύων ἔθνος, ὥσπερ ἕρκος ἢ πρόβολον ἐμποδὼν κείμενον τοῖς Γαλατικοῖς κινήμασιν ἐπαιωρουμένοις ἀεὶ περὶ τὴν Ἰταλίαν. πιστεύσαντες οὖν τῷ Αἰμιλίῳ τάς τε ναῦς καί τάς πόλεις ἐνεχείρισαν. ὁ δὲ τάς μὲν πόλεις οὐδὲν ἀδικήσας ἢ μόνον τὰ τείχη περιελών ἀπέδωκε, τάς δὲ ναῦς ἁπάσας ἀφείλετο, καί πλοῖον οὐδὲν αὐτοῖς τρισκάλμου μεῖζον ἀπέλιπε· τοὺς δὲ ἡλωκότας ὑπ’ αὐτῶν κατὰ γῆν ἢ κατὰ θάλατταν ἀνεσώσατο πολλοὺς καί ξένους καὶ Ῥωμαίους εὑρεθέντας. ἐκείνη μὲν οὖν ἡ ὑπατεία τάς εἰρημένας πράξεις ἐπιφανεῖς ἔσχεν.", "st": "Aem. 6.1"}, {"sp": "N", "t": "ὕστερον δὲ πολλάκις ποιήσας φανερὸν αὑτὸν αὖθις ὑπατεῦσαι βουλόμενον καί ποτε καί παραγγείλας, ὡς ἀπέτυχε καί παρώφθη, τὸ λοιπὸν ἡσυχίαν εἶχε, τῶν ἱερῶν ἐπιμελούμενος καί τοὺς παῖδας ἀσκῶν τὴν μὲν ἐπιχώριον παιδείαν καί πάτριον ὥσπερ αὐτὸς ἤσκητο, τὴν δὲ Ἑλληνικὴν φιλοτιμότερον. οὐ γὰρ μόνον γραμματικοὶ καί σοφισταὶ καί ῥήτορες, ἀλλὰ καί πλάσται καί ζωγράφοι καί πώλων καί σκυλάκων ἐπιστάται καί διδάσκαλοι θήρας Ἕλληνες ἦσαν περὶ τοὺς νεανίσκους. ὁ δὲ πατήρ, εἰ μή τι δημόσιον ἐμποδὼν εἴη, παρῆν ἀεὶ μελετῶσι καί γυμναζομένοις, φιλοτεκνότατος Ῥωμαίων γενόμενος.", "st": "Aem. 6.8"}, {"sp": "N", "t": "τῶν δὲ δημοσίων πράξεων καιρὸς ἦν ἐκεῖνος τότε καθ’ ὃν Περσεῖ τῷ Μακεδόνων βασιλεῖ πολεμοῦντες ἐν αἰτίαις τοὺς στρατηγοὺς εἶχον, ὡς δι’ ἀπειρίαν καὶ ἀτολμίαν αἰσχρῶς καὶ καταγελάστως τοῖς πράγμασι χρωμένους καὶ πάσχοντας κακῶς μᾶλλον ἢ ποιοῦντας. ἄρτι μὲν γὰρ Ἀντίοχον τὸν ἐπικληθέντα μέγαν εἴξαντα τῆς ἄλλης Ἀσίας ὑπὲρ τὸν Ταῦρον ἐκβαλόντες καὶ κατακλείσαντες εἰς Συρίαν, ἐπὶ μυρίοις καὶ πεντακισχιλίοις ταλάντοις ἀγαπήσαντα τὰς διαλύσεις, ὀλίγῳ δὲ πρόσθεν ἐν Θεσσαλίᾳ συντρίψαντες Φίλιππον καὶ τοὺς Ἕλληνας ἀπὸ Μακεδόνων ἐλευθερώσαντες, ᾧ τε βασιλεὺς οὐδεὶς παραβλητὸς εἰς τόλμαν ἢ δύναμιν, Ἀννίβαν καταπολεμήσαντες, οὐκ ἀνεκτὸν ἡγοῦντο Περσεῖ καθάπερ ἀντιπάλῳ τῆς Ῥώμης ἴσον φερόμενοι συμπεπλέχθαι, πολὺν ἤδη χρόνον ἀπὸ τῶν λειψάνων τῆς πατρῴας ἥττης πολεμοῦντι πρὸς αὐτούς, ἀγνοοῦντες ὅτι πολλῷ τὴν Μακεδόνων δύναμιν ἡττηθεὶς Φίλιππος ἐρρωμενεστέραν καὶ μαχιμωτέραν ἐποίησε. περὶ ὧν δίειμι βραχέως ἄνωθεν ἀρξάμενος.", "st": "Aem. 7.1"}, {"sp": "N", "t": "Ἀντίγονος μέγιστον δυνηθεὶς τῶν Ἀλεξάνδρου διαδόχων καὶ στρατηγῶν, κτησάμενος ἑαυτῷ καὶ γένει τὴν τοῦ βασιλέως προσηγορίαν, υἱόν ἔσχε Δημήτριον, οὗ παῖς Ἀντίγονος ἦν ὁ Γονατᾶς ἐπονομασθείς· τούτου δὲ Δημήτριος, ὃς αὐτός τε βασιλεύσας χρόνον οὐ πολύν, υἱόν τε παῖδα τὴν ἡλικίαν ἀπολιπὼν Φίλιππον ἐτελεύτησε. δείσαντες δὲ τὴν ἀναρχίαν οἱ πρῶτοι Μακεδόνων Ἀντίγονον ἐπάγονται τοῦ τεθνηκότος ἀνεψιὸν ὄντα, καὶ συνοικίσαντες αὐτῷ τὴν μητέρα τοῦ Φιλίππου, πρῶτον μὲν ἐπίτροπον καὶ στρατηγόν, εἶτα πειρώμενοι μετρίου καὶ κοινωφελοῦς βασιλέα προσηγόρευσαν. ἐπεκλήθη δὲ Δώσων ὡς ἐπαγγελτικὸς, οὐ τελεσιουργὸς δὲ τῶν ὑποσχέσεων. μετὰ τοῦτον βασιλεύσας ὁ Φίλιππος ἤνθησεν ἐν τοῖς μάλιστα τῶν βασιλέων ἔτι μειράκιον ὢν, καὶ δόξαν ἔσχεν ὡς ἀναστήσων Μακεδονίαν εἰς τὸ παλαιὸν ἀξίωμα καὶ μόνος ἐπὶ πάντας ἤδη τὴν Ῥωμαίων δύναμιν αἰρομένην καθέξων. ἡττηθεὶς δὲ μεγάλῃ μάχῃ περὶ Σκότουσσαν ὑπὸ Τίτου Φλαμινίνου τότε μὲν ἔπτηξε καὶ πάντα τὰ καθ’ ἑαυτὸν ἐπέτρεψε Ῥωμαίοις, καὶ τυχὼν ἐπιτιμήσεως μετρίας ἠγάπησεν. ὕστερον δὲ βαρέως φέρων, καὶ τὸ βασιλεύειν χάριτι Ῥωμαίων ἡγούμενος αἰχμαλώτου τρυφὴν ἀγαπῶντος εἶναι μᾶλλον ἢ φρόνημα καὶ θυμὸν ἔχοντος ἀνδρός, ἐπεῖχε τῷ πολέμῳ τὴν γνώμην καὶ συνετάττετο λάθρα καὶ πανούργως. τῶν γὰρ πόλεων τὰς ἐνοδίους καὶ παραθαλαττίους ἀσθενεῖς γενομένας περιορῶν καὶ ὑπερήμους, ὡς καταφρονεῖσθαι, πολλὴν ἄνω συνῆγε δύναμιν, καὶ τὰ μεσόγεια χωρία καὶ φρούρια καὶ πόλεις ὅπλων καὶ χρημάτων πολλῶν καὶ σωμάτων ἀκμαζόντων ἐμπεπληκώς ἐσωμάσκει τὸν πόλεμον καὶ συνεῖχεν ὥσπερ ἐγκεκρυμμένον ἀδήλως. ὅπλων μὲν γὰρ ἀργούντων ἀπέκειντο τρεῖς μυριάδες, ὀκτακόσιαι δὲ σίτου μεδίμνων ἦσαν ἐγκατῳκοδομημένου τοῖς τείχεσι, χρημάτων δὲ πλῆθος ὅσον ἤρκει μισθοφόρους ἔτη δέκα μυρίους τρέφειν προπολεμοῦντας τῆς χώρας.", "st": "Aem. 8.1"}, {"sp": "N", "t": "ἀλλ’ ἐκεῖνος μὲν οὐκ ἔφθη ταῦτα κινῆσαι καὶ προαγαγεῖν εἰς ἔργον, ὑπὸ λύπης καὶ δυσθυμίας προέμενος τὸν βίον ἔγνω γὰρ ἀδίκως τὸν ἕτερον τῶν υἱῶν Δημήτριον ἐκ διαβολῆς τοῦ χείρονος ἀνῃρηκώς· ὁ δὲ ἀπολειπόμενος υἱὸς αὐτοῦ Περσεὺς ἅμα τῇ βασιλείᾳ διεδέξατο τὴν πρὸς Ῥωμαίους ἔχθραν, οὐκ ὢν ἐχέγγυος ἐνεγκεῖν διὰ μικρότητα καὶ μοχθηρίαν ἤθους, ἐν ᾧ παθῶν τε παντοδαπῶν καὶ νοσημάτων ἐνόντων ἐπρώτευεν ἡ φιλαργυρία, λέγεται δὲ μηδὲ γνήσιος φῦναι, λαβεῖν δὲ αὐτὸν ἡ συνοικοῦσα τῷ Φιλίππῳ νεογνὸν ἀκεστρίας τινὸς Ἀργολικῆς Γναθαινίου τοὔνομα τεκούσης, καὶ λαθεῖν ὑποβαλομένη. δι’ ὃ καὶ μάλιστα δοκεῖ τὸν Δημήτριον φοβηθεὶς ἀποκτεῖναι, μὴ γνήσιον ἔχων ὃ οἶκος διάδοχον ἀποκαλύψῃ τὴν ἐκείνου νοθείαν.", "st": "Aem. 8.9"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ, καίπερ ὢν ἀγεννὴς καὶ ταπεινός, ὑπὸ ῥώμης τῶν πραγμάτων ἀναφερόμενος πρὸς τὸν πόλεμον ἔστη καὶ διηρείσατο πολὺν χρόνον, ἡγεμόνας τε Ῥωμαίων ὑπατικοὺς καὶ στρατεύματα καὶ στόλους μεγάλους ἀποτριψάμενος, ἐνίων δὲ καὶ κρατήσας. Πόπλιόν τε γὰρ Λικίννιον ἐμβαλόντα πρῶτον εἰς Μακεδονίαν τρεψάμενος ἱππομαχίᾳ δισχιλίους πεντακοσίους ἄνδρας ἀγαθοὺς ἀπέκτεινε καὶ ζῶντας ἄλλους ἑξακοσίους ἔλαβε, τοῦ τε ναυστάθμου περὶ Ὠρεὸν ὁρμοῦντος ἀπροσδόκητον ἐπίπλουν θέμενος εἴκοσι μὲν αὐτοφόρτους ὁλκάδας ἐχειρώσατο, τὰς δ’ ἄλλας σίτου γεμούσας κατέδυσεν· ἐκράτησε δὲ καὶ πεντηρικά τέσσαρα. καὶ μάχην ἐπολέμησε τὸ δεύτερον, ἐν ᾗ τὸν ὑπατικὸν Ὁστίλιον ἀπεκρούσατο καταβιαζόμενον κατὰ τὰς Ἐλιμίας· λάθρα δὲ διὰ Θεσσαλίας ἐμβαλόντα προκαλούμενος εἰς μάχην ἐφόβησε. πάρεργον δὲ τοῦ πολέμου στρατείαν ἐπὶ Δαρδανεῖς θέμενος, ὡς δὴ τοὺς Ῥωμαίους ὑπερορῶν καὶ σχολάζων, μυρίους τῶν βαρβάρων κατέκοψε καὶ λείαν ἠλάσατο πολλήν. ὑπεκίνει δὲ καὶ Γαλάτας τοὺς περὶ τὸν Ἴστρον ᾠκημένους, οἳ Βαστέρναι καλοῦνται, στρατὸν ἱππότην καὶ μάχιμον, Ἰλλυριούς τε διὰ Γενθίου τοῦ βασιλέως παρεκάλει συνεφάψασθαι τοῦ πολέμου, καὶ λόγος κατέσχεν ὡς τῶν βαρβάρων μισθῷ πεπεισμένων ὑπ’ αὐτοῦ διὰ τῆς κάτω Γαλατίας παρὰ τὸν Ἀδρίαν ἐμβαλεῖν εἰς τὴν Ἰταλίαν.", "st": "Aem. 9.1"}, {"sp": "N", "t": "ταῦτα τοῖς Ῥωμαίοις πυνθανομένοις ἐδόκει τὰς τῶν στρατηγιώντων χάριτας καὶ παραγγελίας ἐάσαντας αὐτοὺς καλεῖν ἐπὶ τὴν ἡγεμονίαν ἄνδρα νοῦν ἔχοντα καὶ πράγμασι χρῆσθαι μεγάλοις ἐπιστάμενον. οὗτος ἦν Παῦλος Αἰμίλιος, ἡλικίας μὲν ἤδη πρόσω καὶ περὶ ἑξήκοντα γεγονὼς ἔτη, ῥώμῃ δὲ σώματος ἀκμάζων, πεφραγμένος δὲ κηδεσταῖς καὶ παισὶ νεανίαις καὶ φίλων πλήθει καὶ συγγενῶν μέγα δυναμένων, οἳ πάντες αὐτὸν ὑπακοῦσαι καλοῦντι τῷ δήμῳ πρὸς τὴν ὑπατείαν ἔπειθον. ὁ δὲ κατ’ ἀρχὰς μὲν ἐθρύπτετο πρὸς τοὺς πολλούς καὶ διέκλινε τὴν φιλοτιμίαν αὐτῶν καὶ σπουδήν, ὡς μὴ δεόμενος τοῦ ἄρχειν, φοιτώντων δὲ καθ’ ἡμέραν ἐπὶ θύρας καὶ προκαλουμένων αὐτὸν εἰς ἀγορὰν καὶ καταβοώντων ἐπείσθη· καὶ φανεὶς εὐθὺς ἐν τοῖς μετιοῦσι τὴν ὑπατείαν ἔδοξεν οὐκ ἀρχὴν ληψόμενος, ἀλλὰ νίκην καὶ κράτος πολέμου κομίζων καὶ διδοὺς τοῖς πολίταις καταβαίνειν εἰς τὸ πεδίον· μετὰ τοσαύτης ἐλπίδος καὶ προθυμίας ἐδέξαντο πάντες αὐτὸν καὶ κατέστησαν ὕπατον τὸ δεύτερον, οὐκ ἐάσαντες κλῆρον γενέσθαι, καθάπερ εἰώθει, περὶ τῶν ἐπαρχιῶν, ἀλλ’ εὐθὺς ἐκείνῳ ψηφισάμενοι τοῦ Μακεδονικοῦ πολέμου τὴν ἡγεμονίαν. λέγεται δ’ αὐτόν, ὡς ἀνηγορεύθη κατὰ τοῦ Περσέως στρατηγός, ὑπὸ τοῦ δήμου παντὸς οἴκαδε προπεμφθέντα λαμπρῶς εὑρεῖν τὸ θυγάτριον τὴν Τερτίαν δεδακρυμένην ἔτι παιδίον οὖσαν· ἀσπαζόμενον οὖν αὐτὴν ἐρωτᾶν ἐφ’ ὅτῳ λελύπηται· τὴν δὲ περιβαλοῦσαν καὶ καταφιλοῦσαν, οὐ γὰρ οἶσθα, εἰπεῖν, ὦ πάτερ, ὅτι ἡμῖν ὁ Περσεὺς τέθνηκε; λέγουσαν κυνίδιον σύντροφον οὕτω προσαγορευόμενον· καὶ τὸν Αἰμίλιον ἀγαθῇ τύχῃ, φάναι, ὦ θύγατερ, καὶ δέχομαι τὸν οἰωνόν. ταῦτα μὲν οὖν Κικέρων ὁ ῥήτωρ ἐν τοῖς περὶ μαντικῆς ἱστόρηκεν.", "st": "Aem. 10.1"}, {"sp": "N", "t": "εἰωθότων δὲ τῶν ὑπατείαν λαβόντων οἷον ἀνθομολογεῖσθαί τινα χάριν καὶ προσαγορεύειν φιλοφρόνως τὸν δῆμον ἀπὸ τοῦ βήματος, Αἰμίλιος εἰς ἐκκλησίαν συναγαγὼν τοὺς πολίτας τὴν μὲν προτέραν ὑπατείαν μετελθεῖν ἔφη αὐτὸς ἀρχῆς δεόμενος, τὴν δὲ δευτέραν ἐκείνων στρατηγοῦ δεομένων· δι’ ὃ μηδεμίαν αὐτοῖς χάριν ἔχειν, ἀλλ’, εἰ νομίζουσι δι’ ἑτέρου βέλτιον ἕξειν τὰ κατὰ τὸν πόλεμον, ἐξίστασθαι τῆς ἡγεμονίας, εἰ δὲ πιστεύουσιν αὐτῷ, μὴ παραστρατηγεῖν μηδὲ λογοποιεῖν, ἀλλ’ ὑπουργεῖν σιωπῇ τὰ δέοντα πρὸς τὸν πόλεμον, ὡς, ἐὰν ἄρχοντος ἄρχειν ζητῶσιν, ἔτι μᾶλλον ἢ νῦν καταγελάστους ἐν ταῖς στρατείαις ἐσομένους. ἀπὸ τούτων τῶν λόγων πολλὴν μὲν αἰδῶ πρὸς αὑτὸν ἐνεποίησε τοῖς πολίταις, μεγάλην δὲ προσδοκίαν τοῦ μέλλοντος, ἡδομένων ἁπάντων ὅτι τοὺς κολακεύοντας παρελθόντες εἵλοντο παρρησίαν ἔχοντα καὶ φρόνημα στρατηγόν. οὕτως ἐπὶ τῷ κρατεῖν καὶ μέγιστος εἶναι τῶν ἄλλων ἀρετῆς καὶ τοῦ καλοῦ δοῦλος ἦν ὁ Ῥωμαίων δῆμος.", "st": "Aem. 11.1"}, {"sp": "N", "t": "Αἰμίλιον δὲ Παῦλον, ὡς ἐξώρμησεν ἐπὶ στρατείαν, πλοῦ μὲν εὐτυχίᾳ καὶ ῥᾳστώνῃ χρήσασθαι πορείας κατὰ δαίμονα τίθημι, σὺν τάχει καὶ μετ’ ἀσφαλείας εἰς τὸ στρατόπεδον κομισθέντα· τοῦ δὲ πολέμου καὶ τῆς στρατηγίας αὑτοῦ τὸ μὲν τόλμης ὀξύτητι, τὸ δὲ βουλεύμασι χρηστοῖς, τὸ δὲ φίλων ἐκθύμοις ὑπηρεσίαις, τὸ δὲ τῷ παρὰ τὰ δεινὰ θαρρεῖν καὶ χρῆσθαι λογισμοῖς ἀραρόσιν ὁρῶν διαπεπραγμένον, οὐκ ἔχω τῇ λεγομένῃ τοῦ ἀνδρὸς εὐτυχίᾳ λαμπρὸν ἀποδοῦναι καὶ διάσημον ἔργον οἷον ἑτέρων στρατηγῶν. εἰ μή τις ἄρα τὴν Περσέως φιλαργυρίαν Αἰμιλίῳ τύχην ἀγαθὴν περὶ τὰ πράγματα γενέσθαι φησίν, ἣ λαμπρὰ καὶ μεγάλα πρὸς τὸν πόλεμον ἀρθέντα ταῖς ἐλπίσι τὰ Μακεδόνων ἀνέτρεψε καὶ κατέβαλε, πρὸς ἀργύριον ἀποδειλιάσαντος. ἧκον μὲν γὰρ αὐτῷ δεηθέντι Βαστέρναι, μύριοι μὲν ἱππεῖς, μύριοι δὲ παραβάται, μισθοφόροι πάντες, ἄνδρες οὐ γεωργεῖν εἰδότες, οὐ πλεῖν, οὐκ ἀπὸ ποιμνίων ζῆν νέμοντες, ἀλλ’ ἓν ἔργον καὶ μίαν τέχνην μελετῶντες ἀεὶ μάχεσθαι καὶ κρατεῖν τῶν ἀντιταττομένων. ὡς δὲ περὶ τὴν Μαιδικὴν καταστρατοπεδεύσαντες ἐπεμίγνυντο τοῖς παρὰ τοῦ βασιλέως ἄνδρες ὑψηλοὶ μὲν τὰ σώματα, θαυμαστοὶ δὲ τὰς μελέτας, μεγάλαυχοι δὲ καὶ λαμπροὶ ταῖς κατὰ τῶν πολεμίων ἀπειλαῖς, θάρσος παρέστησαν τοῖς Μακεδόσι καὶ δόξαν ὡς τῶν Ῥωμαίων οὐχ ὑπομενούντων, ἀλλ’ ἐκπλαγησομένων τὴν ὄψιν αὐτὴν καὶ τὴν κίνησιν ἔκφυλον οὖσαν καὶ δυσπρόσοπτον. οὕτω διαθεὶς τοὺς ἀνθρώπους ὁ Περσεύς καὶ τοιούτων ἐμπλήσας ἐλπίδων, αἰτούμενος καθ’ ἕκαστον ἡγεμόνα χιλίους, πρὸς τὸ γιγνόμενον τοῦ χρυσίου πλῆθος ἰλιγγιάσας καὶ παραφρονήσας ὑπὸ μικρολογίας ἀπείπατο καὶ προήκατο τὴν συμμαχίαν, ὥσπερ οἰκονομῶν, οὐ πολεμῶν Ῥωμαίοις, καὶ λογισμὸν ἀποδώσων ἀκριβῆ τῆς εἰς τὸν πόλεμον δαπάνης οἷς ἐπολέμει· καίτοι διδασκάλους εἶχεν ἐκείνους, οἷς ἄνευ τῆς ἄλλης παρασκευῆς στρατιωτῶν δέκα μυριάδες ἦσαν ἠθροισμέναι καὶ παρεστῶσαι ταῖς χρείαις. ὁ δὲ πρὸς δύναμιν ἀνταίρων τηλικαύτην καὶ πόλεμον οὗ τοσοῦτον ἦν τὸ παρατρεφόμενον, διεμέτρει καὶ παρεσημαίνετο τὸ χρυσίον, ἅψασθαι δεδιὼς ὥσπερ ἀλλοτρίων. καὶ ταῦτ’ ἔπραττεν οὐ Λυδῶν τις οὐδὲ Φοινίκων γεγονώς, ἀλλὰ τῆς Ἀλεξάνδρου καὶ Φιλίππου κατὰ συγγένειαν ἀρετῆς μεταποιούμενος, οἳ τῷ τὰ πράγματα τῶν χρημάτων ὠνητά, μὴ τὰ χρήματα τῶν πραγμάτων ἡγεῖσθαι πάντων ἐκράτησαν. ἐρρέθη γοῦν ὅτι τὰς πόλεις αἱρεῖ τῶν Ἑλλήνων οὐ Φίλιππος, ἀλλὰ τὸ Φιλίππου χρυσίον. Ἀλέξανδρος δὲ τῆς ἐπ’ Ἰνδοὺς στρατείας ἁπτόμενος, καὶ βαρὺν ὁρῶν καὶ δύσογκον ἤδη τὸν Περσικὸν ἐφελκομένους πλοῦτον τοὺς Μακεδόνας, πρώτας ὑπέπρησε τὰς βασιλικὰς ἁμάξας, εἶτα τοὺς ἄλλους ἔπεισε ταὐτὸ ποιήσαντας ἐλαφροὺς ἀναζεῦξαι πρὸς τὸν πόλεμον ὥσπερ λελυμένους. Περσεύς δὲ τὸν χρυσὸν αὐτὸς αὑτοῦ καὶ τέκνων καὶ βασιλείας καταχεάμενος οὐκ ἠθέλησε δι’ ὀλίγων σωθῆναι χρημάτων, ἀλλὰ μετὰ πολλῶν κομισθεὶς ὁ πλούσιος αἰχμάλωτος ἐπιδείξασθαι Ῥωμαίοις ὅσα φεισάμενος ἐτήρησεν αὐτοῖς.", "st": "Aem. 12.1"}, {"sp": "N", "t": "οὐ γὰρ μόνον ἀπέπεμψε τοὺς Γαλάτας ψευσάμενος, ἀλλὰ καὶ Γένθιον ἐπάρας τὸν Ἰλλυριὸν ἐπὶ τριακοσίοις ταλάντοις συνεφάψασθαι τοῦ πολέμου τὰ μὲν χρήματα τοῖς παρ’ αὐτοῦ πεμφθεῖσι προὔθηκεν ἠριθμημένα καὶ κατασημήνασθαι παρέσχεν· ὡς δὲ πεισθεὶς ἔχειν ἃ ᾔτησεν ὁ Γένθιος ἔργον ἀσεβὲς καὶ δεινὸν ἔδρασε (πρέσβεις γὰρ ἐλθόντας Ῥωμαίων πρὸς αὐτὸν συνέλαβε καὶ κατέδησεν), ἡγούμενος ὁ Περσεὺς οὐδὲν ἔτι δεῖσθαι τῶν χρημάτων τὴν ἐκπολέμωσιν, ἄλυτα τοῦ Γενθίου προδεδωκότος ἔχθρας ἐνέχυρα καὶ διὰ τηλικαύτης ἀδικίας ἐμβεβληκότος ἑαυτὸν εἰς τὸν πόλεμον, ἀπεστέρησε τὸν κακοδαίμονα τῶν τριακοσίων ταλάντων, καὶ περιεῖδεν ὀλίγῳ χρόνῳ μετὰ τέκνων καὶ γυναικὸς ὡς ἀπὸ νεοττιᾶς ἀρθέντα τῆς βασιλείας ὑπὸ Λευκίου Ἀνικίου στρατηγοῦ πεμφθέντος ἐπ’ αὐτὸν μετὰ δυνάμεως.", "st": "Aem. 13.1"}, {"sp": "N", "t": "ἐπὶ τοιοῦτον ἀντίπαλον ἐλθὼν ὁ Αἰμίλιος αὐτοῦ μὲν κατεφρόνει, τὴν δ’ ὑπ’ αὐτῷ παρασκευὴν καὶ δύναμιν ἐθαύμαζεν. ἦσαν γὰρ ἱππεῖς μὲν τετρακισχίλιοι, πεζοὶ δ’ εἰς φάλαγγα τετρακισμυρίων οὐ πολλοῖς ἀποδέοντες. ἱδρυμένος δὲ πρὸ τῆς θαλάττης παρὰ τὴν Ὀλυμπικὴν ὑπώρειαν ἐπὶ χωρίων οὐδαμόθεν προσαγωγὴν ἐχόντων καὶ πάντοθεν ὑπ’ αὐτοῦ διαπεφραγμένων ἐρύμασι καὶ προτειχίσμασι ξυλίνοις πολλὴν ἄδειαν ἦγεν, ἀποτρύσειν χρόνῳ καὶ χρημάτων δαπάνῃ τὸν Αἰμίλιον ἡγούμενος. ὁ δὲ τῇ γνώμῃ μὲν ἦν ἐνεργός ἐπὶ πᾶν βούλευμα καὶ πᾶσαν τρεπόμενος πεῖραν, ὑπ’ ἀδείας δὲ τῆς πρόσθεν τὸν στρατὸν ὁρῶν δυσανασχετοῦντα καὶ λόγῳ πολλὰ διαστρατηγοῦντα τῶν ἀπράκτων, ἐπετίμησεν αὐτοῖς, καὶ παρήγγειλε μηδὲν πολυπραγμονεῖν μηδὲ φροντίζειν, ἀλλ’ ἢ τὸ σῶμα τὸ ἑαυτοῦ καὶ τὴν πανοπλίαν ἕκαστον ὅπως ἐνεργὸν παρέξει καὶ χρήσεται Ῥωμαϊκῶς τῇ μαχαίρᾳ, τὸν καιρὸν παραδόντος τοῦ στρατηγοῦ. τὰς δὲ νυκτερινὰς ἐκέλευσε φυλακὰς ἄνευ λόγχης φυλάττειν, ὡς μᾶλλον προσέξοντας καὶ διαμαχουμένους πρὸς τὸν ὕπνον, ἂν ἀμύνασθαι τοὺς πολεμίους μὴ δύνωνται προσιόντας.", "st": "Aem. 13.4"}, {"sp": "N", "t": "Ἐνοχλουμένων δὲ τῶν ἀνθρώπων μάλιστα περὶ τὴν τοῦ ποτοῦ χρείαν καὶ γὰρ ὀλίγον καὶ πονηρὸν ἐπίδυε καὶ συνελείβετο παρ’ αὐτὴν τὴν θάλατταν, ὁρῶν ὁ Αἰμίλιος μέγα καὶ κατηρεφὲς δένδρεσιν ὄρος τὸν Ὄλυμπον ἐπικείμενον, καὶ τεκμαιρόμενος τῇ χλωρότητι τῆς ὕλης ναμάτων ἔχειν ἀρχὰς διὰ βάθους ὑποφερομένων, ἀναπνοὰς αὐτοῖς καὶ φρέατα πολλὰ παρὰ τὴν ὑπώρειαν ὤρυττε. τὰ δ’ εὐθὺς ἐπίμπλατο ῥευμάτων καθαρῶν, ἐπισυνδιδόντων ὁλκῇ καὶ φορᾷ τοῦ θλιβομένου πρὸς τὸ κενούμενον.", "st": "Aem. 14.1"}, {"sp": "N", "t": "καίτοι τινὲς οὔ φασιν ὑδάτων ἑτοίμων κεκρυμμένων πηγὰς ἐναποκεῖσθαι τοῖς τόποις ἐξ ὧν ῥέουσιν, οὐδ’ ἀποκάλυψιν οὐδὲ ῥῆξιν εἶναι τὴν ἐκβολὴν αὐτῶν, ἀλλὰ γένεσιν καὶ σύστασιν ἐνταῦθα τῆς ὕλης ἐξυγραινομένης· ἐξυγραίνεσθαι δὲ πυκνότητι καὶ ψυχρότητι τὴν νοτερὰν ἀναθυμίασιν, ὅταν ἐν βάθει καταθλιβεῖσα ῥευστικὴ γένηται. καθάπερ γὰρ οἱ μαστοὶ τῶν γυναικῶν οὐχ ὥσπερ ἀγγεῖα πλήρεις εἰσὶν ἐπιρρέοντος ἑτοίμου γάλακτος, ἀλλὰ μεταβάλλοντες τὴν τροφὴν ἐν αὑτοῖς ἐργάζονται γάλα καὶ διηθοῦσιν. οὕτως οἱ περίψυκτοι καὶ πιδακώδεις τόποι τῆς γῆς ὕδωρ μὲν οὐκ ἔχουσι καλυπτόμενον, οὐδὲ κόλπους ῥεύματα καὶ βάθη ποταμῶν τοσούτων ἐξ ἑτοίμης καὶ ὑποκειμένης ἀφιέντας ἀρχῆς, τὸ δὲ πνεῦμα καὶ τὸν ἀέρα τῷ πιέζειν καὶ καταπυκνοῦν ἀποθλίβοντες εἰς ὕδωρ τρέπουσι. τὰ γοῦν ὀρυττόμενα τῶν χωρίων μᾶλλον ἀναπιδύει καὶ διανάει πρὸς τὴν τοιαύτην ψηλάφησιν, ὥσπερ οἱ μαστοὶ τῶν γυναικῶν πρὸς τὸν θηλασμόν, ἀνυγραίνοντα καὶ μαλάττοντα τὴν ἀναθυμίασιν· ὅσα δ’ ἀργὰ τῆς γῆς συμπέφρακται, τυφλὰ πρὸς γένεσιν ὑδάτων ἐστίν, οὐκ ἔχοντα τὴν ἐργαζομένην τὸ ὑγρὸν κίνησιν. οἱ δὲ ταῦτα λέγοντες ἐπιχειρεῖν δεδώκασι τοῖς ἀπορητικοῖς, ὡς οὐδὲ τὸ αἷμα τοῖς ζῴοις ἔνεστιν, ἀλλὰ γεννᾶται πρὸς τὰ τραύματα πνεύματός τινος ἢ σαρκῶν μεταβολῇ, ῥύσιν ἀπεργασαμένῃ καὶ σύντηξιν. ἐλέγχονται δὲ τοῖς πρὸς τοὺς ὑπονόμους καὶ τὰς μεταλλείας ἀπαντῶσιν εἰς βάθη ποταμοῖς, οὐ κατ’ ὀλίγον συλλεγομένοις, ὥσπερ εἰκός ἐστιν εἰ γένεσιν ἐκ τοῦ παραχρῆμα κινουμένης τῆς γῆς λαμβάνουσιν, ἀλλ’ ἀθρόοις ἀναχεομένοις. ὁρῶν δὲ καὶ πέτρας πληγῇ ῥαγείσης ἐξεπήδησε ῥεῦμα λάβρον ὕδατος, εἶτα ἐπέλιπε. ταῦτα μὲν περὶ τούτων·", "st": "Aem. 14.3"}, {"sp": "N", "t": "ὁ δ’ Αἰμίλιος ἡμέρας μέν τινας ἠρέμει, καί φασι μήποτε τηλικούτων στρατοπέδων ἐγγὺς οὕτω συνελθόντων ἡσυχίαν γενέσθαι τοσαύτην. ἐπεὶ δὲ κινῶν ἅπαντα καὶ πειρώμενος ἐπυνθάνετο μίαν εἰσβολὴν ἔτι μόνον ἄφρουρον ἀπολείπεσθαι, τὴν διὰ Περραιβίας παρὰ τὸ Πύθιον καί τὴν Πέτραν, τῷ μὴ φυλάττεσθαι τὸν τόπον ἐλπίσας μᾶλλον ἢ δι’ ἣν οὐκ ἐφυλάττετο δυσχωρίαν καί τραχύτητα δείσας ἐβουλεύετο. πρῶτος δὲ τῶν παρόντων ὁ Νασικᾶς ἐπικαλούμενος Σκηπίων, γαμβρὸς Ἀφρικανοῦ Σκηπίωνος, ὕστερον δὲ μέγιστον ἐν τῇ συγκλήτῳ δυνηθείς, ὑπεδέξατο τῆς κυκλώσεως ἡγεμὼν γενέσθαι. δεύτερος δὲ Φάβιος Μάξιμος, ὁ πρεσβύτατος τῶν Αἰμιλίου παίδων, ἔτι μειράκιον ὤν, ἀνέστη προθυμούμενος. ἡσθεὶς οὖν ὁ Αἰμίλιος δίδωσιν αὐτοῖς οὐχ ὅσους Πολύβιος εἴρηκεν, ἀλλ’ ὅσους αὐτὸς ὁ Νασικᾶς λαβεῖν φησι, γεγραφὼς περὶ τῶν πράξεων τούτων ἐπιστόλιον πρός τινα τῶν βασιλέων, οἱ μέν ἐκτὸς τάξεως Ἰταλικοὶ τρισχίλιοι τὸ πλῆθος ἦσαν, τὸ δ’ εὐώνυμον κέρας εἰς πεντακισχιλίους. τούτοις προσλαβὼν ὁ Νασικᾶς ἱππεῖς ἑκατὸν εἴκοσι καί τῶν παρ’ Ἁρπάλῳ Θρᾳκῶν καί Κρητῶν ἀναμεμιγμένων διακοσίους, ἐξώρμησε τῇ πρὸς θάλασσαν ὁδῷ, καί κατεστρατοπέδευσε παρὰ τὸ Ἡράκλειον, ὡς δὴ ταῖς ναυσὶ μέλλων ἐκπεριπλεῖν καί κυκλοῦσθαι τὸ στρατόπεδον τῶν πολεμίων. ἐπεὶ δ’ ἐδείπνησαν οἱ στρατιῶται καί σκότος ἐγένετο, τοῖς ἡγεμόσι φράσας τὸ ἀληθὲς ἦγε διὰ νυκτὸς τὴν ἐναντίαν ἀπὸ θαλάττης, καί καταλύσας ἀνέπαυε τὴν στρατιὰν ὑπὸ τὸ Πύθιον. ἐνταῦθα τοῦ Ὀλύμπου τὸ ὕψος ἀνατείνει πλέον ἢ δέκα σταδίους· σημαίνεται δὲ ἐπιγράμματι τοῦ μετρήσαντος οὕτως·", "st": "Aem. 15.1"}, {"sp": "N", "t": "Οὐλύμπου κορυφῆς ἐπὶ Πυθίου Ἀπόλλωνος<br>ἱερὸν ὕψος ἔχει, πρός κάθετον δὲ μέτρον,<br>πλήρη μέν δεκάδα σταδίων μίαν, αὐτὰρ ἐπ’ αὐτῇ<br>πλέθρον τετραπέδῳ λειπόμενον μεγέθει.<br>Εὐμήλου δέ μιν υἱὸς ἐθήκατο μέτρα κελεύθου<br>Ξειναγόρης· σὺ δ’, ἄναξ, χαῖρε καί ἐσθλὰ δίδου.", "st": "Aem. 15.10"}, {"sp": "N", "t": "καίτοι λέγουσιν οἱ γεωμετρικοὶ μήτε ὄρους ὕψος μήτε βάθος θαλάττης ὑπερβάλλειν δέκα σταδίους. ὁ μέντοι Ξεναγόρας οὐ παρέργως, ἀλλὰ μεθόδῳ καί δι’ ὀργάνων εἰληφέναι δοκεῖ τὴν μέτρησιν.", "st": "Aem. 15.11"}, {"sp": "N", "t": "ὁ μὲν οὖν Νασικᾶς ἐνταῦθα διενυκτέρευσε· τῷ δὲ Περσεῖ τὸν Αἰμίλιον ἀτρεμοῦντα κατὰ χώραν ὁρῶντι καὶ μὴ λογιζομένῳ τὸ γινόμενον ἀποδρὰς ἐκ τῆς ὁδοῦ Κρὴς αὐτόμολος ἧκε μηνύων τὴν περίοδον τῶν Ῥωμαίων. ὁ δὲ συνταραχθείς τὸ μὲν στρατόπεδον οὐκ ἐκίνησε, μυρίους δὲ μισθοφόρους ξένους καὶ δισχιλίους Μακεδόνας Μίλωνι παραδοὺς ἐξαπέστειλε, παρακελευσάμενος ταχῦναι καὶ καταλαβεῖν τὰς ὑπερβολάς. τούτοις ὁ μὲν Πολύβιός φησιν ἔτι κοιμωμένοις ἐπιπεσεῖν τοὺς Ῥωμαίους, ὁ δὲ Νασικᾶς ὀξὺν ἀγῶνα περὶ τοῖς ἄκροις γενέσθαι καὶ κίνδυνον, αὐτὸς δὲ Θρᾷκα μισθοφόρον εἰς χεῖρας συνδραμόντα τῷ ξυστῷ διὰ τοῦ στήθους πατάξας καταβαλεῖν, ἐκβιασθέντων δὲ τῶν πολεμίων, καὶ τοῦ Μίλωνος αἴσχιστα φεύγοντος ἄνευ τῶν ὅπλων μονοχίτωνος, ἀσφαλῶς ἀκολουθεῖν, ἅμα καταβιβάζων εἰς τὴν χώραν τὸ στράτευμα.", "st": "Aem. 16.1"}, {"sp": "N", "t": "τούτων δὲ τῷ Περσεῖ προσπεσόντων κατὰ τάχος ἀναζεύξας ἦγεν ὀπίσω, περίφοβος γεγονὼς καὶ συγκεχυμένος ταῖς ἐλπίσιν. αὐτοῦ δ’ ὅμως πρὸ τῆς Πύδνης ὑπομένοντα πειρᾶσθαι μάχης ἀναγκαῖον ἦν, ἢ τῷ στρατῷ σκεδασθέντι περὶ τὰς πόλεις δέχεσθαι τὸν πόλεμον, ἐπείπερ ἅπαξ ἐμβέβηκε τῇ χώρᾳ, δίχα πολλοῦ φόνου καὶ νεκρῶν ἐκπεσεῖν μὴ δυνάμενον. πλήθει μὲν οὖν ἀνδρῶν αὐτόθεν περιεῖναι, προθυμίαν δὲ πολλὴν ὑπάρχειν ἀμυνομένοις περὶ τέκνων καὶ γυναικῶν, ἐφορῶντος ἕκαστα τοῦ βασιλέως καὶ προκινδυνεύοντος. ἐκ τούτων ἐθάρσυνον οἱ φίλοι τὸν Περσέα· καὶ βαλόμενος στρατόπεδον συνετάττετο πρὸς μάχην, καὶ τὰ χωρία κατεσκοπεῖτο, καὶ διῄρει τὰς ἡγεμονίας, ὡς εὐθὺς ἐξ ἐφόδου τοῖς Ῥωμαίοις ἀπαντήσων. ὁ δὲ τόπος καὶ πεδίον ἦν τῇ φάλαγγι βάσεως ἐπιπέδου καὶ χωρίων ὁμαλῶν δεομένῃ, καὶ λόφοι συνεχεῖς ἄλλος ἐξ ἄλλου τοῖς γυμνητεύουσι καὶ ψιλοῖς ἀναφυγὰς καὶ περιδρομὰς ἔχοντες. διὰ μέσου δὲ ποταμοὶ ῥέοντες Αἴσων καὶ Λεῦκος οὐ μάλα βαθεῖς τότε (θέρους γὰρ ἦν ὥρα φθίνοντος) ἐδόκουν τινὰ δυσεργίαν ὅμως τοῖς Ῥωμαίοις παρέξειν.", "st": "Aem. 16.4"}, {"sp": "N", "t": "ὁ δ’ Αἰμίλιος, ὡς εἰς ταὐτὸν συνέμιξε τῷ Νασικᾷ, κατέβαινε συντεταγμένος ἐπὶ τοὺς πολεμίους. ὡς δ’ εἶδε τὴν παράταξιν αὐτῶν καὶ τὸ πλῆθος, θαυμάσας ἐπέστησε τὴν πορείαν, αὐτός τι πρὸς ἑαυτὸν συλλογιζόμενος. οἱ δ’ ἡγεμονικοὶ νεανίσκοι προθυμούμενοι μάχεσθαι παρελαύνοντες ἐδέοντο μὴ μέλλειν, καὶ μάλιστα πάντων ὁ Νασικᾶς τῇ περὶ τὸν Ὄλυμπον εὐτυχίᾳ τεθαρρηκώς. ὁ δ’ Αἰμίλιος, μειδιάσας, εἴ γε τὴν σὴν, εἶπεν, ἡλικίαν εἶχον αἱ δὲ πολλαί με νῖκαι διδάσκουσαι τὰ τῶν ἡττωμένων ἁμαρτήματα, κωλύουσιν ἐξ ὁδοῦ μάχην τίθεσθαι πρὸς φάλαγγα συντεταγμένην ἤδη καὶ συνεστῶσαν. ἐκ τούτου τὰ μὲν πρῶτα καὶ καταφανῆ πρὸς τοὺς πολεμίους ἐκέλευσεν εἰς σπείρας καθιστάμενα ποιεῖν σχῆμα παρατάξεως, τοὺς δ’ ἀπ’ οὐρᾶς στραφέντας ἐν χώρᾳ χάρακα βαλέσθαι καὶ στρατοπεδεύειν. οὕτω δὲ τῶν συνεχῶν τοῖς τελευταίοις καθ’ ὑπαγωγὴν ἐξελιττομένων ἔλαθε τὴν παράταξιν ἀναλύσας καὶ καταστήσας ἀθορύβως εἰς τὸν χάρακα πάντας.", "st": "Aem. 17.1"}, {"sp": "N", "t": "ἐπεὶ δὲ νὺξ γεγόνει καὶ μετὰ δεῖπνον ἐτράποντο πρὸς ὕπνον καὶ ἀνάπαυσιν, αἰφνίδιον ἡ σελήνη πλήρης οὖσα καὶ μετέωρος ἐμελαίνετο καὶ τοῦ φωτὸς ἀπολιπόντος αὐτὴν χρόας ἀμείψασα παντοδαπὰς ἠφανίσθη. τῶν δὲ Ῥωμαίων, ὥσπερ ἐστὶ νενομισμένον, χαλκοῦ τε πατάγοις ἀνακαλουμένων τὸ φῶς αὐτῆς καὶ πυρὰ πολλὰ δαλοῖς καὶ δᾳσὶν ἀνεχόντων πρὸς τὸν οὐρανόν, οὐδὲν ὅμοιον ἔπραττον οἱ Μακεδόνες, ἀλλὰ φρίκη καὶ θάμβος τὸ στρατόπεδον κατεῖχε καὶ λόγος ἡσυχῇ διὰ πολλῶν ἐχώρει, βασιλέως τὸ φάσμα σημαίνειν ἔκλειψιν. ὁ δ’ Αἰμίλιος οὐκ ἦν μὲν ἀνήκοος οὐδ’ ἄπειρος παντάπασι τῶν ἐκλειπτικῶν ἀνωμαλιῶν, αἳ τὴν σελήνην περιφερομένην εἰς τὸ σκίασμα τῆς γῆς ἐμβάλλουσι τεταγμέναις περιόδοις καὶ ἀποκρύπτουσιν, ἄχρι οὗ παρελθοῦσα τὴν ἐπισκοτουμένην χώραν πάλιν ἐπιλάμψῃ πρὸς τὸν ἥλιον· οὐ μὴν ἀλλὰ τῷ θείῳ πολὺ νέμων καὶ φιλοθύτης ὢν καὶ μαντικός, ὡς εἶδε πρῶτον τὴν σελήνην ἀποκαθαιρομένην, ἕνδεκα μόσχους αὐτῇ κατέθυσεν. ἅμα δ’ ἡμέρᾳ τῷ Ἡρακλεῖ βουθυτῶν οὐκ ἐκαλλιέρει μέχρις εἴκοσι· τῷ δὲ πρώτῳ καὶ εἰκοστῷ παρῆν τὰ σημεῖα καὶ νίκην ἀμυνομένοις ἔφραζεν. εὐξάμενος οὖν κατὰ βοῶν ἑκατὸν καὶ ἀγῶνος ἱεροῦ τῷ θεῷ, προσέταξε διακοσμεῖν τοῖς ἡγεμόσι τὸν στρατὸν εἰς μάχην· αὐτός δὲ τὴν ἀπόκλισιν καὶ περιφορὰν ἀναμένων τοῦ φωτός, ὅπως μὴ κατὰ προσώπου μαχομένοις αὐτοῖς ἕωθεν ἥλιος ἀντιλάμποι, παρῆγε τὸν χρόνον ἐν τῇ σκηνῇ καθεζόμενος ἀναπεπταμένῃ πρὸς τὸ πεδίον καὶ τὴν στρατοπεδείαν τῶν πολεμίων.", "st": "Aem. 17.7"}, {"sp": "N", "t": "περὶ δὲ δείλην οἱ μὲν αὐτοῦ φασι τοῦ Αἰμιλίου τεχνάζοντος ἐκ τῶν πολεμίων γενέσθαι τὴν ἐπιχείρησιν, ἀχάλινον ἵππον ἐξελάσαντας ἐμβαλεῖν αὐτοῖς τοὺς Ῥωμαίους, καὶ τοῦτον ἀρχὴν μάχης διωκόμενον παρασχεῖν· οἱ δὲ Ῥωμαϊκῶν ὑποζυγίων χορτάσματα παρακομιζόντων ἅπτεσθαι Θρᾷκας, ὧν Ἀλέξανδρος ἡγεῖτο, πρὸς δὲ τούτους ἐκδρομὴν ὀξεῖαν ἑπτακοσίων Λιγύων γενέσθαι· παραβοηθούντων δὲ πλειόνων ἑκατέροις οὕτω συνάπτεσθαι τὴν μάχην ἀμφοτέρων. ὁ μὲν οὖν Αἰμίλιος ὥσπερ κυβερνήτης τῷ παρόντι σάλῳ καὶ κινήματι τῶν στρατοπέδων τεκμαιρόμενος τὸ μέγεθος τοῦ μέλλοντος ἀγῶνος, ἐκ τῆς σκηνῆς προῆλθε καὶ τὰ τάγματα τῶν ὁπλιτῶν ἐπιὼν παρεθάρρυνεν, ὁ δὲ Νασικᾶς ἐξιππασάμενος πρὸς τοὺς ἀκροβολιζομένους ὁρᾷ πάντας ὅσον οὔπω τοὺς πολεμίους ἐν χερσὶν ὄντας.", "st": "Aem. 18.1"}, {"sp": "N", "t": "πρῶτοι δ’ οἱ Θρᾷκες ἐχώρουν, ὧν μάλιστά φησιν ἐκπλαγῆναι τὴν ὄψιν, ἄνδρες ὑψηλοὶ τὰ σώματα, λευκῷ καὶ περιλάμποντι θυρεῶν καὶ περικνημίδων ὁπλισμῷ μέλανας ὑπενδεδυμένοι χιτῶνας, ὀρθὰς δὲ ῥομφαίας βαρυσιδήρους ἀπὸ τῶν δεξιῶν ὤμων ἐπισείοντες. παρὰ δὲ τοὺς Θρᾷκας οἱ μισθοφόροι παρενέβαλλον, ὧν σκευαί τε παντοδαπαὶ, καὶ μεμιγμένοι Παίονες ἦσαν· ἐπὶ δὲ τούτοις ἄγημα τρίτον οἱ λογάδες, αὐτῶν Μακεδόνων ἀρετῇ καὶ ἡλικίᾳ τὸ καθαρώτατον, ἀστράπτοντες ἐπιχρύσοις ὅπλοις καὶ νεουργοῖς φοινικίσιν. οἷς καθισταμένοις εἰς τάξιν αἱ τῶν χαλκασπίδων ἐπανατέλλουσαι φάλαγγες ἐκ τοῦ χάρακος ἐνέπλησαν αὐγῆς σιδήρου καὶ λαμπηδόνος χαλκοῦ τὸ πεδίον, κραυγῆς δὲ καὶ θορύβου παρακελευομένων τὴν ὀρεινήν. οὕτω δὲ θρασέως καὶ μετὰ τάχους ἐπῄεσαν ὥστε τοὺς πρώτους νεκροὺς ἀπὸ δυεῖν σταδίων τοῦ Ῥωμαϊκοῦ χάρακος καταπεσεῖν.", "st": "Aem. 18.5"}, {"sp": "N", "t": "γιγνομένης δὲ τῆς ἐφόδου παρῆν ὁ Αἰμίλιος, καὶ κατελάμβανεν ἤδη τοὺς ἐν τοῖς ἀγήμασι Μακεδόνας ἄκρας τάς σαρίσας προσερηρεικότας τοῖς θυρεοῖς τῶν Ῥωμαίων καὶ μὴ προσιεμένους εἰς ἐφικτὸν αὐτῶν τάς μαχαίρας. ἐπεὶ δὲ καὶ τῶν ἄλλων Μακεδόνων τάς τε πέλτας ἐξ ὤμου περισπασάντων καὶ ταῖς σαρίσαις ἀφ’ ἑνὸς συνθήματος κλιθείσαις ὑποστάντων τοὺς θυρεοφόρους εἶδε τήν τε ῥώμην τοῦ συνασπισμοῦ καὶ τήν τραχύτητα τῆς προβολῆς, ἔκπληξις αὐτὸν ἔσχε καὶ δέος, ὡς οὐδὲν ἰδόντα πώποτε θέαμα φοβερώτερον· καὶ πολλάκις ὕστερον ἐμέμνητο τοῦ πάθους ἐκείνου καὶ τῆς ὄψεως. τότε δὲ πρὸς τοὺς μαχομένους ἐπιδεικνύμενος ἵλεω καὶ φαιδρὸν ἑαυτόν ἄνευ κράνους καὶ θώρακος ἵππῳ παρήλαυνεν. ὁ δὲ τῶν Μακεδόνων βασιλεύς, ὥς φησι Πολύβιος, τῆς μάχης ἀρχὴν λαμβανούσης ἀποδειλιάσας εἰς πόλιν ἀφιππάσατο, σκηψάμενος Ἡρακλεῖ θύειν, δειλὰ παρὰ δειλῶν ἱερὰ μὴ δεχομένῳ μηδ’ εὐχὰς ἀθεμίτους ἐπιτελοῦντι. θεμιτὸν γὰρ οὐκ ἔστιν οὔτε τόν μὴ βάλλοντα κατευστοχεῖν οὔτε τόν μὴ μένοντα κρατεῖν οὔθ’ ὅλως τόν ἄπρακτον εὐπραγεῖν οὔτε τόν κακὸν εὐδαιμονεῖν. ἀλλὰ ταῖς Αἰμιλίου παρῆν εὐχαῖς ὁ θεός· εὔχετο γὰρ κράτος πολέμου καὶ νίκην δόρυ κρατῶν, καὶ μαχόμενος παρεκάλει σύμμαχον τόν θεόν.", "st": "Aem. 19.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ Ποσειδώνιός τις ἐν ἐκείνοις τοῖς χρόνοις καὶ ταῖς πράξεσι γεγονέναι λέγων, ἱστορίαν δὲ γεγραφὼς περὶ Περσέως ἐν πλείοσι βιβλίοις, φησὶν αὐτὸν οὐχ ὑπὸ δειλίας οὐδὲ τήν θυσίαν ποιησάμενον αἰτίαν ἀπελθεῖν, ἀλλὰ τῇ προτέρᾳ τῆς μάχης τυχεῖν λελακτισμένον ὑφ’ ἵππου τὸ σκέλος· ἐν δὲ τῇ μάχῃ, καίπερ ἔχοντα δυσχρήστως καὶ κωλυόμενον ὑπὸ τῶν φίλων, ἵππον αὑτῷ κελεῦσαι τῶν φορέων προσαγαγεῖν καὶ περιβάντα συμμῖξαι τοῖς ἐπὶ τῆς φάλαγγος ἀθωράκιστον· φερομένων δὲ παντοδαπῶν ἑκατέρωθεν βελῶν, παλτὸν ἐμπεσεῖν ὁλοσίδηρον αὐτῷ, καὶ τῇ μὲν ἀκμῇ μὴ θιγεῖν, ἀλλὰ πλάγιον παρὰ τήν ἀριστερὰν πλευρὰν παραδραμεῖν, ῥύμῃ δὲ τῆς παρόδου τόν τε χιτῶνα διακόψαι καὶ τήν σάρκα φοινίξαι τυφλῷ μώλωπι, πολὺν χρόνον διαφυλάξαντι τόν τύπον. ταῦτα μὲν οὖν ὁ Ποσειδώνιος ὑπὲρ τοῦ Περσέως ἀπολογεῖται.", "st": "Aem. 19.7"}, {"sp": "N", "t": "τῶν δὲ Ῥωμαίων, ὡς ἀντέστησαν τῇ φάλαγγι, μὴ δυναμένων βιάζεσθαι, Σάλουιος ὁ τῶν Πελιγνῶν ἡγούμενος ἁρπάσας τὸ σημεῖον τῶν ὑφ’ αὑτὸν εἰς τοὺς πολεμίους ἔρριψε. τῶν δὲ Πελιγνῶν (οὐ γάρ ἐστιν Ἰταλοῖς θεμιτὸν οὐδ’ ὅσιον ἐγκαταλιπεῖν σημεῖον) ἐπιδραμόντων πρὸς ἐκεῖνον τὸν τόπον ἔργα δεινὰ καὶ πάθη παρ’ ἀμφοτέρων ἀπήντα συμπεσόντων. οἱ μὲν γὰρ ἐκκρούειν τε τοῖς ξίφεσι τὰς σαρίσας ἐπειρῶντο καὶ πιέζειν τοῖς θυρεοῖς καὶ ταῖς χερσὶν αὐταῖς ἀντιλαμβανόμενοι παραφέρειν, οἱ δὲ τὴν προβολὴν κρατυνάμενοι δι’ ἀμφοτέρων καὶ τοὺς προσπίπτοντας αὐτοῖς ὅπλοις διελαύνοντες, οὔτε θυρεοῦ στέγοντος οὔτε θώρακος τὴν βίαν τῆς σαρίσης, ἀνερρίπτουν ὑπὲρ κεφαλὴν τὰ σώματα τῶν Πελιγνῶν καὶ Μαρρουκινῶν, κατ’ οὐδένα λογισμὸν, ἀλλὰ θυμῷ θηριώδει, πρὸς ἐναντίας πληγὰς καὶ προὖπτον ὠθουμένων θάνατον. οὕτω δὲ τῶν προμάχων διαφθαρέντων ἀνεκόπησαν οἱ κατόπιν αὐτῶν ἐπιτεταγμένοι· καὶ φυγὴ μὲν οὐκ ἦν, ἀναχώρησις δὲ πρὸς ὄρος τὸ καλούμενον Ὀλόκρον, ὥστε καὶ τὸν Αἰμίλιον ἰδόντα φησὶν ὁ Ποσειδώνιος καταρρήξασθαι τὸν χιτῶνα, τούτων μὲν ἐνδιδόντων, τῶν δ’ ἄλλων Ῥωμαίων διατρεπομένων τὴν φάλαγγα προσβολὴν οὐκ ἔχουσαν, ἀλλ’ ὥσπερ χαρακώματι τῷ πυκνώματι τῶν σαρισῶν ὑπαντιάζουσαν πάντοθεν ἀπρόσμαχον.", "st": "Aem. 20.1"}, {"sp": "N", "t": "ἐπεὶ δὲ τῶν τε χωρίων ἀνωμάλων ὄντων, καὶ διὰ τὸ μῆκος τῆς παρατάξεως οὐ φυλαττούσης ἀραρότα τὸν συνασπισμόν, κατεῖδε τὴν φάλαγγα τῶν Μακεδόνων κλάσεις τε πολλὰς καὶ διασπάσματα λαμβάνουσαν, ὡς εἰκὸς ἐν μεγάλοις στρατοῖς καὶ ποικίλαις ὁρμαῖς τῶν μαχομένων, τοῖς μὲν ἐκθλιβομένην μέρεσι, τοῖς δὲ προπίπτουσαν, ἐπιὼν ὀξέως καὶ διαιρῶν τὰς σπείρας ἐκέλευεν εἰς τὰ διαλείμματα καὶ κενώματα τῆς τῶν πολεμίων τάξεως παρεμπίπτοντας καὶ συμπλεκομένους μὴ μίαν πρὸς ἅπαντας, ἀλλὰ πολλὰς καὶ μεμιγμένας κατά μέρος τὰς μάχας τίθεσθαι. ταῦτα τοῦ μὲν Αἰμιλίου τοὺς ἡγεμόνας, τῶν δ’ ἡγεμόνων τοὺς στρατιώτας διδασκόντων, ὡς πρῶτον ὑπέδυσαν καὶ διέσχον εἴσω τῶν ὅπλων, τοῖς μὲν ἐκ πλαγίου κατὰ γυμνὰ προσφερόμενοι, τοὺς δὲ ταῖς περιδρομαῖς ἀπολαμβάνοντες, ἡ μὲν ἰσχὺς καὶ τὸ κοινὸν ἔργον εὐθὺς ἀπωλώλει τῆς φάλαγγος ἀναρρηγνυμένης, ἐν δὲ ταῖς καθ’ ἕνα καὶ κατ’ ὀλίγους συστάσεσιν οἱ Μακεδόνες μικροῖς μὲν ἐγχειριδίοις στερεοὺς καὶ ποδήρεις θυρεοὺς νύσσοντες, ἐλαφροῖς δὲ πελταρίοις πρὸς τὰς ἐκείνων μαχαίρας ὑπὸ βάρους καὶ καταφορᾶς διὰ παντὸς ὅπλου χωρούσας ἐπὶ τὰ σώματα, κακῶς ἀντέχοντες ἐτράποντο,", "st": "Aem. 20.7"}, {"sp": "N", "t": "κατὰ τούτους δὲ μέγας ἦν ἀγών, ἔνθα δὴ καὶ Μᾶρκος ὁ Κάτωνος υἱός, Αἰμιλίου δὲ γαμβρός, πᾶσαν ἀλκὴν ἐπιδεικνύμενος ἀπέβαλε τὸ ξίφος. οἷα δὲ νεανίας ἐντεθραμμένος πλείστοις παιδεύμασι καὶ μεγάλῳ πατρὶ μεγάλης ἀρετῆς ἀποδείξεις ὀφείλων, οὐ βιωτὸν ἡγησάμενος εἶναι προεμένῳ σκῦλον αὑτοῦ ζῶντος τοῖς πολεμίοις ἐπέδραμε τὴν μάχην, εἴ τινά που φίλον καὶ συνήθη κατίδοι, φράζων τὸ συμπεσὸν αὐτῷ καὶ δεόμενος βοηθεῖν, οἱ δὲ πολλοὶ καὶ ἀγαθοὶ γενόμενοι καὶ διασχόντες ὁρμῇ μιᾷ τοὺς ἄλλους, περὶ αὐτὸν ὑφηγούμενον ἐμβάλλουσι τοῖς ἐναντίοις. μεγάλῳ δ’ ἀγῶνι καὶ φόνῳ πολλῷ καὶ τραύμασιν ὤσαντες ἐκ χώρας καὶ τόπον ἔρημον καὶ γυμνὸν κατασχόντες ἐπὶ ζήτησιν ἐτράποντο τοῦ ξίφους. ὡς δὲ μόλις ἐν πολλοῖς ὅπλοις καὶ πτώμασι νεκρῶν κεκρυμμένον ἀνευρέθη, περιχαρεῖς γενόμενοι καὶ παιανίσαντες ἔτι λαμπρότερον ἐνέκειντο τοῖς συνεστῶσιν ἔτι τῶν πολεμίων. καὶ τέλος οἱ τρισχίλιοι λογάδες ἐν τάξει μένοντες καὶ μαχόμενοι κατεκόπησαν ἅπαντες· τῶν δ’ ἄλλων φευγόντων πολὺς ἦν ὁ φόνος, ὥστε τὸ μὲν πεδίον καὶ τὴν ὑπώρειαν καταπεπλῆσθαι νεκρῶν, τοῦ δὲ Λεύκου ποταμοῦ τὸ ῥεῦμα τοὺς Ῥωμαίους τῇ μετὰ τὴν μάχην ἡμέρᾳ διελθεῖν ἔτι μεμιγμένον αἵματι. λέγονται γὰρ ὑπὲρ δισμυρίους πεντακισχιλίους ἀποθανεῖν. τῶν δὲ Ῥωμαίων ἔπεσον, ὡς μὲν Ποσειδώνιός φησιν, ἑκατόν, ὡς δὲ Νασικᾶς, ὀγδοήκοντα.", "st": "Aem. 21.1"}, {"sp": "N", "t": "καὶ κρίσιν μὲν ὀξυτάτην μέγιστος ἀγὼν οὗτός ἔσχεν ἐνάτης γὰρ ὥρας ἀρξάμενοι μάχεσθαι πρὸ δεκάτης ἐνίκησαν τῷ δὲ λειπομένῳ τῆς ἡμέρας χρησάμενοι πρὸς τὴν δίωξιν καὶ μέχρι σταδίων ἑκατὸν καὶ εἴκοσι διώξαντες ἑσπέρας ἤδη βαθείας ἀπετράποντο. καὶ τοὺς μὲν ἄλλους οἱ θεράποντες ὑπὸ λαμπάδων ἀπαντῶντες μετὰ χαρᾶς καὶ βοῆς ἀπῆγον ἐπὶ τὰς σκηνάς φωτὶ λαμπομένας καὶ κεκοσμημένας κιττοῦ καὶ δάφνης στεφάνοις· αὐτὸν δὲ τὸν στρατηγὸν μέγα πένθος εἶχε. δυεῖν γὰρ υἱῶν αὐτοῦ στρατευομένων ὁ νεώτερος οὐδαμοῦ φανερὸς ἦν, ὃν ἐφίλει τε μάλιστα καὶ πλεῖστον εἰς ἀρετὴν φύσει προὔχοντα τῶν ἀδελφῶν ἑώρα. θυμοειδῆ δὲ καὶ φιλότιμον ὄντα τὴν ψυχήν, ἔτι δ’ ἀντίπαιδα τὴν ἡλικίαν, παντάπασιν ἀπολωλέναι κατεδόξαζεν, ὑπ’ ἀπειρίας ἀναμιχθέντα τοῖς πολεμίοις μαχομένοις. ἀπορουμένου δὲ αὐτοῦ καὶ περιπαθοῦντος ᾔσθετο πᾶν τὸ στράτευμα, καὶ μεταξὺ δειπνοῦντες ἀνεπήδων καὶ διέθεον μετὰ λαμπάδων, πολλοὶ μὲν ἐπὶ τὴν σκηνὴν τοῦ Αἰμιλίου, πολλοὶ δὲ πρὸ τοῦ χάρακος ἐν τοῖς πρώτοις νεκροῖς ζητοῦντες. κατήφεια δὲ τὸ στρατόπεδον καὶ κραυγὴ τὸ πεδίον κατεῖχεν ἀνακαλουμένων τὸν Σκηπίωνα. πᾶσι γὰρ ἀγαστὸς ἦν εὐθὺς ἐξ ἀρχῆς, πρὸς ἡγεμονίαν καὶ πολιτείαν ὡς ἄλλος οὐδεὶς τῶν συγγενῶν κεκραμένος τὸ ἦθος.", "st": "Aem. 22.1"}, {"sp": "N", "t": "ὀψὲ δ’ οὖν ἤδη σχεδὸν ἀπεγνωσμένος ἐκ τῆς διώξεως προσῄει μετὰ δύο ἢ τριῶν ἑταίρων, αἵματος καὶ φόνου πολεμίων ἀνάπλεως, ὥσπερ σκύλαξ γενναῖος, ὑφ’ ἡδονῆς ἀκρατῶς τῇ νίκῃ συνεξενεχθείς. οὗτός ἐστι Σκηπίων ὁ τοῖς ἱκνουμένοις χρόνοις Καρχηδόνα καὶ Νομαντίαν κατασκάψας καὶ πολὺ πρῶτος ἀρετῇ τῶν τότε Ῥωμαίων γενόμενος καὶ δυνηθεὶς μέγιστον. Αἰμιλίῳ μὲν οὖν τὴν τοῦ κατορθώματος νέμεσιν εἰς ἕτερον ἡ τύχη καιρὸν ὑπερβαλλομένη τότε παντελῆ τὴν ἡδονὴν ἀπεδίδου τῆς νίκης.", "st": "Aem. 22.7"}, {"sp": "N", "t": "Περσεὺς δὲ φυγῇ μέν ἐκ Πύδνης εἰς Πέλλαν ἀπεχώρει, τῶν ἱππέων ἐπιεικῶς πάντων ἀπὸ τῆς μάχης διασεσῳσμένων. ἐπεὶ δὲ καταλαμβάνοντες οἱ πεζοὶ τοὺς ἱππεῖς ὡς ἀνάνδρους καὶ προδεδωκότας λοιδοροῦντες ἀπὸ τῶν ἵππων ὤθουν καὶ πληγὰς ἐδίδοσαν, δείσας τὸν θόρυβον ἐκ τῆς ὁδοῦ παρέκλινε τὸν ἵππον, καὶ τὴν πορφύραν, ὡς μὴ διάσημος εἴη, περισπάσας ἔθετο πρόσθεν αὑτοῦ, καὶ τὸ διάδημα διὰ χειρῶν εἶχεν. ὡς δὲ καὶ προσδιαλέγοιτο τοῖς ἑταίροις ἅμα βαδίζων, καταβὰς ἐφείλκετο τὸν ἵππον. τῶν δὲ ὁ μέν τις ὑπόδημα προσποιούμενος λελυμένον συνάπτειν, ὁ δ’ ἵππον ἄρδειν, ὁ δὲ ποτοῦ χρῄζειν, ὑπολειπόμενοι κατὰ μικρὸν ἀπεδίδρασκον, οὐχ οὕτω τοὺς πολεμίους, ὡς τὴν ἐκείνου χαλεπότητα δεδοικότες. κεχαραγμένος γὰρ ὑπὸ τῶν κακῶν εἰς πάντας ἐζήτει τρέπειν ἀφ’ αὐτοῦ τὴν αἰτίαν τῆς ἥττης. ἐπεὶ δὲ νυκτὸς εἰς Πέλλαν εἰσελθὼν Εὖκτον καὶ Εὔλαιον, τοὺς ἐπὶ τοῦ νομίσματος, ἀπαντήσαντας αὐτῷ καὶ τὰ μέν ἐγκαλοῦντας περὶ τῶν γεγονότων, τὰ δὲ παρρησιαζομένους ἀκαίρως καὶ συμβουλεύοντας ὀργισθεὶς ἀπέκτεινεν, αὐτὸς τῷ ξιφιδίῳ παίων ἀμφοτέρους, οὐδεὶς παρέμεινεν αὐτῷ πάρεξ Εὐάνδρου τε τοῦ Κρητὸς καὶ Ἀρχεδάμου τοῦ Αἰτωλοῦ καὶ τοῦ Βοιωτοῦ Νέωνος. τῶν δὲ στρατιωτῶν ἐπηκολούθησαν οἱ Κρῆτες, οὐ δι’ εὔνοιαν, ἀλλὰ τοῖς χρήμασιν, ὥσπερ κηρίοις μέλιτται, προσλιπαροῦντες. πάμπολλα γὰρ ἐπήγετο, καὶ προὔθηκεν ἐξ αὐτῶν διαρπάσαι τοῖς Κρησὶν ἐκπώματα καὶ κρατῆρας καὶ τὴν ἄλλην ἐν ἀργύρῳ καὶ χρυσῷ κατασκευὴν εἰς πεντήκοντα ταλάντων λόγον. γενόμενος δ’ ἐν Ἀμφιπόλει πρῶτον, εἶτ’ ἐκεῖθεν ἐν Γαληψῷ, καὶ τοῦ φόβου μικρὸν ὑπανέντος, εἰς τὸ συγγενὲς καὶ πρεσβύτατον αὐτοῦ τῶν νοσημάτων, τὴν μικρολογίαν, αὖθις ὑπενεχθείς ὠδύρετο πρὸς τοὺς φίλους ὡς τῶν Ἀλεξάνδρου τοῦ μεγάλου χρυσωμάτων ἔνια τοῖς Κρησὶ διερριφὼς ὑπ’ ἀγνοίας, καὶ παρεκάλει τοὺς ἔχοντας ἀντιβολῶν καὶ δακρύων ἀμείψασθαι πρὸς νόμισμα. τοὺς μέν οὖν ἐπισταμένους ἀκριβῶς αὐτὸν οὐκ ἔλαθε κρητίζων πρὸς Κρῆτας, οἱ δὲ πεισθέντες καὶ ἀποδόντες ἀπεστερήθησαν. οὐ γὰρ ἀπέδωκε τἀργύριον, ἀλλὰ τριάκοντα τάλαντα κερδάνας ἀπὸ τῶν φίλων, ἃ μικρὸν ὕστερον ἔμελλον οἱ πολέμιοι λήψεσθαι, μετ’ αὐτῶν διέπλευσεν εἰς Σαμοθρᾴκην καὶ διαφεύγων ἐπὶ τοὺς Διοσκούρους ἱκέτευεν.", "st": "Aem. 23.1"}, {"sp": "N", "t": "ἀεὶ μὲν οὖν λέγονται φιλοβασίλειοι Μακεδόνες, τότε δ’ ὡς ἐρείσματι κεκλασμένῳ πάντων ἅμα συμπεσόντων ἐγχειρίζοντες αὑτοὺς τῷ Αἰμιλίῳ δύο ἡμέραις ὅλης κύριον αὐτὸν κατέστησαν Μακεδονίας. καὶ δοκεῖ τοῦτο μαρτυρεῖν τοῖς εὐτυχίᾳ τινὶ τὰς πράξεις ἐκείνας γεγονέναι φάσκουσιν. ἔτι δὲ καὶ τὸ περὶ τὴν θυσίαν σύμπτωμα δαιμόνιον ἦν ἐν Ἀμφιπόλει θύοντος τοῦ Αἰμιλίου καὶ τῶν ἱερῶν ἐνηργμένων κεραυνὸς ἐνσκήψας εἰς τὸν βωμὸν ἐπέφλεξε καὶ συγκαθήγισε τὴν ἱερουργίαν. ὑπερβάλλει δὲ θειότητι πάντως καὶ τύχῃ τὰ τῆς φήμης, ἦν μὲν γὰρ ἡμέρα τετάρτη νενικημένῳ Περσεῖ περὶ Πύδναν, ἐν δὲ τῇ Ῥώμῃ τοῦ δήμου θεωροῦντος ἱππικοὺς ἀγῶνας ἐξαίφνης ἐνέπεσε λόγος εἰς τὸ πρῶτον τοῦ θεάτρου μέρος ὡς Αἰμίλιος μεγάλῃ μάχῃ νενικηκὼς Περσέα καταστρέφοιτο σύμπασαν Μακεδονίαν. ἐκ δὲ τούτου ταχὺ τῆς φήμης ἀναχεομένης εἰς τὸ πλῆθος ἐξέλαμψε χαρὰ μετὰ κρότου καὶ βοῆς τὴν ἡμέραν ἐκείνην κατασχοῦσα τὴν πόλιν. εἶτα, ὡς ὁ λόγος οὐκ εἶχεν εἰς ἀρχὴν ἀνελθεῖν βέβαιον, ἀλλ’ ἐν πᾶσιν ὁμοίως ἐφαίνετο πλανώμενος, τότε μὲν ἐσκεδάσθη καὶ διερρύη τὰ τῆς φήμης, ὀλίγαις δ’ ὕστερον ἡμέραις πυθόμενοι σαφῶς ἐθαύμαζον τὴν προδραμοῦσαν ἀγγελίαν, ὡς ἐν τῷ ψεύδει τὸ ἀληθὲς εἶχε,", "st": "Aem. 24.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ τῆς ἐπὶ Σάγρᾳ ποταμῷ μάχης Ἰταλιωτῶν αὐθημερὸν ἐν Πελοποννήσῳ λόγον γενέσθαι, καὶ Πλαταιᾶσι τῆς ἐν Μυκάλῃ πρὸς Μήδους. ἣν δὲ Ῥωμαῖοι Ταρκυνίους μετὰ Λατίνων ἐπιστρατεύσαντας ἐνίκησαν, αὐτάγγελοι φράζοντες ὤφθησαν ἀπὸ τοῦ στρατοῦ μικρὸν ὕστερον ἄνδρες δύο καλοὶ καὶ μεγάλοι, τούτους εἴκασαν εἶναι Διοσκούρους. ὁ δ’ ἐντυχὼν πρῶτος αὐτοῖς κατ’ ἀγορὰν πρὸ τῆς κρήνης, ἀναψύχουσι τοὺς ἵππους ἱδρῶτι πολλῷ περιρρεομένους, ἐθαύμαζε τὸν περὶ τῆς νίκης λόγον. εἶθ’ οἱ μὲν ἐπιψαῦσαι λέγονται τῆς ὑπήνης αὐτοῦ τοῖν χεροῖν ἀτρέμα μειδιῶντες· ἡ δὲ εὐθὺς ἐκ μελαίνης τριχὸς εἰς πυρρὰν μεταβαλοῦσα τῷ μὲν λόγῳ πίστιν, τῷ δ’ ἀνδρὶ παρασχεῖν ἐπίκλησιν τὸν Ἀηνόβαρβον, ὅπερ ἐστὶ χαλκοπώγωνα. πᾶσι δὲ τούτοις τὸ καθ’ ἡμᾶς γενόμενον πίστιν παρέσχεν. ὅτε γὰρ Ἀντώνιος ἀπέστη Δομετιανοῦ καὶ πολὺς πόλεμος ἀπὸ Γερμανίας προσεδοκᾶτο, τῆς Ῥώμης ταραττομένης ἄφνω καὶ αὐτομάτως ὁ δῆμος ἐξ αὑτοῦ φήμην ἀνέδωκε νίκης, καὶ τὴν Ῥώμην ἐπέδραμε λόγος αὐτόν τε τὸν Ἀντώνιον ἀνῃρῆσθαι καὶ τοῦ σὺν αὐτῷ στρατεύματος ἡττημένου μηδὲν μέρος λελεῖφθαι. τοσαύτην δὲ λαμπρότητα καὶ ῥύμην ἡ πίστις ἔσχεν ὥστε καὶ θῦσαι τῶν ἐν τέλει πολλούς. ζητουμένου δὲ τοῦ πρώτου φράσαντος, ὡς οὐδεὶς ἦν, ἀλλ’ ο λόγος εἰς ἄλλον ἐξ ἄλλου διωκόμενος ἀνέφευγε, καὶ τέλος καταδὺς ὥσπερ εἰς πέλαγος ἀχανὲς τὸν ἄπειρον ὄχλον ἐφάνη μηδεμίαν ἀρχὴν ἔχων βέβαιον, αὕτη μὲν ἡ φήμη ταχὺ τῆς πόλεως ἐξερρύη, πορευομένῳ δὲ τῷ Δομετιανῷ μετὰ δυνάμεως ἐπὶ τὸν πόλεμον ἤδη καθ’ ὁδὸν ἀγγελία καὶ γράμματα φράζοντα τὴν νίκην ἀπήντησεν. ἡ δ’ αὐτοῦ τοῦ κατορθώματος ἡμέρα καὶ τῆς φήμης ἐγίνετο, ἐπὶ πλέον ἢ δισμυρίους σταδίους τῶν τόπων διεστώτων. ταῦτα μὲν οὐδεὶς ἀγνοεῖ τῶν καθ’ ἡμᾶς.", "st": "Aem. 25.1"}, {"sp": "N", "t": "Γναῖος δὲ Ὀκτάβιος ὁ ναυαρχῶν Αἰμιλίῳ προσορμισάμενος τῇ Σαμοθρᾴκῃ τὴν μὲν ἀσυλίαν παρεῖχε τῷ Περσεῖ διὰ τοὺς θεούς, ἔκπλου δὲ καὶ φυγῆς εἶργεν. οὐ μὴν ἀλλὰ λανθάνει πως ὁ Περσεὺς Ὀροάνδην τινὰ Κρῆτα λέμβον ἔχοντα συμπείσας μετὰ χρημάτων ἀναλαβεῖν αὐτόν, ὁ δὲ κρητισμῷ χρησάμενος τὰ μὲν χρήματα νύκτωρ ἀνέλαβεν, ἐκεῖνον δὲ τῆς ἑτέρας νυκτὸς ἥκειν κελεύσας ἐπὶ τὸν πρὸς τῷ Δημητρίῳ λιμένα μετὰ τῶν τέκνων καὶ θεραπείας ἀναγκαίας, εὐθὺς ἀφ’ ἑσπέρας ἀπέπλευσεν. ὁ δὲ Περσεὺς οἰκτρὰ μὲν ἔπασχε διὰ στενῆς θυρίδος παρὰ τὸ τεῖχος ἐκμηρυόμενος αὑτὸν καὶ παιδία καὶ γυναῖκα πόνων καὶ πλάνης ἀπείρους, οἰκτρότατον δὲ στεναγμὸν ἀφῆκεν, ὥς τις αὐτῷ πλανωμένῳ παρὰ τὸν αἰγιαλὸν ἤδη πελάγιον τὸν Ὀροάνδην θέοντα κατιδὼν ἔφρασεν. ὑπέλαμπε γὰρ ἡμέρα, καὶ πάσης ἐλπίδος ἔρημος ὑπεχώρει φυγῇ πρὸς τὸ τεῖχος, οὐ λαθὼν μέν, ὑποφθάσας δὲ τοὺς Ῥωμαίους, μετὰ τῆς γυναικός. τὰ δὲ παιδία συλλαβὼν αὐτοῖς Ἴων ἐνεχείρισεν, ὃς πάλαι μὲν ἐρώμενος ἦν τοῦ Περσέως, τότε δὲ προδότης γενόμενος αἰτίαν παρέσχε τὴν μάλιστα συναναγκάσασαν τὸν ἄνθρωπον, ὡς θηρίον ἁλισκομένων τῶν τέκνων, εἰς χεῖρας ἐλθεῖν καὶ παραδοῦναι τὸ σῶμα τοῖς ἐκείνων κρατοῦσιν.", "st": "Aem. 26.1"}, {"sp": "N", "t": "ἐπίστευε μὲν οὖν μάλιστα τῷ Νασικᾷ, κἀκεῖνον ἐκάλει μὴ παρόντος δὲ κατακλαύσας τὴν τύχην καὶ τὴν ἀνάγκην περισκεψάμενος ἔδωκεν αὑτὸν ὑποχείριον τῷ Γναίῳ, τότε μάλιστα ποιήσας φανερόν ὅτι τῆς φιλαργυρίας ἦν ἐν αὐτῷ τι κακὸν ἀγεννέστερον ἡ φιλοψυχία, δι’ ἥν, ὃ μόνον ἡ τύχη τῶν ἐπταικότων οὐκ ἀφαιρεῖται, τὸν ἔλεον, ἀπεστέρησεν ἑαυτοῦ. δεηθεὶς γὰρ ἀχθῆναι πρὸς τὸν Αἰμίλιον, ὁ μὲν ὡς ἀνδρὶ μεγάλῳ πεπτωκότι πτῶμα νεμεσητὸν καὶ δυστυχὲς ἐξαναστὰς ὑπήντα μετὰ τῶν φίλων δεδακρυμένος· ὁ δ’, αἴσχιστον θέαμα, προβαλὼν αὑτὸν ἐπὶ στόμα καὶ γονάτων δραξάμενος ἀνεβάλλετο φωνὰς ἀγεννεῖς καὶ δεήσεις, ἃς οὐχ ὑπέμεινεν οὐδ’ ἤκουσεν ὁ Αἰμίλιος, ἀλλὰ προσβλέψας αὑτὸν ἀλγοῦντι καὶ λελυπημένῳ τῷ προσώπῳ, τί τῆς τύχης, εἶπεν, ὦ ταλαίπωρε, τὸ μέγιστον ἀφαιρεῖς τῶν ἐγκλημάτων, ταῦτα πράττων ἀφ’ ὧν δόξεις οὐ παρ’ ἀξίαν ἀτυχεῖν, οὐδὲ τοῦ νῦν, ἀλλὰ τοῦ πάλαι δαίμονος ἀνάξιος γεγονέναι; τί δέ μου καταβάλλεις τὴν νίκην, καὶ τὸ κατόρθωμα ποιεῖς μικρόν, ἐπιδεικνύμενος ἑαυτὸν οὐ γενναῖον οὐδὲ πρέποντα Ῥωμαίων ἀνταγωνιστήν; ἀρετή τοι δυστυχοῦσι μεγάλην ἔχει μοῖραν αἰδοῦς καὶ παρὰ πολεμίοις, δειλία δὲ Ῥωμαίοις, κἂν εὐποτμῇ, πάντη ἀτιμότατον.", "st": "Aem. 26.7"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τοῦτον μὲν ἀναστήσας καὶ δεξιωσάμενος Τουβέρωνι παρέδωκεν, αὐτὸς δὲ τοὺς παῖδας καὶ τοὺς γαμβροὺς καὶ τῶν ἄλλων ἡγεμονικῶν μάλιστα τοὺς νεωτέρους ἔσω τῆς σκηνῆς ἐπισπασάμενος πολὺν χρόνον ἦν πρὸς αὑτῷ σιωπῇ καθήμενος, ὥστε θαυμάζειν ἅπαντας. ὁρμήσας δὲ περὶ τῆς τύχης καὶ τῶν ἀνθρωπίνων διαλέγεσθαι πραγμάτων, ἆρά γε, εἶπεν, ἄξιον εὐπραγίας παρούσης ἄνθρωπον ὄντα θρασύνεσθαι καὶ μέγα φρονεῖν ἔθνος ἢ πόλιν ἢ βασιλείαν καταστρεψάμενον, ἢ τὴν μεταβολὴν ταύτην τῆς τύχης, ἡ παράδειγμα τῷ πολεμοῦντι κοινῆς ἀσθενείας προθεῖσα παιδεύει μηδὲν ὡς μόνιμον καὶ βέβαιον διανοεῖσθαι; ποῖος γὰρ ἀνθρώποις τοῦ θαρρεῖν καιρός, ὅταν τὸ κρατεῖν ἑτέρων μάλιστα δεδοικέναι τὴν τύχην ἀναγκάζῃ, καὶ τῷ χαίροντι δυσθυμίαν ἐπάγῃ τοσαύτην ὁ τῆς περιφερομένης καὶ προσισταμένης ἄλλοτ’ ἄλλοις εἱμαρμένης λογισμός; ἢ τὴν Ἀλεξάνδρου διαδοχήν, ὃς ἐπὶ πλεῖστον ἤρθη δυνάμεως καὶ μέγιστον ἔσχε κράτος, ὥρας μιᾶς μορίῳ πεσοῦσαν ὑπὸ πόδας θέμενοι, καὶ τοὺς ἄρτι μυριάσι πεζῶν καὶ χιλιάσιν ἱππέων τοσαύταις ὁπλοφορουμένους βασιλεῖς ὁρῶντες ἐκ τῶν πολεμίων χειρῶν ἐφήμερα σιτία καὶ ποτὰ λαμβάνοντας, οἴεσθε τὰ καθ’ ἡμᾶς ἔχειν τινὰ βεβαιότητα τύχης διαρκῆ πρὸς τὸν χρόνον; οὐ καταβαλόντες ὑμεῖς οἱ νέοι τὸ κενὸν φρύαγμα τοῦτο καὶ γαυρίαμα τῆς νίκης ταπεινοὶ καταπτήξετε πρὸς τὸ μέλλον, ἀεὶ καραδοκοῦντες εἰς ὅ τι κατασκήψει τέλος ἑκάστῳ τὴν τῆς παρούσης εὐπραγίας ὁ δαίμων νέμεσιν; τοιαῦτά φασι πολλὰ διαλεχθέντα τὸν Αἰμίλιον ἀποπέμψαι τοὺς νέους εὖ μάλα τὸ καύχημα καὶ τὴν ὕβριν, ὥσπερ χαλινῷ, τῷ λόγῳ κόπτοντι κεκολασμένους.", "st": "Aem. 27.1"}, {"sp": "N", "t": "ἐκ τούτου τὴν μὲν στρατιὰν πρὸς ἀνάπαυσιν, αὑτὸν δὲ πρὸς θέαν τῆς Ἑλλάδος ἔτρεψε καὶ διαγωγὴν ἔνδοξον ἅμα καὶ φιλάνθρωπον. ἐπιὼν γὰρ ἀνελάμβανε τοὺς δήμους καὶ τὰ πολιτεύματα καθίστατο, καὶ δωρεὰς ἐδίδου, ταῖς μὲν σῖτον ἐκ τοῦ βασιλικοῦ, ταῖς δ’ ἔλαιον. τοσοῦτον γὰρ εὑρεθῆναί φασιν ἀποκείμενον ὥστε τοὺς λαμβάνοντας καὶ δεομένους ἐπιλιπεῖν πρότερον ἢ καταναλωθῆναι τὸ πλῆθος τῶν εὑρεθέντων. ἐν δὲ Δελφοῖς ἰδὼν κίονα μέγαν τετράγωνον ἐκ λίθων λευκῶν συνηρμοσμένον, ἐφ’ οὗ Περσέως ἔμελλε χρυσοῦς ἀνδριὰς τίθεσθαι, προσέταξε τὸν αὐτοῦ τεθῆναι· τοὺς γὰρ ἡττημένους τοῖς νικῶσιν ἐξίστασθαι χώρας προσήκειν. ἐν δ’ Ὀλυμπίᾳ, τοῦτο δὴ τὸ πολυθρύλητον ἐκεῖνόν ἀναφθέγξασθαί φασιν, ὡς τὸν Ὁμήρου Δία Φειδίας ἀποπλάσαιτο. τῶν δὲ δέκα πρέσβεων ἐκ Ῥώμης ἀφικομένων Μακεδόσι μὲν ἀπέδωκε τὴν χώραν καὶ τὰς πόλεις ἐλευθέρας οἰκεῖν καὶ αὐτονόμους, ἑκατὸν δὲ τάλαντα Ῥωμαίοις ὑποτελεῖν, οὗ πλέον ἢ διπλάσιον τοῖς βασιλεῦσιν εἰσέφερον. θέας δὲ παντοδαπῶν ἀγώνων καὶ θυσίας ἐπιτελῶν τοῖς θεοῖς ἑστιάσεις καὶ δεῖπνα προὔθετο, χορηγίᾳ μὲν ἐκ τῶν βασιλικῶν ἀφθόνῳ χρώμενος, τάξιν δὲ καὶ κόσμον καὶ κατακλίσεις καὶ δεξιώσεις καὶ τὴν πρὸς ἕκαστον αὑτοῦ τῆς κατ’ ἀξίαν τιμῆς καὶ φιλοφροσύνης αἴσθησιν οὕτως ἀκριβῆ καὶ πεφροντισμένην ἐνδεικνύμενος ὥστε θαυμάζειν τοὺς Ἕλληνας, εἰ μηδὲ τὴν παιδιὰν ἄμοιρον ἀπολείπει σπουδῆς, ἀλλὰ τηλικαῦτα πράττων ἀνὴρ πράγματα καὶ τοῖς μικροῖς τὸ πρέπον ἀποδίδωσιν. ὁ δὲ καὶ τούτοις ἔχαιρεν, ὅτι πολλῶν παρεσκευασμένων καὶ λαμπρῶν τὸ ἥδιστον αὐτὸς ἦν ἀπόλαυσμα καὶ θέαμα τοῖς παροῦσι, καὶ πρὸς τοὺς θαυμάζοντας τὴν ἐπιμέλειαν ἔλεγε τῆς αὐτῆς εἶναι ψυχῆς παρατάξεώς τε προστῆναι καλῶς καὶ συμποσίου, τῆς μὲν, ὅπως φοβερωτάτη τοῖς πολεμίοις, τοῦ δ’, ὡς εὐχαριστότατον ᾖ τοῖς συνοῦσιν. οὐδενὸς δ’ ἧττον αὐτοῦ τὴν ἐλευθεριότητα καὶ τὴν μεγαλοψυχίαν ἐπῄνουν οἱ ἄνθρωποι, πολὺ μὲν ἀργύριον, πολὺ δὲ χρυσίον ἐκ τῶν βασιλικῶν ἠθροισμένον οὐδ’ ἰδεῖν ἐθελήσαντος, ἀλλὰ τοῖς ταμίαις εἰς τὸ δημόσιον παραδόντος. μόνα τὰ βιβλία τοῦ βασιλέως φιλογραμματοῦσι τοῖς υἱέσιν ἐπέτρεψεν ἐξελέσθαι, καὶ διανέμων ἀριστεῖα τῆς μάχης Αἰλίῳ Τουβέρωνι τῷ γαμβρῷ φιάλην ἔδωκε πέντε λιτρῶν ὁλκήν. οὗτός ἐστι Τουβέρων ὃν ἔφαμεν μετὰ συγγενῶν οἰκεῖν ἑκκαιδέκατον, ἀπὸ γηδίου μικροῦ διατρεφομένων ἁπάντων. καὶ πρῶτον ἄργυρον ἐκεῖνόν φασιν εἰς τὸν Αἰλίων οἶκον εἰσελθεῖν, ὑπ’ ἀρετῆς καὶ τιμῆς εἰσαγόμενον, τὸν δ’ ἄλλον χρόνον οὔτ’ αὐτοὺς οὔτε τὰς γυναῖκας ἀργυρίου χρῄζειν ἢ χρυσοῦ.", "st": "Aem. 28.1"}, {"sp": "N", "t": "διῳκημένων δὲ πάντων αὐτῷ καλῶς ἀσπασάμενος τοὺς Ἕλληνας, καὶ παρακαλέσας τοὺς Μακεδόνας μεμνῆσθαι τῆς δεδομένης ὑπὸ Ῥωμαίων ἐλευθερίας σῴζοντας αὐτὴν δι’ εὐνομίας καὶ ὁμονοίας, ἀνέζευξεν ἐπὶ τὴν Ἤπειρον, ἔχων δόγμα συγκλήτου τοὺς συμμεμαχημένους αὐτῷ τὴν πρὸς Περσέα μάχην στρατιώτας ἀπὸ τῶν ἐκεῖ πόλεων ὠφελῆσαι. βουλόμενος δὲ πᾶσιν ἅμα καὶ μηδενὸς προσδοκῶντος, ἀλλ’ ἐξαίφνης ἐπιπεσεῖν, μετεπέμψατο τοὺς πρώτους ἐξ ἑκάστης πόλεως ἄνδρας δέκα, καὶ προσέταξεν αὐτοῖς, ὅσος ἄργυρός ἐστι καὶ χρυσὸς ἐν οἰκίαις καὶ ἱεροῖς, ἡμέρᾳ ῥητῇ καταφέρειν. ἑκάστοις δὲ συνέπεμψεν ὡς ἐπ’ αὐτὸ δὴ τοῦτο φρουρὰν στρατιωτῶν καὶ ταξίαρχον προσποιούμενον ζητεῖν καὶ παραλαμβάνειν τὸ χρυσίον. ἐνστάσης δὲ τῆς ἡμέρας, ὑφ’ ἕνα καὶ τὸν αὐτὸν ἅμα καιρὸν ὁρμήσαντες ἐτράποντο πρὸς καταδρομὴν καὶ διαρπαγὴν τῶν πόλεων, ὥστε ὥρᾳ μιᾷ πεντεκαίδεκα ἀνθρώπων ἐξανδραποδισθῆναι μυριάδας, ἑβδομήκοντα δὲ πόλεις πορθηθῆναι, γενέσθαι δ’ ἀπὸ τοσαύτης φθορᾶς καὶ πανωλεθρίας ἑκάστῳ στρατιώτῃ τὴν δόσιν οὐ μείζον’ ἕνδεκα δραχμῶν, φρῖξαι δὲ πάντας ἀνθρώπους τὸ τοῦ πολέμου τέλος, εἰς μικρὸν οὕτω τὸ καθ’ ἕκαστον λῆμμα καὶ κέρδος ἔθνους ὅλου κατακερματισθέντος.", "st": "Aem. 29.1"}, {"sp": "N", "t": "Αἰμίλιος μὲν οὖν τοῦτο πράξας μάλιστα παρὰ τὴν αὑτοῦ φύσιν ἐπιεικῆ καὶ χρηστὴν οὖσαν εἰς Ὠρικὸν κατέβη· κἀκεῖθεν εἰς Ἰταλίαν μετὰ τῶν δυνάμεων περαιωθείς ἀνέπλει τὸν Θύβριν ποταμὸν ἐπὶ τῆς βασιλικῆς ἑκκαιδεκήρους κατεσκευασμένης εἰς κόσμον ὅπλοις αἰχμαλώτοις καὶ φοινικίσι καὶ πορφύραις, ὡς καὶ πανηγυρίζειν ἔξωθεν καθάπερ εἰς τινὰ θριαμβικῆς θέαν πομπῆς καὶ προαπολαύειν τοὺς Ῥωμαίους, τῷ ῥοθίῳ σχέδην ὑπάγοντι τὴν ναῦν ἀντιπαρεξάγοντας.", "st": "Aem. 30.1"}, {"sp": "N", "t": "οἱ δὲ στρατιῶται τοῖς βασιλικοῖς χρήμασιν ἐποφθαλμίσαντες, ὡς οὐχ ὅσων ἠξίουν ἔτυχον, ὠργίζοντο μὲν ἀδήλως διὰ τοῦτο καὶ χαλεπῶς εἶχον πρὸς τὸν Αἰμίλιον, αἰτιώμενοι δὲ φανερῶς ὅτι βαρὺς γένοιτο καὶ δεσποτικὸς αὐτοῖς ἄρχων, οὐ πάνυ προθύμως ἐπὶ τὴν ὑπὲρ τοῦ θριάμβου σπουδὴν ἀπήντησαν. αἰσθόμενος δὲ τοῦτο Σέρβιος Γάλβας, ἐχθρὸς Αἰμιλίου, γεγονὼς δὲ τῶν ὑπ’ αὐτὸν χιλιάρχων, ἐθάρρησεν ἀναφανδὸν εἰπεῖν ὡς οὐ δοτέον εἴη τὸν θρίαμβον. ἐνεὶς δὲ πολλὰς τῷ στρατιωτικῷ πλήθει διαβολὰς κατὰ τοῦ στρατηγοῦ καὶ τὴν οὖσαν ὀργὴν ἔτι μᾶλλον ἐξερεθίσας ᾐτεῖτο παρὰ τῶν δημάρχων ἄλλην ἡμέραν ἐκείνην γὰρ οὐκ ἐξαρκεῖν τῇ κατηγορίᾳ, τέσσαρας ἔτι λοιπὰς ὥρας ἔχουσαν. τῶν δὲ δημάρχων λέγειν αὐτὸν, εἴ τι βούλεται, κελευόντων, ἀρξάμενος μακρῷ καὶ βλασφημίας ἔχοντι παντοδαπὰς χρῆσθαι λόγῳ τὸν χρόνον ἀνήλωσε τῆς ἡμέρας· καὶ γενομένου σκότους οἱ μὲν δήμαρχοι τὴν ἐκκλησίαν ἀφῆκαν, πρὸς δὲ τὸν Γάλβαν οἱ στρατιῶται συνέδραμον θρασύτεροι γεγονότες, καὶ συγκροτήσαντες αὑτοὺς περὶ τὸν ὄρθρον αὖθις καταλαμβάνονται τὸ Καπετώλιον ἐκεῖ γὰρ οἱ δήμαρχοι τὴν ἐκκλησίαν ἔμελλον ἄξειν.", "st": "Aem. 30.4"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ τῆς ψήφου δοθείσης ἥ τε πρώτη φυλὴ τὸν θρίαμβον ἀπεψηφίζετο, καὶ τοῦ πράγματος αἴσθησις εἰς τὸν ἄλλον δῆμον καὶ τὴν σύγκλητον κατῄει. καὶ τὸ μὲν πλῆθος ὑπεραλγοῦν τῷ προπηλακίζεσθαι τὸν Αἰμίλιον ἐν φωναῖς ἦν ἀπράκτοις, οἱ δὲ γνωριμώτατοι τῶν ἀπὸ βουλῆς δεινὸν εἶναι τὸ γινόμενον βοῶντες ἀλλήλους παρεκάλουν ἐπιλαβέσθαι τῆς τῶν στρατιωτῶν ἀσελγείας καὶ θρασύτητος, ἐπὶ πᾶν ἀφιξομένης ἄνομον ἔργον καὶ βίαιον, εἰ μηδὲν ἐμποδὼν αὐτοῖς γένοιτο Παῦλον Αἰμίλιον ἀφελέσθαι τῶν ἐπινικίων τιμῶν, ὠσάμενοι δὲ τὸν ὄχλον καὶ ἀναβάντες ἁθρόοι τοῖς δημάρχοις ἔλεγον ἐπισχεῖν τὴν ψηφοφορίαν, ἄχρι ἂν διαέλθωσιν ἃ βούλονται πρὸς τὸ πλῆθος. ἐπισχόντων δὲ πάντων καὶ γενομένης σιωπῆς ἀνελθὼν ἀνὴρ ὑπατικὸς καὶ πολεμίους εἴκοσι καὶ τρεῖς ἐκ προκλήσεως ἀνῃρηκώς, Μᾶρκος Σερβίλιος, Αἰμίλιον μὲν ἔφη Παῦλον, ἡλίκος αὐτοκράτωρ γένοιτο, νῦν μάλιστα γινώσκειν, ὁρῶν ὅσης ἀπειθείας γέμοντι καὶ κακίας στρατεύματι χρώμενος οὕτω καλὰς κατώρθωσε καὶ μεγάλας πράξεις, θαυμάζειν δὲ τὸν δῆμον εἰ τοῖς ἀπ’ Ἰλλυριῶν καὶ Λιγύων ἀγαλλόμενος θριάμβοις αὑτῷ φθονεῖ τὸν Μακεδόνων βασιλέα ζῶντα καὶ τὴν Ἀλεξάνδρου καὶ Φιλίππου δόξαν ἐπιδεῖν ὑπὸ τοῖς Ῥωμαίων ὅπλοις ἀγομένην αἰχμάλωτον. πῶς γὰρ οὐ δεινὸν, εἶπεν, εἰ, φήμης περὶ νίκης ἀβεβαίου πρότερον εἰς τὴν πόλιν ἐμπεσούσης, ἐθύσατε τοῖς θεοῖς εὐχόμενοι τοῦ λόγου τούτου ταχέως ἀπολαβεῖν τὴν ὄψιν, ἥκοντος δὲ τοῦ στρατηγοῦ μετὰ τῆς ἀληθινῆς νίκης ἀφαιρεῖσθε τῶν μὲν θεῶν τὴν τιμήν, αὑτῶν δὲ τὴν χαράν, ὡς φοβούμενοι θεάσασθαι τὸ μέγεθος τῶν κατορθωμάτων ἢ φειδόμενοι τοῦ πολεμίου; καίτοι κρεῖττον ἦν τῷ πρὸς ἐκεῖνον ἐλέῳ, μὴ τῷ πρὸς αὐτοκράτορα φθόνῳ λυθῆναι τὸν θρίαμβον. ἀλλ’ εἰς τοσαύτην, ἔφη, τὸ κακόηθες ἐξουσίαν προάγεται δι’ ὑμῶν ὥστε περὶ στρατηγίας καὶ θριάμβου τολμᾷ λέγειν ἄνθρωπος ἄτρωτος καὶ τῷ σώματι στίλβων ὑπὸ λειότητος καὶ σκιατραφίας πρὸς ἡμᾶς τοὺς τοσούτοις τραύμασι πεπαιδευμένους ἀρετὰς καὶ κακίας κρίνειν στρατηγῶν. ἅμα δὲ τῆς ἐσθῆτος διασχών ἐξέφηνε κατὰ τῶν στέρνων ὠτειλὰς ἀπίστους τὸ πλῆθος. εἶτα μεταστραφεὶς ἔνια τῶν οὐκ εὐπρεπῶς ἐν ὄχλῳ γυμνοῦσθαι δοκούντων τοῦ σώματος ἀνεκάλυψε, καὶ πρὸς τὸν Γάλβαν ἐπιστρέψας, σὺ μὲν, ἔφη, γελᾷς ἐπὶ τούτοις, ἐγὼ δὲ σεμνύνομαι πρὸς τοὺς πολίτας· ὑπὲρ τούτων γὰρ ἡμέραν καὶ νύκτα συνεχῶς ἱππασάμενος ταῦτ’ ἔσχον. ἀλλ’ ἄγε λαβὼν αὐτοὺς ἐπὶ τὴν ψῆφον ἐγὼ δὲ καταβὰς παρακολουθήσω πᾶσι, καὶ γνώσομαι τοὺς κακοὺς καὶ ἀχαρίστους καὶ δημαγωγεῖσθαι μᾶλλον ἐν τοῖς πολέμοις ἢ στρατηγεῖσθαι βουλομένους.", "st": "Aem. 31.1"}, {"sp": "N", "t": "οὕτω φασὶν ὑπὸ τῶν λόγων τούτων ἀνακοπῆναι καὶ μεταβαλεῖν τὸ στρατιωτικόν ὥστε πάσαις ταῖς φυλαῖς ἐπικυρωθῆναι τῷ Αἰμιλίῳ τὸν θρίαμβον. πεμφθῆναι δ’ αὐτὸν οὕτω λέγουσιν. ὁ μὲν δῆμος ἔν τε τοῖς ἱππικοῖς θεάτροις, ἃ κίρκους καλοῦσι, περί τε τήν ἀγορὰν ἰκρία πηξάμενοι, καὶ τἆλλα τῆς πόλεως μέρη καταλαβόντες, ὡς ἕκαστα παρεῖχε τῆς πομπῆς ἔποψιν, ἐθεῶντο καθαραῖς ἐσθῆσι κεκοσμημένοι. πᾶς δὲ ναὸς ἀνέῳκτο καὶ στεφάνων καὶ θυμιαμάτων ἦν πλήρης, ὑπηρέται τε πολλοὶ καὶ ῥαβδονόμοι τοὺς ἀτάκτως συρρέοντας εἰς τὸ μέσον καὶ διαθέοντας ἐξείργοντες ἀναπεπταμένας τὰς ὁδοὺς καὶ καθαρὰς παρεῖχον. τῆς δὲ πομπῆς εἰς ἡμέρας τρεῖς νενεμημένης, ἡ μὲν πρώτη μόλις ἐξαρκέσασα τοῖς αἰχμαλώτοις ἀνδριάσι καὶ γραφαῖς καὶ κολοσσοῖς ἐπὶ ζευγῶν πεντήκοντα καὶ διακοσίων κομιζομένοις τούτων ἔσχε θέαν. τῇ δ’ ὑστεραίᾳ τὰ κάλλιστα καὶ πολυτελέστατα τῶν Μακεδονικῶν ὅπλων ἐπέμπετο πολλαῖς ἁμάξαις, αὐτά τε μαρμαίροντα χαλκῷ νεοσμήκτῳ καὶ σιδήρῳ, τήν τε θέσιν ἐκ τέχνης καὶ συναρμογῆς ὡς ἂν μάλιστα συμπεφορημένοις χύδην καὶ αὐτομάτως ἐοίκοι πεποιημένα, κράνη πρὸς ἀσπίσι καὶ θώρακες ἐπὶ κνημῖσι, καὶ Κρητικαὶ πέλται καὶ Θρᾴκια γέρρα καὶ φαρέτραι μετὰ ἱππικῶν ἀναμεμιγμέναι χαλινῶν, καὶ ξίφη γυμνὰ διὰ τούτων παρανίσχοντα καὶ σάρισαι παραπεπηγυῖαι, σύμμετρον ἐχόντων χάλασμα τῶν ὅπλων, ὥστε τήν πρὸς ἄλληλα κροῦσιν ἐν τῷ διαφέρεσθαι τραχὺ καὶ φοβερὸν ὑπηχεῖν, καὶ μηδὲ νενικημένων ἄφοβον εἶναι τήν ὄψιν. μετὰ δὲ τὰς ὁπλοφόρους ἁμάξας ἄνδρες ἐπεπορεύοντο τρισχίλιοι νόμισμα φέροντες ἀργυροῦν ἐν ἀγγείοις ἑπτακοσίοις πεντήκοντα τριταλάντοις, ὧν ἕκαστον ἀνὰ τέσσαρες ἐκόμιζον· ἄλλοι δὲ κρατῆρας ἀργυροῦς καὶ κέρατα καὶ φιάλας καὶ κύλικας, εὖ διακεκοσμημένα πρὸς θέαν ἕκαστα καὶ περιττὰ τῷ μεγέθει καὶ τῇ παχύτητι τῆς τορείας.", "st": "Aem. 32.1"}, {"sp": "N", "t": "τῆς δὲ τρίτης ἡμέρας ἕωθεν μὲν εὐθὺς ἐπορεύοντο σαλπιγκταί μέλος οὐ προσόδιον καὶ πομπικόν, ἀλλ’ οἵῳ μαχομένους ἐποτρύνουσιν αὑτοὺς Ῥωμαῖοι, προσεγκελευόμενοι. μετὰ δὲ τούτους ἤγοντο χρυσόκερῳ τροφίαι βοῦς ἑκατὸν εἴκοσι, μίτραις ἠσκημένοι καὶ στέμμασιν. οἱ δ’ ἄγοντες αὑτοὺς νεανίσκοι περιζώμασιν εὐπαρύφοις ἐσταλμένοι πρὸς ἱερουργίαν ἐχώρουν, καὶ παῖδες ἀργυρᾶ λοιβεῖα καὶ χρυσᾶ κομίζοντες. εἶτα μετὰ τούτους οἱ τὸ χρυσοῦν νόμισμα φέροντες, εἰς ἀγγεῖα τριταλαντιαῖα μεμερισμένον ὁμοίως τῷ ἀργυρίῳ. τὸ δὲ πλῆθος ἦν τῶν ἀγγείων ὀγδοήκοντα τριῶν δέοντα. τούτοις ἐπέβαλλον οἵ τε τὴν ἱερὰν φιάλην ἀνέχοντες, ἦν ὁ Αἰμίλιος ἐκ χρυσοῦ δέκα ταλάντων διὰ λίθων κατεσκεύασεν, οἵ τε τὰς Ἀντιγονίδας καὶ Σελευκίδας καὶ Θηρικλείους καὶ ὅσα περὶ δεῖπνον χρυσώματα τοῦ Περσέως ἐπιδεικνύμενοι. τούτοις ἐπέβαλλε τὸ ἅρμα τοῦ Περσέως καὶ τὰ ὅπλα καὶ τὸ διάδημα τοῖς ὅπλοις ἐπικείμενον. εἶτα μικροῦ διαλείμματος ὄντος ἤδη τὰ τέκνα τοῦ βασιλέως ἤγετο δοῦλα, καὶ σὺν αὐτοῖς τροφέων καὶ διδασκάλων καὶ παιδαγωγῶν δεδακρυμένων ὄχλος, αὐτῶν τε τὰς χεῖρας ὀρεγόντων εἰς τοὺς θεατάς καὶ τὰ παιδία δεῖσθαι καὶ λιτανεύειν διδασκόντων. ἦν δ’ ἄρρενα μὲν δύο, θῆλυ δὲ ἕν, οὐ πάνυ συμφρονοῦντα τῶν κακῶν τὸ μέγεθος διὰ τὴν ἡλικίαν· ᾗ καὶ μᾶλλον ἐλεεινὰ πρὸς τὴν μεταβολὴν τῆς ἀναισθησίας ἦν, ὥστε μικροῦ τὸν Περσέα βαδίζειν παρορώμενον· οὕτως ὑπ’ οἴκτου τοῖς νηπίοις προσεῖχον τὰς ὄψεις οἱ Ῥωμαῖοι, καὶ δάκρυα πολλοῖς ἐκβάλλειν συνέβη, πᾶσι δὲ μεμιγμένην ἀλγηδόνι καὶ χάριτι τὴν θέαν εἶναι μέχρι οὗ τὰ παιδία παρῆλθεν.", "st": "Aem. 33.1"}, {"sp": "N", "t": "αὐτὸς δὲ τῶν τέκνων ὁ Περσεὺς καὶ τῆς περὶ αὐτὰ θεραπείας κατόπιν ἐπορεύετο, φαιὸν μὲν ἱμάτιον ἀμπεχόμενος καὶ κρηπῖδας ἔχων ἐπιχωρίους, ὑπὸ δὲ μεγέθους τῶν κακῶν πάντα θαμβοῦντι καὶ παραπεπληγμένῳ μάλιστα τὸν λογισμὸν ἐοικώς. καὶ τούτῳ δ’ εἵπετο χορὸς φίλων καὶ συνήθων, βεβαρημένων τὰ πρόσωπα πένθει, καὶ τῷ πρὸς Περσέα βλέπειν ἀεὶ καὶ δακρύειν ἔννοιαν παριστάντων τοῖς θεωμένοις ὅτι τὴν ἐκείνου τύχην ὀλοφύρονται τῶν καθ’ ἑαυτοὺς ἐλάχιστα φροντίζοντες. καίτοι προσέπεμψε τῷ Αἰμιλίῳ δεόμενος μὴ πομπευθῆναι καὶ παραιτούμενος τὸν θρίαμβον. ὁ δὲ τῆς ἀνανδρίας αὑτοῦ καὶ φιλοψυχίας, ὡς ἔοικε, καταγελῶν, ἀλλὰ τοῦτό γ’, εἶπε, καὶ πρότερον ἦν ἐπ’ αὐτῷ καὶ νῦν ἐστιν, ἂν βούληται· δηλῶν τὸν πρὸ αἰσχύνης θάνατον, ὃν οὐχ ὑπομείνας ὁ δείλαιος, ἀλλ’ ὑπ’ ἐλπίδων τινῶν ἀπομαλακισθείς ἐγεγόνει μέρος τῶν αὑτοῦ λαφύρων.", "st": "Aem. 34.1"}, {"sp": "N", "t": "ἐφεξῆς δὲ τούτοις ἐκομίζοντο χρυσοῖ στέφανοι τετρακόσιοι τὸ πλῆθος, οὓς αἱ πόλεις ἀριστεῖα τῆς νίκης τῷ Αἰμιλίῳ μετὰ πρεσβειῶν ἔπεμψαν. εἶτ’ αὐτὸς ἐπέβαλλεν ἅρματι κεκοσμημένῳ διαπρεπῶς ἐπιβεβηκώς, ἀνὴρ καὶ δίχα τοσαύτης ἐξουσίας ἀξιοθέατος, ἁλουργίδα χρυσόπαστον ἀμπεχόμενος καὶ δάφνης κλῶνα τῇ δεξιᾷ προτείνων. ἐδαφνηφόρει δὲ καὶ σύμπας ὁ στρατός, τῷ μὲν ἅρματι τοῦ στρατηγοῦ κατὰ λόχους καὶ τάξεις ἑπόμενος, ᾄδων δὲ τὰ μὲν ᾠδάς τινας πατρίους ἀναμεμιγμένας γέλωτι, τὰ δὲ παιᾶνας ἐπινικίους καὶ τῶν διαπεπραγμένων ἐπαίνους εἰς τὸν Αἰμίλιον περίβλεπτον ὄντα καὶ ζηλωτὸν ὑπὸ πάντων, οὐδενὶ δὲ τῶν ἀγαθῶν ἐπίφθονον· πλὴν εἴ τι δαιμόνιον ἄρα τῶν μεγάλων καὶ ὑπερόγκων εἴληχεν εὐτυχιῶν ἀπαρύτειν καὶ μιγνύναι τὸν ἀνθρώπινον βίον, ὅπως μηδενὶ κακῶν ἄκρατος εἴη καὶ καθαρός, ἀλλὰ καθ’ Ὅμηρον ἄριστα δοκῶσι πράττειν οἷς αἱ τύχαι τροπὴν ἐπ’ ἀμφότερα τῶν πραγμάτων ἔχουσιν.", "st": "Aem. 34.5"}, {"sp": "N", "t": "ἦσαν γὰρ αὐτῷ τέσσαρες υἱοί, δύο μὲν εἰς ἑτέρας ἀπῳκισμένοι συγγενείας, ὡς ἤδη λέλεκται, Σκηπίων καὶ Φάβιος, δύο δὲ παῖδες ἔτι τὴν ἡλικίαν, οὓς ἐπὶ τῆς οἰκίας εἶχε τῆς ἑαυτοῦ γεγονότας ἐξ ἑτέρας γυναικός, ὧν ὁ μὲν ἡμέραις πέντε πρὸ τοῦ θριαμβεύειν τὸν Αἰμίλιον ἐτελεύτησε τεσσαρεσκαιδεκέτης, ὁ δὲ δωδεκέτης μετὰ τρεῖς ἡμέρας θριαμβεύσαντος ἐπαπέθανεν, ὥστε μηδένα γενέσθαι Ῥωμαίων τοῦ πάθους ἀνάλγητον, ἀλλὰ φρῖξαι τὴν ὠμότητα τῆς τύχης ἅπαντας, ὡς οὐκ ᾐδέσατο πένθος τοσοῦτον εἰς οἰκίαν ζήλου καὶ χαρᾶς καὶ θυσιῶν γέμουσαν εἰσάγουσα, καὶ καταμιγνύουσα θρήνους καὶ δάκρυα παιᾶσιν ἐπινικίοις καὶ θριάμβοις.", "st": "Aem. 35.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὁ Αἰμίλιος ὀρθῶς λογιζόμενος ἀνδρείας καὶ θαρραλεότητος ἀνθρώποις οὐ πρὸς ὅπλα καὶ σαρίσας χρῆσιν εἶναι μόνον, ἀλλὰ πρὸς πᾶσαν ὁμαλῶς τύχης ἀντίστασιν, οὕτως ἡρμόσατο καὶ κατεκόσμησε τὴν τῶν παρόντων σύγκρασιν ὥστε τοῖς ἀγαθοῖς τὰ φαῦλα καὶ τὰ οἰκεῖα τοῖς δημοσίοις ἐναφανισθέντα μὴ ταπεινῶσαι τὸ μέγεθος μηδὲ καθυβρίσαι τὸ ἀξίωμα τῆς νίκης, τὸν μέν γε πρότερον τῶν παίδων ἀποθανόντα θάψας εὐθὺς ἐθριάμβευσεν, ὡς λέλεκται· τοῦ δὲ δευτέρου μετὰ τὸν θρίαμβον τελευτήσαντος συναγαγὼν εἰς ἐκκλησίαν τὸν Ῥωμαίων δῆμον ἐχρήσατο λόγοις ἀνδρὸς οὐ δεομένου παραμυθίας, ἀλλὰ παραμυθουμένου τοὺς πολίτας δυσπαθοῦντας ἐφ’ οἷς ἐκεῖνος ἐδυστύχησεν. ἔφη γάρ ὅτι τῶν ἀνθρωπίνων οὐδὲν οὐδέποτε δείσας, τῶν δὲ θείων ὡς ἀπιστότατον καὶ ποικιλώτατον πρᾶγμα τὴν τύχην ἀεὶ φοβηθείς, μάλιστα περὶ τοῦτον αὐτῆς τὸν πόλεμον, ὥσπερ πνεύματος λαμπροῦ, ταῖς πράξεσι παρούσης, διατελοίη μεταβολήν τινα καὶ παλίρροιαν προσδεχόμενος. μιᾷ μὲν γὰρ, εἶπεν, ἡμέρᾳ τὸν Ἰόνιον ἀπὸ Βρεντεσίου περάσας εἰς Κέρκυραν κατήχθην πεμπταῖος δ’ ἐκεῖθεν ἐν Δελφοῖς τῷ θεῷ θύσας, ἑτέραις αὖθις αὖ πέντε τὴν δύναμιν ἐν Μακεδονίᾳ παρέλαβον, καὶ τὸν εἰωθότα συντελέσας καθαρμὸν αὐτῆς καὶ τῶν πράξεων εὐθὺς ἐναρξάμενος ἐν ἡμέραις ἄλλαις πεντεκαίδεκα τὸ κάλλιστον ἐπέθηκα τῷ πολέμῳ τέλος. ἀπιστῶν δὲ τῇ Τύχῃ διὰ τὴν εὔροιαν τῶν πραγμάτων, ὡς ἄδεια πολλὴ καὶ κίνδυνος οὐδεὶς ἦν ἀπὸ τῶν πολεμίων, μάλιστα κατὰ πλοῦν ἐδεδίειν τὴν μεταβολὴν τοῦ δαίμονος ἐπ’ εὐτυχίᾳ, τοσοῦτον στρατὸν νενικηκότα καὶ λάφυρα καὶ βασιλεῖς αἰχμαλώτους κομίζων. οὐ μὴν ἀλλὰ καὶ σωθεὶς πρὸς ὑμᾶς καὶ τὴν πόλιν ὁρῶν εὐφροσύνης καὶ ζήλου καὶ θυσιῶν γέμουσαν, ἔτι τὴν Τύχην δι’ ὑποψίας εἶχον, εἰδὼς οὐδὲν εἰλικρινὲς οὐδ’ ἀνεμέσητον ἀνθρώποις τῶν μεγάλων χαριζομένην. καὶ τοῦτον οὐ πρότερον ἡ ψυχὴ τὸν φόβον ὠδίνουσα καὶ περισκοπουμένη τό μέλλον ὑπὲρ τῆς πόλεως ἀφῆκεν ἢ τηλικαύτῃ με προσπταῖσαι δυστυχίᾳ περὶ τὸν οἶκον, υἱῶν ἀρίστων, οὓς ἐμαυτῷ μόνους ἐλιπόμην διαδόχους, ταφὰς ἐπαλλήλους ἐν ἡμέραις ἱεραῖς μεταχειρισάμενον. νῦν οὖν ἀκίνδυνός εἰμι τὰ μέγιστα καὶ θαρρῶ, καὶ νομίζω τὴν Τύχην ὑμῖν παραμενεῖν ἀβλαβῆ καὶ βέβαιον. ἱκανῶς γὰρ ἐμοὶ καὶ τοῖς ἐμοῖς κακοῖς εἰς τὴν τῶν κατωρθωμένων ἀποκέχρηται νέμεσιν, οὐκ ἀφανέστερον ἔχουσα παράδειγμα τῆς ἀνθρωπίνης ἀσθενείας τοῦ θριαμβευομένου τὸν θριαμβεύοντα πλὴν ὅτι Περσεὺς μὲν ἔχει καὶ νενικημένος τοὺς παῖδας, Αἰμίλιος δὲ τοὺς αὑτοῦ νικήσας ἀπέβαλεν.", "st": "Aem. 36.1"}, {"sp": "N", "t": "οὕτω μὲν εὐγενεῖς καὶ μεγάλους λόγους τὸν Αἰμίλιον ἐξ ἀπλάστου καὶ ἀληθινοῦ φρονήματος ἐν τῷ δήμῳ διαλεχθῆναι λέγουσι. τῷ δὲ Περσεῖ, καίπερ οἰκτείρας τὴν μεταβολὴν καὶ μάλα βοηθῆσαι προθυμηθείς, οὐδὲν εὕρετο πλὴν μεταστάσεως ἐκ τοῦ καλουμένου κάρκερε παρ’ αὐτοῖς εἰς τόπον καθαρὸν καὶ φιλανθρωποτέραν δίαιταν, ὅπου φρουρούμενος, ὡς μὲν οἱ πλεῖστοι γεγράφασιν, ἀπεκαρτέρησεν, ἔνιοι δὲ τῆς τελευτῆς ἴδιόν τινα καὶ παρηλλαγμένον τρόπον ἱστοροῦσι. μεμψαμένους γάρ τι καὶ θυμωθέντας αὐτῷ τοὺς περὶ τὸ σῶμα στρατιώτας, ὡς ἕτερον οὐδὲν ἠδύναντο λυπεῖν καὶ κακοῦν αὐτόν, ἐξείργειν τῶν ὕπνων, καὶ προσέχοντας ἀκριβῶς ἐνίστασθαι ταῖς καταφοραῖς καὶ συνέχειν ἐγρηγορότα πάσῃ μηχανῇ, μέχρι οὗ τοῦτον τὸν τρόπον ἐκπονηθεὶς ἐτελεύτησεν. ἐτελεύτησε δὲ καὶ τῶν παιδίων τὰ δύο. τὸν δὲ τρίτον, Ἀλέξανδρον, εὐφυᾶ μὲν ἐν τῷ τορεύειν καὶ λεπτουργεῖν γενέσθαι φασίν, ἐκμαθόντα δὲ τὰ Ῥωμαϊκὰ γράμματα καὶ τὴν διάλεκτον ὑπογραμματεύειν τοῖς ἄρχουσιν, ἐπιδέξιον καὶ χαρίεντα περὶ ταύτην τὴν ὑπηρεσίαν ἐξεταζόμενον.", "st": "Aem. 37.1"}, {"sp": "N", "t": "ταῖς δὲ Μακεδονικαῖς πράξεσι τοῦ Αἰμιλίου δημοτικωτάτην προσγράφουσι χάριν ὑπὲρ τῶν πολλῶν, ὡς τοσούτων εἰς τὸ δημόσιον τότε χρημάτων ὑπ’ αὐτοῦ τεθέντων ὥστε μηκέτι δεῆσαι τὸν δῆμον εἰσενεγκεῖν ἄχρι τῶν Ἱρτίου καὶ Πάνσα χρόνων, οἳ περὶ τὸν πρῶτον Ἀντωνίου καὶ Καίσαρος πόλεμον ὑπάτευσαν. κἀκεῖνο δ’ ἴδιον καὶ περιττὸν τοῦ Αἰμιλίου, τὸ σπουδαζόμενον ὑπὸ τοῦ δήμου καὶ τιμώμενον διαφερόντως ἐπὶ τῆς ἀριστοκρατικῆς μεῖναι προαιρέσεως, καὶ μηδὲν εἰπεῖν μηδὲ πρᾶξαι χάριτι τῶν πολλῶν, ἀλλὰ τοῖς πρώτοις καὶ κρατίστοις ἀεὶ συνεξετάζεσθαι περὶ τὴν πολιτείαν. ὃ καὶ χρόνοις ὕστερον Ἄππιος ὠνείδισεν Ἀφρικανῷ Σκηπίωνι. μέγιστοι γὰρ ὄντες ἐν τῇ πόλει τότε τὴν τιμητικὴν ἀρχὴν μετῄεσαν, ὁ μὲν τὴν βουλὴν ἔχων καὶ τοὺς ἀρίστους περὶ αὑτόν· αὕτη γὰρ Ἀππίοις ἡ πολιτεία πάτριος· ὁ δὲ μέγας μὲν ὢν ἐφ’ ἑαυτοῦ, μεγάλῃ δ’ ἀεὶ τῇ παρὰ τοῦ δήμου χάριτι καὶ σπουδῇ κεχρημένος. ὡς οὖν ἐμβάλλοντος εἰς ἀγορὰν τοῦ Σκηπίωνος κατεῖδε παρὰ πλευρὰν ὁ Ἄππιος ἀνθρώπους ἀγεννεῖς καὶ δεδουλευκότας, ἀγοραίους δὲ καὶ δυναμένους ὄχλον συναγαγεῖν καὶ σπουδαρχίᾳ καὶ κραυγῇ πάντα πράγματα βιάσασθαι, μέγα βοήσας· ὦ Παῦλε, εἶπεν, Αἰμίλιε, στέναξον ὑπὸ γῆς αἰσθόμενος ὅτι σου τὸν υἱὸν Αἰμίλιος ὁ κῆρυξ καὶ Λικίννιος Φιλόνεικος ἐπὶ τιμητείαν κατάγουσιν. ἀλλὰ Σκηπίων μὲν αὔξων τὰ πλεῖστα τὸν δῆμον εὔνουν εἶχεν, Αἰμίλιος δέ, καίπερ ὢν ἀριστοκρατικὸς, οὐδὲν ἧττον ὑπὸ τῶν πολλῶν ἠγαπᾶτο τοῦ μάλιστα δημαγωγεῖν καὶ πρός χάριν ὁμιλεῖν τοῖς πολλοῖς δοκοῦντος. ἐδήλωσαν δὲ μετὰ τῶν ἄλλων καλῶν καὶ τιμητείας αὐτὸν ἀξιώσαντες, ἥτις ἐστὶν ἀρχὴ πασῶν ἱερωτάτη καὶ δυναμένη μέγα πρός τε τἆλλα καὶ πρός ἐξέτασιν βίων. ἐκβαλεῖν τε γὰρ ἔξεστι συγκλήτου τὸν ἀπρεπῶς ζῶντα τοῖς τιμηταῖς, καὶ προγράψαι τὸν ἄριστον, ἵππου τ’ ἀφαιρέσει τῶν νέων ἀτιμάσαι τὸν ἀκολασταίνοντα. καὶ τῶν οὐσιῶν οὗτοι τὰ τιμήματα καὶ τὰς ἀπογραφὰς ἐπισκοποῦσιν. ἀπεγράψαντο μὲν οὖν κατ’ αὐτὸν μυριάδες ἀνθρώπων τριάκοντα τρεῖς, ἔτι δ’ ἑπτακισχίλιοι τετρακόσιοι πεντήκοντα δύο, τῆς δὲ βουλῆς προέγραψε μὲν Μᾶρκον Αἰμίλιον Λέπιδον, ἤδη τετράκις καρπούμενον ταύτην τὴν προεδρίαν, ἐξέβαλε δὲ τρεῖς συγκλητικοὺς οὐ τῶν ἐπιφανῶν, καὶ περὶ τὴν τῶν ἱππέων ἐξέτασιν ὁμοίως ἐμετρίασεν αὐτός τε καὶ Μάρκιος Φίλιππος ὁ συνάρχων αὐτοῦ.", "st": "Aem. 38.1"}, {"sp": "N", "t": "διῳκημένων δὲ τῶν πλείστων καὶ μεγίστων ἐνόσησε νόσον ἐν ἀρχῇ μὲν ἐπισφαλῆ, χρόνῳ δὲ ἀκίνδυνον, ἐργώδη δὲ καὶ δυσαπάλλακτον γενομένην. ἐπεὶ δὲ πεισθεὶς ὑπὸ τῶν ἰατρῶν ἔπλευσεν εἰς Ἐλέαν τῆς Ἰταλίας καὶ διέτριβεν αὐτόθι πλείω χρόνον ἐν παραλίοις ἀγροῖς καὶ πολλὴν ἡσυχίαν ἔχουσιν, ἐπόθησαν αὐτὸν οἱ Ῥωμαῖοι, καὶ φωνὰς πολλάκις ἐν θεάτροις οἷον εὐχόμενοι καὶ σπεύδοντες ἰδεῖν ἀφῆκαν. οὔσης δέ τινος ἱερουργίας ἀναγκαίας, ἤδη δὲ καὶ δοκοῦντος ἱκανῶς ἔχειν αὐτῷ τοῦ σώματος, ἐπανῆλθεν εἰς Ῥώμην. κἀκείνην μὲν ἔθυσε μετὰ τῶν ἄλλων τὴν θυσίαν ἱερέων, ἐπιφανῶς τοῦ δήμου περικεχυμένου καὶ χαίροντος· τῇ δ’ ὑστεραίᾳ πάλιν ἔθυσεν αὐτὸς ὑπὲρ αὐτοῦ σωτήρια τοῖς θεοῖς, καὶ συμπερανθείσης, ὡς προείρηται, τῆς θυσίας ὑποστρέψας οἴκαδε καὶ κατακλιθείς, πρὶν αἰσθέσθαι καὶ νοῆσαι τὴν μεταβολήν, ἐν ἐκστάσει καὶ παραφορᾷ τῆς διανοίας γενόμενος τριταῖος ἐτελεύτησεν, οὐδενὸς ἐνδεὴς οὐδ’ ἀτελὴς τῶν πρὸς εὐδαιμονίαν νενομισμένων γενόμενος. καὶ γὰρ ἡ περὶ τὴν ἐκφορὰν πομπὴ θαυμασμὸν ἔσχε, καὶ ζῆλον ἐπικοσμοῦντα τὴν ἀρετὴν τοῦ ἀνδρὸς τοῖς ἀρίστοις καὶ μακαριωτάτοις ἐνταφίοις. ταῦτα δ’ ἦν οὐ χρυσὸς οὐδ’ ἐλέφας οὐδ’ ἡ λοιπὴ πολυτέλεια καὶ φιλοτιμία τῆς παρασκευῆς, ἀλλ’ εὔνοια καὶ τιμὴ καὶ χάρις οὐ μόνον παρὰ τῶν πολιτῶν, ἀλλὰ καὶ τῶν πολεμίων. ὅσοι γοῦν κατὰ τύχην παρῆσαν Ἰβήρων καὶ Λιγύων καὶ Μακεδόνων, οἱ μὲν ἰσχυροὶ τὰ σώματα καὶ νέοι διαλαβόντες τὸ λέχος ὑπέδυσαν καὶ παρεκόμιζον, οἱ δὲ πρεσβύτεροι συνηκολούθουν ἀνακαλούμενοι τὸν Αἰμίλιον εὐεργέτην καὶ σωτῆρα τῶν πατρίδων. οὐ γὰρ μόνον ἐν οἷς ἐκράτησε καιροῖς ἠπίως πᾶσι καὶ φιλανθρώπως ἀπηλλάγη χρησάμενος, ἀλλὰ καὶ παρὰ πάντα τὸν λοιπὸν βίον ἀεί τι πράττων ἀγαθὸν αὐτοῖς καὶ κηδόμενος ὥσπερ οἰκείων καὶ συγγενῶν διετέλεσε.", "st": "Aem. 39.1"}, {"sp": "N", "t": "τὴν δ’ οὐσίαν αὐτοῦ μόλις ἑπτὰ καὶ τριάκοντα μυριάδων γενέσθαι λέγουσιν, ἧς αὐτὸς μὲν ἀμφοτέρους τοὺς υἱοὺς ἀπέλιπε κληρονόμους, ὁ δὲ νεώτερος Σκηπίων τῷ ἀδελφῷ πᾶσαν ἔχειν συνεχώρησεν αὐτὸς εἰς οἶκον εὐπορώτερον τόν Ἀφρικανοῦ δεδομένος, οὗτος μὲν ὁ Παύλου Αἰμιλίου τρόπος καὶ βίος λέγεται γενέσθαι.", "st": "Aem. 39.10"}, {"sp": "HDR", "t": "Τιμολέοντος καὶ Παύλου Αἰμιλίου σύγκρισις"}, {"sp": "N", "t": "τοιούτων δὲ τῶν κατὰ τὴν ἱστορίαν ὄντων, δῆλον ὡς οὐκ ἔχει πολλὰς διαφορὰς οὐδὲ ἀνομοιότητας ἡ σύγκρισις. οἵ τε γὰρ πόλεμοι πρὸς ἐνδόξους γεγόνασιν ἀμφοτέροις ἀνταγωνιστάς, τῷ μὲν Μακεδόνας, τῷ δὲ Καρχηδονίους, αἵ τε νῖκαι περιβόητοι, τοῦ μὲν ἑλόντος Μακεδονίαν καὶ τὴν ἀπ’ Ἀντιγόνου διαδοχὴν ἐν ἑβδόμῳ βασιλεῖ καταπαύσαντος, τοῦ δὲ τὰς τυραννίδας πάσας ἀνελόντος ἐκ Σικελίας καὶ τὴν νῆσον ἐλευθερώσαντος· εἰ μὴ νὴ Δία βούλοιτό τις παρεγχειρεῖν ὡς Αἰμίλιος μὲν ἐρρωμένῳ Περσεῖ καὶ Ῥωμαίους νενικηκότι, Τιμολέων δὲ Διονυσίῳ παντάπασιν ἀπειρηκότι καὶ κατατετριμμένῳ συνέπεσε, καὶ πάλιν ὑπὲρ Τιμολέοντος, ὅτι πολλοὺς μὲν τυράννους, μεγάλην δὲ τὴν Καρχηδονίων δύναμιν ἀπὸ τῆς τυχούσης στρατιᾶς ἐνίκησεν, οὐχ ὥσπερ Αἰμίλιος ἀνδράσιν ἐμπειροπολέμοις καὶ μεμαθηκόσιν ἄρχεσθαι χρώμενος, ἀλλὰ μισθοφόροις οὖσι καὶ στρατιώταις ἀτάκτοις, πρὸς ἡδονὴν εἰθισμένοις στρατεύεσθαι. τὰ γὰρ ἀπ’ οὐκ ἴσης παρασκευῆς ἴσα κατορθώματα τῷ στρατηγῷ τὴν αἰτίαν περιτίθησι.", "st": "Comp. Tim.–Aem. 1.1"}, {"sp": "N", "t": "καθαρῶν οὖν καὶ δικαίων ἐν τοῖς πράγμασιν ἀμφοτέρων γεγονότων, Αἰμίλιος μὲν ὑπὸ τῶν νόμων καὶ τῆς πατρίδος οὕτως ἔοικεν εὐθὺς ἀφικέσθαι παρεσκευασμένος, Τιμολέων δὲ τοιοῦτον αὐτὸς ἑαυτὸν παρέσχε. τούτου τεκμήριον ὅτι Ῥωμαῖοι μὲν ὁμαλῶς ἐν τῷ τότε χρόνῳ πάντες ἦσαν εὔτακτοι καὶ ὑποχείριοι τοῖς ἐθισμοῖς καὶ τοὺς νόμους δεδιότες καὶ τοὺς πολίτας, Ἑλλήνων δὲ οὐδεὶς ἡγεμών ἐστιν οὐδὲ στρατηγός ὃς οὐ διεφθάρη τότε Σικελίας ἁψάμενος ἔξω Δίωνος. καίτοι Δίωνα πολλοὶ μοναρχίας ὀρέγεσθαι καὶ βασιλείαν τινὰ Λακωνικὴν ὀνειροπολεῖν ὑπενόουν. Τίμαιος δὲ καὶ Γύλιππον ἀκλεῶς φησι καὶ ἀτίμως ἀποπέμψαι Συρακουσίους, φιλοπλουτίαν αὑτοῦ καὶ ἀπληστίαν ἐν τῇ στρατηγίᾳ κατεγνωκότας. ἃ δὲ Φάραξ ὁ Σπαρτιάτης καὶ Κάλλιππος. ὁ Ἀθηναῖος ἐλπίσαντες ἄρξειν Σικελίας παρενόμησαν καὶ παρεσπόνδησαν, ὑπὸ πολλῶν ἀναγέγραπται. καίτοι τίνες ἢ πηλίκων κύριοι πραγμάτων ὄντες οὗτοι τοιαῦτα ἤλπισαν; ὧν ὁ μὲν ἐκπεπτωκότα Συρακουσῶν ἐθεράπευε Διονύσιον, Κάλλιππος δὲ εἷς ἦν τῶν περὶ Δίωνα ξεναγῶν. ἀλλὰ Τιμολέων αἰτησαμένοις καὶ δεηθεῖσιν αὐτοκράτωρ πεμφθεὶς Συρακουσίοις, καὶ δύναμιν οὐ ζητεῖν ἀλλ’ ἔχειν ὀφείλων ἣν ἔλαβε βουλομένων καὶ διδόντων, πέρας ἐποιήσατο τῆς αὑτοῦ στρατηγίας καὶ ἀρχῆς τὴν τῶν παρανόμων ἀρχόντων κατάλυσιν.", "st": "Comp. Tim.–Aem. 2.1"}, {"sp": "N", "t": "ἐκεῖνο μέντοι τοῦ Αἰμιλίου θαυμαστόν, ὅτι τηλικαύτην βασιλείαν καταστρεψάμενος οὐδὲ δραχμῇ μείζονα τὴν οὐσίαν ἐποίησεν, οὐδὲ εἶδεν οὐδὲ ἥψατο τῶν χρημάτων, καίτοι πολλὰ δοὺς ἑτέροις καὶ δωρησάμενος. οὐ λέγω δὲ ὅτι Τιμολέων μεμπτός ἐστιν οἰκίαν τε καλὴν λαβὼν καὶ χωρίον· οὐ γὰρ τὸ λαβεῖν ἐκ τοιούτων αἰσχρόν, ἀλλὰ τὸ μὴ λαβεῖν κρεῖττον καὶ περιουσία τῆς ἀρετῆς, ἐν οἷς ἔξεστιν ἐπιδεικνυμένης τὸ μὴ δεόμενον·", "st": "Comp. Tim.–Aem. 2.8"}, {"sp": "N", "t": "ἐπεὶ δέ, ὡς σώματος ῥῖγος ἢ θάλπος φέρειν δυναμένου τὸ πρὸς ἀμφοτέρας εὖ πεφυκὸς ὁμοῦ τὰς μεταβολὰς ῥωμαλεώτερον, οὕτω ψυχῆς ἄκρατος εὐρωστία καὶ ἰσχύς, ἣν οὔτε τὸ εὐτυχεῖν ὕβρει θρύπτει καὶ ἀνίησιν οὔτε συμφοραὶ ταπεινοῦσι, φαίνεται τελειότερος ὁ Αἰμίλιος, ἐν χαλεπῇ τύχῃ καὶ πάθει μεγάλῳ τῷ περὶ τοὺς παῖδας οὐδέν τι μικρότερος οὐδὲ ἀσεμνότερος ἢ διὰ τῶν εὐτυχημάτων ὁραθείς· Τιμολέων δὲ γενναῖα πράξας περὶ τὸν ἀδελφὸν οὐκ ἀντέσχε τῷ λογισμῷ πρὸς τὸ πάθος, ἀλλὰ μετανοίᾳ καὶ λύπῃ ταπεινωθεὶς ἐτῶν εἴκοσι τὸ βῆμα καὶ τὴν ἀγορὰν ἰδεῖν οὐχ ὑπέμεινε. δεῖ δὲ τὰ αἰσχρὰ φεύγειν καὶ αἰδεῖσθαι, τὸ δὲ πρὸς πᾶσαν ἀδοξίαν εὐλαβὲς ἐπιεικοῦς μὲν ἤθους καὶ ἁπαλοῦ, μέγεθος δὲ οὐκ ἔχοντος.", "st": "Comp. Tim.–Aem. 2.10"}, {"sp": "HDR", "t": "Πελοπίδας"}, {"sp": "N", "t": "Κάτων ὁ πρεσβύτερος πρός τινας ἐπαινοῦντας ἄνθρωπον ἀλογίστως παράβολον καὶ τολμηρὸν ἐν τοῖς πολεμικοῖς διαφέρειν ἔφη τὸ πολλοῦ τινα τὴν ἀρετὴν ἀξίαν καὶ τὸ μὴ πολλοῦ ἄξιον τὸ ζῆν νομίζειν ὀρθῶς ἀποφαινόμενος. ὁ γοῦν παρ’ Ἀντιγόνῳ στρατευόμενος ἰταμός, φαῦλος δὲ τὴν ἕξιν καὶ τὸ σῶμα διεφθορώς, ἐρομένου τοῦ βασιλέως τὴν αἰτίαν τῆς ὠχρότητος ὡμολόγησέ τινα νόσον τῶν ἀπορρήτων· ἐπεὶ δὲ φιλοτιμηθεὶς ὁ βασιλεὺς προσέταξε τοῖς ἰατροῖς, ἐάν τις ᾖ βοήθεια, μηδὲν ἐλλιπεῖν τῆς ἄκρας ἐπιμελείας, οὕτω θεραπευθεὶς ὁ γενναῖος ἐκεῖνος οὐκέτ’ ἦν φιλοκίνδυνος οὐδὲ ῥαγδαῖος ἐν τοῖς ἀγῶσιν, ὥστε καὶ τὸν Ἀντίγονον ἐγκαλεῖν καὶ θαυμάζειν τὴν μεταβολήν. οὐ μὴν ὁ ἄνθρωπος ἀπεκρύψατο τὸ αἴτιον, ἀλλ’ εἶπεν ὦ βασιλεῦ, σύ με πεποίηκας ἀτολμότερον, ἀπαλλάξας ἐκείνων τῶν κακῶν δι’ ἃ τοῦ ζῆν ὠλιγώρουν. πρὸς τοῦτο δὲ φαίνεται καὶ Συβαρίτης ἀνὴρ εἰπεῖν περὶ τῶν Σπαρτιατῶν ὡς οὐ μέγα ποιοῦσι θανατῶντες ἐν τοῖς πολέμοις ὑπὲρ τοῦ τοσούτους πόνους καὶ τοιαύτην ἀποφυγεῖν δίαιταν. ἀλλὰ Συβαρίταις μέν ἐκτετηκόσιν ὑπὸ τρυφῆς καὶ μαλακίας διὰ τὴν πρός τὸ καλὸν ὁρμὴν καὶ φιλοτιμίαν εἰκότως ἐφαίνοντο μισεῖν τὸν βίον οἱ μὴ φοβούμενοι τὸν θάνατον, Λακεδαιμονίοις δὲ καὶ ζῆν ἡδέως καὶ θνῄσκειν ἀμφότερα ἀρετὴ παρεῖχεν, ὡς δηλοῖ τὸ ἐπικήδειον· οἵδε γάρ φησιν ἔθανον", "st": "Pel. 1.1"}, {"sp": "N", "t": "οὐ τὸ ζῆν θέμενοι καλὸν οὐδὲ τὸ θνῄσκειν,<br>ἀλλὰ τὸ ταῦτα καλῶς ἀμφότερ’ ἐκτελέσαι.", "st": "Pel. 1.1b"}, {"sp": "N", "t": "οὔτε γὰρ φυγὴ θανάτου μεμπτόν, ἂν ὀρέγηταί τις τοῦ βίου μὴ αἰσχρῶς, οὔτε ὑπομονὴ καλόν, εἰ μετ’ ὀλιγωρίας γίνοιτο τοῦ ζῆν. ὅθεν Ὅμηρος μέν ἀεὶ τοὺς θαρραλεωτάτους καὶ μαχιμωτάτους ἄνδρας εὖ καὶ καλῶς ὡπλισμένους ἐξάγει πρός τοὺς ἀγῶνας, οἱ δὲ τῶν Ἑλλήνων νομοθέται τὸν ῥίψασπιν κολάζουσιν, οὐ τὸν ξίφος οὐδὲ λόγχην προέμενον, διδάσκοντες ὅτι τοῦ μὴ παθεῖν κακῶς πρότερον ἢ τοῦ ποιῆσαι τοὺς πολεμίους ἑκάστῳ μέλειν προσήκει, μάλιστα δὲ ἄρχοντι πόλεως ἢ στρατεύματος.", "st": "Pel. 1.5"}, {"sp": "N", "t": "εἰ γὰρ, ὡς Ἰφικράτης διῄρει, χερσὶ μὲν ἐοίκασιν οἱ ψιλοί, ποσὶ δὲ τὸ ἱππικόν, αὐτὴ δὲ ἡ φάλαγξ στέρνῳ καὶ θώρακι, κεφαλῇ δὲ ὁ στρατηγός, οὐχ αὐτοῦ δόξειεν ἂν ἀποκινδυνεύων παραμελεῖν καὶ θρασυνόμενος, ἀλλ’ ἁπάντων, οἷς ἡ σωτηρία γίνεται δι’ αὐτοῦ καὶ τοὐναντίον, ὅθεν ὁ Καλλικρατίδας, καίπερ ὢν τἆλλα μέγας, οὐκ εὖ πρὸς τὸν μάντιν εἶπε· δεομένου γὰρ αὐτοῦ φυλάττεσθαι θάνατον, ὡς τῶν ἱερῶν προδηλούντων, ἔφη μὴ παρ’· ἕνα εἶναι τὰν Σπάρταν. μαχόμενος γὰρ εἷς ἦν καὶ πλέων καὶ στρατευόμενος ὁ Καλλικρατίδας, στρατηγῶν δὲ τὴν ἁπάντων εἶχε συλλαβὼν ἐν αὑτῷ δύναμιν, ὥστε οὐκ ἦν εἷς ᾧ τοσαῦτα συναπώλλυτο. βέλτιον δὲ Ἀντίγονος ὁ γέρων, ὅτε ναυμαχεῖν περὶ Ἄνδρον ἔμελλεν, εἰπόντος τινὸς ὡς πολὺ πλείους αἱ τῶν πολεμίων νῆες εἶεν, ἐμὲ δὲ αὐτὸν, ἔφη, πρὸς πόσας ἀντιστήσεις; μέγα τὸ τῆς ἀρχῆς, ὥσπερ ἐστίν, ἀξίωμα ποιῶν μετὰ ἐμπειρίας καὶ ἀρετῆς ταττόμενον, ἧς πρῶτον ἔργον ἐστὶ σῴζειν τὸν ἅπαντα τἆλλα σώζοντα. διὸ καλῶς ὁ Τιμόθεος, ἐπιδεικνυμένου ποτὲ τοῖς Ἀθηναίοις τοῦ Χάρητος ὠτειλάς τινας ἐν τῷ σώματι καὶ τὴν ἀσπίδα λόγχῃ διακεκομμένην, ἐγὼ δέ, εἶπεν, ὡς λίαν ᾐσχύνθην ὅτι μου πολιορκοῦντος Σάμον ἐγγὺς ἔπεσε βέλος, ὡς μειρακιωδέστερον ἐμαυτῷ χρώμενος ἢ κατὰ στρατηγοῦ καὶ ἡγεμόνα δυνάμεως τοσαύτης. ὅπου μὲν γὰρ εἷς τὰ ὅλα μεγάλην φέρει ῥοπὴν ὁ τοῦ στρατηγοῦ κίνδυνος, ἐνταῦθα καὶ χειρὶ καὶ σώματι χρηστέον ἀφειδῶς, χαίρειν φράσαντα τοῖς λέγουσιν ὡς χρὴ τὸν ἀγαθὸν στρατηγὸν μάλιστα μὲν ὑπὸ γήρως, εἰ δὲ μή, γέροντα θνῄσκειν ὅπου δὲ μικρὸν τὸ περιγινόμενον ἐκ τοῦ κατορθώματος, τὸ δὲ πᾶν συναπόλλυται σφαλέντος, οὐδεὶς ἀπαιτεῖ στρατιώτου πρᾶξιν κινδύνῳ πραττομένην στρατηγοῦ.", "st": "Pel. 2.1"}, {"sp": "N", "t": "ταῦτα δέ μοι παρέστη προαναφωνῆσαι γράφοντι τὸν Πελοπίδου βίον καὶ τὸν Μαρκέλλου, μεγάλων ἀνδρῶν παραλόγως πεσόντων, καὶ γὰρ χειρὶ χρῆσθαι μαχιμώτατοι γενόμενοι, καὶ στρατηγίαις ἐπιφανεστάταις κοσμήσαντες ἀμφότεροι τὰς πατρίδας, ἔτι δὲ τῶν βαρυτάτων ἀνταγωνιστῶν ὁ μὲν Ἀννίβαν ἀήττητον ὄντα πρῶτος, ὡς λέγεται, τρεψάμενος, ὁ δὲ γῆς καὶ θαλάττης ἄρχοντας Λακεδαιμονίους ἐκ παρατάξεως νικήσας, ἠφείδησαν ἑαυτῶν, σὺν οὐδενὶ λογισμῷ προέμενοι τὸν βίον ὁπηνίκα μάλιστα τοιούτων καιρὸς ἦν ἀνδρῶν σῳζομένων καὶ ἀρχόντων· διόπερ ἡμεῖς ἑπόμενοι ταῖς ὁμοιότησι παραλλήλους ἀνεγράψαμεν αὐτῶν τοὺς βίους.", "st": "Pel. 2.5"}, {"sp": "N", "t": "Πελοπίδᾳ τῷ Ἱππόκλου γένος μὲν ἦν εὐδόκιμον ἐν Θήβαις ὥσπερ Ἐπαμεινώνδᾳ, τραφεὶς δὲ ἐν οὐσίᾳ μεγάλῃ καὶ παραλαβὼν ἔτι νέος λαμπρὸν οἶκον ὥρμησε τῶν δεομένων τοῖς ἀξίοις βοηθεῖν, ἵνα κύριος ἀληθῶς φαίνοιτο χρημάτων γεγονώς, ἀλλὰ μὴ δοῦλος. τῶν γὰρ πολλῶν, ὡς Ἀριστοτέλης φησίν, οἱ μὲν οὐ χρῶνται τῷ πλούτῳ διὰ μικρολογίαν, οἱ δὲ παραχρῶνται δι’ ἀσωτίαν, καὶ δουλεύοντες οὗτοι μὲν ἀεὶ ταῖς ἡδοναῖς, ἐκεῖνοι δὲ ταῖς ἀσχολίαις, διατελοῦσιν. οἱ μὲν οὖν ἄλλοι τῷ Πελοπίδᾳ χάριν ἔχοντες ἐχρῶντο τῇ πρὸς αὐτοὺς ἐλευθεριότητι καὶ φιλανθρωπίᾳ, μόνον δὲ τῶν φίλων τὸν Ἐπαμεινώνδαν οὐκ ἔπειθε τοῦ πλούτου μεταλαμβάνειν αὐτὸς μέντοι μετεῖχε τῆς ἐκείνου πενίας, ἐσθῆτος ἀφελείᾳ καὶ τραπέζης λιτότητι καὶ τῷ πρὸς τοὺς πόνους ἀόκνῳ καὶ κατὰ στρατείας ἀδόλῳ καλλωπιζόμενος, ὥσπερ ὁ Εὐριπίδου Καπανεύς, ᾧ βίος μὲν ἦν πολύς, ἥκιστα δὲ δι’ ὄλβον γαῦρος ἦν, αἰσχυνόμενος εἰ φανεῖται πλείοσι χρώμενος εἰς τὸ σῶμα τοῦ τὰ ἐλάχιστα κεκτημένου Θηβαίων. Ἐπαμεινώνδας μὲν οὖν συνήθη καὶ πατρῴαν οὖσαν αὐτῷ τὴν πενίαν ἔτι μᾶλλον εὔζωνον καὶ κοῦφον ἐποίησε φιλοσοφῶν καὶ μονότροπον βίον ἀπ’ ἀρχῆς ἑλόμενος· Πελοπίδᾳ δὲ ἦν μὲν γάμος λαμπρός, ἐγένοντο δὲ καὶ παῖδες, ἀλλ’ οὐδὲν ἧττον ἀμελῶν τοῦ χρηματίζεσθαι καὶ σχολάζων τῇ πόλει τὸν ἅπαντα χρόνον ἠλάττωσε τὴν οὐσίαν. τῶν δὲ φίλων νουθετούντων καὶ λεγόντων ὡς ἀναγκαίου πράγματος ὀλιγωρεῖ, τοῦ χρήματα ἔχειν, ἀναγκαίου, νὴ Δία, Νικοδήμῳ τούτῳ, ἔφη, δείξας τινὰ χωλὸν καὶ τυφλόν.", "st": "Pel. 3.1"}, {"sp": "N", "t": "ἦσαν δὲ καὶ πρὸς πᾶσαν ἀρετὴν πεφυκότες ὁμοίως, πλὴν ὅτι τῷ γυμνάζεσθαι μᾶλλον ἔχαιρε Πελοπίδας, τῷ δὲ μανθάνειν Ἐπαμεινώνδας, καὶ τὰς διατριβὰς ἐν τῷ σχολάζειν ὁ μὲν περὶ παλαίστρας καὶ κυνηγέσια, ὁ δὲ ἀκούων τι καὶ φιλοσοφῶν ἐποιεῖτο. πολλῶν δὲ καὶ καλῶν ὑπαρχόντων ἀμφοτέροις πρὸς δόξαν, οὐδὲν οἱ νοῦν ἔχοντες ἡγοῦνται τηλικοῦτον ἡλίκον τὴν διὰ τοσούτων ἀγώνων καὶ στρατηγιῶν καὶ πολιτειῶν ἀνεξέλεγκτον εὔνοιαν καὶ φιλίαν ἀπ’ ἀρχῆς μέχρι τέλους ἐμμείνασαν. εἰ γὰρ τις ἀποβλέψας τὴν Ἀριστείδου καὶ Θεμιστοκλέους καὶ Κίμωνος καὶ Περικλέους καὶ Νικίου καὶ Ἀλκιβιάδου πολιτείαν, ὅσων γέγονε μεστὴ διαφορῶν καὶ φθόνων καὶ ζηλοτυπιῶν πρὸς ἀλλήλους, σκέψαιτο πάλιν τὴν Πελοπίδου πρὸς Ἐπαμεινώνδαν εὐμένειαν καὶ τιμήν, τούτους ἂν ὀρθῶς καὶ δικαίως προσαγορεύσειε συνάρχοντας καὶ συστρατήγους ἢ ἐκείνους, οἳ μᾶλλον ἀλλήλων ἢ τῶν πολεμίων ἀγωνιζόμενοι περιεῖναι διετέλεσαν. αἰτία δὲ ἀληθινὴ μὲν ἦν ἡ ἀρετή, δι’ ἣν οὐ δόξαν, οὐ πλοῦτον ἀπὸ τῶν πράξεων μετιόντες, οἷς ὁ χαλεπὸς καὶ δύσερις ἐμφύεται φθόνος, ἀλλ’ ἔρωτα θεῖον ἀπ’ ἀρχῆς ἐρασθέντες ἀμφότεροι τοῦ τὴν πατρίδα λαμπροτάτην καὶ μεγίστην ἐφ’ ἑαυτῶν ἰδεῖν γενομένην, ὥσπερ ἰδίοις ἐπὶ τοῦτο τοῖς αὑτῶν ἐχρῶντο κατορθώμασιν.", "st": "Pel. 4.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ οἵ γε πολλοὶ νομίζουσιν αὐτοῖς τὴν σφοδρὰν φιλίαν ἀπὸ τῆς ἐν Μαντινείᾳ γενέσθαι στρατείας, ἣν συνεστρατεύσαντο Λακεδαιμονίοις, ἔτι φίλοις καὶ συμμάχοις οὖσι, πεμφθείσης ἐκ Θηβῶν βοηθείας, τεταγμένοι γὰρ ἐν τοῖς ὁπλίταις μετ’ ἀλλήλων καὶ μαχόμενοι πρὸς τοὺς Ἀρκάδας, ὡς ἐνέδωκε τὸ κατ’ αὐτοὺς κέρας τῶν Λακεδαιμονίων καὶ τροπὴ τῶν πολλῶν ἐγεγόνει, συνασπίσαντες ἠμύναντο τοὺς ἐπιφερομένους· καὶ Πελοπίδας μὲν ἑπτὰ τραύματα λαβὼν ἐναντία πολλοῖς ἐπικατερρύη νεκροῖς ὁμοῦ φίλοις καὶ πολεμίοις, Ἐπαμεινώνδας δέ, καίπερ ἀβιώτως ἔχειν αὐτὸν ἡγούμενος, ὑπὲρ τοῦ σώματος καὶ τῶν ὅπλων ἔστη προελθών καὶ διεκινδύνευσε πρὸς πολλοὺς μόνος, ἐγνωκὼς ἀποθανεῖν μᾶλλον ἢ Πελοπίδαν ἀπολιπεῖν κείμενον· ἤδη δὲ καὶ τούτου κακῶς ἔχοντος, καὶ λόγχῃ μὲν εἰς τὸ στῆθος, ξίφει δὲ εἰς τὸν βραχίονα τετρωμένου, προσεβοήθησεν ἀπὸ θατέρου κέρως Ἀγησίπολις ὁ βασιλεὺς τῶν Σπαρτιατῶν, καὶ περιεποίησεν ἀνελπίστως αὐτοὺς ἀμφοτέρους·", "st": "Pel. 4.4"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τῶν Σπαρτιατῶν λόγῳ μὲν ὡς φίλοις καὶ συμμάχοις προσφερομένων τοῖς Θηβαίοις, ἔργῳ δὲ τὸ φρόνημα τῆς πόλεως καὶ τὴν δύναμιν ὑφορωμένων, καὶ μάλιστα τὴν Ἰσμηνίου καὶ Ἀνδροκλείδου μισούντων ἑταιρείαν, ἧς μετεῖχεν ὁ Πελοπίδας, φιλελεύθερον ἅμα καὶ δημοτικὴν εἶναι δοκοῦσαν, Ἀρχίας καὶ Λεοντίδας καὶ Φίλιππος, ἄνδρες ὀλιγαρχικοὶ καὶ πλούσιοι καὶ μέτριον οὐδὲν φρονοῦντες, ἀναπείθουσι Φοιβίδαν τὸν Λάκωνα μετὰ στρατιᾶς διαπορευόμενον ἐξαίφνης καταλαβεῖν τὴν Καδμείαν καὶ τοὺς ὑπεναντιουμένους αὐτοῖς ἐκβαλόντα πρὸς τὸ Λακεδαιμονίων ὑπήκοον ἁρμόσασθαι δι’ ὀλίγων τὴν πολιτείαν. πεισθέντος δ’ ἐκείνου καὶ μὴ προσδοκῶσι τοῖς Θηβαίοις ἐπιθεμένου Θεσμοφορίων ὄντων, καὶ τῆς ἄκρας κυριεύσαντος, Ἰσμηνίας μὲν συναρπασθεὶς καὶ κομισθεὶς εἰς Λακεδαίμονα μετ’ οὐ πολὺν χρόνον ἀνῃρέθη, Πελοπίδας δὲ καὶ Φερένικος καὶ Ἀνδροκλείδας μετὰ συχνῶν ἄλλων φεύγοντες ἐξεκηρύχθησαν, Ἐπαμεινώνδας δὲ κατὰ χώραν ἔμεινε τῷ καταφρονηθῆναι διὰ μὲν φιλοσοφίαν ὡς ἀπράγμων, διὰ δὲ πενίαν ὡς ἀδύνατος.", "st": "Pel. 5.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Λακεδαιμόνιοι Φοιβίδαν μὲν ἀφείλοντο τῆς ἀρχῆς καὶ δέκα δραχμῶν μυριάσιν ἐζημίωσαν, τὴν δὲ Καδμείαν οὐδὲν ἧττον φρουρᾷ κατέσχον, οἱ μὲν ἄλλοι πάντες Ἕλληνες ἐθαύμαζον τὴν ἀτοπίαν, εἰ τὸν μὲν πράξαντα κολάζουσι, τὴν δὲ πρᾶξιν δοκιμάζουσι, τοῖς δὲ Θηβαίοις τὴν πάτριον ἀποβεβληκόσι πολιτείαν καὶ καταδεδουλωμένοις ὑπὸ τῶν περὶ Ἀρχίαν καὶ Λεοντίδαν οὐδὲ ἐλπίσαι περιῆν ἀπαλλαγήν τινα τῆς τυραννίδος, ἣν ἑώρων τῇ Σπαρτιατῶν δορυφορουμένην ἡγεμονίᾳ καὶ καταλυθῆναι μὴ δυναμένην, εἰ μή τις ἄρα παύσειε κἀκείνους γῆς καὶ θαλάττης ἄρχοντας, οὐ μὴν ἀλλ’ οἱ περὶ Λεοντίδαν πυνθανόμενοι τοὺς φυγάδας Ἀθήνησι διατρίβειν τῷ τε πλήθει προσφιλεῖς ὄντας καὶ τιμὴν ἔχοντας ὑπὸ τῶν καλῶν καὶ ἀγαθῶν, ἐπεβούλευον αὐτοῖς κρύφα· καὶ πέμψαντες ἀνθρώπους ἀγνῶτας Ἀνδροκλείδαν μὲν ἀποκτιννύουσι δόλῳ, τῶν δὲ ἄλλων διαμαρτάνουσιν. ἧκε δὲ καὶ παρὰ Λακεδαιμονίων γράμματα τοῖς Ἀθηναίοις προστάσσοντα μὴ δέχεσθαι μηδὲ παρακινεῖν, ἀλλ’ ἐξελαύνειν τοὺς φυγάδας ὡς κοινοὺς πολεμίους ὑπὸ τῶν συμμάχων ἀποδεδειγμένους. οἱ μὲν οὖν Ἀθηναῖοι, πρὸς τῷ πάτριον αὐτοῖς καὶ σύμφυτον εἶναι τὸ φιλάνθρωπον, ἀμειβόμενοι τοὺς Θηβαίους μάλιστα συναιτίους γενομένους τῷ δήμῳ τοῦ κατελθεῖν, καὶ ψηφισαμένους, ἐάν τις Ἀθηναίων ἐπὶ τοὺς τυράννους ὅπλα διὰ τῆς Βοιωτίας κομίζῃ, μηδένα Βοιωτὸν ἀκούειν μηδὲ ὁρᾶν, οὐδὲν ἠδίκησαν τοὺς Θηβαίους.", "st": "Pel. 6.1"}, {"sp": "N", "t": "ὁ δὲ Πελοπίδας, καίπερ ἐν τοῖς νεωτάτοις ὤν, ἰδίᾳ τε καθ’ ἕκαστον ἐξώρμα τῶν φυγάδων, καὶ πρὸς τὸ πλῆθος ἐποιήσατο λόγους, ὡς οὔτε καλὸν οὔτε ὅσιον εἴη δουλεύουσαν τὴν πατρίδα καὶ φρουρουμένην περιορᾶν, αὐτοὺς δὲ μόνον τὸ σῴζεσθαι καὶ διαζῆν ἀγαπῶντας ἐκκρέμασθαι τῶν Ἀθήνησι ψηφισμάτων καὶ θεραπεύειν ὑποπεπτωκότας ἀεὶ τοῖς λέγειν δυναμένοις καὶ πείθειν τὸν ὄχλον, ἀλλὰ κινδυνευτέον ὑπὲρ τῶν μεγίστων, παράδειγμα θεμένους τὴν Θρασυβούλου τόλμαν καὶ ἀρετήν, ἵνα, ὡς ἐκεῖνος ἐκ Θηβῶν πρότερον ὁρμηθεὶς κατέλυσε τοὺς ἐν Ἀθήναις τυράννους, οὕτως αὐτοὶ πάλιν ἐξ Ἀθηνῶν προελθόντες ἐλευθερώσωσι τὰς Θήβας, ὡς οὖν ἔπεισε ταῦτα λέγων, πέμπουσιν εἰς Θήβας κρύφα πρὸς τοὺς ὑπολελειμμένους τῶν φίλων τὰ δεδογμένα φράζοντες. οἱ δὲ συνεπῄνουν καὶ Χάρων μέν, ὅσπερ ἦν ἐπιφανέστατος, ὡμολόγησε τὴν οἰκίαν παρέξειν, Φιλλίδας δὲ διεπράξατο τῶν περὶ Ἀρχίαν καὶ Φίλιππον γραμματεὺς γενέσθαι πολεμαρχούντων. Ἐπαμεινώνδας δὲ τοὺς νέους πάλαι φρονήματος ἦν ἐμπεπληκώς· ἐκέλευε γὰρ ἐν τοῖς γυμνασίοις ἐπιλαμβάνεσθαι τῶν Λακεδαιμονίων καὶ παλαίειν, εἶτα ὁρῶν ἐπὶ τῷ κρατεῖν καὶ περιεῖναι γαυρουμένους ἐπέπληττεν, ὡς αἰσχύνεσθαι μᾶλλον αὐτοῖς προσῆκον, εἰ δουλεύουσι δι’ ἀνανδρίαν ὧν τοσοῦτον ταῖς ῥώμαις διαφέρουσιν.", "st": "Pel. 7.1"}, {"sp": "N", "t": "ἡμέρας δὲ πρὸς τὴν πρᾶξιν ὁρισθείσης, ἔδοξε τοῖς φυγάσι τοὺς μὲν ἄλλους συναγαγόντα Φερένικον ἐν τῷ Θριασίῳ περιμένειν, ὀλίγους δὲ τῶν νεωτάτων παραβαλέσθαι προεισελθεῖν εἷς τὴν πόλιν, ἐὰν δέ τι πάθωσιν ὑπὸ τῶν πολεμίων οὗτοι, τοὺς ἄλλους ἐπιμελεῖσθαι πάντας ὅπως μήτε παῖδες αὐτῶν μήτε γονεῖς ἐνδεεῖς ἔσονται τῶν ἀναγκαίων. ὑφίσταται δὲ τὴν πρᾶξιν Πελοπίδας πρῶτος, εἶτα Μέλων καὶ Δαμοκλείδας καὶ Θεόπομπος, ἄνδρες οἴκων τε πρώτων καὶ πρὸς ἀλλήλους τὰ ἄλλα μὲν φιλικῶς καὶ πιστῶς, ὑπὲρ δὲ δόξης καὶ ἀνδρείας ἀεὶ φιλονείκως ἔχοντες, γενόμενοι δὲ οἱ σύμπαντες δώδεκα, καὶ τοὺς ἀπολειπομένους ἀσπασάμενοι, καὶ προπέμψαντες ἄγγελον τῷ Χάρωνι, προῆγον ἐν χλαμυδίοις, σκύλακάς τε θηρατικὰς καὶ στάλικας ἔχοντες, ὡς μηδὲ εἷς ὑποπτεύοι τῶν ἐντυγχανόντων καθ’ ὁδόν, ἀλλ’ ἀλύοντες ἄλλως πλανᾶσθαι καὶ κυνηγεῖν δοκοῖεν.", "st": "Pel. 8.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ πεμφθεὶς παρ’ αὐτῶν ἄγγελος ἧκε πρὸς τὸν Χάρωνα καὶ καθ’ ὁδὸν ὄντας ἔφραζεν, αὐτὸς μὲν ὁ Χάρων οὐδὲ ὑπὸ τοῦ δεινοῦ πλησιάζοντος ἔτρεψέ τι τῆς γνώμης, ἀλλ’ ἀνὴρ ἀγαθὸς ἦν καὶ παρεῖχε τὴν οἰκίαν, Ἱπποσθενείδας δέ τις, οὐ πονηρὸς μὲν, ἀλλὰ καὶ φιλόπατρις καὶ τοῖς φυγάσιν εὔνους ἄνθρωπος, ἐνδεὴς δὲ τόλμης τοσαύτης ὅσης ὅ τε καιρὸς ὀξὺς ὢν αἵ τε ὑποκείμεναι πράξεις ἀπῄτουν, ὥσπερ ἰλιγγιάσας πρὸς τὸ μέγεθος τοῦ ἀγῶνος ἐν χερσὶ γενομένου, καὶ μόλις ποτὲ τῷ λογισμῷ συμφρονήσας ὅτι τρόπον τινὰ τὴν τῶν Λακεδαιμονίων σαλεύουσιν ἀρχὴν καὶ τῆς ἐκεῖθεν δυνάμεως ὑποβάλλονται κατάλυσιν, πιστεύσαντες ἀπόροις καὶ φυγαδικαῖς ἐλπίσιν, ἀπελθὼν οἴκαδε σιωπῇ πέμπει τινὰ τῶν φίλων πρὸς Μέλωνα καὶ Πελοπίδαν, ἀναβαλέσθαι κελεύων ἐν τῷ παρόντι καὶ περιμένειν βελτίονα καιρόν αὖθις ἀπαλλαγέντας εἷς Ἀθήνας. Χλίδων ἦν ὄνομα τῷ πεμφθέντι, καὶ κατὰ σπουδὴν οἴκαδε πρὸς αὑτὸν τραπόμενος καὶ τὸν ἵππον ἐξαγαγών ᾔτει τὸν χαλινόν. ἀπορουμένης δὲ τῆς γυναικὸς ὡς οὐκ εἶχε δοῦναι, καὶ χρῆσαί τινὶ τῶν συνήθων λεγούσης, λοιδορίαι τὸ πρῶτον ἦσαν, εἶτα δυσφημίαι, τῆς γυναικὸς ἐπαρωμένης αὐτῷ τε κακὰς ὁδοὺς ἐκείνῳ καὶ τοῖς πέμπουσιν, ὥστε καὶ τὸν Χλίδωνα πολὺ τῆς ἡμέρας ἀναλώσαντα πρὸς τούτοις δι’ ὀργήν, ἅμα δὲ καὶ τὸ συμβεβηκὸς οἰωνισάμενον, ἀφεῖναι τὴν ὁδὸν ὅλως καὶ πρὸς ἄλλο τι τραπέσθαι. παρὰ τοσοῦτον μὲν ἦλθον αἱ μέγισται καὶ κάλλισται τῶν πράξεων εὐθὺς ἐν ἀρχῇ διαφυγεῖν τὸν καιρόν.", "st": "Pel. 8.3"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Πελοπίδαν ἐσθῆτας γεωργῶν μεταλαβόντες καὶ διελόντες αὑτοὺς ἄλλοι κατ’ ἄλλα μέρη τῆς πόλεως παρεισῆλθον ἔτι ἡμέρας οὔσης. ἦν δέ τι πνεῦμα καὶ νιφετός ἀρχομένου τρέπεσθαι τοῦ ἀέρος, καὶ μᾶλλον ἔλαθον καταπεφευγότων ἤδη διὰ τὸν χειμῶνα τῶν πλείστων εἰς τὰς οἰκίας, οἷς δὲ ἦν ἐπιμελὲς τὰ πραττόμενα γινώσκειν, ἀνελάμβανον τοὺς προσερχομένους καὶ καθίστων εὐθὺς εἰς τήν οἰκίαν τὸν Χάρωνος· ἐγένοντο δὲ σὺν τοῖς φυγάσι πεντήκοντα δυοῖν δέοντες.", "st": "Pel. 9.1"}, {"sp": "N", "t": "τὰ δὲ περὶ τοὺς τυράννους οὕτως εἶχε. Φιλλίδας ὁ γραμματεὺς συνέπραττε μὲν, ὥσπερ εἴρηται, πάντα καὶ συνῄδει τοῖς φυγάσιν, εἰς δὲ τήν ἡμέραν ἐκείνην ἐκ παλαιοῦ κατηγγελκὼς τοῖς περὶ τὸν Ἀρχίαν πότον τινὰ καὶ συνουσίαν καὶ γύναια τῶν ὑπάνδρων, ἔπραττεν ὅτι μάλιστα ταῖς ἡδοναῖς ἐκλελυμένους καὶ κατοίνους μεταχειρίσασθαι παρέξειν τοῖς ἐπιτιθεμένοις. οὔπω δὲ πάνυ πόρρω μέθης οὖσιν αὐτοῖς προσέπεσέ τις οὐ ψευδὴς μέν, ἀβέβαιος δὲ καὶ πολλὴν ἀσάφειαν ἔχουσα περὶ τῶν φυγάδων μήνυσις ὡς ἐν τῇ πόλει κρυπτομένων, τοῦ δὲ Φιλλίδου παραφέροντος τὸν λόγον, ὅμως Ἀρχίας ἔπεμψέ τινα τῶν ὑπηρετῶν πρὸς τὸν Χάρωνα, προστάσσων εὐθὺς ἥκειν αὐτόν, ἦν δὲ ἑσπέρα, καὶ συνέταττον ἔνδον αὑτοὺς οἱ περὶ τὸν Πελοπίδαν, ἤδη τεθωρακισμένοι καὶ τὰς μαχαίρας ἀνειληφότες. ἐξαίφνης δὲ κοπτομένης τῆς θύρας προσδραμών τις, καὶ πυθόμενος τοῦ ὑπηρέτου Χάρωνα μετιέναι παρὰ τῶν πολεμάρχων φάσκοντος, ἀπήγγειλεν εἴσω τεθορυβημένος, καὶ πᾶσιν εὐθὺς παρέστη τήν τε πρᾶξιν ἐκμεμηνῦσθαι καὶ σφᾶς ἅπαντας ἀπολωλέναι, μηδὲ δράσαντάς τι τῆς ἀρετῆς ἄξιον, οὐ μὴν ἀλλ’ ἔδοξεν ὑπακοῦσαι τὸν Χάρωνα καὶ παρασχεῖν ἑαυτὸν δεῖν ἀνυπόπτως τοῖς ἄρχουσιν, ἄλλως μέν ἀνδρώδη καὶ βαρὺν ὄντα τῷ θαρρεῖν παρὰ τὰ δεινά, τότε δὲ δι’ ἐκείνους ἐκπεπληγμένον καὶ περιπαθοῦντα, μή τις ὑποψία προδοσίας ἐπ’ αὐτὸν ἔλθῃ τοσούτων ἅμα καὶ τοιούτων πολιτῶν ἀπολομένων. ὡς οὖν ἔμελλεν ἀπιέναι, παραλαβὼν ἐκ τῆς γυναικωνίτιδος τὸν υἱόν, ἔτι μέν ὄντα παῖδα, κάλλει δὲ καὶ ῥώμῃ σώματος πρωτεύοντα τῶν καθ’ ἡλικίαν, ἐνεχείριζε τοῖς περὶ Πελοπίδαν, εἴ τινα δόλον καὶ προδοσίαν αὐτοῦ καταγνοῖεν, ὡς πολεμίῳ χρῆσθαι κελεύων ἐκείνῳ καὶ μὴ φείδεσθαι. πολλοῖς μέν οὖν αὐτῶν δάκρυα πρὸς τὸ πάθος καὶ τὸ φρόνημα τοῦ Χάρωνος ἐξέπεσε, πάντες δὲ ἠγανάκτουν εἰ δειλὸν οὕτως εἶναί τινα δοκεῖ καὶ διεφθαρμένον ὑπὸ τοῦ παρόντος, ὥστε ὑπονοεῖν ἐκεῖνον ἢ ὅλως αἰτιᾶσθαι καὶ τὸν υἱὸν ἐδέοντο μὴ καταμιγνύειν αὐτοῖς, ἀλλ’ ἐκποδὼν θέσθαι τοῦ μέλλοντος, ὅπως αὐτός γε τῇ πόλει καὶ τοῖς φίλοις τιμωρὸς ὑποτρέφοιτο περισωθεὶς καὶ διαφυγὼν τοὺς τυράννους. ὁ δὲ Χάρων τὸν μέν υἱὸν ἀπαλλάξειν οὐκ ἔφη· ποῖον γὰρ αὐτῷ βίον ὁρᾶν ἢ τίνα σωτηρίαν καλλίονα τῆς ὁμοῦ μετὰ πατρὸς καὶ φίλων τοσούτων ἀνυβρίστου τελευτῆς; ἐπευξάμενος δὲ τοῖς θεοῖς καὶ πάντας ἀσπασάμενος καὶ παραθαρρύνας ἀπῄει, προσέχων ἑαυτῷ καὶ ῥυθμίζων σχήματι προσώπου καὶ τόνῳ φωνῆς ἀνομοιότατος οἷς ἔπραττε φανῆναι.", "st": "Pel. 9.2"}, {"sp": "N", "t": "γενομένου δ’ ἐπὶ ταῖς θύραις αὐτοῦ, προῆλθεν ὁ Ἀρχίας, καὶ Φιλλίδας, καὶ εἶπεν· ὦ Χάρων, τινὰς ἀκήκοα παρεληλυθότας ἐν τῇ πόλει κρύπτεσθαι, καὶ συμπράττειν αὐτοῖς ἐνίους τῶν πολιτῶν. καὶ ὁ Χάρων διαταραχθεὶς τὸ πρῶτον, εἶτα ἐρωτήσας τίνες εἰσὶν οἱ παρεληλυθότες καὶ τίνες οἱ κρύπτοντες αὐτούς, ὡς οὐδὲν ἑώρα σαφὲς εἰπεῖν ἔχοντα τὸν Ἀρχίαν, ὑπονοήσας ἀπ’ οὐδενὸς τῶν ἐπισταμένων γεγονέναι τὴν μήνυσιν, ὁρᾶτε τοίνυν, ἔφη, μὴ κενός τις ὑμᾶς διαταράττῃ λόγος, οὐ μὴν ἀλλὰ σκέψομαι· δεῖ γὰρ ἴσως μηδενὸς καταφρονεῖν. ταῦτα καὶ Φιλλίδας παρὼν ἐπῄνει, καὶ τὸν Ἀρχίαν ἀπαγαγὼν αὖθις εἰς ἄκρατον πολὺν κατέβαλε, καὶ ταῖς περὶ τῶν γυναικῶν ἐλπίσι διεπαιδαγώγει τὸν πότον. ὡς δ’ ἐπανῆλθεν ὁ Χάρων οἴκαδε καὶ διεσκευασμένους τοὺς ἄνδρας εὗρεν οὐχ ὡς ἄν τινα νίκην ἢ σωτηρίαν ἐλπίζοντας, ἀλλ’ ὡς ἀποθανουμένους λαμπρῶς καὶ μετὰ φόνου πολλοῦ τῶν πολεμίων, τὸ μὲν ἀληθὲς αὐτοῖς ἔφραζε τοῖς περὶ τὸν Πελοπίδαν, πρὸς δὲ τοὺς ἄλλους ἐψεύσατο λόγους τινὰς τοῦ Ἀρχίου περὶ πραγμάτων ἑτέρων πλασάμενος.", "st": "Pel. 10.1"}, {"sp": "N", "t": "ἔτι δὲ τοῦ πρώτου παραφερομένου δεύτερον ἐπῆγεν ἡ τύχη χειμῶνα τοῖς ἀνδράσιν. ἧκε γάρ τις ἐξ Ἀθηνῶν παρὰ Ἀρχίου τοῦ ἱεροφάντου πρὸς Ἀρχίαν τὸν ὁμώνυμον, ξένον ὄντα καὶ φίλον, ἐπιστολὴν κομίζων οὐ κενὴν ἔχουσαν οὐδὲ πεπλασμένην ὑπόνοιαν, ἀλλὰ σαφῶς ἕκαστα περὶ τῶν πρασσομένων φάσκουσαν, ὡς ὕστερον ἐπεγνώσθη· τότε δὲ μεθύοντι τῷ Ἀρχίᾳ προσαχθεὶς ὁ γραμματοφόρος καὶ τὴν ἐπιστολὴν ἐπιδούς, ὁ ταύτην, ἔφη, πέμψας ἐκέλευσεν εὐθὺς ἀναγνῶναι· περὶ σπουδαίων γάρ τινων γεγράφθαι. καὶ ὁ Ἀρχίας μειδιάσας, οὐκοῦν εἰς αὔριον ἔφη, τὰ σπουδαῖα. καὶ τὴν ἐπιστολὴν δεξάμενος ὑπὸ τὸ προσκεφάλαιον ὑπέθηκεν, αὐτὸς δὲ πάλιν τῷ Φιλλίδᾳ περὶ ὧν ἐτύγχανον διαλεγόμενοι προσεῖχεν. ὁ μὲν οὖν λόγος οὗτος ἐν παροιμίας τάξει περιφερόμενος μέχρι νῦν διασῴζεται παρὰ τοῖς Ἕλλησι.", "st": "Pel. 10.3"}, {"sp": "N", "t": "τῆς δὲ πράξεως δοκούσης ἔχειν ἤδη τὸν οἰκεῖον καιρόν, ἐξώρμων δίχα διελόντες αὑτούς, οἱ μὲν περὶ Πελοπίδαν καὶ Δαμοκλείδαν ἐπὶ τὸν Λεοντίδαν καὶ τὸν Ὑπάτην ἐγγὺς ἀλλήλων οἰκοῦντας, Χάρων δὲ καὶ Μέλων ἐπὶ τὸν Ἀρχίαν καὶ Φίλιππον, ἐσθῆτας ἐπενδεδυμένοι γυναικείας τοῖς θώραξι, καὶ δασεῖς στεφάνους ἐλάτης τε καὶ πεύκης περικείμενοι κατασκιάζοντας τὰ πρόσωπα. διὸ καὶ ταῖς θύραις τοῦ συμποσίου τὸ πρῶτον ἐπιστάντες, κρότον ἐποίησαν καὶ θόρυβον οἰομένων ἃς πάλαι προσεδόκων γυναῖκας ἥκειν. ἐπεὶ δὲ περιβλέψαντες ἐν κύκλῳ τὸ συμπόσιον καὶ τῶν κατακεκλιμένων ἕκαστον ἀκριβῶς καταμαθόντες ἐσπάσαντο τὰς μαχαίρας, καὶ φερόμενοι διὰ τῶν τραπεζῶν ἐπὶ τὸν Ἀρχίαν καὶ Φίλιππον ἐφάνησαν οἵπερ ἦσαν, ὀλίγους μὲν ὁ Φιλλίδας τῶν κατακειμένων ἔπεισεν ἡσυχίαν ἄγειν, τοὺς δὲ ἄλλους ἀμύνεσθαι μετὰ τῶν πολεμάρχων ἐπιχειροῦντας καὶ συνεξανισταμένους διὰ τὴν μέθην οὐ πάνυ χαλεπῶς ἀπέκτειναν.", "st": "Pel. 11.1"}, {"sp": "N", "t": "τοῖς δὲ περὶ τὸν Πελοπίδαν ἐργωδέστερον ἀπήντα τὸ πρᾶγμα· καὶ γὰρ ἐπὶ νήφοντα καὶ δεινὸν ἄνδρα τὸν Λεοντίδαν ἐχώρουν, καὶ κεκλεισμένην τὴν οἰκίαν εὗρον ἤδη καθεύδοντος, καὶ πολὺν χρόνον κόπτουσιν αὐτοῖς ὑπήκουεν οὐδείς. μόλις δέ ποτε τοῦ θεράποντος αἰσθομένου προϊόντος ἔνδοθεν καὶ τὸν μοχλὸν ἀφαιροῦντος, ἅμα τῷ πρῶτον ἐνδοῦναι καὶ χαλάσαι τὰς θύρας ἐμπεσόντες ἀθρόοι καὶ τὸν οἰκέτην ἀνατρέψαντες ἐπὶ τὸν θάλαμον ὥρμησαν. ὁ δὲ Λεοντίδας αὐτῷ τεκμαιρόμενος τῷ κτύπῳ καὶ δρόμῳ τὸ γιγνόμενον, ἐσπάσατο μὲν τὸ ἐγχειρίδιον ἐξαναστάς, ἔλαθε δὲ αὐτὸν καταβαλεῖν τὰ λύχνα καὶ διὰ σκότους αὐτοὺς ἑαυτοῖς περιπετεῖς ποιῆσαι τοὺς ἄνδρας, ἐν δὲ φωτὶ πολλῷ καθορώμενος, ὑπήντα πρὸς τὰς θύρας αὐτοῖς τοῦ θαλάμου, καὶ τὸν πρῶτον εἰσιόντα Κηφισόδωρον πατάξας κατέβαλε, πεσόντος δὲ τούτου δευτέρῳ συνεπλέκετο τῷ Πελοπίδᾳ· καὶ τὴν μάχην χαλεπὴν ἐποίει καὶ δύσεργον ἡ στενότης τῶν θυρῶν καὶ κείμενος ἐμποδὼν ἤδη νεκρὸς ὁ Κηφισόδωρος. ἐκράτησε δ’ οὖν ὁ Πελοπίδας, καὶ κατεργασάμενος τὸν Λεοντίδαν ἐπὶ τὸν Ὑπάτην εὐθὺς ἐχώρει μετὰ τῶν σὺν αὐτῷ. καὶ παρεισέπεσον μὲν εἰς τὴν οἰκίαν ὁμοίως, αἰσθόμενον δὲ ταχέως καὶ καταφυγόντα πρὸς τοὺς γείτονας, ἐκ ποδῶν διώξαντες εἷλον καὶ διέφθειραν.", "st": "Pel. 11.4"}, {"sp": "N", "t": "διαπραξάμενοι δὲ ταῦτα καὶ τοῖς περὶ Μέλωνα συμβαλόντες ἔπεμψαν μὲν εἰς τὴν Ἀττικὴν ἐπὶ τοὺς ὑπολελειμμένους ἐκεῖ τῶν φυγάδων, ἐκάλουν δὲ τοὺς πολίτας ἐπὶ τὴν ἐλευθερίαν, καὶ τοὺς προσιόντας ὥπλιζον, ἀφαιροῦντες ἀπὸ τῶν στοῶν τὰ περικείμενα σκῦλα, καὶ τὰ περὶ τὴν οἰκίαν ἐργαστήρια δορυξόων καὶ μαχαιροποιῶν ἀναρρηγνύντες. ἧκον δὲ βοηθοῦντες αὐτοῖς μετὰ τῶν ὅπλων οἱ περὶ Ἐπαμεινώνδαν καὶ Γοργίδαν, συνειλοχότες οὐκ ὀλίγους τῶν νέων καὶ τῶν πρεσβυτέρων τοὺς βελτίστους, ἡ δὲ πόλις ἤδη μὲν ἀνεπτόητο πᾶσα, καὶ πολὺς θόρυβος ἦν καὶ φῶτα περὶ τὰς οἰκίας καὶ διαδρομαὶ πρὸς ἀλλήλους, οὔπω δὲ συνειστήκει τὸ πλῆθος, ἀλλ’ ἐκπεπληγμένοι πρὸς τὰ γινόμενα καὶ σαφὲς οὐδὲν εἰδότες ἡμέραν περιέμενον. ὅθεν ἁμαρτεῖν οἱ τῶν Λακεδαιμονίων ἄρχοντες ἔδοξαν εὐθὺς οὐκ ἐπιδραμόντες οὐδὲ συμβαλόντες, αὐτὴ μὲν ἡ φρουρὰ περὶ χιλίους πεντακοσίους ὄντες, ἐκ δὲ τῆς πόλεως πρὸς αὐτοὺς πολλῶν συντρεχόντων, ἀλλὰ τὴν βοὴν καὶ τὰ πυρὰ καὶ τὸν ὄχλον χωροῦντα πανταχόθεν πολὺν φοβηθέντες ἡσύχαζον, αὐτὴν τὴν Καδμείαν κατέχοντες. ἅμα δὲ ἡμέρᾳ παρῆσαν μὲν ἐκ τῆς Ἀττικῆς οἱ φυγάδες ὡπλισμένοι, συνήθροιστο δὲ εἰς τὴν ἐκκλησίαν ὁ δῆμος. εἰσῆγον δὲ τοὺς περὶ Πελοπίδαν Ἐπαμεινώνδας καὶ Γοργίδας ὑπὸ τῶν ἱερέων περιεχομένους στέμματα προτεινόντων καὶ παρακαλούντων τοὺς πολίτας τῇ πατρίδι καὶ τοῖς θεοῖς βοηθεῖν, ἡ δ’ ἐκκλησία ὀρθὴ πρὸς τὴν ὄψιν μετὰ κρότου καὶ βοῆς ἐξανέστη, δεχομένων τοὺς ἄνδρας ὡς εὐεργέτας καὶ σωτῆρας.", "st": "Pel. 12.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου βοιωτάρχης αἱρεθεὶς μετὰ Μέλωνος καὶ Χάρωνος ὁ Πελοπίδας εὐθὺς ἀπετείχιζε τὴν ἀκρόπολιν καὶ προσβολὰς ἐποιεῖτο πανταχόθεν, ἐξελεῖν σπουδάζων τοὺς Λακεδαιμονίους καὶ τὴν Καδμείαν ἐλευθερῶσαι πρὶν ἐκ Σπάρτης στρατὸν ἐπελθεῖν. καὶ παρὰ τοσοῦτον ἔφθασεν ἀφεὶς ὑποσπόνδους τοὺς ἄνδρας ὅσον ἐν Μεγάροις οὖσιν αὐτοῖς ἀπαντῆσαι Κλεόμβροτον ἐπὶ τὰς Θήβας ἐλαύνοντα μετὰ μεγάλης δυνάμεως, οἱ δὲ Σπαρτιᾶται, τριῶν ἁρμοστῶν γενομένων ἐν Θήβαις, Ἡριππίδαν μὲν καὶ Ἄρκισσον ἀπέκτειναν κρίναντες, ὁ δὲ τρίτος Λυσανορίδας χρήμασι πολλοῖς ζημιωθεὶς αὑτὸν ἐκ τῆς Πελοποννήσου μετέστησε.", "st": "Pel. 13.1"}, {"sp": "N", "t": "ταύτην τὴν πρᾶξιν ἀρεταῖς μὲν ἀνδρῶν καὶ κινδύνοις καὶ ἀγῶσι παραπλησίαν τῇ Θρασυβούλου γενομένην, καὶ βραβευθεῖσαν ὁμοίως ὑπὸ τῆς τύχης, ἀδελφὴν ἐκείνης προσηγόρευον οἱ Ἕλληνες, οὐ γὰρ ἔστι ῥᾳδίως ἑτέρους εἰπεῖν οἳ πλειόνων ἐλάττους καὶ δυνατωτέρων ἐρημότεροι τόλμῃ καὶ δεινότητι κρατήσαντες αἴτιοι μειζόνων ἀγαθῶν ταῖς πατρίσι κατέστησαν. ἐνδοξοτέραν δὲ ταύτην ἐποίησεν ἡ μεταβολὴ τῶν πραγμάτων, ὁ γὰρ καταλύσας τὸ τῆς Σπάρτης ἀξίωμα καὶ παύσας ἄρχοντας αὐτοὺς γῆς τε καὶ θαλάττης πόλεμος ἐξ ἐκείνης ἐγένετο τῆς νυκτός, ἐν ᾗ Πελοπίδας οὐ φρούριον, οὐ τεῖχος, οὐκ ἀκρόπολιν καταλαβών, ἀλλ’ εἰς οἰκίαν δωδέκατος κατελθών, εἰ δεῖ μεταφορᾷ τὸ ἀληθὲς εἰπεῖν, ἔλυσε καὶ διέκοψε τοὺς δεσμοὺς τῆς Λακεδαιμονίων ἡγεμονίας, ἀλύτους καὶ ἀρρήκτους εἶναι δοκοῦντας.", "st": "Pel. 13.3"}, {"sp": "N", "t": "ἐπεὶ τοίνυν στρατῷ μεγάλῳ Λακεδαιμονίων εἰς τήν Βοιωτίαν ἐμβαλόντων οἱ Ἀθηναῖοι περίφοβοι γενόμενοι τήν τε συμμαχίαν ἀπείπαντο τοῖς Θηβαίοις καὶ τῶν βοιωτιαζόντων εἰς τὸ δικαστήριον παραγαγόντες τοὺς μὲν ἀπέκτειναν, τοὺς δ’ ἐφυγάδευσαν, τοὺς δὲ χρήμασιν ἐζημίωσαν, ἐδόκει δὲ κακῶς ἔχειν τὰ τῶν Θηβαίων πράγματα μηδενὸς αὐτοῖς βοηθοῦντος, ἔτυχε μὲν ὁ Πελοπίδας μετὰ Γοργίδου βοιωταρχῶν, ἐπιβουλεύοντες δὲ συγκροῦσαι πάλιν τοὺς Ἀθηναίους τοῖς Λακεδαιμονίοις τοιόνδε τι μηχανῶνται. Σφοδρίας, ἀνὴρ Σπαρτιάτης, εὐδόκιμος μὲν ἐν τοῖς πολεμικοῖς καὶ λαμπρός, ὑπόκουφος δὲ τήν γνώμην καὶ κενῶν ἐλπίδων καὶ φιλοτιμίας ἀνοήτου μεστός, ἀπελείφθη περὶ Θεσπιὰς μετὰ δυνάμεως τοὺς ἀφισταμένους τῶν Θηβαίων δέχεσθαι καὶ βοηθεῖν. πρὸς τοῦτον ὑποπέμπουσιν οἱ περὶ τὸν Πελοπίδαν ἰδίᾳ ἔμπορόν τινα τῶν φίλων, χρήματα κομίζοντα καὶ λόγους, οἳ τῶν χρημάτων μᾶλλον ἀνέπεισαν αὐτόν ὡς χρὴ πραγμάτων ἅψασθαι μεγάλων καὶ τὸν Πειραιᾶ καταλαβεῖν, ἀπροσδόκητον ἐπιπεσόντα μὴ φυλαττομένοις τοῖς Ἀθηναίοις· Λακεδαιμονίοις τε γὰρ οὐδὲν οὕτως ἔσεσθαι κεχαρισμένον ὡς λαβεῖν τὰς Ἀθήνας, Θηβαίους τε χαλεπῶς ἔχοντας αὐτοῖς καὶ προδότας νομίζοντας οὐκ ἐπιβοηθήσειν. τέλος δὲ συμπεισθεὶς ὁ Σφοδρίας καὶ τοὺς στρατιώτας ἀναλαβών, νυκτὸς εἰς τήν Ἀττικὴν ἐνέβαλε. καὶ μέχρι μὲν Ἐλευσῖνος προῆλθεν, ἐκεῖ δὲ τῶν στρατιωτῶν ἀποδειλιασάντων φανερὸς γενόμενος, καὶ συνταράξας οὐ φαῦλον οὐδὲ ῥᾴδιον τοῖς Σπαρτιάταις πόλεμον, ἀνεχώρησεν εἰς Θεσπιάς.", "st": "Pel. 14.1"}, {"sp": "N", "t": "ἐκ τούτου πάλιν προθυμότατα Ἀθηναῖοι τοῖς Θηβαίοις συνεμάχουν, καί τῆς θαλάττης ἀντελαμβάνοντο, καί περιϊόντες ἐδέχοντο καί προσήγοντο τοὺς ἀποστατικῶς τῶν Ἑλλήνων ἔχοντας. οἱ δὲ Θηβαῖοι καθ’ αὑτοὺς ἐν τῇ Βοιωτίᾳ συμπλεκόμενοι τοῖς Λακεδαιμονίοις ἑκάστοτε, καί μαχόμενοι μάχας αὐτὰς μὲν οὐ μεγάλας, μεγάλην δὲ τὴν μελέτην ἐχούσας καί τὴν ἄσκησιν. ἐξερριπίζοντο τοῖς θυμοῖς καί διεπονοῦντο τοῖς σώμασιν, ἐμπειρίαν ἅμα τῇ συνηθείᾳ καὶ φρόνημα προσλαμβάνοντες ἐκ τῶν ἀγώνων. διὸ καί φασιν Ἀνταλκίδαν τὸν Σπαρτιάτην, ὡς Ἀγησίλαος ἐπανῆλθεν ἐκ Βοιωτίας τετρωμένος, εἰπεῖν πρὸς αὐτόν ἦ καλὰ διδασκάλια παρὰ Θηβαίων ἀπολαμβάνεις, μὴ βουλομένους αὑτοὺς πολεμεῖν καί μάχεσθαι διδάξας. ἦν δὲ ὡς ἀληθῶς διδάσκαλος οὐκ Ἀγησίλαος, ἀλλ’ οἱ σὺν καιρῷ καί μετὰ λογισμοῦ τοὺς Θηβαίους ὥσπερ σκύλακας ἐμπείρως προσβάλλοντες τοῖς πολεμίοις, εἶτα γευσαμένους νίκης καί φρονήματος ἀσφαλῶς ἀπάγοντες ὧν μεγίστην δόξαν εἶχεν ὁ Πελοπίδας, ἀφ’ ἧς γὰρ εἵλοντο πρῶτον ἡγεμόνα τῶν ὅπλων, οὐκ ἐπαύσαντο καθ’ ἕκαστον ἐνιαυτὸν ἄρχοντα χειροτονοῦντες, ἀλλ’ ἢ τὸν ἱερὸν λόχον ἄγων ἢ τὰ πλεῖστα βοιωταρχῶν ἄχρι τῆς τελευτῆς ἔπραττεν.", "st": "Pel. 15.1"}, {"sp": "N", "t": "ἐγένοντο μὲν οὖν καί περὶ Πλαταιὰς καί Θεσπιὰς ἧτται καί φυγαὶ τῶν Λακεδαιμονίων, ὅπου καί Φοιβίδας ὁ τὴν Καδμείαν καταλαβὼν ἀπέθανε, πολλοὺς δὲ καί πρὸς Τανάγρᾳ τρεψάμενος αὐτῶν καί Πανθοίδαν τὸν ἁρμοστὴν ἀνεῖλεν. ἀλλ’ οὗτοι μὲν οἱ ἀγῶνες ὥσπερ τοὺς κρατοῦντας εἰς φρόνημα καί θάρσος προῆγον, οὕτως τῶν ἡσσωμένων οὐ παντάπασιν ἐδουλοῦντο τὴν γνώμην· οὐ γὰρ ἐκ παρατάξεως ἦσαν οὐδὲ μάχης ἐμφανῆ κατάστασιν ἐχούσης καί νόμιμον, ἐκδρομὰς δὲ προσκαίρους τιθέμενοι, καί φυγὰς ἢ διώξεις ἐπιχειροῦντες αὐτοῖς καί συμπλεκόμενοι κατώρθουν.", "st": "Pel. 15.4"}, {"sp": "N", "t": "ὁ δὲ περὶ Τεγύρας τρόπον τινὰ τοῦ Λευκτρικοῦ προαγὼν γενόμενος μέγαν ἦρε δόξῃ τὸν Πελοπίδαν, οὔτε πρὸς κατόρθωμα τοῖς συστρατήγοις ἀμφισβήτησιν οὔτε τῆς ἥττης πρόφασιν τοῖς πολεμίοις ἀπολιπών. τῇ γὰρ Ὀρχομενίων πόλει τὰ Σπαρτιατῶν ἑλομένῃ καὶ δύο δεδεγμένῃ μόρας αὐτῶν ὑπὲρ ἀσφαλείας ἐπεβούλευε μὲν ἀεὶ καὶ παρεφύλαττε καιρόν, ὡς δὲ ἤκουσε τοῖς φρουροῖς εἰς τὴν Λοκρίδα γεγενῆσθαι στρατείαν ἐλπίσας ἔρημον αἱρήσειν τὸν Ὀρχομενὸν ἐστράτευσεν, ἔχων μεθ’ ἑαυτοῦ τὸν ἱερὸν λόχον καὶ τῶν ἱππέων οὐ πολλούς, ἐπεὶ δὲ πρὸς τὴν πόλιν προσαγαγὼν εὗρεν ἥκουσαν ἐκ Σπάρτης διαδοχὴν τῆς φρουρᾶς, ἀπῆγεν ὀπίσω τὸ στράτευμα πάλιν διὰ Τεγυρῶν, ᾗ μόνῃ βάσιμον ἦν κύκλῳ παρὰ τὴν ὑπώρειαν. τὴν γὰρ διὰ μέσου πᾶσαν ὁ Μέλας ποταμός εὐθὺς ἐκ πηγῶν εἰς ἕλη πλωτὰ καὶ λίμνας διασπειρόμενος ἄπορον ἐποίει.", "st": "Pel. 16.1"}, {"sp": "N", "t": "μικρὸν δὲ ὑπὸ τὰ ἕλη νεώς ἐστιν Ἀπόλλωνος Τεγυραίου καὶ μαντεῖον ἐκλελειμμένον οὐ πάνυ πολὺν χρόνον, ἀλλ’ ἄχρι τῶν Μηδικῶν ἤκμαζε, τὴν προφητείαν Ἐχεκράτους ἔχοντος, ἐνταῦθα μυθολογοῦσι τὸν θεὸν γενέσθαι· καὶ τὸ μὲν πλησίον ὄρος Δῆλος καλεῖται, καὶ πρὸς αὐτὸ καταλήγουσιν αἱ τοῦ Μέλανος διαχύσεις, ὀπίσω δὲ τοῦ ναοῦ δύο ῥήγνυνται πηγαὶ γλυκύτητι καὶ πλήθει καὶ ψυχρότητι θαυμαστοῦ νάματος, ὧν τὸ μὲν Φοίνικα, τὸ δὲ Ἐλαίαν ἄχρι νῦν ὀνομάζομεν, οὐ φυτῶν μεταξὺ δυεῖν, ἀλλὰ ῥείθρων τῆς θεοῦ λοχευθείσης. καὶ γὰρ τὸ Πτῷον ἐγγύς, ὅθεν αὐτὴν ἀναπτοηθῆναι προφανέντος ἐξαίφνης κάπρου λέγουσι, καὶ τὰ περὶ Πύθωνα καὶ Τιτυὸν ὡσαύτως οἱ τόποι τῇ γενέσει τοῦ θεοῦ συνοικειοῦσι. τὰ γὰρ πλεῖστα παραλείπω τῶν τεκμηρίων· οὐ γὰρ ἐν τοῖς ἐκ μεταβολῆς ἀθανάτοις γενομένοις γεννητοῖς ὁ πάτριος λόγος τὸν θεὸν τοῦτον ἀπολείπει δαίμοσιν, ὥσπερ Ἡρακλέα καὶ Διόνυσον, ἐκ μεταβολῆς ἀρετῇ τὸ θνητὸν καὶ παθητὸν ἀποβαλόντας, ἀλλὰ τῶν ἀϊδίων καὶ ἀγεννήτων εἷς ἐστιν, εἰ δεῖ τοῖς ὑπὸ τῶν φρονιμωτάτων καὶ παλαιοτάτων λεγομένοις τεκμαίρεσθαι περὶ τῶν τηλικούτων.", "st": "Pel. 16.4"}, {"sp": "N", "t": "εἰς δ’ οὖν Τεγύρας οἱ Θηβαῖοι κατὰ τὸν αὐτὸν χρόνον ἐκ τῆς Ὀρχομενίας ἀπιόντες καί οἱ Λακεδαιμόνιοι συνέπιπτον, ἐξ ἐναντίας αὐτοῖς ἐκ τῆς Λοκρίδος ἀναζευγνύντες. ὡς δὲ πρῶτον ὤφθησαν τὰ στενὰ διεκβάλλοντες, καί τις εἶπε τῷ Πελοπίδᾳ προσδραμών· ἐμπεπτώκαμεν εἰς τοὺς πολεμίους, τί μᾶλλον, εἶπεν, ἢ εἰς ἡμᾶς ἐκεῖνοι; καί τὴν μὲν ἵππον εὐθὺς πᾶσαν ἐκέλευσε παρελαύνειν ἀπ’ οὐρᾶς ὡς προεμβαλοῦσαν, αὐτὸς δὲ τοὺς ὁπλίτας τριακοσίους ὄντας εἰς ὀλίγον συνήγαγεν, ἐλπίζων καθ’ ὃ προσβάλοι μάλιστα διακόψειν ὑπερβάλλοντας πλήθει τοὺς πολεμίους. ἦσαν δὲ δύο μόραι Λακεδαιμονίων, τὴν δὲ μόραν Ἔφορος μὲν ἄνδρας εἶναι πεντακοσίους φησί, Καλλισθένης δ’ ἑπτακοσίους, ἄλλοι δέ τινες ἐνακοσίους, ὧν Πολύβιός ἐστι. καὶ θαρροῦντες οἱ πολέμαρχοι τῶν Σπαρτιατῶν Γοργολέων καί Θεόπομπος ὥρμησαν ἐπὶ τοὺς Θηβαίους, γενομένης δέ πως μάλιστα τῆς ἐφόδου κατ’ αὐτοὺς τοὺς ἄρχοντας ἀπ’ ἀμφοτέρων μετὰ θυμοῦ καί βίας, πρῶτον μὲν οἱ πολέμαρχοι τῶν Λακεδαιμονίων τῷ Πελοπίδᾳ συρράξαντες ἔπεσον· ἔπειτα τῶν περὶ ἐκείνους παιομένων καί ἀποθνῃσκόντων ἅπαν εἰς φόβον κατέστη τὸ στράτευμα, καί διέσχε μὲν ἐπ’ ἀμφότερα τοῖς Θηβαίοις, ὡς διεκπεσεῖν εἰς τοὔμπροσθεν καί διεκδῦναι βουλομένοις, ἐπεὶ δὲ τὴν δεδομένην ὁ Πελοπίδας ἡγεῖτο πρὸς τοὺς συνεστῶτας καί διεξῄει φονεύων, οὕτω πάντες προτροπάδην ἔφευγον. ἐγένετο δὲ οὐκ ἐπὶ πολὺν τόπον ἡ δίωξις· ἐφοβοῦντο γὰρ ἐγγὺς ὄντας οἱ Θηβαῖοι τοὺς Ὀρχομενίους καί τὴν διαδοχὴν τῶν Λακεδαιμονίων. ὅσον δὲ νικῆσαι κατὰ κράτος καί διεξελθεῖν διὰ παντὸς ἡσσωμένου τοῦ στρατεύματος, ἐξεβιάσαντο· καί στήσαντες τρόπαιον καί νεκροὺς σκυλεύσαντες ἀνεχώρησαν ἐπ’ οἴκου μέγα φρονοῦντες. ἐν γὰρ τοσούτοις, ὡς ἔοικε, πολέμοις Ἑλληνικοῖς καί βαρβαρικοῖς πρότερον οὐδέποτε Λακεδαιμόνιοι πλείονες ὄντες ὑπ’ ἐλαττόνων ἐκρατήθησαν, ἀλλ’ οὐδὲ ἴσοι πρὸς ἴσους ἐκ παρατάξεως συμβαλόντες. ὅθεν ἦσαν ἀνυπόστατοι τὰ φρονήματα, καί τῇ δόξῃ καταπληττόμενοι τοὺς ἀντιταττομένους, οὐδὲ αὐτοὺς ἀξιοῦντας ἀπ’ ἴσης δυνάμεως τὸ ἴσον φέρεσθαι Σπαρτιάταις, εἰς χεῖρας συνέστησαν, ἐκείνη δὲ ἡ μάχη πρώτη καί τοὺς ἄλλους ἐδίδαξεν Ἕλληνας ὡς οὐχ ὁ Εὐρώτας οὐδ’ ὁ μεταξὺ Βαβύκας καί Κνακιῶνος τόπος ἄνδρας ἐκφέρει μαχητὰς καί πολεμικούς, ἀλλὰ παρ’ οἷς ἂν αἰσχύνεσθαι τὰ αἰσχρὰ καί τολμᾶν ἐπὶ τοῖς καλοῖς ἐθέλοντες ἐγγένωνται νέοι καί τοὺς ψόγους τῶν κινδύνων μᾶλλον φεύγοντες, οὗτοι φοβερώτατοι τοῖς ἐναντίοις εἰσί.", "st": "Pel. 17.1"}, {"sp": "N", "t": "τὸν δ’ ἱερὸν λόχον, ὥς φασι, συνετάξατο Γοργίδας πρῶτος ἐξ ἀνδρῶν ἐπιλέκτων τριακοσίων, οἷς ἡ πόλις ἄσκησιν καὶ δίαιταν ἐν τῇ Καδμείᾳ στρατοπεδευομένοις παρεῖχε, καὶ διὰ τοῦθ’ ὁ ἐκ πόλεως λόχος ἐκαλοῦντο· τὰς γὰρ ἀκροπόλεις ἐπιεικῶς οἱ τότε πόλεις ὠνόμαζον. ἔνιοι δέ φασιν ἐξ ἐραστῶν καὶ ἐρωμένων γενέσθαι τὸ σύστημα τοῦτο. καὶ Παμμένους ἀπομνημονεύεταί τι μετὰ παιδιᾶς εἰρημένον· οὐ γὰρ ἔφη τακτικὸν εἶναι τὸν Ὁμήρου Νέστορα κελεύοντα κατὰ φῦλα καὶ φρήτρας συλλοχίζεσθαι τοὺς Ἕλληνας,", "st": "Pel. 18.1"}, {"sp": "N", "t": "ὡς φρήτρη φρήτρηφιν ἀρήγῃ, φῦλα δὲ φύλοις,", "st": "Pel. 18.1b"}, {"sp": "N", "t": "δέον ἐραστὴν παρ’ ἐρώμενον τάττειν. φυλέτας μὲν γὰρ φυλετῶν καὶ φράτορας φρατόρων οὐ πολὺν λόγον ἔχειν ἐν τοῖς δεινοῖς, τὸ δ’ ἐξ ἐρωτικῆς φιλίας συνηρμοσμένον στῖφος ἀδιάλυτον εἶναι καὶ ἄρρηκτον, ὅταν οἱ μὲν ἀγαπῶντες τοὺς ἐρωμένους, οἱ δὲ αἰσχυνόμενοι τοὺς ἐρῶντας ἐμμένωσι τοῖς δεινοῖς ὑπὲρ ἀλλήλων. καὶ τοῦτο θαυμαστὸν οὐκ ἔστιν, εἴγε δὴ καὶ μὴ παρόντας αἰδοῦνται μᾶλλον ἑτέρων παρόντων, ὡς ἐκεῖνος ὁ τοῦ πολεμίου κείμενον αὑτὸν ἐπισφάττειν μέλλοντος δεόμενος καὶ ἀντιβολῶν διὰ τοῦ στέρνου διεῖναι τὸ ξίφος, ὅπως, ἔφη, μή με νεκρὸν ὁ ἐρώμενος ὁρῶν κατὰ νώτου τετρωμένον αἰσχυνθῇ. λέγεται δὲ καὶ τὸν Ἰόλεων τοῦ Ἡρακλέους ἐρώμενον ὄντα κοινωνεῖν τῶν ἄθλων καὶ παρασπίζειν. Ἀριστοτέλης δὲ καὶ καθ’ αὑτὸν ἔτι φησὶν ἐπὶ τοῦ τάφου τοῦ Ἰόλεω τὰς καταπιστώσεις ποιεῖσθαι τοὺς ἐρωμένους καὶ τοὺς ἐραστάς. εἰκὸς οὖν καὶ τὸν λόχον ἱερὸν προσαγορεύεσθαι, καθότι καὶ Πλάτων ἔνθεον φίλον τὸν ἐραστὴν προσεῖπε. λέγεται δὲ διαμεῖναι μέχρι τῆς ἐν Χαιρωνείᾳ μάχης ἀήττητον· ὡς δὲ μετὰ τὴν μάχην ἐφορῶν τοὺς νεκροὺς ὁ Φίλιππος ἔστη κατὰ τοῦτο τὸ χωρίον ἐν ᾧ συνετύγχανε κεῖσθαι τοὺς τριακοσίους, ἐναντίους ἀπηντηκότας ταῖς σαρίσαις ἅπαντας ἐν τοῖς ὅπλοις καὶ μετ’ ἀλλήλων ἀναμεμιγμένους, θαυμάσαντα καὶ πυθόμενον ὡς ὁ τῶν ἐραστῶν καὶ τῶν ἐρωμένων οὗτος εἴη λόχος, δακρῦσαι καὶ εἰπεῖν ἀπόλοιντο κακῶς οἱ τούτους τι ποιεῖν ἢ πάσχειν αἰσχρὸν ὑπονοοῦντες.", "st": "Pel. 18.3"}, {"sp": "N", "t": "ὅλως δὲ τῆς περὶ τοὺς ἐραστὰς συνηθείας οὐχ, ὥσπερ οἱ ποιηταὶ λέγουσι, Θηβαίοις τὸ Λαΐου πάθος ἀρχὴν παρέσχεν, ἀλλ’ οἱ νομοθέται τὸ φύσει θυμοειδὲς αὐτῶν καὶ ἄκρατον ἀνιέναι καὶ ἀνυγραίνειν εὐθὺς ἐκ παίδων βουλόμενοι, πολὺν μὲν ἀνεμίξαντο καὶ σπουδῇ καὶ παιδιᾷ πάσῃ τὸν αὐλόν, εἰς τιμὴν καὶ προεδρίαν ἄγοντες, λαμπρὸν δὲ τὸν ἔρωτα ταῖς παλαίστραις ἐνεθρέψαντο, συγκεραννύντες τὰ ἤθη τῶν νέων. ὀρθῶς δὲ πρὸς τοῦτο καὶ τὴν ἐξ Ἄρεως καὶ Ἀφροδίτης γεγονέναι λεγομένην θεὸν τῇ πόλει συνῳκείωσαν, ὡς, ὅπου τὸ μαχητικὸν καὶ πολεμικὸν μάλιστα τῷ μετέχοντι πειθοῦς καὶ χαρίτων ὁμιλεῖ καὶ σύνεστιν, εἰς τὴν ἐμμελεστάτην καὶ κοσμιωτάτην πολιτείαν δι’ Ἁρμονίας καθισταμένων ἁπάντων.", "st": "Pel. 19.1"}, {"sp": "N", "t": "τὸν οὖν ἱερὸν λόχον τοῦτον ὁ μὲν Γοργίδας διαιρῶν εἰς τὰ πρῶτα ζυγά καὶ παρ’ ὅλην τὴν φάλαγγα τῶν ὁπλιτῶν προβαλλόμενος ἐπίδηλον οὐκ ἐποίει τὴν ἀρετὴν τῶν ἀνδρῶν, οὐδ’ ἐχρῆτο τῇ δυνάμει πρὸς κοινὸν ἔργον, ἅτε δὴ διαλελυμένῃ καὶ πρὸς πολὺ μεμιγμένῃ τὸ φαυλότερον, ὁ δὲ Πελοπίδας, ὡς ἐξέλαμψεν αὐτῶν ἡ ἀρετὴ περὶ Τεγύρας, καθαρῶς καὶ περὶ αὐτὸν ἀγωνισαμένων, οὐκέτι διεῖλεν οὐδὲ διέσπασεν, ἀλλ’ ὥσπερ σώματι χρώμενος ὅλῳ προεκινδύνευε τοῖς μεγίστοις ἀγῶσιν. ὥσπερ γὰρ οἱ ἵπποι θᾶσσον ὑπὸ τοῖς ἅρμασιν ἢ καθ’ αὑτοὺς ἐλαυνόμενοι θέουσιν, οὐχ ὅτι μᾶλλον ἐμπίπτοντες ἐκβιάζονται τὸν ἀέρα τῷ πλήθει ῥηγνύμενον, ἀλλ’ ὅτι συνεκκαίει τὸν θυμὸν ἡ μετ’ ἀλλήλων ἅμιλλα καὶ τὸ φιλόνεικον, οὕτως ᾤετο τοὺς ἀγαθοὺς ζῆλον ἀλλήλοις καλῶν ἔργων ἐνιέντας ὠφελιμωτάτους εἰς κοινὸν ἔργον εἶναι καὶ προθυμοτάτους.", "st": "Pel. 19.3"}, {"sp": "N", "t": "ἐπεὶ δὲ Λακεδαιμόνιοι πᾶσι τοῖς Ἕλλησιν εἰρήνην συνθέμενοι πρὸς μόνους Θηβαίους ἐξήνεγκαν τὸν πόλεμον, ἐνεβεβλήκει δὲ Κλεόμβροτος ὁ βασιλεύς ἄγων ὁπλίτας μυρίους, ἱππεῖς δὲ χιλίους, ὁ δὲ κίνδυνος οὐ περὶ ὧν πρότερον ἦν Θηβαίοις, ἀλλ’ ἄντικρυς ἀπειλὴ καὶ καταγγελία διοικισμοῦ, καὶ φόβος οἷος οὔπω τὴν Βοιωτίαν κατεῖχεν, ἐξιὼν μὲν ἐκ τῆς οἰκίας ὁ Πελοπίδας, καὶ τῆς γυναικὸς ἐν τῷ προπέμπειν δακρυούσης καὶ παρακαλούσης σῴζειν ἑαυτόν, ταῦτα, εἶπεν, ὦ γύναι, τοῖς ἰδιώταις χρὴ παραινεῖν, τοῖς δὲ ἄρχουσιν ὅπως τοὺς ἄλλους σῴζωσιν· ἐλθὼν δὲ εἰς τὸ στρατόπεδον καὶ τοὺς βοιωτάρχας καταλαβὼν οὐχ ὁμογνωμονοῦντας, πρῶτος Ἐπαμεινώνδᾳ προσέθετο γνώμην ψηφιζομένῳ διὰ μάχης ἰέναι τοῖς πολεμίοις, βοιωτάρχης μὲν οὐκ ἀποδεδειγμένος, ἄρχων δὲ τοῦ ἱεροῦ λόχου, καὶ πιστευόμενος, ὡς ἦν δίκαιον ἄνδρα τηλικαῦτα δεδωκότα τῇ πατρίδι σύμβολα εἰς τὴν ἐλευθερίαν.", "st": "Pel. 20.1"}, {"sp": "N", "t": "ὡς οὖν ἐδέδοκτο διακινδυνεύειν καὶ περὶ τὰ Λεῦκτρα τοῖς Λακεδαιμονίοις ἀντεστρατοπέδευον, ὄψιν εἶδε κατὰ τοὺς ὕπνους ὁ Πελοπίδας εὖ μάλα διαταράξασαν αὐτόν, ἔστι γὰρ ἐν τῷ Λευκτρικῷ πεδίῳ τὰ σήματα τῶν τοῦ Σκεδάσου θυγατέρων, ἃς Λευκτρίδας καλοῦσι διὰ τὸν τόπον· ἐκεῖ γὰρ αὐταῖς ὑπὸ ξένων Σπαρτιατῶν βιασθείσαις συνέβη ταφῆναι. γενομένης δὲ χαλεπῆς οὕτω καὶ παρανόμου πράξεως, ὁ μὲν πατήρ, ὡς οὐκ ἔτυχεν ἐν Λακεδαίμονι δίκης, ἀρὰς κατὰ τῶν Σπαρτιατῶν ἀρασάμενος ἔσφαξεν ἑαυτὸν ἐπὶ τοῖς τάφοις τῶν παρθένων, χρησμοὶ δὲ καὶ λόγια τοῖς Σπαρτιάταις ἀεὶ προὔφαινον εὐλαβεῖσθαι καὶ φυλάττεσθαι τὸ Λευκτρικὸν μήνιμα, μὴ πάνυ τῶν πολλῶν συνιέντων, ἀλλ’ ἀμφιγνοούντων τὸν τόπον, ἐπεὶ καὶ τῆς Λακωνικῆς πολίχνιον πρὸς τῇ θαλάσσῃ Λεῦκτρον ὀνομάζεται, καὶ πρὸς Μεγάλῃ πόλει τῆς Ἀρκαδίας τόπος ἐστὶν ὁμώνυμος, τὸ μὲν οὖν πάθος τοῦτο πολὺ τῶν Λευκτρικῶν ἦν παλαιότερον.", "st": "Pel. 20.3"}, {"sp": "N", "t": "ὁ δὲ Πελοπίδας ἐν τῷ στρατοπέδῳ κατακοιμηθεὶς ἔδοξε τάς τε παῖδας ὁρᾶν περὶ τὰ μνήματα θρηνούσας καὶ καταρωμένας τοῖς Σπαρτιάταις, τόν τε Σκέδασον κελεύοντα ταῖς κόραις σφαγιάσαι παρθένον ξανθήν, εἰ βούλοιτο τῶν πολεμίων ἐπικρατῆσαι. δεινοῦ δὲ καὶ παρανόμου τοῦ προστάγματος αὐτῷ φανέντος ἐξαναστὰς ἐκοινοῦτο τοῖς τε μάντεσι καὶ τοῖς ἄρχουσιν. ὧν οἱ μὲν οὐκ εἴων παραμελεῖν οἱ δ’· ἀπειθεῖν, τῶν μὲν παλαιῶν προφέροντες Μενοικέα τόν Κρέοντος καὶ Μακαρίαν τὴν Ἡρακλέους, τῶν δ’ ὕστερον Φερεκύδην τε τόν σοφὸν ὑπὸ Λακεδαιμονίων ἀναιρεθέντα καὶ τὴν δορὰν αὐτοῦ κατά τι λόγιον ὑπὸ τῶν βασιλέων φρουρουμένην, Λεωνίδαν τε τῷ χρησμῷ τρόπον τινὰ προθυσάμενον ἑαυτὸν ὑπὲρ τῆς Ἑλλάδος, ἔτι δὲ τοὺς ὑπὸ Θεμιστοκλέους σφαγιασθέντας Ὠμηστῇ Διονύσῳ πρὸ τῆς ἐν Σαλαμῖνι ναυμαχίας· ἐκείνοις γὰρ ἐπιμαρτυρῆσαι τὰ κατορθώματα· τοῦτο δέ, ὡς Ἀγησίλαον ἀπὸ τῶν αὐτῶν Ἀγαμέμνονι τόπων ἐπὶ τοὺς αὐτοὺς στρατευόμενον πολεμίους ᾔτησε μὲν ἡ θεὸς τὴν θυγατέρα σφάγιον καὶ ταύτην εἶδε τὴν ὄψιν ἐν Αὐλίδι κοιμώμενος, ὁ δ’ οὐκ ἔδωκεν, ἀλλ’ ἀπομαλθακωθεὶς κατέλυσε τὴν στρατείαν ἄδοξον καὶ ἀτελῆ γενομένην. οἱ δὲ τοὐναντίον ἀπηγόρευον, ὡς οὐδενὶ τῶν κρειττόνων καὶ ὑπὲρ ἡμᾶς ἀρεστὴν οὖσαν οὕτω βάρβαρον καὶ παράνομον θυσίαν· οὐ γὰρ τοὺς Τυφῶνας ἐκείνους οὐδὲ τοὺς Γίγαντας ἄρχειν, ἀλλὰ τόν πάντων πατέρα θεῶν καὶ ἀνθρώπων· δαίμονας δὲ χαίροντας ἀνθρώπων αἵματι καὶ φόνῳ πιστεύειν μὲν ἴσως ἐστὶν ἀβέλτερον, ὄντων δὲ τοιούτων ἀμελητέον ὡς ἀδυνάτων· ἀσθενείᾳ γὰρ καὶ μοχθηρίᾳ ψυχῆς ἐμφύεσθαι καὶ παραμένειν τάς ἀτόπους καὶ χαλεπὰς ἐπιθυμίας.", "st": "Pel. 21.1"}, {"sp": "N", "t": "ἐν τοιούτοις οὖν διαλόγοις τῶν πρώτων ὄντων, καὶ μάλιστα τοῦ Πελοπίδου διαποροῦντος, ἵππων ἐξ ἀγέλης πῶλος ἀποφυγοῦσα καὶ φερομένη διὰ τῶν ὅπλων, ὡς ἦν θέουσα κατ’ αὐτοὺς ἐκείνους, ἐπέστη· καὶ τοῖς μὲν ἄλλοις θέαν παρεῖχεν ἥ τε χρόα στίλβουσα τῆς χαίτης πυρσότατον ἥ τε γαυρότης καὶ τὸ σοβαρὸν καὶ τεθαρρηκὸς τῆς φωνῆς, Θεόκριτος δὲ ὁ μάντις συμφρονήσας ἀνεβόησε πρὸς τὸν Πελοπίδαν ἥκει σοι τὸ ἱερεῖον, ὦ δαιμόνιε, καὶ παρθένον ἄλλην μὴ περιμένωμεν, ἀλλὰ χρῶ δεξάμενος ἣν ὁ θεὸς δίδωσιν. ἐκ τούτου λαβόντες τὴν ἵππον ἐπὶ τοὺς τάφους ἦγον τῶν παρθένων, καὶ κατευξάμενοι καὶ καταστέψαντες ἐνέτεμον αὐτοί τε χαίροντες καὶ λόγον εἰς τὸ στρατόπεδον περὶ τῆς ὄψεως τοῦ Πελοπίδου καὶ τῆς θυσίας διδόντες.", "st": "Pel. 22.1"}, {"sp": "N", "t": "ἐν δὲ τῇ μάχῃ τοῦ Ἐπαμεινώνδου τὴν φάλαγγα λοξὴν ἐπὶ τὸ εὐώνυμον ἕλκοντος, ὅπως τῶν ἄλλων Ἑλλήνων ἀπωτάτω γένηται τὸ δεξιὸν τῶν Σπαρτιατῶν καὶ τὸν Κλεόμβροτον ἐξώσῃ προσπεσὼν ἀθρόως κατὰ κέρας καὶ βιασάμενος, οἱ μὲν πολέμιοι καταμαθόντες τὸ γινόμενον ἤρξαντο μετακινεῖν τῇ τάξει σφᾶς αὐτοὺς, καὶ τὸ δεξιὸν ἀνέπτυσσον καὶ περιῆγον ὡς κυκλωσόμενοι καὶ περιβαλοῦντες ὑπὸ πλήθους τὸν Ἐπαμεινώνδαν, ὁ δὲ Πελοπίδας ἐν τούτῳ προεξέδραμε, καὶ συστρέψας τοὺς τριακοσίους δρόμῳ φθάνει πρὶν ἀνατεῖναι τὸν Κλεόμβροτον τὸ κέρας ἢ συναγαγεῖν πάλιν εἰς τὸ αὐτὸ καὶ συγκλεῖσαι τὴν τάξιν, οὐ καθεστῶσιν, ἀλλὰ θορυβουμένοις δι’ ἀλλήλων τοῖς Λακεδαιμονίοις ἐπιβαλών. καίτοι πάντων ἄκροι τεχνῖται καὶ σοφισταὶ τῶν πολεμικῶν ὄντες οἱ Σπαρτιᾶται πρὸς οὐδὲν οὕτως ἐπαίδευον αὑτοὺς καὶ συνείθιζον, ὡς τὸ μὴ πλανᾶσθαι μηδὲ ταράττεσθαι τάξεως διαλυθείσης, ἀλλὰ χρώμενοι πᾶσι πάντες ἐπιστάταις καὶ ζευγίταις, ὅποι ποτὲ καὶ συνίστησιν ὁ κίνδυνος, καταλαμβάνειν καὶ συναρμόττειν καὶ μάχεσθαι παραπλησίως. τότε δὲ ἡ τοῦ Ἐπαμεινώνδου φάλαγξ ἐπιφερομένη μόνοις ἐκείνοις καὶ παραλλάττουσα τοὺς ἄλλους, ὅ τε Πελοπίδας μετὰ τάχους ἀπίστου καὶ τόλμης ἐν τοῖς ὅπλοις γενόμενος, συνέχεον τά τε φρονήματα καὶ τὰς ἐπιστήμας αὐτῶν οὕτως ὥστε φυγὴν καὶ φόνον Σπαρτιατῶν ὅσον οὔπω πρότερον γενέσθαι, διὸ τῷ Ἐπαμεινώνδᾳ βοιωταρχοῦντι μὴ βοιωταρχῶν, καὶ πάσης ἡγουμένῳ τῆς δυνάμεως μικροῦ μέρους ἄρχων. ἴσον ἠνέγκατο δόξης τῆς νίκης ἐκείνης καὶ τοῦ κατορθώματος.", "st": "Pel. 23.1"}, {"sp": "N", "t": "εἰς μέντοι Πελοπόννησον ἀμφότεροι βοιωταρχοῦντες ἐνέβαλον καὶ τῶν ἐθνῶν τὰ πλεῖστα προσήγοντο, Λακεδαιμονίων ἀποστήσαντες Ἦλιν, Ἄργος, Ἀρκαδίαν σύμπασαν, αὐτῆς τῆς Λακωνικῆς τὰ πλεῖστα, καίτοι χειμῶνος μὲν ἦσαν αἱ περὶ τροπὰς ἀκμαί, μηνὸς δὲ τοῦ τελευταίου φθίνοντος ὀλίγαι περιῆσαν ἡμέραι, καὶ τὴν ἀρχὴν ἔδει παραλαμβάνειν ἑτέρους εὐθὺς ἱσταμένου τοῦ πρώτου μηνός, ἢ θνῄσκειν τοὺς μὴ παραδιδόντας. οἱ δὲ ἄλλοι βοιωτάρχαι καὶ τὸν νόμον δεδιότες τοῦτον καὶ τὸν χειμῶνα φεύγοντες ἀπάγειν ἔσπευδον ἐπ’ οἴκου τὸ στράτευμα, Πελοπίδας δὲ πρῶτος Ἐπαμεινώνδᾳ γενόμενος σύμψηφος καὶ συμπαρορμήσας τοὺς πολίτας ἦγεν ἐπὶ τὴν Σπάρτην καὶ διεβίβαζε τὸν Εὐρώταν. καὶ πολλὰς μὲν ᾕρει πόλεις αὐτῶν, πᾶσαν δὲ τὴν χώραν ἐπόρθει μέχρι θαλάττης, ἡγούμενος ἑπτὰ μυριάδων Ἑλληνικῆς στρατιᾶς, ἧς ἔλαττον ἢ δωδέκατον ἦσαν αὐτοὶ Θηβαῖοι μέρος. ἀλλ’ ἡ δόξα τῶν ἀνδρῶν ἄνευ δόγματος κοινοῦ καὶ ψηφίσματος ἐποίει τοὺς συμμάχους ἕπεσθαι σιωπῇ πάντας ἡγουμένοις ἐκείνοις. ὁ γὰρ πρῶτος, ὡς ἔοικε, καὶ κυριώτατος νόμος τῷ σῴζεσθαι δεομένῳ τὸν σῴζειν δυνάμενον ἄρχοντα κατὰ φύσιν ἀποδίδωσι· κἂν ὥσπερ οἱ πλέοντες εὐδίας οὔσης ἢ παρ’ ἀκτὴν ὁρμοῦντες ἀσελγῶς προσενεχθῶσι τοῖς κυβερνήταις καὶ θρασέως, ἅμα τῷ χειμῶνα καὶ κίνδυνον καταλαμβάνειν πρὸς ἐκείνους ἀποβλέπουσι καὶ τὰς ἐλπίδας ἐν ἐκείνοις ἔχουσι. καὶ γὰρ Ἀργεῖοι καὶ Ἠλεῖοι καὶ Ἀρκάδες ἐν τοῖς συνεδρίοις ἐρίζοντες καὶ διαφερόμενοι πρὸς τοὺς Θηβαίους ὑπὲρ ἡγεμονίας, ἐπ’ αὐτῶν τῶν ἀγώνων καὶ παρὰ τὰ δεινὰ τοῖς ἐκείνων αὐθαιρέτως πειθόμενοι στρατηγοῖς ἠκολούθουν.", "st": "Pel. 24.1"}, {"sp": "N", "t": "ἐν ἐκείνῃ τῇ στρατείᾳ πᾶσαν μὲν Ἀρκαδίαν εἰς μίαν δύναμιν συνέστησαν, τὴν δὲ Μεσσηνίαν χώραν νεμομένων Σπαρτιατῶν ἀποτεμόμενοι τοὺς παλαιοὺς Μεσσηνίους ἐκάλουν καὶ κατῆγον Ἰθώμην συνοικίσαντες, ἀπιόντες δὲ ἐπ’ οἴκου διὰ Κεγχρεῶν Ἀθηναίους ἐνίκων ἐπιχειροῦντας ἁψιμαχεῖν περὶ τὰ στενὰ καὶ κωλύειν τὴν πορείαν.", "st": "Pel. 24.5"}, {"sp": "N", "t": "ἐπὶ δὲ τούτοις οἱ μὲν ἄλλοι πάντες ὑπερηγάπων τὴν ἀρετὴν καὶ τὴν τύχην ἐθαύμαζον, ὁ δὲ συγγενὴς καὶ πολιτικὸς φθόνος ἅμα τῇ δόξῃ τῶν ἀνδρῶν συναυξόμενος οὐ καλὰς οὐδὲ πρεπούσας ὑποδοχὰς παρεσκεύαζεν αὐτοῖς. θανάτου γὰρ ἀμφότεροι δίκας ἔφυγον ἐπανελθόντες, ὅτι τοῦ νόμου κελεύοντος ἐν τῷ πρώτῳ μηνὶ παραδοῦναι τὴν βοιωταρχίαν ἑτέροις, ὃν Βουκάτιον ὀνομάζουσι, τέτταρας ὅλους προσεπεβάλοντο μῆνας, ἐν οἷς τὰ περὶ Μεσσήνην καὶ Ἀρκαδίαν καὶ τὴν Λακωνικὴν διῴκησαν.", "st": "Pel. 25.1"}, {"sp": "N", "t": "εἰσήχθη μὲν οὖν πρότερος εἰς τὸ δικαστήριον Πελοπίδας, διὸ καὶ μᾶλλον ἐκινδύνευσεν, ἀμφότεροι δὲ ἀπελύθησαν. τὸ δὲ συκοφάντημα καὶ τὴν πεῖραν Ἐπαμεινώνδας ἤνεγκε πρᾴως, μέγα μέρος ἀνδρείας καὶ μεγαλοψυχίας τὴν ἐν τοῖς πολιτικοῖς ἀνεξικακίαν ποιούμενος, Πελοπίδας δὲ καὶ φύσει θυμοειδέστερος ὤν, καὶ παροξυνόμενος ὑπὸ τῶν φίλων ἀμύνασθαι τοὺς ἐχθρούς, ἐπελάβετο τοιαύτης αἰτίας. Μενεκλείδας ὁ ῥήτωρ ἦν μὲν εἷς τῶν μετὰ Πελοπίδου καὶ Μέλωνος εἰς τὴν Χάρωνος οἰκίαν συνελθόντων, ἐπεὶ δὲ τῶν ἴσων οὐκ ἠξιοῦτο παρὰ τοῖς Θηβαίοις, δεινότατος μὲν ὢν λέγειν, ἀκόλαστος δὲ καὶ κακοήθης τὸν τρόπον, ἐχρῆτο τῇ φύσει πρὸς τὸ συκοφαντεῖν καὶ διαβάλλειν τοὺς κρείττονας, οὐδὲ μετὰ δίκην ἐκείνην παυσάμενος. Ἐπαμεινώνδαν μὲν οὖν ἐξέκρουσε τῆς βοιωταρχίας καὶ κατεπολιτεύσατο πολὺν χρόνον, Πελοπίδαν δὲ πρὸς μὲν τὸν δῆμον οὐκ ἴσχυσε διαβαλεῖν, ἐπεχείρει δὲ συγκροῦσαι τῷ Χάρωνι·", "st": "Pel. 25.2"}, {"sp": "N", "t": "καὶ κοινήν τινα τοῦ φθόνου παραμυθίαν ἔχοντος, ἂν ὧν αὐτοὶ μὴ δύνανται βελτίους φανῆναι, τούτους ἁμῶς γέ πως ἑτέρων ἀποδείξωσι κακίους, πολὺς ἦν πρὸς τὸν δῆμον αὔξων τὰ τὸν Χάρωνος ἔργα, καὶ τὰς στρατηγίας τὰς ἐκείνου καὶ τὰς νίκας ἐγκωμιάζων. τῆς δὲ πρὸς Πλαταιὰς ἱππομαχίας, ἣν πρὸ τῶν Λευκτρικῶν ἐνίκησαν ἡγουμένου Χάρωνος, ἐπεχείρησεν ἀνάθημα τοιόνδε ποιῆσαι. Ἀνδροκύδης ὁ Κυζικηνὸς ἐκλαβὼν παρὰ τῆς πόλεως πίνακα γράψαι μάχης ἑτέρας, ἐπετέλει τὸ ἔργον ἐν Θήβαις γενομένης δὲ τῆς ἀποστάσεως καὶ τοῦ πολέμου συμπεσόντος, οὐ πολὺ τοῦ τέλος ἔχειν ἐλλείποντα τὸν πίνακα παρ’ ἑαυτοῖς οἱ Θηβαῖοι κατέσχον. τοῦτον οὖν ὁ Μενεκλείδας ἔπεισεν ἀναθέντας ἐπιγράψαι τοὔνομα τοῦ Χάρωνος, ὡς ἀμαυρώσων τὴν Πελοπίδου καὶ Ἐπαμεινώνδου δόξαν.", "st": "Pel. 25.5"}, {"sp": "N", "t": "ἦν δὲ ἀβέλτερος ἡ φιλοτιμία, παρὰ τοσούτους καὶ τηλικούτους ἀγῶνας ἑνὸς ἔργου καὶ μιᾶς νίκης ἀγαπωμένης, ἐν ᾗ Γεράνδαν τινὰ τῶν ἀσήμων Σπαρτιατῶν καὶ τεσσαράκοντα μετ’ αὐτοῦ πεσεῖν, ἄλλο δὲ οὐδὲν μέγα πραχθῆναι λέγουσι. τοῦτο τὸ ψήφισμα γράφεται Πελοπίδας παρανόμων, ἰσχυριζόμενος ὅτι Θηβαίοις οὐ πάτριον ἦν ἰδίᾳ κατ’ ἄνδρα τιμᾶν, ἀλλὰ τῇ πατρίδι κοινῶς τὸ τῆς νίκης ὄνομα σῴζειν. καὶ τὸν μὲν Χάρωνα παρὰ πᾶσαν τὴν δίκην ἐγκωμιάζων ἀφθόνως διετέλεσε, τὸν δὲ Μενεκλείδαν βάσκανον καὶ πονηρὸν ἐξελέγχων, καὶ τοὺς Θηβαίους ἐρωτῶν εἰ μηδὲν αὐτοῖς καλὸν πέπρακται, ὥστε Μενεκλείδαν ζημιῶσαι χρήμασιν, ἃ μὴ δυνάμενος ἐκτῖσαι διὰ πλῆθος, ὕστερον ἐπεχείρησε κινῆσαι καὶ μεταστῆσαι τὴν πολιτείαν. ταῦτα μὲν οὖν ἔχει τινὰ καὶ τοῦ βίου ἀποθεώρησιν.", "st": "Pel. 25.7"}, {"sp": "N", "t": "ἐπεὶ δὲ Ἀλεξάνδρου τοῦ Φερῶν τυράννου πολεμοῦντος μὲν ἐκ προδήλου πολλοῖς Θετταλῶν, ἐπιβουλεύοντος δὲ πᾶσιν, ἐπρέσβευσαν εἰς Θήβας αἱ πόλεις στρατηγὸν αἰτούμεναι καὶ δύναμιν, ὁρῶν ὁ Πελοπίδας τὸν Ἐπαμεινώνδαν τὰς ἐν Πελοποννήσῳ πράξεις διοικεῖν, αὐτὸς ἑαυτὸν ἐπέδωκε καὶ προσένειμε τοῖς Θεσσαλοῖς, μήτε τήν ἰδίαν ἐπιστήμην καὶ δύναμιν ἀργοῦσαν περιορᾶν ὑπομένων, μήτε ὅπου πάρεστιν Ἐπαμεινώνδας ἑτέρου δεῖσθαι στρατηγοῦ νομίζων. ὡς οὖν ἐστράτευσεν ἐπὶ Θεσσαλίαν μετὰ δυνάμεως, τήν τε Λάρισσαν εὐθὺς παρέλαβε, καὶ τὸν Ἀλέξανδρον ἐλθόντα καὶ δεόμενον διαλλάττειν ἐπειρᾶτο καὶ ποιεῖν ἐκ τυράννου πρᾷον ἄρχοντα τοῖς Θεσσαλοῖς καὶ νόμιμον. ὡς δὲ ἦν ἀνήκεστος καὶ θηριώδης καὶ πολλὴ μὲν ὠμότης αὐτοῦ, πολλὴ δὲ ἀσέλγεια καὶ πλεονεξία κατηγορεῖτο, τραχυνομένου τοῦ Πελοπίδου πρὸς αὐτὸν καὶ χαλεπαίνοντος ἀποδρὰς ᾤχετο μετὰ τῶν δορυφόρων. ὁ δὲ Πελοπίδας ἄδειάν τε πολλὴν ἀπὸ τοῦ τυράννου τοῖς Θεσσαλοῖς ἀπολιπὼν καὶ πρὸς ἀλλήλους ὁμόνοιαν, αὐτὸς εἰς Μακεδονίαν ἀπῆρε, Πτολεμαίου μὲν Ἀλεξάνδρῳ τῷ βασιλεύοντι τῶν Μακεδόνων πολεμοῦντος, ἀμφοτέρων δὲ μεταπεμπομένων ἐκεῖνον ὡς διαλλακτὴν καὶ δικαστὴν καὶ σύμμαχον καὶ βοηθὸν τοῦ δοκοῦντος ἀδικεῖσθαι γενησόμενον. ἐλθὼν δὲ καὶ διαλύσας τὰς διαφορὰς καὶ καταγαγὼν τοὺς φεύγοντας, ὅμηρον ἔλαβε τὸν ἀδελφὸν τοῦ βασιλέως Φίλιππον καὶ τριάκοντα παῖδας ἄλλους τῶν ἐπιφανεστάτων, καὶ κατέστησεν εἰς Θήβας, ἐπιδειξάμενος τοῖς Ἕλλησιν ὡς πόρρω διήκει τὰ Θηβαίων πράγματα τῇ δόξῃ τῆς δυνάμεως καὶ τῇ πίστει τῆς δικαιοσύνης.", "st": "Pel. 26.1"}, {"sp": "N", "t": "οὗτος ἦν Φίλιππος ὁ τοῖς Ἕλλησιν ὕστερον πολεμήσας ὑπὲρ τῆς ἐλευθερίας, τότε δὲ παῖς ὢν ἐν Θήβαις παρὰ Παμμένει δίαιταν εἶχεν. ἐκ δὲ τούτου καὶ ζηλωτὴς γεγονέναι ἔδοξεν Ἐπαμεινώνδου, τὸ περὶ τοὺς πολέμους καὶ τὰς στρατηγίας δραστήριον ἴσως κατανοήσας, ὃ μικρὸν ἦν τῆς τοῦ ἀνδρὸς ἀρετῆς μόριον, ἐγκρατείας δὲ καὶ δικαιοσύνης καὶ μεγαλοψυχίας καὶ πρᾳότητος, οἷς ἦν ἀληθῶς μέγας ἐκεῖνος, οὐδὲν οὔτε φύσει Φίλιππος οὔτε μιμήσει μετέσχε.", "st": "Pel. 26.5"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα πάλιν τῶν Θετταλῶν αἰτιωμένων τὸν Φεραῖον Ἀλέξανδρον ὡς διαταράττοντα τὰς πόλεις, ἀπεστάλη Μετὰ Ἰσμηνίου πρεσβεύων ὁ Πελοπίδας· καὶ παρῆν οὔτε οἴκοθεν ἄγων δύναμιν οὔτε πόλεμον προσδοκήσας, αὐτοῖς δὲ τοῖς Θετταλοῖς χρῆσθαι πρὸς τὸ κατεπεῖγον τῶν πραγμάτων ἀναγκαζόμενος. ἐν τούτῳ δὲ πάλιν τῶν κατὰ Μακεδονίαν ταραττομένων ὁ γὰρ Πτολεμαῖος ἀνῃρήκει τὸν βασιλέα καὶ τὴν ἀρχὴν κατέσχεν, οἱ δὲ φίλοι τοῦ τεθνηκότος ἐκάλουν τὸν Πελοπίδαν, βουλόμενος μὲν ἐπιφανῆναι τοῖς πράγμασιν, ἰδίους δὲ στρατιώτας οὐκ ἔχων, μισθοφόρους τινὰς αὐτόθεν προσλαβόμενος Μετὰ τούτων εὐθὺς ἐβάδιζεν ἐπὶ τὸν Πτολεμαῖον. ὡς δ’ ἐγγὺς ἀλλήλων ἐγένοντο, τοὺς μὲν μισθοφόρους Πτολεμαῖος χρήμασι διαφθείρας ἔπεισεν ὡς αὐτὸν μεταστῆναι, τοῦ δὲ Πελοπίδου τὴν δόξαν αὐτὴν καὶ τοὔνομα δεδοικώς ἀπήντησεν ὡς κρείσσονι, καὶ δεξιωσάμενος καὶ δεηθεὶς ὡμολόγησε τὴν μὲν ἀρχὴν τοῖς τοῦ τεθνηκότος ἀδελφοῖς διαφυλάξειν, Θηβαίοις δὲ τὸν αὐτὸν ἐχθρὸν ἕξειν καὶ φίλον ὁμήρους δ’ ἐπὶ τούτοις τὸν υἱὸν Φιλόξενον ἔδωκε καὶ πεντήκοντα τῶν ἑταίρων. τούτους μὲν οὖν ἀπέστειλεν εἰς Θήβας ὁ Πελοπίδας, αὐτὸς δὲ βαρέως φέρων τὴν τῶν μισθοφόρων προδοσίαν, καὶ πυνθανόμενος τὰ πλεῖστα τῶν χρημάτων αὐτοῖς καὶ παῖδας καὶ γυναῖκας ἀποκεῖσθαι περὶ Φάρσαλον, ὥστε τούτων κρατήσας ἱκανὴν δίκην ὧν καθύβρισται λήψεσθαι, συναγαγὼν τῶν Θεσσαλῶν τινας ἧκεν εἰς Φάρσαλον. ἀρτίως δ’ αὐτοῦ παρεληλυθότος Ἀλέξανδρος ὁ τύραννος ἐπεφαίνετο Μετὰ τῆς δυνάμεως. καὶ νομίσαντες οἱ περὶ τὸν Πελοπίδαν ἀπολογησόμενον ἥκειν ἐβάδιζον αὐτοὶ πρὸς αὐτόν, ἐξώλη μὲν ὄντα καὶ μιαιφόνον εἰδότες, διὰ δὲ τὰς Θήβας καὶ τὸ περὶ αὐτοὺς ἀξίωμα καὶ δόξαν οὐδὲν ἂν παθεῖν προσδοκήσαντες. ὁ δέ, ὡς εἶδεν ἀνόπλους καὶ μόνους προσιόντας, ἐκείνους μὲν εὐθὺς συνέλαβε, τὴν δὲ Φάρσαλον κατέσχε, φρίκην δὲ καὶ φόβον ἐνειργάσατο τοῖς ὑπηκόοις πᾶσιν ὥς γε μετά τὴν τηλικαύτην ἀδικίαν καὶ τόλμαν ἀφειδήσων ἁπάντων, καὶ χρησόμενος οὕτω τοῖς παραπίπτουσιν ἀνθρώποις καὶ πράγμασιν ὡς τότε γε κομιδῇ τὸν ἑαυτοῦ βίον ἀπεγνωκώς.", "st": "Pel. 27.1"}, {"sp": "N", "t": "οἱ μὲν οὖν Θηβαῖοι ταῦτα ἀκούσαντες ἔφερόν βαρέως καὶ στρατιὰν ἐξέπεμπον εὐθύς, δι’ ὀργήν τινα πρὸς τὸν Ἐπαμεινώνδαν ἑτέρους ἀποδείξαντες ἄρχοντας, τὸν δὲ Πελοπίδαν εἰς τὰς Φερὰς ἀπαγαγὼν ὁ τύραννος τὸ μὲν πρῶτον εἴα τοὺς βουλομένους αὐτῷ διαλέγεσθαι, νομίζων ἐλεεινὸν γεγονέναι καὶ ταπεινὸν ὑπὸ τῆς συμφορᾶς· ἐπεὶ δὲ τοὺς μὲν Φεραίους ὁ Πελοπίδας ὀδυρομένους παρεκάλει θαρρεῖν, ὡς νῦν μάλιστα δώσοντος τοῦ τυράννου δίκην, πρὸς δὲ αὐτὸν ἐκεῖνον ἀποστείλας ἔλεγεν ὡς ἄτοπός ἐστι τοὺς μὲν ἀθλίους πολίτας καὶ μηδὲν ἀδικοῦντας ὁσημέραι στρεβλῶν καὶ φονεύων, αὐτοῦ δὲ φειδόμενος, ὃν μάλιστα γινώσκει τιμωρησόμενον αὐτὸν ἄνπερ διαφύγῃ, θαυμάσας τὸ φρόνημα καὶ τὴν ἄδειαν αὐτοῦ, τί δέ, φησὶ, σπεύδει Πελοπίδας ἀποθανεῖν; κἀκεῖνος ἀκούσας, ὅπως, εἶπε, σὺ τάχιον ἀπολῇ, μᾶλλον ἢ νῦν θεομισὴς γενόμενος. ἐκ τούτου διεκώλυσεν ἐντυγχάνειν αὐτῷ τοὺς ἐκτός.", "st": "Pel. 28.1"}, {"sp": "N", "t": "ἡ δὲ Θήβη, θυγάτηρ μὲν Ἰάσονος οὖσα, γυνὴ δὲ Ἀλεξάνδρου, πυνθανομένη παρὰ τῶν φυλαττόντων Πελοπίδαν τὸ θαρραλέον αὐτοῦ καὶ γενναῖον, ἐπεθύμησεν ἰδεῖν τὸν ἄνδρα καὶ προσειπεῖν. ὡς δὲ ἦλθε πρὸς αὐτόν καὶ ἅτε δὴ γυνὴ τὸ μὲν μέγεθος τοῦ ἤθους οὐκ εὐθὺς ἐν τοσαύτῃ συμφορᾷ κατεῖδε, κουρᾷ δὲ καὶ στολῇ καὶ διαίτῃ τεκμαιρομένη λυπρὰ καὶ μὴ πρέποντα τῇ δόξῃ πάσχειν αὐτόν ἀπεδάκρυσε, τὸ μὲν πρῶτον ἀγνοῶν ὁ Πελοπίδας τίς εἴη γυναικῶν, ἐθαύμαζεν, ὡς δὲ ἔγνω, προσηγόρευσεν αὐτὴν πατρόθεν ἦν γὰρ τῷ Ἰάσονι συνήθης καὶ φίλος, εἰπούσης δὲ ἐκείνης, ἐλεῶ σου τὴν γυναῖκα, καὶ γὰρ ἐγώ σε, εἶπεν, ὅτι ἄδετος οὖσα ὑπομένεις Ἀλέξανδρον. οὗτος ἔθιγέ πως ὁ λόγος τῆς γυναικός· ἐβαρύνετο γὰρ τὴν ὠμότητα καὶ τὴν ὕβριν τοῦ τυράννου, μετὰ τῆς ἄλλης ἀσελγείας καὶ τὸν νεώτατον αὐτῆς τῶν ἀδελφῶν παιδικὰ πεποιημένου. διὸ καὶ συνεχῶς φοιτῶσα πρὸς τὸν Πελοπίδαν καὶ παρρησιαζομένη περὶ ὧν ἔπασχεν ὑπεπίμπλατο θυμοῦ καὶ φρονήματος καὶ δυσμενείας πρὸς τὸν Ἀλέξανδρον.", "st": "Pel. 28.4"}, {"sp": "N", "t": "ἐπεὶ δὲ οἱ στρατηγοὶ τῶν Θηβαίων εἰς τὴν Θετταλίαν ἐμβαλόντες ἔπραξαν οὐδέν, ἀλλὰ δι’ ἀπειρίαν ἢ δυστυχίαν αἰσχρῶς ἀνεχώρησαν, ἐκείνων μὲν ἕκαστον ἡ πόλις μυρίαις δραχμαῖς ἐζημίωσεν, Ἐπαμεινώνδαν δὲ μετὰ δυνάμεως ἀπέστειλεν. εὐθὺς οὖν κίνησίς τις μεγάλη Θετταλῶν ἦν ἐπαιρομένων πρὸς τὴν δόξαν τοῦ στρατηγοῦ, καὶ τὰ πράγματα τοῦ τυράννου ῥοπῆς ἐδεῖτο μικρᾶς ἀπολωλέναι· τοσοῦτος ἐνεπεπτώκει φόβος τοῖς περὶ αὐτὸν ἡγεμόσι καὶ φίλοις, τοσαύτη δὲ τοὺς ὑπηκόους ὁρμὴ πρὸς ἀπόστασιν εἶχε καὶ χαρὰ τοῦ μέλλοντος, ὡς νῦν ἐποψομένους δίκην διδόντα τὸν τύραννον. οὐ μὴν ἀλλ’ Ἐπαμεινώνδας τὴν αὐτοῦ δόξαν ἐν ὑστέρῳ τῆς Πελοπίδου σωτηρίας τιθέμενος, καὶ δεδοικὼς μὴ τῶν πραγμάτων ταραχθέντων ἀπογνοὺς ἑαυτὸν Ἀλέξανδρος ὥσπερ θηρίον τράπηται πρὸς ἐκεῖνον, ἐπῃωρεῖτο τῷ πολέμῳ, καὶ κύκλῳ περιϊὼν, τῇ παρασκευῇ καὶ τῇ μελλήσει κατεσκεύαζε καὶ συνέστελλε τὸν τύραννον, ὡς μήτε ἀντεῖναι τὸ αὔθαδες αὐτοῦ καὶ θρασυνόμενον μήτε τὸ πικρὸν καὶ θυμοειδὲς ἐξερεθίσαι, πυνθανόμενος τὴν ὠμότητα καὶ τὴν ὀλιγωρίαν τῶν καλῶν καὶ δικαίων, ὡς ζῶντας μὲν ἀνθρώπους κατώρυττεν, ἑτέροις δὲ δέρματα συῶν ἀγρίων καὶ ἄρκτων περιτιθεὶς καὶ τοὺς θηρατικοὺς ἐπάγων κύνας καὶ διέσπα καὶ κατηκόντιζε, παιδιᾷ ταύτῃ χρώμενος, Μελιβοίᾳ δὲ καὶ Σκοτούσῃ, πόλεσιν ἐνσπόνδοις καὶ φίλαις, ἐκκλησιαζούσαις περιστήσας ἅμα τοὺς δορυφόρους ἡβηδὸν ἀπέσφαξε, τὴν δὲ λόγχην ᾗ Πολύφρονα τὸν θεῖον ἀπέκτεινε καθιερώσας καὶ καταστέψας, ἔθυεν ὥσπερ θεῷ καὶ Τύχωνα προσηγόρευε. τραγῳδὸν δέ ποτε θεώμενος Εὐριπίδου Τρῳάδας ὑποκρινόμενον ᾤχετο ἀπιὼν ἐκ τοῦ θεάτρου, καὶ πέμψας πρὸς αὐτὸν ἐκέλευε θαρρεῖν καὶ μηδὲν ἀγωνίζεσθαι διὰ τοῦτο χεῖρον, οὐ γὰρ ἐκείνου καταφρονῶν ἀπελθεῖν, ἀλλ’ αἰσχυνόμενος τοὺς πολίτας, εἰ μηδένα πώποτε τῶν ὑπ’ αὐτοῦ φονευομένων ἠλεηκώς, ἐπὶ τοῖς Ἑκάβης καὶ Ἀνδρομάχης κακοῖς ὀφθήσεται δακρύων. οὗτος μέντοι τὴν δόξαν αὐτὴν καὶ τοὔνομα καὶ τὸ πρόσχημα τῆς Ἐπαμεινώνδου στρατηγίας καταπλαγείς,", "st": "Pel. 29.1"}, {"sp": "N", "t": "ἔπτηξ’ ἀλέκτωρ δοῦλος ὣς κλίνας πτερόν,", "st": "Pel. 29.1b"}, {"sp": "N", "t": "καὶ τοὺς ἀπολογησομένους ταχὺ πρὸς αὐτὸν ἔπεμπεν. ὁ δὲ συνθέσθαι μὲν εἰρήνην καὶ φιλίαν πρὸς τοιοῦτον ἄνδρα Θηβαίοις οὐχ ὑπέμεινε, σπεισάμενος δέ τριακονθημέρους ἀνοχὰς τοῦ πολέμου καὶ λαβὼν τὸν Πελοπίδαν καὶ τὸν Ἰσμηνίαν ἀνεχώρησεν.", "st": "Pel. 29.1c"}, {"sp": "N", "t": "οἱ δὲ Θηβαῖοι παρὰ τῶν Λακεδαιμονίων καὶ τῶν Ἀθηναίων αἰσθόμενοι πρὸς τὸν μέγαν βασιλέα πρέσβεις ἀναβαίνοντας ὑπὲρ συμμαχίας, ἔπεμψαν καὶ αὐτοὶ Πελοπίδαν, ἄριστα βουλευσάμενοι πρὸς τὴν δόξαν αὐτοῦ. πρῶτον μὲν γὰρ ἀνέβαινε διὰ τῶν βασιλέως ἐπαρχιῶν ὀνομαστὸς ὢν καὶ περιβόητος· οὐ γὰρ ἠρέμα διῖκτο τῆς Ἀσίας οὐδ’ ἐπὶ μικρὸν ἡ δόξα τῶν πρὸς Λακεδαιμονίους ἀγώνων, ἀλλ’, ὡς πρῶτος περὶ τῆς ἐν Λεύκτροις μάχης ἐξέδραμε λόγος, ἀεί τινος καινοῦ προστιθεμένου κατορθώματος αὐξανομένη καὶ ἀναβαίνουσα πορρωτάτω κατέσχεν ἔπειτα τοῖς ἐπὶ θύραις σατράπαις καὶ στρατηγοῖς καὶ ἡγεμόσιν ὀφθείς θαῦμα καὶ λόγον παρέσχεν, ὡς οὗτος ἀνήρ ἐστιν ὁ γῆς καὶ θαλάττης ἐκβαλὼν Λακεδαιμονίους καὶ συστείλας ὑπὸ Ταΰγετον καὶ τὸν Εὐρώταν τὴν Σπάρτην τὴν ὀλίγον ἔμπροσθεν βασιλεῖ τῷ μεγάλῳ καὶ Πέρσαις δι’ Ἀγησιλάου τὸν περὶ Σούσων καὶ Ἐκβατάνων ἐπαραμένην πόλεμον. ταῦτ’ οὖν ὁ Ἀρταξέρξης ἔχαιρε, καὶ τὸν Πελοπίδαν ἐθαύμαζε ἐπὶ τῇ δόξῃ καὶ μέγαν ἐποίει ταῖς τιμαῖς, ὑπὸ τῶν μεγίστων εὐδαιμονίζεσθαι καὶ θεραπεύεσθαι βουλόμενος δοκεῖν. ἐπεὶ δὲ καὶ τὴν ὄψιν αὐτοῦ εἶδε καὶ τοὺς λόγους κατενόησε, τῶν μὲν Ἀττικῶν βεβαιοτέρους, τῶν δὲ Λακεδαιμονίων ἁπλουστέρους ὄντας, ἔτι μᾶλλον ἠγάπησε, καὶ πάθος βασιλικὸν παθὼν οὐκ ἀπεκρύψατο τὴν πρὸς τὸν ἄνδρα τιμήν, οὐδ’ ἔλαθε τοὺς ἄλλους πρέσβεις πλεῖστον νέμων ἐκείνῳ. καίτοι δοκεῖ μάλιστα τῶν Ἑλλήνων Ἀνταλκίδαν τιμῆσαι τὸν Λακεδαιμόνιον, ὅτι τὸν στέφανον, ὃν πίνων περιέκειτο, βάψας εἰς μύρον ἀπέστειλε. Πελοπίδᾳ δὲ οὕτω μὲν οὐκ ἐνετρύφησε, δῶρα δὲ λαμπρότατα καὶ μέγιστα τῶν νομιζομένων ἐξέπεμψε καὶ τὰς ἀξιώσεις ἐπεκύρωσεν, αὐτονόμους μὲν εἶναι τοὺς Ἕλληνας, οἰκεῖσθαι δὲ Μεσσήνην, Θηβαίους δὲ πατρικοὺς φίλους νομίζεσθαι βασιλέως.", "st": "Pel. 30.1"}, {"sp": "N", "t": "ταύτας ἔχων τὰς ἀποκρίσεις, τῶν δὲ δώρων οὐδὲν ὅ τι μὴ χάριτος ἦν σύμβολον καὶ φιλοφροσύνης δεξάμενος, ἀνέζευξεν· ὃ καὶ μάλιστα τοὺς ἄλλους πρέσβεις διέβαλε. Τιμαγόραν γοῦν Ἀθηναῖοι κρίναντες ἀπέκτειναν, εἰ μὲν ἐπὶ τῷ πλήθει τῶν δωρεῶν, ὀρθῶς καὶ δικαίως· οὐ γὰρ μόνον χρυσίον οὐδ’ ἀργύριον ἔλαβεν, ἀλλὰ καὶ κλίνην πολυτελῆ καὶ στρώτας θεράποντας, ὡς τῶν Ἑλλήνων οὐκ ἐπισταμένων, ἔτι δὲ βοῦς ὀγδοήκοντα καὶ βουκόλους, ὡς δὴ πρὸς ἀρρωστίαν τινὰ γάλακτος βοείου δεόμενος, τέλος δὲ κατέβαινεν ἐπὶ θάλασσαν ἐν φορείῳ κομιζόμενος, καὶ τέσσαρα τάλαντα τοῖς κομίζουσι μισθὸς ἐδόθη παρὰ βασιλέως· ἀλλ’ ἔοικεν οὐχ ἡ δωροδοκία μάλιστα παροξῦναι τοὺς Ἀθηναίους. Ἐπικράτους γοῦν ποτε τοῦ σακεσφόρου μήτε ἀρνουμένου δῶρα δέξασθαι παρὰ βασιλέως, ψήφισμά τε γράφειν φάσκοντος ἀντὶ τῶν ἐννέα ἀρχόντων χειροτονεῖσθαι κατ’ ἐνιαυτὸν ἐννέα πρέσβεις πρὸς βασιλέα τῶν δημοτικῶν καὶ πενήτων, ὅπως λαμβάνοντες εὐπορῶσιν, ἐγέλασεν ὁ δῆμος· ἀλλ’ ὅτι Θηβαίοις ἐγεγόνει πάντα χαλεπῶς ἔφερον, οὐ λογιζόμενοι τὴν Πελοπίδου δόξαν, ὅσων ἦν ῥητορειῶν καὶ λόγων κρείττων παρ’ ἀνθρώπῳ θεραπεύοντι τοὺς τῶν ὅπλων ἀεὶ κρατοῦντας.", "st": "Pel. 30.6"}, {"sp": "N", "t": "ἡ μὲν οὖν πρεσβεία τῷ Πελοπίδᾳ προσέθηκεν οὐ μικρὰν εὔνοιαν ἐπανελθόντι, διὰ τὸν Μεσσήνης συνοικισμὸν καὶ τὴν τῶν ἄλλων Ἑλλήνων αὐτονομίαν· Ἀλεξάνδρου δὲ τοῦ Φεραίου πάλιν εἰς τὴν αὐτοῦ φύσιν ἀναδραμόντος καὶ Θεσσαλῶν μὲν οὐκ ὀλίγας περικόπτοντος πόλεις, Φθιώτας δὲ Ἀχαιοὺς ἅπαντας καὶ τὸ Μαγνήτων ἔθνος ἔμφρουρον πεποιημένου, πυνθανόμεναι Πελοπίδαν ἐπανήκειν αἱ πόλεις εὐθὺς ἐπρέσβευον εἰς Θήβας αἰτούμεναι δύναμιν καὶ στρατηγὸν ἐκεῖνον. ψηφισαμένων δὲ τῶν Θηβαίων προθύμως, καὶ ταχὺ πάντων ἑτοίμων γενομένων καὶ τοῦ στρατηγοῦ περὶ ἔξοδον ὄντος, ὁ μὲν ἥλιος ἐξέλιπε καὶ σκότος ἐν ἡμέρᾳ τὴν πόλιν ἔσχεν, ὁ δὲ Πελοπίδας ὁρῶν πρὸς τὸ φάσμα συντεταραγμένους ἅπαντας οὐκ ᾤετο δεῖν βιάζεσθαι καταφόβους καὶ δυσέλπιδας ὄντας, οὐδὲ ἀποκινδυνεύειν ἑπτακισχιλίοις πολίταις, ἀλλ’ ἑαυτὸν μόνον τοῖς Θεσσαλοῖς ἐπιδούς καὶ τριακοσίους τῶν ἱππέων ἐθελοντὰς ἀναλαβὼν καὶ ξένους ἐξώρμησεν, οὔτε τῶν μάντεων ἐώντων οὔτε τῶν ἄλλων συμπροθυμουμένων πολιτῶν μέγα γὰρ ἐδόκει καὶ πρὸς ἄνδρα λαμπρὸν ἐξ οὐρανοῦ γεγονέναι σημεῖον. ὁ δὲ ἦν μὲν καὶ δι’ ὀργὴν ὧν καθύβριστο θερμότερος ἐπὶ τὸν Ἀλέξανδρον, ἤλπιζε δὲ καὶ τὴν οἰκίαν αὐτοῦ νοσοῦσαν ἤδη καὶ διεφθαρμένην εὑρήσειν ἐξ ὧν διείλεκτο τῇ Θήβῃ. μάλιστα δ’ αὐτὸν καὶ παρεκάλει τὸ τῆς πράξεως κάλλος, ἐπιθυμοῦντα καὶ φιλοτιμούμενον, ἐν οἷς χρόνοις Λακεδαιμόνιοι Διονυσίῳ τῷ Σικελίας τυράννῳ στρατηγοὺς καὶ ἁρμοστὰς ἔπεμπον, Ἀθηναῖοι δὲ μισθοδότην Ἀλέξανδρον εἶχον καὶ χαλκοῦν ἵστασαν ὡς εὐεργέτην, τότε τοῖς Ἕλλησιν ἐπιδεῖξαι Θηβαίους μόνους ὑπὲρ τῶν τυραννουμένων στρατευομένους καὶ καταλύοντας ἐν τοῖς Ἕλλησι τὰς παρανόμους καὶ βιαίους δυναστείας.", "st": "Pel. 31.1"}, {"sp": "N", "t": "ὡς οὖν εἰς Φάρσαλον ἐλθὼν ἤθροισε τὴν δύναμιν, εὐθὺς ἐβάδιζεν ἐπὶ τὸν Ἀλέξανδρον. ὁ δὲ Θηβαίους μὲν ὀλίγους περὶ τὸν Πελοπίδαν ὁρῶν, αὐτὸς δὲ πλείους ἔχων ἢ διπλασίους ὁπλίτας τῶν Θεσσαλῶν ἀπήντα πρὸς τὸ Θετίδειον. εἰπόντος δέ τινος τῷ Πελοπίδᾳ πολλοὺς ἔχοντα τὸν τύραννον ἐπέρχεσθαι, βέλτιον, ἔφη, πλείονας γὰρ νικήσομεν.", "st": "Pel. 32.1"}, {"sp": "N", "t": "ἀνατεινόντων δὲ πρὸς τὸ μέσον κατὰ τὰς καλουμένας Κυνὸς κεφαλὰς λόφων περικλινῶν καὶ ὑψηλῶν, ὥρμησαν ἀμφότεροι τούτους καταλαβεῖν τοῖς πεζοῖς. τοὺς δ’ ἱππεῖς ὁ Πελοπίδας πολλοὺς κἀγαθοὺς ὄντας ἐφῆκε τοῖς ἱππεῦσι τῶν πολεμίων, ὡς δὲ οὗτοι μὲν ἐκράτουν καὶ συνεξέπεσον εἰς τὸ πεδίον τοῖς φεύγουσιν, ὁ δὲ Ἀλέξανδρος ἔφθη τοὺς λόφους καταλαβών, τοῖς ὁπλίταις τῶν Θεσσαλῶν ὕστερον ἐπερχομένοις καὶ πρὸς ἰσχυρὰ καὶ μετέωρα χωρία βιαζομένοις ἐμβαλὼν ἔκτεινε τοὺς πρώτους, οἱ δὲ ἄλλοι πληγὰς λαβόντες οὐδὲν ἔπρασσον. κατιδὼν οὖν ὁ Πελοπίδας τοὺς μὲν ἱππεῖς ἀνεκαλεῖτο καὶ πρὸς τὸ συνεστηκὸς τῶν πολεμίων ἐλαύνειν ἐκέλευεν, αὐτὸς δὲ συνέμιξε δρόμῳ τοῖς περὶ τοὺς λόφους μαχομένοις εὐθὺς τὴν ἀσπίδα λαβών. καὶ διὰ τῶν ὄπισθεν ὠσάμενος εἰς τοὺς πρώτους τοσαύτην ἐνεποίησε ῥώμην καὶ προθυμίαν ἅπασιν ὥστε καὶ τοῖς πολεμίοις ἑτέρους δοκεῖν γεγονότας καὶ σώμασι καὶ ψυχαῖς ἐπέρχεσθαι. καὶ δύο μὲν ἢ τρεῖς ἀπεκρούσαντο προσβολάς, ὁρῶντες δὲ καὶ τούτους ἐπιβαίνοντας εὐρώστως καὶ τὴν ἵππον ἀπὸ τῆς διώξεως ἀναστρέφουσαν εἶξαν, ἐπὶ σκέλος ποιούμενοι τὴν ἀναχώρησιν. ὁ δέ Πελοπίδας ἀπὸ τῶν ἄκρων κατιδὼν ἅπαν τὸ στρατόπεδον τῶν πολεμίων οὔπω μὲν εἰς φυγὴν τετραμμένον, ἤδη δὲ θορύβου καὶ ταραχῆς ἀναπιμπλάμενον, ἔστη καὶ περιέβλεψεν αὐτὸν ζητῶν τὸν Ἀλέξανδρον. ὡς δ’ εἶδεν ἐπὶ τοῦ δεξιοῦ παραθαρρύνοντα καὶ συντάττοντα τοὺς μισθοφόρους, οὐ κατέσχε τῷ λογισμῷ τὴν ὀργήν, ἀλλὰ πρὸς τὴν βλέψιν ἀναφλεχθείς καὶ τῷ θυμῷ παραδοὺς τὸ σῶμα καὶ τὴν ἡγεμονίαν τῆς πράξεως, πολὺ πρὸ τῶν ἄλλων ἐξαλόμενος ἐφέρετο βοῶν καὶ προκαλούμενος τὸν τύραννον. ἐκεῖνος μὲν οὖν οὐκ ἐδέξατο τὴν ὁρμὴν οὐδὲ ὑπέμεινεν, ἀλλ’ ἀναφυγὼν πρὸς τοὺς δορυφόρους ἐνέκρυψεν ἑαυτόν, τῶν δὲ μισθοφόρων οἱ μὲν πρῶτοι συμβαλόντες εἰς χεῖρας ἀνεκόπησαν ὑπὸ τοῦ Πελοπίδου, τινὲς δὲ καὶ πληγέντες ἐτελεύτησαν, οἱ δὲ πολλοὶ τοῖς δόρασι πόρρωθεν διὰ τῶν ὅπλων τύπτοντες αὐτὸν κατετραυμάτιζον, ἕως οἱ Θεσσαλοὶ περιπαθήσαντες ἀπὸ τῶν λόφων δρόμῳ προσεβοήθησαν, ἤδη πεπτωκότος, οἵ τε ἱππεῖς προσελάσαντες ὅλην ἐτρέψαντο τὴν φάλαγγα καὶ διώξαντες ἐπὶ πλεῖστον ἐνέπλησαν νεκρῶν τὴν χώραν, πλέον ἢ τρισχιλίους καταβαλόντες.", "st": "Pel. 32.2"}, {"sp": "N", "t": "τὸ μὲν οὖν Θηβαίων τοὺς παρόντας ἐπὶ τῇ τοῦ Πελοπίδου τελευτῇ βαρέως φέρειν, πατέρα καὶ σωτῆρα καὶ διδάσκαλον τῶν μεγίστων καὶ καλλίστων ἀγαθῶν ἀποκαλοῦντας ἐκεῖνον, οὐ πάνυ θαυμαστὸν ἦν· οἱ δὲ Θεσσαλοὶ καὶ οἱ σύμμαχοι πᾶσαν ἀνθρωπίνῃ πρέπουσαν ἀρετῇ τιμὴν τοῖς ψηφίσμασιν ὑπερβαλόντες, ἔτι μᾶλλον ἐπεδείξαντο τοῖς πάθεσι τὴν πρὸς τὸν ἄνδρα χάριν, τοὺς μὲν γὰρ παραγεγονότας τῷ ἔργῳ λέγουσι μήτε θώρακα θέσθαι μήτε ἵππον ἐκχαλινῶσαι μήτε τραῦμα δήσασθαι πρότερον, ὡς ἐπύθοντο τὴν ἐκείνου τελευτήν, ἀλλὰ μετὰ τῶν ὅπλων θερμοὺς ἰόντας ἐπὶ τὸν νεκρόν ὥσπερ αἰσθανόμενον, τὰ τῶν πολεμίων κύκλῳ περὶ τὸ σῶμα σωρεύειν λάφυρα, κεῖραι δὲ ἵππους, κείρασθαι δὲ καὶ αὐτούς. ἀπιόντας δὲ πολλοὺς ἐπὶ σκηνὰς μήτε πῦρ ἀνάψαι μήτε δεῖπνον ἑλέσθαι, σιγὴν δὲ καὶ κατήφειαν εἶναι τοῦ στρατοπέδου παντός, ὥσπερ οὐ νενικηκότων ἐπιφανεστάτην νίκην καὶ μεγίστην, ἀλλ’ ἡττημένων ὑπὸ τοῦ τυράννου καὶ καταδεδουλωμένων. ἐκ δὲ τῶν πόλεων, ὡς ἀπηγγέλθη ταῦτα, παρῆσαν αἵ τε ἀρχαὶ καὶ μετ’ αὑτῶν ἔφηβοι καὶ παῖδες καὶ ἱερεῖς πρὸς τὴν ὑποδοχὴν τοῦ σώματος, τρόπαια καὶ στεφάνους καὶ πανοπλίας χρυσᾶς ἐπιφέροντες. ὡς δὲ ἔμελλεν ἐκκομίζεσθαι τὸ σῶμα, προσελθόντες οἱ πρεσβύτατοι τῶν Θεσσαλῶν ᾐτοῦντο τοὺς Θηβαίους δι’ αὑτῶν θάψαι τὸν νεκρόν. εἷς δὲ αὑτῶν ἔλεγεν· ἄνδρες σύμμαχοι, χάριν αἰτοῦμεν παρ’ ὑμῶν κόσμον ἡμῖν ἐπὶ ἀτυχίᾳ τοσαύτῃ καὶ παραμυθίαν φέρουσαν. οὐ γὰρ ζῶντα Θεσσαλοὶ Πελοπίδαν προπέμψουσιν, οὐδὲ αἰσθανομένῳ τὰς ἀξίας τιμὰς ἀποδώσουσιν, ἀλλ’ ἐὰν ψαῦσαί τε τοῦ νεκροῦ τύχωμεν καὶ δι’ αὑτῶν κοσμῆσαι καὶ θάψαι τὸ σῶμα, δόξομεν ὑμῖν οὐκ ἀπιστεῖν ὅτι μείζων ἡ συμφορὰ γέγονε Θετταλοῖς ἢ Θηβαίοις· ὑμῖν μὲν γὰρ ἡγεμόνος ἀγαθοῦ μόνον, ἡμῖν δὲ καὶ τούτου καὶ τῆς ἐλευθερίας στέρεσθαι συμβέβηκε. πῶς γὰρ ἔτι τολμήσομεν αἰτῆσαι στρατηγὸν ἄλλον παρ’ ὑμῶν οὐκ ἀποδόντες Πελοπίδαν; ταῦτα μὲν οἱ Θηβαῖοι συνεχώρησαν.", "st": "Pel. 33.1"}, {"sp": "N", "t": "ἐκείνων δὲ τῶν ταφῶν οὐ δοκοῦσιν ἕτεραι λαμπρότεραι γενέσθαι τοῖς τὸ λαμπρὸν οὐκ ἐν ἐλέφαντι καὶ χρυσῷ καὶ πορφύραις εἶναι νομίζουσιν, ὥσπερ Φίλιστος ὑμνῶν καὶ θαυμάζων τὴν Διονυσίου ταφήν, οἷον τραγῳδίας μεγάλης τῆς τυραννίδος ἐξόδιον θεατρικὸν γενομένην. Ἀλέξανδρος δὲ ὁ μέγας Ἡφαιστίωνος ἀποθανόντος οὐ μόνον ἵππους ἔκειρε καὶ ἡμιόνους, ἀλλὰ καὶ τὰς ἐπάλξεις ἀφεῖλε τῶν τειχῶν, ὡς ἂν δοκοῖεν αἱ πόλεις πενθεῖν, ἀντὶ τῆς πρόσθεν μορφῆς κούριμον σχῆμα καὶ ἄτιμον ἀναλαμβάνουσαι. ταῦτα μὲν οὖν προστάγματα δεσποτῶν ὄντα, καὶ μετὰ πολλῆς ἀνάγκης περαινόμενα καὶ μετὰ φθόνου τῶν τυχόντων καὶ μίσους τῶν βιαζομένων, οὐδεμιᾶς χάριτος ἦν οὐδὲ τιμῆς, ὄγκου δὲ βαρβαρικοῦ καὶ τρυφῆς καὶ ἀλαζονείας ἐπίδειξις, εἰς κενὰ καὶ ἄζηλα τὴν περιουσίαν διατιθεμένων· ἀνὴρ δὲ δημοτικὸς ἐπὶ ξένης τεθνηκώς, οὐ γυναικός, οὐ παίδων, οὐ συγγενῶν παρόντων, οὐ δεομένου τινός, οὐκ ἀναγκάζοντος, ὑπὸ δήμων τοσούτων καὶ πόλεων ἁμιλλωμένων προπεμπόμενος καὶ συνεκκομιζόμενος καὶ στεφανούμενος, εἰκότως ἐδόκει τὸν τελειότατον ἀπέχειν εὐδαιμονισμόν. οὐ γάρ, ὡς Αἴσωπος ἔφασκε, χαλεπώτατός ἐστιν ὁ τῶν εὐτυχούντων θάνατος, ἀλλὰ μακαριώτατος, εἰς ἀσφαλῆ χώραν τὰς εὐπραξίας κατατιθέμενος τῶν ἀγαθῶν καὶ τύχην μεταβάλλεσθαι μὴ ἀπολείπων. διὸ βέλτιον ὁ Λάκων τὸν Ὀλυμπιονίκην Διαγόραν, ἐπιδόντα μὲν υἱοὺς στεφανουμένους Ὀλυμπίασιν, ἐπιδόντα δ’ υἱωνοὺς καὶ θυγατριδοῦς, ἀσπασάμενος, κάτθανε, εἶπε, Διαγόρα· οὐκ εἰς τὸν Ὄλυμπον ἀναβήσῃ. τὰς δὲ Ὀλυμπιακὰς καὶ Πυθικὰς νίκας οὐκ ἂν, οἶμαί, τις εἰς τὸ αὐτὸ συνθεὶς ἁπάσας ἑνὶ τῶν Πελοπίδου παραβαλεῖν ἀγώνων ἀξιώσειεν, οὓς πολλοὺς ἀγωνισάμενος καὶ κατορθώσας, καὶ τοῦ βίου τὸ πλεῖστον ἐν δόξῃ καὶ τιμῇ βιώσας, τέλος ἐν τῇ τρισκαιδεκάτῃ βοιωταρχίᾳ, τυραννοκτονίᾳ μεμιγμένην ἀριστείαν ἀριστεύων, ὑπὲρ τῆς τῶν Θεσσαλῶν ἐλευθερίας ἀπέθανεν.", "st": "Pel. 34.1"}, {"sp": "N", "t": "ὁ δὲ θάνατος αὐτοῦ μεγάλα μὲν ἐλύπησε τοὺς συμμάχους, μείζονα δὲ ὠφέλησε. Θηβαῖοι γὰρ, ὡς ἐπύθοντο τὴν τοῦ Πελοπίδου τελευτήν, οὐδεμίαν ἀναβολὴν ποιησάμενοι τῆς τιμωρίας κατὰ τάχος ἐστράτευσαν ὁπλίταις ἑπτακισχιλίοις, ἱππεῦσι δ’ ἑπτακοσίοις, ἡγουμένου Μαλκίτου καὶ Διογείτονος. καταλαβόντες δὲ συνεσταλμένον καὶ περικεκομμένον τῆς δυνάμεως Ἀλέξανδρον ἠνάγκασαν Θεσσαλοῖς μὲν ἀποδοῦναι τὰς πόλεις ἃς εἶχεν αὐτῶν, Μάγνητας δὲ καὶ Φθιώτας Ἀχαιοὺς ἀφεῖναι καὶ τὰς φρουρὰς ἐξαγαγεῖν, ὀμόσαι δὲ αὐτὸν ἐφ’ οὓς ἂν ἡγῶνται Θηβαῖοι καὶ κελεύσωσιν ἀκολουθήσειν. Θηβαῖοι μὲν οὖν τούτοις ἠρκέσθησαν ἣν δὲ ὀλίγον ὕστερον τοῖς θεοῖς ὑπὲρ Πελοπίδου δίκην ἔδωκε διηγήσομαι.", "st": "Pel. 35.1"}, {"sp": "N", "t": "Θήβην τὴν συνοικοῦσαν αὐτῷ πρῶτον μὲν, ὡς εἴρηται, Πελοπίδας ἐδίδαξε μὴ φοβεῖσθαι τὴν ἔξω λαμπρότητα καὶ παρασκευὴν τῆς τυραννίδος, ἐντὸς τῶν ὅπλων καὶ τῶν φυλακῶν οὖσαν ἔπειτα δὲ φοβουμένη τὴν ἀπιστίαν αὐτοῦ καὶ μισοῦσα τὴν ὠμότητα, συνθεμένη μετὰ τῶν ἀδελφῶν, τριῶν ὄντων, Τισιφόνου, Πειθολάου, Λυκόφρονος, ἐπεχείρει τόνδε τὸν τρόπον. τὴν μὲν ἄλλην οἰκίαν τοῦ τυράννου κατεῖχον αἱ φυλακαὶ τῶν παρανυκτερευόντων, ὁ δὲ θάλαμος, ἐν ᾧ καθεύδειν εἰώθεσαν, ὑπερῷος ἦν, καὶ πρὸ αὐτοῦ φυλακὴν εἶχε κύων δεδεμένος, πᾶσι φοβερὸς πλὴν αὐτοῖς ἐκείνοις καὶ ἑνὶ τῶν οἰκετῶν τῷ τρέφοντι. καθ’ ὃν οὖν ἔμελλε καιρὸν ἐπιχειρεῖν ἡ Θήβη, τοὺς μὲν ἀδελφοὺς ἀφ’ ἡμέρας εἶχε πλησίον ἐν οἴκῳ τινὶ κεκρυμμένους, εἰσελθοῦσα δέ, ὥσπερ εἰώθει, μόνη πρὸς τὸν Ἀλέξανδρον ἤδη καθεύδοντα καὶ μετὰ μικρὸν πάλιν προελθοῦσα, τῷ μὲν οἰκέτῃ προσέταξεν ἀπάγειν ἔξω τὸν κύνα· βούλεσθαι γὰρ ἀναπαύεσθαι μεθ’ ἡσυχίας ἐκεῖνον· αὐτὴ δὲ τὴν κλίμακα φοβουμένη μὴ κτύπον παράσχῃ τῶν νεανίσκων ἀναβαινόντων ἐρίοις κατεστόρεσεν· εἶτα οὕτως ἀναγαγοῦσα τοὺς ἀδελφοὺς ξιφήρεις καὶ στήσασα πρὸ τῶν θυρῶν εἰσῆλθεν αὐτή, καὶ καθελοῦσα τὸ ξίφος ὑπὲρ τῆς κεφαλῆς κρεμάμενον σημεῖον εἶναι τοῦ κατέχεσθαι τὸν ἄνδρα καὶ καθεύδειν ἔδειξεν. ἐκπεπληγμένων δὲ τῶν νεανίσκων καὶ κατοκνούντων, κακίζουσα καὶ διομνυμένη μετ’ ὀργῆς αὐτὴ τὸν Ἀλέξανδρον ἐξεγείρασα μηνύσειν τὴν πρᾶξιν, αἰσχυνθέντας αὐτοὺς ἅμα καὶ φοβηθέντας εἰσήγαγε καὶ περιέστησε τῇ κλίνῃ, προσφέρουσα τὸν λύχνον. τῶν δὲ ὁ μὲν τοὺς πόδας κατεῖχε πιέσας, ὁ δὲ τὴν κεφαλὴν λαβόμενος τῶν τριχῶν ἀνέκλασεν, ὁ δὲ τρίτος τῷ ξίφει τύπτων αὐτὸν διεχρήσατο, τῷ μὲν τάχει τῆς τελευτῆς πρᾳότερον ἴσως ἢ προσῆκον ἦν ἀποθανόντα, τῷ δὲ μόνον ἢ πρῶτον τυράννων ὑπὸ γυναικὸς ἰδίας ἀπολέσθαι, καὶ τῇ μετὰ θάνατον αἰκίᾳ τοῦ σώματος ῥιφέντος καὶ πατηθέντος ὑπὸ τῶν Φεραίων, ἄξια πεπονθέναι δόξαντα τῶν παρανομημάτων.", "st": "Pel. 35.3"}, {"sp": "HDR", "t": "Μάρκελλος"}, {"sp": "N", "t": "Μᾶρκον δὲ Κλαύδιον τὸν πεντάκις ὑπατεύσαντα Ῥωμαίων Μάρκου μὲν υἱὸν γενέσθαι λέγουσι, κληθῆναι δὲ τῶν ἀπὸ τῆς οἰκίας πρῶτον Μάρκελλον, ὅπερ ἐστὶν Ἀρήϊον, ὥς φησι Ποσειδώνιος. ἦν γὰρ τῇ μὲν ἐμπειρίᾳ πολεμικός, τῷ δὲ σώματι ῥωμαλέος, τῇ δὲ χειρὶ πλήκτης, τῇ δὲ φύσει φιλοπόλεμος κἀν τούτῳ δὴ πολὺ τὸ γαῦρον καὶ ἀγέρωχον ἐπιφαίνων ἐν τοῖς ἀγῶσι, τῷ δὲ ἄλλῳ τρόπῳ σώφρων, φιλάνθρωπος, Ἑλληνικῆς παιδείας καὶ λόγων ἄχρι τοῦ τιμᾶν καὶ θαυμάζειν τοὺς κατορθοῦντας ἐραστής, αὐτὸς δὲ ὑπ’ ἀσχολιῶν ἐφ’ ὅσον ἦν πρόθυμος ἀσκῆσαι καὶ μαθεῖν οὐκ ἐξικόμενος. εἰ γὰρ ἄλλοις τισὶν ἀνθρώποις ὁ θεός, ὥσπερ Ὅμηρος εἴρηκεν,", "st": "Marc. 1.1"}, {"sp": "N", "t": "ἐκ νεότητος ἔδωκε καὶ εἰς γῆρας τολυπεύειν<br>ἀργαλέους πολέμους,<br>καὶ τοῖς τότε πρωτεύουσι Ῥωμαίων,", "st": "Marc. 1.1b"}, {"sp": "N", "t": "οἳ νέοι μὲν ὄντες περὶ Σικελίαν Καρχηδονίοις, ἀκμάζοντες δὲ Γαλάταις ὑπὲρ αὐτῆς Ἰταλίας ἐπολέμουν, ἤδη δὲ γηρῶντες Ἀννίβᾳ πάλιν συνείχοντο καὶ Καρχηδονίοις, οὐκ ἔχοντες, ὥσπερ οἱ πολλοὶ, διὰ γῆρας ἀνάπαυσιν στρατειῶν, ἀλλ’ ἐπὶ στρατηγίας πολέμων καὶ ἡγεμονίας κατ’ εὐγένειαν καὶ ἀρετὴν ἀγόμενοι.", "st": "Marc. 1.3"}, {"sp": "N", "t": "Μάρκελλος δὲ πρὸς οὐδὲν μὲν ἦν μάχης εἶδος ἀργὸς οὐδὲ ἀνάσκητος, αὐτὸς δ’ ἑαυτοῦ κράτιστος ἐν τῷ μονομαχεῖν γενόμενος οὐδεμίαν πρόκλησιν ἔφυγε, πάντας δὲ τοὺς προκαλεσαμένους ἀπέκτεινεν. ἐν δὲ Σικελίᾳ τὸν ἀδελφὸν Ὀτακίλιον κινδυνεύοντα διέσωσεν ὑπερασπίσας καὶ ἀποκτείνας τοὺς ἐπιφερομένους. ἀνθ’ ὧν ὄντι μὲν ἔτι νέῳ στέφανοι καὶ γέρα παρὰ τῶν στρατηγῶν ἦσαν, εὐδοκιμοῦντα δὲ μᾶλλον ἀγορανόμον μὲν ἀπέδειξε τῆς ἐπιφανεστέρας τάξεως ὁ δῆμος, οἱ δὲ ἱερεῖς αὔγουρα. τοῦτο δ’ ἐστὶν ἱερωσύνης εἶδος, ᾧ μάλιστα τὴν ἀπ’ οἰωνῶν μαντικὴν ἐπιβλέπειν καὶ παραφυλάττειν νόμος δέδωκεν.", "st": "Marc. 2.1"}, {"sp": "N", "t": "ἠναγκάσθη δὲ ἀγορανομῶν δίκην ἀβούλητον εἰσενεγκεῖν. ἦν γὰρ αὐτῷ παῖς ὁμώνυμος ἐν ὥρᾳ, τὴν ὄψιν ἐκπρεπής, οὐχ ἧττον δὲ τῷ σωφρονεῖν καὶ πεπαιδεῦσθαι περίβλεπτος ὑπὸ τῶν πολιτῶν τούτῳ Καπετωλῖνος ὁ τοῦ Μαρκέλλου συνάρχων, ἀσελγὴς ἀνὴρ καὶ θρασύς, ἐρῶν λόγους προσήνεγκε. τοῦ δὲ παιδὸς τὸ μὲν πρῶτον αὐτοῦ καθ’ ἑαυτὸν ἀποτριψαμένου τὴν πεῖραν, ὡς δὲ αὖθις ἐπεχείρησε κατειπόντος πρὸς τὸν πατέρα, βαρέως ἐνεγκὼν ὁ Μάρκελλος προσήγγειλε τῇ βουλῇ τὸν ἄνθρωπον. ὁ δὲ πολλὰς μὲν ἀποδράσεις καὶ παραγραφὰς ἐμηχανᾶτο, τοὺς δημάρχους ἐπικαλούμενος, ἐκείνων δὲ μὴ προσδεχομένων τὴν ἐπίκλησιν ἀρνήσει τὴν αἰτίαν ἔφευγε, καὶ μάρτυρος οὐδενὸς τῶν λόγων γεγονότος ἔδοξε μεταπέμπεσθαι τὸν παῖδα τῇ βουλῇ, παραγενομένου δ’ ἰδόντες ἐρύθημα καὶ δάκρυον καὶ μεμιγμένον ἀπαύστῳ τῷ θυμουμένῳ τὸ αἰδούμενον, οὐδενὸς ἄλλου δεηθέντες τεκμηρίου κατεψηφίσαντο καὶ χρήμασιν ἐζημίωσαν Καπετωλῖνον, ἐξ ὧν ὁ Μάρκελλος ἀργυρᾶ λοιβεῖα ποιησάμενος τοῖς θεοῖς καθιέρωσεν.", "st": "Marc. 2.3"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῦ πρώτου τῶν Καρχηδονίων πολέμων ἔτει δευτέρῳ καὶ εἰκοστῷ συναιρεθέντος ἀρχαὶ πάλιν Γαλατικῶν ἀγώνων διεδέχοντο τὴν Ῥώμην, οἱ δὲ τὴν ὑπαλπείαν νεμόμενοι τῆς Ἰταλίας Ἴνσομβρες, Κελτικὸν ἔθνος, μεγάλοι καὶ καθ’ ἑαυτοὺς ὄντες, δυνάμεις ἐκάλουν, καὶ μετεπέμποντο Γαλατῶν τοὺς μισθοῦ στρατευομένους, οἳ Γαισάται καλοῦνται, θαυμαστὸν μὲν ἐδόκει καὶ τύχης ἀγαθῆς γενέσθαι τὸ μὴ συρραγῆναι τὸν Κελτικὸν εἰς τὸ αὐτὸ τῷ Λιβυκῷ πόλεμον, ἀλλ’ ὥσπερ ἐφεδρείαν εἰληφότας τοὺς Γαλάτας, ὀρθῶς καὶ δικαίως ἀτρεμήσαντας μαχομένων ἐκείνων, οὕτω τότε δὴ τοῖς νενικηκόσιν ἐπαποδύεσθαι καὶ προκαλεῖσθαι σχολὴν ἄγοντας· οὐ μὴν ἀλλὰ μέγαν ἥ τε χώρα παρεῖχε φόβον, διὰ τὴν γειτνίασιν ὁμόρῳ καὶ προσοίκῳ πολέμῳ συνοισομένοις, καὶ τὸ παλαιὸν ἀξίωμα τῶν Γαλατῶν, οὓς μάλιστα Ῥωμαῖοι δεῖσαι δοκοῦσιν, ἅτε δὴ καὶ τὴν πόλιν ὑπ’ αὐτῶν ἀποβαλόντες, ἐξ ἐκείνου δὲ καὶ θέμενοι νόμον ἀτελεῖς εἶναι στρατείας τοὺς ἱερέας, πλὴν εἰ μὴ Γαλατικὸς πάλιν ἐπέλθοι πόλεμος. ἐδήλου δὲ καὶ τὸν φόβον αὐτῶν ἥ τε παρασκευὴ μυριάδες γὰρ ἐν ὅπλοις ἅμα τοσαῦται Ῥωμαίων οὔτε πρότερον οὔτε ὕστερον γενέσθαι λέγονται καὶ τὰ περὶ τὰς θυσίας καινοτομούμενα· βαρβαρικὸν μὲν γὰρ οὐδὲν οὐδ’ ἔκφυλον ἐπιτηδεύοντες, ἀλλ’ ὡς ἔνι μάλιστα ταῖς δόξαις Ἑλληνικῶς διακείμενοι καὶ πρᾴως πρὸς τὰ θεῖα, τότε τοῦ πολέμου συμπεσόντος ἠναγκάσθησαν εἶξαι λογίοις τισὶν ἐκ τῶν Σιβυλλείων, καὶ δύο μὲν Ἕλληνας, ἄνδρα καὶ γυναῖκα, δύο δὲ Γαλάτας ὁμοίως ἐν τῇ καλουμένῃ βοῶν ἀγορᾷ κατορύξαι ζῶντας, οἷς ἔτι καὶ νῦν ἐν τῷ Νοεμβρίῳ μηνὶ δρῶσιν Ἕλλησι καὶ Γαλάταις ἀπορρήτους καὶ ἀθεάτους ἱερουργίας.", "st": "Marc. 3.1"}, {"sp": "N", "t": "οἱ μὲν οὖν πρῶτοι τῶν ἀγώνων νίκας τε μεγάλας καὶ σφάλματα τοῖς Ῥωμαίοις ἐνέγκαντες εἰς οὐδὲν ἐτελεύτησαν πέρας βέβαιον Φλαμινίου δὲ καὶ Φουρίου τῶν ὑπάτων μεγάλαις ἐκστρατευσάντων δυνάμεσιν ἐπὶ τοὺς Ἴνσομβρας, ὤφθη μὲν αἵματι ῥέων ὁ διὰ τῆς Πικηνίδος χώρας ποταμός, ἐλέχθη δὲ τρεῖς σελήνας φανῆναι περὶ πόλιν Ἀρίμινον, οἱ δὲ ἐπὶ ταῖς ὑπατικαῖς ψηφοφορίαις παραφυλάττοντες οἰωνοὺς ἱερεῖς διεβεβαιοῦντο μοχθηρὰς καὶ δυσόρνιθας αὐτοῖς γεγονέναι τὰς τῶν ὑπάτων ἀναγορεύσεις, εὐθὺς οὖν ἔπεμψεν ἡ σύγκλητος ἐπὶ τὸ στρατόπεδον γράμματα καλοῦσα καὶ μεταπεμπομένη τοὺς ὑπάτους, ὅπως ἐπανελθόντες ᾗ τάχιστα τὴν ἀρχὴν ἀπείπωνται καὶ μηδὲν ὡς ὕπατοι φθάσωσι πρᾶξαι πρὸς τοὺς πολεμίους. ταῦτα δεξάμενος τὰ γράμματα Φλαμίνιος οὐ πρότερον ἔλυσεν ἢ μάχῃ συνάψας τρέψασθαι τοὺς βαρβάρους καὶ τὴν χώραν αὐτῶν ἐπιδραμεῖν. ὡς οὖν ἐπανῆλθε μετὰ πολλῶν λαφύρων, οὐκ ἀπήντησεν ὁ δῆμος, ἀλλ’ ὅτι καλούμενος οὐκ εὐθὺς ὑπήκουσεν οὐδ’ ἐπείσθη τοῖς γράμμασιν, ἀλλ’ ἐνύβρισε καὶ κατεφρόνησε, μικροῦ μὲν ἐδέησεν ἀποψηφίσασθαι τὸν θρίαμβον αὐτοῦ, θριαμβεύσαντα δὲ ἰδιώτην ἐποίησεν, ἀναγκάσας ἐξομόσασθαι τὴν ὑπατείαν μετὰ τοῦ συνάρχοντος. οὕτω πάντα τὰ πράγματα Ῥωμαίοις εἰς τὸν θεὸν ἀνήγετο, μαντειῶν δὲ καὶ πατρίων ὑπεροψίαν οὐδ’ ἐπὶ ταῖς μεγίσταις εὐπραξίαις ἀπεδέχοντο, μεῖζον ἡγούμενοι πρὸς σωτηρίαν πόλεως τὸ θαυμάζειν τὰ θεῖα τοὺς ἄρχοντας τὸν κρατεῖν τῶν πολεμίων.", "st": "Marc. 4.1"}, {"sp": "N", "t": "Τιβέριος οὖν Σεμπρώνιος, ἀνὴρ δι’ ἀνδρείαν καὶ καλοκαγαθίαν οὐδενὸς ἧττον ἀγαπηθεὶς ὑπὸ Ῥωμαίων, ἀπέδειξε μὲν ὑπατεύων διαδόχους Σκηπίωνα Νασικᾶν καὶ Γάϊον Μάρκιον, ἤδη δὲ ἐχόντων αὐτῶν ἐπαρχίας καὶ στρατεύματα, ἱερατικοῖς ὑπομνήμασιν ἐντυχὼν εὗρεν ἠγνοημένον ὑφ’ αὑτοῦ τι τῶν πατρίων. ἦν δὲ τοιοῦτον· ὅταν ἄρχων ἐπ’ ὄρνισι καθεζόμενος ἔξω πόλεως οἶκον ἢ σκηνὴν μεμισθωμένος ὑπ’ αἰτίας τινὸς ἀναγκασθῇ μήπω γεγονότων σημείων βεβαίων ἐπανελθεῖν εἰς πόλιν, ἀφεῖναι χρῆν τὸ προμεμισθωμένον οἴκημα καὶ λαβεῖν ἕτερον, ἐξ οὗ ποιήσεται τὴν θέαν αὖθις ἐξ ὑπαρχῆς, τοῦτο ἔλαθεν, ὡς ἔοικε, τὸν Τιβέριον, καὶ δὶς τῷ αὐτῷ χρησάμενος ἀπέδειξε τοὺς εἰρημένους ἄνδρας ὑπάτους. ὕστερον δὲ γνοὺς τὴν ἁμαρτίαν ἀνήνεγκε πρὸς τὴν σύγκλητον. ἡ δὲ οὐ κατεφρόνησε τοῦ κατὰ μικρὸν οὕτως ἐλλείμματος, ἀλλ’ ἔγραψε τοῖς ἀνδράσι· καὶ ἐκεῖνοι τὰς ἐπαρχίας ἀπολιπόντες ἐπανῆλθον εἰς Ῥώμην ταχὺ καὶ κατέθεντο τὴν ἀρχήν. ἀλλὰ ταῦτα μὲν ὕστερον ἐπράχθη· περὶ δὲ τοὺς αὐτοὺς ἐκείνους χρόνους καὶ δύο ἱερεῖς ἐπιφανέστατοι τὰς ἱερωσύνας ἀφῃρέθησαν, Κορνήλιος μὲν Κέθηγος ὅτι τὰ σπλάγχνα τοῦ ἱερείου παρὰ τάξιν ἐπέδωκε, Κούϊντος δὲ Σουλπίκιος ἐπὶ τῷ θύοντος αὐτοῦ τὸν κορυφαῖον ἀπορρυῆναι τῆς κεφαλῆς πῖλον, ὃν οἱ καλούμενοι φλαμίνιοι φοροῦσι. Μινουκίου δὲ δικτάτορος ἵππαρχον ἀποδείξαντος Γάϊον Φλαμίνιον, ἐπεὶ τρισμὸς ἠκούσθη μυὸς ὃν σόρικα καλοῦσιν, ἀποψηφισάμενοι τούτους αὖθις ἑτέρους κατέστησαν, καὶ τὴν ἐν οὕτω μικροῖς ἀκρίβειαν φυλάττοντες οὐδεμιᾷ προσεμίγνυσαν δεισιδαιμονίᾳ, τῷ μηδὲν ἀλλάττειν μηδὲ παρεκβαίνειν τῶν πατρίων.", "st": "Marc. 5.1"}, {"sp": "N", "t": "Ὡς δ’ οὖν ἐξωμόσαντο τὴν ἀρχὴν οἱ περὶ τὸν Φλαμίνιον, διὰ τῶν καλουμένων μεσοβασιλέων ὕπατος ἀποδείκνυται Μάρκελλος, καὶ παραλαβὼν τὴν ἀρχὴν ἀποδείκνυσιν αὑτῷ συνάρχοντα Γναῖον Κορνήλιον. ἐλέχθη μὲν οὖν ὡς πολλὰ συμβατικὰ τῶν Γαλατῶν λεγόντων, καὶ τῆς βουλῆς εἰρηναῖα βουλομένης, ὁ Μάρκελλος ἐξετράχυνε τὸν δῆμον ἐπὶ τὸν πόλεμον· οὐ μὴν ἀλλὰ καὶ γενομένης εἰρήνης ἀνακαινίσαι τὸν πόλεμον οἱ Γαισάται δοκοῦσι, τὰς Ἄλπεις ὑπερβαλόντες καὶ τοὺς Ἰνσόμβρους ἐπάραντες· τρισμύριοι γὰρ ὄντες προσεγένοντο πολλαπλασίοις ἐκείνοις οὖσι καὶ μέγα φρονοῦντες εὐθὺς ἐπ’ Ἀκέρρας ὥρμησαν, πόλιν ὑπὲρ ποταμοῦ Πάδου ἀνῳκισμένην. ἐκεῖθεν δὲ μυρίους τῶν Γαισατῶν ὁ βασιλεὺς Βριτόματος ἀναλαβὼν τὴν περὶ Πάδον χώραν ἐπόρθει. ταῦτα Μάρκελλος πυθόμενος τὸν μὲν συνάρχοντα πρὸς Ἀκέρραις ἀπέλιπε τὴν πεζὴν καὶ βαρεῖαν ὁμοῦ πᾶσαν ἔχοντα δύναμιν καὶ τῶν ἱππέων μέρος τρίτον, αὐτὸς δὲ τοὺς λοιποὺς ἱππεῖς ἀναλαβὼν καὶ τοὺς ἐλαφροτάτους τῶν ὁπλιτῶν περὶ ἑξακοσίους ἤλαυνεν, οὔτε ἡμέρας οὔτε νυκτὸς ἀνιεὶς τὸν δρόμον, ἕως ἐπέβαλε τοῖς μυρίοις Γαισάταις περὶ τὸ καλούμενον Κλαστίδιον, Γαλατικὴν κώμην οὐ πρὸ πολλοῦ Ῥωμαίοις ὑπήκοον γεγενημένην. ἀναλαβεῖν δὲ καὶ διαναπαῦσαι τὸν στρατὸν οὐχ ὑπῆρξεν αὐτῷ· ταχὺ γὰρ αἴσθησιν τοῖς βαρβάροις ἀφικόμενος παρέσχε, καὶ κατεφρονήθη πεζῶν μὲν ὀλίγων παντάπασιν ὄντων σὺν αὐτῷ, τὸ δ’ ἱππικὸν ἐν οὐδενὶ λόγῳ τῶν Κελτῶν τιθεμένων, κράτιστοι γὰρ ὄντες ἱππομαχεῖν καὶ μάλιστα τούτῳ διαφέρειν δοκοῦντες, τότε καὶ πλήθει πολὺ τὸν Μάρκελλον ὑπερέβαλλον. εὐθὺς οὖν ἐπ’ αὐτὸν ὡς ἀναρπασόμενοι μετὰ βίας πολλῆς καὶ δεινῶν ἀπειλῶν ἐφέροντο, τοῦ βασιλέως προϊππεύοντος. ὁ δὲ Μάρκελλος, ὡς μὴ φθαῖεν αὐτὸν ἐγκυκλωσάμενοι καὶ περιχυθέντες ὀλιγοστὸν ὄντα, τὰς ἴλας ἦγε πόρρω τῶν ἱππέων καὶ περιήλαυνε, λεπτὸν ἐκτείνων τὸ κέρας, ἄχρι οὗ μικρὸν ἀπέσχε τῶν πολεμίων, Ἤδη δέ πως εἰς ἐμβολὴν ἐπιστρέφοντος αὐτοῦ συντυγχάνει τὸν ἵππον πτυρέντα τῇ γαυρότητι τῶν πολεμίων ἀποτραπέσθαι καὶ βίᾳ φέρειν ὀπίσω τὸν Μάρκελλον. ὁ δὲ τοῦτο δείσας μὴ ταραχὴν ἐκ δεισιδαιμονίας τοῖς Ῥωμαίοις ἐνεργάσηται, ταχὺ περισπάσας ἐφ’ ἡνίαν τῷ χαλινῷ καὶ περιστρέψας τὸν ἵππον ἐναντίον τοῖς πολεμίοις, τὸν ἥλιον αὐτὸς προσεκύνησεν, ὡς δὴ μὴ κατὰ τύχην, ἀλλ’ ἕνεκα τούτου τῇ περιαγωγῇ χρησάμενος· οὕτω γὰρ ἔθος ἐστὶ Ῥωμαίοις προσκυνεῖν τοὺς θεοὺς περιστρεφομένοις, καὶ αὐτὸν ἤδη προσμιγνύντα τοῖς ἐναντίοις προσεύξασθαι τῷ Φερετρίῳ Διῒ τὰ κάλλιστα τῶν παρὰ τοῖς πολεμίοις ὅπλων καθιερώσειν.", "st": "Marc. 6.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ κατιδὼν ὁ τῶν Γαλατῶν βασιλεὺς καὶ τεκμηράμενος ἀπὸ τῶν συμβόλων ἄρχοντα τοῦτον εἶναι, πολὺ πρὸ τῶν ἄλλων ἐξελάσας τὸν ἵππον ὑπηντίασεν, ἅμα τῇ φωνῇ προκλητικὸν ἐπαλαλάζων καὶ τὸ δόρυ κραδαίνων, ἀνὴρ μεγέθει τε σώματος ἔξοχος Γαλατῶν, καὶ πανοπλίᾳ ἐν ἀργύρῳ καὶ χρυσῷ καὶ βαφαῖς καὶ πᾶσι ποικίλμασιν, ὥσπερ ἀστραπῇ, διαφέρων στιλβούσῃ. ὡς οὖν ἐπιβλέψαντι τὴν φάλαγγα τῷ Μαρκέλλῳ ταῦτα τῶν ὅπλων ἔδοξε κάλλιστα καὶ κατὰ τούτων ὑπέλαβε πεποιῆσθαι τῷ θεῷ τὴν κατευχήν, ὥρμησεν ἐπὶ τὸν ἄνδρα, καὶ τῷ δόρατι διακόψας τὸν θώρακα καὶ συνεπερείσας τῇ ῥύμῃ τοῦ ἵππου ζῶντα μὲν αὐτὸν περιέτρεψε, δευτέραν δὲ καὶ τρίτην πληγὴν ἐνεὶς εὐθὺς ἀπέκτεινεν. ἀποπηδήσας δὲ τοῦ ἵππου, καὶ τῶν ὅπλων τοῦ νεκροῦ ταῖς χερσὶν ἐφαψάμενος, πρὸς τὸν οὐρανὸν εἶπεν· ὦ μεγάλα στρατηγῶν καὶ ἡγεμόνων ἔργα καὶ πράξεις ἐπιβλέπων ἐν πολέμοις καὶ μάχαις Φερέτριε Ζεῦ, μαρτύρομαί σε Ῥωμαίων τρίτος ἄρχων ἄρχοντα καὶ βασιλέα στρατηγὸς ἰδίᾳ χειρὶ τόνδε τὸν ἄνδρα κατεργασάμενος καὶ Κτείνας σοὶ καθιεροῦν τὰ πρῶτα καὶ κάλλιστα τῶν λαφύρων, σὺ δὲ δίδου τύχην ὁμοίαν ἐπὶ τὰ λοιπὰ τοῦ πολέμου προτρεπομένοις.", "st": "Marc. 7.1"}, {"sp": "N", "t": "ἐκ τούτου συνέμισγον οἱ ἱππεῖς οὐ διακεκριμένοις τοῖς ἱππεῦσιν, ἀλλὰ καὶ πρὸς τοὺς πεζοὺς ὁμοῦ προσφερομένους μαχόμενοι, καὶ νικῶσι νίκην ἰδέᾳ τε καὶ τρόπῳ περιττὴν καὶ παράδοξον ἱππεῖς γὰρ ἱππεῖς καὶ πεζοὺς ἅμα τοσοῦτοι τοσούτους οὔτε πρότερον οὔτε ὕστερον νικῆσαι λέγονται, Κτείνας δὲ τοὺς πλείστους καὶ κρατήσας ὅπλων καὶ χρημάτων ἐπανῆλθε πρὸς τὸν συνάρχοντα μοχθηρῶς πολεμοῦντα Κελτοῖς περὶ πόλιν μεγίστην καὶ πολυανθρωποτάτην τῶν Γαλατικῶν. Μεδιόλανον καλεῖται, καὶ μητρόπολιν αὐτὴν οἱ τῇδε Κελτοὶ νομίζουσιν· ὅθεν ἐκθύμως μαχόμενοι περὶ αὐτῆς ἀντεπολιόρκουν τὸν Κορνήλιον. ἐπελθόντος δὲ Μαρκέλλου, καὶ τῶν Γαισατῶν, ὡς ἐπύθοντο τὴν τοῦ βασιλέως ἧτταν καὶ τελευτήν, ἀπελθόντων, τὸ μὲν Μεδιόλανον ἁλίσκεται, τὰς δὲ ἄλλας πόλεις αὐτοὶ παραδιδόασιν οἱ Κελτοὶ καὶ τὰ καθ’ ἑαυτοὺς ἐπιτρέπουσι πάντα Ῥωμαίοις. καὶ τούτοις μὲν ἦν εἰρήνη μετρίων τυχοῦσι.", "st": "Marc. 7.4"}, {"sp": "N", "t": "ψηφισαμένης δὲ τῆς συγκλήτου μόνῳ Μαρκέλλῳ θρίαμβον, εἰσήλαυνε τῇ μὲν ἄλλῃ λαμπρότητι καὶ πλούτῳ καὶ λαφύροις καὶ σώμασιν ὑπερφυέσιν αἰχμαλώτων ἐν ὀλίγοις θαυμαστός, ἥδιστον δὲ πάντων θέαμα καὶ καινότατον ἐπιδεικνύμενος αὑτὸν κομίζοντα τῷ θεῷ τὴν τοῦ βαρβάρου πανοπλίαν. δρυὸς γὰρ εὐκτεάνου πρέμνον ὄρθιον καὶ μέγα τεμών καὶ ἀσκήσας ὥσπερ τρόπαιον ἀνεδήσατο καὶ κατήρτησεν ἐξ αὐτοῦ τὰ λάφυρα, κόσμῳ διαθεὶς καὶ περιαρμόσας ἕκαστον. προϊούσης δὲ τῆς πομπῆς ἀράμενος αὐτὸς ἐπέβη τοῦ τεθρίππου, καὶ τροπαιοφόρον ἄγαλμα τῶν ἐπ’ ἐκείνου κάλλιστον καὶ διαπρεπέστατον ἐπόμπευε διὰ τῆς πόλεως, ὁ δὲ στρατὸς εἵπετο καλλίστοις ὅπλοις κεκοσμημένος, ᾄδων ἅμα πεποιημένα μέλη καὶ παιᾶνας ἐπινικίους εἷς τὸν θεὸν καὶ τὸν στρατηγόν. οὕτω δὲ προβὰς καὶ παρελθὼν εἷς τὸν νεὼν τοῦ Φερετρίου Διός, ἀνέστησε καὶ καθιέρωσε, τρίτος καὶ τελευταῖος ἄχρι τοῦ καθ’ ἡμᾶς αἰῶνος, πρῶτος μὲν γὰρ ἀνήνεγκε σκῦλα Ῥωμύλος ἀπὸ Ἄκρωνος τοῦ Καινινήτου, δεύτερος δὲ Κόσσος Κορνήλιος ἀπὸ Τολουμνίου Τυρρηνοῦ, μετὰ δὲ τούτους Μάρκελλος ἀπὸ Βριτομάτου, βασιλέως Γαλατῶν, μετὰ δὲ Μάρκελλον οὐδὲ εἷς. καλεῖται δὲ ὁ μὲν θεὸς ᾧ πέμπεται Φερέτριος Ζεύς, ὡς μὲν ἔνιοί φασὶν, ἀπὸ τοῦ φερετρευομένου τροπαίου, κατὰ τὴν Ἑλληνίδα γλῶσσαν ἔτι πολλὴν τότε συμμεμιγμένην τῇ Λατίνων, ὡς δὲ ἕτεροι, Διός ἐστιν ἡ προσωνυμία κεραυνοβολοῦντος. τὸ γὰρ τύπτειν φερῖρε οἱ Ῥωμαῖοι καλοῦσιν. ἄλλοι δὲ παρὰ τὴν τοῦ πολεμίου πληγὴν γεγονέναι τοὔνομα λέγουσι· καὶ γὰρ νῦν ἐν ταῖς μάχαις, ὅταν διώκωσι τοὺς πολεμίους, πυκνὸν τὸ φέρι, τουτέστι παῖε, παρεγγυῶσιν ἀλλήλοις. τὰ δὲ σκῦλα σπόλια μὲν κοινῶς, ἰδίως δὲ ὀπίμια ταῦτα καλοῦσι. καίτοι φασὶν ἐν τοῖς ὑπομνήμασι Νομᾶν Πομπίλιον καὶ πρώτων ὀπιμίων καὶ δευτέρων καὶ τρίτων μνημονεύειν, τὰ μὲν πρῶτα ληφθέντα τῷ Φερετρίῳ Διῒ κελεύοντα καθιεροῦν, τὰ δεύτερα δὲ τῷ Ἄρει, τὰ δὲ τρίτα τῷ Κυρίνῳ, καὶ λαμβάνειν γέρας ἀσσάρια τριακόσια τὸν πρῶτον, τὸν δὲ δεύτερον διακόσια, τὸν δὲ τρίτον ἑκατόν, ὁ μέντοι πολὺς οὗτος ἐπικρατεῖ λόγος, ὡς ἐκείνων μόνων ὀπιμίων ὄντων, ὅσα καὶ παρατάξεως οὔσης καὶ πρῶτα καὶ στρατηγοῦ στρατηγὸν ἀνελόντος. περὶ μὲν οὖν τούτων ἐπὶ τοσοῦτον.", "st": "Marc. 8.1"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι τὴν νίκην ἐκείνην καὶ τοῦ πολέμου τὴν κατάλυσιν οὕτως ὑπερηγάπησαν ὥστε καὶ τῷ Πυθίῳ χρυσοῦν κρατῆρα ἀπὸ λιτρῶν … εἷς Δελφοὺς ἀποστεῖλαι χαριστήριον, καὶ τῶν λαφύρων ταῖς τε συμμαχίσι μεταδοῦναι πόλεσι λαμπρῶς, καὶ πρὸς Ἱέρωνα πολλὰ πέμψαι, τὸν Συρακουσίων βασιλέα, φίλον ὄντα καὶ σύμμαχον.", "st": "Marc. 8.6"}, {"sp": "N", "t": "Ἀννίβου δὲ ἐμβαλόντος εἰς Ἰταλίαν ἐπέμφθη μὲν ὁ Μάρκελλος ἐπὶ Σικελίαν στόλον ἄγων ἐπεὶ δὲ ἡ περὶ Κάννας ἀτυχία συνέπεσε καὶ Ῥωμαίων οὐκ ὀλίγαι μυριάδες ἐν τῇ μάχῃ διεφθάρησαν, ὀλίγοι δὲ σωθέντες εἰς Κανύσιον συνεπεφεύγεσαν, ἦν δὲ προσδοκία τὸν Ἀννίβαν εὐθὺς ἐπὶ τὴν Ῥώμην ἐλᾶν, ὅπερ ἦν κράτιστον τῆς δυνάμεως ἀνῃρηκότα, πρῶτον μὲν ὁ Μάρκελλος ἀπὸ τῶν νεῶν ἔπεμψε τῇ πόλει φυλακὴν πεντακοσίους καὶ χιλίους ἄνδρας, ἔπειτα δόγμα τῆς βουλῆς δεξάμενος εἰς Κανύσιον παρῆλθε, καὶ τοὺς ἐκεῖ συνειλεγμένους παραλαβὼν ἐξήγαγε τῶν ἐρυμάτων ὡς οὐ προησόμενος τὴν χώραν. Ῥωμαίοις δὲ τῶν ἡγεμονικῶν καὶ δυνατῶν ἀνδρῶν οἱ μὲν ἐτεθνήκεσαν ἐν ταῖς μάχαις, Φαβίου δὲ Μαξίμου τοῦ πλεῖστον ἔχοντος ἀξίωμα πίστεως καὶ συνέσεως, τὸ λίαν ἀπηκριβωμένον ἐν τοῖς ὑπὲρ τοῦ μὴ παθεῖν λογισμοῖς ὡς ἀργὸν ἐπὶ τὰς πράξεις καὶ ἄτολμον ᾐτιῶντο· καὶ νομίζοντες ἀποχρῶντα τοῦτον ἔχειν πρὸς ἀσφάλειαν, οὐ διαρκῆ δὲ πρὸς ἄμυναν στρατηγόν, ἐπὶ τὸν Μάρκελλον ἀφεώρων, καὶ τὸ θαρραλέον αὐτοῦ καὶ δραστήριον πρὸς τὴν ἐκείνου κεραννύντες καὶ ἁρμόττοντες εὐλάβειαν καὶ πρόνοιαν, ποτὲ μὲν ἀμφοτέρους ἅμα χειροτονοῦντες ὑπάτους, ποτὲ δὲ ἐν μέρει, τὸν μὲν ὕπατον, τὸν δὲ ἀνθύπατον, ἐξέπεμπον. ὁ δὲ Ποσειδώνιός φησι τὸν μὲν Φάβιον θυρεὸν καλεῖσθαι, τὸν δὲ Μάρκελλον ξίφος, αὐτὸς δὲ ὁ Ἀννίβας ἔλεγε τὸν μὲν Φάβιον ὡς παιδαγωγὸν φοβεῖσθαι, τὸν δὲ Μάρκελλον ὡς ἀνταγωνιστήν ὑφ’ οὗ μὲν γὰρ κωλύεσθαι κακόν τι ποιεῖν, ὑφ’ οὗ δὲ καὶ πάσχειν.", "st": "Marc. 9.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἀνέσεως πολλῆς καί θρασύτητος ἐκ τοῦ κρατεῖν τοῦ Ἀννίβαν τοῖς στρατιώταις ἐγγενομένης, τοὺς ἀποσκιδναμένους τοῦ στρατοπέδου καί κατατρέχοντας τὴν χώραν ἐπιτιθέμενος κατέκοπτε καί ὑπανήλισκε τῆς δυνάμεως· ἔπειτα πρὸς Νέαν πόλιν καί Νῶλαν βοηθήσας Νεαπολίτας μὲν ἐπέρρωσεν αὐτοὺς καθ’ ἑαυτοὺς βεβαίους ὄντας Ῥωμαίοις, εἷς δὲ Νῶλαν εἰσελθὼν στάσιν εὗρε, τῆς βουλῆς τὸν δῆμον ἀννιβίζοντα μεταχειρίσασθαι καί καταρτίσαι μὴ δυναμένης. ἦν γὰρ τις ἀνὴρ εὐγενείᾳ, τε πρωτεύων ἐν τῇ πόλει καί κατ’ ἀνδρείαν ἐπιφανής, ὄνομα Βάνδιος· τοῦτον ἐν Κάνναις περιόπτως ἀγωνισάμενον καί πολλοὺς μὲν ἀνελόντα τῶν Καρχηδονίων, τέλος δὲ αὐτὸν ἐν τοῖς νεκροῖς εὑρεθέντα πολλῶν βελῶν κατάπλεων τὸ σῶμα, θαυμάσας ὁ Ἀννίβας οὐ μόνον ἀφῆκεν ἄνευ λύτρων, ἀλλὰ καί δῶρα προσέθηκε καί φίλον ἐποιήσατο καί ξένον. ἀμειβόμενος οὖν τὴν χάριν ὁ Βάνδιος εἷς ἦν τῶν ἀννιβιζόντων προθύμως, καί τὸν δῆμον ἰσχύων ἐξῆγε πρὸς ἀπόστασιν. ὁ δὲ Μάρκελλος ἀνελεῖν μὲν ἄνδρα λαμπρὸν οὕτω τὴν τύχην καί κεκοινωνηκότα τῶν μεγίστων Ῥωμαίοις ἀγώνων οὐχ ὅσιον ἡγεῖτο, πρὸς δὲ τῷ φύσει φιλανθρώπῳ καί πιθανὸς ὢν ὁμιλίᾳ προσάγεσθαι φιλότιμον ἦθος, ἀσπασαμένου ποτε τὸν Βανδίου αὐτὸν ἠρώτησεν ὅστις ἀνθρώπων εἴη, πάλαι μὲν εὖ εἰδώς, ἀρχὴν δὲ καί πρόφασιν ἐντεύξεως ζητῶν. ὡς γὰρ εἶπε, Λεύκιος Βάνδιος, οἷον ἡσθεὶς καί θαυμάσας ὁ Μάρκελλος, ἦ γὰρ ἐκεῖνος, ἔφη, σὺ Βάνδιος, οὗ πλεῖστος ἐν Ῥώμῃ λόγος τῶν ἐν Κάνναις ἀγωνισαμένων, ὡς μόνου Παῦλον Αἰμίλιον τὸν ἄρχοντα μὴ προλιπόντος, ἀλλὰ τὰ πλεῖστα τῶν ἐκείνῳ φερομένων βελῶν ὑποστάντος τῷ σώματι καί ἀναδεξαμένου; φήσαντος δὲ τοῦ Βανδίου καί τι καί παραφήναντος αὐτῷ τῶν τραυμάτων, εἶτα, ἔφη, τηλικαῦτα γνωρίσματα φέρων τῆς πρὸς ἡμᾶς φιλίας οὐκ εὐθὺς προσῄεις; ἢ κακοί σοι δοκοῦμεν ἀρετὴν ἀμείβεσθαι φίλων οἷς ἐστι τιμὴ καί παρὰ τοῖς πολεμίοις; ταῦτα φιλοφρονηθεὶς καί δεξιωσάμενος ἵππον τε δωρεῖται πολεμιστὴν αὐτῷ καὶ δραχμὰς ἀργυρίου πεντακοσίας.", "st": "Marc. 10.1"}, {"sp": "N", "t": "ἐκ τούτου βεβαιότατος μὲν ἦν Μαρκέλλῳ παραστάτης καὶ σύμμαχος, δεινότατος δὲ μηνυτὴς καὶ κατήγορος τῶν τἀναντία φρονούντων ὁ Βάνδιος. ἦσαν δὲ πολλοί, καὶ διενοοῦντο τῶν Ῥωμαίων ἐπεξιόντων τοῖς πολεμίοις αὐτοὶ διαρπάσαι τὰς ἀποσκευάς. διὸ συντάξας ὁ Μάρκελλος τὴν δύναμιν ἐντός παρὰ τὰς πύλας ἔστησε τὰ σκευοφόρα, καὶ τοῖς Νωλανοῖς διὰ κηρύγματος ἀπεῖπε πρὸς τὰ τείχη προσπελάζειν. ἦν οὖν ὅπλων ἐρημία καὶ τὸν Ἀννίβαν ἐπεσπάσατο προσάγειν ἀτακτότερον, ὡς τῶν ἐν τῇ πόλει ταραττομένων. ἐν τούτῳ δὲ τὴν καθ’ αὑτὸν πύλην ἀναπετάσαι κελεύσας ὁ Μάρκελλος ἐξήλασεν, ἔχων μεθ’ ἑαυτοῦ τῶν ἱπποτῶν τοὺς λαμπροτάτους, καὶ προσπεσὼν κατὰ στόμα συνείχετο τοῖς πολεμίοις. μετ’ ὀλίγον δ’ οἱ πεζοὶ καθ’ ἑτέραν πύλην ἐχώρουν μετὰ δρόμου καὶ βοῆς· καὶ πρὸς τούτους αὖθις αὖ τοῦ Ἀννίβᾳ μερίζοντος τὴν δύναμιν ἡ τρίτη τῶν πυλῶν ἀνεῴγνυτο, καὶ δι’ αὐτῆς ἐξέθεον οἱ λοιποὶ καὶ προσέκειντο πανταχόθεν ἐκπεπληγμένοις τῷ ἀπροσδοκήτῳ καὶ κακῶς ἀμυνομένοις τοὺς ἐν χερσὶν ἤδη διὰ τοὺς ὕστερον ἐπιφερομένους, κἀνταῦθα πρῶτον οἱ σὺν Ἀννίβᾳ Ῥωμαίοις ἐνέδωκαν, ὠθούμενοι φόνῳ πολλῷ καὶ τραύμασι πρὸς τὸ στρατόπεδον. λέγονται γὰρ ὑπὲρ πεντακισχιλίους ἀποθανεῖν, ἀποκτεῖναι δὲ Ῥωμαίων οὐ πλείονας ἢ πεντακοσίους, ὁ δὲ Λίβιος οὕτω μὲν οὐ διαβεβαιοῦται γενέσθαι μεγάλην ἧτταν οὐδὲ πεσεῖν νεκροὺς τοσούτους τῶν πολεμίων, κλέος δὲ μέγα Μαρκέλλῳ καὶ Ῥωμαίοις ἐκ κακῶν θάρσος ἀπὸ τῆς μάχης ἐκείνης ὑπάρξαι θαυμαστόν, οὐχ ὡς πρὸς ἄμαχον οὐδὲ ἀήττητον, ἀλλά τι καὶ παθεῖν δυνάμενον διαγωνιζομένοις πολέμιον.", "st": "Marc. 11.1"}, {"sp": "N", "t": "διὸ καὶ θατέρου τῶν ὑπάτων ἀποθανόντος ἐκάλει Μάρκελλον ὁ δῆμος ἐπὶ τὴν διαδοχὴν ἀπόντα, καὶ βίᾳ τῶν ἀρχόντων ὑπερέθετο τὴν κατάστασιν ἕως ἐκεῖνος ἦλθεν ἀπὸ τοῦ στρατοπέδου. καὶ πάσαις μὲν ἀπεδείχθη ταῖς ψήφοις ὕπατος, ἐπιβροντήσαντος δὲ τοῦ θεοῦ καὶ τῶν ἱερέων οὐκ αἴσιον τιθεμένων τὸ σημεῖον, ἐμφανῶς δὲ κωλύειν ὀκνούντων καὶ δεδιότων τὸν δῆμον, αὐτὸς ἐξωμόσατο τὴν ἀρχήν. οὐ μέντοι τὴν στρατείαν ἔφυγεν, ἀλλ’ ἀνθύπατος ἀναγορευθεὶς καὶ πάλιν πρὸς Νῶλαν ἐπανελθὼν εἰς τὸ στρατόπεδον κακῶς ἐποίει τοὺς ᾑρημένους τὰ τοῦ Φοίνικος, ὡς δὲ ὀξεῖαν ἐπ’ αὐτὸν θέμενος βοήθειαν ἐκεῖνος ἧκε, προκαλουμένῳ μὲν ἐκ παρατάξεως οὐκ ἠβουλήθη διαγωνίσασθαι, τρέψαντι δὲ τὸ πλεῖστον ἐφ’ ἁρπαγὴν τοῦ στρατοῦ καὶ μηκέτι προσδεχομένῳ μάχην ἐπεξῆλθε, διαδοὺς δόρατα τῶν ναυμάχων μεγάλα τοῖς πεζοῖς, καὶ διδάξας πόρρωθεν συντηροῦσι παίειν τοὺς Καρχηδονίους, ἀκοντιστὰς μὲν οὐκ ὄντας αἰχμαῖς δὲ χρωμένους ἐκ χειρὸς βραχείαις. διὸ καὶ δοκοῦσι τότε δεῖξαι τὰ νῶτα Ῥωμαίοις ὅσοι συνέβαλον καὶ φυγὴν ἀπροφάσιστον φυγεῖν, ἀποβαλόντες ἐξ ἑαυτῶν νεκροὺς μὲν γενομένους πεντακισχιλίους, αἰχμαλώτους δὲ ἑξακοσίους, καὶ τῶν ἐλεφάντων τέσσαρας μὲν πεσόντας, δύο δὲ ζωοὺς ἁλόντας. ὃ δ’ ἦν μέγιστον, ἡμέρᾳ τρίτῃ μετὰ τὴν μάχην ἱππεῖς Ἰβήρων καὶ Νομάδων μιγάδες αὐτομολοῦσιν ὑπὲρ τοὺς τριακοσίους, οὔπω πρότερον Ἀννίβα τοῦτο παθόντος, ἀλλ’ ἐκ ποικίλων καὶ πολυτρόπων συνηρμοσμένον ἐθνῶν βαρβαρικὸν στράτευμα πλεῖστον χρόνον ἐν μιᾷ γνώμῃ διαφυλάξαντος. οὗτοι μὲν οὖν πιστοὶ παρέμειναν εἰς ἅπαν αὐτῷ τε τῷ Μαρκέλλῳ καὶ τοῖς μετ’ αὐτὸν στρατηγοῖς.", "st": "Marc. 12.1"}, {"sp": "N", "t": "ὁ δὲ Μάρκελλος ἀποδειχθεὶς ὕπατος τὸ τρίτον εἰς Σικελίαν ἔπλευσεν. αἱ γὰρ Ἀννίβου περὶ τὸν πόλεμον εὐπραξίαι Καρχηδονίους ἐπῆραν αὖθις ἀντιλαμβάνεσθαι τῆς νήσου, μάλιστα τεταραγμένων τῶν περὶ τὰς Συρακούσας μετὰ τὴν Ἱερωνύμου τοῦ τυράννου τελευτήν. διὸ καὶ Ῥωμαίων ἦν ἐκεῖ προαπεσταλμένη δύναμις καὶ στρατηγὸς Ἄππιος. ταύτην παραλαμβάνοντι τῷ Μαρκέλλῳ προσπίπτουσι Ῥωμαῖοι πολλοί συμφορᾷ κεχρημένοι τοιαύτῃ, τῶν περὶ Κάννας παραταξαμένων πρὸς Ἀννίβαν οἱ μὲν ἔφυγον, οἱ δὲ ζῶντες ἥλωσαν, τοσοῦτον πλῆθος ὡς δοκεῖν Ῥωμαίοις ὑπολελεῖφθαι μηδὲ τοὺς τὰ τείχη διαφυλάξοντας. τοῖς δὲ ἄρα τοσοῦτο τοῦ φρονήματος καὶ μεγαλοψυχίας περιῆν ὥστε τοὺς μὲν αἰχμαλώτους ἐπὶ μικροῖς λύτροις ἀποδιδόντος Ἀννίβου μὴ λαβεῖν, ἀλλ’ ἀποψηφίσασθαι καὶ περιϊδεῖν τοὺς μὲν ἀναιρεθέντας, τοὺς δὲ πραθέντας ἔξω τῆς Ἰταλίας, τῶν δὲ φυγῇ περιγενομένων τὸ πλῆθος εἰς Σικελίαν ἀποστεῖλαι, διακελευσαμένους Ἰταλίας μὴ ἐπιβαίνειν ἕως πολεμοῦσι πρὸς Ἀννίβαν. οὗτοι δὴ τῷ Μαρκέλλῳ παραγενομένῳ προσπεσόντες ἀθρόοι, καὶ χαμαὶ καταβαλόντες αὑτούς, ᾔτουν τάξιν ἐπιτίμου στρατείας μετὰ πολλῆς βοῆς καὶ δακρύων, ἐπαγγελλόμενοι δείξειν δι’ ἔργων ἀτυχίᾳ τινὶ μᾶλλον ἢ δι’ ἀνανδρίαν αὐτῶν τὴν τροπὴν ἐκείνην γενομένην. οἰκτείρας οὖν αὐτοὺς ὁ Μάρκελλος ἔγραψε πρὸς τὴν σύγκλητον αἰτούμενος ἐκ τούτων ἀεὶ τῆς στρατιᾶς τὸ ἐπιλεῖπον ἀναπληροῦν. λόγων δὲ πολλῶν γενομένων ἐποιήσατο γνώμην ἡ βουλή μηδὲν εἰς δημόσια πράγματα δεῖσθαι Ῥωμαίους ἀνθρώπων ἀνάνδρων εἰ δὲ βούλεται χρῆσθαι Μάρκελλος αὐτοῖς ἴσως, μηδενὸς τῶν ἐπ’ ἀνδρείᾳ νομιζομένων στεφάνων καὶ γερῶν τυχεῖν ὑπάρχοντος, τοῦτο τὸ δόγμα Μάρκελλον ἠνίασε, καὶ μετὰ τὸν ἐν Σικελίᾳ πόλεμον ἐπανελθών ἐμέμψατο τὴν βουλήν, ὡς ἀντὶ πολλῶν καὶ μεγάλων οὐ παρασχοῦσαν αὐτῷ τοσούτων δυστυχίαν ἐπανορθώσασθαι πολιτῶν.", "st": "Marc. 13.1"}, {"sp": "N", "t": "τότε δ’ ἐν Σικελίᾳ πρῶτον μὲν ἀδικηθεὶς ὑπὸ Ἱπποκράτους στρατηγοῦ στρατηγοῦ, ὃς Καρχηδονίοις χαριζόμενος καὶ τυραννίδα κτώμενος αὑτῷ πολλοὺς διέφθειρε Ῥωμαίων πρὸς Λεοντίνοις, εἷλε τὴν τῶν Λεοντίνων πόλιν κατὰ κράτος, καὶ Λεοντίνους μὲν οὐκ ἠδίκησε, τῶν δὲ αὐτομόλων ὅσους ἔλαβε μαστιγώσας ἀπέκτεινε. τοῦ δ’ Ἱπποκράτους πρῶτον μὲν λόγον εἰς τὰς Συρακούσας προπέμψαντος ὡς Λεοντίνους ἡβηδὸν ἀποσφάττει Μάρκελλος, ἔπειτα δὲ τεταραγμένοις ἐπιπεσόντος καὶ τὴν πόλιν καταλαβόντος, ἄρας Μάρκελλος τῷ στρατῷ παντὶ πρὸς τὰς Συρακούσας ἐχώρει. καὶ καταστρατοπεδεύσας πλησίον εἰσέπεμψε μὲν πρέσβεις περὶ τῶν ἐν Λεοντίνοις διδάξοντας, ὡς δὲ οὐδὲν ἦν ὄφελος μὴ πειθομένων Συρακουσίων (ἐκράτουν γὰρ οἱ περὶ τὸν Ἱπποκράτην), προσβολὰς ἐποιεῖτο κατὰ γῆν ἅμα καὶ κατὰ θάλατταν, Ἀππίου μὲν τὸν πεζὸν ἐπάγοντος στρατόν, αὐτὸς δὲ πεντήρεις ἔχων ἑξήκοντα παντοδαπῶν ὅπλων καὶ βελῶν πλήρεις, ὑπὲρ δὲ μεγάλου ζεύγματος νεῶν ὀκτὼ πρὸς ἀλλήλας συνδεδεμένων μηχανὴν ἄρας ἐπέπλει πρὸς τὸ τεῖχος, τῷ πλήθει καὶ τῇ λαμπρότητι τῆς παρασκευῆς καὶ τῇ δόξῃ τῇ περὶ αὑτὸν πεποιθώς· ἧς ἄρα λόγος οὐδεὶς ἦν Ἀρχιμήδει καὶ τοῖς Ἀρχιμήδους μηχανήμασιν. ὧν ὡς μὲν ἔργον ἄξιον σπουδῆς οὐδὲν ὁ ἀνὴρ προὔθετο, γεωμετρίας δὲ παιζούσης ἐγεγόνει πάρεργα τὰ πλεῖστα, πρότερον φιλοτιμηθέντος Ἱέρωνος τοῦ βασιλέως καὶ πείσαντος Ἀρχιμήδη τρέψαι τι τῆς τέχνης ἀπὸ τῶν νοητῶν ἐπὶ τὰ σωματικά καὶ τὸν λόγον ἁμῶς γέ πως δι’ αἰσθήσεως μίξαντα ταῖς χρείαις ἐμφανέστερον καταστῆσαι τοῖς πολλοῖς.", "st": "Marc. 14.1"}, {"sp": "N", "t": "τὴν γὰρ ἀγαπωμένην ταύτην καὶ περιβόητον ὀργανικὴν ἤρξαντο μὲν κινεῖν οἱ περὶ Εὔδοξον καὶ Ἀρχύταν, ποικίλλοντες τῷ γλαφυρῷ γεωμετρίαν, καὶ λογικῆς καὶ γραμμικῆς ἀποδείξεως οὐκ εὐποροῦντα προβλήματα δι’ αἰσθητῶν καὶ ὀργανικῶν παραδειγμάτων ὑπερείδοντες, ὡς τὸ περὶ δύο μέσας ἀνὰ λόγον πρόβλημα καὶ στοιχεῖον ἐπὶ πολλὰ τῶν γραφομένων ἀναγκαῖον εἰς ὀργανικὰς ἐξῆγον ἀμφότεροι κατασκευάς, μεσογράφους τινὰς ἀπὸ καμπύλων γραμμῶν καὶ τμημάτων μεθαρμόζοντες· ἐπεὶ δὲ Πλάτων ἠγανάκτησε καὶ διετείνατο πρὸς αὐτούς ὡς ἀπολλύντας καὶ διαφθείροντας τὸ γεωμετρίας ἀγαθόν, ἀπὸ τῶν ἀσωμάτων καὶ νοητῶν ἀποδιδρασκούσης ἐπὶ τὰ αἰσθητά, καὶ προσχρωμένης αὖθις αὖ σώμασι πολλῆς καὶ φορτικῆς βαναυσουργίας δεομένοις, οὕτω διεκρίθη γεωμετρίας ἐκπεσοῦσα μηχανική, καὶ περιορωμένη πολὺν χρόνον ὑπὸ φιλοσοφίας μία τῶν στρατιωτίδων τεχνῶν ἐγεγόνει.", "st": "Marc. 14.5"}, {"sp": "N", "t": "καὶ μέντοι καὶ Ἀρχιμήδης, Ἱέρωνι τῷ βασιλεῖ συγγενὴς ὢν καὶ φίλος, ἔγραψεν ὡς τῇ δοθείσῃ δυνάμει τὸ δοθὲν βάρος κινῆσαι δυνατόν ἐστι· καὶ νεανιευσάμενος, ὥς φασι, ῥώμῃ τῆς ἀποδείξεως εἶπεν ὡς, εἰ γῆν εἶχεν ἑτέραν, ἐκίνησεν ἂν ταύτην μεταβὰς εἰς ἐκείνην. θαυμάσαντος δὲ τοῦ Ἱέρωνος, καὶ δεηθέντος εἰς ἔργον ἐξαγαγεῖν τὸ πρόβλημα καὶ δεῖξαί τι τῶν μεγάλων κινούμενον ὑπὸ σμικρᾶς δυνάμεως, ὁλκάδα τριάρμενον τῶν βασιλικῶν πόνῳ μεγάλῳ καὶ χειρὶ πολλῇ νεωλκηθεῖσαν, ἐμβαλὼν ἀνθρώπους τε πολλοὺς καὶ τὸν συνήθη φόρτον, αὐτὸς ἄπωθεν καθήμενος, οὐ μετὰ σπουδῆς, ἀλλὰ ἠρέμα τῇ χειρὶ σείων ἀρχήν τινα πολυσπάστου προσηγάγετο λείως καὶ ἀπταίστως καὶ ὥσπερ διὰ θαλάττης ἐπιθέουσαν. ἐκπλαγεὶς οὖν ὁ βασιλεὺς καὶ συννοήσας τῆς τέχνης τὴν δύναμιν, ἔπεισε τὸν Ἀρχιμήδην ὅπως αὐτῷ τὰ μὲν ἀμυνομένῳ, τὰ δ’ ἐπιχειροῦντι μηχανήματα κατασκευάσῃ πρὸς πᾶσαν ἰδέαν πολιορκίας, οἷς αὐτὸς μὲν οὐκ ἐχρήσατο, τοῦ βίου τὸ πλεῖστον ἀπόλεμον καὶ πανηγυρικὸν βιώσας, τότε δ’ ὑπῆρχε τοῖς Συρακουσίοις εἰς δέον ἡ παρασκευή καὶ μετὰ τῆς παρασκευῆς ὁ δημιουργός.", "st": "Marc. 14.7"}, {"sp": "N", "t": "ὡς οὖν προσέβαλον οἱ Ῥωμαῖοι διχόθεν, ἔκπληξις ἦν τῶν Συρακουσίων καὶ σιγὴ διὰ δέος, μηδὲν ἂν ἀνθέξειν πρὸς βίαν καὶ δύναμιν οἰομένων τοσαύτην. σχάσαντος δὲ τὰς μηχανὰς τοῦ Ἀρχιμήδους ἅμα τοῖς μὲν πεζοῖς ἀπήντα τοξεύματά τε παντοδαπὰ καὶ λίθων ὑπέρογκα μεγέθη, ῥοίζῳ καὶ τάχει καταφερομένων ἀπίστῳ, καὶ μηδενὸς ὅλως τὸ βρῖθος στέγοντος ἀθρόους ἀνατρεπόντων τοὺς ὑποπίπτοντας καὶ τὰς τάξεις συγχεόντων, ταῖς δὲ ναυσὶν ἀπὸ τῶν τειχῶν ἄφνω ὑπεραιωρούμεναι κεραῖαι τὰς μὲν ὑπὸ βρίθους στηρίζοντος ἄνωθεν ὠθοῦσαι κατέδυον εἰς βυθόν, τὰς δὲ χερσὶ σιδηραῖς ἢ στόμασιν εἰκασμένοις γεράνων ἀνασπῶσαι πρῴραθεν ὀρθὰς ἐπὶ πρύμναν ἐβάπτιζον, ἢ δι’ ἀντιτόνων ἔνδον ἐπιστρεφόμεναι καὶ περιαγόμεναι τοῖς ὑπὸ τὸ τεῖχος πεφυκόσι κρημνοῖς καὶ σκοπέλοις προσήρασσον, ἅμα φθόρῳ πολλῷ τῶν ἐπιβατῶν συντριβομένων. πολλάκις δὲ μετέωρος ἐξαρθεῖσα ναῦς ἀπὸ τῆς θαλάσσης δεῦρο κἀκεῖσε περιδινουμένη καὶ κρεμαμένη θέαμα φρικῶδες ἦν, μέχρι οὗ τῶν ἀνδρῶν ἀπορριφέντων καὶ διασφενδονηθέντων κενὴ προσπέσοι τοῖς τείχεσιν ἢ περιολίσθοι τῆς λαβῆς ἀνείσης. ἣν δὲ ὁ Μάρκελλος ἀπὸ τοῦ ζεύγματος ἐπῆγε μηχανήν, σαμβύκη μὲν ἐκαλεῖτο δι’ ὁμοιότητά τινα σχήματος πρὸς τὸ μουσικὸν ὄργανον, ἔτι δὲ ἄπωθεν αὐτῆς προσφερομένης πρὸς τὸ τεῖχος ἐξήλατο λίθος δεκατάλαντος ὁλκήν, εἶτα ἕτερος ἐπὶ τούτῳ καὶ τρίτος, ὧν οἱ μὲν αὐτῇ ἐμπεσόντες μεγάλῳ κτύπῳ καὶ κλύδωνι τῆς μηχανῆς τήν τε βάσιν συνηλόησαν καὶ τὸ γόμφωμα διέσεισαν καὶ διέσπασαν τοῦ ζεύγματος, ὥστε τὸν Μάρκελλον ἀπορούμενον αὐτόν τε ταῖς ναυσὶν ἀποπλεῖν κατὰ τάχος καὶ τοῖς πεζοῖς ἀναχώρησιν παρεγγυῆσαι.", "st": "Marc. 15.1"}, {"sp": "N", "t": "βουλευομένοις δὲ ἔδοξεν αὐτοῖς ἔτι νυκτὸς, ἂν δύνωνται, προσμῖξαι τοῖς τείχεσι· τοὺς γὰρ τόνους, οἷς χρῆσθαι τὸν Ἀρχιμήδην, ῥύμην ἔχοντας ὑπερπετεῖς ποιήσεσθαι τὰς τῶν βελῶν ἀφέσεις, ἐγγύθεν δὲ καὶ τελέως ἀπράκτους εἶναι διάστημα τῆς πληγῆς οὐκ ἐχούσης. ὁ δ’ ἦν, ὡς ἔοικεν, ἐπὶ ταῦτα πάλαι παρεσκευασμένος ὀργάνων τε συμμέτρους πρὸς πᾶν διάστημα κινήσεις καὶ βέλη βραχέα, καὶ διὰ τὸ τεῖχος οὐ μεγάλων, πολλῶν δὲ καὶ συνεχῶν τρημάτων ὄντων, οἱ σκορπίοι βραχύτονοι μέν, ἐγγύθεν δὲ πλῆξαι παρεστήκεσαν ἀόρατοι τοῖς πολεμίοις.", "st": "Marc. 15.5"}, {"sp": "N", "t": "ὡς οὖν προσέμιξαν οἰόμενοι λανθάνειν, αὖθις αὖ βέλεσι πολλοῖς ἐντυγχάνοντες καὶ πληγαῖς, πετρῶν μὲν ἐκ κεφαλῆς ἐπ’ αὐτοὺς φερομένων ὥσπερ πρὸς κάθετον, τοῦ δὲ τείχους τοξεύματα πανταχόθεν ἀναπέμποντος, ἀνεχώρουν ὀπίσω. κἀνταῦθα πάλιν αὐτῶν εἰς μῆκος ἐκτεταγμένων, βελῶν ἐκθεόντων καὶ καταλαμβανόντων ἀπιόντας ἐγίνετο πολὺς μὲν αὐτῶν φθόρος, πολὺς δὲ τῶν νεῶν συγκρουσμός, οὐδὲν ἀντιδρᾶσαι τοὺς πολεμίους δυναμένων, τὰ γὰρ πλεῖστα τῶν ὀργάνων ὑπὸ τὸ τεῖχος ἐσκευοποίητο τῷ Ἀρχιμήδει, καὶ θεομαχοῦσιν ἐῴκεσαν οἱ Ῥωμαῖοι, μυρίων αὐτοῖς κακῶν ἐξ ἀφανοῦς ἐπιχεομένων.", "st": "Marc. 16.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὁ Μάρκελλος ἀπέφυγέ τε καὶ τοὺς σὺν ἑαυτῷ σκώπτων τεχνίτας καὶ μηχανοποιοὺς ἔλεγεν οὐ παυσόμεθα πρὸς τὸν γεωμετρικὸν τοῦτον Βριάρεων πολεμοῦντες, ὃς ταῖς μὲν ναυσὶν ἡμῶν κυαθίζει ἐκ τῆς θαλάσσης, τὴν δὲ σαμβύκην ῥαπίζων μετ’ αἰσχύνης ἐκβέβληκε, τοὺς δὲ μυθικοὺς ἑκατόγχειρας ὑπεραίρει τοσαῦτα βάλλων ἅμα βέλη καθ’ ἡμῶν; τῷ γὰρ ὄντι πάντες οἱ λοιποὶ Συρακούσιοι σῶμα τῆς Ἀρχιμήδους παρασκευῆς ἦσαν, ἡ δὲ κινοῦσα πάντα καὶ στρέφουσα ψυχὴ μία, τῶν μὲν ἄλλων ὅπλων ἀτρέμα κειμένων, μόνοις δὲ τοῖς ἐκείνου τότε τῆς πόλεως χρωμένης καὶ πρὸς ἄμυναν καὶ πρὸς ἀσφάλειαν. τέλος δὲ τοὺς Ῥωμαίους οὕτω περιφόβους γεγονότας ὁρῶν ὁ Μάρκελλος ὥστ’, εἰ καλῴδιον ἢ ξύλον ὑπὲρ τοῦ τείχους μικρὸν ὀφθείη προτεινόμενον, τοῦτο ἐκεῖνο, μηχανήν τινα κινεῖν ἐπ’ αὐτοὺς Ἀρχιμήδη βοῶντας ἀποτρέπεσθαι καὶ φεύγειν, ἀπέσχετο μάχης ἁπάσης καὶ προσβολῆς, τὸ λοιπὸν ἐπὶ τῷ χρόνῳ τὴν πολιορκίαν θέμενος.", "st": "Marc. 17.1"}, {"sp": "N", "t": "τηλικοῦτον μέντοι φρόνημα καὶ βάθος ψυχῆς καὶ τοσοῦτον ἐκέκτητο θεωρημάτων πλοῦτον Ἀρχιμήδης ὥστε, ἐφ’ οἷς ὄνομα καὶ δόξαν οὐκ ἀνθρωπίνης, ἀλλὰ δαιμονίου τινὸς ἔσχε συνέσεως, μηθὲν ἐθελῆσαι σύγγραμμα περὶ τούτων ἀπολιπεῖν, ἀλλὰ τὴν περὶ τὰ μηχανικὰ πραγματείαν καὶ πᾶσαν ὅλως τέχνην χρείας ἐφαπτομένην ἀγεννῆ καὶ βάναυσον ἡγησάμενος, εἰς ἐκεῖνα καταθέσθαι μόνα τὴν αὐτοῦ φιλοτιμίαν οἷς τὸ καλὸν καὶ περιττὸν ἀμιγὲς τοῦ ἀναγκαίου πρόσεστιν, ἀσύγκριτα μὲν ὄντα τοῖς ἄλλοις, ἔριν δὲ παρέχοντα πρὸς τὴν ὕλην τῇ ἀποδείξει, τῆς μὲν τὸ μέγεθος καὶ τὸ κάλλος, τῆς δὲ τὴν ἀκρίβειαν καὶ τὴν δύναμιν ὑπερφυῆ παρεχομένης· οὐ γὰρ ἔστιν ἐν γεωμετρίᾳ χαλεπωτέρας καὶ βαρυτέρας ὑποθέσεις ἐν ἁπλουστέροις λαβεῖν καὶ καθαρωτέροις στοιχείοις γραφομένας, καὶ τοῦθ’ οἱ μὲν εὐφυΐᾳ τοῦ ἀνδρὸς προσάπτουσιν, οἱ δὲ ὑπερβολῇ τινι πόνου νομίζουσιν ἀπόνως πεποιημένῳ καὶ ῥᾳδίως ἕκαστον ἐοικὸς γεγονέναι· ζητῶν μὲν γὰρ οὐκ ἄν τις εὕροι δι’ αὐτοῦ τὴν ἀπόδειξιν, ἅμα δὲ τῇ μαθήσει παρίσταται δόξα τοῦ κἂν αὐτὸν εὑρεῖν οὕτω λείαν ὁδὸν ἄγει καὶ ταχεῖαν ἐπὶ τὸ δεικνύμενον. οὔκουν οὐδὲ ἀπιστῆσαι τοῖς περὶ αὐτοῦ λεγομένοις ἐστίν, ὡς ὑπ’ οἰκείας δή τινος καὶ συνοίκου θελγόμενος ἀεὶ σειρῆνος ἐλέληστο καὶ σίτου καὶ θεραπείας σώματος ἐξέλειπε, βίᾳ δὲ πολλάκις ἑλκόμενος ἐπ’ ἄλειμμα καὶ λουτρόν, ἐν ταῖς ἐσχάραις ἔγραφε σχήματα τῶν γεωμετρικῶν, καὶ τοῦ σώματος ἀληλιμμένου διῆγε τῷ δακτύλῳ γραμμάς, ὑπὸ ἡδονῆς μεγάλης κάτοχος ὢν καὶ μουσόληπτος ἀληθῶς. πολλῶν δὲ καὶ καλῶν εὑρετὴς γεγονώς λέγεται τῶν φίλων δεηθῆναι καὶ τῶν συγγενῶν ὅπως αὐτοῦ μετὰ τὴν τελευτὴν ἐπιστήσωσι τῷ τάφῳ τὸν περιλαμβάνοντα τὴν σφαῖραν ἐντὸς κύλινδρον, ἐπιγράψαντες τὸν λόγον τῆς ὑπεροχῆς τοῦ περιέχοντος στερεοῦ πρὸς τὸ περιεχόμενον.", "st": "Marc. 17.4"}, {"sp": "N", "t": "Ἀρχιμήδης μὲν οὖν τοιοῦτος γενόμενος ἀήττητον ἑαυτόν τε καὶ τὴν πόλιν, ὅσον ἐφ’ ἑαυτῷ, διεφύλαξε. τῆς δὲ πολιορκίας διὰ μέσου Μάρκελλος εἷλε μὲν Μεγαρέας, πόλιν ἐν ταῖς παλαιοτάταις τῶν Σικελιωτίδων, εἷλε δὲ τὸ Ἱπποκράτους πρὸς Ἀκρίλλαις στρατόπεδον, καὶ κατέκτεινεν ὑπὲρ ὀκτακισχιλίους ἐπιπεσὼν χάρακα βαλλομένοις, ἐπέδραμε δὲ πολλὴν Τῆς Σικελίας καὶ πόλεις ἀπέστησε Καρχηδονίων καὶ μάχας ἐνίκησε πάσας τοὺς ἀντιταχθῆναι τολμήσαντας. χρόνῳ δὲ προϊόντι Δάμιππόν τινα Σπαρτιάτην ἐκ Συρακουσῶν λαβὼν ἐκπλέοντα αἰχμάλωτον, ἀξιούντων ἐπὶ λύτροις τῶν Συρακοσίων κομίσασθαι τὸν ἄνδρα, πολλάκις ὑπὲρ τούτου διαλεγόμενος καὶ συντιθέμενος πύργον τινὰ κατεσκέψατο φυλαττόμενον μὲν ἀμελῶς, ἄνδρας δὲ δυνάμενον δέξασθαι κρύφα, τοῦ τείχους ἐπιβατοῦ παρ’ αὐτὸν ὄντος. ὡς οὖν τό τε ὕψος ἐκ τοῦ πολλάκις προσιέναι καὶ διαλέγεσθαι πρὸς τὸν πύργον εἰκάσθη καλῶς καὶ κλίμακες παρεσκευάσθησαν, ἑορτὴν Ἀρτέμιδι τοὺς Συρακουσίους ἄγοντας καὶ πρὸς οἶνον ὡρμημένους καὶ παιδιὰν παραφυλάξας, ἔλαθεν οὐ μόνον τὸν πύργον κατασχών, ἀλλὰ καὶ κύκλῳ τὸ τεῖχος παρεμπλήσας ὅπλων πρὶν ἡμέραν γενέσθαι, καὶ τὰ Ἑξάπυλα διακόψας. ἀρχομένων δὲ κινεῖσθαι καὶ ταράττεσθαι τῶν Συρακουσίων πρὸς τὴν αἴσθησιν, ἅμα πανταχόθεν ταῖς σάλπιγξι χρῆσθαι κελεύσας φυγὴν ἐποίησε πολλὴν καὶ φόβον, ὡς οὐδενὸς μέρους ἀναλώτου μένοντος, ἔμενε δὲ τὸ καρτερώτατον καὶ κάλλιστον καὶ μέγιστον Ἀχραδινὴ καλεῖται διὰ τὸ τετειχίσθαι πρὸς τὴν ἔξω πόλιν, ἧς τὸ μὲν Νέαν, τὸ δὲ Τύχην ὀνομάζουσι.", "st": "Marc. 18.1"}, {"sp": "N", "t": "καὶ τούτων ἐχομένων ἅμα φάει διὰ τῶν Ἑξαπύλων ὁ Μάρκελλος κατῄει, μακαριζόμενος ὑπὸ τῶν ὑφ’ ἑαυτὸν ἡγεμόνων. αὐτός μέντοι λέγεται κατιδὼν ἄνωθεν καὶ περισκεψάμενος τῆς πόλεως τὸ μέγεθος καὶ τὸ κάλλος ἐπὶ πολὺ δακρῦσαι τῷ μέλλοντι γίνεσθαι συμπαθήσας, ἐννοήσας οἷον ἐξ οἵου σχῆμα καὶ μορφὴν ἀμείψει μετὰ μικρόν ὑπὸ τοῦ στρατοπέδου διαφορηθεῖσα. τῶν γὰρ ἡγεμόνων οὐδεὶς μὲν ἦν ὁ τολμῶν ἐναντιοῦσθαι τοῖς στρατιώταις αἰτουμένοις δι’ ἁρπαγῆς ὠφεληθῆναι, πολλοὶ δὲ καὶ πυρπολεῖν καὶ κατασκάπτειν ἐκέλευον. ἀλλὰ τοῦτον μὲν οὐδὲ ὅλως προσήκατο τὸν λόγον ὁ Μάρκελλος, μάλα δὲ ἄκων βιασθεὶς ἔδωκεν ἀπὸ χρημάτων καὶ ἀνδραπόδων ὠφελεῖσθαι, τῶν δὲ ἐλευθέρων σωμάτων ἀπεῖπεν ἅψασθαι, καὶ διεκελεύσατο μήτε ἀποκτεῖναί τινα μήτε αἰσχῦναι μήτε ἀνδραποδίσασθαι Συρακουσίων.", "st": "Marc. 19.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καίπερ οὕτω μετριάσαι δόξας οἰκτρὰ πάσχειν ἡγεῖτο τήν πόλιν, καὶ τὸ συμπαθοῦν καὶ τὸ συναλγοῦν ὅμως ἐν τοσούτῳ μεγέθει χαρᾶς ἡ ψυχὴ διέφαινεν ὁρῶντος ἐν βραχεῖ χρόνῳ πολλῆς καὶ λαμπρᾶς ἀφανισμὸν εὐδαιμονίας, λέγεται γὰρ οὐκ ἐλάττονα τοῦτον ἢ τὸν ὕστερον ἀπὸ Καρχηδόνος διαφορηθέντα πλοῦτον γενέσθαι· καὶ γὰρ τήν ἄλλην πόλιν οὐ μετὰ πολὺν χρόνον ἁλοῦσαν ἐκ προδοσίας ἐβιάσαντο διαρπάσαι, πλὴν τῶν βασιλικῶν χρημάτων· ταῦτα δὲ εἰς τὸ δημόσιον ἐξῃρέθη.", "st": "Marc. 19.3"}, {"sp": "N", "t": "μάλιστα δὲ τὸ Ἀρχιμήδους πάθος ἠνίασε Μάρκελλον. ἔτυχε μὲν γὰρ αὐτός τι καθ’ ἑαυτὸν ἀνασκοπῶν ἐπὶ διαγράμματος· καὶ τῇ θεωρίᾳ δεδωκὼς ἅμα τήν τε διάνοιαν καὶ τήν πρόσοψιν οὐ προῄσθετο τήν καταδρομὴν τῶν Ῥωμαίων οὐδὲ τήν ἅλωσιν τῆς πόλεως, ἄφνω δὲ ἐπιστάντος αὐτῷ στρατιώτου καὶ κελεύοντος ἀκολουθεῖν πρὸς Μάρκελλον οὐκ ἐβούλετο πρὶν ἢ τελέσαι τὸ πρόβλημα καὶ καταστῆσαι πρὸς τήν ἀπόδειξιν. ὁ δὲ ὀργισθεὶς καὶ σπασάμενος τὸ ξίφος ἀνεῖλεν αὐτόν. ἕτεροι μὲν οὖν λέγουσιν ἐπιστῆναι μὲν εὐθὺς ὡς ἀποκτενοῦντα ξιφήρη τὸν Ῥωμαῖον, ἐκεῖνον δ’ ἰδόντα δεῖσθαι καὶ ἀντιβολεῖν ἀναμεῖναι βραχὺν χρόνον, ὡς μὴ καταλίπῃ τὸ ζητούμενον ἀτελὲς καὶ ἀθεώρητον, τὸν δὲ οὐ φροντίσαντα διαχρήσασθαι. καὶ τρίτος ἐστὶ λόγος, ὡς κομίζοντι πρὸς Μάρκελλον αὐτῷ τῶν μαθηματικῶν ὀργάνων σκιόθηρα καὶ σφαίρας καὶ γωνίας, αἷς ἐναρμόττει τὸ τοῦ ἡλίου μέγεθος πρὸς τήν ὄψιν, στρατιῶται περιτυχόντες καὶ χρυσίον ἐν τῷ τεύχει δόξαντες φέρειν ἀπέκτειναν. ὅτι μέντοι Μάρκελλος ἤλγησε καὶ τὸν αὐτόχειρα τοῦ ἀνδρὸς ἀπεστράφη καθάπερ ἐναγῆ, τοὺς δὲ οἰκείους ἀνευρὼν ἐτίμησεν, ὁμολογεῖται.", "st": "Marc. 19.4"}, {"sp": "N", "t": "τῶν δὲ Ῥωμαίων τοῖς ἐκτὸς ἀνθρώποις δεινῶν μὲν εἶναι πόλεμον μεταχειρίσασθαι καὶ φοβερῶν εἰς χεῖρας ἐλθεῖν νομιζομένων, εὐγνωμοσύνης δὲ καὶ φιλανθρωπίας καὶ ὅλως πολιτικῆς ἀρετῆς ὑποδείγματα μὴ δεδωκότων, πρῶτος δοκεῖ τότε Μάρκελλος ὑποδεῖξαι τοῖς Ἕλλησι δικαιοτέρους Ῥωμαίους. οὕτω γὰρ ἐχρῆτο τοῖς συμβάλλουσι καὶ τοσαῦτα καὶ πόλεις καὶ ἰδιώτας εὐεργέτησεν ὥστε, εἴ τι περὶ Ἔνναν ἢ Μεγαρεῖς ἢ Συρακουσίους ἔργον ἦν εἰργασμένον οὐκ ἐπιεικὲς αὐτοῖς, τοῦτο τῶν πεπονθότων αἰτίᾳ μᾶλλον ἢ τῶν πεποιηκότων δοκεῖν γεγονέναι. μνησθήσομαι δὲ ἑνὸς ἀπὸ πολλῶν, πόλις ἐστι τῆς Σικελίας Ἐγγύϊον οὐ μεγάλη, ἀρχαία δὲ πάνυ καὶ διὰ θεῶν ἐπιφάνειαν ἔνδοξος, ἃς καλοῦσι Ματέρας. ἵδρυμα λέγεται Κρητῶν γενέσθαι τὸ ἱερόν καὶ λόγχας τινὰς ἐδείκνυσαν καὶ κράνη χαλκᾶ, τὰ μὲν ἔχοντα Μηριόνου, τὰ δὲ Οὐλίξου, τουτέστιν Ὀδυσσέως, ἐπιγραφάς, ἀνατεθεικότων ταῖς θεαῖς.", "st": "Marc. 20.1"}, {"sp": "N", "t": "ταύτην προθυμότατα καρχηδονίζουσαν Νικίας, ἀνὴρ πρῶτος τῶν πολιτῶν, ἔπειθε μεταθέσθαι πρὸς Ῥωμαίους, ἀναφανδὸν ἐν ταῖς ἐκκλησίαις παρρησιαζόμενος καὶ κακῶς φρονοῦντας ἐξελέγχων τοὺς ὑπεναντίους. οἱ δὲ φοβούμενοι τὴν δύναμιν αὐτοῦ καὶ τὴν δόξαν ἐβουλεύσαντο συναρπάσαι καὶ παραδοῦναι τοῖς Φοίνιξιν. αἰσθόμενος οὖν ὁ Νικίας ἤδη καὶ παραφυλαττόμενον ἀδήλως ἑαυτόν, ἐξέφερεν ἐν φανερῷ λόγους περὶ τῶν Ματέρων ἀνεπιτηδείους, καὶ πολλὰ πρὸς τὴν νομιζομένην ἐπιφάνειαν καὶ δόξαν ὡς ἀπιστῶν καὶ καταφρονῶν ἔπραττεν, ἡδομένων τῶν ἐχθρῶν ὅτι τὴν μεγίστην αἰτίαν αὐτὸς ἐφ’ ἑαυτὸν ὧν πείσεται παρεῖχε. γεγονότων δὲ τῶν πρὸς τὴν σύλληψιν ἑτοίμων ἦν μὲν ἐκκλησία τῶν πολιτῶν, ὁ δὲ Νικίας μεταξύ τι λέγων καὶ συμβουλεύων πρὸς τὸν δῆμον ἐξαίφνης ἀφῆκεν εἰς τὴν γῆν τὸ σῶμα, καὶ μικρὸν διαλιπών, οἷον εἰκὸς, ἡσυχίας σὺν ἐκπλήξει γενομένης, τὴν κεφαλὴν ἐπάρας καὶ περιενεγκὼν, ὑποτρόμῳ φωνῇ καὶ βαρείᾳ, κατὰ μικρὸν συντείνων καὶ παροξύνων τὸν ἦχον, ὡς ἑώρα φρίκῃ καὶ σιωπῇ κατεχόμενον τὸ θέατρον, ἀπορρίψας τὸ ἱμάτιον καὶ περιρρηξάμενος τὸν χιτωνίσκον, ἡμίγυμνος ἀναπηδήσας ἔθεε πρὸς τὴν ἔξοδον τοῦ θεάτρου, βοῶν ὑπὸ τῶν Ματέρων ἐλαύνεσθαι.", "st": "Marc. 20.4"}, {"sp": "N", "t": "μηδενὸς δὲ τολμῶντος ἅψασθαι μηδὲ ἀπαντῆσαι διὰ δεισιδαιμονίαν, ἀλλ’ ἐκτρεπομένων, ἐπὶ τὰς πύλας ἐξέδραμεν, οὔτε φωνῆς τινος οὔτε κινήσεως πρεπούσης δαιμονῶντι καὶ παραφρονοῦντι φεισάμενος. ἡ δὲ γυνὴ συνειδυῖα καὶ συντεχνάζουσα τῷ ἀνδρί, λαβοῦσα τὰ παιδία πρῶτον μὲν ἱκέτις προσεκυλινδεῖτο τοῖς μεγάροις τῶν θεῶν, ἔπειτα πλανώμενον ἐκεῖνον προσποιουμένη ζητεῖν κωλύοντος οὐδενὸς ἀσφαλῶς ἀπῆλθεν ἐκ τῆς πόλεως. καὶ διεσώθησαν μὲν οὕτως εἰς Συρακούσας πρὸς Μάρκελλον ἐπεὶ δὲ πολλὰ τοὺς Ἐγγυΐους ὑβρίσαντας καὶ πλημμελήσαντας ἐλθὼν Μάρκελλος ἔδησε πάντας ὡς τιμωρησόμενος, ὁ δὲ Νικίας ἐδάκρυσε παρεστώς, τέλος δὲ χειρῶν καὶ γονάτων ἁπτόμενος παρῃτεῖτο τοὺς πολίτας, ἀπὸ τῶν ἐχθρῶν ἀρξάμενος, ἐπικλασθεὶς ἀφῆκε πάντας καὶ τὴν πόλιν οὐδὲν ἠδίκησε, τῷ δὲ Νικίᾳ χώραν τε πολλὴν καὶ δωρεὰς πολλὰς ἔδωκε. ταῦτα μὲν οὖν Ποσειδώνιος ὁ φιλόσοφος ἱστόρησε.", "st": "Marc. 20.6"}, {"sp": "N", "t": "τὸν δὲ Μάρκελλον ἀνακαλουμένων τῶν Ῥωμαίων ἐπὶ τὸν ἐγχώριον καὶ σύνοικον πόλεμον, ἐπανερχόμενος τὰ πλεῖστα καὶ κάλλιστα τῶν ἐν Συρακούσαις ἐκίνησεν ἀναθημάτων, ὡς αὐτῷ τε πρὸς τὸν θρίαμβον ὄψις εἴη καὶ τῇ πόλει κόσμος. οὐδὲν γὰρ εἶχεν οὐδ’ ἐγίνωσκε πρότερον τῶν κομψῶν καὶ περιττῶν, οὐδὲ ἦν ἐν αὐτῇ τὸ χάριεν τοῦτο καὶ γλαφυρὸν ἀγαπώμενον, ὅπλων δὲ βαρβαρικῶν καὶ λαφύρων ἐναίμων ἀνάπλεως οὖσα καὶ περιεστεφανωμένη θριάμβων ὑπομνήμασι καὶ τροπαίοις οὐχ ἱλαρὸν οὐδ’ ἄφοβον οὐδὲ δειλῶν ἦν θέαμα καὶ τρυφώντων θεατῶν, ἀλλ’ ὥσπερ Ἐπαμεινώνδας τὸ Βοιώτιον πεδίον Ἄρεως ὀρχήστραν, Ξενοφῶν δὲ τὴν Ἔφεσον πολέμου ἐργαστήριον, οὕτως ἄν μοι δοκεῖ τις τότε τὴν Ῥώμην κατὰ Πίνδαρον βαθυπτολέμου τέμενος Ἄρεως προσειπεῖν. διὸ καὶ μᾶλλον εὐδοκίμησε παρὰ μὲν τῷ δήμῳ Μάρκελλος ἡδονὴν ἐχούσαις καὶ χάριν Ἑλληνικὴν καὶ πιθανότητα διαποικίλας ὄψεσι τὴν πόλιν, παρὰ δὲ τοῖς πρεσβυτέροις Φάβιος Μάξιμος, οὐδὲν γὰρ ἐκίνησε τοιοῦτον οὐδὲ μετήνεγκεν ἐκ τῆς Ταραντίνοις πόλεως ἁλούσης, ἀλλὰ τὰ μὲν ἄλλα χρήματα καὶ τὸν πλοῦτον ἐξεφόρησε, τὰ δὲ ἀγάλματα μένειν εἴασεν, ἐπειπὼν τὸ μνημονευόμενον· ἀπολείπωμεν γὰρ ἔφη, τοὺς θεοὺς τούτους τοῖς Ταραντίνοις κεχολωμένους. Μάρκελλον δ’ ᾐτιῶντο πρῶτον μὲν ὡς ἐπίφθονον ποιοῦντα τὴν πόλιν, οὐ μόνον ἀνθρώπων, ἀλλὰ καὶ θεῶν οἷον αἰχμαλώτων ἀγομένων ἐν αὐτῇ καὶ πομπευομένων, ἔπειτα ὅτι τὸν δῆμον εἰθισμένον πολεμεῖν ἢ γεωργεῖν, τρυφῆς δὲ καὶ ῥᾳθυμίας ἄπειρον ὄντα καὶ κατὰ τὸν Εὐριπίδειον Ἡρακλέα,", "st": "Marc. 21.1"}, {"sp": "N", "t": "φαῦλον, ἄκομψον, τὰ μέγιστ’ ἀγαθόν,", "st": "Marc. 21.1b"}, {"sp": "N", "t": "σχολῆς ἐνέπλησε καὶ λαλιᾶς περὶ τεχνῶν καὶ τεχνιτῶν, ἀστεϊζόμενον καὶ διατρίβοντα πρὸς τούτῳ πολὺ μέρος τῆς ἡμέρας, οὐ μὴν ἀλλὰ τούτοις ἐσεμνύνετο καὶ πρὸς τοὺς Ἕλληνας, ὡς τὰ καλὰ καὶ θαυμαστὰ τῆς Ἑλλάδος οὐκ ἐπισταμένους τιμᾶν καὶ θαυμάζειν Ῥωμαίους διδάξας.", "st": "Marc. 21.1c"}, {"sp": "N", "t": "ἐνισταμένων δὲ τῶν ἐχθρῶν τῷ Μαρκέλλῳ πρὸς τὸν θρίαμβον, ἐπεὶ καὶ πράξεις τινὲς ὑπολιπεῖς ἦσαν ἔτι περὶ Σικελίαν καὶ φθόνον εἶχεν ὁ τρίτος θρίαμβος, συνεχώρησεν αὐτὸς τὸν μὲν ἐντελῆ καὶ μέγαν εἰς τὸ Ἀλβανὸν ὄρος ἐξελάσαι, τὸν δὲ ἐλάττω καταγαγεῖν εἰς τὴν πόλιν, ὃν εὔαν Ἕλληνες, ὄβαν δὲ Ῥωμαῖοι καλοῦσι. πέμπει δὲ αὐτὸν οὐκ ἐπὶ τὸν τεθρίππου βεβηκὼς οὐδὲ δάφνης ἔχων στέφανον οὐδὲ περισαλπιζόμενος, ἀλλὰ πεζὸς ἐν βλαύταις, ὑπ’ αὐλητῶν μάλα πολλῶν, καὶ μυρρίνης στέφανον ἐπικείμενος, ὡς ἀπόλεμος καὶ ἡδὺς ὀφθῆναι μᾶλλον ἢ καταπληκτικός, ὃ καὶ μέγιστον ἐμοὶ τεκμήριόν ἐστι τοῦ τρόπῳ πράξεως, ἀλλὰ μὴ μεγέθει, διωρίσθαι τοὺς θριάμβους τὸ παλαιόν. οἱ μὲν γὰρ μετὰ μάχης καὶ φόνου τῶν πολεμίων ἐπικρατήσαντες τὸν Ἀρήϊον ἐκεῖνον, ὡς ἔοικε, καὶ φοβερὸν εἰσῆγον, ὥσπερ ἐν τοῖς καθαρμοῖς τῶν στρατοπέδων εἰώθεσαν, δάφνῃ πολλῇ καταστέψαντες τὰ ὅπλα καὶ τοὺς ἄνδρας, τοῖς δὲ πολέμου μὲν μὴ δεηθεῖσι στρατηγοῖς, ὁμιλίᾳ δὲ καὶ πειθοῖ καὶ διὰ λόγου πάντα θεμένοις καλῶς, οἷον ἐπιπαιανίσαι τὴν ἀπόλεμον ταύτην καὶ πανηγυρικὴν ἀπεδίδου πομπὴν ὁ νόμος. καὶ γὰρ ὁ αὐλὸς εἰρήνης μέρος καὶ τὸ μύρτον Ἀφροδίτης φυτόν, ἣ μάλιστα θεῶν ἀπέχθεται βίᾳ καὶ πολέμοις. ὄβας δ’ οὐ παρὰ τὸν εὐασμόν, ὡς οἱ πολλοὶ νομίζουσιν, ὁ θρίαμβος οὗτος ὀνομάζεται καὶ γὰρ ἐκεῖνον ἐφευάζοντες καὶ ᾄδοντες παραπέμπουσιν, ἀλλ’ ὑφ’ Ἑλλήνων εἰς τὸ σύνηθες αὐτοῖς παρῆκται τοὔνομα, πεπεισμένων ἅμα καὶ Διονύσῳ τι τῆς τιμῆς προσήκειν, ὃν Εὔϊον καὶ Θρίαμβον ὀνομάζομεν. οὐχ οὕτω δὲ ἔχει τὸ ἀληθές, ἀλλ’ ἐπὶ μὲν τῷ μεγάλῳ θριάμβῳ βουθυτεῖν πάτριον ἦν τοῖς στρατηγοῖς, ἐπὶ δὲ τούτῳ πρόβατον ἔθυον. ὄβα δὲ τὰ πρόβατα Ῥωμαῖοι καλοῦσιν ἐκ τούτου καὶ τὸν θρίαμβον ὄβαν ὠνόμασαν. ἄξιον δὲ καὶ τὸν Λακωνικὸν ἀποθεωρῆσαι νομοθέτην ὑπεναντίως τῷ Ῥωμαϊκῷ τάξαντα τὰς θυσίας, θύει γὰρ ἐν Σπάρτῃ τῶν ἀποστρατήγων ὁ μὲν δι’ ἀπάτης ἢ πειθοῦς ὃ βούλεται διαπραξάμενος βοῦν, ὁ δὲ διὰ μάχης ἀλεκτρυόνα. καίπερ γὰρ ὄντες πολεμικώτατοι μείζονα καὶ μᾶλλον ἀνθρώπῳ πρέπουσαν ἡγοῦντο τὴν διὰ λόγου καὶ συνέσεως πρᾶξιν ἢ τὴν μετὰ βίας καὶ ἀνδρείας, ταῦτα μὲν οὖν ὅπως ἔχει σκοπεῖν πάρεστι.", "st": "Marc. 22.1"}, {"sp": "N", "t": "τοῦ δὲ Μαρκέλλου τὸ τέταρτον ὑπατεύοντος οἱ ἐχθροὶ τοὺς Συρακουσίους ἀνέπεισαν εἰς Ῥώμην ἀφικομένους κατηγορεῖν καὶ καταβοᾶν πρὸς τὴν σύγκλητον ὡς δεινὰ καὶ παράσπονδα πεπονθότας. ἔτυχε μὲν οὖν ἐν Καπιτωλίῳ θυσίαν τινὰ συντελῶν ὁ Μάρκελλος· ἔτι δὲ συγκαθεζομένῃ τῇ γερουσίᾳ τῶν Συρακουσίων προσπεσόντων καὶ δεομένων λόγου τυχεῖν καὶ δίκης, ὁ μὲν συνάρχων ἐξεῖργεν αὑτούς, ἀγανακτῶν ὑπὲρ τοῦ Μαρκέλλου μὴ παρόντος, ὁ δὲ Μάρκελλος εὐθὺς ἧκεν ἀκούσας, καὶ πρῶτον μὲν ἐπὶ τοῦ δίφρου καθίσας ὡς ὕπατος ἐχρημάτιζεν, ἔπειτα, τῶν ἄλλων τέλος ἐχόντων, καταβὰς ἀπὸ τοῦ δίφρου καὶ καταστὰς ὥσπερ ἰδιώτης εἰς τὸν τόπον ἐν ᾧ λέγειν εἰώθασιν οἱ κρινόμενοι, τοῖς Συρακουσίοις ἐλέγχειν αὑτὸν παρεῖχεν. οἱ δὲ δεινῶς μὲν συνεταράχθησαν πρὸς τὸ ἀξίωμα καὶ τὸ πεποιθὸς τοῦ ἀνδρός, καὶ τὸ ἐν τοῖς ὅπλοις ἀνυπόστατον ἔτι μᾶλλον ἐν τῇ περιπορφύρῳ φοβερὸν ἡγοῦντο καὶ δυσαντίβλεπτον. οὐ μὴν ἀλλὰ καὶ παραθαρρυνόντων αὐτοὺς τῶν διαφερομένων πρὸς τὸν Μάρκελλον ἤρξαντο τῆς κατηγορίας καὶ διεξῆλθον ὀλοφυρμῷ τινι μεμιγμένην δικαιολογίαν, ἧς ἦν τὸ κεφάλαιον ὅτι σύμμαχοι καὶ φίλοι Ῥωμαίοις ὄντες πεπόνθασιν ἃ πολλοῖς τῶν πολεμίων ἕτεροι στρατηγοὶ μὴ παθεῖν ἐχαρίσαντο. πρὸς ταῦτα ὁ Μάρκελλος ἔλεγεν ὡς ἀντὶ πολλῶν ὧν δεδράκασι Ῥωμαίους κακῶς οὐδὲν πεπόνθασι, πλὴν ἃ πολέμῳ καὶ κατὰ κράτος ἁλόντας ἀνθρώπους κωλῦσαι παθεῖν οὐ δυνατόν ἐστιν, οὕτω δὲ ἁλῶναι δι’ αὑτούς, πολλὰ προκαλουμένῳ πεισθῆναι μὴ ἐθελήσαντας. οὐ γὰρ ὑπὸ τῶν τυράννων πολεμῆσαι βιασθέντας, ἀλλὰ κἀκείνους ἐπὶ τῷ πολεμεῖν ἑλέσθαι τυράννους.", "st": "Marc. 23.1"}, {"sp": "N", "t": "λεχθέντων δὲ τῶν λόγων καὶ μεθισταμένοις, ὥσπερ εἴωθεν, ἐκ τῆς βουλῆς τοῖς Συρακουσίοις συνεξῆλθε Μάρκελλος, ἐπὶ τῷ συνάρχοντι ποιησάμενος τὴν σύγκλητον, καὶ πρὸ τῶν θυρῶν τοῦ βουλευτηρίου διέτριβεν, οὔτε φόβῳ διὰ τὴν δίκην οὔτε θυμῷ πρὸς τοὺς Συρακουσίους τοῦ συνήθους μεταβαλὼν καταστήματος, ἀλλὰ πρᾴως πάνυ καὶ κοσμίως τὸ τῆς δίκης τέλος ἐκδεχόμενος. ἐπεὶ δὲ διηνέχθησαν αἱ γνῶμαι καὶ νικῶν ἀπεδείχθη, προσπίπτουσιν αὐτῷ οἱ Συρακούσιοι, μετὰ δακρύων δεόμενοι τὴν ὀργὴν εἰς αὐτοὺς ἀφεῖναι τοὺς παρόντας, οἰκτεῖραι δὲ τὴν ἄλλην πόλιν μεμνημένην ὧν ἔτυχεν ἀεὶ καὶ χάριν ἔχουσαν. ἐπικλασθεὶς οὖν ὁ Μάρκελλος τούτοις τε διηλλάγη, καὶ τοῖς ἄλλοις Συρακουσίοις ἀεί τι πράττων ἀγαθὸν διετέλει. καὶ τὴν ἐλευθερίαν ἣν ἀπέδωκεν αὐτοῖς, καὶ τοὺς νόμους καὶ τῶν κτημάτων τὰ περιόντα βέβαια παρέσχεν ἡ σύγκλητος, ἀνθ’ ὧν ἄλλας τε τιμὰς ὑπερφυεῖς ἔσχε παρ’ αὐτοῖς, καὶ νόμον ἔθεντο τοιοῦτον, ὁπόταν ἐπιβῇ Σικελίας Μάρκελλος ἢ τῶν ἐκγόνων τις αὐτοῦ, στεφανηφορεῖν Συρακουσίους καὶ θύειν τοῖς θεοῖς.", "st": "Marc. 23.6"}, {"sp": "N", "t": "τοὐντεῦθεν ἤδη τρέπεται πρὸς Ἀννίβαν. καὶ τῶν ἄλλων ὑπάτων καὶ ἡγεμόνων σχεδὸν ἁπάντων μετὰ τὰ ἐν Κάνναις ἑνὶ στρατηγήματι τῷ φυγομαχεῖν χρωμένων ἐπὶ τὸν ἄνδρα, παρατάττεσθαι δὲ καὶ συμπλέκεσθαι μηδενὸς τολμῶντος, αὐτὸς ἐπὶ τὴν ἐναντίαν ὥρμησεν ὁδόν, οἰόμενος τῷ δοκοῦντι καταλύειν Ἀννίβαν χρόνῳ πρότερον ἐκτριβεῖσαν ὑπ’ ἐκείνου λήσεσθαι τὴν Ἰταλίαν, καὶ τὸν Φάβιον ἀεὶ τῆς ἀσφαλείας ἐχόμενον οὐ καλῶς ἔχειν ἰᾶσθαι τὸ νόσημα τῆς πατρίδος, περιμένοντα τῇ ῥώμῃ μαραινομένῃ συναποσβῆναι τὸν πόλεμον, ὥσπερ ἰατρῶν τοὺς ἀτόλμους καὶ δειλοὺς πρὸς τὰ βοηθήματα, τῆς νόσου παρακμὴν τὴν τῆς δυνάμεως ἐξανάλωσιν ἡγουμένους. πρῶτον μὲν οὖν τὰς Σαυνιτικὰς πόλεις μεγάλας ἀφεστώσας ἑλών, σῖτόν τε πολὺν ἀποκείμενον ἐν αὐταῖς καὶ χρήματα καὶ τοὺς φυλάσσοντας Ἀννίβου στρατιώτας τρισχιλίους ὄντας ἔλαβεν ἔπειτα τοῦ Ἀννίβου Φούλβιον Γναῖον ἀνθύπατον ἐν Ἀπουλίᾳ, κατακτείναντος μὲν αὐτὸν σὺν ἕνδεκα χιλιάρχοις, κατακόψαντος δὲ τῆς στρατιᾶς τὸ πλεῖστον, ἔπεμψεν εἰς Ῥώμην γράμματα τοὺς πολίτας παρακαλῶν θαρρεῖν αὐτὸς γὰρ ἤδη βαδίζειν ὡς ἀφέλοιτο τὴν χαρὰν Ἀννίβου. καὶ ταῦτα μὲν ὁ Λίβιός φησιν ἀναγνωσθέντα τὰ γράμματα μὴ τῆς λύπης ἀφελεῖν, ἀλλὰ τῷ φόβῳ προσθεῖναι, τῶν Ῥωμαίων μεῖζον ἡγουμένων τοῦ γεγονότος τὸ κινδυνευόμενον ὅσῳ Φουλβίου κρείττων ἦν Μάρκελλος ὁ δέ, ὥσπερ ἔγραψεν, εὐθὺς Ἀννίβαν διώκων εἰς τὴν Λευκανίαν ἐνέβαλε, καὶ περὶ πόλιν Νομίστρωνα καθήμενον ὑπὲρ λόφων ὀχυρῶν καταλαβών αὐτὸς ἐν τῷ πεδίῳ κατεστρατοπέδευσε. τῇ δ’ ὑστεραίᾳ πρότερος εἰς μάχην παρατάξας τὸ στράτευμα καταβάντος Ἀννίβου, συνέβαλε μάχην κρίσιν οὐ λαβοῦσαν, ἰσχυρὰν δὲ καὶ μεγάλην γενομένην ἀπὸ γὰρ ὥρας τρίτης συμπεσόντες ἤδη σκότους μόλις διελύθησαν. ἅμα δ’ ἡμέρᾳ προαγαγὼν αὖθις τὸ στράτευμα παρέταξε διὰ τῶν νεκρῶν καὶ προὐκαλεῖτο διαγωνίσασθαι περὶ τῆς νίκης τὸν Ἀννίβαν. ἀναζεύξαντος δὲ ἐκείνου σκυλεύσας τοὺς πολεμίους νεκροὺς καὶ θάψας τοὺς φίλους ἐδίωκεν αὖθις· καὶ πολλὰς μὲν ὑφέντος ἐνέδρας οὐδεμιᾷ περιπεσών, ἐν δὲ πᾶσι τοῖς ἀκροβολισμοῖς πλεῖον ἔχων ἐθαυμάζετο. διὸ καὶ τῶν ἀρχαιρεσίων ἐπειγόντων ἔδοξε τῇ βουλῇ μᾶλλον ἐκ Σικελίας τὸν ἕτερον ἀπάγειν ὕπατον ἢ Μάρκελλον Ἀννίβᾳ συνηρτημένον κινεῖν, ἐλθόντα δ’ ἐκέλευεν εἰπεῖν δικτάτορα Κόϊντον Φούλβιον.", "st": "Marc. 24.1"}, {"sp": "N", "t": "ὁ γὰρ δικτάτωρ οὐκ ἔστιν ὑπὸ τοῦ πλήθους οὐδὲ τῆς βουλῆς αἱρετός, ἀλλὰ τῶν ὑπάτων τις ἢ τῶν στρατηγῶν προελθὼν εἰς τὸν δῆμον ὃν αὐτῷ δοκεῖ λέγει δικτάτορα, καὶ διὰ τοῦτο δικτάτωρ ὁ ῥηθεὶς καλεῖται· τὸ γὰρ λέγειν δίκερε Ῥωμαῖοι καλοῦσιν ἔνιοι δὲ τὸν δικτάτορα τῷ μὴ προτιθέναι ψῆφον ἢ χειροτονίαν, ἀλλ’ ἀφ’ αὑτοῦ τὰ δόξαντα προστάττειν καὶ λέγειν οὕτως ὠνομάσθαι καὶ γὰρ τὰ διαγράμματα τῶν ἀρχόντων Ἕλληνες μὲν διατάγματα, Ῥωμαῖοι δὲ ἔδικτα προσαγορεύουσιν.", "st": "Marc. 24.7"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐλθὼν ἀπὸ τῆς Σικελίας ὁ τοῦ Μαρκέλλου συνάρχων ἕτερον ἐβούλετο λαβεῖν δικτάτορα, καὶ βιασθῆναι παρὰ γνώμην μὴ βουλόμενος ἐξέπλευσε νυκτὸς εἰς Σικελίαν, οὕτως ὁ μὲν δῆμος ὠνόμασε δικτάτορα Κόϊντον Φούλβιον, ἡ βουλὴ δ’ ἔγραψε Μαρκέλλῳ κελεύουσα τοῦτον εἰπεῖν. ὁ δὲ πεισθεὶς ἀνεῖπε καὶ συνεπεκύρωσε τοῦ δήμου τὴν γνώμην, αὐτὸς δὲ πάλιν ἀνθύπατος εἰς τοὐπιὸν ἀπεδείχθη. συνθέμενος δὲ πρὸς Φάβιον Μάξιμον ὅπως ἐκεῖνος μὲν ἐπιχειρῇ Ταραντίνοις, αὐτὸς δὲ συμπλεκόμενος καὶ περιέλκων Ἀννίβαν ἐμποδὼν ᾖ τοῦ βοηθεῖν πρὸς ἐκεῖνον, ἐπέβαλε περὶ Κανύσιον, καὶ πολλὰς ἀλλάσσοντι στρατοπεδείας καὶ φυγομαχοῦντι πανταχόθεν ἐπεφαίνετο, τέλος δ’ ἱδρυνθέντα προσκείμενος ἐξανίστη τοῖς ἀκροβολισμοῖς. ὁρμήσαντος δὲ μάχεσθαι δεξάμενος ὑπὸ νυκτὸς διελύθη· καὶ μεθ’ ἡμέραν αὖθις ἐν τοῖς ὅπλοις ἑωρᾶτο τὸν στρατὸν ἔχων παρατεταγμένον, ὥστε τὸν Ἀννίβαν περιαλγῆ γενόμενον τοὺς Καρχηδονίους ἀθροῖσαι καὶ δεηθῆναι τὴν μάχην ἐκείνην ὑπὲρ πασῶν ἀγωνίσασθαι τῶν ἔμπροσθεν. ὁρᾶτε γὰρ, εἶπεν, ὡς οὐδὲ ἀναπνεῦσαι μετὰ νίκας τοσαύτας οὐδὲ σχολὴν ἄγειν κρατοῦσιν ἡμῖν ἔστιν, εἰ μὴ τοῦτον ὠσαίμεθα τὸν ἄνθρωπον.", "st": "Marc. 25.1"}, {"sp": "N", "t": "ἐκ τούτου συμβαλόντες ἐμάχοντο. καὶ δοκεῖ παρὰ τὸ ἔργον ἀκαίρῳ στρατηγήματι χρώμενος ὁ Μάρκελλος σφαλῆναι. τοῦ γὰρ δεξιοῦ πονοῦντος ἐκέλευσεν ἓν τῶν ταγμάτων εἰς τοὔμπροσθεν προελθεῖν ἡ δὲ μετακίνησις αὕτη ταράξασα τοὺς μαχομένους παρέδωκε τὸ νίκημα τοῖς πολεμίοις, ἑπτακοσίων ἐπὶ δισχιλίοις Ῥωμαίων πεσόντων. ἀναχωρήσας δὲ ὁ Μάρκελλος εἰς τὸν χάρακα καὶ συναγαγὼν τὸν στρατόν, ὁρᾶν ἔφη Ῥωμαίων ὅπλα πολλὰ καὶ σώματα, Ῥωμαῖον δὲ μηδένα ὁρᾶν. αἰτουμένων δὲ συγγνώμην οὐκ ἔφη διδόναι νενικημένοις, ἐὰν δὲ νικήσωσι, δώσειν αὔριον δὲ μαχεῖσθαι πάλιν, ὅπως οἱ πολῖται τὴν νίκην πρότερον ἢ τὴν φυγὴν ἀκούσωσι. διαλεχθεὶς δὲ ταῦτα, προσέταξε ταῖς ἡττημέναις σπείραις ἀντὶ πυρῶν κριθὰς μετρῆσαι. δι’ ἃ πολλῶν ἀπὸ τῆς μάχης ἐπικινδύνως καὶ πονήρως ἐχόντων οὐδένα φασὶν ὃν οἱ Μαρκέλλου λόγοι τῶν τραυμάτων οὐχὶ μᾶλλον ἤλγυναν.", "st": "Marc. 25.4"}, {"sp": "N", "t": "ἅμα δὲ ἡμέρᾳ προὔκειτο μὲν ὁ φοινικοῦς χιτὼν, ὡς εἴωθε, μάχης ἐσομένης σύμβολον, αἱ δὲ ἠτιμασμέναι σπεῖραι τὴν πρώτην αὐταὶ δεηθεῖσαι τάξιν ἐλάμβανον, τὴν δὲ ἄλλην ἐξάγοντες οἱ χιλίαρχοι στρατιὰν παρενέβαλλον, ἀκούσας δὲ ὁ Ἀννίβας, ὦ Ἡράκλεις, εἶπε, τί χρήσεταί τις ἀνθρώπῳ μήτε τὴν χείρονα τύχην μήτε τὴν βελτίονα φέρειν εἰδότι; μόνος γὰρ οὗτος οὔτε νικῶν δίδωσιν ἀνάπαυσιν οὔτε λαμβάνει νικώμενος, ἀλλ’ ἀεὶ μαχησόμεθα πρὸς τοῦτον, ὡς ἔοικεν, ᾧ τοῦ τολμᾶν ἀεὶ καὶ τὸ θαρρεῖν εὐτυχοῦντι καὶ σφαλλομένῳ τὸ αἰδεῖσθαι πρόφασίς ἐστιν. ἐκ τούτου συνῄεσαν αἱ δυνάμεις· καὶ τῶν ἀνδρῶν ἴσα φερομένων ἐκέλευσεν Ἀννίβας τὰ θηρία καταστήσαντας εἷς πρώτην τάξιν ἐπάγειν τοῖς ὅπλοις τῶν Ῥωμαίων, ὠθισμοῦ δὲ μεγάλου καὶ ταραχῆς εὐθὺς ἐν τοῖς πρώτοις γενομένης, εἷς τῶν χιλιάρχων ὄνομα Φλάβιος ἀναρπάσας σημαίαν ὑπηντίαζε καὶ τῷ στύρακι τὸν πρῶτον ἐλέφαντα τύπτων ἀπέστρεφεν. ὁ δὲ ἐμβαλὼν εἷς τὸν ὀπίσω συνετάραξε καὶ τοῦτον καὶ τοὺς ἐπιφερομένους, κατιδὼν δὲ τοῦτο Μάρκελλος ἐκέλευσε τοὺς ἱππεῖς ἐλαύνειν ἀνὰ κράτος πρὸς τὸ θορυβούμενον καὶ ποιεῖν ἔτι μᾶλλον αὑτοῖς περιπετεῖς τοὺς πολεμίους, οὗτοί τε δὴ λαμπρῶς ἐμβαλόντες ἀνέκοπτον ἄχρι τοῦ στρατοπέδου τοὺς Καρχηδονίους, καὶ τῶν θηρίων τὰ κτεινόμενα καὶ πίπτοντα τὸν πλεῖστον αὐτῶν φόνον ἀπειργάζετο. λέγονται γὰρ ὑπὲρ ὀκτακισχιλίους ἀποθανεῖν Ῥωμαίων δὲ νεκροὶ μὲν ἐγένοντο τρισχίλιοι, τραυματίαι δὲ ὀλίγου δεῖν ἅπαντες. καὶ τοῦτο παρέσχεν Ἀννίβᾳ καθ’ ἡσυχίαν ἀναστάντι νυκτὸς ἆραι πορρωτάτω τοῦ Μαρκέλλου. διώκειν γὰρ οὐκ ἦν δυνατὸς ὑπὸ πλήθους τῶν τετρωμένων, ἀλλὰ κατὰ σχολὴν εἷς Καμπανίαν ἀνέζευξε, καὶ τὸ θέρος ἐν Σινοέσσῃ διῆγεν ἀναλαμβάνων τοὺς στρατιώτας.", "st": "Marc. 26.1"}, {"sp": "N", "t": "ὁ δὲ Ἀννίβας ὡς ἀπέρρηξεν ἑαυτὸν τοῦ Μαρκέλλου, χρώμενος ὥσπερ λελυμένῳ τῷ στρατεύματι, πᾶσαν ἀδεῶς ἐν κύκλῳ περιϊὼν ἔφλεγε τὴν Ἰταλίαν καὶ κακῶς ἤκουσεν ἐν Ῥώμῃ Μάρκελλος, οἱ δὲ ἐχθροὶ Πουβλίκιον Βίβλον, ἕνα τῶν δημάρχων, ἀνέστησαν ἐπὶ τὴν κατηγορίαν αὐτοῦ, δεινὸν εἰπεῖν ἄνδρα καὶ βίαιον· ὃς πολλάκις συναγαγὼν τὸν δῆμον ἔπειθεν ἄλλῳ παραδοῦναι στρατηγῷ τὴν δύναμιν, ἐπεὶ Μάρκελλος, ἔφη, μικρὰ τῷ πολέμῳ προσγεγυμνασμένος ὥσπερ ἐκ παλαίστρας ἐπὶ θερμὰ λουτρὰ θεραπεύσων ἑαυτὸν τέτραπται. ταῦτα πυνθανόμενος ὁ Μάρκελλος ἐπὶ μὲν τοῦ στρατοπέδου τοὺς πρεσβευτὰς ἀπέλιπεν, αὐτὸς δὲ πρὸς τὰς διαβολὰς ἐπλογησόμενος εἰς Ῥώμην ἐπανῆλθεν. ἐκ δὲ τῶν διαβολῶν ἐκείνων δίκην εὗρε παρεσκευασμένην ἐφ’ αὑτόν, ἡμέρας οὖν ὁρισθείσης καὶ τοῦ δήμου συνελθόντος εἰς τὸν Φλαμίνιον ἱππόδρομον, ὁ μὲν Βίβλος ἀναβὰς κατηγόρησεν, ὁ δὲ· Μάρκελλος ἀπελογεῖτο, βραχέα μὲν καὶ ἁπλᾶ δι’ ἑαυτοῦ, πολλὴν δὲ καὶ λαμπρὰν οἱ δοκιμώτατοι καὶ πρῶτοι τῶν πολιτῶν παρρησίαν ἦγον, παρακαλοῦντες μὴ χείρονας τοῦ πολεμίου κριτὰς φανῆναι δειλίαν Μαρκέλλου καταψηφισαμένους, ὃν μόνον φεύγει τῶν ἡγεμόνων ἐκεῖνος καὶ διατελεῖ τούτῳ μὴ μάχεσθαι στρατηγῶν, ὡς τοῖς ἄλλοις μάχεσθαι. ῥηθέντων δὲ τῶν λόγων τούτων τοσοῦτον ἡ τῆς δίκης ἐλπὶς ἐψεύσατο τὸν κατήγορον ὥστε μὴ μόνον ἀφεθῆναι τῶν αἰτιῶν τὸν Μάρκελλον, ἀλλὰ καὶ τὸ πέμπτον ὕπατον ἀποδειχθῆναι.", "st": "Marc. 27.1"}, {"sp": "N", "t": "παραλαβὼν δὲ τὴν ἀρχήν πρῶτον μὲν ἐν Τυρρηνίᾳ μέγα κίνημα πρὸς ἀπόστασιν ἔπαυσε καὶ κατεπράϋνεν ἐπελθὼν τὰς πόλεις· ἔπειτα ναὸν ἐκ τῶν Σικελικῶν λαφύρων ᾠκοδομημένον ὑπ’ αὐτοῦ Δόξης καὶ Ἀρετῆς καθιερῶσαι βουλόμενος, καὶ κωλυθεὶς ὑπὸ τῶν ἱερέων οὐκ ἀξιούντων ἑνὶ ναῷ δύο θεοὺς περιέχεσθαι, πάλιν ἤρξατο προσοικοδομεῖν ἕτερον, οὐ ῥᾳδίως φέρων τὴν γεγενημένην ἀντίκρουσιν, ἀλλ’ ὥσπερ οἰωνιζόμενος. καὶ γὰρ ἄλλα πολλὰ σημεῖα διετάραττεν αὐτόν, ἱερῶν τινων κεραυνώσεις καὶ μύες τὸν ἐν Διὸς χρυσὸν διαφαγόντες ἐλέχθη δὲ καὶ βοῦν ἀνθρώπου φωνὴν ἀφεῖναι καὶ παιδίον ἔχον κεφαλὴν ἐλέφαντος γενέσθαι· καὶ περὶ τὰς ἐκθύσεις καὶ ἀποτροπὰς δυσιεροῦντες οἱ μάντεις κατεῖχον αὐτὸν ἐν Ῥώμῃ σπαργῶντα καὶ φλεγόμενον. οὐδεὶς γὰρ ἔρωτα τοσοῦτον ἠράσθη πράγματος οὐδενός ὅσον οὗτος ὁ ἀνὴρ τοῦ μάχῃ κριθῆναι πρὸς Ἀννίβαν. τοῦτο καὶ νύκτωρ ὄνειρον ἦν αὐτῷ καὶ μετὰ φίλων καὶ συναρχόντων ἓν βούλευμα καὶ μία πρὸς θεοὺς φωνή, παραταττόμενον Ἀννίβαν λαβεῖν, ἥδιστα δ’ ἄν μοι δοκεῖ τείχους ἑνὸς ἤ τινος χάρακος ἀμφοτέροις τοῖς στρατεύμασι περιτεθέντος διαγωνίσασθαι, καὶ εἰ μὴ πολλῆς μὲν ἤδη μεστὸς ὑπῆρχε δόξης, πολλὴν δὲ πεῖραν παρεσχήκει τοῦ παρ’ ὁντινοῦν τῶν στρατηγῶν ἐμβριθὴς γεγονέναι καὶ φρόνιμος, εἶπον ἂν ὅτι μειρακιῶδες αὐτῷ προσπεπτώκει καὶ φιλοτιμότερον πάθος ἢ κατὰ πρεσβύτην τοσοῦτον· ὑπὲρ γὰρ ἑξήκοντα γεγονὼς ἔτη τὸ πέμπτον ὑπάτευεν.", "st": "Marc. 28.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ θυσιῶν καὶ καθαρμῶν ὧν ὑπηγόρευον οἱ μάντεις γενομένων ἐξῆλθε μετὰ τοῦ συνάρχοντος ἐπὶ τόν πόλεμον, καὶ πολλὰ μεταξὺ Βαντίας πόλεως καὶ Βενυσίας καθήμενον ἠρέθιζε τόν Ἀννίβαν. ὁ δὲ εἰς μάχην μὲν οὐ κατέβαινεν, αἰσθόμενος δὲ πεμπομένην ὑπ’ αὐτῶν στρατιὰν ἐπὶ Λοκροὺς τοὺς Ἐπιζεφυρίους, κατὰ τόν περὶ Πετηλίαν λόφον ὑφεὶς ἐνέδρας πεντακοσίους καὶ δισχιλίους ἀπέκτεινε. τοῦτο Μάρκελλον ἐξέφερε τῷ θυμῷ πρὸς τὴν μάχην, καὶ προσῆγεν ἄρας ἐγγυτέρω τὴν δύναμιν.", "st": "Marc. 29.1"}, {"sp": "N", "t": "ἦν δὲ μεταξὺ τῶν στρατοπέδων λόφος ἐπιεικῶς μὲν εὐερκής, ὕλης δὲ παντοδαπῆς ἀνάπλεως· εἶχε δὲ καὶ σκοπὰς περικλινεῖς ἐπ’ ἀμφότερα, καὶ ναμάτων ὑπεφαίνοντο πηγαὶ καταρρεόντων, ἐθαύμαζον οὖν οἱ Ῥωμαῖοι Ἀννίβαν ὅτι πρῶτος ἐλὼν εὐφυᾶ τόπον οὕτως οὐ κατέσχεν, ἀλλ’ ἀπέλιπε τοῖς πολεμίοις. τῷ δὲ ἄρα καλὸν μὲν ἐνστρατοπεδεῦσαι τὸ χωρίον ἐφαίνετο, πολὺ δὲ κρεῖττον ἐνεδρεῦσαι· καὶ πρὸς τοῦτο μᾶλλον αὐτῷ χρῆσθαι βουλόμενος ἐνέπλησε τὴν ὕλην καὶ τὰς κοιλάδας ἀκοντιστῶν τε πολλῶν καὶ λογχοφόρων, πεπεισμένος ἐπάξεσθαι δι’ εὐφυΐαν αὐτὰ τὰ χωρία τοὺς Ῥωμαίους. οὐδὲ ἀπεψεύσθη τῆς ἐλπίδος· εὐθὺς γὰρ ἦν πολὺς ἐν τῷ στρατοπέδῳ τῶν Ῥωμαίων λόγος ὡς χρὴ τὸ χωρίον καταλαμβάνειν, καὶ διεστρατήγουν ὅσα πλεονεκτήσουσι τοὺς πολεμίους, μάλιστα μὲν ἐκεῖ στρατοπεδεύσαντες, εἰ δὲ μή, τειχίσαντες τόν λόφον. ἔδοξεν οὖν τῷ Μαρκέλλῳ μετ’ ὀλίγων ἱπποτῶν ἐπελάσαντι κατασκέψασθαι. καὶ λαβὼν τόν μάντιν ἐθύετο· καὶ τοῦ πρώτου πεσόντος ἱερείου δείκνυσιν αὐτῷ τὸ ἧπαρ οὐκ ἔχον κεφαλὴν ὁ μάντις. ἐπιθυσαμένου δὲ τὸ δεύτερον ἥ τε κεφαλὴ μέγεθος ὑπερφυὲς ἀνέσχε καὶ τἆλλα φαιδρὰ θαυμαστῶς διεφάνη, καὶ λύσιν ἔχειν ὁ τῶν πρώτων φόβος ἔδοξεν. οἱ δὲ μάντεις ταῦτα μᾶλλον ἔφασαν δεδιέναι καὶ ταράττεσθαι· λαμπροτάτων γὰρ ἐπ’ αἰσχίστοις καὶ σκυθρωποτάτοις ἱεροῖς γενομένων ὕποπτον εἶναι τῆς μεταβολῆς τὴν ἀτοπίαν. ἀλλὰ γὰρ", "st": "Marc. 29.3"}, {"sp": "N", "t": "τὸ πεπρωμένον οὐ πῦρ, οὐ σιδαροῦν σχήσει τεῖχος,", "st": "Marc. 29.3b"}, {"sp": "N", "t": "κατὰ Πίνδαρον, ἐξῄει τόν τε συνάρχοντα Κριοπῖνον παραλαβὼν καὶ τόν υἱὸν χιλιαρχοῦντα καὶ τοὺς σύμπαντας ἱππεῖς εἴκοσι καὶ διακοσίους. ὧν Ῥωμαῖος οὐδεὶς ἦν, ἀλλ’ οἱ μὲν ἄλλοι Τυρρηνοί, τεσσαράκοντα δὲ Φρεγελλανοί, πεῖραν ἀρετῆς καὶ πίστεως ἀεὶ τῷ Μαρκέλλῳ δεδωκότες. ὑλώδους δὲ τοῦ λόφου καὶ συνηρεφοῦς ὄντος ἀνὴρ καθήμενος ἄνω σκοπὴν εἶχε τοῖς πολεμίοις, αὐτὸς οὐ συνορώμενος, καθορῶν δὲ τῶν Ῥωμαίων τὸ στρατόπεδον. καὶ τὰ γινόμενα τούτου φράσαντος τοῖς λοχῶσι, προσελαύνοντα τόν Μάρκελλον ἐάσαντες ἐγγὺς προσελθεῖν ἐξαίφνης ἀνέστησαν, καὶ περιχυθέντες ἅμα πανταχόθεν ἠκόντιζον, ἔπαιον, ἐδίωκον τοὺς φεύγοντας, συνεπλέκοντο τοῖς ὑφισταμένοις· οὗτοι δ’ ἦσαν οἱ τεσσαράκοντα Φρεγελλανοί. καὶ τῶν Τυρρηνῶν εὐθὺς ἐν ἀρχῇ διατρεσάντων αὐτοὶ συστραφέντες ἠμύνοντο πρὸ τῶν ὑπάτων, ἄχρι οὗ Κρισπῖνος μὲν ἀκοντίσμασι δυσὶ βεβλημένος ἐπέστρεψεν εἰς φυγὴν τόν ἵππον, Μάρκελλον δέ τις λόγχῃ πλατείᾳ διὰ τῶν πλευρῶν διήλασεν, ἣν λαγκίαν καλοῦσιν. οὕτω δὲ καὶ τῶν Φρεγελλανῶν οἱ περιόντες ὀλίγοι παντάπασιν αὐτὸν μὲν πεσόντα λείπουσι, τόν δ’ υἱὸν ἁρπάσαντες τετρωμένον φεύγουσιν ἐπὶ τὸ στρατόπεδον. ἐγένοντο δὲ νεκροὶ μὲν οὐ πολλῷ τῶν τεσσαράκοντα πλείους, αἰχμάλωτοι δὲ τῶν μὲν ῥαβδούχων πέντε, τῶν δὲ ἱππέων εἴκοσι δυεῖν δέοντες, ἐτελεύτησε δὲ καὶ Κρισπῖνος ἐκ τῶν τραυμάτων οὐ πολλὰς ἡμέρας ἐπιβιώσας. καὶ πάθος τοῦτο Ῥωμαίοις συνέπεσε πρότερον οὐ γεγονός, ἀμφοτέρους ἐξ ἑνὸς ἀγῶνος τοὺς ὑπάτους ἀποθανεῖν.", "st": "Marc. 29.6"}, {"sp": "N", "t": "Ἀννίβᾳ δὲ τῶν μὲν ἄλλων ἐλάχιστος ἦν λόγος, Μάρκελλον δὲ πεπτωκέναι πυθόμενος αὐτὸς ἐξέδραμεν ἐπὶ τὸν τόπον, καὶ τῷ νεκρῷ παραστάς καὶ πολὺν χρόνον τήν τε ῥώμην τοῦ σώματος καταμαθὼν καὶ τὸ εἶδος, οὔτε φωνὴν ἀφῆκεν ὑπερήφανον, οὔτε ἀπ’ ὄψεως τὸ χαῖρον, ὡς ἄν τις ἐργώδη πολέμιον καὶ βαρὺν ἀπεκτονώς, ἐξέφηνεν, ἀλλ’ ἐπιθαυμάσας τὸ παράλογον τῆς τελευτῆς τὸν μὲν δακτύλιον ἀφείλετο, τὸ δὲ σῶμα κοσμήσας πρέποντι κόσμῳ καὶ περιστείλας ἐντίμως ἔκαυσε καὶ τὰ λείψανα συνθεὶς εἰς κάλπιν ἀργυρᾶν, καὶ χρυσοῦν ἐμβαλὼν στέφανον, ἀπέστειλε πρὸς τὸν υἱόν. τῶν δὲ Νομάδων τινὲς περιτυχόντες τοῖς κομίζουσιν ὥρμησαν ἀφαιρεῖσθαι τὸ τεῦχος, ἀντιλαμβανομένων δ’ ἐκείνων ἐκβιαζόμενοι καὶ μαχόμενοι διέρριψαν τὰ ὀστᾶ. πυθόμενος δὲ Ἀννίβας, καὶ πρὸς τοὺς παρόντας εἰπὼν, οὐδὲν ἄρα δυνατὸν γενέσθαι ἄκοντος θεοῦ τοῖς μὲν Νομάσιν ἐπέθηκε δίκην, οὐκέτι δὲ κομιδῆς ἢ συλλογῆς τῶν λειψάνων ἐφρόντισεν, ὡς δὴ κατὰ θεόν τινα καὶ τῆς τελευτῆς καὶ τῆς ἀταφίας παραλόγως οὕτω τῷ Μαρκέλλῳ γενομένης. ταῦτα μὲν οὖν οἱ περὶ Κορνήλιον Νέπωτα καὶ Οὐαλέριον Μάξιμον ἱστορήκασι· Λίβιος δὲ καὶ Καῖσαρ ὁ Σεβαστὸς κομισθῆναι τήν ὑδρίαν πρὸς τὸν υἱὸν εἰρήκασι καὶ ταφῆναι λαμπρῶς.", "st": "Marc. 30.1"}, {"sp": "N", "t": "ἦν δὲ ἀνάθημα Μαρκέλλου δίχα τῶν ἔν Ῥώμῃ γυμνάσιον μὲν ἐν Κατάνῃ τῆς Σικελίας, ἀνδριάντες δὲ καὶ πίνακες τῶν ἐκ Συρακουσῶν ἔν τε Σαμοθρᾴκῃ παρὰ τοῖς θεοῖς, οὓς Καβείρους ὠνόμαζον, καὶ περὶ Λίνδον ἐν τῷ ἱερῷ τῆς Ἀθηνᾶς. ἐκεῖ δὲ αὐτοῦ τῷ ἀνδριάντι τοῦτ’ ἦν ἐπιγεγραμμένον, ὡς Ποσειδώνιός φησι, τὸ ἐπίγραμμα·", "st": "Marc. 30.5"}, {"sp": "N", "t": "οὗτός τοι Ῥώμης ὁ μέγας, ξένε, πατρίδος ἀστήρ,<br>Μάρκελλος κλεινῶν Κλαύδιος ἐκ πατέρων.<br>ἑπτάκι τὰν ὑπάταν ἀρχὰν ἐν Ἄρηϊ φυλάξας,<br>τὸν πολὺν ἀντιπάλοις ὃς κατέχευε φόνον.", "st": "Marc. 30.5b"}, {"sp": "N", "t": "τήν γὰρ ἀνθύπατον ἀρχήν, ἣν δὶς ἦρξε, ταῖς πέντε προσκατηρίθμησεν ὑπατείαις ὁ τὸ ἐπίγραμμα ποιήσας. γένος δ’ αὐτοῦ λαμπρὸν ἄχρι Μαρκέλλου τοῦ Καίσαρος ἀδελφιδοῦ διέτεινεν, ὃς Ὀκταβίας ἦν τῆς Καίσαρος ἀδελφῆς υἱὸς ἐκ Γαΐου Μαρκέλλου γεγονώς, ἀγορανομῶν δὲ Ῥωμαίων ἐτελεύτησε νυμφίος, Καίσαρος θυγατρὶ χρόνον οὐ πολὺν συνοικήσας. εἰς δὲ τιμὴν αὐτοῦ καὶ μνήμην Ὀκταβία μὲν ἡ μήτηρ τήν βιβλιοθήκην ἀνέθηκε, Καῖσαρ δὲ θέατρον ἐπιγράψας Μαρκέλλου.", "st": "Marc. 30.6"}, {"sp": "HDR", "t": "Πελοπίδου καὶ Μαρκέλλου σύγκρισις"}, {"sp": "N", "t": "ὅσα μὲν οὖν ἔδοξεν ἡμῖν ἀναγραφῆς ἄξια τῶν ἱστορημένων περὶ Μαρκέλλου καὶ Πελοπίδου, ταὐτά ἔστι. τῶν δὲ κατὰ τὰς φύσεις καὶ τὰ ἤθη κοινοτήτων ὥσπερ ἐφαμίλλων οὐσῶν καὶ γὰρ ἀνδρεῖοι καὶ φιλόπονοι καὶ θυμοειδεῖς καὶ μεγαλόφρονες ἀμφότεροι γεγόνασιν, ἐκεῖνο δόξειεν ἂν διαφορὰν ἔχειν μόνον, ὅτι Μάρκελλος μὲν ἐν πολλαῖς πόλεσιν ὑποχειρίοις γενομέναις σφαγὰς ἐποίησεν, Ἐπαμεινώνδας δὲ καὶ Πελοπίδας οὐδένα πώποτε κρατήσαντες ἀπέκτειναν οὐδὲ πόλεις ἠνδραποδίσαντο. λέγονται δὲ Θηβαῖοι μηδὲ Ὀρχομενίους ἂν οὕτω μεταχειρίσασθαι παρόντων ἐκείνων·", "st": "Comp. Pel.–Marc. 1.1"}, {"sp": "N", "t": "ἐν δὲ ταῖς πράξεσι θαυμαστὰ μὲν καὶ μεγάλα τοῦ Μαρκέλλου τὰ πρὸς Κελτούς, ὠσαμένου τοσοῦτον πλῆθος ἱππέων ὁμοῦ καὶ πεζῶν ὀλίγοις τοῖς περὶ αὐτὸν ἱππεῦσιν, ὃ ῥᾳδίως ὑφ’ ἑτέρου στρατηγοῦ γεγονὸς οὐχ ἱστόρηται, καὶ τὸν ἄρχοντα τῶν πολεμίων ἀνελόντος· ἐν ᾧ τρόπῳ Πελοπίδας ἔπταισεν ὁρμήσας ἐπὶ ταὐτά, προαναιρεθεὶς δὲ ὑπὸ τοῦ τυράννου καὶ παθὼν πρότερον ἢ δράσας. οὐ μὴν ἀλλὰ τούτοις μὲν ἔστι παραβαλεῖν τὰ Λεῦκτρα καὶ Τεγύρας, ἐπιφανεστάτους καὶ μεγίστους ἀγώνων, κρυφαίαν δὲ σὺν λόχῳ κατωρθωμένην πρᾶξιν οὐκ ἔχομεν τοῦ Μαρκέλλου παραβαλεῖν οἷς Πελοπίδας περὶ τὴν ἐκ φυγῆς κάθοδον καὶ ἀναίρεσιν τῶν ἐν Θήβαις τυράννων ἔπραξεν, ἀλλ’ ἐκεῖνο πολὺ πάντων ἔοικε πρωτεύειν τῶν ὑπὸ σκότῳ καὶ δι’ ἀπάτης γεγενημένων τὸ ἔργον. Ἀννίβας φοβερὸς μὲν καὶ δεινὸς ἐνέκειτο Ῥωμαίοις, ὥσπερ ἀμέλει Λακεδαιμόνιοι τότε Θηβαίοις, ἐνδοῦναι δὲ τούτους μὲν Πελοπίδᾳ καὶ περὶ Τεγύρας καὶ περὶ Λεῦκτρα βέβαιόν ἐστιν, Ἀννίβαν δὲ Μάρκελλος, ὡς μὲν οἱ περὶ Πολύβιον λέγουσιν, οὐδὲ ἅπαξ ἐνίκησεν, ἀλλ’ ἀήττητος ὁ ἁνὴρ δοκεῖ διαγενέσθαι μέχρι Σκηπίωνος· ἡμεῖς δὲ Λιβίῳ, Καίσαρι καὶ Νέπωτι καὶ τῶν Ἑλληνικῶν τῷ βασιλεῖ Ἰόβᾳ πιστεύομεν, ἥττας τινὰς καὶ τροπὰς ὑπὸ Μαρκέλλου τῶν σὺν Ἀννίβᾳ, γενέσθαι· μεγάλην δὲ αὗται ῥοπὴν οὐδεμίαν ἐποίησαν, ἀλλ’ ἔοικε ψευδόπτωμά τι γενέσθαι περὶ τὸν Λίβυν ἐν ταῖς συμπλοκαῖς ἐκείναις. ὃ δὴ κατὰ λόγον καὶ προσηκόντως ἐθαυμάσθη, μετὰ τοσαύτας τροπὰς στρατοπέδων καὶ φόνους στρατηγῶν καὶ σύγχυσιν ὅλης ὁμοῦ τῆς Ῥωμαίων ἡγεμονίας εἰς ἀντίπαλα τῷ θαρρεῖν καθισταμένων· ὁ γὰρ ἐκ πολλοῦ τοῦ πάλαι περιδεοῦς καὶ καταπεπληγότος αὖθις ἐμβαλὼν τῷ στρατεύματι ζῆλον καὶ φιλονεικίαν πρὸς τοὺς πολεμίους, καὶ τοῦτο δὴ τὸ μὴ ῥᾳδίως τῆς νίκης ὑφιέμενον, ἀλλὰ καὶ ἀμφισβητοῦν τε καὶ φιλοτιμούμενον ἐπάρας καὶ θαρρύνας, εἷς ἀνὴρ ἦν, Μάρκελλος· εἰθισμένους γὰρ ὑπὸ τῶν συμφορῶν, εἰ φεύγοντες ἐκφύγοιεν Ἀννίβαν, ἀγαπᾶν, ἐδίδαξεν αἰσχύνεσθαι σῳζομένους μεθ’ ἥττης, αἰδεῖσθαι δὲ παρὰ μικρὸν ἐνδόντας, ἀλγεῖν δὲ μὴ κρατήσαντας.", "st": "Comp. Pel.–Marc. 1.2"}, {"sp": "N", "t": "ἐπεὶ τοίνυν Πελοπίδας μὲν οὐδεμίαν ἡττήθη μάχην στρατηγῶν, Μάρκελλος δὲ πλείστας τῶν καθ’ αὑτὸν Ῥωμαίων ἐνίκησε, δόξειεν ἂν ἴσως τῷ δυσνικήτῳ πρὸς τὸ ἀήττητον ὑπὸ πλήθους τῶν κατωρθωμένων ἐπανισοῦσθαι. καὶ μὴν οὗτος μὲν εἷλε Συρακούσας, ἐκεῖνος δὲ τῆς Λακεδαίμονος ἀπέτυχεν. ἀλλ’ οἶμαι μεῖζον εἶναι τοῦ καταλαβεῖν Σικελίαν τὸ τῇ Σπάρτῃ προσελθεῖν καὶ διαβῆναι πρῶτον ἀνθρώπων πολέμῳ τὸν Εὐρώταν, εἰ μὴ νὴ Δία τοῦτο μὲν φήσει τις τὸ ἔργον Ἐπαμεινώνδᾳ μᾶλλον ἢ Πελοπίδᾳ προσήκειν, ὥσπερ καὶ τὰ Λεῦκτρα, τῶν δὲ Μαρκέλλῳ διαπεπραγμένων ἀκοινώνητον εἶναι τὴν δόξαν. καὶ γὰρ Συρακούσας μόνος εἷλε, καὶ Κελτοὺς ἄνευ τοῦ συνάρχοντος ἐτρέψατο, καὶ πρὸς Ἀννίβαν μηδενὸς συλλαμβάνοντος, ἀλλὰ καὶ πάντων ἀποτρεπόντων, ἀντιταξάμενος καὶ μεταβαλὼν τὸ σχῆμα τοῦ πολέμου πρῶτος ἡγεμὼν τοῦ τολμᾶν κατέστη.", "st": "Comp. Pel.–Marc. 2.1"}, {"sp": "N", "t": "τὴν τοίνυν τελευτὴν ἐπαινῶ μὲν οὐδετέρου τῶν ἀνδρῶν, ἀλλ’ ἀνιῶμαι καὶ ἀγανακτῶ τῷ παραλόγῳ τοῦ συμπτώματος· καὶ θαυμάζω μὲν ἐν μάχαις τοσαύταις ὅσαις ἀποκάμοι τις ἂν καταριθμῶν, μηδὲ τρωθέντα τὸν Ἀννίβαν, ἄγαμαι δὲ καὶ τὸν ἐν τῇ Παιδείᾳ Χρυσάνταν, ὃς διηρμένος κοπίδα καὶ παίειν μέλλων πολέμιον, ὡς ὑπεσήμηνεν ἡ σάλπιγξ ἀνακλητικόν, ἀφεὶς τὸν ἄνδρα μάλα πρᾴως καὶ κοσμίως ἀνεχώρησεν. οὐ μὴν ἀλλὰ τὸν Πελοπίδαν ποιεῖ συγγνωστὸν ἅμα τῷ τῆς μάχης καιρῷ παράθερμον ὄντα καὶ πρὸς τὴν ἄμυναν οὐκ ἀγεννῶς ἐκφέρων ὁ θυμός· ἄριστον μὲν γὰρ νικῶντα σῴζεσθαι τὸν στρατηγόν, εἰ δὲ θανεῖν, εἰς ἀρετὴν καταλύσαντα βίον, ὡς Εὐριπίδης φησίν. οὕτω γὰρ οὐ πάθος, ἀλλὰ πρᾶξις γίνεται τοῦ τελευτῶντος ὁ θάνατος. πρὸς δὲ τῷ θυμῷ τοῦ Πελοπίδου καὶ τὸ τέλος αὐτὸ τὸ τῆς νίκης ἐν τῷ πεσεῖν τὸν τύραννον ὁρώμενον οὐ παντάπασιν ἀλόγως ἐπεσπάσατο τὴν ὁρμήν· χαλεπὸν γὰρ ἑτέρας οὕτω καλὴν καὶ λαμπρὰν ἐχούσης ὑπόθεσιν ἀριστείας ἐπιλαβέσθαι. Μάρκελλος δὲ, μήτε χρείας μεγάλης ἐπικειμένης, μήτε τοῦ παρὰ τὰ δεινὰ πολλάκις ἐξιστάντος τὸν λογισμὸν ἐνθουσιασμοῦ παρεστῶτος, ὠσάμενος ἀπερισκέπτως εἰς κίνδυνον οὐ στρατηγοῦ πτῶμα, προδρόμου δέ τινος ἢ κατασκόπου πέπτωκεν, ὑπατείας πέντε καὶ τρεῖς θριάμβους καὶ σκῦλα καὶ τροπαιοφορίας ἀπὸ βασιλέων τοῖς προαποθνῄσκουσι Καρχηδονίων Ἴβηρσι καὶ Νομάσιν ὑποβαλών. ὥστε νεμεσῆσαι αὐτοὺς ἐκείνους ἑαυτοῖς τοῦ κατορθώματος, ἄνδρα Ῥωμαίων ἄριστον ἀρετῇ καὶ δυνάμει μέγιστον καὶ δόξῃ λαμπρότατον ἐν τοῖς Φρεγελλανῶν προδιερευνηταῖς παραναλῶσθαι.", "st": "Comp. Pel.–Marc. 3.1"}, {"sp": "N", "t": "χρὴ δὲ ταῦτα μὴ κατηγορίαν εἶναι τῶν ἀνδρῶν νομίζειν, ἀλλ’ ὡς ἀγανάκτησίν τινα καὶ παρρησίαν ὑπὲρ αὐτῶν ἐκείνων πρὸς αὐτοὺς καὶ τὴν ἀνδρείαν αὐτῶν, εἰς ἣν τὰς ἄλλας κατανάλωσαν ἀρετάς ἀφειδήσαντες τοῦ βίου καὶ τῆς ψυχῆς, ὥσπερ ἑαυτοῖς, οὐ ταῖς πατρίσι μᾶλλον καὶ φίλοις καὶ συμμάχοις, ἀπολλυμένων.", "st": "Comp. Pel.–Marc. 3.5"}, {"sp": "N", "t": "μετὰ δὲ τὸν θάνατον Πελοπίδας μὲν τοὺς συμμάχους ταφεῖς ἔσχεν, ὑπὲρ ὧν ἀπέθανε, Μάρκελλος δὲ τοὺς πολεμίους, ὑφ’ ὧν ἀπέθανε, ζηλωτὸν μὲν οὖν ἐκεῖνο καὶ μακάριον, κρεῖττον δὲ καὶ μεῖζον εὐνοίας χάριν ἀμειβομένης ἔχθρα λυποῦσαν ἀρετὴν θαυμάζουσα. τὸ γὰρ καλὸν ἐνταῦθα τὴν τιμὴν ἔχει μόνον, ἐκεῖ δὲ τὸ λυσιτελὲς καὶ ἡ χρεία μᾶλλον ἀγαπᾶται τῆς ἀρετῆς.", "st": "Comp. Pel.–Marc. 3.6"}, {"sp": "HDR", "t": "Ἀριστείδης"}, {"sp": "N", "t": "Ἀριστείδης ὁ Λυσιμάχου φυλῆς μὲν ἦν Ἀντιοχίδος, τῶν δὲ δήμων Ἀλωπεκῆθεν. περὶ δ’ οὐσίας αὐτοῦ λόγοι διάφοροι γεγόνασιν, οἱ μὲν ὡς ἐν πενίᾳ συντόνῳ καταβιώσαντος καὶ μετὰ τὴν τελευτὴν ἀπολιπόντος θυγατέρας δύο πολὺν χρόνον ἀνεκδότους δι’ ἀπορίαν γενομένας· πρὸς δὲ τοῦτον τὸν λόγον ὑπὸ πολλῶν εἰρημένον ἀντιτασσόμενος ὁ Φαληρεὺς Δημήτριος ἐν τῷ Σωκράτει χωρίον Φαληροῖ φησι γινώσκειν Ἀριστείδου γενόμενον, ἐν ᾧ τέθαπται, καὶ τεκμήρια τῆς περὶ τὸν οἶκον εὐπορίας ἓν μὲν ἡγεῖται τὴν ἐπώνυμον ἀρχήν, ἣν ἦρχεν ὁ τῷ κυάμῳ λαχὼν ἐκ τῶν γενῶν τῶν τὰ μέγιστα τιμήματα κεκτημένων, οὓς πεντακοσιομεδίμνους προσηγόρευον, ἕτερον δὲ τὸν ἐξοστρακισμόν· οὐδενὶ γὰρ τῶν πενήτων, ἀλλὰ τοῖς ἐξ οἴκων τε μεγάλων καὶ διὰ γένους ὄγκον ἐπιφθόνων ὄστρακον ἐπιφέρεσθαι· τρίτον δὲ καὶ τελευταῖον, ὅτι νίκης ἀναθήματα χορηγικοὺς τρίποδας ἐν Διονύσου καταλέλοιπεν, οἳ καὶ καθ’ ἡμᾶς ἐδείκνυντο τοιαύτην ἐπιγραφὴν διασώζοντες· Ἀντιοχὶς ἐνίκα, Ἀριστείδης ἐχορήγει, Ἀρχέστρατος ἐδίδασκε.", "st": "Arist. 1.1"}, {"sp": "N", "t": "τουτὶ μὲν οὖν, καίπερ εἶναι δοκοῦν μέγιστον, ἀσθενέστατόν ἐστι. καὶ γὰρ Ἐπαμεινώνδας, ὃν πάντες ἄνθρωποι γινώσκουσιν ἐν πενίᾳ καὶ τραφέντα πολλῇ καὶ βιώσαντα, καὶ Πλάτων ὁ φιλόσοφος οὐκ ἀφιλοτίμους ἀνεδέξαντο χορηγίας, ὁ μὲν αὐληταῖς ἀνδράσιν, ὁ δὲ παισὶ κυκλίοις χορηγήσας, τούτῳ μὲν Δίωνος τοῦ Συρακουσίου τὴν δαπάνην παρέχοντος, Ἐπαμεινώνδᾳ δὲ τῶν περὶ Πελοπίδαν. οὐ γὰρ ἔστι τοῖς ἀγαθοῖς ἀκήρυκτος καὶ ἄσπονδος πρὸς τὰς παρὰ τῶν φίλων δωρεὰς πόλεμος, ἀλλὰ τὰς εἰς ἀπόθεσιν καὶ πλεονεξίαν ἀγεννεῖς ἡγούμενοι καὶ ταπεινάς, ὅσαι φιλοτιμίας τινὸς ἀκερδοῦς ἔχονται καὶ λαμπρότητος οὐκ ἀπωθοῦνται.", "st": "Arist. 1.4"}, {"sp": "N", "t": "Παναίτιος μέντοι περὶ τοῦ τρίποδος ἀποφαίνει τὸν Δημήτριον ὁμωνυμίᾳ διεψευσμένον· ἀπὸ γὰρ τῶν Μηδικῶν εἰς τὴν τελευτὴν τοῦ Πελοποννησιακοῦ πολέμου δύο μόνους Ἀριστείδας χορηγοὺς ἀναγράφεσθαι νικῶντας, ὧν οὐδέτερον εἶναι τῷ Λυσιμάχου τὸν αὐτόν, ἀλλὰ τὸν μὲν Ξενοφίλου πατρός, τὸν δὲ χρόνῳ πολλῷ νεώτερον, ὡς ἐλέγχει τὰ γράμματα τῆς μετ’ Εὐκλείδην ὄντα γραμματικῆς καὶ προσγεγραμμένος ὁ Ἀρχέστρατος, ὃν ἐν τοῖς Μηδικοῖς οὐδείς, ἐν δὲ τοῖς Πελοποννησιακοῖς συχνοὶ χορῶν διδάσκαλον ἀναγράφουσι.", "st": "Arist. 1.6"}, {"sp": "N", "t": "τὸ μὲν οὖν τοῦ Παναιτίου βέλτιον ἐπισκεπτέον ὅπως ἔχει. τῷ δ’ ὀστράκῳ πᾶς ὁ διὰ δόξαν ἢ γένος ἢ λόγου δύναμιν ὑπὲρ τοὺς πολλοὺς νομιζόμενος ὑπέπιπτεν· ὅπου καὶ Δάμων ὁ Περικλέους διδάσκαλος, ὅτι τὸ φρονεῖν ἐδόκει τις εἶναι περιττός, ἐξωστρακίσθη. καὶ μὴν ἄρξαι γε τὸν Ἀριστείδην ὁ Ἰδομενεὺς οὐ κυαμευτόν, ἀλλ’ ἑλομένων Ἀθηναίων φησίν. εἰ δὲ καὶ μετὰ τὴν ἐν Πλαταιαῖς μάχην ἦρξεν, ὡς αὐτὸς ὁ Δημήτριος γέγραφε, καὶ πάνυ πιθανόν ἐστιν ἐπὶ δόξῃ τοσαύτῃ καὶ κατορθώμασι τηλικούτοις ἀξιωθῆναι δι’ ἀρετὴν ἧς διὰ πλοῦτον ἐτύγχανον οἱ λαγχάνοντες. ἀλλὰ γὰρ ὁ μὲν Δημήτριος οὐ μόνον Ἀριστείδην, ἀλλὰ καὶ Σωκράτην δῆλός ἐστι τῆς πενίας ἐξελέσθαι φιλοτιμούμενος ὡς μεγάλου κακοῦ· καὶ γὰρ ἐκείνῳ φησὶν οὐ μόνον τὴν οἰκίαν ὑπάρχειν, ἀλλὰ καὶ μνᾶς ἑβδομήκοντα τοκιζομένας ὑπὸ Κρίτωνος.", "st": "Arist. 1.7"}, {"sp": "N", "t": "Ἀριστείδης δὲ Κλεισθένους μὲν τοῦ καταστησαμένου τὴν πολιτείαν μετὰ τοὺς τυράννους ἑταῖρος γενόμενος, ζηλώσας δὲ καὶ θαυμάσας μάλιστα τῶν πολιτικῶν ἀνδρῶν Λυκοῦργον τὸν Λακεδαιμόνιον, ἥψατο μὲν ἀριστοκρατικῆς πολιτείας, ἔσχε δ’ ἀντιτασσόμενον ὑπὲρ τοῦ δήμου Θεμιστοκλέα τὸν Νεοκλέους. ἔνιοι μὲν οὖν φασιν παῖδας ὄντας αὐτοὺς καὶ συντρεφομένους ἀπ’ ἀρχῆς ἐν παντὶ καὶ σπουδῆς ἐχομένῳ καὶ παιδιᾶς πράγματι καὶ λόγῳ διαφέρεσθαι πρὸς ἀλλήλους, καὶ τὰς φύσεις εὐθὺς ὑπὸ τῆς φιλονεικίας ἐκείνης ἀνακαλύπτεσθαι, τὴν μὲν εὐχερῆ καὶ παράβολον καὶ πανοῦργον οὖσαν καὶ μετ’ ὀξύτητος ἐπὶ πάντα ῥᾳδίως φερομένην, τὴν δ’ ἱδρυμένην ἐν ἤθει βεβαίῳ καὶ πρὸς τὸ δίκαιον ἀτενῆ, ψεῦδος δὲ καὶ βωμολοχίαν καὶ ἀπάτην οὐδ’ ἐν παιδιᾶς τινι τρόπῳ προσιεμένην.", "st": "Arist. 2.1"}, {"sp": "N", "t": "ἀρίστων δ’ ὁ Κεῖος ἐξ ἐρωτικῆς ἀρχῆς γενέσθαι φησὶ καὶ προελθεῖν ἐπὶ τοσοῦτον τὴν ἔχθραν αὐτῶν. Στησίλεω γάρ, ὃς ἦν γένει Κεῖος, ἰδέᾳ τε καὶ μορφῇ σώματος πολὺ τῶν ἐν ὥρᾳ λαμπρότατος, ἀμφοτέρους ἐρασθέντας οὐ μετρίως ἐνεγκεῖν τὸ πάθος οὐδ’ ἅμα λήγοντι τῷ κάλλει τοῦ παιδὸς ἀποθέσθαι τὴν φιλονεικίαν, ἀλλ’ ὥσπερ ἐγγυμνασαμένους ἐκείνῃ πρὸς τὴν πολιτείαν εὐθὺς ὁρμῆσαι διαπύρους ὄντας καὶ διαφόρως ἔχοντας.", "st": "Arist. 2.3"}, {"sp": "N", "t": "ὁ μὲν οὖν Θεμιστοκλῆς εἰς ἑταιρείαν ἐμβαλὼν ἑαυτὸν εἶχε πρόβλημα καὶ δύναμιν οὐκ εὐκαταφρόνητον, ὥστε καὶ πρὸς τὸν εἰπόντα καλῶς αὐτὸν ἄρξειν Ἀθηναίων, ἄνπερ ἴσος ᾖ καὶ κοινὸς ἅπασι μηδέποτε, εἰπεῖν, εἰς τοῦτον ἐγὼ καθίσαιμι τὸν θρόνον, ἐν ᾧ πλέον οὐδὲν ἕξουσιν οἱ φίλοι παρ’ ἐμοὶ τῶν ἀλλοτρίων· Ἀριστείδης δὲ καθ’ ἑαυτὸν ὥσπερ ὁδὸν ἰδίαν ἐβάδιζε διὰ τῆς πολιτείας, πρῶτον μὲν οὐ βουλόμενος συναδικεῖν τοῖς ἑταίροις ἢ λυπηρὸς εἶναι μὴ χαριζόμενος, ἔπειτα τὴν ἀπὸ τῶν φίλων δύναμιν οὐκ ὀλίγους ἰδὼν ἐπαίρουσαν ἀδικεῖν ἐφυλάττετο, μόνῳ τῷ χρηστὰ καὶ δίκαια πράττειν καὶ λέγειν ἀξιῶν θαρρεῖν τὸν ἀγαθὸν πολίτην.", "st": "Arist. 2.4"}, {"sp": "N", "t": "οὐ μὴν ἀλλά, πολλὰ κινουμένου τοῦ Θεμιστοκλέους παραβόλως καὶ πρὸς πᾶσαν αὐτῷ πολιτείαν ἐνισταμένου καὶ διακόπτοντος, ἠναγκάζετό που καὶ αὐτὸς τὰ μὲν ἀμυνόμενος, τὰ δὲ κολούων τὴν ἐκείνου δύναμιν χάριτι τῶν πολλῶν αὐξομένην ὑπεναντιοῦσθαι οἷς ἔπραττεν ὁ Θεμιστοκλῆς, βέλτιον ἡγούμενος παρελθεῖν ἔνια τῶν συμφερόντων τὸν δῆμον ἢ τῷ κρατεῖν ἐκεῖνον ἐν πᾶσιν ἰσχυρὸν γενέσθαι. τέλος δέ ποτε τοῦ Θεμιστοκλέους πράττοντός τι τῶν δεόντων ἀντικρούσας καὶ περιγενόμενος οὐ κατέσχεν, ἀλλ’ εἶπεν ἀπὸ τῆς ἐκκλησίας ἀπιών, ὡς οὐκ ἔστι σωτηρία τοῖς Ἀθηναίων πράγμασιν, εἰ μὴ καὶ Θεμιστοκλέα καὶ αὐτὸν εἰς τὸ βάραθρον ἐμβάλοιεν. πάλιν δὲ γράψας τινὰ γνώμην εἰς τὸν δῆμον, ἀντιλογίας οὔσης πρὸς αὐτὴν καὶ φιλονεικίας, ἐκράτει· μέλλοντος δὲ τοῦ προέδρου τὸν δῆμον ἐπερωτᾶν αἰσθόμενος ἐκ τῶν λόγων αὐτῶν τὸ ἀσύμφορον ἀπέστη τοῦ ψηφίσματος. πολλάκις δὲ καὶ δι’ ἑτέρων εἰσέφερε τὰς γνώμας, ὡς μὴ φιλονεικίᾳ τῇ πρὸς αὐτὸν ὁ Θεμιστοκλῆς ἐμπόδιος εἴη τῷ συμφέροντι.", "st": "Arist. 3.1"}, {"sp": "N", "t": "θαυμαστὴ δέ τις ἐφαίνετο αὐτοῦ παρὰ τὰς ἐν τῇ πολιτείᾳ μεταβολὰς ἡ εὐστάθεια, μήτε ταῖς τιμαῖς ἐπαιρομένου πρός τε τὰς δυσημερίας ἀθορύβως καὶ πρᾴως ἔχοντος, καὶ ὁμοίως ἡγουμένου χρῆναι τῇ πατρίδι παρέχειν ἑαυτὸν οὐ χρημάτων μόνον, ἀλλὰ καὶ δόξης προῖκα καὶ ἀμισθὶ πολιτευόμενον. ὅθεν, ὡς ἔοικε, τῶν εἰς Ἀμφιάραον ὑπ’ Αἰσχύλου πεποιημένων ἰαμβείων ἐν τῷ θεάτρῳ λεγομένων·", "st": "Arist. 3.4"}, {"sp": "N", "t": "οὐ γὰρ δοκεῖν δίκαιος, ἀλλ’ εἶναι θέλει,<br>βαθεῖαν ἄλοκα διὰ φρενὸς καρπούμενος,<br>ἀφ’ ἧς τὰ κεδνὰ βλαστάνει βουλεύματα,", "st": "Arist. 3.4b"}, {"sp": "N", "t": "πάντες ἀπέβλεψαν εἰς Ἀριστείδην, ὡς ἐκείνῳ μάλιστα τῆς ἀρετῆς ταύτης προσηκούσης.", "st": "Arist. 3.4c"}, {"sp": "N", "t": "οὐ μόνον δὲ πρὸς εὔνοιαν καὶ χάριν, ἀλλὰ καὶ πρὸς ὀργὴν καὶ πρὸς ἔχθραν ἰσχυρότατος ἦν ὑπὲρ τῶν δικαίων ἀντιστῆναι. λέγεται γοῦν ποτε διώκων ἐχθρόν ἐν δικαστηρίῳ, μετὰ τὴν κατηγορίαν οὐ βουλομένων ἀκούειν τοῦ κινδυνεύοντος τῶν δικαστῶν, ἀλλὰ τὴν ψῆφον εὐθὺς αἰτούντων ἐπ’ αὐτόν, ἀναπηδήσας τῷ κρινομένῳ συνικετεύειν, ὅπως ἀκουσθείη καὶ τύχοι τῶν νομίμων· πάλιν δὲ κρίνων ἰδιώταις δυσί, τοῦ ἑτέρου λέγοντος, ὡς πολλὰ τυγχάνει τὸν Ἀριστείδην ὁ ἀντίδικος λελυπηκὼς λέγ’, ὦ ’γαθέ, φάναι, μᾶλλον, εἴ τι σὲ κακὸν πεποίηκε· σοὶ γάρ, οὐκ ἐμαυτῷ, δικάζω. τῶν δὲ δημοσίων προσόδων αἱρεθεὶς ἐπιμελητὴς οὐ μόνον τοὺς καθ’ αὑτόν, ἀλλὰ καὶ τοὺς πρὸ αὑτοῦ γενομένους ἄρχοντας ἀπεδείκνυε πολλὰ νενοσφισμένους, καὶ μάλιστα τὸν Θεμιστοκλέα·", "st": "Arist. 4.1"}, {"sp": "N", "t": "σοφὸς γὰρ ἁνήρ, τῆς δὲ χειρὸς οὐ κρατῶν.", "st": "Arist. 4.1b"}, {"sp": "N", "t": "διὸ καὶ συναγαγὼν πολλοὺς ἐπὶ τὸν Ἀριστείδην ἐν ταῖς εὐθύναις διώκων κλοπῆς καταδίκῃ περιέβαλεν, ὥς φησιν Ἰδομενεύς. ἀγανακτούντων δὲ τῶν πρώτων ἐν τῇ πόλει καὶ βελτίστων, οὐ μόνον ἀφείθη τῆς ζημίας, ἀλλὰ καὶ πάλιν ἄρχων ἐπὶ τὴν αὐτὴν διοίκησιν ἀπεδείχθη. προσποιούμενος δὲ τῶν προτέρων μεταμέλειν αὐτῷ καὶ μαλακώτερον ἐνδιδοὺς ἑαυτόν, ἤρεσκε τοῖς τὰ κοινὰ κλέπτουσιν οὐκ ἐξελέγχων οὐδ’ ἀκριβολογούμενος, ὥστε καταπιμπλαμένους τῶν δημοσίων ὑπερεπαινεῖν τὸν Ἀριστείδην καὶ δεξιοῦσθαι τὸν δῆμον ὑπὲρ αὐτοῦ, σπουδάζοντας ἄρχοντα πάλιν αἱρεθῆναι. μελλόντων δὲ χειροτονεῖν ἐπετίμησε τοῖς Ἀθηναίοις· ὅτε μὲν γάρ, ἔφη, πιστῶς καὶ καλῶς ὑμῖν ἦρξα, προὐπηλακίσθην· ἐπεὶ δὲ πολλὰ τῶν κοινῶν καταπροεῖμαι τοῖς κλέπτουσι θαυμαστὸς εἶναι δοκῶ πολίτης. αὐτὸς μὲν οὖν αἰσχύνομαι τῇ νῦν τιμῇ μᾶλλον ἢ τῇ πρώην καταδίκῃ, συνάχθομαι δ’ ὑμῖν, παρ’ οἷς ἐνδοξότερόν ἐστι τοῦ σώζειν τὰ δημόσια τὸ χαρίζεσθαι τοῖς πονηροῖς. ταῦτα δ’ εἰπὼν καὶ τὰς κλοπὰς ἐξελέγξας τοὺς μὲν τότε βοῶντας ὑπὲρ αὐτοῦ καὶ μαρτυροῦντας ἐπεστόμισε, τὸν δ’ ἀληθινὸν καὶ δίκαιον ἀπὸ τῶν βελτίστων ἔπαινον εἶχεν.", "st": "Arist. 4.3"}, {"sp": "N", "t": "ἐπεὶ δὲ Δᾶτις ὑπὸ Δαρείου πεμφθεὶς λόγῳ μὲν ἐπιθεῖναι δίκην Ἀθηναίοις, ὅτι Σάρδεις ἐνέπρησαν, ἔργῳ δὲ καταστρέψασθαι τοὺς Ἕλληνας, εἰς Μαραθῶνα παντὶ τῷ στόλῳ κατέσχε καὶ τὴν χώραν ἐπόρθει, τῶν δέκα καθεστώτων τοῖς Ἀθηναίοις ἐπὶ τὸν πόλεμον στρατηγῶν μέγιστον μὲν εἶχεν ἀξίωμα Μιλτιάδης, δόξῃ δὲ καὶ δυνάμει δεύτερος ἦν Ἀριστείδης. καὶ τότε περὶ τῆς μάχης γνώμῃ τῇ Μιλτιάδου προσθέμενος οὐ μικρὰν ἐποίησε ῥοπήν· καὶ παρ’ ἡμέραν ἑκάστου στρατηγοῦ τὸ κράτος ἔχοντος, ὡς περιῆλθεν εἰς αὐτὸν ἡ ἀρχή, παρέδωκε Μιλτιάδῃ, διδάσκων τοὺς συνάρχοντας, ὅτι τὸ πείθεσθαι καὶ ἀκολουθεῖν τοῖς εὖ φρονοῦσιν οὐκ αἰσχρόν, ἀλλὰ σεμνόν ἐστι καὶ σωτήριον. οὕτω δὲ πραΰνας τὴν φιλονεικίαν καὶ προτρεψάμενος αὐτοὺς ἀγαπᾶν μιᾷ γνώμῃ τῇ κρατίστῃ χρωμένους, ἔρρωσε τὸν Μιλτιάδην τῷ ἀπερισπάστῳ τῆς ἐξουσίας ἰσχυρὸν γενόμενον. χαίρειν γὰρ ἐῶν ἕκαστος ἤδη τὸ παρ’ ἡμέραν ἄρχειν ἐκείνῳ προσεῖχεν.", "st": "Arist. 5.1"}, {"sp": "N", "t": "ἐν δὲ τῇ μάχῃ μάλιστα τῶν Ἀθηναίων τοῦ μέσου πονήσαντος καὶ πλεῖστον ἐνταῦθα χρόνον τῶν βαρβάρων ἀντερεισάντων κατὰ τὴν Λεοντίδα καὶ τὴν Ἀντιοχίδα φυλήν, ἠγωνίσαντο λαμπρῶς τεταγμένοι παρ’ ἀλλήλους ὅ τε Θεμιστοκλῆς καὶ ὁ Ἀριστείδης· ὁ μὲν γὰρ Λεοντίδος ἦν, ὁ δ’ Ἀντιοχίδος· ἐπεὶ δὲ τρεψάμενοι τοὺς βαρβάρους ἐνέβαλον εἰς τὰς ναῦς καὶ πλέοντας οὐκ ἐπὶ νήσων ἑώρων, ἀλλ’ ὑπὸ τοῦ πνεύματος καὶ τῆς θαλάσσης εἴσω πρὸς τὴν Ἀττικὴν ἀποβιαζομένους, φοβηθέντες μὴ τὴν πόλιν ἔρημον λάβωσι τῶν ἀμυνομένων, ταῖς μὲν ἐννέα φυλαῖς ἠπείγοντο πρὸς τὸ ἄστυ καὶ κατήνυσαν αὐθημερόν· ἐν δὲ Μαραθῶνι μετὰ τῆς ἑαυτοῦ φυλῆς Ἀριστείδης ἀπολειφθεὶς φύλαξ τῶν αἰχμαλώτων καὶ τῶν λαφύρων οὐκ ἐψεύσατο τὴν δόξαν, ἀλλὰ χύδην μὲν ἀργύρου καὶ χρυσοῦ παρόντος, ἐσθῆτος δὲ παντοδαπῆς καὶ χρημάτων ἄλλων ἀμυθήτων ἐν ταῖς σκηναῖς καὶ τοῖς ἡλωκόσι σκάφεσιν ὑπαρχόντων, οὔτ’ αὐτὸς ἐπεθύμησε θιγεῖν οὔτ’ ἄλλον εἴασε, πλὴν εἴ τινες ἐκεῖνον λαθόντες ὠφελήθησαν· ὧν ἦν καὶ Καλλίας ὁ δᾳδοῦχος.", "st": "Arist. 5.3"}, {"sp": "N", "t": "τούτῳ γάρ τις, ὡς ἔοικε, τῶν βαρβάρων προσέπεσεν οἰηθεὶς βασιλέα διὰ τὴν κόμην καὶ τὸ στρόφιον εἶναι· προσκυνήσας δὲ καὶ λαβόμενος τῆς δεξιᾶς ἔδειξε πολὺ χρυσίον ἐν λάκκῳ τινὶ κατορωρυγμένον. ὁ δὲ Καλλίας ὠμότατος ἀνθρώπων καὶ παρανομώτατος γενόμενος τὸν μὲν χρυσὸν ἀνείλετο, τὸν δ’ ἄνθρωπον, ὡς μὴ κατείποι πρὸς ἑτέρους, ἀπέκτεινεν. ἐκ τούτου φασὶ καὶ λακκοπλούτους ὑπὸ τῶν κωμικῶν τοὺς ἀπὸ τῆς οἰκίας λέγεσθαι, σκωπτόντων εἰς τὸν τόπον, ἐν ᾧ τὸ χρυσίον ὁ Καλλίας εὗρεν.", "st": "Arist. 5.6"}, {"sp": "N", "t": "Ἀριστείδης δὲ τὴν ἐπώνυμον εὐθὺς ἀρχὴν ἦρξε. καίτοι φησὶν ὁ Φαληρεὺς Δημήτριος ἄρξαι τὸν ἄνδρα μικρὸν ἔμπροσθεν τοῦ θανάτου μετὰ τὴν ἐν Πλαταιαῖς μάχην. ἐν δὲ ταῖς ἀναγραφαῖς μετὰ μὲν Ξανθιππίδην, ἐφ’ οὗ Μαρδόνιος ἡττήθη Πλαταιᾶσιν, οὐδ’ ὁμώνυμον Ἀριστείδην ἐν πάνυ πολλοῖς λαβεῖν ἔστι, μετὰ δὲ Φαίνιππον, ἐφ’ οὗ τὴν ἐν Μαραθῶνι μάχην ἐνίκων, εὐθὺς Ἀριστείδης ἄρχων ἀναγέγραπται.", "st": "Arist. 5.7"}, {"sp": "N", "t": "πασῶν δὲ τῶν περὶ αὐτὸν ἀρετῶν ἡ δικαιοσύνη μάλιστα τοῖς πολλοῖς αἴσθησιν παρεῖχε διὰ τὸ τὴν χρείαν ἐνδελεχεστάτην αὐτῆς καὶ κοινοτάτην ὑπάρχειν. ὅθεν ἀνὴρ πένης καὶ δημοτικὸς ἐκτήσατο τὴν βασιλικωτάτην καὶ θειοτάτην προσηγορίαν τὸν Δίκαιον· ὃ τῶν βασιλέων καὶ τυράννων οὐδεὶς ἐζήλωσεν, ἀλλὰ Πολιορκηταὶ καὶ Κεραυνοὶ καὶ Νικάτορες, ἔνιοι δ’ Ἀετοὶ καὶ Ἱέρακες ἔχαιρον προσαγορευόμενοι, τὴν ἀπὸ τῆς βίας καὶ τῆς δυνάμεως, ὡς ἔοικε, μᾶλλον ἢ τὴν ἀπὸ τῆς ἀρετῆς δόξαν ἀγαπῶντες. καίτοι τὸ θεῖον, ᾧ γλίχονται συνοικειοῦν καὶ συναφομοιοῦν αὑτούς, τρισὶ δοκεῖ διαφέρειν, ἀφθαρσίᾳ καὶ δυνάμει καὶ ἀρετῇ, ὧν καὶ σεμνότατον ἡ ἀρετὴ καὶ θειότατόν ἐστιν. ἀφθάρτῳ μὲν γὰρ εἶναι καὶ τῷ κενῷ καὶ τοῖς στοιχείοις συμβέβηκε, δύναμιν δὲ καὶ σεισμοὶ καὶ κεραυνοὶ καὶ πνευμάτων ὁρμαὶ καὶ ῥευμάτων ἐπιφοραὶ μεγάλην ἔχουσι, δίκης δὲ καὶ θέμιδος οὐδὲν ὅτι μὴ τῷ φρονεῖν καὶ λογίζεσθαι μεταλαγχάνει.", "st": "Arist. 6.1"}, {"sp": "N", "t": "διὸ καὶ τριῶν ὄντων, ἃ πεπόνθασιν οἱ πολλοὶ πρὸς τὸ θεῖον, ζήλου καὶ φόβου καὶ τιμῆς, ζηλοῦν μὲν αὐτοὺς καὶ μακαρίζειν ἐοίκασι κατὰ τὸ ἄφθαρτον καὶ ἀΐδιον, ἐκπλήττεσθαι δὲ καὶ δεδιέναι κατὰ τὸ κύριον καὶ δυνατόν, ἀγαπᾶν δὲ καὶ τιμᾶν καὶ σέβεσθαι κατὰ τὴν δικαιοσύνην. ἀλλά, καίπερ οὕτω διακείμενοι, τῆς μὲν ἀθανασίας, ἣν ἡ φύσις ἡμῶν οὐ δέχεται, καὶ τῆς δυνάμεως, ἧς ἐν τῇ τύχῃ κεῖται τὸ πλεῖστον, ἐπιθυμοῦσι, τὴν δ’ ἀρετήν, ὃ μόνον ἐστὶ τῶν θείων ἀγαθῶν ἐφ’ ἡμῖν, ἐν ὑστέρῳ τίθενται, κακῶς φρονοῦντες, ὡς τὸν ἐν δυνάμει καὶ τύχῃ μεγάλῃ καὶ ἀρχῇ βίον ἡ μὲν δικαιοσύνη ποιεῖ θεῖον, ἡ δ’ ἀδικία θηριώδη.", "st": "Arist. 6.4"}, {"sp": "N", "t": "τῷ δ’ οὖν Ἀριστείδῃ συνέβη τὸ πρῶτον ἀγαπωμένῳ διὰ τὴν ἐπωνυμίαν ὕστερον φθονεῖσθαι, μάλιστα μὲν τοῦ Θεμιστοκλέους λόγον εἰς τοὺς πολλοὺς διαδιδόντος, ὡς Ἀριστείδης ἀνῃρηκὼς τὰ δικαστήρια τῷ κρίνειν ἅπαντα καὶ δικάζειν, λέληθε μοναρχίαν ἀδορυφόρητον ἑαυτῷ κατεσκευασμένος· ἤδη δέ που καὶ ὁ δῆμος ἐπὶ τῇ νίκῃ μέγα φρονῶν καὶ τῶν μεγίστων ἀξιῶν αὑτὸν ἤχθετο τοῖς ὄνομα καὶ δόξαν ὑπὲρ τοὺς πολλοὺς ἔχουσι. καὶ συνελθόντες εἰς ἄστυ πανταχόθεν ἐξοστρακίζουσι τὸν Ἀριστείδην, ὄνομα τῷ φθόνῳ τῆς δόξης φόβον τυραννίδος θέμενοι.", "st": "Arist. 7.1"}, {"sp": "N", "t": "μοχθηρίας γὰρ οὐκ ἦν κόλασις ὁ ἐξοστρακισμός, ἀλλ’ ἐκαλεῖτο μὲν δι’ εὐπρέπειαν ὄγκου καὶ δυνάμεως βαρυτέρας ταπείνωσις καὶ κόλουσις, ἦν δὲ φθόνου παραμυθία φιλάνθρωπος, εἰς ἀνήκεστον οὐδέν, ἀλλ’ εἰς μετάστασιν ἐτῶν δέκα τὴν πρὸς τὸ λυποῦν ἀπερειδομένου δυσμένειαν. ἐπεὶ δ’ ἤρξαντό τινες ἀνθρώπους ἀγεννεῖς καὶ πονηροὺς ὑποβάλλειν τῷ πράγματι, τελευταῖον ἁπάντων Ὑπέρβολον ἐξοστρακίσαντες ἐπαύσαντο. λέγεται δὲ τὸν Ὑπέρβολον ἐξοστρακισθῆναι διὰ τοιαύτην αἰτίαν. Ἀλκιβιάδης καὶ Νικίας μέγιστον ἐν τῇ πόλει δυνάμενοι διεστασίαζον. ὡς οὖν ὁ δῆμος ἔμελλε φέρειν τὸ ὄστρακον καὶ δῆλος ἦν τὸν ἕτερον γράψων, διαλεχθέντες ἀλλήλοις καὶ τὰς στάσεις ἑκατέρας εἰς ταὐτὸ συναγαγόντες τὸν Ὑπέρβολον ἐξοστρακισθῆναι παρεσκεύασαν. ἐκ δὲ τούτου δυσχεράνας ὁ δῆμος ὡς καθυβρισμένον τὸ πρᾶγμα καὶ προπεπηλακισμένον ἀφῆκε παντελῶς καὶ κατέλυσεν.", "st": "Arist. 7.3"}, {"sp": "N", "t": "ἦν δὲ τοιοῦτον, ὡς τύπῳ φράσαι, τὸ γινόμενον. ὄστρακον λαβὼν ἕκαστος καὶ γράψας ὃν ἐβούλετο μεταστῆσαι τῶν πολιτῶν, ἔφερεν εἰς ἕνα τόπον τῆς ἀγορᾶς περιπεφραγμένον ἐν κύκλῳ δρυφάκτοις. οἱ δ’ ἄρχοντες πρῶτον μὲν διηρίθμουν τὸ σύμπαν ἐν ταὐτῷ τῶν ὀστράκων πλῆθος· εἰ γὰρ ἑξακισχιλίων ἐλάττονες οἱ φέροντες εἶεν, ἀτελὴς ἦν ὁ ἐξοστρακισμός· ἔπειτα τῶν ὀνομάτων ἕκαστον ἰδίᾳ θέντες τὸν ὑπὸ τῶν πλείστων γεγραμμένον ἐξεκήρυττον εἰς ἔτη δέκα, καρπούμενον τὰ αὑτοῦ.", "st": "Arist. 7.5"}, {"sp": "N", "t": "γραφομένων οὖν τότε τῶν ὀστράκων λέγεταί τινα τῶν ἀγραμμάτων καὶ παντελῶς ἀγροίκων ἀναδόντα τῷ Ἀριστείδῃ τὸ ὄστρακον ὡς ἑνὶ τῶν τυχόντων παρακαλεῖν, ὅπως Ἀριστείδην ἐγγράψειε. τοῦ δὲ θαυμάσαντος καὶ πυθομένου, μή τι κακὸν αὐτὸν Ἀριστείδης πεποίηκεν, οὐδέν, εἶπεν, οὐδὲ γιγνώσκω τὸν ἄνθρωπον, ἀλλ’ ἐνοχλοῦμαι πανταχοῦ τὸν Δίκαιον ἀκούων. ταῦτα ἀκούσαντα τὸν Ἀριστείδην ἀποκρίνασθαι μὲν οὐδέν, ἐγγράψαι δὲ τοὔνομα τῷ ὀστράκῳ καὶ ἀποδοῦναι. τῆς δὲ πόλεως ἀπαλλαττόμενος ἤδη, τὰς χεῖρας ἀνατείνας πρὸς τὸν οὐρανὸν εὔξατο τὴν ἐναντίαν, ὡς ἔοικεν, εὐχὴν τῷ Ἀχιλλεῖ, μηδένα καιρὸν Ἀθηναίους καταλαβεῖν, ὃς ἀναγκάσει τὸν δῆμον Ἀριστείδου μνησθῆναι.", "st": "Arist. 7.6"}, {"sp": "N", "t": "τρίτῳ δ’ ἔτει Ξέρξου διὰ Θετταλίας καὶ Βοιωτίας ἐλαύνοντος ἐπὶ τὴν Ἀττικήν, λύσαντες τὸν νόμον ἐψηφίσαντο τοῖς μεθεστῶσι κάθοδον, μάλιστα φοβούμενοι τὸν Ἀριστείδην, μὴ προσθέμενος τοῖς πολεμίοις διαφθείρῃ καὶ μεταστήσῃ πολλοὺς τῶν πολιτῶν πρὸς τὸν βάρβαρον, οὐκ ὀρθῶς στοχαζόμενοι τοῦ ἀνδρός, ὅς γε καὶ πρὸ τοῦ δόγματος τούτου διετέλει προτρέπων καὶ παροξύνων τοὺς Ἕλληνας ἐπὶ τὴν ἐλευθερίαν, καὶ μετὰ τὸ δόγμα τοῦτο, Θεμιστοκλέους στρατηγοῦντος αὐτοκράτορος, πάντα συνέπραττε καὶ συνεβούλευεν, ἐνδοξότατον ἐπὶ σωτηρίᾳ κοινῇ ποιῶν τὸν ἔχθιστον.", "st": "Arist. 8.1"}, {"sp": "N", "t": "ὡς γὰρ ἀπολιπεῖν τὴν Σαλαμῖνα βουλευομένων τῶν περὶ Εὐρυβιάδην αἱ βαρβαρικαὶ τριήρεις νύκτωρ ἀναχθεῖσαι καὶ περιβαλοῦσαι τόν τε πόρον ἐν κύκλῳ καὶ τὰς νήσους κατεῖχον, οὐδενὸς προειδότος τὴν κύκλωσιν ἧκεν ὁ Ἀριστείδης ἀπ’ Αἰγίνης παραβόλως διὰ τῶν πολεμίων νεῶν διεκπλεύσας· καὶ νυκτὸς ἐλθὼν ἐπὶ τὴν σκηνὴν τοῦ Θεμιστοκλέους καὶ καλέσας αὐτὸν ἔξω μόνον. ἡμεῖς, εἶπεν, ὦ Θεμιστόκλεις, εἰ σωφρονοῦμεν, ἤδη τὴν κενὴν καὶ μειρακιώδη στάσιν ἀφέντες ἀρξώμεθα σωτηρίου καὶ καλῆς φιλονεικίας πρὸς ἀλλήλους ἁμιλλώμενοι σῶσαι τὴν Ἑλλάδα, σὺ μὲν ἄρχων καὶ στρατηγῶν, ἐγὼ δ’ ὑπουργῶν καὶ συμβουλεύων, ἐπεὶ καὶ νῦν σε πυνθάνομαι μόνον ἅπτεσθαι τῶν ἀρίστων λογισμῶν, κελεύοντα διαναυμαχεῖν ἐν τοῖς στενοῖς τὴν ταχίστην. καί σοι τῶν συμμάχων ἀντιπραττόντων οἱ πολέμιοι συνεργεῖν ἐοίκασι· τὸ γὰρ ἐν κύκλῳ καὶ κατόπιν ἤδη πέλαγος ἐμπέπλησται νεῶν πολεμίων, ὥστε καὶ τοὺς μὴ θέλοντας ἀνάγκη κατείληφεν ἀγαθοὺς ἄνδρας εἶναι καὶ μάχεσθαι· φυγῆς γὰρ ὁδὸς οὐ λέλειπται. πρὸς ταῦτα ὁ Θεμιστοκλῆς εἶπεν· οὐκ ἂν ἐβουλόμην, ὦ Ἀριστείδη, σὲ κατὰ τοῦτό μου κρείττονα γενέσθαι, πειράσομαι δὲ πρὸς καλὴν ἀρχὴν ἁμιλλώμενος ὑπερβάλλεσθαι τοῖς ἔργοις. ἅμα δ’ αὐτῷ φράσας τὴν ὑφ’ ἑαυτοῦ κατασκευασθεῖσαν ἀπάτην πρὸς τὸν βάρβαρον, παρεκάλει πείθειν τὸν Εὐρυβιάδην καὶ διδάσκειν, ὡς ἀμήχανόν ἐστι σωθῆναι μὴ ναυμαχήσαντας· εἶχε γὰρ αὐτοῦ μᾶλλον πίστιν. ὅθεν ἐν τῷ συλλόγῳ τῶν στρατηγῶν εἰπόντος Κλεοκρίτου τοῦ Κορινθίου πρὸς τὸν Θεμιστοκλέα, μηδ’ Ἀριστείδῃ τὴν γνώμην ἀρέσκειν αὐτοῦ, παρόντα γὰρ σιωπᾶν, ἀντεῖπεν ὁ Ἀριστείδης, ὡς οὐκ ἂν ἐσιώπα μὴ λέγοντος τὰ ἄριστα τοῦ Θεμιστοκλέους· νῦν δ’ ἡσυχίαν ἄγειν οὐ δι’ εὔνοιαν τοῦ ἀνδρός, ἀλλὰ τὴν γνώμην ἐπαινῶν.", "st": "Arist. 8.2"}, {"sp": "N", "t": "οἱ μὲν οὖν ναύαρχοι τῶν Ἑλλήνων ταῦτ’ ἔπραττον. Ἀριστείδης δ’ ὁρῶν τὴν Ψυττάλειαν, ἣ πρὸ τῆς Σαλαμῖνος ἐν τῷ πόρῳ κεῖται νῆσος οὐ μεγάλη, πολεμίων ἀνδρῶν μεστὴν οὖσαν, ἐμβιβάσας εἰς ὑπηρετικὰ τοὺς προθυμοτάτους καὶ μαχιμωτάτους τῶν πολιτῶν προσέμιξε τῇ Ψυτταλείᾳ, καὶ μάχην πρὸς τοὺς βαρβάρους συνάψας ἀπέκτεινε πάντας, πλὴν ὅσοι τῶν ἐπιφανῶν ζῶντες ἥλωσαν. ἐν δὲ τούτοις ἦσαν ἀδελφῆς βασιλέως ὄνομα Σανδαύκης τρεῖς παῖδες, οὓς εὐθὺς ἀπέστειλε πρὸς τὸν Θεμιστοκλέα· καὶ λέγονται κατά τι λόγιον, τοῦ μάντεως Εὐφραντίδου κελεύσαντος, ὠμηστῇ Διονύσῳ καθιερευθῆναι. τὴν δὲ νησῖδα τοῖς ὅπλοις πανταχόθεν ὁ Ἀριστείδης περιστέψας ἐφήδρευε τοῖς ἐκφερομένοις πρὸς αὐτήν, ὡς μήτε τῶν φίλων τινὰ διαφθαρῆναι μήτε τῶν πολεμίων διαφυγεῖν. ὁ γὰρ πλεῖστος ὠθισμὸς τῶν νεῶν καὶ τῆς μάχης τὸ καρτερώτατον ἔοικε περὶ τὸν τόπον ἐκεῖνον γενέσθαι· διὸ καὶ τρόπαιον ἕστηκεν ἐν τῇ Ψυτταλείᾳ.", "st": "Arist. 9.1"}, {"sp": "N", "t": "μετὰ δὲ τὴν μάχην ὁ Θεμιστοκλῆς ἀποπειρώμενος τοῦ Ἀριστείδου καλὸν μὲν εἶναι καὶ τὸ πεπραγμένον αὐτοῖς ἔργον ἔλεγε, κρεῖττον δὲ λείπεσθαι τὸ λαβεῖν ἐν τῇ Εὐρώπῃ τὴν Ἀσίαν, ἀναπλεύσαντας εἰς Ἑλλήσποντον τὴν ταχίστην καὶ τὰ ζεύγματα διακόψαντας. ἐπεὶ δ’ Ἀριστείδης ἀνακραγὼν τοῦτον μὲν ἐκέλευε τὸν λόγον καταβαλεῖν, σκοπεῖν δὲ καὶ ζητεῖν, ὅπως τὴν ταχίστην ἐκβάλωσι τὸν Μῆδον ἐκ τῆς Ἑλλάδος, μὴ κατακλεισθεὶς ἀπορίᾳ φυγῆς μετὰ τοσαύτης δυνάμεως τραπῇ πρὸς ἄμυναν ὑπ’ ἀνάγκης, οὕτω πέμπει πάλιν Ἀρνάκην εὐνοῦχον ὁ Θεμιστοκλῆς ἐκ τῶν αἰχμαλώτων κρύφα, φράσαι τῷ βασιλεῖ κελεύσας, ὅτι πλεῖν ἐπὶ τὰς γεφύρας ὡρμημένους τοὺς Ἕλληνας αὐτὸς ἀποστρέψειε σώζεσθαι βασιλέα βουλόμενος.", "st": "Arist. 9.3"}, {"sp": "N", "t": "ἐκ τούτου Ξέρξης μὲν περίφοβος γενόμενος εὐθὺς ἐπὶ τὸν Ἑλλήσποντον ἠπείγετο, Μαρδόνιος δὲ τοῦ στρατοῦ τὸ δοκιμώτατον ἔχων περὶ τριάκοντα μυριάδας ὑπελείπετο, καὶ φοβερὸς ἦν ἀπ’ ἰσχυρᾶς τῆς περὶ τὸ πεζὸν ἐλπίδος ἀπειλῶν τοῖς Ἕλλησι καὶ γράφων τοιαῦτα· νενικήκατε θαλασσίοις ξύλοις χερσαίους ἀνθρώπους οὐκ ἐπισταμένους κώπην ἐλαύνειν· ἀλλὰ νῦν πλατεῖα μὲν ἡ Θετταλῶν γῆ, καλὸν δὲ τὸ Βοιώτιον πεδίον ἀγαθοῖς ἱππεῦσι καὶ ὁπλίταις ἐναγωνίσασθαι. πρὸς δὲ Ἀθηναίους ἔπεμψεν ἰδίᾳ γράμματα καὶ λόγους παρὰ βασιλέως, τήν τε πόλιν αὐτοῖς ἀναστήσειν ἐπαγγελλομένου καὶ χρήματα πολλὰ δώσειν καὶ τῶν Ἑλλήνων κυρίους καταστήσειν ἐκποδὼν τοῦ πολέμου γενομένους.", "st": "Arist. 10.1"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι πυθόμενοι ταῦτα καὶ δείσαντες ἔπεμψαν Ἀθήναζε πρέσβεις, δεόμενοι τῶν Ἀθηναίων, ὅπως παῖδας μὲν καὶ γυναῖκας εἰς Σπάρτην ἀποστείλωσι, τοῖς δὲ πρεσβυτέροις τροφὰς παρ’ αὐτῶν λαμβάνωσιν· ἰσχυρὰ γὰρ ἦν ἀπορία περὶ τὸν δῆμον ἀπολωλεκότα καὶ τὴν χώραν καὶ τὴν πόλιν. οὐ μὴν ἀλλὰ τῶν πρέσβεων ἀκούσαντες, Ἀριστείδου ψήφισμα γράψαντος, ἀπεκρίναντο θαυμαστὴν ἀπόκρισιν, τοῖς μὲν πολεμίοις συγγνώμην ἔχειν φάσκοντες, εἰ πάντα πλούτου καὶ χρημάτων ὤνια νομίζοιεν, ὧν κρεῖττον οὐδὲν ἴσασιν, ὀργίζεσθαι δὲ Λακεδαιμονίοις, ὅτι τὴν πενίαν καὶ τὴν ἀπορίαν τὴν νῦν παροῦσαν Ἀθηναίοις μόνον ὁρῶσι, τῆς δ’ ἀρετῆς καὶ τῆς φιλοτιμίας ἀμνημονοῦσιν ἐπὶ σιτίοις ὑπὲρ τῆς Ἑλλάδος ἀγωνίζεσθαι παρακαλοῦντες. ταῦτα γράψας Ἀριστείδης καὶ τοὺς πρέσβεις εἰς τὴν ἐκκλησίαν παραγαγών, Λακεδαιμονίοις μὲν ἐκέλευσε φράζειν, ὡς οὐκ ἔστι χρυσοῦ τοσοῦτον πλῆθος οὔθ’ ὑπὲρ γῆν οὔθ’ ὑπὸ γῆν, ὅσον Ἀθηναῖοι δέξαιντο ἂν πρὸ τῆς τῶν Ἑλλήνων ἐλευθερίας. τοῖς δὲ παρὰ Μαρδονίου τὸν ἥλιον δείξας, ἄχρι ἂν οὗτος, ἔφη, ταύτην πορεύηται τὴν πορείαν, Ἀθηναῖοι πολεμήσουσι Πέρσαις ὑπὲρ τῆς δεδῃωμένης χώρας καὶ τῶν ἠσεβημένων καὶ κατακεκαυμένων ἱερῶν. ἔτι δὲ ἀρὰς θέσθαι τοὺς ἱερεῖς ἔγραψεν, εἴ τις ἐπικηρυκεύσαιτο Μήδοις ἢ τὴν συμμαχίαν ἀπολίποι τῶν Ἑλλήνων.", "st": "Arist. 10.3"}, {"sp": "N", "t": "ἐμβαλόντος δὲ Μαρδονίου τὸ δεύτερον εἰς τὴν Ἀττικήν, αὖθις εἰς Σαλαμῖνα διεπέρασαν. Ἀριστείδης δὲ πεμφθεὶς εἰς Λακεδαίμονα τῆς μὲν βραδυτῆτος αὐτοῖς ἐνεκάλει καὶ τῆς ὀλιγωρίας, προεμένοις αὖθις τῷ βαρβάρῳ τὰς Ἀθήνας, ἠξίου δὲ πρὸς τὰ ἔτι σωζόμενα τῆς Ἑλλάδος βοηθεῖν. ταῦτα ἀκούσαντες οἱ Ἔφοροι μεθ’ ἡμέραν μὲν ἐδόκουν παίζειν καὶ ῥᾳθυμεῖν ἑορτάζοντες· ἦν γὰρ αὐτοῖς Ὑακίνθια· νυκτὸς δὲ πεντακισχιλίους Σπαρτιατῶν ἐπιλέξαντες, ὧν ἕκαστος ἑπτὰ περὶ αὑτὸν εἵλωτας εἶχεν, ἐξέπεμψαν οὐκ εἰδότων τῶν Ἀθηναίων. ἐπεὶ δὲ πάλιν ἐγκαλῶν ὁ Ἀριστείδης προσῆλθεν, οἱ δὲ σὺν γέλωτι ληρεῖν αὐτὸν ἔφασκον καὶ καθεύδειν, ἤδη γὰρ ἐν Ὀρεστείῳ τὸν στρατὸν εἶναι πορευόμενον ἐπὶ τοὺς ξένους (ξένους γὰρ ἐκάλουν τοὺς Πέρσασς), οὐ κατὰ καιρὸν ἔφη παίζειν αὐτοὺς ὁ Ἀριστείδης, ἀντὶ τῶν πολεμίων τοὺς φίλους ἐξαπατῶντας. ταῦθ’ οἱ περὶ τὸν Ἰδομενέα λέγουσιν. ἐν δὲ τῷ ψηφίσματι τοῦ Ἀριστείδου πρεσβευτὴς οὐκ αὐτός, ἀλλὰ Κίμων καὶ Ξάνθιππος καὶ Μυρωνίδης φέρονται.", "st": "Arist. 10.7"}, {"sp": "N", "t": "χειροτονηθεὶς δὲ στρατηγὸς αὐτοκράτωρ ἐπὶ τὴν μάχην, καὶ τῶν Ἀθηναίων ὀκτακισχιλίους ὁπλίτας ἀναλαβών, ἧκεν εἰς Πλαταιάς. ἐκεῖ δὲ καὶ Παυσανίας ὁ τοῦ σύμπαντος ἡγούμενος Ἑλληνικοῦ συνέμιξεν ἔχων τοὺς Σπαρτιάτας, καὶ τῶν ἄλλων Ἑλλήνων ἐπέρρει τὸ πλῆθος. τῶν δὲ βαρβάρων τὸ μὲν ὅλον τῆς στρατοπεδείας παρὰ τὸν Ἀσωπὸν ποταμὸν παρεκτεταμένης οὐδεὶς ἦν ὄρος διὰ τὸ μέγεθος, περὶ δὲ τὰς ἀποσκευὰς καὶ τὰ κυριώτατα τεῖχος περιεφράξαντο τετράγωνον, οὗ τῶν πλευρῶν ἑκάστη μῆκος ἦν δέκα σταδίων.", "st": "Arist. 11.1"}, {"sp": "N", "t": "Παυσανίᾳ μὲν οὖν καὶ τοῖς Ἕλλησι κοινῇ Τισαμενὸς ὁ Ἠλεῖος ἐμαντεύσατο, καὶ προεῖπε νίκην ἀμυνομένοις καὶ μὴ προεπιχειροῦσιν· Ἀριστείδου δὲ πέμψαντος εἰς Δελφοὺς ἀνεῖλεν ὁ θεὸς Ἀθηναίους καθυπερτέρους ἔσεσθαι τῶν ἐναντίων εὐχομένους τῷ Διῒ καὶ τῇ Ἥρα τῇ Κιθαιρωνίᾳ καὶ Πανὶ καὶ νύμφαις Σφραγίτισι, καὶ θύοντας ἥρωσιν Ἀνδροκράτει, Λεύκωνι, Πεισάνδρῳ, Δαμοκράτει, Ὑψίωνι, Ἀκταίωνι, Πολϋΐδῳ, καὶ τὸν κίνδυνον ἐν γᾷ ἰδίᾳ ποιουμένους ἐν τῷ πεδίῳ τᾶς Δάματρος τᾶς Ἐλευσινίας καὶ τᾶς Κόρας. οὗτος ὁ χρησμὸς ἀνενεχθεὶς ἀπορίαν τῷ Ἀριστείδῃ παρεῖχεν. οἱ μὲν γὰρ ἥρωες, οἷς ἐκέλευε θύειν, ἀρχηγέται Πλαταιέων ἦσαν, καὶ τὸ τῶν Σφραγιτίδων νυμφῶν ἄντρον ἐν μιᾷ κορυφῇ τοῦ Κιθαιρῶνός ἐστιν, εἰς δυσμὰς ἡλίου θερινὰς τετραμμένον, ἐν ᾧ καὶ μαντεῖον ἦν πρότερον, ὥς φασι, καὶ πολλοὶ κατείχοντο τῶν ἐπιχωρίων, οὓς νυμφολήπτους προσηγόρευον. τὸ δὲ τῆς Ἐλευσινίας Δήμητρος πεδίον, καὶ τὸ τὴν μάχην ἐν ἰδίᾳ χώρᾳ ποιουμένοις τοῖς Ἀθηναίοις νίκην δίδοσθαι, πάλιν εἰς τὴν Ἀττικὴν ἀνεκαλεῖτο καὶ μεθίστη τὸν πόλεμον.", "st": "Arist. 11.3"}, {"sp": "N", "t": "ἔνθα τῶν Πλαταιέων ὁ στρατηγὸς Ἀρίμνηστος ἔδοξε κατὰ τοὺς ὕπνους ὑπὸ τοῦ Διὸς τοῦ Σωτῆρος ἐπερωτώμενον αὑτόν, ὅ τι δὴ πράττειν δέδοκται τοῖς Ἕλλησιν, εἰπεῖν, αὔριον εἰς Ἐλευσῖνα τὴν στρατιὰν ἀπάξομεν, ὦ δέσποτα, καὶ διαμαχούμεθα τοῖς βαρβάροις ἐκεῖ κατὰ τὸ πυθόχρηστον. τὸν οὖν θεὸν φάναι διαμαρτάνειν αὐτοὺς τοῦ παντός· αὐτόθι γὰρ εἶναι περὶ τὴν Πλαταϊκὴν τὰ πυθόχρηστα καὶ ζητοῦντας ἀνευρήσειν. τούτων ἐναργῶς τῷ Ἀριμνήστῳ φανέντων ἐξεγρόμενος τάχιστα μετεπέμψατο τοὺς ἐμπειροτάτους καὶ πρεσβυτάτους τῶν πολιτῶν, μεθ’ ὧν διαλεγόμενος καὶ συνδιαπορῶν εὗρεν, ὅτι τῶν Ὑσιῶν πλησίον ὑπὸ τὸν Κιθαιρῶνα ναός ἐστιν ἀρχαῖος πάνυ Δήμητρος Ἐλευσινίας καὶ Κόρης προσαγορευόμενος. εὐθὺς οὖν παραλαβὼν τὸν Ἀριστείδην ἦγεν ἐπὶ τὸν τόπον, εὐφυέστατον ὄντα παρατάξαι φάλαγγα πεζικὴν ἱπποκρατουμένοις, διὰ τὰς ὑπωρείας τοῦ Κιθαιρῶνος ἄφιππα ποιούσας τὰ καταλήγοντα καὶ συγκυροῦντα τοῦ πεδίου πρὸς τὸ ἱερόν. αὐτοῦ δ’ ἦν καὶ τὸ τοῦ Ἀνδροκράτους ἡρῷον ἐγγύς, ἄλσει πυκνῶν καὶ συσκίων δένδρων περιεχόμενον. ὅπως δὲ μηδὲν ἐλλιπὲς ἔχῃ πρὸς τὴν ἐλπίδα τῆς νίκης ὁ χρησμός, ἔδοξε τοῖς Πλαταιεῦσιν, Ἀριμνήστου γνώμην εἰπόντος, ἀνελεῖν τὰ πρὸς τὴν Ἀττικὴν ὅρια τῆς Πλαταιΐδος καὶ τὴν χώραν ἐπιδοῦναι τοῖς Ἀθηναίοις ὑπὲρ τῆς Ἑλλάδος ἐν οἰκείᾳ κατὰ τὸν χρησμὸν ἐναγωνίσασθαι.", "st": "Arist. 11.6"}, {"sp": "N", "t": "ταύτην μὲν οὖν τὴν φιλοτιμίαν τῶν Πλαταιέων οὕτω συνέβη περιβόητον γενέσθαι, ὥστε καὶ Ἀλέξανδρον ἤδη βασιλεύοντα τῆς Ἀσίας ὕστερον πολλοῖς ἔτεσι τειχίζοντα τὰς Πλαταιὰς ἀνειπεῖν Ὀλυμπιάσιν ὑπὸ κήρυκος, ὅτι ταύτην ὁ βασιλεὺς ἀποδίδωσι Πλαταιεῦσι τῆς ἀνδραγαθίας καὶ τῆς μεγαλοψυχίας χάριν, ἐπειδὴ τοῖς Ἕλλησιν ἐν τῷ Μηδικῷ πολέμῳ τὴν χώραν ἐπέδωκαν καὶ παρέσχον αὑτοὺς προθυμοτάτους.", "st": "Arist. 11.9"}, {"sp": "N", "t": "Ἀθηναίοις δὲ Τεγεᾶται περὶ τάξεως ἐρίσαντες ἠξίουν, ὥσπερ ἀεί, Λακεδαιμονίων τὸ δεξιὸν ἐχόντων κέρας, αὐτοὶ τὸ εὐώνυμον ἔχειν, πολλὰ τοὺς αὑτῶν προγόνους ἐγκωμιάζοντες. ἀγανακτούντων δὲ τῶν Ἀθηναίων παρελθὼν ὁ Ἀριστείδης εἶπε· Τεγεάταις μὲν ἀντειπεῖν περὶ εὐγενείας καὶ ἀνδραγαθίας ὁ παρὼν καιρὸς οὐ δίδωσι, πρὸς δ’ ὑμᾶς, ὦ Σπαρτιᾶται, καὶ τοὺς ἄλλους Ἕλληνας λέγομεν, ὅτι τὴν ἀρετὴν οὐκ ἀφαιρεῖται τόπος οὐδὲ δίδωσιν· ἣν δ’ ἂν ὑμεῖς ἡμῖν τάξιν ἀποδῶτε πειρασόμεθα κοσμοῦντες καὶ φυλάττοντες μὴ καταισχύνειν τοὺς προηγωνισμένους ἀγῶνας. ἥκομεν γὰρ οὐ τοῖς συμμάχοις στασιάσοντες, ἀλλὰ μαχούμενοι τοῖς πολεμίοις, οὐδ’ ἐπαινεσόμενοι τοὺς πατέρας, ἀλλ’ αὑτοὺς ἄνδρας ἀγαθοὺς τῇ Ἑλλάδι παρέξοντες· ὡς οὗτος ὁ ἀγὼν δείξει καὶ πόλιν καὶ ἄρχοντα καὶ ἰδιώτην ὁπόσου τοῖς Ἕλλησιν ἄξιός ἐστι. ταῦτ’ ἀκούσαντες οἱ σύνεδροι καὶ ἡγεμόνες ἀπεδέξαντο τοὺς Ἀθηναίους καὶ θάτερον αὐτοῖς κέρας ἀπέδοσαν.", "st": "Arist. 12.1"}, {"sp": "N", "t": "οὔσης δὲ μετεώρου τῆς Ἑλλάδος καὶ μάλιστα τοῖς Ἀθηναίοις τῶν πραγμάτων ἐπισφαλῶς ἐχόντων, ἄνδρες ἐξ οἴκων ἐπιφανῶν καὶ χρημάτων μεγάλων πένητες ὑπὸ τοῦ πολέμου γεγονότες καὶ πᾶσαν ἅμα τῷ πλούτῳ τὴν ἐν τῇ πόλει δύναμιν αὑτῶν καὶ δόξαν οἰχομένην ὁρῶντες, ἑτέρων τιμωμένων καὶ ἀρχόντων, συνῆλθον εἰς οἰκίαν τινὰ τῶν ἐν Πλαταιαῖς κρύφα καὶ συνωμόσαντο καταλύσειν τὸν δῆμον· εἰ δὲ μὴ προχωροίη, λυμανεῖσθαι τὰ πράγματα καὶ τοῖς βαρβάροις προδώσειν.", "st": "Arist. 13.1"}, {"sp": "N", "t": "πραττομένων δὲ τούτων ἐν τῷ στρατοπέδῳ καὶ συχνῶν ἤδη διεφθαρμένων, αἰσθόμενος ὁ Ἀριστείδης καὶ φοβηθεὶς τὸν καιρόν, ἔγνω μήτ’ ἐᾶν ἀμελούμενον τὸ πρᾶγμα μήθ’ ἅπαν ἐκκαλύπτειν, ἀγνοούμενον εἰς ὅσον ἐκβήσεται πλῆθος ὁ ἔλεγχος τὸν τοῦ δικαίου ζητῶν ὅρον ἀντὶ τοῦ συμφέροντος. ὀκτὼ δή τινας ἐκ πολλῶν συνέλαβε· καὶ τούτων δύο μέν, οἷς πρώτοις ἡ κρίσις προεγράφη, οἳ καὶ πλείστην αἰτίαν εἶχον, Αἰσχίνης Λαμπτρεὺς καὶ Ἀγησίας Ἀχαρνεύς, ᾤχοντο φεύγοντες ἐκ τοῦ στρατοπέδου, τοὺς δ’ ἄλλους ἀφῆκε, θαρσῆσαι διδοὺς καὶ μεταγνῶναι τοῖς ἔτι λανθάνειν οἰομένοις, ὑπειπὼν ὡς μέγα δικαστήριον ἔχουσι τὸν πόλεμον ἀπολύσασθαι τὰς αἰτίας ὀρθῶς καὶ δικαίως τῇ πατρίδι βουλευόμενοι.", "st": "Arist. 13.2"}, {"sp": "N", "t": "μετὰ ταῦτα Μαρδόνιος, ᾧ πλεῖστον ἐδόκει διαφέρειν, τῶν Ἑλλήνων ἀπεπειρᾶτο, τὴν ἵππον ἀθρόαν αὐτοῖς ἐφεὶς καθεζομένοις ὑπὸ τὸν πρόποδα τοῦ Κιθαιρῶνος ἐν χωρίοις ὀχυροῖς καὶ πετρώδεσι πλὴν Μεγαρέων. οὗτοι δὲ τρισχίλιοι τὸ πλῆθος ὄντες ἐν τοῖς ἐπιπέδοις μᾶλλον ἐστρατοπεδεύοντο. διὸ καὶ κακῶς ἔπασχον ὑπὸ τῆς ἵππου ῥυείσης ἐπ’ αὐτοὺς καὶ προσβολὰς ἐχούσης πανταχόθεν. ἔπεμπον οὖν ἄγγελον κατὰ τάχος πρὸς Παυσανίαν βοηθεῖν κελεύοντες, ὡς οὐ δυνάμενοι καθ’ αὑτοὺς ὑποστῆναι τὸ τῶν βαρβάρων πλῆθος. ταῦτα Παυσανίας ἀκούων, ἤδη δὲ καὶ καθορῶν ἀποκεκρυμμένον ἀκοντισμάτων καὶ τοξευμάτων πλήθει τὸ στρατόπεδον τῶν Μεγαρέων καὶ συνεσταλμένους αὐτοὺς εἰς ὀλίγον, αὐτὸς μὲν ἀμήχανος ἦν πρὸς ἱππότας ἀμύνειν ὁπλιτικῇ φάλαγγι καὶ βαρείᾳ τῇ Σπαρτιατῶν, τοῖς δ’ ἄλλοις στρατηγοῖς καὶ λοχαγοῖς τῶν Ἑλλήνων περὶ αὐτὸν οὖσι προὔθετο ζῆλον ἀρετῆς καὶ φιλοτιμίας, εἰ δή τινες ἑκόντες ἀναδέξαιντο προαγωνίσασθαι καὶ βοηθῆσαι τοῖς Μεγαρεῦσι. τῶν δ’ ἄλλων ὀκνούντων Ἀριστείδης ἀναδεξάμενος ὑπὲρ τῶν Ἀθηναίων τὸ ἔργον ἀποστέλλει τὸν προθυμότατον τῶν λοχαγῶν Ὀλυμπιόδωρον, ἔχοντα τοὺς ὑπ’ αὐτῷ τεταγμένους λογάδας τριακοσίους καὶ τοξότας ἀναμεμιγμένους σὺν αὐτοῖς.", "st": "Arist. 14.1"}, {"sp": "N", "t": "τούτων δὲ ὀξέως διασκευασαμένων καὶ προσφερομένων δρόμῳ, Μασίστιος ὁ τῶν βαρβάρων ἵππαρχος, ἀνὴρ ἀλκῇ τε θαυμαστὸς μεγέθει τε καὶ κάλλει σώματος περιττός, ὡς κατεῖδεν, ἐναντίον ἐπιστρέψας τὸν ἵππον εἰς αὐτοὺς ἤλαυνε. τῶν δ’ ἀνασχομένων καὶ συμβαλόντων ἦν ἀγὼν καρτερός, ὡς πεῖραν ἐν τούτῳ τοῦ παντὸς λαμβανόντων. ἐπεὶ δὲ τοξευθεὶς ὁ ἵππος τὸν Μασίστιον ἀπέρριψε καὶ πεσὼν ὑπὸ βάρους τῶν ὅπλων αὐτός τε δυσκίνητος ἦν ἀναφέρειν καὶ τοῖς Ἀθηναίοις ἐπικειμένοις καὶ παίουσι δυσμεταχείριστος, οὐ μόνον στέρνα καὶ κεφαλήν, ἀλλὰ καὶ τὰ γυῖα χρυσῷ καὶ χαλκῷ καὶ σιδήρῳ καταπεφραγμένος, τοῦτον μὲν ᾗ τὸ κράνος ὑπέφαινε τὸν ὀφθαλμὸν ἀκοντίου στύρακι παίων τις ἀνεῖλεν, οἱ δ’ ἄλλοι Πέρσαι προέμενοι τὸν νεκρὸν ἔφευγον. ἐγνώσθη δὲ τοῦ κατορθώματος τὸ μέγεθος τοῖς Ἕλλησιν οὐκ ἀπὸ τῶν νεκρῶν τοῦ πλήθους, ὀλίγοι γὰρ οἱ πεσόντες ἦσαν, ἀλλὰ τῷ πένθει τῶν βαρβάρων. καὶ γὰρ ἑαυτοὺς ἔκειραν ἐπὶ τῷ Μασιστίῳ καὶ ἵππους καὶ ἡμιόνους, οἰμωγῆς τε καὶ κλαυθμοῦ τὸ πεδίον ἐνεπίμπλασαν, ὡς ἄνδρα πολὺ πρῶτον ἀρετῇ καὶ δυνάμει μετά γε Μαρδόνιον αὐτὸν ἀποβαλόντες.", "st": "Arist. 14.4"}, {"sp": "N", "t": "μετὰ δὲ τὴν ἱππομαχίαν ἀμφότεροι μάχης ἔσχοντο χρόνον πολύν· ἀμυνομένοις γὰρ οἱ μάντεις νίκην προὔφαινον ἐκ τῶν ἱερῶν ὁμοίως καὶ τοῖς Πέρσαις καὶ τοῖς Ἕλλησιν, εἰ δ’ ἐπιχειροῖεν, ἧτταν. ἔπειτα Μαρδόνιος, ὡς αὐτῷ μὲν ἡμερῶν ὀλίγων τὰ ἐπιτήδεια περιῆν, οἱ δ’ Ἕλληνες ἀεί τινων ἐπιρρεόντων πλείονες ἐγίνοντο, δυσανασχετῶν ἔγνω μηκέτι μένειν, ἀλλὰ διαβὰς ἅμα φάει τὸν Ἀσωπὸν ἐπιθέσθαι τοῖς Ἕλλησιν ἀπροσδοκήτως· καὶ παράγγελμα τοῖς ἡγεμόσιν ἑσπέρας ἔδωκε.", "st": "Arist. 15.1"}, {"sp": "N", "t": "μεσούσης δὲ μάλιστα τῆς νυκτὸς ἀνὴρ ἵππον ἔχων ἀτρέμα προσεμίγνυε τῷ στρατοπέδῳ τῶν Ἑλλήνων· ἐντυχὼν δὲ ταῖς φυλακαῖς ἐκέλευεν αὐτῷ προσελθεῖν Ἀριστείδην τὸν Ἀθηναῖον. ὑπακούσαντος δὲ ταχέως ἔφησεν· εἰμὶ μὲν Ἀλέξανδρος ὁ Μακεδών, ἥκω δὲ κινδύνων τὸν μέγιστον εὐνοίᾳ τῇ πρὸς ὑμᾶς αἰρόμενος, ὡς μὴ τὸ αἰφνίδιον ἐκπλήξειεν ὑμᾶς χεῖρον ἀγωνίσασθαι. μαχεῖται γὰρ ὑμῖν Μαρδόνιος αὔριον, οὐχ ὑπ’ ἐλπίδος χρηστῆς οὐδὲ θάρσους, ἀλλ’ ἀπορίας τῶν παρόντων, ἐπεὶ καὶ μάντεις ἐκεῖνον ἀπαισίοις ἱεροῖς καὶ λογίοις χρησμῶν εἴργουσι μάχης, καὶ τὸν στρατὸν ἔχει δυσθυμία πολλὴ καὶ κατάπληξις. ἀλλ’ ἀνάγκη τολμῶντα πειρᾶσθαι τῆς τύχης ἢ τὴν ἐσχάτην ὑπομένειν ἀπορίαν καθεζόμενον. ταῦτα φράσας ὁ Ἀλέξανδρος ἐδεῖτο τὸν Ἀριστείδην αὐτὸν εἰδέναι καὶ μνημονεύειν, ἑτέρῳ δὲ μὴ κατειπεῖν. ὁ δ’ οὐ καλῶς ἔχειν ἔφη ταῦτα Παυσανίαν ἀποκρύψασθαι, ἐκείνῳ γὰρ ἀνακεῖσθαι τὴν ἡγεμονίαν, πρὸς δὲ τοὺς ἄλλους ἄρρητα πρὸ τῆς μάχης ἔδοξεν ἔσεσθαι, νικώσης δὲ τῆς Ἑλλάδος οὐδένα τὴν Ἀλεξάνδρου προθυμίαν καὶ ἀρετὴν ἀγνοήσειν. λεχθέντων δὲ τούτων ὅ τε βασιλεὺς τῶν Μακεδόνων ἀπήλαυνεν ὀπίσω πάλιν, ὅ τε Ἀριστείδης ἀφικόμενος ἐπὶ τὴν σκηνὴν τοῦ Παυσανίου διηγεῖτο τοὺς λόγους· καὶ μετεπέμποντο τοὺς ἄλλους ἡγεμόνας καὶ παρήγγελλον ἐν κόσμῳ τὸν στρατὸν ἔχειν, ὡς μάχης ἐσομένης.", "st": "Arist. 15.2"}, {"sp": "N", "t": "ἐν τούτῳ δ’, ὡς Ἡρόδοτος ἱστορεῖ, Παυσανίας Ἀριστείδῃ προσέφερε λόγον, ἀξιῶν τοὺς Ἀθηναίους ἐπὶ τὸ δεξιὸν μετατάξαι καὶ κατὰ τοὺς Πέρσας ἀντιταχθῆναι, βέλτιον γὰρ ἀγωνιεῖσθαι τῆς τε μάχης ἐμπείρους γεγονότας καὶ τῷ προνενικηκέναι θαρροῦντας, αὑτῷ δὲ παραδοῦναι τὸ εὐώνυμον, ὅπου τῶν Ἑλλήνων οἱ μηδίζοντες ἐπιβάλλειν ἔμελλον.", "st": "Arist. 16.1"}, {"sp": "N", "t": "οἱ μὲν οὖν ἄλλοι στρατηγοὶ τῶν Ἀθηναίων ἀγνώμονα καὶ φορτικὸν ἡγοῦντο τὸν Παυσανίαν, εἰ τὴν ἄλλην ἐῶν τάξιν ἐν χώρᾳ μόνους ἄνω καὶ κάτω μεταφέρει σφᾶς ὥσπερ εἵλωτας, κατὰ τὸ μαχιμώτατον προβαλλόμενος· ὁ δ’ Ἀριστείδης διαμαρτάνειν αὐτοὺς ἔφασκε τοῦ παντός, εἰ πρώην μὲν ὑπὲρ τοῦ τὸ εὐώνυμον κέρας ἔχειν διεφιλοτιμοῦντο Τεγεάταις καὶ προκριθέντες ἐσεμνύνοντο, νῦν δέ, Λακεδαιμονίων ἑκουσίως αὐτοῖς ἐξισταμένων τοῦ δεξιοῦ καὶ τρόπον τινὰ τὴν ἡγεμονίαν παραδιδόντων, οὔτε τὴν δόξαν ἀγαπῶσιν οὔτε κέρδος ἡγοῦνται τὸ μὴ πρὸς ὁμοφύλους καὶ συγγενεῖς, ἀλλὰ βαρβάρους καὶ φύσει πολεμίους ἀγωνίσασθαι. ἐκ τούτου πάνυ προθύμως οἱ Ἀθηναῖοι διημείβοντο τοῖς Σπαρτιάταις τὴν τάξιν· καὶ λόγος ἐχώρει δι’ αὐτῶν πολὺς ἀλλήλοις παρεγγυώντων, ὡς οὔτε ὅπλα βελτίω λαβόντες οὔτε ψυχὰς ἀμείνους οἱ πολέμιοι τῶν ἐν Μαραθῶνι προσίασιν, ἀλλὰ ταὐτὰ μὲν ἐκείνοις τόξα, ταὐτὰ δ’ ἐσθῆτος ποικίλματα καὶ χρυσὸς ἐπὶ σώμασι μαλακοῖς καὶ ψυχαῖς ἀνάνδροις· ἡμῖν δ’ ὅμοια μὲν ὅπλα καὶ σώματα, μεῖζον δὲ ταῖς νίκαις τὸ θάρσος, ὁ δ’ ἀγὼν οὐχ ὑπὲρ χώρας καὶ πόλεως μόνον, ὡς ἐκείνοις, ἀλλ’ ὑπὲρ τῶν ἐν Μαραθῶνι καὶ Σαλαμῖνι τροπαίων, ὡς μηδ’ ἐκεῖνα Μιλτιάδου δοκῇ καὶ τύχης, ἀλλὰ Ἀθηναίων.", "st": "Arist. 16.2"}, {"sp": "N", "t": "οὗτοι μὲν οὖν σπεύδοντες ἐν ἀμείψει τῶν τάξεων ἦσαν· αἰσθόμενοι δὲ Θηβαῖοι παρ’ αὐτομόλων Μαρδονίῳ φράζουσι. κἀκεῖνος εὐθύς, εἴτε δεδιὼς τοὺς Ἀθηναίους, εἴτε τοῖς Λακεδαιμονίοις συμπεσεῖν φιλοτιμούμενος, ἀντιπαρεξῆγε τοὺς Πέρσας ἐπὶ τὸ δεξιόν, τοὺς δὲ Ἕλληνας ἐκέλευε τοὺς σὺν αὐτῷ κατὰ τοὺς Ἀθηναίους ἵστασθαι. γενομένης δὲ τῆς μετακοσμήσεως καταφανοῦς ὅ τε Παυσανίας ἀποτραπεὶς αὖθις ἐπὶ τοῦ δεξιοῦ κατέστη, καὶ Μαρδόνιος, ὥσπερ εἶχεν ἐξ ἀρχῆς, ἀνέλαβε τὸ εὐώνυμον κατὰ τοὺς Λακεδαιμονίους γενόμενος, ἥ τε ἡμέρα διεξῆλθεν ἀργή. καὶ τοῖς Ἕλλησι βουλευομένοις ἔδοξε πορρωτέρω μεταστρατοπεδεῦσαι καὶ καταλαβεῖν εὔυδρον χωρίον, ἐπεὶ τὰ πλησίον νάματα καθύβριστο καὶ διέφθαρτο τῶν βαρβάρων ἱπποκρατούντων.", "st": "Arist. 16.5"}, {"sp": "N", "t": "ἐπελθούσης δὲ νυκτὸς καὶ τῶν στρατηγῶν ἀγόντων ἐπὶ τὴν ἀποδεδειγμένην στρατοπεδείαν οὐ πάνυ πρόθυμον ἦν ἕπεσθαι καὶ συμμένειν τὸ πλῆθος, ἀλλ’ ὡς ἀνέστησαν ἐκ τῶν πρώτων ἐρυμάτων ἐφέροντο πρὸς τὴν πόλιν τῶν Πλαταιέων οἱ πολλοί, καὶ θόρυβος ἦν ἐκεῖ διασκιδναμένων καὶ κατασκηνούντων ἀτάκτως. Λακεδαιμονίοις δὲ συνέβαινεν ἄκουσι μόνοις ἀπολείπεσθαι τῶν ἄλλων· Ἀμομφάρετος γάρ, ἀνὴρ θυμοειδὴς καὶ φιλοκίνδυνος, ἔκπαλαι πρὸς τὴν μάχην σπαργῶν καὶ βαρυνόμενος τὰς πολλὰς ἀναβολὰς καὶ μελλήσεις, τότε δὴ παντάπασι τὴν μετανάστασιν φυγὴν ἀποκαλῶν καὶ ἀπόδρασιν, οὐκ ἔφη λείψειν τὴν τάξιν, ἀλλ’ αὐτόθι μένων μετὰ τῶν ἑαυτοῦ λοχιτῶν ὑποστήσεσθαι Μαρδόνιον. ὡς δὲ Παυσανίας ἐπελθὼν ἔλεγε ταῦτα πράττειν ἐψηφισμένα καὶ δεδογμένα τοῖς Ἕλλησιν, ἀράμενος ταῖν χεροῖν πέτρον μέγαν ὁ Ἀμομφάρετος καὶ καταβαλὼν πρὸ τῶν ποδῶν τοῦ Παυσανίου ταύτην ἔφη ψῆφον αὐτὸς περὶ τῆς μάχης τίθεσθαι, τὰ δὲ τῶν ἄλλων δειλὰ βουλεύματα καὶ δόγματα χαίρειν ἐᾶν. ἀπορούμενος δὲ Παυσανίας τῷ παρόντι πρὸς μὲν τοὺς Ἀθηναίους ἔπεμψεν ἀπιόντας ἤδη, περιμεῖναι δεόμενος καὶ κοινῇ βαδίζειν, αὐτὸς δὲ τὴν ἄλλην δύναμιν ἦγε πρὸς τὰς Πλαταιὰς ὡς ἀναστήσων τὸν Ἀμομφάρετον.", "st": "Arist. 17.1"}, {"sp": "N", "t": "ἐν τούτῳ δὲ κατελάμβανεν ἡμέρα, καὶ Μαρδόνιος (οὐ γὰρ ἔλαθον τὴν στρατοπεδείαν ἐκλελοιπότες οἱ Ἕλληνες) ἔχων συντεταγμένην τὴν δύναμιν ἐπεφέρετο τοῖς Λακεδαιμονίοις βοῇ πολλῇ καὶ πατάγῳ τῶν βαρβάρων, ὡς οὐ μάχης ἐσομένης, ἀλλὰ φεύγοντας ἀναρπασομένων τοὺς Ἕλληνας. ὃ μικρᾶς ῥοπῆς ἐδέησε γενέσθαι. κατιδὼν γὰρ τὸ γινόμενον ὁ Παυσανίας ἔσχετο μὲν τῆς πορείας καὶ τὴν ἐπὶ μάχῃ τάξιν ἐκέλευσε λαμβάνειν ἕκαστον, ἔλαθε δ’ αὐτόν, εἴθ’ ὑπὸ τῆς πρὸς τὸν Ἀμομφάρετον ὀργῆς εἴτε τῷ τάχει θορυβηθέντα τῶν πολεμίων, σύνθημα μὴ δοῦναι τοῖς Ἕλλησιν. ὅθεν οὔτ’ εὐθὺς οὔτ’ ἀθρόοι, κατ’ ὀλίγους δὲ καὶ σποράδην, ἤδη τῆς μάχης ἐν χερσὶν οὔσης, προσεβοήθουν.", "st": "Arist. 17.4"}, {"sp": "N", "t": "ὡς δὲ θυόμενος οὐκ ἐκαλλιέρει, προσέταξε τοῖς Λακεδαιμονίοις τὰς ἀσπίδας πρὸ τῶν ποδῶν θεμένους ἀτρέμα καθέζεσθαι καὶ προσέχειν αὐτῷ, μηδένα τῶν πολεμίων ἀμυνομένους, αὐτὸς δὲ πάλιν ἐσφαγιάζετο. καὶ προσέπιπτον οἱ ἱππεῖς· ἤδη δὲ καὶ βέλος ἐξικνεῖτο καί τις ἐπέπληκτο τῶν Σπαρτιατῶν. ἐν τούτῳ δὲ καὶ Καλλικράτης, ὃν ἰδέᾳ τε κάλλιστον Ἑλλήνων καὶ σώματι μέγιστον ἐν ἐκείνῳ τῷ στρατῷ γενέσθαι λέγουσι, τοξευθεὶς καὶ θνήσκων οὐκ ἔφη τὸν θάνατον ὀδύρεσθαι, καὶ γὰρ ἐλθεῖν οἴκοθεν ὑπὲρ τῆς Ἑλλάδος ἀποθανούμενος, ἀλλ’ ὅτι θνήσκει τῇ χειρὶ μὴ χρησάμενος. ἦν οὖν τὸ μὲν πάθος δεινόν, ἡ δ’ ἐγκράτεια θαυμαστὴ τῶν ἀνδρῶν. οὐ γὰρ ἠμύνοντο τοὺς πολεμίους ἐπιβαίνοντας, ἀλλὰ τὸν παρὰ τοῦ θεοῦ καὶ τοῦ στρατηγοῦ καιρὸν ἀναμένοντες ἠνείχοντο βαλλόμενοι καὶ πίπτοντες ἐν ταῖς τάξεσιν.", "st": "Arist. 17.6"}, {"sp": "N", "t": "ἔνιοι δέ φασι τῷ Παυσανίᾳ μικρὸν ἔξω τῆς παρατάξεως θύοντι καὶ κατευχομένῳ τῶν Λυδῶν τινας ἄφνω προσπεσόντας ἁρπάζειν καὶ διαρρίπτειν τὰ περὶ τὴν θυσίαν, τὸν δὲ Παυσανίαν καὶ τοὺς περὶ αὐτὸν οὐκ ἔχοντας ὅπλα ῥάβδοις καὶ μάστιξι παίειν· διὸ καὶ νῦν ἐκείνης τῆς ἐπιδρομῆς μιμήματα τὰς περὶ τὸν βωμὸν ἐν Σπάρτῃ πληγὰς τῶν ἐφήβων καὶ τὴν μετὰ ταῦτα τῶν Λυδῶν πομπὴν συντελεῖσθαι.", "st": "Arist. 17.8"}, {"sp": "N", "t": "δυσφορῶν οὖν ὁ Παυσανίας τοῖς παροῦσιν, ἄλλα τοῦ μάντεως ἐπ’ ἄλλοις ἱερεῖα καταβάλλοντος, τρέπεται πρὸς τὸ Ἡραῖον τῇ ὄψει δεδακρυμένος, καὶ τὰς χεῖρας ἀνασχὼν εὔξατο Κιθαιρωνίᾳ Ἥρᾳ καὶ θεοῖς ἄλλοις, οἳ Πλαταιΐδα γῆν ἔχουσιν, εἰ μὴ πέπρωται τοῖς Ἕλλησι νικᾶν, ἀλλὰ δράσαντάς γέ τι παθεῖν καὶ δείξαντας ἔργῳ τοῖς πολεμίοις, ὡς ἐπ’ ἄνδρας ἀγαθοὺς καὶ μάχεσθαι μεμαθηκότας ἐστράτευσαν. ταῦτα τοῦ Παυσανίου θεοκλυτοῦντος ἅμα ταῖς εὐχαῖς ἐφάνη τὰ ἱερὰ καὶ νίκην ὁ μάντις ἔφραζε. καὶ δοθέντος εἰς ἅπαντας τοῦ παραγγέλματος καθίστασθαι πρὸς τοὺς πολεμίους, ἥ τε φάλαγξ ὄψιν ἔσχεν αἰφνιδίως ἑνὸς ζῴου θυμοειδοῦς πρὸς ἀλκὴν τρεπομένου καὶ φρίξαντος, τοῖς τε βαρβάροις τότε παρέστη λογισμός, ὡς πρὸς ἄνδρας ὁ ἀγὼν ἔσοιτο μαχουμένους ἄχρι θανάτου. διὸ καὶ προθέμενοι πολλὰ τῶν γέρρων ἐτόξευον εἰς τοὺς Λακεδαιμονίους. οἱ δὲ τηροῦντες ἅμα τὸν συνασπισμὸν ἐπέβαινον, καὶ προσπεσόντες ἐξεώθουν τὰ γέρρα, καὶ τοῖς δόρασι τύπτοντες πρόσωπα καὶ στέρνα τῶν Περσῶν πολλοὺς κατέβαλλον, οὐκ ἀπράκτως οὐδὲ ἀθύμως πίπτοντας. καὶ γὰρ ἀντιλαμβανόμενοι τῶν δοράτων ταῖς χερσὶ γυμναῖς συνέθραυον τὰ πλεῖστα, καὶ πρὸς τὰς ξιφουλκίας ἐχώρουν οὐκ ἀργῶς, ἀλλὰ ταῖς τε κοπίσι καὶ τοῖς ἀκινάκαις χρώμενοι καὶ τὰς ἀσπίδας παρασπῶντες καὶ συμπλεκόμενοι χρόνον πολὺν ἀντεῖχον.", "st": "Arist. 18.1"}, {"sp": "N", "t": "οἱ δ’ Ἀθηναῖοι τέως μὲν ἠτρέμουν ἀναμένοντες τοὺς Λακεδαιμονίους, ἐπεὶ δὲ κραυγή τε προσέπιπτε πολλὴ μαχομένων καὶ παρῆν, ὥς φασιν, ἄγγελος παρὰ Παυσανίου τὰ γινόμενα φράζων, ὥρμησαν κατὰ τάχος βοηθεῖν. καὶ προχωροῦσιν αὐτοῖς διὰ τοῦ πεδίου πρὸς τὴν βοὴν ἐπεφέροντο τῶν Ἑλλήνων οἱ μηδίζοντες, Ἀριστείδης δὲ πρῶτον μέν, ὡς εἶδε, πολὺ προελθὼν ἐβόα, μαρτυρόμενος Ἑλληνίους θεούς, ἀπέχεσθαι μάχης καὶ μὴ σφίσιν ἐμποδὼν εἶναι μηδὲ κωλύειν ἐπαμύνοντας τοῖς προκινδυνεύουσιν ὑπὲρ τῆς Ἑλλάδος, ἐπεὶ δ’ ἑώρα μὴ προσέχοντας αὐτῷ καὶ συντεταγμένους ἐπὶ τὴν μάχην, οὕτω τῆς ἐκεῖ βοηθείας ἀποτραπόμενος συνέβαλε τούτοις περὶ πεντακισμυρίους οὖσιν. ἀλλὰ τὸ μὲν πλεῖστον εὐθὺς ἐνέδωκε καὶ ἀπεχώρησεν, ἅτε δὴ καὶ τῶν βαρβάρων ἀπηλλαγμένων, ἡ δὲ μάχη λέγεται μάλιστα κατὰ Θηβαίους γενέσθαι, προθυμότατα τῶν πρώτων καὶ δυνατωτάτων τότε παρ’ αὐτοῖς μηδιζόντων καὶ τὸ πλῆθος οὐ κατὰ γνώμην, ἀλλ’ ὀλιγαρχούμενον ἀγόντων.", "st": "Arist. 18.4"}, {"sp": "N", "t": "οὕτω δὲ τοῦ ἀγῶνος δίχα συνεστῶτος πρῶτοι μὲν ἐώσαντο τοὺς Πέρσας οἱ Λακεδαιμόνιοι· καὶ τὸν Μαρδόνιον ἀνὴρ Σπαρτιάτης ὄνομα Ἀρίμνηστος ἀποκτίννυσι, λίθῳ τὴν κεφαλὴν πατάξας, ὥσπερ αὐτῷ προεσήμανε τὸ ἐν Ἀμφιάρεω μαντεῖον. ἔπεμψε γὰρ ἄνδρα Λυδὸν ἐνταῦθα, Κᾶρα δὲ ἕτερον εἰς Τροφωνίου ὁ Μαρδόνιος· καὶ τοῦτον μὲν ὁ προφήτης Καρικῇ γλώσσῃ προσεῖπεν, ὁ δὲ Λυδὸς ἐν τῷ σηκῷ τοῦ Ἀμφιάρεω κατευνασθεὶς ἔδοξεν ὑπηρέτην τινὰ τοῦ θεοῦ παραστῆναι καὶ κελεύειν αὐτὸν ἀπιέναι, μὴ βουλομένου δὲ λίθον εἰς τὴν κεφαλὴν ἐμβαλεῖν μέγαν, ὥστε δόξαι πληγέντα τεθνάναι τὸν ἄνθρωπον· καὶ ταῦτα μὲν οὕτω γενέσθαι λέγεται. τοὺς δὲ φεύγοντας εἰς τὰ ξύλινα τείχη καθεῖρξαν.", "st": "Arist. 19.1"}, {"sp": "N", "t": "ὀλίγῳ δ’ ὕστερον Ἀθηναῖοι τοὺς Θηβαίους τρέπονται, τριακοσίους τοὺς ἐπιφανεστάτους καὶ πρώτους διαφθείραντες ἐν αὐτῇ τῇ μάχῃ. γεγενημένης δὲ τῆς τροπῆς ἧκεν αὐτοῖς ἄγγελος πολιορκεῖσθαι τὸ βαρβαρικὸν εἰς τὰ τείχη κατακεκλεισμένον. οὕτω δὴ σώζεσθαι τοὺς Ἕλληνας ἐάσαντες ἐβοήθουν πρὸς τὰ τείχη· καὶ τοῖς Λακεδαιμονίοις παντάπασιν ἀργῶς πρὸς τειχομαχίαν καὶ ἀπείρως ἔχουσιν ἐπιφανέντες αἱροῦσι τὸ στρατόπεδον φόνῳ πολλῷ τῶν πολεμίων. λέγονται γὰρ ἀπὸ τῶν τριάκοντα μυριάδων τετρακισμύριοι φυγεῖν σὺν Ἀρταβάζῳ, τῶν δ’ ὑπὲρ τῆς Ἑλλάδος ἀγωνισαμένων ἔπεσον οἱ πάντες ἐπὶ χιλίοις ἑξήκοντα καὶ τριακόσιοι. τούτων Ἀθηναῖοι μὲν ἦσαν δύο καὶ πεντήκοντα, πάντες ἐκ τῆς Αἰαντίδος φυλῆς, ὥς φησι Κλείδημος, ἀγωνισαμένης ἄριστα· διὸ καὶ ταῖς Σφραγίτισι νύμφαις ἔθυον Αἰαντίδαι τὴν πυθόχρηστον θυσίαν ὑπὲρ τῆς νίκης, ἐκ δημοσίου τὸ ἀνάλωμα λαμβάνοντες· Λακεδαιμόνιοι δ’ ἑνὶ πλείους τῶν ἐνενήκοντα, Τεγεᾶται δ’ ἑκκαίδεκα.", "st": "Arist. 19.3"}, {"sp": "N", "t": "θαυμαστὸν οὖν τὸ Ἡροδότου, πῶς μόνους τούτους φησὶν εἰς χεῖρας ἐλθεῖν τοῖς πολεμίοις, τῶν δ’ ἄλλων Ἑλλήνων μηδένα. καὶ γὰρ τὸ πλῆθος τῶν πεσόντων μαρτυρεῖ καὶ τὰ μνήματα κοινὸν γενέσθαι τὸ κατόρθωμα· καὶ τὸν βωμὸν οὐκ ἂν ἐπέγραψαν οὕτως, εἰ μόναι τρεῖς πόλεις ἠγωνίσαντο, τῶν ἄλλων ἀτρέμα καθεζομένων·", "st": "Arist. 19.6"}, {"sp": "N", "t": "τόνδε ποθ’ Ἕλληνες νίκας κράτει, ἔργῳ Ἄρηος,<br>Πέρσας ἐξελάσαντες ἐλευθέρᾳ Ἑλλάδι κοινὸν<br>ἱδρύσαντο Διὸς βωμὸν ἐλευθερίου.", "st": "Arist. 19.6b"}, {"sp": "N", "t": "ταύτην τὴν μάχην ἐμαχέσαντο τῇ τετράδι τοῦ Βοηδρομιῶνος ἱσταμένου κατ’ Ἀθηναίους, κατὰ δὲ Βοιωτοὺς τετράδι τοῦ Πανέμου φθίνοντος, ᾗ καὶ νῦν ἔτι τὸ Ἑλληνικὸν ἐν Πλαταιαῖς ἀθροίζεται συνέδριον καὶ θύουσι τῷ ἐλευθερίῳ Διῒ Πλαταιεῖς ὑπὲρ τῆς νίκης. τὴν δὲ τῶν ἡμερῶν ἀνωμαλίαν οὐ θαυμαστέον, ὅπου καὶ νῦν διηκριβωμένων τῶν ἐν ἀστρολογίᾳ μᾶλλον ἄλλην ἄλλοι μηνὸς ἀρχὴν καὶ τελευτὴν ἄγουσιν.", "st": "Arist. 19.7"}, {"sp": "N", "t": "ἐκ τούτου τῶν Ἀθηναίων τὸ ἀριστεῖον οὐ παραδιδόντων τοῖς Σπαρτιάταις οὐδὲ τρόπαιον ἱστάναι συγχωρούντων ἐκείνοις, παρ’ οὐδὲν ἂν ἦλθεν εὐθὺς ἀπολέσθαι τὰ πράγματα τῶν Ἑλλήνων ἐν τοῖς ὅπλοις διαστάντων, εἰ μὴ πολλὰ παρηγορῶν καὶ διδάσκων τοὺς συστρατήγους ὁ Ἀριστείδης, μάλιστα δὲ Λεωκράτη καὶ Μυρωνίδην, ἔσχε καὶ συνέπεισε τὴν κρίσιν ἐφεῖναι τοῖς Ἕλλησιν. ἐνταῦθα βουλευομένων τῶν Ἑλλήνων Θεογείτων μὲν ὁ Μεγαρεὺς εἶπεν, ὡς ἑτέρᾳ πόλει δοτέον εἴη τὸ ἀριστεῖον, εἰ μὴ βούλονται συνταράξαι πόλεμον ἐμφύλιον· ἐπὶ τούτῳ δ’ ἀναστὰς Κλεόκριτος ὁ Κορίνθιος δόξαν μὲν παρέσχεν ὡς Κορινθίοις αἰτήσων τὸ ἀριστεῖον· ἦν γὰρ ἐν ἀξιώματι μεγίστῳ μετὰ τὴν Σπάρτην καὶ τὰς Ἀθήνας ἡ Κόρινθος· εἶπε δὲ πᾶσιν ἀρέσαντα καὶ θαυμαστὸν λόγον ὑπὲρ Πλαταιέων, καὶ συνεβούλευσε τὴν φιλονεικίαν ἀνελεῖν ἐκείνοις τὸ ἀριστεῖον ἀποδόντας, οἷς οὐδετέρους τιμωμένοις ἄχθεσθαι. ῥηθέντων δὲ τούτων πρῶτος μὲν Ἀριστείδης συνεχώρησεν ὑπὲρ τῶν Ἀθηναίων, ἔπειτα Παυσανίας ὑπὲρ τῶν Λακεδαιμονίων. οὕτω δὲ διαλλαγέντες ἐξεῖλον ὀγδοήκοντα τάλαντα τοῖς Πλαταιεῦσιν, ἀφ’ ὧν τὸ τῆς Ἀθηνᾶς ἀνῳκοδόμησαν ἱερὸν καὶ τὸ ἕδος ἔστησαν καὶ γραφαῖς τὸν νεὼν διεκόσμησαν, αἳ μέχρι νῦν ἀκμάζουσαι διαμένουσιν, ἔστησαν δὲ τρόπαιον ἰδίᾳ μὲν Λακεδαιμόνιοι, χωρὶς δ’ Ἀθηναῖοι.", "st": "Arist. 20.1"}, {"sp": "N", "t": "περὶ δὲ θυσίας ἐρομένοις αὐτοῖς ἀνεῖλεν ὁ Πύθιος Διὸς ἐλευθερίου βωμὸν ἱδρύσασθαι, θῦσαι δὲ μὴ πρότερον ἢ τὸ κατὰ τὴν χώραν πῦρ ἀποσβέσαντας ὡς ὑπὸ τῶν βαρβάρων μεμιασμένον ἐναύσασθαι καθαρὸν ἐκ Δελφῶν ἀπὸ τῆς κοινῆς ἑστίας. οἱ μὲν οὖν ἄρχοντες τῶν Ἑλλήνων περιιόντες εὐθὺς ἠνάγκαζον ἀποσβεννύναι τὰ πυρὰ πάντα τοὺς χρωμένους, ἐκ δὲ Πλαταιέων Εὐχίδας ὑποσχόμενος ὡς ἐνδέχεται τάχιστα κομιεῖν τὸ παρὰ τοῦ θεοῦ πῦρ ἧκεν εἰς Δελφούς. ἁγνίσας δὲ τὸ σῶμα καὶ περιρρανάμενος ἐστεφανώσατο δάφνῃ· καὶ λαβὼν ἀπὸ τοῦ βωμοῦ τὸ πῦρ δρόμῳ πάλιν εἰς τὰς Πλαταιὰς ἐχώρει καὶ πρὸ ἡλίου δυσμῶν ἐπανῆλθε, τῆς αὐτῆς ἡμέρας χιλίους σταδίους κατανύσας. ἀσπασάμενος δὲ τοὺς πολίτας καὶ τὸ πῦρ παραδοὺς εὐθὺς ἔπεσε καὶ μετὰ μικρὸν ἐξέπνευσεν. ἀγάμενοι δ’ αὐτὸν οἱ Πλαταιεῖς ἔθαψαν ἐν τῷ ἱερῷ τῆς Εὐκλείας Ἀρτέμιδος, ἐπιγράψαντες τόδε τὸ τετράμετρον·", "st": "Arist. 20.4"}, {"sp": "N", "t": "Εὐχίδας Πυθῶδε θρέξας ἦλθε τᾷδ’ αὐθημερόν.", "st": "Arist. 20.4b"}, {"sp": "N", "t": "τὴν δ’ Εὔκλειαν οἱ μὲν πολλοὶ καὶ καλοῦσι καὶ νομίζουσιν Ἄρτεμιν, ἔνιοι δέ φασιν Ἡρακλέους μὲν θυγατέρα καὶ Μυρτοῦς γενέσθαι, τῆς Μενοιτίου μὲν θυγατρός, Πατρόκλου δ’ ἀδελφῆς, τελευτήσασαν δὲ παρθένον ἔχειν παρά τε Βοιωτοῖς καὶ Λοκροῖς τιμάς. βωμὸς γὰρ αὐτῇ καὶ ἄγαλμα κατὰ πᾶσαν ἀγορὰν ἵδρυται, καὶ προθύουσιν αἵ τε γαμούμεναι καὶ οἱ γαμοῦντες.", "st": "Arist. 20.6"}, {"sp": "N", "t": "ἐκ τούτου γενομένης ἐκκλησίας κοινῆς τῶν Ἑλλήνων ἔγραψεν Ἀριστείδης ψήφισμα συνιέναι μὲν εἰς Πλαταιὰς καθ’ ἕκαστον ἐνιαυτὸν ἀπὸ τῆς Ἑλλάδος προβούλους καὶ θεωρούς, ἄγεσθαι δὲ πενταετηρικὸν ἀγῶνα τῶν Ἐλευθερίων. εἶναι δὲ σύνταξιν Ἑλληνικὴν μυρίας μὲν ἀσπίδας, χιλίους δὲ ἵππους, ναῦς δ’ ἑκατὸν ἐπὶ τὸν πρὸς βαρβάρους πόλεμον, Πλαταιεῖς δ’ ἀσύλους καὶ ἱεροὺς ἀφεῖσθαι τῷ θεῷ θύοντας ὑπὲρ τῆς Ἑλλάδος.", "st": "Arist. 21.1"}, {"sp": "N", "t": "κυρωθέντων δὲ τούτων οἱ Πλαταιεῖς ὑπεδέξαντο τοῖς πεσοῦσι καὶ κειμένοις αὐτόθι τῶν Ἑλλήνων ἐναγίζειν καθ’ ἕκαστον ἐνιαυτόν. καὶ τοῦτο μέχρι νῦν δρῶσι τόνδε τὸν τρόπον· τοῦ Μαιμακτηριῶνος μηνός, ὅς ἐστι παρὰ Βοιωτοῖς Ἀλαλκομένιος, τῇ ἕκτῃ ἐπὶ δέκα πέμπουσι πομπήν, ἧς προηγεῖται μὲν ἅμ’ ἡμέρᾳ σαλπιγκτὴς ἐγκελευόμενος τὸ πολεμικόν, ἕπονται δ’ ἅμαξαι μυρρίνης μεσταὶ καὶ στεφανωμάτων καὶ μέλας ταῦρος καὶ χοὰς οἴνου καὶ γάλακτος ἐν ἀμφορεῦσιν ἐλαίου τε καὶ μύρου κρωσσοὺς νεανίσκοι κομίζοντες ἐλεύθεροι· δούλῳ γὰρ οὐδενὸς ἔξεστι τῶν περὶ τὴν διακονίαν ἐκείνην προσάψασθαι διὰ τὸ τοὺς ἄνδρας ἀποθανεῖν ὑπὲρ ἐλευθερίας· ἐπὶ πᾶσι δὲ τῶν Πλαταιέων ὁ ἄρχων, ᾧ τὸν ἄλλον χρόνον οὔτε σιδήρου θιγεῖν ἔξεστιν οὔθ’ ἑτέραν ἐσθῆτα πλὴν λευκῆς ἀναλαβεῖν, τότε χιτῶνα φοινικοῦν ἐνδεδυκὼς ἀράμενός τε ὑδρίαν ἀπὸ τοῦ γραμματοφυλακίου ξιφήρης ἐπὶ τοὺς τάφους προάγει διὰ μέσης τῆς πόλεως. εἶτα λαβὼν ὕδωρ ἀπὸ τῆς κρήνης αὐτὸς ἀπολούει τε τὰς στήλας καὶ μύρῳ χρίει, καὶ τὸν ταῦρον εἰς τὴν πυρὰν σφάξας καὶ κατευξάμενος Διῒ καὶ Ἑρμῇ χθονίῳ παρακαλεῖ τοὺς ἀγαθοὺς ἄνδρας τοὺς ὑπὲρ τῆς Ἑλλάδος ἀποθανόντας ἐπὶ τὸ δεῖπνον καὶ τὴν αἱμοκουρίαν. ἔπειτα κρατῆρα κεράσας οἴνου καὶ χεάμενος ἐπιλέγει· προπίνω τοῖς ἀνδράσι τοῖς ὑπὲρ τῆς ἐλευθερίας τῶν Ἑλλήνων ἀποθανοῦσι. ταῦτα μὲν οὖν ἔτι καὶ νῦν διαφυλάττουσιν οἱ Πλαταεῖς.", "st": "Arist. 21.2"}, {"sp": "N", "t": "ἐπεὶ δ’ ἀναχωρήσαντας εἰς τὸ ἄστυ τοὺς Ἀθηναίους ὁ Ἀριστείδης ἑώρα ζητοῦντας τὴν δημοκρατίαν ἀπολαβεῖν, ἅμα μὲν ἄξιον ἡγούμενος διὰ τὴν ἀνδραγαθίαν ἐπιμελείας τὸν δῆμον, ἅμα δ’ οὐκ ἔτι ῥᾴδιον ἰσχύοντα τοῖς ὅπλοις καὶ μέγα φρονοῦντα ταῖς νίκαις ἐκβιασθῆναι, γράφει ψήφισμα κοινὴν εἶναι τὴν πολιτείαν καὶ τοὺς ἄρχοντας ἐξ Ἀθηναίων πάντων αἱρεῖσθαι.", "st": "Arist. 22.1"}, {"sp": "N", "t": "Θεμιστοκλέους δὲ πρὸς τὸν δῆμον εἰπόντος, ὡς ἔχει τι βούλευμα καὶ γνώμην ἀπόρρητον, ὠφέλιμον δὲ τῇ πόλει καὶ σωτήριον, ἐκέλευσαν Ἀριστείδην μόνον ἀκοῦσαι καὶ συνδοκιμάσαι. φράσαντος δὲ τῷ Ἀριστείδη τοῦ Θεμιστοκλέους, ὡς διανοεῖται τὸν ναύσταθμον ἐμπρῆσαι τῶν Ἑλλήνων, οὕτω γὰρ ἔσεσθαι μεγίστους καὶ κυρίους ἁπάντων τοὺς Ἀθηναίους, παρελθὼν εἰς τὸν δῆμον ὁ Ἀριστείδης ἔφη τῆς πράξεως, ἣν Θεμιστοκλῆς πράττειν διανοεῖται, μήτε λυσιτελεστέραν ἄλλην μήτ’ ἀδικωτέραν εἶναι. ταῦτ’ ἀκούσαντες οἱ Ἀθηναῖοι παύσασθαι τὸν Θεμιστοκλέα προσέταξαν. οὕτω μὲν ὁ δῆμος ἦν φιλοδίκαιος, οὕτω δὲ τῷ δήμῳ πιστὸς ὁ ἀνὴρ καὶ βέβαιος.", "st": "Arist. 22.2"}, {"sp": "N", "t": "ἐπεὶ δὲ στρατηγὸς ἐκπεμφθεὶς μετὰ Κίμωνος ἐπὶ τὸν πόλεμον ἑώρα τόν τε Παυσανίαν καὶ τοὺς ἄλλους ἄρχοντας τῶν Σπαρτιατῶν ἐπαχθεῖς καὶ χαλεποὺς τοῖς συμμάχοις ὄντας, αὐτός τε πρᾴως καὶ φιλανθρώπως ὁμιλῶν καὶ τὸν Κίμωνα παρέχων εὐάρμοστον αὐτοῖς καὶ κοινὸν ἐν ταῖς στρατείαις ἔλαθε τῶν Λακεδαιμονίων οὐχ ὅπλοις οὐδὲ ναυσὶν οὐδ’ ἵπποις, εὐγνωμοσύνῃ δὲ καὶ πολιτείᾳ τὴν ἡγεμονίαν παρελόμενος. προσφιλεῖς γὰρ ὄντας τοὺς Ἀθηναίους τοῖς Ἕλλησι διὰ τὴν Ἀριστείδου δικαιοσύνην καὶ τὴν Κίμωνος ἐπιείκειαν ἔτι μᾶλλον ἡ τοῦ Παυσανίου πλεονεξία καὶ βαρύτης ποθεινοὺς ἐποίει. τοῖς τε γὰρ ἄρχουσι τῶν συμμάχων ἀεὶ μετ’ ὀργῆς ἐνετύγχανε καὶ τραχέως, τούς τε πολλοὺς ἐκόλαζε πληγαῖς ἢ σιδηρᾶν ἄγκυραν ἐπιτιθεὶς ἠνάγκαζεν ἑστάναι δι’ ὅλης τῆς ἡμέρας. στιβάδα δ’ οὐκ ἦν λαβεῖν οὐδὲ χόρτον οὐδὲ κρήνῃ προσελθεῖν ὑδρευόμενον οὐδένα πρὸ τῶν Σπαρτιατῶν, ἀλλὰ μάστιγας ἔχοντες ὑπηρέται τοὺς προσιόντας ἀπήλαυνον. ὑπὲρ ὧν τοῦ Ἀριστείδου ποτὲ βουληθέντος ἐγκαλέσαι καὶ διδάξαι, συναγαγὼν τὸ πρόσωπον ὁ Παυσανίας οὐκ ἔφη σχολάζειν οὐδ’ ἤκουσεν.", "st": "Arist. 23.1"}, {"sp": "N", "t": "ἐκ τούτου προσιόντες οἱ ναύαρχοι καὶ στρατηγοὶ τῶν Ἑλλήνων, μάλιστα δὲ Χῖοι καὶ Σάμιοι καὶ Λέσβιοι, τὸν Ἀριστείδην ἔπειθον ἀναδέξασθαι τὴν ἡγεμονίαν καὶ προσαγαγέσθαι τοὺς συμμάχους πάλαι δεομένους ἀπαλλαγῆναι τῶν Σπαρτιατῶν καὶ μετατάξασθαι πρὸς τοὺς Ἀθηναίους. ἀποκριναμένου δ’ ἐκείνου τοῖς μὲν λόγοις αὐτῶν τό τε ἀναγκαῖον ἐνορᾶν καὶ τὸ δίκαιον, ἔργου δὲ δεῖσθαι τὴν πίστιν, ὃ πραχθὲν οὐκ ἐάσει πάλιν μεταβαλέσθαι τοὺς πολλούς, οὕτως οἱ περὶ τὸν Σάμιον Οὐλιάδην καὶ τὸν Χῖον Ἀνταγόραν συνομοσάμενοι περὶ Βυζάντιον ἐμβάλλουσιν εἰς τὴν τριήρη τοῦ Παυσανίου, προεκπλέουσαν ἐν μέσῳ λαβόντες. ὡς δὲ κατιδὼν ἐκεῖνος ἐξανέστη καὶ μετ’ ὀργῆς ἠπείλησεν ὀλίγῳ χρόνῳ τοὺς ἄνδρας ἐπιδείξειν οὐκ εἰς τὴν αὐτοῦ ναῦν ἐμβεβληκότας, ἀλλ’ εἰς τὰς ἰδίας πατρίδας, ἐκέλευον αὐτὸν ἀπιέναι καὶ ἀγαπᾶν τὴν συναγωνισαμένην τύχην ἐν Πλαταιαῖς· ἐκείνην γὰρ ἔτι τοὺς Ἕλληνας αἰσχυνομένους μὴ λαμβάνειν ἀξίαν δίκην παρ’ αὐτοῦ· τέλος δ’ ἀποστάντες ᾤχοντο πρὸς τοὺς Ἀθηναίους.", "st": "Arist. 23.4"}, {"sp": "N", "t": "ἔνθα δὴ καὶ τὸ φρόνημα τῆς Σπάρτης διεφάνη θαυμαστόν. ὡς γὰρ ᾔσθοντο τῷ μεγέθει τῆς ἐξουσίας διαφθειρομένους αὐτῶν τοὺς ἄρχοντας, ἀφῆκαν ἑκουσίως τὴν ἡγεμονίαν καὶ πέμποντες ἐπὶ τὸν πόλεμον ἐπαύσαντο στρατηγούς, μᾶλλον αἱρούμενοι σωφρονοῦντας ἔχειν καὶ τοῖς ἔθεσιν ἐμμένοντας τοὺς πολίτας ἢ τῆς Ἑλλάδος ἄρχειν ἁπάσης.", "st": "Arist. 23.6"}, {"sp": "N", "t": "οἱ δ’ Ἕλληνες ἐτέλουν μέν τινα καὶ Λακεδαιμονίων ἡγουμένων ἀποφορὰν εἰς τὸν πόλεμον, ταχθῆναι δὲ βουλόμενοι κατὰ πόλιν ἑκάστοις τὸ μέτριον ᾐτήσαντο παρὰ τῶν Ἀθηναίων Ἀριστείδην, καὶ προσέταξαν αὐτῷ χώραν τε καὶ προσόδους ἐπισκεψάμενον ὁρίσαι τὸ κατ’ ἀξίαν ἑκάστῳ καὶ δύναμιν. ὁ δὲ τηλικαύτης ἐξουσίας κύριος γενόμενος καὶ τρόπον τινὰ τῆς Ἑλλάδος ἐπ’ αὐτῷ μόνῳ τὰ πράγματα πάντα θεμένης, πένης μὲν ἐξῆλθεν, ἐπανῆλθε δὲ πενέστερος, οὐ μόνον καθαρῶς καὶ δικαίως, ἀλλὰ καὶ προσφιλῶς πᾶσι καὶ ἁρμοδίως τὴν ἐπιγραφὴν τῶν χρημάτων ποιησάμενος. ὡς γὰρ οἱ παλαιοὶ τὸν ἐπὶ Κρόνου βίον, οὕτως οἱ σύμμαχοι τῶν Ἀθηναίων τὸν ἐπ’ Ἀριστείδου φόρον εὐποτμίαν τινὰ τῆς Ἑλλάδος ὀνομάζοντες ὕμνουν, καὶ μάλιστα μετ’ οὐ πολὺν χρόνον διπλασιασθέντος, εἶτ’ αὖθις τριπλασιασθέντος. ὃν μὲν γὰρ Ἀριστείδης ἔταξεν, ἦν εἰς ἐξήκοντα καὶ τετρακοσίων ταλάντων λόγον· τούτῳ δὲ Περικλῆς μὲν ἐπέθηκεν ὀλίγου δεῖν τὸ τρίτον μέρος· ἑξακόσια γὰρ τάλαντα Θουκυδίδης φησὶν ἀρχομένου τοῦ πολέμου προσιέναι τοῖς Ἀθηναίοις ἀπὸ τῶν συμμάχων· Περικλέους δ’ ἀποθανόντος ἐπιτείνοντες οἱ δημαγωγοὶ κατὰ μικρὸν εἰς χιλίων καὶ τριακοσίων ταλάντων κεφάλαιον ἀνήγαγον, οὐχ οὕτω τοῦ πολέμου διὰ μῆκος καὶ τύχας δαπανηροῦ γενομένου καὶ πολυτελοῦς, ὡς τὸν δῆμον εἰς διανομὰς καὶ θεωρικὰ καὶ κατασκευὰς ἀγαλμάτων καὶ ἱερῶν προαγαγόντες.", "st": "Arist. 24.1"}, {"sp": "N", "t": "μέγα δ’ οὖν ὄνομα τοῦ Ἀριστείδου καὶ θαυμαστὸν ἔχοντος ἐπὶ τῇ διατάξει τῶν φόρων ὁ Θεμιστοκλῆς λέγεται καταγελᾶν, ὡς οὐκ ἀνδρὸς ὄντα τὸν ἔπαινον, ἀλλὰ θυλάκου χρυσοφύλακος· ἀνομοίως ἀμυνόμενος τὴν Ἀριστείδου παρρησίαν· ἐκείνῳ γὰρ εἰπόντος ποτὲ τοῦ Θεμιστοκλέους ἀρετὴν ἡγεῖσθαι μεγίστην στρατηγοῦ τὸ γινώσκειν καὶ προαισθάνεσθαι τὰ βουλεύματα τῶν πολεμίων, τοῦτο μέν, εἰπεῖν, ἀναγκαῖόν ἐστιν, ὦ Θεμιστόκλεις, καλὸν δὲ καὶ στρατηγικὸν ἀληθῶς ἡ περὶ τὰς χεῖρας ἐγκράτεια.", "st": "Arist. 24.4"}, {"sp": "N", "t": "ὁ δ’ Ἀριστείδης ὥρκισε μὲν τοὺς Ἕλληνας καὶ ὤμοσεν ὑπὲρ τῶν Ἀθηναίων, μύδρους ἐμβαλὼν ἐπὶ ταῖς ἀραῖς εἰς τὴν θάλατταν, ὕστερον δὲ τῶν πραγμάτων ἄρχειν ἐγκρατέστερον, ὡς ἔοικεν, ἐκβιαζομένων ἐκέλευε τοὺς Ἀθηναίους τὴν ἐπιορκίαν τρέψαντας εἰς ἑαυτὸν ᾗ συμφέρει χρῆσθαι τοῖς πράγμασι. καθ’ ὅλου δ’ ὁ Θεόφραστός φησι τὸν ἄνδρα τοῦτον περὶ τὰ οἰκεῖα καὶ τοὺς πολίτας ἄκρως ὄντα δίκαιον ἐν τοῖς κοινοῖς πολλὰ πρᾶξαι πρὸς τὴν ὑπόθεσιν τῆς πατρίδος, ὡς συχνῆς καὶ ἀδικίας δεομένην. καὶ γὰρ τὰ χρήματά φησιν ἐκ Δήλου βουλευομένων Ἀθήναζε κομίσαι παρὰ τὰς συνθήκας, καὶ Σαμίων εἰσηγουμένων, εἰπεῖν ἐκεῖνον, ὡς οὐ δίκαιον μέν, συμφέρον δὲ τοῦτ’ ἐστί. καὶ τέλος εἰς τὸ ἄρχειν ἀνθρώπων τοσούτων καταστήσας τὴν πόλιν αὐτὸς ἐνέμεινε τῇ πενίᾳ καὶ τὴν ἀπὸ τοῦ πένης εἶναι δόξαν οὐδὲν ἧττον ἀγαπῶν τῆς ἀπὸ τῶν τροπαίων διετέλεσε.", "st": "Arist. 25.1"}, {"sp": "N", "t": "δῆλον δ’ ἐκεῖθεν. Καλλίας ὁ δᾳδοῦχος ἦν αὐτῷ γένει προσήκων· τοῦτον οἱ ἐχθροὶ θανάτου διώκοντες, ἐπεὶ περὶ ὧν ἐγράψαντο μετρίως κατηγόρησαν, εἶπόν τινα λόγον ἔξωθεν τοιοῦτον πρὸς τοὺς δικαστάς· Ἀριστείδην, ἔφησαν, ἴστε τὸν Λυσιμάχου θαυμαζόμενον ἐν τοῖς Ἕλλησι· τούτῳ πῶς οἴεσθε τὰ κατ’ οἶκον ἔχειν ὁρῶντες αὐτὸν ἐν τρίβωνι τοιούτῳ προερχόμενον εἰς τὸ δημόσιον; ἆρ’ οὐκ εἰκός ἐστι τὸν ῥιγοῦντα φανερῶς καὶ πεινᾶν οἴκοι καὶ τῶν ἄλλων ἐπιτηδείων σπανίζειν; τοῦτον μέντοι Καλλίας, ἀνεψιὸν ὄντα, πλουσιώτατος ὢν Ἀθηναίων περιορᾷ μετὰ τέκνων καὶ γυναικὸς ἐνδεόμενον, πολλὰ κεχρημένος τῷ ἀνδρὶ καὶ πολλάκις αὐτοῦ τῆς παρ’ ὑμῖν δυνάμεως ἀπολελαυκώς. ὁ δὲ Καλλίας ὁρῶν ἐπὶ τούτῳ μάλιστα θορυβοῦντας τοὺς δικαστὰς καὶ χαλεπῶς πρὸς αὐτὸν ἔχοντας ἐκάλει τὸν Ἀριστείδην, ἀξιῶν μαρτυρῆσαι πρὸς τοὺς δικαστάς, ὅτι πολλάκις αὐτοῦ πολλὰ καὶ διδόντος καὶ δεομένου λαβεῖν οὐκ ἠθέλησεν ἀποκρινόμενος, ὡς μᾶλλον αὐτῷ διὰ πενίαν μέγα φρονεῖν ἢ Καλλίᾳ διὰ πλοῦτον προσήκει· πλούτῳ μὲν γὰρ ἔστι πολλοὺς ἰδεῖν εὖ τε καὶ κακῶς χρωμένους, πενίαν δὲ φέροντι γενναίως οὐ ῥᾴδιον ἐντυχεῖν· αἰσχύνεσθαι δὲ πενίαν τοὺς ἀκουσίως πενομένους. ταῦτα δὲ τοῦ Ἀριστείδου τῷ Καλλίᾳ προσμαρτυρήσαντος οὐδεὶς ἦν τῶν ἀκουόντων, ὃς οὐκ ἀπῄει πένης μᾶλλον ὡς Ἀριστείδης εἶναι βουλόμενος ἢ πλουτεῖν ὡς Καλλίας. ταῦτα μὲν οὖν Αἰσχίνης ὁ Σωκρατικὸς ἀναγέγραφε. Πλάτων δὲ τῶν μεγάλων δοκούντων καὶ ὀνομαστῶν Ἀθήνησι μόνον ἄξιον λόγου τοῦτον ἀποφαίνει τὸν ἄνδρα· Θεμιστοκλέα μὲν γὰρ καὶ Κίμωνα καὶ Περικλέα στοῶν καὶ χρημάτων καὶ φλυαρίας πολλῆς ἐμπλῆσαι τὴν πόλιν, Ἀριστείδην δὲ πολιτεύσασθαι πρὸς ἀρετήν.", "st": "Arist. 25.4"}, {"sp": "N", "t": "μεγάλα δ’ αὐτοῦ καὶ τὰ πρὸς Θεμιστοκλέα τῆς ἐπιεικείας σημεῖα. χρησάμενος γὰρ αὐτῷ παρὰ πᾶσαν ὁμοῦ τὴν πολιτείαν ἐχθρῷ καὶ δι’ ἐκεῖνον ἐξοστρακισθείς, ἐπεὶ τὴν αὐτὴν λαβὴν παρέσχεν ὁ ἀνὴρ ἐν αἰτίᾳ γενόμενος πρὸς τὴν πόλιν, οὐκ ἐμνησικάκησεν, ἀλλ’ Ἀλκμαίωνος καὶ Κίμωνος καὶ πολλῶν ἄλλων ἐλαυνόντων καὶ κατηγορούντων μόνος Ἀριστείδης οὔτ’ ἔπραξεν οὔτ’ εἶπέ τι φαῦλον, οὐδ’ ἀπέλαυσεν ἐχθροῦ δυστυχοῦντος, ὥσπερ οὐδ’ εὐημεροῦντι πρότερον ἐφθόνησε.", "st": "Arist. 25.7"}, {"sp": "N", "t": "τελευτῆσαι δὲ Ἀριστείδην οἱ μὲν ἐν Πόντῳ φασὶν ἐκπλεύσαντα πράξεων ἕνεκα δημοσίων, οἱ δ’ Ἀθήνησι γήρα, τιμώμενον καὶ θαυμαζόμενον ὑπὸ τῶν πολιτῶν. κρατερὸς δ’ ὁ Μακεδὼν τοιαῦτά τινα περὶ τῆς τελευτῆς τοῦ ἀνδρὸς εἴρηκε. μετὰ γὰρ τὴν Θεμιστοκλέους φυγήν φησιν ὥσπερ ἐξυβρίσαντα τὸν δῆμον ἀναφῦσαι πλῆθος συκοφαντῶν, οἳ τοὺς ἀρίστους καὶ δυνατωτάτους ἄνδρας διώκοντες ὑπέβαλλον τῷ φθόνῳ τῶν πολλῶν ἐπαιρομένων ὑπ’ εὐτυχίας καὶ δυνάμεως. ἐν τούτοις καὶ Ἀριστείδην ἁλῶναι δωροδοκίας, Διοφάντου τοῦ Ἀμφιτροπῆθεν κατηγοροῦντος, ὡς, ὅτε τοὺς φόρους ἔταττε, παρὰ τῶν Ἰώνων χρήματα λαβόντος· ἐκτῖσαι δ’ οὐκ ἔχοντα τὴν καταδίκην πεντήκοντα μνῶν οὖσαν ἐκπλεῦσαι καὶ περὶ τὴν Ἰωνίαν ἀποθανεῖν. τούτων δὲ οὐδὲν ἔγγραφον ὁ Κρατερὸς τεκμήριον παρέσχηκεν, οὔτε δίκην οὔτε ψήφισμα, καίπερ εἰωθὼς ἐπιεικῶς γράφειν τὰ τοιαῦτα καὶ παρατίθεσθαι τοὺς ἱστοροῦντας.", "st": "Arist. 26.1"}, {"sp": "N", "t": "οἱ δ’ ἄλλοι πάντες, ὡς ἔπος εἰπεῖν, ὅσοι τὰ πλημμεληθέντα τῷ δήμῳ περὶ τοὺς στρατηγοὺς διεξίασι, τὴν μὲν Θεμιστοκλέους φυγὴν καὶ τὰ Μιλτιάδου δεσμὰ καὶ τὴν Περικλέους ζημίαν καὶ τὸν Πάχητος ἐν τῷ δικαστηρίῳ θάνατον, ἀνελόντος αὑτὸν ἐπὶ τοῦ βήματος ὡς ἡλίσκετο, καὶ πολλὰ τοιαῦτα συνάγουσι καὶ θρυλοῦσιν, Ἀριστείδου δὲ τὸν μὲν ἐξοστρακισμὸν παρατίθενται, καταδίκης δὲ τοιαύτης οὐδαμοῦ μνημονεύουσι.", "st": "Arist. 26.3"}, {"sp": "N", "t": "καὶ μέντοι καὶ τάφος ἐστὶν αὐτοῦ Φαληροῖ δεικνύμενος, ὅν φασι κατασκευάσαι τὴν πόλιν αὐτῷ μηδ’ ἐντάφια καταλιπόντι. καὶ τὰς μὲν θυγατέρας ἱστοροῦσιν ἐκ τοῦ πρυτανείου τοῖς νυμφίοις ἐκδοθῆναι δημοσίᾳ, τῆς πόλεως τὸν γάμον ἐγγυώσης καὶ προῖκα τρισχιλίας δραχμὰς ἑκατέρᾳ ψηφισαμένης, Λυσιμάχῳ δὲ τῷ υἱῷ μνᾶς μὲν ἑκατὸν ἀργυρίου καὶ γῆς τοσαῦτα πλέθρα πεφυτευμένης ἔδωκεν ὁ δῆμος, ἄλλας δὲ δραχμὰς τέσσαρας εἰς ἡμέραν ἑκάστην ἀπέταξεν, Ἀλκιβιάδου τὸ ψήφισμα γράψαντος. ἔτι δὲ Λυσιμάχου θυγατέρα Πολυκρίτην ἀπολιπόντος, ὡς Καλλισθένης φησί, καὶ ταύτῃ σίτησιν ὅσην καὶ τοῖς Ὀλυμπιονίκαις ὁ δῆμος ἐψηφίσατο. Δημήτριος δ’ ὁ Φαληρεὺς καὶ Ἱερώνυμος ὁ Ῥόδιος καὶ Ἀριστόξενος ὁ μουσικὸς καὶ Ἀριστοτέλης (εἰ δὴ τό γε Περὶ εὐγενείας βιβλίον ἐν τοῖς γνησίοις Ἀριστοτέλους θετέον) ἱστοροῦσι Μυρτὼ θυγατριδῆν Ἀριστείδου Σωκράτει τῷ σοφῷ συνοικῆσαι, γυναῖκα μὲν ἑτέραν ἔχοντι, ταύτην δ’ ἀναλαβόντι χηρεύουσαν διὰ πενίαν καὶ τῶν ἀναγκαίων ἐνδεομένην. πρὸς μὲν οὖν τούτους ἱκανῶς ὁ Παναίτιος ἐν τοῖς περὶ Σωκράτους ἀντείρηκεν·", "st": "Arist. 27.1"}, {"sp": "N", "t": "ὁ δὲ Φαληρεὺς ἐν τῷ Σωκράτει φησὶ μνημονεύειν Ἀριστείδου θυγατριδοῦν εὖ μάλα πένητα Λυσίμαχον, ὃς ἑαυτὸν μὲν ἐκ πινακίου τινὸς ὀνειροκριτικοῦ παρὰ τὸ Ἰακχεῖον λεγόμενον καθεζόμενος ἔβοσκε. τῇ δὲ μητρὶ καὶ τῇ ταύτης ἀδελφῇ ψήφισμα γράψας ἔπεισε τὸν δῆμον τροφὴν διδόναι τριώβολον ἑκάστης ἡμέρας. αὐτὸς μέντοι φησὶν ὁ Δημήτριος νομοθετῶν ἀντὶ τριωβόλου δραχμὴν ἑκατέρᾳ τάξαι τῶν γυναικῶν.", "st": "Arist. 27.1b"}, {"sp": "N", "t": "καὶ οὐδέν ἐστι θαυμαστὸν οὕτω φροντίσαι τῶν ἐν ἄστει τὸν δῆμον, ὅπου θυγατριδῆν Ἀριστογείτονος ἐν Λήμνῳ πυθόμενοι ταπεινὰ πράττειν ἀνδρὸς ἀποροῦσαν διὰ πενίαν κατήγαγον Ἀθήναζε, καὶ συνοικίσαντες ἀνδρὶ τῶν εὖ γεγονότων τὸ Ποταμοῖ χωρίον εἰς φερνὴν ἐπέδωκαν. ἧς φιλανθρωπίας καὶ χρηστότητος ἔτι πολλὰ καὶ καθ’ ἡμᾶς ἡ πόλις ἐκφέρουσα δείγματα θαυμάζεται καὶ ζηλοῦται δικαίως.", "st": "Arist. 27.4"}, {"sp": "HDR", "t": "Μάρκος Κάτων"}, {"sp": "N", "t": "Μάρκῳ δὲ Κάτωνί φασιν ἀπὸ Τούσκλου τὸ γένος εἶναι, δίαιταν δὲ καὶ βίον ἔχειν πρὸ τῶν στρατειῶν καὶ τῆς πολιτείας ἐν χωρίοις πατρῴοις περὶ Σαβίνους, τῶν δὲ προγόνων παντάπασιν ἀγνώστων γεγονέναι δοκούντων αὐτὸς ὁ Κάτων καὶ τὸν πατέρα Μᾶρκον ὡς ἀγαθὸν ἄνδρα καὶ στρατιωτικὸν ἐπαινεῖ, καὶ Κάτωνα τὸν πρόπαππον ἀριστείων πολλάκις τυχεῖν φησὶ καὶ πέντε πολεμιστὰς ἵππους ἐν μάχαις ἀποβαλόντα τὴν τιμὴν ἀπολαβεῖν ἐκ τοῦ δημοσίου δι’ ἀνδραγαθίαν. εἰωθότων δὲ τῶν Ῥωμαίων τοὺς ἀπὸ γένους μὲν δόξαν οὐκ ἔχοντας, ἀρχομένους δὲ γνωρίζεσθαι δι’ αὑτῶν καινοὺς προσαγορεύειν ἀνθρώπους, ὥσπερ καὶ τὸν Κάτωνα προσηγόρευον, αὐτὸς ἔλεγε καινὸς εἶναι πρὸς ἀρχὴν καὶ δόξαν, ἔργοις δὲ προγόνων καὶ ἀρεταῖς παμπάλαιος, ἐκαλεῖτο δὲ τῷ τρίτῳ τῶν ὀνομάτων πρότερον οὐ Κάτων, ἀλλὰ Πρῖσκος, ὕστερον δὲ τὸν Κάτωνα τῆς δυνάμεως ἐπώνυμον ἔσχε Ῥωμαῖοι γὰρ τὸν ἔμπειρον κάτον ὀνομάζουσιν.", "st": "Cat. Ma. 1.1"}, {"sp": "N", "t": "ἦν δὲ τὸ μὲν εἶδος ὑπόπυρρος καὶ γλαυκός, ὡς ὁ ποιήσας τὸ ἐπιγραμμάτιον οὐκ εὐμενῶς παρεμφαίνει", "st": "Cat. Ma. 1.3"}, {"sp": "N", "t": "πυρρόν, πανδακέτην, γλαυκόμματον, οὐδὲ θανόντα<br>Πόρκιον εἰς ἀίδην Φερσεφόνη δέχεται.", "st": "Cat. Ma. 1.3b"}, {"sp": "N", "t": "τὴν δὲ τοῦ σώματος ἕξιν αὐτουργίᾳ καὶ διαίτῃ σώφρονι καὶ στρατείαις ἀπ’ ἀρχῆς συντρόφου γεγονότος πάνυ χρηστικὴν εἶχε, καὶ πρὸς ἰσχὺν καὶ πρὸς ὑγίειαν ὁμαλῶς συνεστῶσαν. τὸν δὲ λόγον, ὥσπερ δεύτερον σῶμα καὶ τῶν καλῶν, οὐ μόνον τῶν ἀναγκαίων ὄργανον ἀνδρὶ μὴ ταπεινῶς βιωσομένῳ μηδ’ ἀπράκτως, ἐξηρτύετο καὶ παρεσκεύαζεν ἐν ταῖς περιοικίσι κώμαις καὶ τοῖς πολιχνίοις ἑκάστοτε συνδικῶν τοῖς δεομένοις καὶ πρῶτον μὲν ἀγωνιστὴς εἶναι δοκῶν πρόθυμος, εἶτα καὶ ῥήτωρ ἱκανός, ἐκ δὲ τούτου μᾶλλον τοῖς χρωμένοις κατεφαίνετο βάρος τι καὶ φρόνημα περὶ αὐτὸν ἤθους πραγμάτων μεγάλων καὶ πολιτείας δεόμενον ἡγεμονικῆς. οὐ γὰρ μόνον, ὡς ἔοικε, μισθαρνίας καθαρὸν ἑαυτὸν ἐπὶ τὰς δίκας καὶ τοὺς ἀγῶνας παρεῖχεν, ἀλλ’ οὐδὲ τὴν δόξαν ὡς μέγιστον ἀγαπῶν ἐφαίνετο τὴν ἀπὸ τῶν τοιούτων ἀγώνων, πολὺ δὲ μᾶλλον ἐν ταῖς μάχαις ταῖς πρὸς τοὺς πολεμίους καὶ ταῖς στρατείαις βουλόμενος εὐδοκιμεῖν ἔτι μειράκιον ὢν τραυμάτων τὸ σῶμα μεστὸν ἐναντίων εἶχε. φησὶ γὰρ αὐτὸς ἑπτακαίδεκα γεγονὼς ἔτη τὴν πρώτην στρατεύσασθαι στρατείαν περὶ ὃν Ἀννίβας χρόνον εὐτυχῶν ἐπέφλεγε τὴν Ἰταλίαν.", "st": "Cat. Ma. 1.4"}, {"sp": "N", "t": "παρεῖχε δ’ αὑτὸν ἐν ταῖς μάχαις τῇ μὲν χειρὶ πλήκτην, τῷ δὲ ποδὶ μόνιμον καὶ βέβαιον, γαῦρον δὲ τῷ προσώπῳ· λόγου δ’ ἀπειλῇ καὶ τραχύτητι φωνῆς πρὸς τοὺς πολεμίους ἐχρῆτο, ὀρθῶς καὶ διανοούμενος καὶ διδάσκων, ὅτι πολλάκις τὰ τοιαῦτα τοῦ ξίφους μᾶλλον καταπλήττεται τοὺς ἐναντίους. ἐν δὲ ταῖς πορείαις αὐτὸς ἐβάδιζε φέρων τὰ ὅπλα, καὶ θεράπων εἷς εἵπετο τὰ πρὸς δίαιταν αὐτῷ κομίζων, ᾧ λέγεται μηδέποτε δυσκολᾶναι μηδὲ μέμψασθαι παραθέντι ἄριστον ἢ δεῖπνον, ἀλλὰ καὶ συλλαμβάνειν αὐτὸς τὰ πλεῖστα καὶ συμπαρασκευάζειν ἀπὸ τῶν στρατιωτικῶν γενόμενος ἔργων, ὕδωρ δ’ ἔπινεν ἐπὶ στρατείας, πλὴν εἴποτε διψήσας περιφλεγῶς ὄξος αἰτήσειεν ἢ τῆς ἰσχύος ἐνδιδούσης ἐπιλάβοι μικρὸν οἰνάριον.", "st": "Cat. Ma. 1.7"}, {"sp": "N", "t": "ἦν δὲ πλησίον αὐτοῦ τῶν ἀγρῶν ἡ γενομένη Μανίου Κουρίου τοῦ τρὶς θριαμβεύσαντος ἔπαυλις. ἐπὶ ταύτην συνεχῶς βαδίζων καὶ θεώμενος τοῦ τε χωρίου τὴν μικρότητα καὶ τῆς οἰκήσεως τὸ λιτόν, ἔννοιαν ἐλάμβανε τοῦ ἀνδρὸς, ὅτι Ῥωμαίων μέγιστος γενόμενος καὶ τὰ μαχιμώτατα τῶν ἐθνῶν ὑπαγαγόμενος καὶ Πύρρον ἐξελάσας τῆς Ἰταλίας τοῦτο τὸ χωρίδιον αὐτὸς ἔσκαπτε καὶ ταύτην τὴν ἔπαυλιν ᾤκει μετὰ τρεῖς θριάμβους. ἐνταῦθα πρὸς ἐσχάρᾳ καθήμενον αὐτὸν ἕψοντα γογγυλίδας εὑρόντες οἱ Σαυνιτῶν πρέσβεις ἐδίδοσαν πολὺ χρυσίον· ὁ δ’ ἀπεπέμψατο φήσας οὐδὲν χρυσίου δεῖν ᾧ δεῖπνον ἀρκεῖ τοιοῦτον, αὐτῷ μέντοι τοῦ χρυσίον ἔχειν κάλλιον εἶναι τὸ νικᾶν τοὺς ἔχοντας. ταῦθ’ ὁ Κάτων ἐνθυμούμενος ἀπῄει, καὶ τὸν αὑτοῦ πάλιν οἶκον ἐφορῶν καὶ χωρία καὶ θεράποντας καὶ δίαιταν ἐπέτεινε τὴν αὐτουργίαν καὶ περιέκοπτε τὴν πολυτέλειαν.", "st": "Cat. Ma. 2.1"}, {"sp": "N", "t": "Φαβίου δὲ Μαξίμου τὴν Ταραντίνων πόλιν ἑλόντος ἔτυχε μὲν ὁ Κάτων στρατευόμενος ὑπ’ αὐτῷ κομιδῇ μειράκιον ὤν, Νεάρχῳ δέ τινι τῶν Πυθαγορικῶν ξένῳ χρησάμενος ἐσπούδασε τῶν λόγων μεταλαβεῖν. ἀκούσας δὲ ταῦτα διαλεγομένου τοῦ ἀνδρὸς, οἷς κέχρηται καὶ Πλάτων, τὴν μὲν ἡδονὴν ἀποκαλῶν μέγιστον κακοῦ δέλεαρ, συμφορὰν δὲ τῇ ψυχῇ τὸ σῶμα πρώτην, λύσιν δὲ καὶ καθαρμὸν οἷς μάλιστα χωρίζει καὶ ἀφίστησιν αὑτὴν τῶν περὶ τὸ σῶμα παθημάτων λογισμοῖς, ἔτι μᾶλλον ἠγάπησε τὸ λιτὸν καὶ τὴν ἐγκράτειαν. ἄλλως δὲ παιδείας Ἑλληνικῆς ὀψιμαθὴς γενέσθαι λέγεται, καὶ πόρρω παντάπασιν ἡλικίας ἐληλακὼς Ἑλληνικὰ βιβλία λαβὼν εἰς χεῖρας βραχέα μὲν ἀπὸ Θουκυδίδου, πλείονα δ’ ἀπὸ Δημοσθένους εἰς τὸ ῥητορικὸν ὠφεληθῆναι. τὰ μέντοι συγγράμματα καὶ δόγμασιν Ἑλληνικοῖς καὶ ἱστορίαις ἐπιεικῶς διαπεποίκιλται καὶ μεθηρμηνευμένα πολλὰ κατὰ λέξιν ἐν τοῖς ἀποφθέγμασι καὶ ταῖς γνωμολογίαις τέτακται.", "st": "Cat. Ma. 2.3"}, {"sp": "N", "t": "ἦν δέ τις ἀνὴρ εὐπατρίδης μὲν ἐν τοῖς μάλιστα Ῥωμαίων καί δυνατός, ἀρετὴν δὲ φυομένην μὲν αἰσθάνεσθαι δεινός, εὐμενὴς δὲ καί θρέψαι καί προαγαγεῖν εἰς δόξαν, Οὐαλλέριος Φλάκκος. οὗτος εἶχεν ὁμοροῦντα χωρία τοῖς Κάτωνος, πυθόμενος δὲ τὴν αὐτουργίαν καί δίαιταν αὐτοῦ παρὰ τῶν οἰκετῶν καί θαυμάσας ἐξηγουμένων, ὅτι πρωὶ μὲν εἰς ἀγορὰν βαδίζει καί παρίσταται τοῖς δεομένοις, ἐπανελθὼν δ’ εἰς τὸ χωρίον, ἂν μὲν ᾖ χειμὼν, ἐξωμίδα λαβών, θέρους δὲ γυμνὸς ἐργασάμενος μετὰ τῶν οἰκετῶν ἐσθίει τὸν αὐτὸν ἄρτον ὁμοῦ καθήμενος καί πίνει τὸν αὐτὸν οἶνον, ἄλλην τε πολλὴν ἐπιείκειαν αὐτοῦ καί μετριότητα καί τινας καί λόγους ἀποφθεγματικοὺς διαμνημονευόντων, ἐκέλευσε κληθῆναι πρὸς τὸ δεῖπνον. ἐκ δὲ τούτου χρώμενος καί κατανοῶν ἥμερον καί ἀστεῖον ἦθος, ὥσπερ φυτὸν ἀσκήσεως καί χώρας ἐπιφανοῦς δεόμενον, προετρέψατο καί συνέπεισεν ἅψασθαι τῆς ἐν Ῥώμῃ πολιτείας. κατελθὼν οὖν εὐθὺς τοὺς μὲν αὐτὸς ἐκτᾶτο θαυμαστὰς καὶ φίλους διὰ τῶν συνηγοριῶν, πολλὴν δὲ τοῦ Οὐαλλερίου τιμήν καὶ δύναμιν αὐτῷ προστιθέντος χιλιαρχίας ἔτυχε πρῶτον, εἶτα ἐταμίευσεν. ἐκ τούτου δὲ λαμπρὸς ὢν ἤδη καί περιφανής αὐτῷ τῷ Οὐαλλερίῳ περὶ τὰς μεγίστας συνεξέδραμεν ἀρχάς, ὕπατός τε μετ’ ἐκείνου καί πάλιν τιμητὴς γενόμενος.", "st": "Cat. Ma. 3.1"}, {"sp": "N", "t": "τῶν δὲ πρεσβυτέρων πολιτῶν Μαξίμῳ Φαβίῳ προσένειμεν ἑαυτόν, ἐνδοξοτάτῳ μὲν ὄντι καί μεγίστην ἔχοντι δύναμιν, μᾶλλον δὲ τὸν τρόπον αὐτοῦ καί τὸν βίον ὡς κάλλιστα παραδείγματα προθέμενος. διὸ καί Σκηπίωνι τῷ μεγάλῳ, νέῳ μὲν ὄντι τότε, πρὸς δὲ τὴν Φαβίου δύναμιν ἀνταίροντι καὶ φθονεῖσθαι δοκοῦντι, παρ’ οὐδὲν ἐποιήσατο γενέσθαι διάφορος, ἀλλὰ καί ταμίας αὐτῷ πρὸς τὸν ἐν Λιβύῃ πόλεμον συνεκπεμφθεὶς, ὡς ἑώρα τῇ συνήθει πολυτελείᾳ χρώμενον τὸν ἄνδρα καὶ καταχορηγοῦντα τοῖς στρατεύμασιν ἀφειδῶς τῶν χρημάτων, ἐπαρρησιάζετο πρὸς αὐτόν, οὐ τὸ τῆς δαπάνης μέγιστον εἶναι φάμενος, ἀλλ’ ὅτι διαφθείρει τὴν πάτριον εὐτέλειαν τῶν στρατιωτῶν ἐφ’ ἡδονὰς καί τρυφὰς τῷ περιόντι τῆς χρείας τρεπομένων. εἰπόντος δὲ τοῦ Σκηπίωνος, ὡς οὐδὲν δέοιτο ταμίου λίαν ἀκριβοῦς πλησίστιος ἐπὶ τὸν πόλεμον φερόμενος, πράξεων γάρ, οὐ χρημάτων, τῇ πόλει λόγον ὀφείλειν, ἀπῆλθεν ὁ Κάτων ἐκ Σικελίας, καί μετὰ τοῦ Φαβίου καταβοῶν ἐν τῷ συνεδρίῳ φθοράν τε χρημάτων ἀμυθήτων ὑπὸ τοῦ Σκηπίωνος καί διατριβὰς αὐτοῦ μειρακιώδεις ἐν παλαίστραις καί θεάτροις, ὥσπερ οὐ στρατηγοῦντος, ἀλλὰ πανηγυρίζοντος, ἐξειργάσατο πεμφθῆναι δημάρχους ἐπ’ αὐτὸν ἄξοντας εἰς Ῥώμην, ἄνπερ ἀληθεῖς αἱ κατηγορίαι φανῶσιν. ὁ μὲν οὖν Σκηπίων ἐν τῇ παρασκευῇ τοῦ πολέμου τὴν νίκην ἐπιδειξάμενος, καί φανεὶς ἡδὺς μὲν ἐπὶ σχολῆς συνεῖναι φίλοις, οὐδαμοῦ δὲ τῷ φιλανθρώπῳ τῆς διαίτης εἰς τὰ σπουδαῖα καί μεγάλα ῥᾴθυμος, ἐξέπλευσεν ἐπὶ τὸν πόλεμον.", "st": "Cat. Ma. 3.5"}, {"sp": "N", "t": "τῷ δὲ Κάτωνι πολλὴ μὲν ἀπὸ τοῦ λόγου δύναμις ηὔξητο, καὶ Ῥωμαῖον αὐτὸν οἱ πολλοὶ Δημοσθένην προσηγόρευον, ὁ δὲ βίος μᾶλλον ὀνομαστὸς ἦν αὐτοῦ καὶ περιβόητος, ἡ μὲν γὰρ ἐν τῷ λέγειν δεινότης προὔκειτο τοῖς νέοις ἀγώνισμα κοινὸν ἤδη καὶ περισπούδαστον, ὁ δὲ τὴν πάτριον αὐτουργίαν ὑπομένων καὶ δεῖπνον ἀφελὲς καὶ ἄριστον ἄπυρον καὶ λιτὴν ἐσθῆτα καὶ δημοτικὴν ἀσπαζόμενος οἴκησιν καὶ τὸ μὴ δεῖσθαι τῶν περιττῶν μᾶλλον ἢ τὸ κεκτῆσθαι θαυμάζων σπάνιος ἦν, ἤδη τότε τῆς πολιτείας τὸ καθαρὸν ὑπὸ μεγέθους οὐ φυλαττούσης, ἀλλὰ τῷ κρατεῖν πραγμάτων πολλῶν καὶ ἀνθρώπων πρὸς πολλὰ μιγνυμένης ἔθη καὶ βίων παραδείγματα παντοδαπῶν ὑποδεχομένης. εἰκότως οὖν ἐθαύμαζον τὸν Κάτωνα, τοὺς μὲν ἄλλους ὑπὸ τῶν πόνων θραυομένους καὶ μαλασσομένους ὑπὸ τῶν ἡδονῶν ὁρῶντες, ἐκεῖνον δὲ ὑπ’ ἀμφοῖν ἀήττητον, οὐ μόνον ἕως ἔτι νέος καὶ φιλότιμος ἦν, ἀλλὰ καὶ γέροντα καὶ πολιὸν ἤδη μεθ’ ὑπατείαν καὶ θρίαμβον, ὥσπερ ἀθλητὴν νικηφόρον, ἐγκαρτεροῦντα τῇ τάξει τῆς ἀσκήσεως καὶ διομαλίζοντα μέχρι τῆς τελευτῆς.", "st": "Cat. Ma. 4.1"}, {"sp": "N", "t": "ἐσθῆτα μὲν γὰρ οὐδέποτέ φησι φορέσαι πολυτελεστέραν ἑκατὸν δραχμῶν, πιεῖν δὲ καὶ στρατηγῶν καὶ ὑπατεύων τὸν αὐτὸν οἶνον τοῖς ἐργάταις, ὄψον δὲ παρασκευάζεσθαι πρὸς τὸ δεῖπνον ἐξ ἀγορᾶς ἀσσαρίων τριάκοντα, καὶ τοῦτο διὰ τὴν πόλιν, ὅπως ἰσχύοι τὸ σῶμα πρὸς τὰς στρατείας. ἐπίβλημα δὲ τῶν ποικίλων Βαβυλώνιον ἐκ κληρονομίας κτησάμενος εὐθὺς ἀποδόσθαι, τῶν δὲ ἐπαύλεων αὐτοῦ μηδεμίαν εἶναι κεκονιαμένην, οὐδένα δὲ πώποτε πρίασθαι δοῦλον ὑπὲρ τὰς χιλίας δραχμὰς καὶ πεντακοσίας, ὡς ἂν οὐ τρυφερῶν οὐδ’ ὡραίων, ἀλλ’ ἐργατικῶν καὶ στερεῶν, οἷον ἱπποκόμων καὶ βοηλατῶν, δεόμενος καὶ τούτους δὲ πρεσβυτέρους γενομένους ᾤετο δεῖν ἀποδίδοσθαι καὶ μὴ βόσκειν ἀχρήστους. ὅλως δὲ μηδὲν εὔωνον εἶναι τῶν περιττῶν, ἀλλ’ οὗ τις οὐ δεῖται, κἂν ἀσσαρίου πιπράσκηται, πολλοῦ νομίζειν· κτᾶσθαι δὲ τὰ σπειρόμενα καὶ νεμόμενα μᾶλλον ἢ τὰ ῥαινόμενα καὶ σαιρόμενα.", "st": "Cat. Ma. 4.4"}, {"sp": "N", "t": "ταῦτα δ’ οἱ μὲν εἰς μικρολογίαν ἐτίθεντο τοῦ ἀνδρός, οἱ δ’ ὡς ἐπὶ διορθώσει καὶ σωφρονισμῷ τῶν ἄλλων ἐνδοτέρω συστέλλοντος ἑαυτὸν ἀπεδέχοντο. πλὴν τὸ τοῖς οἰκέταις ὡς ὑποζυγίοις ἀποχρησάμενον ἐπὶ γήρως ἐλαύνειν καὶ πιπράσκειν ἀτενοῦς ἄγαν ἤθους ἔγωγε τίθεμαι, καὶ μηδὲν ἀνθρώπῳ πρὸς ἄνθρωπον οἰομένου κοινώνημα τῆς χρείας πλέον ὑπάρχειν. καίτοι τὴν χρηστότητα τῆς δικαιοσύνης πλατύτερον τόπον ὁρῶμεν ἐπιλαμβάνουσαν νόμῳ μὲν γὰρ καὶ τῷ δικαίῳ πρὸς ἀνθρώπους μόνον χρῆσθαι πεφύκαμεν, πρὸς εὐεργεσίας δὲ καὶ χάριτας ἔστιν ὅτε καὶ μέχρι τῶν ἀλόγων ζῴων ὥσπερ ἐκ πηγῆς πλουσίας ἀπορρεῖ τῆς ἡμερότητος. καὶ γὰρ ἵππων ἀπειρηκότων ὑπὸ χρόνου τροφαὶ καὶ κυνῶν οὐ σκυλακεῖαι μόνον, ἀλλὰ καὶ γηροκομίαι τῷ χρηστῷ προσήκουσιν.", "st": "Cat. Ma. 5.1"}, {"sp": "N", "t": "ὁ δὲ τῶν Ἀθηναίων δῆμος οἰκοδομῶν τὸν Ἑκατόμπεδον, ὅσας κατενόησεν ἡμιόνους μάλιστα τοῖς πόνοις ἐγκαρτερούσας, ἀπέλυσεν ἐλευθέρας νέμεσθαι καὶ ἀφέτους, ὧν μίαν φασὶ καταβαίνουσαν ἀφ’ ἑαυτῆς πρὸς τὰ ἔργα τοῖς ἀνάγουσι τὰς ἁμάξας ὑποζυγίοις εἰς ἀκρόπολιν συμπαρατρέχειν καὶ προηγεῖσθαι καθάπερ ἐγκελευομένην καὶ συνεξορμῶσαν, ἣν καὶ τρέφεσθαι δημοσίᾳ μέχρι τελευτῆς ἐψηφίσαντο. τῶν δὲ Κίμωνος ἵππων, αἷς Ὀλύμπια τρὶς ἐνίκησε, καὶ ταφαὶ πλησίον εἰσὶ τῶν ἐκείνου μνημάτων, κύνας δὲ συντρόφους γενομένους καὶ συνήθεις ἄλλοι τε πολλοὶ καὶ Ξάνθιππος ὁ παλαιὸς τὸν εἰς Σαλαμῖνα τῇ τριήρει παρανηξάμενον, ὅτε τὴν πόλιν ὁ δῆμος ἐξέλειπεν, ἐπὶ τῆς ἄκρας ἐκήδευσεν, ἣν Κυνὸς σῆμα μέχρι νῦν καλοῦσιν.", "st": "Cat. Ma. 5.3"}, {"sp": "N", "t": "οὐ γὰρ ὡς ὑποδήμασιν ἢ σκεύεσι τοῖς ψυχὴν ἔχουσι χρηστέον, κοπέντα καὶ κατατριβέντα ταῖς ὑπηρεσίαις ἀπορριπτοῦντας, ἀλλ’ εἰ διὰ μηδὲν ἄλλο, μελέτης ἕνεκα τοῦ φιλανθρώπου προεθιστέον ἑαυτὸν ἐν τούτοις πρᾷον εἶναι καὶ μείλιχον. ἐγὼ μὲν οὖν οὐδὲ βοῦν ἂν ἐργάτην διὰ γῆρας ἀποδοίμην, μή τί γε πρεσβύτερον ἄνθρωπον, ἐκ χώρας συντρόφου καὶ διαίτης συνήθους ὥσπερ ἐκ πατρίδος μεθιστάμενον ἀντὶ κερμάτων μικρῶν, ἄχρηστόν γε τοῖς ὠνουμένοις ὥσπερ τοῖς πιπράσκουσι γενησόμενον. ὁ δὲ Κάτων ὥσπερ νεανιευόμενος ἐπὶ τούτοις καὶ τὸν ἵππον, ᾧ παρὰ τὰς στρατείας ὑπατεύων ἐχρῆτο, φησὶν ἐν Ἰβηρίᾳ καταλιπεῖν, ἵνα μὴ τῇ πόλει τὸ ναῦλον αὐτοῦ λογίσηται. ταῦτα μὲν οὖν εἴτε μεγαλοψυχίας εἴτε μικρολογίας θετέον, ἔξεστι τῷ πείθοντι χρῆσθαι λογισμῷ.", "st": "Cat. Ma. 5.5"}, {"sp": "N", "t": "τῆς δ’ ἄλλης ἐγκρατείας ὑπερφυῶς θαυμαστὸς ὁ ἀνήρ· οἷον ὅτι στρατηγῶν ἐλάμβανεν ἑαυτῷ καὶ τοῖς περὶ αὑτὸν οὐ πλέον εἰς τὸν μῆνα πυρῶν ἢ τρεῖς Ἀττικοὺς μεδίμνους, εἰς δὲ τὴν ἡμέραν κριθῶν τοῖς ὑποζυγίοις ἔλαττον τριῶν ἡμιμεδίμνων. ἐπαρχίαν δὲ λαβὼν Σαρδόνα, τῶν πρὸ αὐτοῦ στρατηγῶν εἰωθότων χρῆσθαι καὶ σκηνώμασι δημοσίοις καὶ κλίναις καὶ ἱματίοις, πολλῇ δὲ θεραπείᾳ καὶ φίλων πλήθει καὶ περὶ δεῖπνα δαπάναις καὶ παρασκευαῖς βαρυνόντων, ἐκεῖνος ἄπιστον ἐποίησε τὴν διαφορὰν τῆς εὐτελείας, δαπάνης μὲν γὰρ εἰς οὐδὲν οὐδεμιᾶς προσεδεήθη δημοσίας, ἐπεφοίτα δὲ ταῖς πόλεσιν αὐτὸς μὲν ἄνευ ζεύγους πορευόμενος, εἷς δὲ ἠκολούθει δημόσιος ἐσθῆτα καὶ σπονδεῖον αὐτῷ πρὸς ἱερουργίαν κομίζων. ἐν δὲ τούτοις οὕτως εὔκολος καὶ ἀφελὴς τοῖς ὑπὸ χεῖρα φαινόμενος, αὖθις ἀνταπεδίδου τὴν σεμνότητα καὶ τὸ βάρος ἀπαραίτητος ὢν ἐν τῷ δικαίῳ καὶ τοῖς ὑπὲρ τῆς ἡγεμονίας προστάγμασιν ὄρθιος καὶ αὐθέκαστος, ὥστε μηδέποτε τὴν Ῥωμαίων ἀρχὴν ἐκείνοις μήτε φοβερωτέραν μήτε προσφιλεστέραν γενέσθαι.", "st": "Cat. Ma. 6.1"}, {"sp": "N", "t": "τοιαύτην δέ τινα φαίνεται καὶ ὁ λόγος τοῦ ἀνδρὸς ἰδέαν ἔχειν εὔχαρις γὰρ ἅμα καὶ δεινὸς ἦν, ἡδὺς καὶ καταπληκτικός, φιλοσκώμμων καὶ αὐστηρός, ἀποφθεγματικὸς καὶ ἀγωνιστικός, ὥσπερ ὁ Πλάτων τὸν Σωκράτην φησὶν ἔξωθεν ἰδιώτην καὶ σατυρικὸν καὶ ὑβριστὴν τοῖς ἐντυγχάνουσι φαινόμενον ἔνδοθεν σπουδῆς καὶ πραγμάτων μεστὸν εἶναι δάκρυα κινούντων τοῖς ἀκροωμένοις καὶ τὴν καρδίαν στρεφόντων. ὅθεν οὐκ οἶδ’ ὅτι πεπόνθασιν οἱ τῷ Λυσίου λόγῳ μάλιστα φάμενοι προσεοικέναι τὸν Κάτωνος, οὐ μὴν ἀλλὰ ταῦτα μὲν οἷς μᾶλλον ἰδέας λόγων Ῥωμαϊκῶν αἰσθάνεσθαι προσήκει διακρινοῦσιν, ἡμεῖς δὲ τῶν ἀπομνημονευομένων βραχέα γράψομεν, οἳ τῷ λόγῳ πολὺ μᾶλλον ἢ τῷ προσώπῳ, καθάπερ ἔνιοι νομίζουσι, τῶν ἀνθρώπων φαμὲν ἐμφαίνεσθαι τὸ ἦθος.", "st": "Cat. Ma. 7.1"}, {"sp": "N", "t": "μέλλων ποτὲ τὸν Ῥωμαίων δῆμον ὡρμημένον ἀκαίρως ἐπὶ σιτομετρίας καὶ διανομὰς ἀποτρέπειν, ἤρξατο τῶν λόγων οὕτως· χαλεπὸν μέν ἐστιν, ὦ πολῖται, πρὸς γαστέρα λέγειν ὦτα οὐκ ἔχουσαν. Κατηγορῶν δὲ τῆς πολυτελείας ἔφη χαλεπὸν εἶναι σωθῆναι πόλιν, ἐν ᾗ πωλεῖται πλείονος ἰχθὺς ἢ βοῦς. ἐοικέναι δὲ προβάτοις ἔφη τοὺς Ῥωμαίους· ὡς γὰρ ἐκεῖνα καθ’ ἕκαστον μέν οὐ πείθεται, σύμπαντα δ’ ἕπεται μετ’ ἀλλήλων τοῖς ἄγουσιν, οὕτω καὶ ὑμεῖς, εἶπεν, οἷς οὐκ ἂν ἀξιώσαιτε συμβούλοις χρήσασθαι κατ’ ἰδίαν, ὑπὸ τούτων εἰς ἓν συνελθόντες ἄγεσθε. Περὶ δὲ τῆς γυναικοκρατίας διαλεγόμενος πάντες, εἶπεν, ἄνθρωποι τῶν γυναικῶν ἄρχουσιν, ἡμεῖς δὲ πάντων ἀνθρώπων, ἡμῶν δὲ αἱ γυναῖκες. τοῦτο μέν οὖν ἐστιν ἐκ τῶν Θεμιστοκλέους μετενηνεγμένον ἀποφθεγμάτων, ἐκεῖνος γὰρ ἐπιτάττοντος αὐτῷ πολλὰ τοῦ υἱοῦ διὰ τῆς μητρός ὦ γύναι, εἶπεν, Ἀθηναῖοι μέν ἄρχουσι τῶν Ἑλλήνων, ἐγὼ δὲ Ἀθηναίων, ἐμοῦ δὲ σύ, σοῦ δὲ ὁ υἱός, ὥστε φειδέσθω τῆς ἐξουσίας, δι’ ἣν ἀνόητος ὢν πλεῖστον Ἑλλήνων δύναται.", "st": "Cat. Ma. 8.1"}, {"sp": "N", "t": "τὸν δὲ δῆμον ὁ Κάτων ἔφη τῶν Ῥωμαίων οὐ μόνον ταῖς πορφύραις, ἀλλὰ καὶ τοῖς ἐπιτηδεύμασι τὰς τιμὰς ἐπιγράφειν. ὡς γὰρ οἱ βαφεῖς, ἔφη, ταύτην μάλιστα βάπτουσιν, ᾗ χαίροντας ὁρῶσιν, οὕτως οἱ νέοι ταῦτα μανθάνουσι καὶ ζηλοῦσιν, οἷς ἂν ὁ παρ’ ὑμῶν ἔπαινος ἕπηται παρεκάλει δ’ αὐτούς, εἰμὲν ἀρετῇ καὶ σωφροσύνῃ γεγόνασι μεγάλοι, μηδὲν μεταβάλλεσθαι πρὸς τὸ χεῖρον, εἰ δ’ ἀκρασίᾳ καὶ κακίᾳ, μεταβάλλεσθαι πρὸς τὸ βέλτιον ἱκανῶς γὰρ ἤδη μεγάλους ἀπ’ ἐκείνων γεγονέναι. τοὺς δὲ πολλάκις ἄρχειν σπουδάζοντας ἔφη καθάπερ ἀγνοοῦντας τὴν ὁδὸν ἀεὶ μετὰ ῥαβδούχων ζητεῖν πορεύεσθαι, μὴ πλανηθῶσιν. ἐπετίμα δὲ τοῖς πολίταις Τοὺς αὐτοὺς αἱρουμένοις πολλάκις ἄρχοντας. δόξετε γάρ, ἔφη, μὴ πολλοῦ τὸ ἄρχειν ἄξιον ἢ μὴ πολλοὺς τοῦ ἄρχειν ἀξίους ἡγεῖσθαι. Περὶ δὲ τῶν ἐχθρῶν τινος αἰσχρῶς καὶ ἀδόξως βιοῦν δοκοῦντος ἡ τούτου μήτηρ, ἔφη, κατάραν, οὐκ εὐχήν, ἡγεῖται τὸ τοῦτον ὑπὲρ γῆς ἀπολιπεῖν. τὸν δὲ πεπρακότα Τοὺς πατρῴους ἀγροὺς παραλίους ὄντας ἐπιδεικνύμενος προσεποιεῖτο θαυμάζειν ὡς ἰσχυρότερον τῆς θαλάττης· ἃ γὰρ ἐκείνη μόλις ἔκλυζεν, οὗτος, ἔφη, ῥᾳδίως καταπέπωκεν.", "st": "Cat. Ma. 8.4"}, {"sp": "N", "t": "ἐπεὶ δὲ Εὐμένους τοῦ βασιλέως ἐπιδημήσαντος εἰς Ῥώμην ἥ τε σύγκλητος ὑπερφυῶς ἀπεδέξατο καὶ τῶν πρώτων ἅμιλλα καὶ σπουδὴ Περὶ αὐτὸν ἐγίνετο, δῆλος ἦν ὁ Κάτων ὑφορώμενος καὶ φυλαττόμενος αὐτόν. εἰπόντος δέ τινος ἀλλὰ μὴν χρηστός ἐστι καὶ φιλορρώμαιος, ἔστω, εἶπεν, ἀλλὰ φύσει τοῦτο τὸ ζῷον ὁ βασιλεὺς σαρκοφάγον ἐστιν. οὐδένα δὲ τῶν εὐδαιμονιζομένων ἔφη βασιλέων ἄξιον εἶναι παραβάλλειν πρὸς Ἐπαμεινώνδαν ἢ Περικλέα ἢ Θεμιστοκλέα ἢ Μάνιον Κούριον ἢ Ἀμίλκαν τὸν ἐπικληθέντα Βάρκαν. αὑτῷ δ’ ἔλεγε Τοὺς ἐχθροὺς φθονεῖν, ὅτι καθ’ ἡμέραν ἐκ νυκτὸς ἀνίσταται καὶ τῶν ἰδίων ἀμελῶν τοῖς δημοσίοις σχολάζει, βούλεσθαι δ’ ἔλεγε μᾶλλον εὖ πράξας ἀποστερηθῆναι χάριν ἢ κακῶς μὴ τυχεῖν κολάσεως, καὶ συγγνώμην ἔφη διδόναι πᾶσι τοῖς ἁμαρτάνουσι πλὴν αὑτοῦ.", "st": "Cat. Ma. 8.8"}, {"sp": "N", "t": "τῶν δὲ Ῥωμαίων εἰς Βιθυνίαν τρεῖς ἑλομένων πρέσβεις, ὧν ὁ μὲν ποδαγρικὸς ἦν, ὁ δὲ τὴν κεφαλὴν ἐξ ἀνατρήσεως καὶ περικοπῆς κοίλην εἶχεν, ὁ δὲ τρίτος ἐδόκει μωρὸς εἶναι, καταγελῶν ὁ Κάτων εἶπε πρεσβείαν ὑπὸ Ῥωμαίων ἀποστέλλεσθαι μήτε πόδας μήτε κεφαλὴν μήτε καρδίαν ἔχουσαν. ὑπὲρ δὲ τῶν ἐξ Ἀχαΐας φυγάδων ἐντευχθεὶς διὰ Πολύβιον ὑπὸ Σκηπίωνος, ὡς πολὺς ἐν τῇ συγκλήτῳ λόγος ἐγίνετο, τῶν μὲν διδόντων κάθοδον αὐτοῖς, τῶν δ’ ἐνισταμένων, ἀναστὰς ὁ Κάτων ὥσπερ οὐκ ἔχοντες, εἶπεν, ὃ πράττωμεν καθήμεθα τὴν ἡμέραν ὅλην περὶ γεροντίων Γραικῶν ζητοῦντες, πότερον ὑπὸ τῶν παρ’ ἡμῖν ἢ τῶν ἐν Ἀχαΐᾳ νεκροφόρων ἐκκομισθῶσι. ψηφισθείσης δὲ τῆς καθόδου τοῖς ἀνδράσιν, ἡμέρας ὀλίγας οἱ περὶ Τὸν Πολύβιον διαλιπόντες αὖθις ἐπεχείρουν εἰς τὴν σύγκλητον εἰσελθεῖν, ὅπως ἃς πρότερον εἶχον ἐν Ἀχαΐᾳ τιμὰς οἱ φυγάδες ἀναλάβοιεν, καὶ τοῦ Κάτωνος ἀπεπειρῶντο τῆς γνώμης, ὁ δὲ μειδιάσας ἔφη τὸν Πολύβιον, ὥσπερ Τὸν Ὀδυσσέα, βούλεσθαι πάλιν εἰς τὸ Τοῦ Κύκλωπος σπήλαιον εἰσελθεῖν, τὸ πιλίον ἐκεῖ καὶ τὴν ζώνην ἐπιλελησμένον.", "st": "Cat. Ma. 9.1"}, {"sp": "N", "t": "τοὺς δὲ φρονίμους ἔλεγε μᾶλλον ὑπὸ τῶν ἀφρόνων ἢ τοὺς ἄφρονας ὑπὸ τῶν φρονίμων ὠφελεῖσθαι· τούτους μὲν γὰρ φυλάττεσθαι τὰς ἐκείνων ἁμαρτίας, ἐκείνους δὲ τὰς τούτων μὴ μιμεῖσθαι κατορθώσεις, τῶν δὲ νέων ἔφη χαίρειν τοῖς ἐρυθριῶσι μᾶλλον ἢ τοῖς ὠχριῶσι, στρατιώτου δὲ μὴ δεῖσθαι τὰς μὲν χεῖρας ἐν τῷ βαδίζειν, τοὺς δὲ πόδας ἐν τῷ μάχεσθαι κινοῦντος, μεῖζον δὲ ῥέγχοντος ἢ ἀλαλάζοντος. τὸν δὲ ὑπέρπαχυν κακίζων ποῦ δ’ ἄν, ἔφη, σῶμα τοιοῦτόν τῇ πόλει γένοιτο χρήσιμον, οὗ τὸ μεταξὺ λαιμοῦ καὶ βουβώνων πᾶν ὑπὸ τῆς γαστρὸς κατέχεται; τῶν δὲ φιληδόνων τινὰ βουλόμενον αὐτῷ συνεῖναι παραιτούμενος, ἔφη μὴ δύνασθαι ζῆν μετ’ ἀνθρώπου τῆς καρδίας τὴν ὑπερῴαν εὐαισθητοτέραν ἔχοντος, Τοῦ δ’ ἐρῶντος ἔλεγε τὴν ψυχὴν ἐν ἀλλοτρίῳ σώματι ζῆν. Μεταμεληθῆναι δ’ αὐτὸς ἐν παντὶ τῷ βίῳ τρεῖς μεταμελείας· μίαν μὲν ἐπὶ τῷ γυναικὶ πιστεῦσαι λόγον ἀπόρρητον, ἑτέραν δὲ πλεύσας ὅπου δυνατὸν ἦν πεζεῦσαι, τὴν δὲ τρίτην, ὅτι μίαν ἡμέραν ἀδιάθετος ἔμεινε, Πρὸς δὲ πρεσβύτην πονηρευόμενον ἄνθρωπε, εἶπε, πολλὰ ἔχοντι τῷ γήρᾳ τὰ αἰσχρὰ μὴ προστίθει τὴν ἀπὸ τῆς κακίας αἰσχύνην. πρὸς δὲ δήμαρχον ἐν διαβολῇ μὲν φαρμακείας γενόμενον, φαῦλον δὲ νόμον εἰσφέροντα καὶ βιαζόμενον ὦ μειράκιον, εἶπεν, οὐκ οἶδα, πότερον χεῖρόν ἐστιν ὃ κίρνης πιεῖν ἢ ὃ γράφεις κυρῶσαι. Βλασφημούμενος δ’ ὑπ’ ἀνθρώπου βεβιωκότος ἀσελγῶς καὶ κακῶς ἄνισος, εἶπεν, ἡ πρὸς σέ μοι μάχη ἐστί· καὶ γὰρ ἀκούεις τὰ κακὰ ῥᾳδίως καὶ λέγεις εὐχερῶς, ἐμοὶ δὲ καὶ λέγειν ἀηδὲς καὶ ἀκούειν ἄηθες.", "st": "Cat. Ma. 9.4"}, {"sp": "N", "t": "τὸ μὲν οὖν τῶν ἀπομνημονευμάτων γένος τοιοῦτόν ἐστιν.", "st": "Cat. Ma. 9.4b"}, {"sp": "N", "t": "ὕπατος δὲ μετὰ Φλάκκου Οὐαλλερίου τοῦ φίλου καὶ συνήθους ἀποδειχθείς ἔλαχε τῶν ἐπαρχιῶν ἣν Ἐντὸς Ἱσπανίαν Ῥωμαῖοι καλοῦσιν. ἐνταῦθα δ’ αὐτῷ τὰ μέν καταστρεφομένῳ τῶν ἐθνῶν, τὰ δ’ οἰκειουμένῳ διὰ λόγων πολλὴ στρατιὰ τῶν βαρβάρων ἐπέπεσε, καὶ κίνδυνος ἦν αἰσχρῶς ἐκβιασθῆναι. διὸ τῶν ἐγγὺς Κελτιβήρων ἐπεκαλεῖτο συμμαχίαν. αἰτούντων δ’ ἐκείνων τῆς βοηθείας διακόσια τάλαντα μισθόν, οἱ μέν ἄλλοι πάντες οὐκ ἀνασχετὸν ἐποιοῦντο Ῥωμαίους βαρβάροις ἐπικουρίας ὁμολογῆσαι μισθόν, ὁ δὲ Κάτων οὐδὲν ἔφη δεινὸν εἶναι, νικῶντας μέν γὰρ ἀποδώσειν παρὰ τῶν πολεμίων, οὐ παρ’ αὑτῶν, ἡττωμένων δὲ μήτε τοὺς ἀπαιτουμένους ἔσεσθαι μήτε τοὺς ἀπαιτοῦντας, ταύτην δὲ τὴν μάχην κατὰ κράτος ἐνίκησε, καὶ τἆλλα προὐχώρει λαμπρῶς. Πολύβιος μέν γέ φησι τῶν ἐντὸς Βαίτιος ποταμοῦ πόλεων ἡμέρᾳ μιᾷ τὰ τείχη κελεύσαντος αὐτοῦ περιαιρεθῆναι· πάμπολλαι δ’ ἦσαν αὗται καί γέμουσαι μαχίμων ἀνδρῶν. αὐτὸς δέ φησιν ὁ Κάτων πλείονας εἰληφέναι πόλεις ὧν διήγαγεν ἡμερῶν ἐν Ἰβηρίᾳ· καὶ τοῦτο κόμπος οὐκ ἔστιν, εἴπερ ὡς ἀληθῶς τετρακόσιαι τὸ πλῆθος ἦσαν.", "st": "Cat. Ma. 10.1"}, {"sp": "N", "t": "τοῖς μέν οὖν στρατιώταις πολλὰ παρὰ τὴν στρατείαν ὠφεληθεῖσιν ἔτι καὶ λίτραν ἀργυρίου κατ’ ἄνδρα προσδιένειμεν, εἰπὼν ὡς κρεῖττον εἴη πολλοὺς Ῥωμαίων ἀργύριον ἢ χρυσίον ὀλίγους ἔχοντας ἐπανελθεῖν. εἷς δ’ αὑτὸν ἐκ τῶν ἁλισκομένων οὐδὲν ἐλθεῖν λέγει πλὴν ὅσα πέπωκεν ἢ βέβρωκε. καὶ οὐκ αἰτιῶμαι, φησί, τοὺς ὠφελεῖσθαι ζητοῦντας ἐκ τούτων, ἀλλὰ βούλομαι μᾶλλον περὶ ἀρετῆς τοῖς ἀρίστοις ἢ περὶ χρημάτων τοῖς πλουσιωτάτοις ἁμιλλᾶσθαι καὶ τοῖς φιλαργυρωτάτοις περὶ φιλαργυρίας. οὐ μόνον δ’ αὑτόν, ἀλλὰ καὶ τοὺς περὶ αὑτὸν ἐφύλαττε καθαροὺς παντὸς λήμματος. ἦσαν δὲ πέντε θεράποντες ἐπὶ στρατείας σὺν αὐτῷ. τούτων εἷς ὄνομα Πάκκιος ἠγόρασε τῶν αἰχμαλώτων τρία παιδάρια· τοῦ δὲ Κάτωνος αἰσθομένου, πρὶν εἷς ὄψιν ἐλθεῖν, ἀπήγξατο. τοὺς δὲ παῖδας ὁ Κάτων ἀποδόμενος εἷς τὸ δημόσιον ἀνήνεγκε τὴν τιμήν.", "st": "Cat. Ma. 10.4"}, {"sp": "N", "t": "ἔτι δ’ αὐτοῦ διατρίβοντος ἐν Ἰβηρίᾳ Σκηπίων ὁ μέγας, ἐχθρὸς ὢν καὶ βουλόμενος ἐνστῆναι κατορθοῦντι καὶ τὰς Ἰβηρικὰς πράξεις ὑπολαβεῖν, διεπράξατο τῆς ἐπαρχίας ἐκείνης ἀποδειχθῆναι διάδοχος. σπεύσας δ’ ὡς ἐνῆν τάχιστα κατέπαυσε τὴν ἀρχὴν τοῦ Κάτωνος, ὁ δὲ λαβὼν σπείρας ὁπλιτῶν πέντε καὶ πεντακοσίους ἱππεῖς προπομπούς κατεστρέψατο μὲν τὸ Λακετανῶν ἔθνος, ἑξακοσίους δὲ τῶν ηὐτομοληκότων κομισάμενος ἀπέκτεινεν. ἐφ’ οἷς σχετλιάζοντα τὸν Σκηπίωνα κατειρωνευόμενος οὕτως ἔφη τὴν Ῥώμην ἔσεσθαι μεγίστην, τῶν μὲν ἐνδόξων καὶ μεγάλων τὰ τῆς ἀρετῆς πρωτεῖα μὴ μεθιέντων τοῖς ἀσημοτέροις, τῶν δ’ ὥσπερ αὐτός ἐστι δημοτικῶν ἁμιλλωμένων ἀρετῇ πρὸς τοὺς τῷ γένει καὶ τῇ δόξῃ προήκοντας. οὐ μὴν ἀλλὰ τῆς συγκλήτου ψηφισαμένης μηδὲν ἀλλάττειν μηδὲ κινεῖν τῶν διῳκημένων ὑπὸ Κάτωνος, ἡ μὲν ἀρχὴ τῷ Σκηπίωνι τῆς αὐτοῦ μᾶλλον ἢ τῆς Κάτωνος ἀφελοῦσα δόξης ἐν ἀπραξίᾳ καὶ σχολῇ μάτην διῆλθεν, ὁ δὲ Κάτων θριαμβεύσας οὐχ, ὥσπερ οἱ πλεῖστοι τῶν μὴ πρὸς ἀρετήν, ἀλλὰ πρὸς δόξαν ἁμιλλωμένων, ὅταν εἰς τὰς ἄκρας τιμὰς ἐξίκωνται καὶ τύχωσιν ὑπατείας καὶ θριάμβων, ἤδη τὸ λοιπὸν εἰς ἡδονὴν καὶ σχολὴν συσκευασάμενοι τὸν βίον ἐκ τῶν κοινῶν ἀπίασιν, οὕτω καὶ αὐτός ἐζανῆκε καὶ κατέλυσε τὴν ἀρετήν, ἀλλ’ ὅμοια τοῖς πρῶτον ἁπτομένοις πολιτείας καὶ διψῶσι τιμῆς καὶ δόξης ἀφ’ ἑτέρας ἀρχῆς συντείνας ἑαυτὸν ἐν μέσῳ παρεῖχε καὶ φίλοις χρῆσθαι καὶ πολίταις, οὔτε τὰς συνηγορίας οὔτε τὰς στρατείας ἀπειπάμενος.", "st": "Cat. Ma. 11.1"}, {"sp": "N", "t": "Τιβερίῳ μέν οὖν Σεμπρωνίῳ τὰ περὶ Θρᾴκην καὶ Ἴστρον ὑπατεύοντι πρεσβεύων συγκατειργάσατο, Μανίῳ δ’ Ἀκιλίῳ χιλιαρχῶν ἐπ’ Ἀντίοχον τὸν μέγαν συνεξῆλθεν εἰς τὴν Ἑλλάδα, φοβήσαντα Ῥωμαίους ὡς οὐδένα ἕτερον μετ’ Ἀννίβαν. τὴν γὰρ Ἀσίαν, ὅσην ὁ Νικάτωρ Σέλευκος εἶχεν, ὀλίγου δεῖν ἅπασαν ἐξ ὑπαρχῆς ἀνειληφώς, ἔθνη τε πάμπολλα καὶ μάχιμα βαρβάρων ὑπήκοα πεποιημένος, ἐπῆρτο συμπεσεῖν Ῥωμαίοις ὡς μόνοις ἔτι πρὸς αὐτὸν ἀξιομάχοις οὖσιν. εὐπρεπῆ δὲ τοῦ πολέμου ποιησάμενος αἰτίαν τοὺς Ἕλληνας ἐλευθεροῦν, οὐδὲν δεομένους, ἀλλὰ καὶ ἐλευθέρους καὶ αὐτονόμους χάριτι τῇ Ῥωμαίων ἀπὸ Φιλίππου καὶ Μακεδόνων νεωστὶ γεγονότας, διέβη μετὰ δυνάμεως, καὶ σάλον εὐθὺς ἡ Ἑλλὰς εἶχε καὶ μετέωρος ἦν ἐλπίσι διαφθειρομένη βασιλικαῖς ὑπὸ τῶν δημαγωγῶν. ἔπεμπεν οὖν πρέσβεις ὁ Μάνιος ἐπὶ τὰς πόλεις. καὶ τὰ μέν πλεῖστα τῶν νεωτεριζόντων Τίτος Φλαμινῖνος ἔσχεν ἄνευ ταραχῆς καὶ κατεπράυνεν, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται, Κάτων δὲ Κορινθίους καὶ Πατρεῖς, ἔτι δὲ Αἰγιεῖς παρεστήσατο.", "st": "Cat. Ma. 12.1"}, {"sp": "N", "t": "πλεῖστον δὲ χρόνον ἐν Ἀθήναις διέτριψε. καὶ λέγεται μέν τις αὐτοῦ φέρεσθαι λόγος, ὃν Ἑλληνιστὶ πρὸς τὸν δῆμον εἶπεν, ὡς ζηλῶν τε τὴν ἀρετὴν τῶν παλαιῶν Ἀθηναίων τῆς τε πόλεως διὰ τὸ κάλλος καὶ τὸ μέγεθος ἡδέως γεγονὼς θεατής· τὸ δ’ οὐκ ἀληθές ἐστιν, ἀλλὰ δι’ ἑρμηνέως ἐνέτυχε τοῖς Ἀθηναίοις, δυνηθεὶς ἂν αὐτὸς εἰπεῖν, ἐμμένων δὲ τοῖς πατρίοις καὶ καταγελῶν τῶν τὰ Ἑλληνικὰ τεθαυμακότων. Ποστούμιον γοῦν Ἀλβῖνον ἱστορίαν Ἑλληνιστὶ γράψαντα καὶ συγγνώμην αἰτούμενον ἐπέσκωψεν εἰπὼν, δοτέον εἶναι τὴν συγγνώμην, εἰ τῶν Ἀμφικτυόνων ψηφισαμένων ἀναγκασθεὶς ὑπέμεινε τὸ ἔργον, θαυμάσαι δέ φησι τοὺς Ἀθηναίους τὸ τάχος αὐτοῦ καὶ τὴν ὀξύτητα τῆς φράσεως· ἃ γὰρ αὐτὸς ἐξέφερε βραχέως, τὸν ἑρμηνέα μακρῶς καὶ διὰ πολλῶν ἀπαγγέλλειν τὸ δ’ ὅλον οἴεσθαι τὰ ῥήματα τοῖς μέν Ἕλλησιν ἀπὸ χειλέων, τοῖς δὲ Ῥωμαίοις ἀπὸ καρδίας φέρεσθαι.", "st": "Cat. Ma. 12.4"}, {"sp": "N", "t": "ἐπεὶ δ’ Ἀντίοχος ἐμφράξας τὰ περὶ Θερμοπύλας στενὰ τῷ στρατοπέδῳ, καὶ τοῖς αὐτοφυέσι τῶν τόπων ἐρύμασι προσβαλὼν χαρακώματα καὶ διατειχίσματα, καθῆστο τὸν πόλεμον ἐκκεκλεικέναι νομίζων, τὸ μὲν κατὰ στόμα βιάζεσθαι παντάπασιν ἀπεγίνωσκον οἱ Ῥωμαῖοι, τὴν δὲ Περσικὴν ἐκείνην περιήλυσιν καὶ κύκλωσιν ὁ Κάτων εἰς νοῦν βαλόμενος ἐξώδευσε νύκτωρ, ἀναλαβὼν μέρος τι τῆς στρατιᾶς. ἐπεὶ δ’ ἄνω προελθόντων ὁ καθοδηγῶν αἰχμάλωτος ἐξέπεσε τῆς ὁδοῦ καὶ πλανώμενος ἐν τόποις ἀπόροις καὶ κρημνώδεσι δεινὴν ἀθυμίαν καὶ φόβον ἐνειργάσατο τοῖς στρατιώταις, ὁρῶν ὁ Κάτων τὸν κίνδυνον ἐκέλευσε τοὺς ἄλλους ἅπαντας ἀτρεμεῖν καὶ περιμένειν, αὐτὸς δὲ Λεύκιόν τινα Μάλλιον, ἄνδρα δεινὸν ὀρειβατεῖν, παραλαβὼν ἐχώρει πολυπόνως καὶ παραβόλως ἐν ἀσελήνῳ νυκτὶ καὶ βαθείᾳ, κοτίνοις καὶ πάγοις ἀνατεταμένοις διασπάσματα πολλὰ τῆς ὄψεως καὶ ἀσάφειαν ἐχούσης, ἕως ἐμβαλόντες εἰς ἀτραπόν, ὡς ᾤοντο, κάτω περαίνουσαν ἐπὶ τὸ στρατόπεδον τῶν πολεμίων ἔθεντο σημεῖα πρός τινας εὐσκόπους κεραίας ὑπὲρ τὸ Καλλίδρομον ἀνεχούσας.", "st": "Cat. Ma. 13.1"}, {"sp": "N", "t": "οὕτω δὲ πάλιν ἐπανελθόντες ὀπίσω τὴν στρατιὰν ἀνέλαβον, καὶ πρός τὰ σημεῖα προάγοντες ἥψαντο μὲν ἐκείνης τῆς ἀτραποῦ καὶ κατεστήσαντο τὴν πορείαν, μικρὸν δὲ προελθοῦσιν αὐτοῖς ἐπέλιπε φάραγγος ὑπολαμβανούσης. καὶ πάλιν ἦν ἀπορία καὶ δέος οὐκ ἐπισταμένων οὐδὲ συνορώντων ὅτι πλησίον ἐτύγχανον τῶν πολεμίων γεγονότες. ἤδη δὲ διέλαμπεν ἡμέρα, καὶ φθογγῆς τίς ἔδοξεν ἐπακοῦσαι, τάχα δὲ καὶ καθορᾶν Ἑλληνικὸν χάρακα καὶ προφυλακὴν ὑπὸ τὸ κρημνῶδες. οὕτως οὖν ἐπιστήσας ἐνταῦθα τὴν στρατιὰν ὁ Κάτων ἐκέλευσεν αὐτῷ προσελθεῖν ἄνευ τῶν ἄλλων τοὺς Φιρμανούς, οἷς ἀεὶ πιστοῖς ἐχρῆτο καὶ προθύμοις.", "st": "Cat. Ma. 13.4"}, {"sp": "N", "t": "συνδραμόντων δὲ καὶ περιστάντων αὐτὸν ἀθρόων εἶπεν, ἄνδρα χρῄζω λαβεῖν τῶν πολεμίων ζῶντα καὶ πυθέσθαι, τίνες οἱ προφυλάττοντες οὗτοι, πόσον πλῆθος αὐτῶν, τίς ὁ τῶν ἄλλων διάκοσμος ἢ τάξις καὶ παρασκευὴ, μεθ’ ἧς ὑπομένουσιν ἡμᾶς. τὸ δ’ ἔργον ἅρπαγμα δεῖ τάχους γενέσθαι καὶ τόλμης, ᾗ καὶ λέοντες ἄνοπλοι θαρροῦντες ἐπὶ τὰ δειλὰ τῶν θηρίων βαδίζουσι. ταῦτα εἰπόντος τοῦ Κάτωνος αὐτόθεν ὀρούσαντες, ὥσπερ εἶχον, οἱ Φιρμανοὶ κατὰ τῶν ὁρῶν ἔθεον ἐπὶ τὰς προφυλακάς καὶ προσπεσόντες ἀπροσδόκητοι πάντας μὲν διετάραξαν καὶ διεσκέδασαν, ἕνα δ’ αὐτοῖς ὅπλοις ἁρπάσαντες ἐνεχείρισαν τῷ Κάτωνι.", "st": "Cat. Ma. 13.6"}, {"sp": "N", "t": "παρὰ τούτου μαθών, ὡς ἡ μὲν ἄλλη δύναμις ἐν τοῖς στενοῖς κάθηται μετ’ αὐτοῦ τοῦ βασιλέως, οἱ δὲ φρουροῦντες οὗτοι τὰς ὑπερβολὰς Αἰτωλῶν εἰσιν ἑξακόσιοι λογάδες, καταφρονήσας τῆς ὀλιγότητος ἅμα καὶ τῆς ὀλιγωρίας εὐθὺς ἐπῆγεν ἅμα σάλπιγξι καὶ ἀλαλαγμῷ, πρῶτος σπασάμενος τὴν μάχαιραν. οἱ δ’ ὡς εἶδον ἀπὸ τῶν κρημνῶν ἐπιφερομένους, φεύγοντες εἰς τὸ μέγα στρατόπεδον κατεπίμπλασαν ταραχῆς ἅπαντας.", "st": "Cat. Ma. 13.7"}, {"sp": "N", "t": "ἐν τούτῳ δὲ καί τοῦ Μανίου κάτωθεν πρὸς τὰ διατειχίσματα βιαζομένου καί τοῖς στενοῖς προσβάλλοντος ἀθρόαν τὴν δύναμιν, ὁ μέν Ἀντίοχος εἰς τὸ στόμα λίθῳ πληγείς ἐκτιναχθέντων αὐτοῦ τῶν ὀδόντων ἀπέστρεψε τὸν ἵππον ὀπίσω, περιαλγὴς γενόμενος, τοῦ δὲ στρατοῦ μέρος οὐδὲν ὑπέμεινε τοὺς Ῥωμαίους, ἀλλὰ καίπερ ἀπόρους καί ἀμηχάνους τῆς φυγῆς ὁδοὺς καί πλάνας ἐχούσης, ἑλῶν βαθέων καί πετρῶν ἀποτόμων τὰ πτώματα καί τὰς ὀλισθήσεις ὑποδεχομένων, εἰς ταῦτα διὰ τῶν στενῶν ὑπερχεόμενοι καί συνωθοῦντες ἀλλήλους φόβῳ πληγῆς καί σιδήρου πολεμίων αὑτοὺς διέφθειρον.", "st": "Cat. Ma. 14.1"}, {"sp": "N", "t": "ὁ δὲ Κάτων ἀεὶ μέν τις ἦν, ὡς ἔοικε, τῶν ἰδίων ἐγκωμίων ἀφειδὴς καί τὴν ἄντικρυς μεγαλαυχίαν ὡς ἐπακολούθημα τῆς μεγαλουργίας οὐκ ἔφευγε, πλεῖστον δὲ ταῖς πράξεσι ταύταις ὄγκον περιτέθεικε, καί φησι τοῖς ἰδοῦσιν αὐτόν τότε διώκοντα καί παίοντα τοὺς πολεμίους παραστῆναι μηδὲν ὀφείλειν Κάτωνα τῷ δήμῳ τοσοῦτον, ὅσον Κάτωνι τὸν δῆμον, αὐτόν τε Μάνιον τὸν ὕπατον θερμὸν ἀπὸ τῆς νίκης ἔτι θερμῷ περιπλακέντα πολὺν χρόνον ἀσπάζεσθαι καὶ βοᾶν ὑπὸ χαρᾶς, ὡς οὔτ’ ἂν αὐτὸς οὔθ’ ὁ σύμπας δῆμος ἐξισώσειε τὰς ἀμοιβὰς ταῖς Κάτωνος εὐεργεσίαις. μετὰ δὲ τὴν μάχην εὐθὺς εἰς Ῥώμην ἐπέμπετο τῶν ἠγωνισμένων αὐτάγγελος· καί διέπλευσε μέν εἰς Βρεντέσιον εὐτυχῶς, μιᾷ δ’ ἡμέρᾳ διελάσας ἐκεῖθεν εἰς Τάραντα καί τέσσαρας ἄλλας ὁδεύσας πεμπταῖος εἰς Ῥώμην ἀπὸ θαλάσσης ἀφίκετο καί πρῶτος ἀπήγγειλε τὴν νίκην. καί τὴν μέν πόλιν ἐνέπλησεν εὐφροσύνης καὶ θυσιῶν, φρονήματος δὲ τὸν δῆμον ὡς πάσης γῆς καί θαλάσσης κρατεῖν δυνάμενον.", "st": "Cat. Ma. 14.3"}, {"sp": "N", "t": "τῶν μὲν οὖν πολεμικῶν πράξεων τοῦ Κάτωνος αὗται σχεδόν εἰσιν ἐλλογιμώταται· τῆς δὲ πολιτείας φαίνεται τὸ περὶ τὰς κατηγορίας καὶ τοὺς ἐλέγχους τῶν πονηρῶν μόριον οὐ μικρᾶς ἄξιον σπουδῆς ἡγησάμενος. αὐτός τε γὰρ ἐδίωξε πολλούς καὶ διώκουσιν ἑτέροις συνηγωνίσατο καὶ παρεσκεύασεν ὅλως διώκοντας, ὡς ἐπὶ Σκηπίωνα τοὺς περὶ Πετίλλιον. τοῦτον μὲν οὖν ἀπ’ οἴκου τε μεγάλου καὶ φρονήματος ἀληθινοῦ ποιησάμενον ὑπὸ πόδας τὰς διαβολὰς μὴ ἀποκτεῖναι δυνηθεὶς ἀφῆκε· Λεύκιον δὲ τὸν ἀδελφὸν αὐτοῦ μετὰ τῶν κατηγόρων συστὰς καταδίκῃ περιέβαλε χρημάτων πολλῶν πρὸς τὸ δημόσιον, ἣν οὐκ ἔχων ἐκεῖνος ἀπολύσασθαι καὶ κινδυνεύων δεθῆναι μόλις ἐπικλήσει τῶν δημάρχων ἀφείθη.", "st": "Cat. Ma. 15.1"}, {"sp": "N", "t": "λέγεται δὲ καὶ νεανίσκῳ τινὶ τεθνηκότος πατρὸς ἐχθρὸν ἠτιμωκότι καὶ πορευομένῳ δι’ ἀγορᾶς μετὰ τὴν δίκην ἀπαντήσας ὁ Κάτων δεξιώσασθαι καὶ εἰπεῖν, ὅτι ταῦτα χρὴ τοῖς γονεῦσιν ἐναγίζειν, οὐκ ἄρνας οὐδ’ ἐρίφους, ἀλλ’ ἐχθρῶν δάκρυα καὶ καταδίκας. οὐ μὴν οὐδ’ αὐτός ἐν τῇ πολιτείᾳ περιῆν ἀθῷος, ἀλλ’ ὅπου τινὰ λαβὴν παράσχοι τοῖς ἐχθροῖς, κρινόμενος καὶ κινδυνεύων διετέλει. λέγεται γὰρ ὀλίγον ἀπολιπούσας τῶν πεντήκοντα φυγεῖν δίκας, μίαν δὲ τὴν τελευταίαν ἓξ ἔτη καὶ ὀγδοήκοντα γεγονώς· ἐν ᾗ καὶ τὸ μνημονευόμενον εἶπεν, ὡς χαλεπόν ἐστιν ἐν ἄλλοις βεβιωκότα ἀνθρώποις ἐν ἄλλοις ἀπολογεῖσθαι. καὶ τοῦτο πέρας οὐκ ἐποιήσατο τῶν ἀγώνων, τεσσάρων δ’ ἄλλων ἐνιαυτῶν διελθόντων Σερουίου Γάλβα κατηγόρησεν ἐνενήκοντα γεγονὼς ἔτη. κινδυνεύει γὰρ ὡς ὁ Νέστωρ εἰς τριγονίαν τῷ βίῳ καὶ ταῖς πράξεσι κατελθεῖν. Σκηπίωνι γὰρ, ὡς λέλεκται, τῷ μεγάλῳ πολλὰ διερισάμενος ἐν τῇ πολιτείᾳ διέτεινεν εἰς Σκηπίωνα τὸν νέον, ὃς ἦν ἐκείνου κατὰ ποίησιν υἱωνός, υἱὸς δὲ Παύλου τοῦ Περσέα καὶ Μακεδόνας καταπολεμήσαντος.", "st": "Cat. Ma. 15.3"}, {"sp": "N", "t": "τῆς δ’ ὑπατείας κατόπιν ἔτεσι δέκα τιμητείαν ὁ Κάτων παρήγγειλε. κορυφὴ δέ τίς ἐστι τιμῆς ἁπάσης ἡ ἀρχὴ καὶ τρόπον τινὰ τῆς πολιτείας ἐπιτελείωσις, ἄλλην τε πολλὴν ἐξουσίαν ἔχουσα καὶ τὴν περὶ τὰ ἤθη καὶ τοὺς βίους ἐξέτασιν. οὔτε γὰρ γάμον οὔτε παιδοποιίαν τινὸς οὔτε δίαιταν οὔτε συμπόσιον ᾤοντο δεῖν ἄκριτον καὶ ἀνεξέταστον, ὡς ἕκαστος ἐπιθυμίας ἔχοι καὶ προαιρέσεως, ἀφεῖσθαι. πολὺ δὲ μᾶλλον ἐν τούτοις νομίζοντες ἡ ταῖς ὑπαίθροις καὶ πολιτικαῖς πράξεσι τρόπον ἀνδρὸς ἐνορᾶσθαι, φύλακα καὶ σωφρονιστὴν καὶ κολαστὴν τοῦ μηδένα καθ’ ἡδονὰς ἐκτρέπεσθαι καὶ παρεκβαίνειν τὸν ἐπιχώριον καὶ συνήθη βίον ᾑροῦντο τῶν καλουμένων πατρικίων ἕνα καὶ τῶν δημοτικῶν ἕνα. τιμητὰς δὲ τούτους προσηγόρευον, ἐξουσίαν ἔχοντας ἀφελέσθαι μὲν ἵππον, ἐκβαλεῖν δὲ συγκλήτου τὸν ἀκολάστως βιοῦντα καὶ ἀτάκτως. οὗτοι δὲ καὶ τὰ τιμήματα τῶν οὐσιῶν λαμβάνοντες ἐπεσκόπουν, καὶ ταῖς ἀπογραφαῖς τὰ γένη καὶ τὰς πολιτείας διέκρινον· ἄλλας τε μεγάλας ἔχει δυνάμεις ἡ ἀρχή.", "st": "Cat. Ma. 16.1"}, {"sp": "N", "t": "διὸ καὶ τῷ Κάτωνι πρὸς τὴν παραγγελίαν ἀπήντησαν ἐνιστάμενοι σχεδὸν οἱ γνωριμώτατοι καὶ πρῶτοι τῶν συγκλητικῶν. τοὺς μὲν γὰρ εὐπατρίδας ὁ φθόνος ἐλύπει, παντάπασιν οἰομένους προπηλακίζεσθαι τὴν εὐγένειαν ἀνθρώπων ἀπ’ ἀρχῆς ἀδόξων εἰς τὴν ἄκραν τιμὴν καὶ δύναμιν ἀναβιβαζομένων, οἱ δὲ μοχθηρὰ συνειδότες αὑτοῖς ἐπιτηδεύματα καὶ τῶν πατρίων ἐκδιαίτησιν ἐθῶν ἐφοβοῦντο τὴν αὐστηρίαν τοῦ ἀνδρός, ἀπαραίτητον ἐν ἐξουσίᾳ καὶ χαλεπὴν ἐσομένην. διὸ συμφρονήσαντες καὶ παρασκευάσαντες ἑπτὰ κατῆγον ἐπὶ τὴν παραγγελίαν ἀντιπάλους τῷ Κάτωνι, θεραπεύοντας ἐλπίσι χρησταῖς τὸ πλῆθος, ὡς δὴ μαλακῶς καὶ πρὸς ἡδονὴν ἄρχεσθαι δεόμενον. τοὐναντίον δ’ ὁ Κάτων οὐδεμίαν ἐνδιδοὺς ἐπιείκειαν, ἀλλ’ ἄντικρυς ἀπειλῶν τε τοῖς πονηροῖς ἀπὸ τοῦ βήματος καὶ κεκραγὼς μεγάλου καθαρμοῦ χρῄζειν τὴν πόλιν, ἠξίου τοὺς πολλοὺς, εἰ σωφρονοῦσι, μὴ τὸν ἥδιστον, ἀλλὰ τὸν σφοδρότατον αἱρεῖσθαι τῶν ἰατρῶν τοῦτον δὲ αὐτὸν εἶναι καὶ τῶν πατρικίων ἕνα Φλάκκον Οὐαλλέριον· μετ’ ἐκείνου γὰρ οἴεσθαι μόνου τὴν τρυφὴν καὶ τὴν μαλακίαν ὥσπερ ὕδραν τέμνων καὶ ἀποκαίων προὔργου τι ποιήσειν, τῶν δ’ ἄλλων ὁρᾶν ἕκαστον ἄρξαι κακῶς βιαζόμενον, ὅτι τοὺς καλῶς ἄρξοντας δέδοικεν. οὕτω δ’ ἄρα μέγας ἦν ὡς ἀληθῶς καὶ μεγάλων ἄξιος δημαγωγῶν ὁ Ῥωμαίων δῆμος, ὥστε μὴ φοβηθῆναι τὴν ἀνάτασιν καὶ τὸν ὄγκον τοῦ ἀνδρός, ἀλλὰ τοὺς ἡδεῖς ἐκείνους καὶ πρὸς χάριν ἅπαντα ποιήσειν δοκοῦντας ἀπορρίψας ἑλέσθαι μετὰ τοῦ Κάτωνος τὸν Φλάκκον, ὥσπερ οὐκ αἰτοῦντος ἀρχήν, ἀλλ’ ἄρχοντος ἤδη καὶ προστάττοντος ἀκροώμενος.", "st": "Cat. Ma. 16.4"}, {"sp": "N", "t": "προέγραψε μὲν οὖν ὁ Κάτων τῆς συγκλήτου τὸν συνάρχοντα καὶ φίλον Λεύκιον Οὐαλλέριον Φλάκκον, ἐξέβαλε δὲ τῆς βουλῆς ἄλλους τε συχνοὺς καὶ Λεύκιον Κοΐντιον, ὕπατον μὲν ἑπτὰ πρότερον ἐνιαυτοῖς γεγενημένον, ὃ δ’ ἦν αὐτῷ πρὸς δόξαν ὑπατείας μεῖζον, ἀδελφὸν Τίτου Φλαμινίνου τοῦ καταπολεμήσαντος Φίλιππον. αἰτίαν δὲ τῆς ἐκβολῆς ἔσχε τοιαύτην. μειράκιον ἐκ τῆς παιδικῆς ὥρας ἑταιροῦν ἀνειληφὼς ὁ Λεύκιος ἀεὶ Περὶ αὑτὸν εἶχε καὶ συνεπήγετο στρατηγῶν ἐπὶ τιμῆς καὶ δυνάμεως τοσαύτης ὅσην οὐδεὶς εἶχε τῶν πρώτων παρ’ αὐτῷ φίλων καὶ οἰκείων, ἐτύγχανε μὲν οὖν ἡγούμενος ὑπατικῆς ἐπαρχίας· ἐν δὲ συμποσίῳ τινὶ τὸ μειράκιον, ὥσπερ εἰώθει, συγκατακείμενον ἄλλην τε κολακείαν ἐκίνει πρὸς ἄνθρωπον ἐν οἴνῳ ῥᾳδίως ἀγόμενον, καὶ φιλεῖν αὑτὸν οὕτως ἔλεγεν ὥστ’, ἔφη, θέας οὔσης οἴκοι μονομάχων οὐ τεθεαμένος πρότερον ἐξώρμησα πρὸς σέ, καίπερ ἐπιθυμῶν ἰδεῖν ἄνθρωπον σφαττόμενον. ὁ δὲ Λεύκιος ἀντιφιλοφρονούμενος ἀλλὰ τούτου γε χάριν, εἶπε, μή μοι κατάκεισο λυπούμενος, ἐγὼ γὰρ ἰάσομαι. καὶ κελεύσας ἕνα τῶν ἐπὶ θανάτῳ κατακρίτων εἰς τὸ συμπόσιον ἀχθῆναι καὶ τὸν ὑπηρέτην ἔχοντα πέλεκυν παραστῆναι, πάλιν ἠρώτησε τὸν ἐρώμενον, εἰ βούλεται τυπτόμενον θεάσασθαι. φήσαντος δὲ βούλεσθαι, προσέταξεν ἀποκόψαι τοῦ ἀνθρώπου τὸν τράχηλον.", "st": "Cat. Ma. 17.1"}, {"sp": "N", "t": "οἱ μὲν οὖν πλεῖστοι ταῦτα ἱστοροῦσι, καὶ ὅ γε Κικέρων αὑτὸν τὸν Κάτωνα διηγούμενον ἐν τῷ Περὶ γήρως διαλόγῳ πεποίηκεν ὁ δὲ Λίβιος αὐτόμολον εἶναί φησι Γαλάτην τὸν ἀναιρεθέντα, τὸν δὲ Λεύκιον οὐ δι’ ὑπηρέτου κτεῖναι τὸν ἄνθρωπον, ἀλλ’ αὑτὸν ἰδίᾳ χειρί, καὶ ταῦτα ἐν λόγῳ γεγράφθαι Κάτωνος.", "st": "Cat. Ma. 17.4"}, {"sp": "N", "t": "ἐκβληθέντος οὖν τοῦ Λευκίου τῆς βουλῆς ὑπὸ τοῦ Κάτωνος, ὁ ἀδελφὸς αὑτοῦ βαρέως φέρων ἐπὶ τὸν δῆμον κατέφυγε καὶ τὴν αἰτίαν ἐκέλευεν εἰπεῖν τὸν Κάτωνα τῆς ἐκβολῆς. εἰπόντος δὲ καὶ διηγησαμένου τὸ συμπόσιον ἐπεχείρει μὲν ὁ Λεύκιος ἀρνεῖσθαι, προκαλουμένου δὲ τοῦ Κάτωνος εἰς ὁρισμὸν ἀνεδύετο. καὶ τότε μὲν ἄξια παθεῖν κατεγνώσθη· θέας δ’ οὔσης ἐν θεάτρῳ τὴν ὑπατικὴν χώραν παρελθὼν καὶ πορρωτάτω που καθεσθεὶς οἶκτον ἔσχε παρὰ τῷ δήμῳ, καὶ βοῶντες ἠνάγκασαν αὑτὸν μετελθεῖν, ὡς ἦν δυνατὸν ἐπανορθούμενοι καὶ θεραπεύοντες τὸ γεγενημένον.", "st": "Cat. Ma. 17.5"}, {"sp": "N", "t": "ἄλλον δὲ βουλῆς ἐξέβαλεν ὑπατεύσειν ἐπίδοξον ὄντα, Μανίλλιον, ὅτι τὴν αὑτοῦ γυναῖκα μεθ’ ἡμέραν ὁρώσης τῆς θυγατρὸς κατεφίλησεν. αὑτῷ δ’ ἔφη τὴν γυναῖκα μηδέποτε πλὴν βροντῆς μεγάλης γενομένης περιπλακῆναι, καὶ μετὰ παιδιᾶς εἰπεῖν αὑτὸν ὡς μακάριός ἐστι τοῦ Διὸς βροντῶντος.", "st": "Cat. Ma. 17.7"}, {"sp": "N", "t": "ἤνεγκε δέ τινα τῷ Κάτωνι καὶ Λεύκιος ὁ Σκηπίωνος ἀδελφὸς ἐπίφθονον αἰτίαν, θριαμβικὸς ἀνὴρ ἀφαιρεθεὶς ὑπ’ αὐτοῦ τὸν ἵππον· ἔδοξε γὰρ οἷον ἐφυβρίζων Ἀφρικανῷ Σκηπίωνι τεθνηκότι τοῦτο ποιῆσαι. τοὺς δὲ πλείστους ἠνίασε μάλιστά τῇ περικοπῇ τῆς πολυτελείας, ἣν ἄντικρυς μὲν ἀφελέσθαι, νενοσηκότων ἤδη καὶ διεφθαρμένων ὑπ’ αὐτῆς τῶν πολλῶν, ἀδύνατον ἦν, κύκλῳ δὲ περιϊὼν ἠνάγκαζεν ἐσθῆτος, ὀχήματος, κόσμου γυναικείου, σκευῶν τῶν περὶ δίαιταν, ὧν ἑκάστου τὸ τίμημα δραχμὰς χιλίας καὶ πεντακοσίας ὑπερέβαλλεν, ἀποτιμᾶσθαι τὴν ἀξίαν εἰς τὸ δεκαπλάσιον, βουλόμενος ἀπὸ μειζόνων τιμημάτων αὐτοῖς μείζονας καὶ τὰς εἰσφορὰς εἶναι, καὶ προσετίμησε τρεῖς χαλκοῦς πρὸς τοῖς χιλίοις, ὅπως βαρυνόμενοι ταῖς ἐπιβολαῖς καὶ Τοὺς εὐσταλεῖς καὶ λιτοὺς ὁρῶντες ἀπὸ τῶν ἴσων ἐλάττονα τελοῦντας εἰς τὸ δημόσιον ἀπαγορεύωσιν. ἦσαν οὖν αὐτῷ χαλεποὶ μὲν οἱ τὰς εἰσφορὰς διὰ τὴν τρυφὴν ὑπομένοντες, χαλεποὶ δ’ αὖ πάλιν οἱ τὴν τρυφὴν ἀποτιθέμενοι διὰ τὰς εἰσφοράς, πλούτου γὰρ ἀφαίρεσιν οἱ πολλοὶ νομίζουσι τὴν κώλυσιν αὐτοῦ τῆς ἐπιδείξεως, ἐπιδείκνυσθαι δὲ τοῖς περιττοῖς, οὐ τοῖς ἀναγκαίοις. ὃ δὴ καὶ μάλιστά φασι τὸν φιλόσοφον Ἀρίστωνα θαυμάζειν, ὅτι Τοὺς τὰ περιττὰ κεκτημένους μᾶλλον ἡγοῦνται μακαρίους ἢ Τοὺς τῶν ἀναγκαίων καὶ χρησίμων εὐποροῦντας. Σκόπας δὲ ὁ Θετταλὸς αἰτουμένου τινὸς τῶν φίλων παρ’ αὐτοῦ τι τοιοῦτον, ὃ μὴ σφόδρα ἦν χρήσιμον ἐκείνῳ, καὶ λέγοντος, ὡς οὐδὲν αἰτεῖ τῶν ἀναγκαίων καὶ χρησίμων καὶ μὴν ἐγὼ τούτοις εἶπεν, εὐδαίμων καὶ πλούσιός εἰμι, τοῖς ἀχρήστοις καὶ περιττοῖς. οὕτως ὁ τοῦ πλούτου ζῆλος οὐδενὶ πάθει φυσικῷ συνημμένος ἐκ τῆς ὀχλώδους καὶ θυραίου δόξης ἐπεισόδιός ἐστιν.", "st": "Cat. Ma. 18.1"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ τῶν ἐγκαλούντων ἐλάχιστα φροντίζων ὁ Κάτων ἔτι μᾶλλον ἐπέτεινεν, ἀποκόπτων μὲν ὀχετοὺς, οἷς τὸ παραρρέον δημόσιον ὕδωρ ὑπολαμβάνοντες ἀπῆγον εἰς οἰκίας ἰδίας καὶ κήπους, ἀνατρέπων δὲ καὶ καταβάλλων ὅσα προὔβαινεν εἰς τὸ δημόσιον οἰκοδομήματα, συστέλλων δὲ τοῖς μισθοῖς τὰς ἐργολαβίας, τὰ δὲ τέλη ταῖς πράσεσιν ἐπὶ τὰς ἐσχάτας ἐλαύνων τιμάς. ἀφ’ ὧν αὐτῷ πολὺ συνήχθη μῖσος, οἱ δὲ περὶ τὸν Τίτον συστάντες ἐπ’ αὐτὸν ἔν τε τῇ βουλῇ τὰς γεγενημένας ἐκδόσεις καὶ μισθώσεις τῶν ἱερῶν καὶ δημοσίων ἔργων ἔλυσαν ὡς γεγενημένας ἀλυσιτελῶς, καὶ τῶν δημάρχων τοὺς θρασυτάτους παρώξυναν ἐν δήμῳ προσκαλέσασθαι τὸν Κάτωνα καὶ ζημιῶσαι δυσὶ ταλάντοις. πολλὰ δὲ καὶ πρὸς τὴν τῆς βασιλικῆς κατασκευὴν ἠναντιώθησαν, ἣν ἐκεῖνος ἐκ χρημάτων κοινῶν ὑπὸ τὸ βουλευτήριον τῇ ἀγορᾷ παρέβαλε καὶ Πορκία βασιλικὴ προσηγορεύθη.", "st": "Cat. Ma. 19.1"}, {"sp": "N", "t": "φαίνεται δὲ θαυμαστῶς ἀποδεξάμενος αὐτοῦ τὴν τιμητείαν ὁ δῆμος, ἀνδριάντα γοῦν ἀναθεὶς ἐν τῷ ναῷ τῆς Ὑγιείας ἐπέγραψεν οὐ τὰς στρατηγίας οὐδὲ τὸν θρίαμβον τὸν Κάτωνος, ἀλλ’, ὡς ἄν τις μεταφράσειε τὴν ἐπιγραφήν, ὅτι τὴν Ῥωμαίων πολιτείαν ἐγκεκλιμένην καὶ ῥέπουσαν ἐπὶ τὸ χεῖρον τιμητὴς γενόμενος χρησταῖς ἀγωγαῖς καὶ σώφροσιν ἐθισμοῖς καὶ διδασκαλίαις εἰς ὀρθὸν αὖθις ἀποκατέστησε καίτοι πρότερον αὐτὸς κατεγέλα τῶν ἀγαπώντων τὰ τοιαῦτα, καὶ λανθάνειν αὐτοὺς ἔλεγεν ἐπὶ χαλκέων καὶ ζωγράφων ἔργοις μέγα φρονοῦντας, αὐτοῦ δὲ καλλίστας εἰκόνας ἐν ταῖς ψυχαῖς περιφέρειν τοὺς πολίτας πρὸς δὲ τοὺς θαυμάζοντας, ὅτι πολλῶν ἀδόξων ἀνδριάντας ἐχόντων ἐκεῖνος οὐκ ἔχει μᾶλλον γὰρ, ἔφη, βούλομαι ζητεῖσθαι, διὰ τί μου ἀνδριὰς οὐ κεῖται ἢ διὰ τί κεῖται τὸ δ’ ὅλον οὐδ’ ἐπαινούμενον ἠξίου τὸν ἀγαθὸν πολίτην ὑπομένειν, εἰ μὴ τοῦτο χρησίμως γίνοιτο τῷ κοινῷ.", "st": "Cat. Ma. 19.3"}, {"sp": "N", "t": "καίτοι πλεῖστα πάντων ἑαυτὸν ἐγκεκωμίακεν, ὅς γε καὶ τοὺς ἁμαρτάνοντάς τι περὶ τὸν βίον, εἶτ’ ἐλεγχομένους λέγειν φησίν, ὡς οὐκ ἄξιον ἐγκαλεῖν αὐτοῖς· οὐ γὰρ Κάτωνές εἰσι· καὶ τοὺς ἔνια μιμεῖσθαι τῶν ὑπ’ αὐτοῦ πραττομένων οὐκ ἐμμελῶς ἐπιχειροῦντας ἐπαριστέρους καλεῖσθαι Κάτωνας· ἀφορᾶν δὲ τὴν βουλὴν πρὸς αὐτὸν ἐν τοῖς ἐπισφαλεστάτοις καιροῖς ὥσπερ ἐν πλῷ πρὸς κυβερνήτην, καὶ πολλάκις μὴ παρόντος ὑπερτίθεσθαι τὰ πλείστης ἄξια σπουδῆς, ἃ δὴ παρὰ τῶν ἄλλων αὐτῷ μαρτυρεῖται· μέγα γὰρ ἔσχεν ἐν τῇ πόλει καὶ διὰ τὸν βίον καὶ διὰ τὸν λόγον καὶ διὰ τὸ γῆρας ἀξίωμα.", "st": "Cat. Ma. 19.6"}, {"sp": "N", "t": "γέγονε δὲ καὶ πατὴρ ἀγαθὸς καὶ περὶ γυναῖκα χρηστὸς ἀνὴρ καὶ χρηματιστὴς οὐκ εὐκαταφρόνητος οὐδ’ ὥς τι μικρὸν ἢ φαῦλον ἐν παρέργῳ μεταχειρισάμενος τὴν τοιαύτην ἐπιμέλειαν. ὅθεν οἴομαι δεῖν καὶ περὶ τούτων ὅσα καλῶς ἔχει διελθεῖν γυναῖκα μὲν εὐγενεστέραν ἢ πλουσιωτέραν ἔγημεν, ἡγούμενος ὁμοίως μὲν ἀμφοτέρας ἔχειν βάρος καὶ φρόνημα, τὰς δὲ γενναίας αἰδουμένας τὰ αἰσχρὰ μᾶλλον ὑπηκόους εἶναι πρός τὰ καλὰ τοῖς γεγαμηκόσι. τὸν δὲ τύπτοντα γαμετὴν ἢ παῖδα τοῖς ἁγιωτάτοις ἔλεγεν ἱεροῖς προσφέρειν τὰς χεῖρας, ἐν ἐπαίνῳ δὲ μείζονι τίθεσθαι τὸ γαμέτην ἀγαθὸν ἢ τὸ μέγαν εἶναι συγκλητικόν ἐπεὶ καὶ Σωκράτους οὐδὲν ἄλλο θαυμάζειν τοῦ παλαιοῦ πλὴν ὅτι γυναικὶ χαλεπῇ καὶ παισὶν ἀποπλήκτοις χρώμενος ἐπιεικῶς καὶ πρᾴως διετέλεσε, γενομένου δὲ τοῦ παιδὸς οὐδὲν ἦν ἔργον οὕτως ἀναγκαῖον, εἰ μή τι δημόσιον, ὡς μὴ παρεῖναι τῇ γυναικὶ λουούσῃ τὸ βρέφος καὶ σπαργανούσῃ. αὐτὴ γὰρ ἔτρεφεν ἰδίῳ γάλακτι· πολλάκις δὲ καὶ τὰ τῶν δούλων παιδάρια τῷ μαστῷ προσιεμένη κατεσκεύαζεν εὔνοιαν ἐκ τῆς συντροφίας πρός τὸν υἱόν. ἐπεὶ δὲ ἤρξατο συνιέναι, παραλαβὼν αὐτὸς ἐδίδασκε γράμματα, καίτοι χαρίεντα δοῦλον εἶχε γραμματιστὴν ὄνομα Χίλωνα, πολλοὺς διδάσκοντα παῖδας. οὐκ ἠξίου δὲ τὸν υἱόν, ὥς φησιν αὐτός, ὑπὸ δούλου κακῶς ἀκούειν ἢ τοῦ ὠτὸς ἀνατείνεσθαι μανθάνοντα βράδιον, οὐδέ γε μαθήματος τηλικούτου τῷ δούλῳ χάριν ὀφείλειν, ἀλλ’ αὐτὸς μὲν ἦν γραμματιστής, αὐτὸς δὲ νομοδιδάκτης, αὐτὸς δὲ γυμναστής, οὐ μόνον ἀκοντίζειν οὐδ’ ὁπλομαχεῖν οὐδ’ ἱππεύειν διδάσκων τὸν υἱόν, ἀλλὰ καὶ τῇ χειρὶ πὺξ παίειν καὶ καῦμα καὶ ψῦχος ἀνέχεσθαι καὶ τὰ δινώδη καὶ τραχύνοντα τοῦ ποταμοῦ διανηχόμενον ἀποβιάζεσθαι. καὶ τὰς ἱστορίας δὲ συγγράψαι φησὶν αὐτὸς ἰδίᾳ χειρὶ καὶ μεγάλοις γράμμασιν, ὅπως οἴκοθεν ὑπάρχοι τῷ παιδὶ πρός ἐμπειρίαν τῶν παλαιῶν καὶ πατρίων ὠφελεῖσθαι τὰ δ’ αἰσχρὰ τῶν ῥημάτων οὐχ ἧττον εὐλαβεῖσθαι τοῦ παιδὸς παρόντος ἢ τῶν ἱερῶν παρθένων, ἃς Ἑστιάδας καλοῦσι συλλούσασθαι δὲ μηδέποτε. καὶ τοῦτο κοινὸν ἔοικε Ῥωμαίων ἔθος εἶναι· καὶ γὰρ πενθεροὶ γαμβροῖς ἐφυλάττοντο συλλούεσθαι, δυσωπούμενοι τὴν ἀποκάλυψιν καὶ γύμνωσιν. εἶτα μέντοι παρ’ Ἑλλήνων τὸ γυμνοῦσθαι μαθόντες, αὐτοὶ πάλιν τοῦ καὶ μετὰ γυναικῶν τοῦτο πράσσειν ἀναπεπλήκασι τοὺς Ἕλληνας.", "st": "Cat. Ma. 20.1"}, {"sp": "N", "t": "οὕτω δὲ καλὸν ἔργον εἰς ἀρετὴν τῷ Κάτωνι πλάττοντι καὶ δημιουργοῦντι τὸν υἱόν, ἐπεὶ τὰ τῆς προθυμίας ἦν ἄμεμπτα καὶ δι’ εὐφυΐαν ὑπήκουεν ἡ ψυχή, τὸ δὲ σῶμα μαλακώτερον ἐφαίνετο τοῦ πονεῖν, ὑπανῆκεν αὐτῷ τὸ σύντονον ἄγαν καὶ κεκολασμένον τῆς διαίτης. ὁ δέ, καίπερ οὕτως ἔχων, ἀνὴρ ἀγαθὸς ἦν ἐν ταῖς στρατείαις, καὶ τὴν πρός Περσέα μάχην ἠγωνίσατο λαμπρῶς Παύλου στρατηγοῦντος. εἶτα μέντοι τοῦ ξίφους ἐκκρουσθέντος ὑπὸ πληγῆς ἢ δι’ ὑγρότητα τῆς χειρὸς ἐξολισθόντος ἀχθεσθεὶς τρέπεται πρός τινας τῶν συνήθων, καὶ παραλαβὼν ἐκείνους αὖθις εἰς τοὺς πολεμίους ἐνέβαλε. πολλῷ δ’ ἀγῶνι καὶ βίᾳ μεγάλῃ διαφωτίσας τὸν τόπον ἀνεῦρε μόγις ἐν πολλοῖς σάγμασιν ὅπλων καὶ σώμασι νεκρῶν ὁμοῦ φίλων τε καὶ πολεμίων κατασεσωρευμένων. ἐφ’ ᾧ καὶ Παῦλος ὁ στρατηγὸς ἠγάσθη τὸ μειράκιον, καὶ Κάτωνος αὐτοῦ φέρεταί τις ἐπιστολὴ πρός τὸν υἱόν ὑπερφυῶς ἐπαινοῦντος τὴν περὶ τὸ ξίφος φιλοτιμίαν αὐτοῦ καὶ σπουδήν. ὕστερον δὲ καὶ Παύλου θυγατέρα Τερτίαν ἔγημεν ὁ νεανίας, ἀδελφὴν Σκηπίωνος, οὐχ ἧττον ἤδη δι’ αὑτὸν ἢ τὸν πατέρα καταμιγνύμενος εἰς γένος τηλικοῦτον. ἡ μὲν οὖν περὶ τὸν υἱὸν ἐπιμέλεια τοῦ Κάτωνος ἄξιον ἔσχεν τέλος.", "st": "Cat. Ma. 20.7"}, {"sp": "N", "t": "οἰκέτας δὲ πολλοὺς ἐκτᾶτο, τῶν αἰχμαλώτων ὠνούμενος μάλιστα τοὺς μικροὺς καὶ δυναμένους ἔτι τροφὴν καὶ παίδευσιν ὡς σκύλακας ἢ πώλους ἐνεγκεῖν. τούτων οὐδεὶς εἰσῆλθεν εἰς οἰκίαν ἑτέραν, εἰ μὴ πέμψαντος αὐτοῦ Κάτωνος ἢ τῆς γυναικός. ὁ δ’ ἐρωτηθεὶς, τί πράττοι Κάτων, οὐδὲν ἀπεκρίνετο πλὴν ἀγνοεῖν. ἔδει δὲ ἢ πράττειν τι τῶν ἀναγκαίων οἴκοι τὸν δοῦλον ἢ καθεύδειν καὶ σφόδρα τοῖς κοιμωμένοις ὁ Κάτων ἔχαιρε, πρᾳοτέρους τε τῶν ἐγρηγορότων νομίζων καὶ πρὸς ὁτιοῦν βελτίονας χρῆσθαι τῶν δεομένων ὕπνου τοὺς ἀπολελαυκότας, οἰόμενος δὲ τὰ μέγιστα ῥᾳδιουργεῖν ἀφροδισίων ἕνεκα τοὺς δούλους ἔταξεν ὡρισμένου νομίσματος ὁμιλεῖν ταῖς θεραπαινίσιν, ἑτέρᾳ δὲ γυναικὶ μηδένα πλησιάζειν.", "st": "Cat. Ma. 21.1"}, {"sp": "N", "t": "ἐν ἀρχῇ μὲν οὖν ἔτι πένης ὢν καὶ στρατευόμενος πρὸς οὐδὲν ἐδυσκόλαινε τῶν περὶ δίαιταν, ἀλλ’ αἴσχιστον ἀπέφαινε διὰ γαστέρα πρὸς οἰκέτην ζυγομαχεῖν. ὕστερον δὲ τῶν πραγμάτων ἐπιδιδόντων ποιούμενος ἑστιάσεις φίλων καὶ συναρχόντων ἐκόλαζεν εὐθὺς μετὰ τὸ δεῖπνον ἱμάντι τοὺς ἀμελέστερον ὑπουργήσαντας ὁτιοῦν ἢ σκευάσαντας. ἀεὶ δέ τινα στάσιν ἔχειν τοὺς δούλους ἐμηχανᾶτο καὶ διαφορὰν πρὸς ἀλλήλους, ὑπονοῶν τὴν ὁμόνοιαν αὐτῶν καὶ δεδοικώς. τοὺς δ’ ἄξιον εἰργάσθαι τι θανάτου δόξαντας ἐδικαίου κριθέντας ἐν τοῖς οἰκέταις πᾶσιν ἀποθνῄσκειν, εἰ καταγνωσθεῖεν.", "st": "Cat. Ma. 21.3"}, {"sp": "N", "t": "ἁπτόμενος δὲ συντονώτερον πορισμοῦ τὴν μὲν γεωργίαν μᾶλλον ἡγεῖτο διαγωγὴν ἢ πρόσοδον, εἰς δ’ ἀσφαλῆ πράγματα καὶ βέβαια κατατιθέμενος τὰς ἀφορμάς ἐκτᾶτο λίμνας, ὕδατα θερμά, τόπους κναφεῦσιν ἀνειμένους, ἔργα πίσσια, χώραν ἔχουσαν αὐτοφυεῖς νομὰς καὶ ὕλας, ἀφ’ ὧν αὐτῷ χρήματα προσῄει πολλὰ μηδ’ ὑπὸ τοῦ Διός, ὥς φησὶν αὐτός, βλαβῆναι δυναμένων. ἐχρήσατο δὲ καὶ τῷ διαβεβλημένῳ μάλιστα τῶν δανεισμῶν ἐπὶ ναυτικοῖς τὸν τρόπον τοῦτον, ἐκέλευε τοὺς δανειζομένους ἐπὶ κοινωνίᾳ πολλοὺς παρακαλεῖν, γενομένων δὲ πεντήκοντα καὶ πλοίων τοσούτων αὐτὸς εἶχε μίαν μερίδα διὰ Κουϊντίωνος ἀπελευθέρου τοῖς δανειζομένοις συμπραγματευομένου καὶ συμπλέοντος. ἦν δ’ οὖν οὐκ εἰς ἅπαν ὁ κίνδυνος, ἀλλ’ εἰς μέρος μικρὸν ἐπὶ κέρδεσι μεγάλοις. ἐδίδου δὲ καὶ τῶν οἰκετῶν τοῖς βουλομένοις ἀργύριον οἱ δ’ ἐωνοῦντο παῖδας, εἶτα τούτους ἀσκήσαντες καὶ διδάξαντες ἀναλώμασι τοῦ Κάτωνος μετ’ ἐνιαυτὸν ἀπεδίδοντο. πολλοὺς δὲ καὶ κατεῖχεν ὁ Κάτων, ὅσην ὁ πλείστην διδοὺς ἐωνεῖτο τιμὴν ὑπολογιζόμενος. προτρέπων δὲ τὸν υἱὸν ἐπὶ ταῦτα φησὶν οὐκ ἀνδρός, ἀλλὰ χήρας γυναικὸς εἶναι τὸ μειῶσαί τι τῶν ὑπαρχόντων. ἐκεῖνο δ’ ἤδη σφοδρότερον τοῦ Κάτωνος, ὅτι θαυμαστὸν ἄνδρα καὶ θεῖον εἰπεῖν ἐτόλμησε πρὸς δόξαν, ὃς ἀπολείπει πλέον ἐν τοῖς λόγοις ὃ προσέθηκεν οὗ παρέλαβεν.", "st": "Cat. Ma. 21.5"}, {"sp": "N", "t": "ἤδη δὲ αὐτοῦ γέροντος γεγονότος πρέσβεις Ἀθήνηθεν ἦλθον εἰς Ῥώμην οἱ περὶ Καρνεάδην τὸν Ἀκαδημαϊκὸν καὶ Διογένη τὸν Στωικὸν φιλόσοφον, καταδίκην τινὰ παραιτησόμενοι τοῦ δήμου τῶν Ἀθηναίων, ἣν ἐρήμην ὦφλον Ὠρωπίων μὲν διωξάντων, Σικυωνίων δὲ καταψηφισαμένων, τίμημα ταλάντων πεντακοσίων ἔχουσαν. εὐθὺς οὖν οἱ φιλολογώτατοι τῶν νεανίσκων ἐπὶ τοὺς ἄνδρας ἵεντο, καὶ συνῆσαν ἀκροώμενοι καὶ θαυμάζοντες αὐτούς, μάλιστα δ’ ἡ Καρνεάδου χάρις, ἧς δύναμίς τε πλείστη καὶ δόξα τῆς δυνάμεως οὐκ ἀποδέουσα, μεγάλων ἐπιλαβομένη καὶ φιλανθρώπων ἀκροατηρίων ὡς πνεῦμα τὴν πόλιν ἠχῆς ἐνέπλησε. καὶ λόγος κατεῖχεν, ὡς ἀνὴρ Ἕλλην εἰς ἔκπληξιν ὑπερφυὴς πάντα κηλῶν καὶ χειρούμενος ἔρωτα δεινὸν ἐμβέβληκε τοῖς νέοις, ὑφ’ οὗ τῶν ἄλλων ἡδονῶν καὶ διατριβῶν ἐκπεσόντες ἐνθουσιῶσι περὶ φιλοσοφίαν. ταῦτα τοῖς μὲν ἄλλοις ἤρεσκε Ῥωμαίοις γινόμενα, καὶ τὰ μειράκια παιδείας Ἑλληνικῆς μεταλαμβάνοντα καὶ συνόντα θαυμαζομένοις ἀνδράσιν ἡδέως ἑώρων· ὁ δὲ Κάτων ἐξ ἀρχῆς τε τοῦ ζήλου τῶν λόγων παραρρέοντος εἰς τὴν πόλιν ἤχθετο φοβούμενος, μὴ τὸ φιλότιμον ἐνταῦθα τρέψαντες οἱ νέοι τὴν ἐπὶ τῷ λέγειν δόξαν ἀγαπήσωσι μᾶλλον τῆς ἀπὸ τῶν ἔργων καὶ τῶν στρατειῶν, ἐπεὶ δὲ προὔβαινεν ἡ δόξα τῶν φιλοσόφων ἐν τῇ πόλει καὶ τοὺς πρώτους λόγους αὐτῶν πρὸς τὴν σύγκλητον ἀνὴρ ἐπιφανὴς σπουδάσας αὐτὸς καὶ δεηθεὶς ἡρμήνευσε, Γάϊος Ἀκίλιος, ἔγνω μετ’ εὐπρεπείας ἀποδιοπομπήσασθαι τοὺς φιλοσόφους ἅπαντας ἐκ τῆς πόλεως. καὶ παρελθὼν εἰς τὴν σύγκλητον ἐμέμψατο τοῖς ἄρχουσιν, ὅτι πρεσβεία κάθηται πολὺν χρόνον ἄπρακτος ἀνδρῶν, οἳ περὶ παντὸς οὗ βούλοιντο ῥᾳδίως πείθειν δύνανται δεῖν οὖν τὴν ταχίστην γνῶναί τι καὶ ψηφίσασθαι περὶ τῆς πρεσβείας, ὅπως οὗτοι μὲν ἐπὶ τὰς σχολὰς τραπόμενοι διαλέγωνται παισὶν Ἑλλήνων, οἱ δὲ Ῥωμαίων νέοι τῶν νόμων καὶ τῶν ἀρχόντων ὡς πρότερον ἀκούωσι.", "st": "Cat. Ma. 22.1"}, {"sp": "N", "t": "ταῦτα δ’ οὐχ, ὡς ἔνιοι νομίζουσι, Καρνεάδῃ δυσχεράνας ἔπραξεν, ἀλλ’ ὅλως φιλοσοφίᾳ προσκεκρουκὼς καὶ πᾶσαν Ἑλληνικὴν μοῦσαν καὶ παιδείαν ὑπὸ φιλοτιμίας προπηλακίζων, ὅς γε καὶ Σωκράτη φησὶ λάλον καὶ βίαιον γενόμενον ἐπιχειρεῖν τρόπῳ δυνατὸς ἦν, τυραννεῖν τῆς πατρίδος, καταλύοντα τὰ ἔθη καὶ πρὸς ἐναντίας τοῖς νόμοις δόξας ἕλκοντα καὶ μεθιστάντα τοὺς πολίτας. τὴν δ’ Ἰσοκράτους διατριβὴν ἐπισκώπτων γηρᾶν φησὶ παρ’ αὑτῷ τοὺς μαθητάς ὡς ἐν Ἅιδου παρὰ Μίνῳ χρησομένους ταῖς τέχναις καὶ δίκας ἐροῦντας. τὸν δὲ παῖδα διαβάλλων πρὸς τὰ Ἑλληνικά φωνῇ κέχρηται θρασυτέρᾳ τοῦ γήρως, οἷον ἀποθεσπίζων καὶ προμαντεύων, ὡς ἀπολοῦσι Ῥωμαῖοι τὰ πράγματα γραμμάτων Ἑλληνικῶν ἀναπλησθέντες. ἀλλὰ ταύτην μὲν αὐτοῦ τὴν δυσφημίαν ὁ χρόνος ἀποδείκνυσι κενήν, ἐν ᾧ τοῖς τε πράγμασιν ἡ πόλις ἤρθη μεγίστη καὶ πρὸς Ἑλληνικὰ μαθήματα καὶ παιδείαν ἅπασαν ἔσχεν οἰκείως.", "st": "Cat. Ma. 23.1"}, {"sp": "N", "t": "ὁ δ’ οὐ μόνον ἀπηχθάνετο τοῖς φιλοσοφοῦσιν Ἑλλήνων, ἀλλὰ καὶ τοὺς ἰατρεύοντας ἐν Ῥώμῃ δι’ ὑποψίας εἶχε. καὶ τὸν Ἱπποκράτους, ὡς ἔοικεν, ἀκηκοώς λόγον, ὃν εἶπε τοῦ μεγάλου βασιλέως καλοῦντος αὐτὸν ἐπὶ πολλοῖς τισι ταλάντοις, οὐκ ἄν ποτε βαρβάροις Ἑλλήνων πολεμίοις ἑαυτὸν παρασχεῖν, ἔλεγε κοινὸν ὅρκον εἶναι τοῦτον ἰατρῶν ἁπάντων, καὶ παρεκελεύετο φυλάττεσθαι τῷ παιδὶ πάντας· αὑτῷ δὲ γεγραμμένον ὑπόμνημα εἶναι, καὶ πρὸς τοῦτο θεραπεύειν καὶ διαιτᾶν τοὺς νοσοῦντας οἴκοι, νῆστιν μὲν οὐδέποτε διατηρῶν οὐδένα, τρέφων δὲ λαχάνοις ἢ σαρκιδίοις νήσσης ἢ φάσσης ἢ λαγώ καὶ γὰρ τοῦτο κοῦφον εἶναι καὶ πρόσφορον ἀσθενοῦσι, πλὴν ὅτι πολλὰ συμβαίνει τοῖς φαγοῦσιν ἐνυπνιάζεσθαι τοιαύτῃ δὲ θεραπείᾳ καὶ διαίτῃ χρώμενος ὑγιαίνειν μὲν αὐτός, ὑγιαίνοντας δὲ τοὺς ἑαυτοῦ διαφυλάττειν.", "st": "Cat. Ma. 23.4"}, {"sp": "N", "t": "καὶ περί γε τοῦτο φαίνεται γεγονὼς οὐκ ἀνεμέσητος· καὶ γὰρ τὴν γυναῖκα καὶ τὸν υἱὸν ἀπέβαλεν. αὐτὸς δὲ τῷ σώματι πρὸς εὐεξίαν καὶ ῥώμην ἀσφαλῶς πεπηγὼς ἐπὶ πλεῖστον ἀντεῖχεν, ὥστε καὶ γυναικὶ πρεσβύτης ὢν σφόδρα πλησιάζειν καὶ γῆμαι γάμον οὐ καθ’ ἡλικίαν ἐκ τοιαύτης προφάσεως. ἀποβαλὼν τὴν γυναῖκα τῷ μὲν υἱῷ Παύλου θυγατέρα, Σκηπίωνος δὲ ἀδελφήν ἠγάγετο πρὸς γάμον, αὐτὸς δὲ χηρεύων ἐχρῆτο παιδίσκῃ κρύφα φοιτώσῃ πρὸς αὐτόν· ἦν οὖν ἐν οἰκίᾳ μικρᾷ νύμφην ἐχούσῃ τοῦ πράγματος αἴσθησις· καί ποτε τοῦ γυναίου θρασύτερον παρασοβῆσαι παρὰ τὸ δωμάτιον δόξαντος ὁ νεανίας εἶπε μὲν οὐδέν, ἐμβλέψας δέ πως πικρότερον καὶ διατραπεὶς οὐκ ἔλαθε τὸν πρεσβύτην. ὡς οὖν ἔγνω τὸ πρᾶγμα δυσχεραινόμενον ὑπ’ αὐτῶν, οὐδὲν ἐγκαλέσας οὐδὲ μεμψάμενος, ἀλλὰ καταβαίνων, ὥσπερ εἰώθει, μετὰ φίλων εἰς ἀγοράν Σαλώνιόν τινα τῶν ὑπογεγραμματευκότων αὐτῷ παρόντα καὶ συμπροπέμποντα μεγάλῃ φωνῇ προσαγορεύσας ἠρώτησεν, εἰ τὸ θυγάτριον συνήρμοκε νυμφίῳ. τοῦ δ’ ἀνθρώπου φήσαντος, ὡς οὐδὲ μέλλει μὴ πρότερον ἐκείνῳ κοινωσάμενος· καὶ μὴν ἐγώ σοι, φησίν, εὕρηκα κηδεστὴν ἐπιτήδειον, εἰ μὴ νὴ Δία τὰ τῆς ἡλικίας δυσχεραίνοιτο τἆλλα γὰρ οὐ μεμπτός ἐστι, σφόδρα δὲ πρεσβύτης. ὡς οὖν ὁ Σαλώνιος ἐκέλευε ταῦτα φροντίζειν καὶ διδόναι τὴν κόρην ᾧ προαιρεῖται, πελάτιν οὖσαν αὐτοῦ καὶ δεομένην τῆς ἐκείνου κηδεμονίας, οὐδεμίαν ὁ Κάτων ἀναβολὴν ποιησάμενος αὐτὸς ἔφη τὴν παρθένον αἰτεῖν ἑαυτῷ. καὶ τὸ μὲν πρῶτον, ὡς εἰκός, ὁ λόγος ἐξέπληξε τὸν ἄνθρωπον, πόρρω μὲν γάμου τὸν Κάτωνα, πόρρω δ’ αὑτὸν οἰκίας ὑπατικῆς καὶ θριαμβικῶν κηδευμάτων τιθέμενον σπουδῇ δὲ χρώμενον ὁρῶν ἄσμενος ἐδέξατο, καὶ καταβάντες εὐθὺς εἰς ἀγοράν ἐποιοῦντο τὴν ἐγγύην.", "st": "Cat. Ma. 24.1"}, {"sp": "N", "t": "πραττομένου δὲ τοῦ γάμου παραλαβὼν τοὺς ἐπιτηδείους ὁ υἱὸς τοῦ Κάτωνος ἠρώτησε τὸν πατέρα, μή τι μεμφόμενος ἢ λελυπημένος ὑπ’ αὐτοῦ μητρυιὰν ἐπάγεται. ὁ δὲ Κάτων ἀναβοήσας εὐφήμησον, εἶπεν, ὦ παῖ· πάντα γὰρ ἀγαστά μοι τὰ παρὰ σοῦ καὶ μεμπτὸν οὐδέν ἐπιθυμῶ δὲ πλείονας ἐμαυτῷ τε παῖδας καὶ πολίτας τῇ πατρίδι τοιούτους ἀπολιπεῖν. ταύτην δὲ τὴν γνώμην πρότερον εἰπεῖν φασι Πεισίστρατον τὸν Ἀθηναίων τύραννον ἐπιγήμαντα τοῖς ἐνηλίκοις παισὶ τὴν Ἀργολίδα Τιμώνασσαν, ἐξ ἧς Ἰοφῶντα καὶ Θεσσαλὸν αὐτῷ λέγουσι γενέσθαι. γήμαντι δὲ τῷ Κάτωνι γίνεται παῖς, ᾧ παρωνύμιον ἀπὸ τῆς μητρὸς ἔθετο Σαλώνιον. ὁ δὲ πρεσβύτερος υἱὸς ἐτελεύτησε στρατηγῶν, καὶ μέμνηται μὲν αὐτοῦ πολλάκις ἐν τοῖς βιβλίοις ὁ Κάτων ὡς ἀνδρὸς ἀγαθοῦ γεγονότος, πρᾴως δὲ καὶ φιλοσόφως λέγεται τὴν συμφορὰν ἐνεγκεῖν καὶ μηδὲν ἀμβλύτερος δι’ αὐτὴν εἰς τὰ πολιτικὰ γενέσθαι. οὐ γὰρ, ὡς Λεύκιος Λούκουλλος ὕστερον καὶ Μέτελλος ὁ Πίος, ἐξέκαμεν ὑπὸ γήρως πρὸς τὰ δημόσια, λειτουργίαν τὴν πολιτείαν ἡγούμενος, οὐδ’ ὡς πρότερον Σκηπίων ὁ Ἀφρικανὸς διὰ τὸν ἀντικρούσαντα πρὸς τὴν δόξαν αὐτοῦ φθόνον ἀποστραφεὶς τὸν δῆμον ἐκ μεταβολῆς ἐποιήσατο τοῦ λοιποῦ βίου τέλος ἀπραγμοσύνην, ἀλλ’, ὥσπερ Διονύσιόν τις ἔπεισε κάλλιστον ἐντάφιον ἡγεῖσθαι τὴν τυραννίδα, κάλλιστον αὐτὸς ἐγγήραμα τὴν πολιτείαν ποιησάμενος ἀναπαύσεσιν ἐχρῆτο καὶ παιδιαῖς, ὁπότε σχολάζοι, τῷ συντάττεσθαι βιβλία καὶ τῷ γεωργεῖν.", "st": "Cat. Ma. 24.5"}, {"sp": "N", "t": "συνετάττετο μὲν οὖν λόγους τε παντοδαποὺς καὶ ἱστορίας· γεωργίᾳ δὲ προσεῖχε νέος μὲν ὢν ἔτι καὶ διὰ τὴν χρείαν φησὶ γὰρ δυσὶ κεχρῆσθαι μόνοις πορισμοῖς γεωργίᾳ καὶ φειδοῖ, τότε δὲ διαγωγὴν καὶ θεωρίαν αὐτῷ τὰ γινόμενα κατ’ ἀγρὸν παρεῖχε, καὶ συντέτακταί γε βιβλίον γεωργικόν, ἐν ᾧ καὶ περὶ πλακούντων σκευασίας καὶ τηρήσεως ὀπώρας γέγραφεν, ἐν παντὶ φιλοτιμούμενος περιττὸς εἶναι καὶ ἴδιος. ἦν δὲ καὶ τὸ δεῖπνον ἐν ἀγρῷ δαψιλέστερον ἐκάλει γὰρ ἑκάστοτε τῶν ἀγρογειτόνων καὶ περιχώρων τοὺς συνήθεις καὶ συνδιῆγεν ἱλαρῶς, οὐ τοῖς καθ’ ἡλικίαν μόνοις ἡδὺς ὢν συγγενέσθαι καὶ ποθεινός, ἀλλὰ καὶ τοῖς νέοις, ἅτε δὴ πολλῶν μὲν ἔμπειρος πραγμάτων γεγονώς, πολλοῖς δὲ γράμμασι καὶ λόγοις ἀξίοις ἀκοῆς ἐντετυχηκώς. τὴν δὲ τράπεζαν ἐν τοῖς μάλιστα φιλοποιὸν ἡγεῖτο καὶ πολλὴ μὲν εὐφημία τῶν καλῶν καὶ ἀγαθῶν πολιτῶν ἐπεισήγετο, πολλὴ δ’ ἦν ἀμνηστία τῶν ἀχρήστων καὶ πονηρῶν, μήτε ψόγῳ μήτ’ ἐπαίνῳ πάροδον ὑπὲρ αὐτῶν τοῦ Κάτωνος εἰς τὸ συμπόσιον διδόντος.", "st": "Cat. Ma. 25.1"}, {"sp": "N", "t": "ἔσχατον δὲ τῶν πολιτευμάτων αὐτοῦ τὴν Καρχηδόνος ἀνάστασιν οἴονται γεγονέναι, τῷ μὲν ἔργῳ τέλος ἐπιθέντος τοῦ νέου Σκηπίωνος, βουλῇ δὲ καὶ γνώμῃ μάλιστα τῇ Κάτωνος ἀραμένων τὸν πόλεμον ἐξ αἰτίας τοιᾶσδε. Κάτων ἐπέμφθη πρὸς Καρχηδονίους καὶ Μασσανάσσην τὸν Νομάδα πολεμοῦντας ἀλλήλοις, ἐπισκεψόμενος τὰς τῆς διαφορᾶς προφάσεις, ὁ μὲν γὰρ ἦν τοῦ δήμου φίλος ἀπ’ ἀρχῆς, οἱ δ’ ἐγεγόνεισαν ἔνσπονδοι μετὰ τὴν ὑπὸ Σκηπίωνος ἧτταν, ἀφαιρέσει τε τῆς ἀρχῆς καὶ βαρεῖ δασμῷ χρημάτων κολουθέντες. εὑρὼν δὲ τὴν πόλιν οὐχ, ὡς ᾤοντο Ῥωμαῖοι, κεκακωμένην καὶ ταπεινὰ πράττουσαν, ἀλλὰ πολλῇ μὲν εὐανδροῦσαν ἡλικίᾳ, μεγάλων δὲ πλούτων γέμουσαν, ὅπλων δὲ παντοδαπῶν καὶ παρασκευῆς πολεμιστηρίου μεστὴν καὶ μικρὸν οὐδὲν ἐπὶ τούτοις φρονοῦσαν, οὐ τὰ Νομάδων ᾤετο καὶ Μασσανάσσου πράγματα Ῥωμαίους ὥραν ἔχειν τίθεσθαι καὶ διαιτᾶν, ἀλλ’ εἰ μὴ καταλήψονται πόλιν ἄνωθεν ἐχθρὰν καὶ βαρύθυμον ηὐξημένην ἀπίστως, πάλιν ἐν τοῖς ἴσοις κινδύνοις ἔσεσθαι. ταχέως οὖν ὑποστρέψας ἐδίδασκε τὴν βουλήν, ὡς αἱ πρότερον ἧτται καὶ συμφοραὶ Καρχηδονίων οὐ τοσοῦτον τῆς δυνάμεως ὅσον τῆς ἀνοίας ἀπαρύσασαι, κινδυνεύουσιν αὐτοὺς οὐκ ἀσθενεστέρους, ἐμπειροτέρους δὲ πολεμεῖν ἀπεργάσασθαι, ἤδη δὲ καὶ προανακινεῖσθαι τοῖς Νομαδικοῖς τοὺς πρὸς Ῥωμαίους ἀγῶνας, εἰρήνην δὲ καὶ σπονδὰς ὄνομα τοῦ πολέμου τῇ μελλήσει κεῖσθαι καιρὸν περιμένοντος.", "st": "Cat. Ma. 26.1"}, {"sp": "N", "t": "πρὸς τούτοις φασὶ τὸν Κάτωνά καὶ σῦκα τῶν Λιβυκῶν ἐπίτηδες ἐκβαλεῖν ἐν τῇ βουλῇ, τὴν τήβεννον ἀναβαλόμενον· εἶτα θαυμασάντων τὸ μέγεθος καὶ τὸ κάλλος εἰπεῖν, ὡς ἡ ταῦτα φέρουσα χώρα τριῶν ἡμερῶν πλοῦν ἀπέχει τῆς Ῥώμης. ἐκεῖνο δ’ ἤδη καὶ βιαιότερον, τὸ περὶ παντὸς οὗ δήποτε πράγματος γνώμην ἀποφαινόμενον προσεπιφωνεῖν οὕτως δοκεῖ δέ μοι καὶ Καρχηδόνα μὴ εἶναι. τοὐναντίον δὲ Πόπλιος Σκηπίων ὁ Νασικᾶς ἐπικαλούμενος ἀεὶ διετέλει λέγων καὶ ἀποφαινόμενος· δοκεῖ μοι Καρχηδόνα εἶναι. πολλὰ γὰρ, ὡς ἔοικεν, ὕβρει τὸν δῆμον ὁρῶν ἤδη πλημμελοῦντα καὶ δι’ εὐτυχίαν καὶ φρόνημα τῇ βουλῇ δυσκάθεκτον ὄντα καὶ τὴν πόλιν ὅλην ὑπὸ δυνάμεως ὅπῃ ῥέψειε ταῖς ὁρμαῖς βίᾳ συνεφελκόμενον, ἐβούλετο τοῦτον γοῦν τὸν φόβον ὥσπερ χαλινὸν ἐπικεῖσθαι σωφρονιστῆρα τῇ θρασύτητι τῶν πολλῶν, ἔλαττον μὲν ἡγούμενος ἰσχύειν Καρχηδονίους τοῦ περιγενέσθαι Ῥωμαίων, μεῖζον δὲ τοῦ καταφρονεῖσθαι. τῷ δὲ Κάτωνι τοῦτ’ αὐτὸ δεινὸν ἐφαίνετο, βακχεύοντι τῷ δήμῳ καὶ σφαλλομένῳ τὰ πολλὰ δι’ ἐξουσίαν πόλιν ἀεὶ μεγάλην, νῦν δὲ καὶ νήφουσαν ὑπὸ συμφορῶν καὶ κεκολασμένην ἐπικρέμασθαι καὶ μὴ παντάπασι τοὺς ἔξωθεν ἀνελεῖν τῆς ἡγεμονίας φόβους, ἀναφορὰς αὑτοῖς πρὸς τὰς οἴκοθεν ἁμαρτίας ἀπολιπόντας.", "st": "Cat. Ma. 27.1"}, {"sp": "N", "t": "οὕτω μὲν ἐξεργάσασθαι λέγεται τὸν τρίτον καὶ τελευταῖον ὁ Κάτων ἐπὶ Καρχηδονίους πόλεμον, ἀρξαμένων δὲ πολεμεῖν ἐτελεύτησεν, ἀποθεσπίσας περὶ τοῦ μέλλοντος ἐπιθήσειν τῷ πολέμῳ τέλος ἀνδρός, ὃς ἦν τότε μὲν νεανίας, χιλίαρχος δὲ στρατευόμενος ἀπεδείκνυτο καὶ γνώμης ἔργα καὶ τόλμης πρὸς τοὺς ἀγῶνας. ἀπαγγελλομένων δὲ τούτων εἰς Ῥώμην πυνθανόμενον τὸν Κάτωνά φασιν εἰπεῖν", "st": "Cat. Ma. 27.4"}, {"sp": "N", "t": "οἶος πέπνυται, τοὶ δὲ σκιαὶ ἀίσσουσι.", "st": "Cat. Ma. 27.4b"}, {"sp": "N", "t": "ταύτην μὲν οὖν τὴν ἀπόφασιν ταχὺ δι’ ἔργων ἐβεβαίωσεν ὁ Σκηπίων· ὁ δὲ Κάτων ἀπέλιπε γενεὰν ἕνα μὲν υἱὸν ἐκ τῆς ἐπιγαμηθείσης, ᾧ παρωνύμιον ἔφαμεν γενέσθαι Σαλώνιον, ἕνα δὲ υἱωνὸν ἐκ τοῦ τελευτήσαντος υἱοῦ. καὶ Σαλώνιος μὲν ἐτελεύτησε στρατηγῶν, ὁ δ’ ἐξ αὐτοῦ γενόμενος Μᾶρκος ὑπάτευσεν. ἦν δὲ πάππος οὗτος τοῦ φιλοσόφου Κάτωνος, ἀνδρὸς ἀρετῇ καὶ δόξῃ τῶν κατ’ αὐτὸν ἐπιφανεστάτου γενομένου.", "st": "Cat. Ma. 27.5"}, {"sp": "HDR", "t": "Ἀριστείδου καὶ Κάτωνος σύγκρισις"}, {"sp": "N", "t": "γεγραμμένων δὲ καὶ περὶ τούτων τῶν ἀξίων μνήμης, ὅλος ὁ τούτου βίος ὅλῳ τῷ θατέρου παρατεθεὶς οὐκ εὐθεώρητον ἔχει τὴν διαφοράν ἐναφανιζομένην πολλαῖς καὶ μεγάλαις ὁμοιότησιν. εἰ δὲ δεῖ κατὰ μέρος τῇ συγκρίσει διαλαβεῖν ὥσπερ ἔπος ἢ γραφὴν ἑκάτερον, τὸ μὲν ἐξ οὐχ ὑπαρχούσης ἀφορμῆς εἰς πολιτείαν καὶ δόξαν ἀρετῇ καὶ δυνάμει προελθεῖν ἀμφοτέροις κοινόν ἐστι. φαίνεται δ’ ὁ μὲν Ἀριστείδης οὔπω τότε μεγάλων οὐσῶν τῶν Ἀθηνῶν καὶ ταῖς οὐσίαις ἔτι συμμέτροις καὶ ὁμαλοῖς ἐπιβαλὼν δημαγωγοῖς καὶ στρατηγοῖς ἐπιφανὴς γενέσθαι· τὸ γὰρ μέγιστον ἦν τίμημα τότε πεντακοσίων μεδίμνων, τὸ δὲ δεύτερον τριακοσίων, ἔσχατον δὲ καὶ τρίτον διακοσίων· ὁ δὲ Κάτων ἐκ πολίχνης τε μικρᾶς καὶ διαίτης ἀγροίκου δοκούσης φέρων ἀφῆκεν ἑαυτὸν ὥσπερ εἰς πέλαγος ἀχανὲς τὴν ἐν Ῥώμῃ πολιτείαν, οὐκέτι Κουρίων καὶ Φαβρικίων καὶ Ἀτιλίων ἔργον οὖσαν ἡγεμόνων, οὐδ’ ἀπ’ ἀρότρου καὶ σκαφείου πένητας καὶ αὐτουργοὺς ἀναβαίνοντας ἐπὶ τὸ βῆμα προσιεμένην ἄρχοντας καὶ δημαγωγούς, ἀλλὰ πρὸς γένη μεγάλα καὶ πλούτους καὶ νομὰς καὶ σπουδαρχίας ἀποβλέπειν εἰθισμένην, καὶ δι’ ὄγκον ἤδη καὶ δύναμιν ἐντρυφῶσαν τοῖς ἄρχειν ἀξιοῦσιν. οὐκ ἦν δ’ ὅμοιον ἀντιπάλῳ χρῆσθαι Θεμιστοκλεῖ μήτ’ ἀπὸ γένους λαμπρῷ καὶ κεκτημένῳ μέτρια πέντε γὰρ ἢ τριῶν ταλάντων οὐσίαν αὐτῷ γενέσθαι λέγουσιν ὅτε πρῶτον ἥπτετο τῆς πολιτείας καὶ πρὸς Σκηπίωνας Ἀφρικανοὺς καὶ Σερουίους Γάλβας καὶ Κοϊντίους Φλαμινίνους ἁμιλλᾶσθαι περὶ πρωτείων, μηδὲν ὁρμητήριον ἔχοντα πλὴν φωνὴν παρρησιαζομένην ὑπὲρ τῶν δικαίων.", "st": "Comp. Arist.–Cat. 1.1"}, {"sp": "N", "t": "ἔτι δ’ Ἀριστείδης μὲν ἐν Μαραθῶνι καὶ πάλιν ἐν Πλαταιαῖς δέκατος ἦν στρατηγός, Κάτων δὲ δεύτερος μὲν ὕπατος ᾑρέθη πολλῶν ἀντιμετιόντων, δεύτερος δὲ τιμητής ἑπτὰ τοὺς ἐπιφανεστάτους καὶ πρώτους ἁμιλλωμένους ὑπερβαλόμενος. καὶ μὴν Ἀριστείδης μὲν ἐν οὐδενὶ τῶν κατορθωμάτων γέγονε πρῶτος, ἀλλὰ Μιλτιάδης ἔχει τοῦ Μαραθῶνος τὸ πρωτεῖον, Θεμιστοκλῆς δὲ τῆς Σαλαμῖνος, ἐν δὲ Πλαταιαῖς φησιν Ἡρόδοτος ἀνελέσθαι καλλίστην νίκην Παυσανίαν, Ἀριστείδῃ δὲ καὶ τῶν δευτερείων ἀμφισβητοῦσι Σωφάναι καὶ Ἀμεινίαι καὶ Καλλίμαχοι καὶ Κυναίγειροι διαπρεπῶς ἀριστεύσαντες ἐν ἐκείνοις τοῖς ἀγῶσι· Κάτων δ’ οὐ μόνον αὐτὸς ὑπατεύων ἐπρώτευσε καὶ χειρὶ καὶ γνώμῃ κατὰ τὸν Ἰβηρικὸν πόλεμον, ἀλλὰ καὶ χιλιαρχῶν περὶ Θερμοπύλας ὑπατεύοντος ἑτέρου τὴν δόξαν ἔσχε τῆς νίκης, μεγάλας ἐπ’ Ἀντίοχον Ῥωμαίοις ἀναπετάσας κλεισιάδας καὶ πρόσω μόνον ὁρῶντι τῷ βασιλεῖ περιστήσας κατὰ νώτου τὸν πόλεμον. ἐκείνη γὰρ ἡ νίκη περιφανῶς ἔργον οὖσα Κάτωνος ἐξήλασε τῆς Ἑλλάδος τὴν Ἀσίαν καὶ παρέσχεν ἐπιβατὴν αὖθις Σκηπίωνι.", "st": "Comp. Arist.–Cat. 2.1"}, {"sp": "N", "t": "πολεμοῦντες μὲν οὖν ἀήττητοι γεγόνασιν ἀμφότεροι, περὶ δὲ τὴν πολιτείαν Ἀριστείδης μὲν ἔπταισεν ἐξοστρακισθεὶς καὶ καταστασιασθεὶς ὑπὸ Θεμιστοκλέους, Κάτων δ’, οἵπερ ἦσαν ἐν Ῥώμῃ δυνατώτατοι καὶ μέγιστοι, πᾶσιν, ὡς ἔπος εἰπεῖν, ἀντιπάλοις χρώμενος καὶ μέχρι γήρως ὥσπερ ἀθλητὴς ἀγωνιζόμενος ἀπτῶτα διετήρησεν ἑαυτόν, πλείστας δὲ καὶ φυγὼν δημοσίας δίκας καὶ διώξας πολλὰς μὲν εἷλε, πάσας δ’ ἀπέφυγε, πρόβλημα τοῦ βίου καὶ δραστήριον ὄργανον ἔχων τὸν λόγον, ᾧ δικαιότερον ἄν τις ἢ τύχῃ καὶ δαίμονι τοῦ ἀνδρὸς τὸ μηδὲν παθεῖν παρ’ ἀξίαν ἀνατιθείη. μέγα γὰρ καὶ Ἀριστοτέλει τῷ φιλοσόφῳ τοῦτο προσεμαρτύρησεν Ἀντίπατρος γράφων περὶ αὐτοῦ μετὰ τὴν τελευτήν, ὅτι πρὸς τοῖς ἄλλοις ὁ ἀνὴρ καὶ τὸ πιθανὸν εἶχεν.", "st": "Comp. Arist.–Cat. 2.4"}, {"sp": "N", "t": "ὅτι μέν δὴ τῆς πολιτικῆς ἄνθρωπος ἀρετῆς οὐ κτᾶται τελειοτέραν, ὁμολογούμενόν ἐστι ταύτης δέ που μόριον οἱ πλεῖστοι τὴν οἰκονομικὴν οὐ οὐμικρόν τίθενται· καὶ γὰρ ἡ πόλις οἴκων τι σύστημα καὶ κεφάλαιον οὖσα ῥώννυται πρὸς τὰ δημόσια τοῖς ἰδίοις βίοις τῶν πολιτῶν εὐθενούντων, ὅπου καὶ Λυκοῦργος ἐξοικίσας μέν ἄργυρον, ἐξοικίσας δὲ χρυσὸν τῆς Σπάρτης, νόμισμα δὲ διεφθαρμένου πυρὶ σιδήρου θέμενος αὐτοῖς οἰκονομίας οὐκ ἀπήλλαξε τοὺς πολίτας, ἀλλά τὰ τρυφῶντα καὶ ὕπουλα καὶ φλεγμαίνοντα τοῦ πλούτου περιελών, ὅπως εὐπορήσωσι τῶν ἀναγκαίων καὶ χρησίμων ἅπαντες, ὡς ἄλλος οὐδεὶς νομοθέτης προὐνόησε, τὸν ἄπορον καὶ ἀνέστιον καὶ πένητα σύνοικον ἐπὶ κοινωνίᾳ πολιτείας μᾶλλον τοῦ πλουσίου καὶ ὑπερόγκου φοβηθείς. φαίνεται τοίνυν ὁ μέν Κάτων οὐδέν τι φαυλότερος οἴκου προστάτης ἢ πόλεως γενόμενος· καὶ γὰρ αὐτὸς ηὔξησε τὸν αὑτοῦ βίον καὶ κατέστη διδάσκαλος οἰκονομίας καὶ γεωργίας ἑτέροις, πολλὰ καὶ χρήσιμα περὶ τούτων συνταξάμενος· Ἀριστείδης δὲ τῇ πενίᾳ καὶ τὴν δικαιοσύνην συνδιέβαλεν ὡς οἰκοφθόρον καὶ πτωχοποιὸν καὶ πᾶσι μᾶλλον ἢ τοῖς κεκτημένοις ὠφέλιμον. καίτοι πολλὰ μέν Ἡσίοδος πρὸς δικαιοσύνην ἅμα καὶ οἰκονομίαν παρακαλῶν ἡμᾶς εἴρηκε καὶ τὴν ἀργίαν ὡς ἀδικίας ἀρχὴν λελοιδόρηκεν, εὖ δὲ καὶ Ὁμήρῳ πεποίηται·", "st": "Comp. Arist.–Cat. 3.1"}, {"sp": "N", "t": "ἔργον δέ μοι οὐ φίλον ἦεν<br>οὐδ’ οἰκωφελίη, ἥ τε τρέφει ἀγλαά τέκνα,", "st": "Comp. Arist.–Cat. 3.1b"}, {"sp": "N", "t": "ἀλλά μοι αἰεὶ νῆες ἐπήρετμοι φίλαι ἦσαν<br>καὶ πόλεμοι καὶ ἄκοντες ἐύξεστοι καὶ ὀϊστοί·", "st": "Comp. Arist.–Cat. 3.1c"}, {"sp": "N", "t": "ὡς τοὺς αὐτοὺς ἀμελοῦντας οἰκίας καὶ ποριζομένους ἐξ ἀδικίας. οὐ γὰρ, ὡς τοὔλαιον οἱ ἰατροί φασι τοῦ σώματος εἶναι τοῖς μέν ἐκτὸς ὠφελιμώτατον, τοῖς δ’ ἐντὸς βλαβερώτατον, οὕτως ὁ δίκαιος ἑτέροις μέν ἐστι χρήσιμος, αὑτοῦ δὲ καὶ τῶν ἰδίων ἀκηδής, ἀλλ’ ἔοικε ταύτῃ πεπηρῶσθαι τῷ Ἀριστείδῃ τὸ πολιτικόν, εἴπερ, ὡς οἱ πλεῖστοι λέγουσιν, οὐδὲ προῖκα τοῖς θυγατρίοις οὐδὲ ταφὴν αὐτῷ καταλιπέσθαι προὐνόησεν. ὅθεν ὁ μὲν Κάτωνος οἶκος ἄχρι γένους τετάρτου στρατηγοὺς καὶ ὑπάτους τῇ Ῥώμῃ παρεῖχε· καὶ γὰρ υἱωνοὶ καὶ τούτων ἔτι παῖδες ἦρξαν ἀρχὰς τὰς μεγίστας· τῆς δ’ Ἀριστείδου τοῦ πρωτεύσαντος Ἑλλήνων γενεᾶς ἡ πολλὴ καὶ ἄπορος πενίᾳ τοὺς μέν εἰς ἀγυρτικοὺς κατέβαλε πίνακας, τοὺς δὲ δημοσίῳ τὰς χεῖρας ἐράνῳ δι’ ἔνδειαν ὑπέχειν ἠνάγκασεν, οὐδενὶ δὲ λαμπρὸν οὐδέν οὐδ’ ἄξιον ἐκείνου τοῦ ἀνδρὸς φρονῆσαι παρέσχεν.", "st": "Comp. Arist.–Cat. 3.5"}, {"sp": "N", "t": "ἢ τοῦτο πρῶτον ἀμφιλογίαν ἔχει; πενία γὰρ αἰσχρὸν οὐδαμοῦ μὲν δι’ αὑτήν, ἀλλ’ ὅπου δεῖγμα ῥᾳθυμίας ἐστίν, ἀκρασίας, πολυτελείας, ἀλογιστίας, ἀνδρὶ δὲ σώφρονι καὶ φιλοπόνῳ καὶ δικαίῳ καὶ ἀνδρείῳ καὶ δημοσιεύοντι ταῖς ἀρεταῖς ἁπάσαις συνοῦσα μεγαλοψυχίας ἐστὶ καὶ μεγαλοφροσύνης σημεῖον. οὐ γὰρ ἔστι πράττειν μεγάλα φροντίζοντα μικρῶν, οὐδὲ πολλοῖς δεομένοις βοηθεῖν πολλῶν αὐτὸν δεόμενον. μέγα δ’ εἰς πολιτείαν ἐφόδιον οὐχὶ πλοῦτος, ἀλλ’ αὐτάρκεια, τῷ μηδενὸς ἰδίᾳ τῶν περιττῶν δεῖσθαι πρὸς οὐδεμίαν ἀσχολίαν ἄγουσα τῶν δημοσίων, ἀπροσδεὴς μὲν γὰρ ἁπλῶς ὁ θεὸς, ἀνθρωπίνης δ’ ἀρετῆς, ᾧ συνάγεται πρὸς τὸ ἐλάχιστον ἡ χρείᾳ, τοῦτο τελειότατον καὶ θειότατον. ὡς γὰρ σῶμα τὸ καλῶς πρὸς εὐεξίαν κεκραμένον οὔτ’ ἐσθῆτος οὔτε τροφῆς δεῖται περιττῆς, οὕτω καὶ βίος καὶ οἶκος ὑγιαίνων ἀπὸ τῶν τυχόντων διοικεῖται. δεῖ δὲ τῇ χρείᾳ σύμμετρον ἔχειν τὴν κτῆσιν· ὡς ὅ γε πολλὰ συνάγων, ὀλίγοις δὲ χρώμενος οὐκ ἔστιν αὐτάρκης, ἀλλ’ εἴτε μὴ δεῖται, τῆς παρασκευῆς ὧν οὐκ ὀρέγεται μάταιος, εἴτ’ ὀρέγεται, μικρολογίᾳ κολούων τὴν ἀπόλαυσιν ἄθλιος.", "st": "Comp. Arist.–Cat. 4.1"}, {"sp": "N", "t": "αὐτοῦ γέ τοι Κάτωνος ἡδέως ἂν πυθοίμην· εἰ μὲν ἀπολαυστὸν ὁ πλοῦτός ἐστι, τί σεμνύνῃ τῷ πολλὰ κεκτημένος ἀρκεῖσθαι μετρίοις; εἰ δὲ λαμπρόν ἐστιν, ὥσπερ ἐστίν, ἄρτῳ τε χρῆσθαι τῷ προστυχόντι καὶ πίνειν οἷον ἐργάται πίνουσι καὶ θεράποντες οἶνον καὶ πορφύρας μὴ δεηθῆναι μηδὲ οἰκίας κεκονιαμένης, οὐδὲν οὔτ’ Ἀριστείδης οὔτ’ Ἐπαμεινώνδας οὔτε Μάνιος Κούριος οὔτε Γάιος Φαβρίκιος ἐνέλιπον τοῦ προσήκοντος, χαίρειν ἐάσαντες τὴν κτῆσιν ὧν τὴν χρῆσιν ἀπεδοκίμαζον. οὐ γὰρ ἦν ἀναγκαῖον ἀνθρώπῳ γογγυλίδας ἥδιστον ὄψον πεποιημένῳ καὶ δι’ αὑτοῦ ταύτας ἕψοντι, ματτούσης ἅμα τῆς γυναικὸς ἄλφιτα, τοσαῦτα περὶ ἀσσαρίου θρυλεῖν καὶ γράφειν ἀφ’ ἧς ἄν τις ἐργασίας τάχιστα πλούσιος γένοιτο, μέγα γὰρ τὸ εὐτελὲς καὶ αὔταρκες, ὅτι τῆς ἐπιθυμίας ἅμα καὶ τῆς φροντίδος ἀπαλλάττει τῶν περιττῶν. διὸ καὶ τοῦτό φασιν ἐν τῇ Καλλίου δίκῃ τὸν Ἀριστείδην εἰπεῖν, ὡς αἰσχύνεσθαι πενίαν προσήκει τοῖς ἀκουσίως πενομένοις, τοῖς δ’, ὥσπερ αὐτὸς, ἑκουσίως, ἐγκαλλωπίζεσθαι. γελοῖον γὰρ οἴεσθαι ῥᾳθυμίας εἶναι τὴν Ἀριστείδου πενίαν, ᾧ παρῆν αἰσχρὸν εἰργασμένῳ μηδέν, ἀλλ’ ἕνα σκυλεύσαντι βάρβαρον ἢ μίαν σκηνὴν καταλαβόντι πλουσίῳ γενέσθαι, ταῦτα μὲν οὖν περὶ τούτων.", "st": "Comp. Arist.–Cat. 4.4"}, {"sp": "N", "t": "στρατηγίαι δὲ αἱ μὲν Κάτωνος οὐδὲν ὡς μεγάλοις πράγμασι μέγα προσέθηκαν, ἐν δὲ ταῖς Ἀριστείδου τὰ κάλλιστα καὶ λαμπρότατα καὶ πρῶτα τῶν Ἑλληνικῶν ἔργων ἐστίν, ὁ Μαραθών, ἡ Σαλαμίς, αἱ Πλαταιαί. καὶ οὐκ ἄξιον δήπου παραβαλεῖν τῷ Ξέρξῃ τὸν Ἀντίοχον καὶ τὰ περιαιρεθέντα τῶν Ἰβηρικῶν πόλεων τείχη ταῖς τοσαύταις μὲν ἐν γῇ, τοσαύταις δ’ ἐν θαλάσσῃ πεσούσαις μυριάσιν· ἐν οἷς Ἀριστείδης ἔργῳ μὲν οὐδενὸς ἐλείπετο, δόξης δὲ καὶ στεφάνων, ὥσπερ ἀμέλει πλούτου καὶ χρημάτων, ὑφήκατο τοῖς μᾶλλον δεομένοις, ὅτι καὶ πάντων τούτων διέφερεν·", "st": "Comp. Arist.–Cat. 5.1"}, {"sp": "N", "t": "ἐγὼ δ’ οὐ μέμφομαι μὲν Κάτωνος τὸ μεγαλύνειν ἀεί καὶ πρῶτον ἑαυτὸν ἁπάντων τίθεσθαι· καίτοι φησὶν ἔν τινι λόγῳ τὸ ἐπαινεῖν αὑτὸν ὥσπερ τὸ λοιδορεῖν ἄτοπον εἶναι· τελειότερος δέ μοι δοκεῖ πρὸς ἀρετὴν τοῦ πολλάκις ἑαυτὸν ἐγκωμιάζοντος ὁ μηδ’ ἑτέρων τοῦτο ποιούντων δεόμενος. τὸ γὰρ ἀφιλότιμον οὐ μικρὸν εἰς πρᾳότητα πολιτικὴν ἐφόδιον, καὶ τοὐναντίον ἡ φιλοτιμία χαλεπὸν καὶ φθόνου γονιμώτατον, ἧς ὁ μὲν ἀπήλλακτο παντάπασιν, ὁ δὲ καὶ πάνυ πολλῆς μετεῖχεν. Ἀριστείδης μέν γε Θεμιστοκλεῖ τὰ μέγιστα συμπράττων καὶ τρόπον τινὰ τὴν στρατηγίαν αὐτοῦ δορυφορῶν ὤρθωσε τὰς Ἀθήνας, Κάτων δ’ ἀντιπράττων Σκηπίωνι μικροῦ μὲν ἀνέτρεψε καὶ διελυμήνατο τὴν ἐπὶ Καρχηδονίους αὐτοῦ στρατηγίαν, ἐν ᾗ τὸν ἀήττητον Ἀννίβαν καθεῖλε, τέλος δὲ μηχανώμενος ἀεί τινας ὑποψίας καὶ διαβολάς αὐτὸν μὲν ἐξήλασε τῆς πόλεως, τὸν δ’ ἀδελφὸν αἰσχίστῃ κλοπῆς καταδίκῃ περιέβαλεν.", "st": "Comp. Arist.–Cat. 5.3"}, {"sp": "N", "t": "ἥν τοίνυν πλείστοις ὁ Κάτων κεκόσμηκε καὶ καλλίστοις ἐπαίνοις ἀεὶ σωφροσύνην Ἀριστείδης μὲν ἄθικτον ὡς ἀληθῶς καὶ καθαρὰν ἐτήρησεν, αὐτοῦ δὲ τοῦ Κάτωνος ὁ παρ’ ἀξίαν ἅμα καὶ παρ’ ὥραν γάμος οὐ μικρὰν οὐδὲ φαύλην εἰς τοῦτο διαβολὴν κατεσκέδασε. πρεσβύτην γὰρ ἤδη τοσοῦτον ἐνηλίκῳ παιδὶ καὶ γυναικὶ νύμφῃ παιδὸς ἐπιγῆμαι κόρην ὑπηρέτου καὶ δημοσιεύοντος ἐπὶ μισθῷ πατρὸς οὐδαμοῦ καλόν, ἀλλ’ εἴτε πρὸς ἡδονὴν ταῦτ’ ἔπραξεν εἴτ’ ὀργῇ διὰ τὴν ἑταίραν ἀμυνόμενος τὸν υἱόν, αἰσχύνην ἔχει καὶ τὸ ἔργον καὶ ἡ πρόφασις. ᾧ δ’αὐτὸς ἐχρήσατο λόγῳ κατειρωνευόμενος τὸ μειράκιον, οὐκ ἦν ἀληθής, εἰ γὰρ ἐβούλετο παῖδας ἀγαθοὺς ὁμοίως τεκνῶσαι, γάμον ἔδει λαβεῖν γενναῖον ἐξ ἀρχῆς σκεψάμενον, οὐχ ἕως μὲν ἐλάνθανεν ἀνεγγύῳ γυναικὶ καὶ κοινῇ συγκοιμώμενος ἀγαπᾶν, ἐπεὶ δὲ ἐφωράθη ποιήσασθαι πενθερὸν, ὃν ῥᾷστα πείσειν, οὐχ ᾧ κάλλιστα κηδεύσειν ἔμελλεν.", "st": "Comp. Arist.–Cat. 6.1"}, {"sp": "HDR", "t": "Φιλοποίμην"}, {"sp": "N", "t": "Κλέανδρος ἦν ἐν Μαντινείᾳ γένους τε πρώτου καὶ δυνηθεὶς ἐν τοῖς μάλιστα τῶν πολιτῶν, τύχῃ δὲ χρησάμενος καὶ τὴν ἑαυτοῦ φυγών ἧκεν εἰς Μεγάλην πόλιν οὐχ ἥκιστα διὰ τὸν Φιλοποίμενος πατέρα Κραῦγιν, ἄνδρα πάντων ἕνεκα λαμπρόν, ἰδίᾳ δὲ πρὸς ἐκεῖνον οἰκείως ἔχοντα. ζῶντος μὲν οὖν αὐτοῦ πάντων ἐτύγχανε, τελευτήσαντος δὲ τὴν ἀμοιβὴν τῆς φιλοξενίας ἀποδιδούς ἔθρεψεν αὐτοῦ τὸν υἱὸν ὀρφανὸν ὄντα, καθάπερ φησὶν Ὅμηρος ὑπὸ τοῦ Φοίνικος τὸν Ἀχιλλέα τραφῆναι, γενναίαν τινὰ καὶ βασιλικὴν τοῦ ἤθους εὐθὺς ἐξ ἀρχῆς πλάσιν καὶ αὔξησιν λαμβάνοντος, ἤδη δὲ τοῦ Φιλοποίμενος ἀντίπαιδος ὄντος Ἔκδημος καὶ Μεγαλοφάνης οἱ Μεγαλοπολῖται διεδέξαντο τὴν ἐπιμέλειαν, Ἀρκεσιλάῳ συνήθεις ἐν Ἀκαδημείᾳ γεγονότες καὶ φιλοσοφίαν μάλιστα τῶν καθ’ ἑαυτοὺς ἐπὶ πολιτείαν καὶ πράξεις προαγαγόντες. οὗτοι καὶ τὴν ἑαυτῶν πατρίδα τυραννίδος ἀπήλλαξαν, τοὺς ἀποκτενοῦντας Ἀριστόδημον κρύφα παρασκευάσαντες, καὶ Νικοκλέα τὸν Σικυωνίων τύραννον Ἀράτῳ συνεξέβαλον, καὶ Κυρηναίοις δεηθεῖσι, τεταραγμένων τῶν κατὰ τὴν πόλιν καὶ νοσούντων, πλεύσαντες εὐνομίαν ἔθεντο καὶ διεκόσμησαν ἄριστα τὴν πόλιν. αὐτοί γε μὴν ἐν τοῖς ἄλλοις ἔργοις καὶ τὴν Φιλοποίμενος ἐποιοῦντο παίδευσιν, ὡς κοινὸν ὄφελος τῇ Ἑλλάδι τὸν ἄνδρα τοῦτον ὑπὸ φιλοσοφίας ἀπεργασόμενοι. καὶ γὰρ ὥσπερ ὀψίγονον ἐν γήρᾳ ταῖς τῶν παλαιῶν ἡγεμόνων ἐπιτεκοῦσα τοῦτον ἀρεταῖς ἡ Ἑλλὰς ἠγάπησε διαφερόντως καὶ συνηύξησε τῇ δόξῃ τὴν δύναμιν. Ῥωμαίων δέ τις ἐπαινῶν ἔσχατον αὐτὸν Ἑλλήνων προσεῖπεν, ὡς οὐδένα μέγαν μετὰ τοῦτον ἔτι τῆς Ἑλλάδος ἄνδρα γειναμένης οὐδὲ αὑτῆς ἄξιον.", "st": "Phil. 1.1"}, {"sp": "N", "t": "ἦν δὲ τὸ μὲν εἶδος οὐκ αἰσχρός, ὡς ἔνιοι νομίζουσιν εἰκόνα γὰρ αὐτοῦ διαμένουσαν ἐν Δελφοῖς ὁρῶμεν· τὴν δὲ τῆς ξένης τῆς Μεγαρικῆς ἄγνοιαν συμβῆναι λέγουσι δι’ εὐκολίαν τινὰ καὶ ἀφέλειαν αὐτοῦ, πυνθανομένη γὰρ ἔρχεσθαι πρὸς αὐτοὺς τὸν στρατηγὸν τῶν Ἀχαιῶν ἐθορυβεῖτο παρασκευάζουσα δεῖπνον, οὐ παρόντος κατὰ τύχην τοῦ ἀνδρός. ἐν τούτῳ δὲ τοῦ Φιλοποίμενος εἰσελθόντος χλαμύδιον εὐτελὲς ἔχοντος, οἰομένη τινὰ τῶν ὑπηρετῶν εἶναι καὶ πρόδρομον παρεκάλει τῆς διακονίας συνεφάψασθαι. καὶ ὁ μὲν εὐθὺς ἀπορρίψας τὴν χλαμύδα τῶν ξύλων ἔσχιζεν ὁ δὲ ξένος ἐπεισελθὼν καὶ θεασάμενος, τί τοῦτο, ἔφη, ὦ Φιλοποίμην; τί γὰρ ἄλλο, ἔφη δωρίζων ἐκεῖνος, ἢ κακᾶς ὄψεως δίκας δίδωμι; τοῦ δὲ ἄλλου σώματος τὴν φύσιν ἐπισκώπτων ὁ Τίτος εἶπεν, ὦ Φιλοποίμην, ὡς καλὰς χεῖρας ἔχεις καὶ σκέλη· γαστέρα δ’ οὐκ ἔχεις· ἦν γὰρ ἐκ τῶν μέσων στενώτερος. τὸ μέντοι σκῶμμα πρὸς τὴν δύναμιν αὐτοῦ μᾶλλον ἐλέχθη, καὶ γὰρ ὁπλίτας ἔχων ἀγαθοὺς καὶ ἱππεῖς χρημάτων πολλάκις οὐκ εὐπόρει. ταῦτα μὲν οὖν ἐν ταῖς σχολαῖς περὶ τοῦ Φιλοποίμενος λέγεται.", "st": "Phil. 2.1"}, {"sp": "N", "t": "τοῦ δ’ ἤθους τὸ φιλότιμον οὐκ ἦν παντάπασι φιλονεικίας καθαρὸν οὐδ’ ὀργῆς ἀπηλλαγμένον ἀλλὰ καίπερ Ἐπαμεινώνδου βουλόμενος εἶναι μάλιστα ζηλωτής, τὸ δραστήριον καὶ συνετὸν αὐτοῦ καὶ ὑπὸ χρημάτων ἀπαθὲς ἰσχυρῶς ἐμιμεῖτο, τῷ δὲ πρᾴῳ καὶ βαθεῖ καὶ φιλανθρώπῳ παρὰ τὰς πολιτικὰς διαφορὰς ἐμμένειν οὐ δυνάμενος δι’ ὀργὴν καὶ φιλονεικίαν μᾶλλον ἐδόκει στρατιωτικῆς ἢ πολιτικῆς ἀρετῆς οἰκεῖος εἶναι. καὶ γὰρ ἐκ παίδων εὐθὺς ἦν φιλοστρατιώτης, καὶ τοῖς πρὸς τοῦτο χρησίμοις μαθήμασιν ὑπήκουε προθύμως, ὁπλομαχεῖν καὶ ἱππεύειν. ἐπεὶ δὲ καὶ παλαίειν εὐφυῶς ἐδόκει καὶ παρεκάλουν αὐτὸν ἐπὶ τὴν ἄθλησιν ἔνιοι τῶν φίλων καὶ τῶν ἐπιτρόπων, ἠρώτησεν αὐτούς μή τι πρὸς τὴν στρατιωτικὴν ἄσκησιν ὑπὸ τῆς ἀθλήσεως βλαβήσοιτο. τῶν δὲ φαμένων, ὅπερ ἦν, ἀθλητικὸν στρατιωτικοῦ σῶμα καὶ βίον διαφέρειν τοῖς πᾶσι, μάλιστα δὲ δίαιταν ἑτέραν καὶ ἄσκησιν εἶναι, τῶν μὲν ὕπνῳ τε πολλῷ καὶ πλησμοναῖς ἐνδελεχέσι καὶ κινήσεσί τεταγμέναις καὶ ἡσυχίαις αὐξόντων τε καὶ διαφυλαττόντων τὴν ἕξιν ὑπὸ πάσης ῥοπῆς καὶ παρεκβάσεως τοῦ συνήθους ἀκροσφαλῆ πρὸς μεταβολὴν οὖσαν, τὰ δὲ πάσης μὲν πλάνης ἔμπειρα καὶ πάσης ἀνωμαλίας προσῆκον εἶναι, μάλιστα δὲ φέρειν ῥᾳδίως μὲν ἔνδειαν εἰθισμένα, ῥᾳδίως δὲ ἀγρυπνίαν, ἀκούσας ὁ Φιλοποίμην οὐ μόνον αὐτὸς ἔφυγε τὸ πρᾶγμα καὶ κατεγέλασεν, ἀλλὰ καὶ στρατηγῶν ὕστερον ἀτιμίαις καὶ προπηλακισμοῖς, ὅσον ἦν ἐπ’ αὐτῷ, πᾶσαν ἄθλησιν ἐξέβαλεν ὡς τὰ χρησιμώτατα τῶν σωμάτων εἰς τοὺς ἀναγκαίους ἀγῶνας ἄχρηστα ποιοῦσαν.", "st": "Phil. 3.1"}, {"sp": "N", "t": "ἀπαλλαγεὶς δὲ διδασκάλων καὶ παιδαγωγῶν ἐν μὲν ταῖς πολιτικαῖς στρατείαις, ἃς ἐποιοῦντο κλωπείας ἕνεκα καὶ λεηλασίας εἰς τὴν Λακωνικὴν ἐμβάλλοντες, εἴθισεν αὑτὸν πρῶτον μὲν ἐκστρατευόντων, ὕστατον δὲ ἀπερχομένων βαδίζειν. σχολῆς δὲ οὔσης ἢ κυνηγῶν διεπόνει τὸ σῶμα καὶ κατεσκεύαζε κοῦφον ἅμα καὶ ῥωμαλέον, ἢ γεωργῶν. ἦν γὰρ ἀγρὸς αὐτῷ καλὸς ἀπὸ σταδίων εἴκοσι τῆς πόλεως, εἰς τοῦτον ἐβάδιζε καθ’ ἡμέραν μετὰ τὸ ἄριστον ἢ μετὰ τὸ δεῖπνον, καὶ καταβαλὼν ἑαυτὸν ἐπὶ στιβαδίου τοῦ τυχόντος ὥσπερ ἕκαστος τῶν ἐργατῶν ἀνεπαύετο. πρωῒ δὲ ἀναστὰς καὶ συνεφαψάμενος ἔργου τοῖς ἀμπελουργοῦσιν ἢ βοηλατοῦσιν, αὖθις εἰς πόλιν ἀπῄει καὶ περὶ τὰ δημόσια τοῖς φίλοις καὶ τοῖς ἄρχουσι συνησχολεῖτο.", "st": "Phil. 4.1"}, {"sp": "N", "t": "τὰ μὲν οὖν ἐκ τῶν στρατειῶν προσιόντα κατάνλισκεν εἰς ἵππους καὶ ὅπλα καὶ λύσεις αἰχμαλώτων, τὸν δὲ οἶκον ἀπὸ τῆς γεωργίας αὔξειν ἐπειρᾶτο δικαιοτάτῳ τῶν χρηματισμῶν, οὐδὲ τοῦτο ποιούμενος πάρεργον, ἀλλὰ καὶ πάνυ προσήκειν οἰόμενος οἰκεῖα κεκτῆσθαι τὸν ἀλλοτρίων ἀφεξόμενον. ἠκροᾶτο δὲ λόγων καὶ συγγράμμασι φιλοσόφων ἐνετύγχανεν, οὐ πᾶσιν, ἀλλ’ ἀφ’ ὧν ἐδόκει πρὸς ἀρετὴν ὠφελεῖσθαι. καὶ τῶν Ὁμηρικῶν ὅσα τὰς πρὸς ἀνδρείαν ἐγείρειν καὶ παροξύνειν ἐνόμιζε φαντασίας, τούτοις προσεῖχε. τῶν δ’ ἄλλων ἀναγνωσμάτων μάλιστα τοῖς Εὐαγγέλου τακτικοῖς ἐνεφύετο καὶ τὰς περὶ Ἀλέξανδρον ἱστορίας κατεῖχε, τοὺς λόγους ἐπὶ τὰ πράγματα καταστρέφειν οἰόμενος, εἰ μὴ σχολῆς ἕνεκα καὶ λαλιᾶς ἀκάρπου περαίνοιντο. καὶ γὰρ τῶν τακτικῶν θεωρημάτων τὰς ἐπὶ τοῖς πινακίοις διαγραφὰς ἐῶν χαίρειν, ἐπὶ τῶν τόπων αὐτῶν ἐλάμβανεν ἔλεγχον καὶ μελέτην ἐποιεῖτο, χωρίων συγκλινίας καὶ πεδίων ἀποκοπὰς, καὶ ὅσα περὶ ῥείθροις ἢ τάφροις ἢ στενωποῖς πάθη καὶ σχήματα διασπωμένης καὶ πάλιν συστελλομένης φάλαγγος, ἐπισκοπῶν αὐτὸς πρὸς αὑτὸν ἐν ταῖς ὁδοιπορίαις καὶ τοῖς μεθ’ ἑαυτοῦ προβάλλων. ἔοικε γὰρ οὗτος ὁ ἀνὴρ περαιτέρω τῆς ἀνάγκης ἐμφιλοκαλῆσαι τοῖς στρατιωτικοῖς, καὶ τὸν πόλεμον ὡς ποικιλωτάτην ὑπόθεσιν τῆς ἀρετῆς ἀσπάσασθαι, καὶ ὅλως καταφρονεῖν τῶν ἀπολειπομένων ὡς ἀπράκτων.", "st": "Phil. 4.3"}, {"sp": "N", "t": "ἤδη δὲ αὐτοῦ τριάκοντα ἔτη γεγονότος Κλεομένης ὁ βασιλεὺς Λακεδαιμονίων νυκτὸς ἐξαίφνης προσπεσὼν τῇ Μεγάλῃ πόλει καὶ τὰς φυλακὰς βιασάμενος ἐντὸς παρῆλθε καὶ τήν ἀγορὰν κατέλαβεν. ἐκβοηθήσας δὲ Φιλοποίμην τοὺς μὲν πολεμίους οὐ κατίσχυσεν ἐξελάσαι, καίπερ ἐρρωμένως καὶ παραβόλως διαγωνισάμενος, τοὺς δὲ πολίτας τρόπον τινὰ τῆς πόλεως ἐξέκλεψε, προσμαχόμενος τοῖς ἐπιδιώκουσι καὶ τὸν Κλεομένην περισπῶν ἐφ’ ἑαυτόν, ὡς χαλεπῶς καὶ μόλις ὕστατος ἀπελθεῖν, ἀποβαλὼν τὸν ἵππον καὶ τραυματίας γενόμενος. ἐπεὶ δὲ προσέπεμψεν αὐτοῖς ὁ Κλεομένης εἰς Μεσσήνην ἀπελθοῦσι τήν τε πόλιν μετὰ τῶν χρημάτων ἀποδιδοὺς καὶ τήν χώραν, ὁρῶν ὁ Φιλοποίμην τοὺς πολίτας ἀσμένως δεχομένους καὶ σπεύδοντας ἐπανελθεῖν ἐνέστη καὶ διεκώλυσε τῷ λόγῳ, διδάσκων ὡς οὐκ ἀποδίδωσι τήν πόλιν Κλεομένης, προσκτᾶται δὲ τοὺς πολίτας ἐπὶ τῷ καὶ τήν πόλιν ἔχειν βεβαιότερον οὐ γὰρ ἕξειν αὐτόν ὅπως οἰκίας καὶ τείχη κενὰ φυλάξει καθήμενος, ἀλλὰ καὶ τούτων ὑπ’ ἐρημίας ἐκπεσεῖσθαι. ταῦτα λέγων τοὺς μὲν πολίτας ἀπέτρεψε, τῷ δὲ Κλεομένει πρόφασιν παρέσχε λυμήνασθαι καὶ καταβαλεῖν τὰ πλεῖστα τῆς πόλεως καὶ χρημάτων εὐπορήσαντι μεγάλων ἀπελθεῖν.", "st": "Phil. 5.1"}, {"sp": "N", "t": "ἐπεὶ δὲ Ἀντίγονος ὁ βασιλεὺς βοηθῶν ἐπὶ τὸν Κλεομένην μετὰ τῶν Ἀχαιῶν ἐστράτευσε, καὶ τὰς περὶ Σελλασίαν ἄκρας καὶ τὰς ἐμβολὰς κατέχοντος αὐτοῦ παρέταξε τὴν δύναμιν ἐγγύς ἐπιχειρεῖν καὶ βιάζεσθαι διανοούμενος, ἦν μὲν ἐν τοῖς ἱππεῦσι μετὰ τῶν ἑαυτοῦ πολιτῶν τεταγμένος ὁ Φιλοποίμην, καὶ παραστάτας εἶχεν Ἰλλυριούς, οἷς τὰ λήγοντα τῆς παρατάξεως συνεπέφρακτο πολλοῖς οὖσι καὶ μαχίμοις. εἴρητο δὲ αὐτοῖς ἐφεδρεύουσιν ἡσυχίαν ἔχειν ἄχρι ἂν ἀπὸ θατέρου κέρως ὑπὸ τοῦ βασιλέως ἀρθῇ φοινικὶς ὑπὲρ σαρίσης διατεταμένη. τῶν δὲ ἡγεμόνων τοῖς Ἰλλυριοῖς πειρωμένων ἐκβιάζεσθαι τοὺς Λακεδαιμονίους, καὶ τῶν Ἀχαιῶν, ὥσπερ προσετέτακτο, τὴν ἐφεδρείαν ἐν τάξει διαφυλαττόντων, Εὐκλείδας ὁ τοῦ Κλεομένους ἀδελφὸς καταμαθὼν τὸ γινόμενον διάσπασμα περὶ τοὺς πολεμίους ταχὺ τοὺς ἐλαφροτάτους τῶν ψιλῶν περιέπεμψεν, ἐξόπισθεν τοῖς Ἰλλυριοῖς ἐπιπεσεῖν κελεύσας καὶ περισπᾶν ἐρήμους τῶν ἱππέων ἀπολελειμμένους.", "st": "Phil. 6.1"}, {"sp": "N", "t": "γινομένων δὲ τούτων καὶ τῶν ψιλῶν τοὺς Ἰλλυριοὺς περισπώντων καὶ διαταραττόντων, συνιδὼν ὁ Φιλοποίμην οὐ μέγα ὂν ἔργον ἐπιθέσθαι τοῖς ψιλοῖς καὶ τὸν καιρὸν ὑφηγούμενον τοῦτο, πρῶτον μὲν ἔφραζε τοῖς βασιλικοῖς, ὡς δὲ οὐκ ἔπειθεν, ἀλλὰ μαίνεσθαι δοκῶν κατεφρονεῖτο, οὐδέπω μεγάλης οὐδὲ ἀξιοπίστου πρὸς τηλικοῦτο στρατήγημα δόξης περὶ αὐτὸν οὔσης, αὐτὸς ἐμβάλλει συνεπισπασάμενος τοὺς πολίτας. γενομένης δὲ ταραχῆς τὸ πρῶτον, εἶτα φυγῆς καὶ φόνου πολλοῦ τῶν ψιλῶν, βουλόμενος ἔτι μᾶλλον ἐπιρρῶσαι τοὺς βασιλικοὺς καὶ προσμῖξαι κατὰ τάχος θορυβουμένοις τοῖς πολεμίοις τὸν μὲν ἵππον ἀφῆκεν, αὐτὸς δὲ πρὸς χωρία σκολιὰ καὶ μεστὰ ῥείθρων καὶ φαράγγων πεζὸς ἐν ἱππικῷ θώρακι καὶ σκευῇ βαρυτέρᾳ χαλεπῶς καὶ ταλαιπώρως ἁμιλλώμενος διελαύνεται διαμπερὲς ὁμοῦ τοὺς μηροὺς ἑκατέρους ἑνὶ μεσαγκύλῳ, καιρίας μὲν οὐ γενομένης, ἰσχυρᾶς δὲ τῆς πληγῆς, ὥστε τὴν αἰχμὴν ἐπὶ θάτερα διῶσαι. τὸ μὲν οὖν πρῶτον ἐνσχεθεὶς ὥσπερ δεσμῷ παντάπασιν ἀπόρως εἶχε· τὸ γὰρ ἔναμμα τῆς ἀγκύλης χαλεπὴν ἐποίει τοῦ ἀκοντίσματος ἀνελκομένου διὰ τῶν τραυμάτων τὴν πάροδον· ὡς δὲ ὤκνουν οἱ παρόντες ἅψασθαι καὶ τῆς μάχης ἀκμὴν ὀξεῖαν ἐχούσης ἐσφάδαζεν ὑπὸ θυμοῦ καὶ φιλοτιμίας πρὸς τὸν ἀγῶνα, τῇ παραβάσει καὶ τῇ παραλλάξει τῶν σκελῶν διὰ μέσου κλάσας τὸ ἀκόντισμα χωρὶς ἐκέλευσεν ἑλκύσαι τῶν ἀγμάτων ἑκάτερον. οὕτω δὲ ἀπαλλαγεὶς καὶ σπασάμενος τὸ ξίφος ἐχώρει διὰ τῶν προμάχων ἐπὶ τοὺς πολεμίους, ὥστε πολλὴν προθυμίαν καὶ ζῆλον ἀρετῆς παρασχεῖν τοῖς ἀγωνιζομένοις. νικήσας οὖν ὁ Ἀντίγονος ἀπεπειρᾶτο τῶν Μακεδόνων, ἐρωτῶν διὰ τί, μὴ κελεύσαντος αὐτοῦ, τὸ ἱππικὸν ἐκίνησαν. τῶν δὲ ἀπολογουμένων ὡς παρὰ γνώμην βιασθεῖεν εἰς χεῖρας ἐλθεῖν τοῖς πολεμίοις μειρακίου Μεγαλοπολιτικοῦ προεμβαλόντος, γελάσας ὁ Ἀντίγονος ἐκεῖνο τοίνυν τὸ μειράκιον, εἶπεν, ἔργον ἡγεμόνος μεγάλου πεποίηκεν.", "st": "Phil. 6.3"}, {"sp": "N", "t": "ἐκ τούτου δόξαν ἔσχεν, ὥσπερ εἰκὸς, ὁ Φιλοποίμην, καὶ τοῦ μὲν Ἀντιγόνου σπουδάσαντος ὅπως στρατεύοιτο μετ’ αὐτοῦ, καὶ διδόντος ἡγεμονίαν καὶ χρήματα, παρῃτήσατο, μάλιστα τὴν ἑαυτοῦ φύσιν καταμαθὼν πρὸς τὸ ἄρχεσθαι δυσκόλως καὶ χαλεπῶς ἔχουσαν, ἀργεῖν δὲ καὶ σχολάζειν οὐ βουλόμενος ἀσκήσεως ἕνεκα καὶ μελέτης τῶν πολεμικῶν εἰς Κρήτην ἔπλευσεν ἐπὶ στρατείαν. κἀκεῖ συχνὸν χρόνον ἐγγυμνασάμενος ἀνδράσι μαχίμοις καὶ ποικίλοις μεταχειρίσασθαι πόλεμον, ἔτι δὲ σώφροσι καὶ κεκολασμένοις περὶ δίαιταν, ἐπανῆλθεν οὕτω λαμπρὸς εἰς τοὺς Ἀχαιούς ὥστε εὐθὺς ἵππαρχος ἀποδειχθῆναι. παραλαβὼν δὲ τοὺς ἱππεῖς φαύλοις μὲν ἱππαρίοις ἐκ τοῦ προστυχόντος, ὅτε συμβαίνοι στρατεία, προσχρωμένους, αὐτοὺς δὲ τὰς πολλὰς τῶν στρατειῶν ἀποδιδράσκοντας, ἑτέρους δὲ πέμποντας ἀνθ’ ἑαυτῶν, δεινὴν δὲ ἀπειρίαν μετὰ ἀτολμίας πάντων οὖσαν, περιορῶντας δὲ ταῦτα τοὺς ἄρχοντας ἀεὶ διά τε τὸ πλεῖστον ἐν τοῖς Ἀχαιοῖς τοὺς ἱππεῖς δύνασθαι καὶ μάλιστα κυρίους εἶναι τιμῆς καὶ κολάσεως, οὐχ ὑπεῖξεν οὐδὲ ἀνῆκεν, ἀλλὰ καὶ τὰς πόλεις ἐπιών καὶ κατ’ ἄνδρα τῶν νέων ἕκαστον ἐπὶ τὴν φιλοτιμίαν συνεξορμῶν, καὶ κολάζων τοὺς ἀνάγκης δεομένους, μελέταις τε καὶ πομπαῖς καὶ πρὸς ἀλλήλους ἁμίλλαις χρώμενος, ὅπου πλεῖστοι θεᾶσθαι μέλλοιεν, ἐν ὀλίγῳ χρόνῳ πᾶσι ῥώμην τε θαυμαστὴν καὶ προθυμίαν παρέστησε καὶ, ὃ μέγιστον ἦν ἐν τοῖς τακτικοῖς, ἐλαφροὺς καὶ ὀξεῖς πρός τε τὰς κατ’ οὐλαμὸν ἐπιστροφὰς καὶ περισπασμοὺς καὶ τὰς καθ’ ἵππον ἐπιστροφὰς καὶ κλίσεις ἀπειργάσατο, καὶ συνείθισεν ὡς ἑνὶ σώματι κινουμένῳ καθ’ ὁρμὴν ἑκούσιον ἐοικέναι τὴν ὅλου τοῦ συστήματος ἐν ταῖς μεταβολαῖς εὐχέρειαν.", "st": "Phil. 7.1"}, {"sp": "N", "t": "συστάσης δὲ τῆς περὶ τὸν Λάρισσον αὐτοῖς ποταμὸν ἰσχυρᾶς μάχης πρός Αἰτωλοὺς καὶ Ἠλείους, ὁ τῶν Ἠλείων ἵππαρχος Δαμόφαντος ὥρμησεν ἐπὶ τὸν Φιλοποίμενα προεξελάσας. δεξάμενος δὲ τὴν ὁρμὴν ἐκεῖνος αὐτοῦ καὶ φθάσας τῷ δόρατι παίει καὶ καταβάλλει τὸν Δαμόφαντον. εὐθὺς δὲ τούτου πεσόντος ἔφυγον οἱ πολέμιοι, καὶ λαμπρὸς ἦν ὁ Φιλοποίμην, ὡς οὔτε κατὰ χεῖρα τῶν νέων τινὸς οὔτε συνέσει τῶν πρεσβυτέρων ἀπολειπόμενος, ἀλλὰ καὶ μάχεσθαι καὶ στρατηγεῖν ἱκανώτατος.", "st": "Phil. 7.6"}, {"sp": "N", "t": "τὸ δὲ κοινὸν τῶν Ἀχαιῶν πρῶτος μὲν Ἄρατος εἰς ἀξίωμα καὶ δύναμιν ἦρεν, ἐκ ταπεινοῦ καὶ διερριμμένου κατὰ πόλεις συναγαγὼν καὶ πολιτευσάμενος Ἑλληνικὴν καὶ φιλάνθρωπον πολιτείαν· ἔπεια, ὥσπερ ἐν τοῖς ὕδασιν, ἀρξαμένων ὀλίγων ὑφίστασθαι καὶ μικρῶν σωμάτων, ἤδη τὰ ἐπιρρέοντα τοῖς πρώτοις ἐνισχόμενα καὶ περιπίπτοντα πῆξιν ἰσχυρὰν καὶ στερεότητα ποιεῖ δι’ ἀλλήλων, οὕτω τῆς Ἑλλάδος ἀσθενοῦς καὶ εὐδιαλύτου φερομένης κατὰ πόλεις ἐν τῷ τότε χρόνῳ πρῶτον συστάντες οἱ Ἀχαιοί, καὶ τῶν κύκλῳ πόλεων τὰς μὲν ἐκ τοῦ βοηθεῖν καὶ συνελευθεροῦν ἀπὸ τῶν τυράννων ὑπολαμβάνοντες, τὰς δὲ ὁμονοίᾳ καὶ πολιτείᾳ καταμιγνύντες εἰς ἑαυτούς, ἓν σῶμα καὶ μίαν δύναμιν κατασκευάσαι διενοοῦντο τὴν Πελοπόννησον. ἀλλ’ Ἀράτου μὲν ζῶντος ἔτι τοῖς Μακεδόνων ὅπλοις ὑπεδύοντο τὰ πολλά, θεραπεύοντες Πτολεμαῖον, εἶτ’ αὖθις Ἀντίγονον καὶ Φίλιππον ἐν μέσαις ἀναστρεφομένους ταῖς Ἑλληνικαῖς πράξεσιν ἐπεὶ δὲ Φιλοποίμην εἰς τὸ πρωτεύειν προῆλθεν, ἤδη καθ’ ἑαυτοὺς ἀξιόμαχοι τοῖς ἰσχύουσι πλεῖστον ὄντες ἐπαύσαντο χρώμενοι προστάταις ἐπεισάκτοις. Ἄρατος μὲν γὰρ, ἀργότερος εἶναι δοκῶν πρὸς τοὺς πολεμικοὺς ἀγῶνας, ὁμιλίᾳ καὶ πρᾳότητι καὶ φιλίαις βασιλικαῖς τὰ πλεῖστα κατειργάσατο τῶν πραγμάτων, ὡς ἐν τοῖς περὶ ἐκείνου γέγραπται, Φιλοποίμην δὲ ἀγαθὸς πολεμιστὴς ὢν καὶ διὰ τῶν ὅπλων ἐνεργός, ἔτι δ’ εὐτυχὴς καὶ κατορθωτικὸς εὐθὺς ἐν ταῖς πρώταις γενόμενος μάχαις, ἅμα τῇ δυνάμει τὸ φρόνημα τῶν Ἀχαιῶν ηὔξησε νικᾶν ἐθισθέντων μετ’ αὐτοῦ καὶ κατευτυχεῖν ἐν τοῖς πλείστοις ἀγῶσι.", "st": "Phil. 8.1"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τὰ περὶ τὰς τάξεις καὶ τοὺς ὁπλισμοὺς φαύλως ἔχοντα τοῖς Ἀχαιοῖς ἐκίνησεν. ἐχρῶντο μὲν γὰρ θυρεοῖς μὲν εὐπετέσι διὰ λεπτότητα καὶ στενωτέροις τοῦ περιστέλλειν τὰ σώματα, δόρασι δὲ μικροτέροις πολὺ τῶν σαρισῶν καὶ διὰ τοῦτο πλῆκται καὶ μάχιμοι πόρρωθεν ἦσαν ὑπὸ κουφότητος, προσμίξαντες δὲ τοῖς πολεμίοις ἔλαττον εἶχον· εἶδος δὲ τάξεως καὶ σχήματος εἰς σπεῖραν οὐκ ἦν σύνηθες, φάλαγγι δὲ χρώμενοι μήτε προβολὴν ἐχούσῃ μήτε συνασπισμὸν ὡς ἡ Μακεδόνων, ῥᾳδίως ἐξεθλίβοντο καὶ διεσπῶντο. ταῦτα ὁ Φιλοποίμην διδάξας ἔπεισεν αὐτοὺς ἀντὶ μὲν θυρεοῦ καὶ δόρατος ἀσπίδα λαβεῖν καὶ σάρισαν, κράνεσι δὲ καὶ θώραξι καὶ περικνημῖσι πεφραγμένους μόνιμον καὶ βεβηκυῖαν ἀντὶ δρομικῆς καὶ πελταστικῆς μάχην ἀσκεῖν. πείσας δὲ καθοπλίσασθαι τοὺς ἐν ἡλικίᾳ πρῶτον μὲν ἐπῆρε θαρρεῖν ὡς ἀμάχους γεγονότας, ἔπειτα τὰς τρυφὰς αὐτῶν καὶ τὰς πολυτελείας ἄριστα μετεκόσμησεν. ἀφελεῖν γὰρ οὐκ ἦν παντάπασιν ἐκ πολλοῦ νοσούντων τὸν κενὸν καὶ μάταιον ζῆλον, ἐσθῆτας ἀγαπώντων περιττάς στρωμνάς τε βαπτομένων ἁλουργεῖς καὶ περὶ δεῖπνα φιλοτιμουμένων καὶ τραπέζας. ὁ δὲ ἀρξάμενος ἐκτρέπειν ἀπὸ τῶν οὐκ ἀναγκαίων ἐπὶ τὰ χρήσιμα καὶ καλὰ τὴν φιλοκοσμίαν, ταχὺ πάντας ἔπεισε καὶ παρώρμησε τὰς καθ’ ἡμέραν περὶ σῶμα δαπάνας κολούσαντας ἐν ταῖς στρατιωτικαῖς καὶ πολεμικαῖς παρασκευαῖς διαπρεπεῖς ὁρᾶσθαι κεκοσμημένους. ἦν οὖν ἰδεῖν τὰ μὲν ἐργαστήρια μεστὰ κατακοπτομένων κυλίκων καὶ Θηρικλείων, χρυσουμένων δὲ θωράκων καὶ καταργυρουμένων θυρεῶν καὶ χαλινῶν, τὰ δὲ στάδια πώλων δαμαζομένων καὶ νεανίσκων ὁπλομαχούντων, ἐν δὲ ταῖς χερσὶ τῶν γυναικῶν κράνη καὶ πτερὰ βαφαῖς κοσμούμενα καὶ χιτώνων ἱππικῶν καὶ στρατιωτικῶν χλαμύδων διηνθισμένων· ἡ δ’ ὄψις αὕτη τὸ θάρσος αὔξουσα καὶ παρακαλοῦσα τὴν ὁρμὴν ἐποίει φιλοπαράβολον καὶ πρόθυμον ἐπὶ τοὺς κινδύνους. ἡ μὲν γὰρ ἐν τοῖς ἄλλοις θεάμασι πολυτέλεια τρυφὴν ἐπάγεται καὶ μαλακίαν ἐνδίδωσι τοῖς χρωμένοις, ὥσπερ ὑπὸ νυγμῶν καὶ γαργαλισμῶν τῆς αἰσθήσεως συνεπικλώσης τὴν διάνοιαν, ἡ δ’ εἰς τὰ τοιαῦτα ῥώννυσι καὶ μεγαλύνει τὸν θυμόν, ὥσπερ Ὅμηρος ἐποίησε τὸν Ἀχιλλέα τῶν καινῶν ὅπλων παρατεθέντων ἐγγὺς ὑπὸ τῆς ὄψεως οἷον ὀργῶντα καὶ φλεγόμενον πρὸς τὴν δι’ αὐτῶν ἐνέργειαν.", "st": "Phil. 9.1"}, {"sp": "N", "t": "οὕτω δὲ κοσμήσας τοὺς νέους ἐγύμναζε καὶ διεπόνει, ταῖς κινήσεσι προθύμως ὑπακούοντας καὶ φιλοτίμως. καὶ γὰρ ἡ τάξις θαυμαστῶς ἠγαπᾶτο ἄθραυστόν τι λαμβάνειν πύκνωμα δοκοῦσα, καὶ τὰ ὅπλα τοῖς σώμασιν ἐγίνετο χειροήθη καὶ κοῦφα, μεθ’ ἡδονῆς διὰ λαμπρότητα καὶ κάλλος ἁπτομένων καὶ φορούντων, ἐναγωνίσασθαί τε βουλομένων καὶ διακριθῆναι τάχιστα πρὸς τοὺς πολεμίους.", "st": "Phil. 9.8"}, {"sp": "N", "t": "ἦν δὲ τότε τοῖς Ἀχαιοῖς ὁ πρὸς Μαχανίδαν πόλεμος τὸν Λακεδαιμονίων τύραννον, ἀπὸ πολλῆς καὶ μεγάλης δυνάμεως ἐπιβουλεύοντα πᾶσι Πελοποννησίοις. ὡς οὖν εἰς τὴν Μαντίνειαν ἐμβεβληκὼς ἀπηγγέλθη, κατὰ τάχος ὁ Φιλοποίμην ἐξήγαγε τὴν στρατιὰν ἐπ’ αὐτόν, ἐγγὺς δὲ τῆς πόλεως παρετάξαντο πολλοῖς μὲν ξένοις ἑκάτεροι, πάσαις δὲ ὁμοῦ τι ταῖς πολιτικαῖς δυνάμεσι. γενομένου δὲ τοῦ ἀγῶνος ἐν χερσίν, ὁ Μαχανίδας τοῖς ξένοις τοὺς τῶν Ἀχαιῶν προτεταγμένους ἀκοντιστὰς καὶ Ταραντίνους τρεψάμενος ἀντὶ τοῦ χωρεῖν εὐθὺς ἐπὶ τοὺς μαχομένους καὶ παραρρηγνύναι τὸ συνεστηκός ἐξέπεσε διώκων καὶ παρήλλαξε τὴν φάλαγγα τῶν Ἀχαιῶν ἐν τάξει μενόντων. ὁ δὲ Φιλοποίμην τηλικούτου πταίσματος ἐν ἀρχῇ γενομένου καὶ τῶν πραγμάτων ἀπολωλέναι κομιδῇ καὶ διεφθάρθαι δοκούντων, τοῦτο μὲν ὅμως προσεποιεῖτο παρορᾶν καὶ μηδὲν ἡγεῖσθαι δεινόν, κατιδὼν δὲ τοὺς πολεμίους, ὅσον ἡμάρτανον ἐν τῇ διώξει, τῆς φάλαγγος ἀπορρηγνυμένους καὶ κενὴν χώραν διδόντας, οὐκ ἀπήντησεν οὐδ’ ἐνέστη φερομένοις αὐτοῖς ἐπὶ τοὺς φεύγοντας,", "st": "Phil. 10.1"}, {"sp": "N", "t": "ἀλλ’ ἐάσας παρελθεῖν καὶ διάσπασμα ποιῆσαι μέγα πρὸς τοὺς ὁπλίτας εὐθὺς ἦγε τῶν Λακεδαιμονίων, ὁρῶν τὴν φάλαγγα γυμνὴν ἀπολελειμμένην, καὶ κατὰ κέρας παραδραμὼν ἐνέβαλε, μήτε ἄρχοντος αὐτοῖς παρόντος μήτε μάχεσθαι προσδεχομένοις· νικᾶν γὰρ ἡγοῦντο καὶ κρατεῖν παντάπασι, διώκοντα τὸν Μαχανίδαν ὁρῶντες. ὠσάμενος δὲ τούτους φόνῳ πολλῷ λέγονται γὰρ ὑπὲρ τοὺς τετρακισχιλίους ἀποθανεῖν ὥρμησεν ἐπὶ τὸν Μαχανίδαν ἐκ τῆς διώξεως ἀναστρέφοντα μετὰ τῶν ξένων, τάφρου δὲ μεγάλης καὶ βαθείας ἐν μέσῳ διειργούσης, παρεξήλαυνον ἀλλήλοις ἑκατέρωθεν, ὁ μὲν διαβῆναι καὶ φυγεῖν, ὁ δὲ τοῦτο κωλῦσαι βουλόμενος.", "st": "Phil. 10.4"}, {"sp": "N", "t": "ἦν δὲ ὄψις οὐχ ὡς στρατηγῶν μαχομένων, ἀλλ’ ὥσπερ θηρίῳ πρὸς ἀλκὴν ὑπ’ ἀνάγκης τρεπομένῳ δεινοῦ κυνηγέτου τοῦ Φιλοποίμενος συνεστῶτος, ἔνθα ὁ μὲν ἵππος τοῦ τυράννου ῥωμαλέος ὢν καὶ θυμοειδὴς καὶ τοῖς μύωψιν αἱμαχθεὶς ἑκατέρωθεν ἐπετόλμησε τῇ διαβάσει, καὶ προσβαλὼν τῇ τάφρῳ τὸ στῆθος ἐβιάζετο τοῖς προσθίοις πέραν ἐρείσασθαι σκέλεσιν. ἐν δὲ τούτῳ Σιμίας καὶ Πολύαινος, οἵπερ ἀεὶ τῷ Φιλοποίμενι παρῆσαν μαχομένῳ καὶ συνήσπιζον, ὁμοῦ προσήλαυνον ἀμφότεροι τὰς αἰχμὰς κλίναντες ἐναντίας, φθάνει δὲ αὐτοὺς ὁ Φιλοποίμην ἀπαντήσας τῷ Μαχανίδᾳ, καὶ τὸν ἵππον αὐτοῦ μετεωρίζοντα τὴν κεφαλὴν πρὸ τοῦ σώματος ὁρῶν μικρὸν ἐνέκλινε τὸν ἴδιον, καὶ διαλαβὼν τὸ ξυστὸν ἐκ χειρὸς ὠθεῖ καὶ περιτρέπει τὸν ἄνδρα συνεπερείσας. τοῦτο ἔχων τὸ σχῆμα χαλκοῦς ἐν Δελφοῖς ἕστηκεν ὑπὸ τῶν Ἀχαιῶν θαυμασάντων μάλιστα καὶ τὴν πρᾶξιν αὐτοῦ καὶ τὴν στρατηγίαν ἐκείνην.", "st": "Phil. 10.6"}, {"sp": "N", "t": "λέγεται δὲ τῆς τῶν Νεμείων πανηγύρεως συνεστώσης στρατηγοῦντα τὸν Φιλοποίμενα τὸ δεύτερον καὶ νενικηκότα μὲν οὐ πάλαι τὴν ἐν Μαντινείᾳ μάχην, τότε δὲ σχολὴν ἄγοντα διὰ τὴν ἑορτήν, πρῶτον μὲν ἐπιδεῖξαι τοῖς Ἕλλησι κεκοσμημένην τὴν φάλαγγα καὶ κινουμένην, ὥσπερ εἴθιστο, τοὺς τακτικοὺς ῥυθμοὺς μετὰ τάχους καὶ ῥώμης· ἔπειτα κιθαρῳδῶν ἀγωνιζομένων εἰς τὸ θέατρον παρελθεῖν ἔχοντα τοὺς νεανίσκους ἐν ταῖς στρατιωτικαῖς χλαμύσι καὶ τοῖς φοινικοῖς ὑποδύταις, ἀκμάζοντάς τε τοῖς σώμασιν ἅπαντας καὶ ταῖς ἡλικίαις παραλλήλους, αἰδῶ δὲ πολλὴν πρὸς τὸν ἄρχοντα καὶ φρόνημα νεανικὸν ὑποφαίνοντας ἐκ πολλῶν καὶ καλῶν ἀγώνων ἄρτι δ’ αὐτῶν εἰσεληλυθότων κατὰ τύχην Πυλάδην τὸν κιθαρῳδὸν ᾄδοντα τοὺς Τιμοθέου Πέρσας ἐνάρξασθαι", "st": "Phil. 11.1"}, {"sp": "N", "t": "κλεινὸν ἐλευθερίας τεύχων μέγαν Ἑλλάδι κόσμον·", "st": "Phil. 11.1b"}, {"sp": "N", "t": "ἅμα δὲ τῇ λαμπρότητι τῆς φωνῆς τοῦ περὶ τὴν ποίησιν ὄγκου συμπρέψαντος ἐπίβλεψιν γενέσθαι τοῦ θεάτρου πανταχόθεν εἰς τὸν Φιλοποίμενα καὶ κρότον μετὰ χαρᾶς, τῶν Ἑλλήνων τὸ παλαιὸν ἀξίωμα ταῖς ἐλπίσιν ἀναλαμβανόντων καὶ τοῦ τότε φρονήματος ἔγγιστα τῷ θαρρεῖν γινομένων.", "st": "Phil. 11.3"}, {"sp": "N", "t": "παρὰ δὲ τὰς μάχας καὶ τοὺς κινδύνους, ὥσπερ οἱ πῶλοι τοὺς συνήθεις ἐπιβάτας ποθοῦντες, ἐὰν ἄλλον φέρωσι, πτύρονται καὶ ξενοπαθοῦσιν, οὕτως ἡ δύναμις τῶν Ἀχαιῶν ἑτέρου στρατηγοῦντος ἠθύμει καὶ πρὸς ἐκεῖνον ἐπάπταινε καὶ μόνον ὀφθέντος εὐθὺς ὀρθὴ καὶ δραστήριος ἦν διὰ τὸ θαρρεῖν, ἅτε δὴ καὶ τοὺς ἐναντίους αἰσθανόμενοι πρὸς ἕνα τοῦτον τῶν στρατηγῶν ἀντιβλέπειν οὐ δυναμένους, ἀλλὰ καὶ τὴν δόξαν αὐτοῦ καὶ τοὔνομα δεδοικότας, ὡς ἦν φανερὸν ἐξ ὧν ἔπρασσον. Φίλιππος μὲν γὰρ ὁ τῶν Μακεδόνων βασιλεύς οἰόμενος, ἂν ἐκποδὼν ὁ Φιλοποίμην γένηται, πάλιν ὑποπτήξειν αὐτῷ τοὺς Ἀχαιούς, ἔπεμψεν εἰς Ἄργος κρύφα τοὺς ἀναιρήσοντας αὐτόν ἐπιγνωσθείσης δὲ τῆς ἐπιβουλῆς παντάπασιν ἐξεμισήθη καὶ διεβλήθη πρὸς τοὺς Ἕλληνας. Βοιωτοὶ δὲ πολιορκοῦντες Μέγαρα καὶ λήψεσθαι ταχέως ἐλπίζοντες, ἐξαίφνης λόγου προσπεσόντος αὐτοῖς, ὃς οὐκ ἦν ἀληθής, Φιλοποίμενα βοηθοῦντα τοῖς πολιορκουμένοις ἐγγὺς εἶναι, τὰς κλίμακας ἀφέντες ἤδη προσερηρεισμένας τοῖς τείχεσιν ᾤχοντο φεύγοντες. Νάβιδος δὲ τοῦ μετὰ Μαχανίδαν τυραννοῦντος Λακεδαιμονίων Μεσσήνην ἄφνω καταλαβόντος, ἐτύγχανε μὲν ἰδιώτης ὢν τότε ὁ Φιλοποίμην καὶ δυνάμεως οὐδεμιᾶς κύριος, ἐπεὶ δὲ τὸν στρατηγοῦντα τῶν Ἀχαιῶν Λύσιππον οὐκ ἔπειθε βοηθεῖν τοῖς Μεσσηνίοις, ἀπολωλέναι κομιδῇ φάσκοντα τὴν πόλιν ἔνδον γεγονότων τῶν πολεμίων, αὐτὸς ἐβοήθει τοὺς ἑαυτοῦ πολίτας ἀναλαβών οὔτε νόμον οὔτε χειροτονίαν περιμείναντας, ἀλλ’ ὡς διὰ παντὸς ἄρχοντι τῷ κρείττονι κατὰ φύσιν ἑπομένους. ἤδη δ’ αὐτοῦ πλησίον ὄντος ἀκούσας ὁ Νάβις οὐχ ὑπέστη, καίπερ ἐν τῇ πόλει στρατοπεδεύων, ἀλλ’ ὑπεκδὺς διὰ πυλῶν ἑτέρων κατὰ τάχος ἀπήγαγε τὴν δύναμιν, εὐτυχίᾳ χρήσεσθαι δοκῶν εἰ διαφύγοι· καὶ διέφυγε, Μεσσήνη δ’ ἠλευθέρωτο.", "st": "Phil. 12.1"}, {"sp": "N", "t": "ταῦτα μὲν οὖν καλὰ τοῦ Φιλοποίμενος· ἡ δ’ εἰς Κρήτην αὖθις ἀποδημία Γορτυνίων δεηθέντων, ὡς χρήσαιντο πολεμούμενοι στρατηγῷ, διαβολὴν ἔσχεν, ὅτι τῆς πατρίδος αὐτοῦ πολεμουμένης ὑπὸ Νάβιδος ἀπῆν φυγομαχῶν ἡ φιλοτιμούμενος ἀκαίρως πρὸς ἑτέρους, καίτοι συντόνως οὕτως ἐπολεμήθησαν Μεγαλοπολῖται κατὰ τὸν χρόνον ἐκεῖνον ὥστε τοῖς μὲν τείχεσιν ἐνοικεῖν, σπείρειν δέ τοὺς στενωπούς, περικεκομμένης τῆς χώρας καὶ τῶν πολεμίων σχεδὸν ἐν ταῖς πύλαις στρατοπεδευόντων. ὁ δὲ Κρησὶ πολεμῶν τηνικαῦτα καὶ στρατηγῶν διαπόντιος ἐγκλήματα παρεῖχε καθ’ ἑαυτοῦ τοῖς ἐχθροῖς ὡς ἀποδιδράσκων τὸν οἴκοι πόλεμον. ἦσαν δέ τινες οἱ λέγοντες, ἑτέρους τῶν Ἀχαιῶν ᾑρημένων ἄρχοντας, ἰδιώτην ὄντα τὸν Φιλοποίμενα χρῆσαι τὴν ἑαυτοῦ σχολὴν ἐφ’ ἡγεμονίᾳ δεηθεῖσι τοῖς Γορτυνίοις. ἦν γὰρ ἀλλότριος σχολῆς, καθάπερ ἄλλο τι κτῆμα τὴν στρατηγικὴν καὶ πολεμικὴν ἀρετὴν ἔχειν διὰ παντὸς ἐν χρήσει καὶ τριβῇ βουλόμενος, ὡς καὶ τῷ περὶ Πτολεμαίου ποτὲ ῥηθέντι τοῦ βασιλέως ἀπεδήλωσεν. ἐκεῖνον γὰρ ἐγκωμιαζόντων τινῶν ὡς ἐν μὲν ἐξασκοῦντα τὸ στράτευμα καθ’ ἡμέραν, ἐν δὲ γυμνάζοντα καὶ φιλοπόνως διὰ τῶν ὅπλων τὸ σῶμα, καὶ τίς ἂν, ἔφη, βασιλέα θαυμάσειεν ἐν τούτῳ τῆς ἡλικίας μὴ ἐπιδεικνύμενον, ἀλλὰ μελετῶντα;", "st": "Phil. 13.1"}, {"sp": "N", "t": "χαλεπῶς δ’ οὖν οἱ Μεγαλοπολῖται φέροντες ἐπὶ τούτῳ καὶ προδεδόσθαι νομίζοντες ἐπεχείρησαν ἀποξενοῦν αὐτόν· οἱ δ’ Ἀχαιοὶ διεκώλυσαν Ἀρίσταινον πέμψαντες εἰς Μεγάλην πόλιν στρατηγόν, ὃς καίπερ ὢν διάφορος τῷ Φιλοποίμενι περὶ τὴν πολιτείαν, οὐκ εἴασε τελεσθῆναι τὴν καταδίκην. ἐκ δὲ τούτου παρορώμενος ὑπὸ τῶν πολιτῶν ὁ Φιλοποίμην ἀπέστησε πολλὰς τῶν περιοικίδων κωμῶν, λέγειν διδάξας ὡς οὐ συνετέλουν οὐδὲ ἦσαν ἐξ ἀρχῆς ἐκείνων, καὶ λεγούσαις ταῦτα φανερῶς συνηγωνίσατο καὶ συγκατεστασίασε τὴν πόλιν ἐπὶ τῶν Ἀχαιῶν, ταῦτα μὲν οὖν ὕστερον.", "st": "Phil. 13.4"}, {"sp": "N", "t": "ἐν δὲ τῇ Κρήτῃ συνεπολέμει τοῖς Γορτυνίοις, οὐχ ὡς Πελοποννήσιος ἀνὴρ καὶ Ἀρκὰς ἁπλοῦν τινα καὶ γενναῖον πόλεμον, ἀλλὰ τὸ Κρητικὸν ἦθος ἐνδὺς καὶ τοῖς ἐκείνων σοφίσμασι καὶ δόλοις κλωπείαις τε καὶ λοχισμοῖς χρώμενος ἐπ’ αὐτούς ταχὺ παῖδας ἀπέδειξεν ἀνόητα καὶ κενὰ πρὸς ἐμπειρίαν ἀληθινὴν πανουργοῦντας.", "st": "Phil. 13.6"}, {"sp": "N", "t": "ἐπὶ τούτοις δὲ θαυμασθείς καὶ λαμπρὸς παρὰ τῶν ἐκεῖ πράξεων ἀνακομισθεὶς εἰς Πελοπόννησον εὗρε τὸν μὲν Φίλιππον ὑπὸ τοῦ Τίτου καταπεπολεμημένον, τὸν δὲ Νάβιν ὑπὸ τῶν Ἀχαιῶν καὶ τῶν Ῥωμαίων πολεμούμενον. ἐφ’ ὃν εὐθὺς αἱρεθεὶς ἄρχων καὶ ναυμαχίᾳ παραβαλόμενος τὸ τοῦ Ἐπαμεινώνδου παθεῖν ἔδοξε, ποχὺ τῆς περὶ αὐτὸν ἀρετῆς καὶ δόξης ἐν τῇ θαλάσσῃ κάκιον ἀγωνισάμενος. πλὴν Ἐπαμεινώνδαν μὲν ἔνιοι λέγουσιν ὀκνοῦντα γεῦσαι τῶν κατὰ θάλασσαν ὠφελειῶν τοὺς πολίτας, ὅπως αὐτῷ μὴ λάθωσιν ἀντὶ μονίμων ὁπλιτῶν, κατὰ Πλάτωνα, ναῦται γενόμενοι καὶ διαφθαρέντες, ἄπρακτον ἐκ τῆς Ἀσίας καὶ τῶν νήσων ἀπελθεῖν ἑκουσίως· Φιλοποίμην δὲ τὴν ἐν τοῖς πεζοῖς ἐπιστήμην καὶ διὰ θαλάττης ἀρκέσειν αὐτῷ πρὸς τὸ καλῶς ἀγωνίσασθαι πεπεισμένος, ἔγνω τὴν ἄσκησιν ἡλίκον μέρος ἐστὶ τῆς ἀρετῆς καὶ πόσην ἐπὶ πάντα τοῖς ἐθισθεῖσι δύναμιν προστίθησιν. οὐ γὰρ μόνον ἐν τῇ ναυμαχίᾳ διὰ τὴν ἀπειρίαν ἔλαττον ἔσχεν, ἀλλὰ καὶ ναῦν τινα, παλαιὰν μέν, ἔνδοξον δέ, δι’ ἐτῶν τεσσαράκοντα κατασπάσας ἐπλήρωσεν, ὥστε μὴ στεγούσης κινδυνεῦσαι τοὺς πλέοντας.", "st": "Phil. 14.1"}, {"sp": "N", "t": "πρὸς ταῦτα γινώσκων καταφρονοῦντας αὐτοῦ τοὺς πολεμίους ὡς παντάπασι πεφευγότος ἐκ τῆς θαλάττης, καὶ πολιορκοῦντας ὑπερηφάνως τὸ Γύθιον, εὐθὺς ἐπέπλευσεν αὐτοῖς οὐ προσδοκῶσιν, ἀλλ’ ἐκλελυμένοις διὰ τὴν νίκην. καὶ νυκτὸς ἐκβιβάσας τοὺς στρατιώτας καὶ προσαγαγών, πῦρ ἐνῆκε ταῖς σκηναῖς καὶ τὸ στρατόπεδον κατέκαυσε καὶ πολλοὺς διέφθειρεν. ὀλίγαις δ’ ὕστερον ἡμέραις καθ’ ὁδὸν ἐν δυσχωρίαις τισὶν ἄφνω τοῦ Νάβιδος ἐπιφανέντος αὐτῷ καὶ φοβήσαντος τοὺς Ἀχαιούς ἀνέλπιστον ἡγουμένους τὴν σωτηρίαν ἐκ τόπων χαλεπῶν καὶ γεγονότων ὑποχειρίων τοῖς πολεμίοις, ὀλίγον χρόνον ἐπιστὰς καὶ περιλαβὼν ὄψει τὴν τοῦ χωρίου φύσιν ἐπέδειξε τὴν τακτικὴν τῶν ἄκρων τῆς πολεμικῆς τέχνην οὖσαν οὕτω μικρὰ κινήσας τὴν ἑαυτοῦ φάλαγγα καὶ πρὸς τὰ παρόντα μεθαρμόσας ἀθορύβως καὶ ῥᾳδίως διεκρούσατο τὴν ἀπορίαν, καὶ προσβαλὼν τοῖς πολεμίοις τροπὴν ἰσχυρὰν ἐποίησεν. ἐπεὶ δὲ οὐ πρὸς τὴν πόλιν ἑώρα φεύγοντας, ἀλλὰ τῆς χώρας ἄλλον ἄλλῃ διασπειρόμενον ὑλώδης δὲ καὶ περίβουνος ἦν πᾶσα καὶ δύσιππος ὑπὸ ῥείθρων καὶ φαράγγων, τὴν μὲν δίωξιν ἐπέσχε καὶ κατεστρατοπέδευσεν ἔτι φωτὸς ὄντος· τεκμαιρόμενος δὲ τοὺς πολεμίους ἐκ τῆς φυγῆς καθ’ ἕνα καὶ δύο πρὸς τὴν πόλιν ὑπάξειν σκοταίους, ἐλλοχίζει τοῖς περὶ τὸ ἄστυ ῥείθροις καὶ λόφοις πολλοὺς ἔχοντας ἐγχειρίδια τῶν Ἀχαιῶν. ἐνταῦθα πλείστους ἀποθανεῖν συνέβη τῶν τοῦ Νάβιδος· ἅτε γὰρ οὐκ ἀθρόαν ποιούμενοι τὴν ἀναχώρησιν, ἀλλ’ ὡς ἑκάστοις αἱ φυγαὶ συνετύγχανον, ὥσπερ ὄρνιθες ἡλίσκοντο περὶ τὴν πόλιν εἰς τὰς τῶν πολεμίων χεῖρας καταίροντες.", "st": "Phil. 14.4"}, {"sp": "N", "t": "ἐπὶ τούτοις ἀγαπώμενος καὶ τιμώμενος ἐκπρεπῶς ὑπὸ τῶν Ἑλλήνων ἐν τοῖς θεάτροις φιλότιμον ὄντα τὸν Τίτον ἡσυχῇ παρελύπει. καὶ γὰρ ὡς Ῥωμαίων ὕπατος ἀνδρὸς Ἀρκάδος ἠξίου θαυμάζεσθαι μᾶλλον ὑπὸ τῶν Ἀχαιῶν, καὶ ταῖς εὐεργεσίαις ὑπερβάλλειν οὐ παρὰ μικρὸν ἡγεῖτο, δι’ ἑνὸς κηρύγματος ἐλευθερώσας τὴν Ἑλλάδα, ὅση Φιλίππῳ καὶ Μακεδόσιν ἐδούλευσεν.", "st": "Phil. 15.1"}, {"sp": "N", "t": "ἐκ δὲ τούτου καταλύεται μὲν ὁ Τίτος τῷ Νάβιδι τὸν πόλεμον, ἀποθνῄσκει δὲ ὁ Νάβις ὑπὸ Αἰτωλῶν δολοφονηθείς, τεταραγμένης δὲ τῆς Σπάρτης ὁ Φιλοποίμην ἁρπάσας τὸν καιρὸν ἐπιπίπτει μετὰ δυνάμεως, καὶ τῶν μὲν ἀκόντων, τοὺς δὲ συμπείσας προσηγάγετο καὶ μετεκόμισεν εἰς τοὺς Ἀχαιοὺς τὴν πόλιν. οὗ γενομένου θαυμαστῶς μὲν εὐδοκίμησε παρὰ τοῖς Ἀχαιοῖς, προσκτησάμενος αὐτοῖς ἀξίωμα πόλεως τηλικαύτης καὶ δύναμιν οὐ γὰρ ἦν μικρὸν Ἀχαΐας μέρος γενέσθαι τὴν Σπάρτην, ἀνέλαβε δὲ καὶ Λακεδαιμονίων τοὺς ἀρίστους, φύλακα τῆς ἐλευθερίας ἐκεῖνον ἐλπίσαντας ἕξειν. διὸ καὶ τὴν Νάβιδος οἰκίαν καὶ οὐσίαν ἐξαργυρισθεῖσαν καὶ γενομένην εἴκοσι καὶ ἑκατὸν ταλάντων ἐψηφίσαντο δωρεὰν αὐτῷ δοῦναι, πρεσβείαν ὑπὲρ τούτων πέμψαντες. ἔνθα δὴ καὶ διεφάνη καθαρῶς ἐκεῖνος ὁ ἀνὴρ οὐ δοκῶν μόνον, ἀλλὰ καὶ ὢν ἄριστος, πρῶτον μὲν γὰρ οὐδεὶς ἐβούλετο τῶν Σπαρτιατῶν ἀνδρὶ τοιούτῳ διαλέγεσθαι περὶ δωροδοκίας, ἀλλὰ δεδοικότες καὶ ἀναδυόμενοι προεβάλοντο τὸν ξένον αὐτοῦ Τιμόλαον. ἔπειτα δὲ αὐτὸς ὁ Τιμόλαος, ὡς ἦλθεν εἰς Μεγάλην πόλιν, ἑστιαθεὶς παρὰ τῷ Φιλοποίμενι καὶ τὴν σεμνότητα τῆς ὁμιλίας αὐτοῦ καὶ τὴν ἀφέλειαν τῆς διαίτης καὶ τὸ ἦθος ἐγγύθεν οὐδαμῇ προσιτὸν οὐδὲ εὐάλωτον ὑπὸ χρημάτων κατανοήσας, ἀπεσιώπησε περὶ τῆς δωρεᾶς, ἑτέραν δέ τινα πρόφασιν τῆς πρὸς αὐτὸν ὁδοῦ ποιησάμενος ᾤχετο ἀπιών. καὶ πάλιν ἐκ δευτέρου πεμφθείς ταὐτὸν ἔπαθε. τρίτῃ δὲ ὁδῷ μόλις ἐντυχὼν ἐδήλωσε τὴν προθυμίαν τῆς πόλεως, ὁ δὲ Φιλοποίμην ἡδέως ἀκούσας ἧκεν αὐτὸς εἰς Λακεδαίμονα, καὶ συνεβούλευσεν αὐτοῖς μὴ τοὺς φίλους καὶ ἀγαθοὺς δεκάζειν, ὧν προῖκα τῆς ἀρετῆς ἔξεστιν ἀπολαύειν, ἀλλὰ τοὺς πονηροὺς καὶ τὴν πόλιν ἐν τῷ συνεδρίῳ καταστασιάζοντας ὠνεῖσθαι καὶ διαφθείρειν, ἵνα τῷ λαβεῖν ἐπιστομισθέντες ἧττον ἐνοχλοῖεν αὐτοῖς βέλτιον γὰρ εἶναι τῶν ἐχθρῶν παραιρεῖσθαι τὴν παρρησίαν ἢ τῶν φίλων, οὕτως μὲν ἦν πρὸς χρήματα λαμπρός.", "st": "Phil. 15.2"}, {"sp": "N", "t": "ἐπεὶ δὲ πάλιν τοὺς Λακεδαιμονίους νεωτερίζειν ἀκούσας ὁ στρατηγὸς τῶν Ἀχαιῶν Διοφάνης ἐβούλετο κολάζειν, οἱ δὲ εἰς πόλεμον καθιστάμενοι διετάρασσον τὴν Πελοπόννησον, ἐπειρᾶτο πραΰνειν καὶ καταπαύειν τόν Διοφάνη τῆς ὀργῆς ὁ Φιλοποίμην, διδάσκων τόν καιρόν ὡς Ἀντιόχου τοῦ βασιλέως καὶ Ῥωμαίων ἐν τῇ Ἑλλάδι τηλικούτοις αἰωρουμένων στρατοπέδοις ἐκεῖσε χρὴ τόν ἄρχοντα τὴν γνώμην ἔχειν, τὰ δὲ οἰκεῖα μὴ κινεῖν, ἀλλὰ καὶ παριδεῖν τι καὶ παρακοῦσαι τῶν ἁμαρτανομένων. οὐ προσέχοντος δὲ τοῦ Διοφάνους, ἀλλ’ εἰς τὴν Λακωνικὴν ἐμβαλόντος ἅμα τῷ Τίτῳ καὶ βαδιζόντων εὐθὺς ἐπὶ τὴν πόλιν, ἀγανακτήσας ὁ Φιλοποίμην, ἔργον οὐ νόμιμον οὐδ’ ἀπηκριβωμένον ἐκ τῶν δικαίων, ἀλλὰ μέγα καὶ μεγάλῳ φρονήματι τολμήσας, εἰς τὴν Λακεδαίμονα παρῆλθε καὶ τόν τε στρατηγὸν τῶν Ἀχαιῶν καὶ τόν ὕπατον τῶν Ῥωμαίων ἰδιώτης ὢν ἀπέκλεισε, τὰς δ’ ἐν τῇ πόλει ταραχὰς ἔπαυσε καὶ κατέστησε τοὺς Λακεδαιμονίους πάλιν εἰς τὸ κοινόν, ὥσπερ ἐξ ἀρχῆς ἦσαν.", "st": "Phil. 16.1"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον ἐγκαλέσας τι τοῖς Λακεδαιμονίοις στρατηγῶν ὁ Φιλοποίμην τὰς μὲν φυγὰς κατήγαγεν εἰς τὴν πόλιν, ὀγδοήκοντα δὲ Σπαρτιάτας ἀπέκτεινεν, ὡς Πολύβιός φησιν, ὡς δὲ Ἀριστοκράτης, πεντήκοντα καὶ τριακοσίους. τὰ δὲ τείχη καθεῖλε, χώραν δὲ πολλὴν ἀποτεμόμενος προσένειμε τοῖς Μεγαλοπολίταις, ὅσοι δὲ ἦσαν ὑπὸ τῶν τυράννων ἀποδεδειγμένοι πολῖται τῆς Σπάρτης, μετῴκιζεν ἅπαντας ἀπάγων εἰς Ἀχαΐαν πλὴν τρισχιλίων τούτους δὲ ἀπειθοῦντας καὶ μὴ βουλομένους ἀπελθεῖν ἐκ τῆς Λακεδαίμονος ἐπώλησεν, εἶθ’ οἷον ἐφυβρίζων ἀπὸ τῶν χρημάτων τούτων ἐν Μεγάλῃ πόλει στοὰν ᾠκοδόμησεν. ἐμπιπλάμενος δὲ τῶν Λακεδαιμονίων καὶ παρ’ ἀξίαν πεπραχόσιν ἐπεμβαίνων, τὸ περὶ τὴν πολιτείαν ἔργον ὠμότατον ἐξειργάσατο καὶ παρανομώτατον. ἀνεῖλε γὰρ καὶ διέφθειρε τὴν Λυκούργειον ἀγωγήν, ἀναγκάσας τοὺς παῖδας αὐτῶν καὶ τοὺς ἐφήβους τὴν Ἀχαϊκὴν ἀντὶ τῆς πατρίου παιδείαν μεταβαλεῖν, ὡς οὐδέποτε μικρὸν ἐν τοῖς Λυκούργου νόμοις φρονήσοντας.", "st": "Phil. 16.3"}, {"sp": "N", "t": "τότε μὲν οὖν ὑπὸ συμφορῶν μεγάλων ὥσπερ νεῦρα τῆς πόλεως ἐκτεμεῖν τῷ Φιλοποίμενι παρασχόντες, ἐγένοντο χειροήθεις καὶ ταπεινοί, χρόνῳ δ’ ὕστερον αἰτησάμενοι παρὰ Ῥωμαίων τὴν μὲν Ἀχαϊκὴν ἔφυγον πολιτείαν, ἀνέλαβον δὲ καὶ κατεστήσαντο τὴν πάτριον, ὡς ἦν ἀνυστὸν ἐκ κακῶν καὶ φθορᾶς τηλικαύτης.", "st": "Phil. 16.6"}, {"sp": "N", "t": "ἐπεὶ δὲ Ῥωμαίοις ὁ πρὸς Ἀντίοχον ἐν τῇ Ἑλλάδι συνέστη πόλεμος, ἦν μὲν ἰδιώτης ὁ Φιλοποίμην, ὁρῶν δὲ τὸν Ἀντίοχον αὐτὸν ἐν Χαλκίδι καθήμενον περὶ γάμους καὶ παρθένων ἔρωτας οὐ καθ’ ὥραν σχολάζοντα, τοὺς δὲ Σύρους ἐν ἀταξίᾳ πολλῇ καὶ χωρὶς ἡγεμόνων ἐν ταῖς πόλεσι πλαζομένους καὶ τρυφῶντας, ἤχθετο μὴ στρατηγῶν τότε τῶν Ἀχαιῶν, καὶ Ῥωμαίοις ἔλεγε φθονεῖν τῆς νίκης. ἐγὼ γὰρ ἂν, ἔφη, στρατηγῶν ἐν τοῖς καπηλείοις κατέκοψα τούτους πάντας. ἐπεὶ δὲ νικήσαντες οἱ Ῥωμαῖοι τὸν Ἀντίοχον ἐνεφύοντο τοῖς Ἑλληνικοῖς μᾶλλον ἤδη, καὶ περιεβάλλοντο τῇ δυνάμει τοὺς Ἀχαιοὺς ὑποκατακλινομένων αὐτοῖς τῶν δημαγωγῶν, ἡ δ’ ἰσχὺς ἐπὶ πάντα πολλὴ μετὰ τοῦ δαίμονος ἐχώρει, καὶ τὸ τέλος ἐγγὺς ἦν εἰς ὃ τὴν τύχην ἔδει περιφερομένην ἐξικέσθαι, καθάπερ ἀγαθὸς κυβερνήτης πρὸς κῦμα διερειδόμενος ὁ Φιλοποίμην τὰ μὲν ἐνδιδόναι καὶ παρείκειν ἠναγκάζετο τοῖς καιροῖς, περὶ δὲ τῶν πλείστων διαφερόμενος τοὺς τῷ λέγειν καὶ πράττειν ἰσχύοντας ἀντισπᾶν ἐπειρᾶτο πρὸς τὴν ἐλευθερίαν.", "st": "Phil. 17.1"}, {"sp": "N", "t": "Ἀρισταίνου δὲ τοῦ Μεγαλοπολίτου δυναμένου μὲν ἐν τοῖς Ἀχαιοῖς μέγιστον, τοὺς δὲ Ῥωμαίους ἀεὶ θεραπεύοντος καὶ τοὺς Ἀχαιοὺς μὴ οἰομένου δεῖν ἐναντιοῦσθαι μηδὲ ἀχαριστεῖν ἐκείνοις, ἐν τῷ συνεδρίῳ λέγεται τὸν Φιλοποίμενα σιωπᾶν ἀκούοντα καὶ βαρέως φέρειν, τέλος δὲ ὑπ’ ὀργῆς δυσανασχετοῦντα πρὸς τὸν Ἀρίσταινον εἰπεῖν ὦ ἄνθρωπε, τί σπεύδεις τὴν πεπρωμένην τῆς Ἑλλάδος ἐπιδεῖν; Μανίου δὲ τοῦ Ῥωμαίων ὑπάτου νενικηκότος μὲν Ἀντίοχον, αἰτουμένου δὲ παρὰ τῶν Ἀχαιῶν ὅπως ἐάσωσι τοὺς Λακεδαιμονίων φυγάδας κατελθεῖν, καὶ Τίτου ταὐτὸ τῷ Μανίῳ περὶ τῶν φυγάδων ἀξιοῦντος, διεκώλυσεν ὁ Φιλοποίμην οὐ τοῖς φυγάσι πολεμῶν, ἀλλὰ βουλόμενος δι’ αὑτοῦ καὶ τῶν Ἀχαιῶν, ἀλλὰ μὴ Τίτου μηδὲ Ῥωμαίων χάριτι τοῦτο πραχθῆναι· καὶ στρατηγῶν εἰς τοὐπιὸν αὐτὸς κατήγαγε τοὺς φυγάδας, οὕτως εἶχέ τι πρὸς τὰς ἐξουσίας ὑπὸ φρονήματος δύσερι καὶ φιλόνεικον.", "st": "Phil. 17.3"}, {"sp": "N", "t": "ἤδη δὲ γεγονὼς ἔτος ἑβδομηκοστόν, ὄγδοον δὲ τῶν Ἀχαιῶν στρατηγῶν, ἤλπιζεν οὐ μόνον ἐκείνην τήν ἀρχὴν ἀπολέμως διάξειν, ἀλλὰ καὶ τοῦ βίου τὸ λοιπὸν αὐτῷ μεθ’ ἡσυχίας καταβιῶναι τὰ πράγματα παρέξειν. ὡς γὰρ αἱ νόσοι ταῖς τῶν σωμάτων ῥώμαις συναπομαραίνεσθαι δοκοῦσιν, οὕτως ἐν ταῖς Ἑλληνικαῖς πόλεσιν ἐπιλειπούσης τῆς δυνάμεως ἔληγε τὸ φιλόνικον. οὐ μὴν ἀλλὰ Νέμεσίς τις ὥσπερ ἀθλητὴν εὐδρομοῦντα πρὸς τέρμασι τοῦ βίου κατέβαλε, λέγεται γὰρ ἔν τινι συλλόγῳ τῶν παρόντων ἐπαινούντων ἄνδρα δεινὸν εἶναι δοκοῦντα περὶ στρατηγίαν εἰπεῖν τὸν Φιλοποίμενα, καὶ πῶς ἄξιον ἐκείνου λόγον ἔχειν τοῦ ἀνδρός, ὅστις ἥλω ζῶν ὑπὸ τῶν πολεμίων;", "st": "Phil. 18.1"}, {"sp": "N", "t": "μεθ’ ἡμέρας δὲ ὀλίγας Δεινοκράτης Μεσσήνιος, ἄνθρωπος ἰδίᾳ τε τῷ Φιλοποίμενι προσκεκρουκώς καὶ τοῖς ἄλλοις ἐπαχθὴς διὰ πονηρίαν καὶ ἀκολασίαν, τήν τε Μεσσήνην ἀπέστησε τῶν Ἀχαιῶν, καὶ κώμην τήν καλουμένην Κολωνίδα προσηγγέλθη μέλλων καταλαμβάνειν ὁ δὲ Φιλοποίμην ἔτυχε μὲν ἐν Ἄργει πυρέσσων, πυθόμενος δὲ ταῦτα συνέτεινεν εἰς Μεγάλην πόλιν ἡμέρᾳ μιᾷ σταδίους πλείονας ἢ τετρακοσίους. κἀκεῖθεν εὐθὺς ἐβοήθει τοὺς ἱππεῖς ἀναλαβών, οἵπερ ἦσαν ἐνδοξότατοι μὲν τῶν πολιτῶν, νέοι δὲ κομιδῇ, δι’ εὔνοιαν τοῦ Φιλοποίμενος καὶ ζῆλον ἐθελονταὶ συστρατεύοντες. ἱππασάμενοι δὲ πρὸς τήν Μεσσήνην καὶ περὶ τὸν Εὐάνδρου λόφον ἀπαντῶντι τῷ Δεινοκράτει συμπεσόντες ἐκεῖνον μὲν ἐτρέψαντο, τῶν δὲ πεντακοσίων, οἳ τήν χώραν τῶν Μεσσηνίων παρεφύλαττον, ἐξαίφνης ἐπιφερομένων καὶ τῶν πρότερον ἡττημένων, ὡς τούτους κατεῖδον, αὖθις ἀνὰ τοὺς λόφους ἀθροιζομένων, δείσας ὁ Φιλοποίμην κυκλωθῆναι καὶ τῶν ἱππέων φειδόμενος ἀνεχώρει διὰ τόπων χαλεπῶν, αὐτὸς οὐραγῶν καὶ πολλάκις ἀντεξελαύνων τοῖς πολεμίοις καὶ ὅλως ἐπισπώμενος ἐφ’ ἑαυτόν, οὐ τολμώντων ἀντεμβαλεῖν ἐκείνων, ἀλλὰ κραυγαῖς καὶ περιδρομαῖς χρωμένων ἄποθεν.", "st": "Phil. 18.3"}, {"sp": "N", "t": "ἀφιστάμενος οὖν πολλάκις διὰ τοὺς νεανίσκους καὶ καθ’ ἕνα παραπέμπων ἔλαθεν ἐν πολλοῖς ἀπομονωθεὶς πολεμίοις. καὶ συνάψαι μὲν εἰς χεῖρας οὐδεὶς ἐτόλμησεν αὐτῷ, πόρρωθεν δὲ βαλλόμενος καὶ βιαζόμενος πρὸς χωρία πετρώδη καὶ παράκρημνα χαλεπῶς μετεχειρίζετο καὶ κατέξαινε τὸν ἵππον. αὐτῷ δὲ τὸ μὲν γῆρας ὑπὸ ἀσκήσεως πολλῆς ἐλαφρὸν ἦν καὶ πρὸς οὐδὲν ἐμπόδιον εἰς τὸ σωθῆναι, τότε δὲ καὶ διὰ τήν ἀρρωστίαν τοῦ σώματος ἐνδεοῦς γεγονότος καὶ διὰ τήν ὁδοιπορίαν κατακόπου, βαρὺν ὄντα καὶ δυσκίνητον ἤδη σφαλεὶς ὁ ἵππος εἰς τήν γῆν κατέβαλε, σκληροῦ δὲ τοῦ πτώματος γενομένου καὶ τῆς κεφαλῆς παθούσης ἔκειτο πολὺν χρόνον ἄναυδος, ὥστε καὶ τοὺς πολεμίους τεθνάναι δόξαντας αὐτόν ἐπιχειρεῖν στρέφειν τὸ σῶμα καὶ σκυλεύειν. ἐπεὶ δὲ τήν κεφαλὴν ἐπάρας διέβλεψεν, ἀθρόοι περιπεσόντες ἀπέστρεφον αὐτοῦ τὰς χεῖρας ὀπίσω καὶ δήσαντες ἦγον, ὕβρει χρώμενοι πολλῇ καὶ λοιδορίᾳ κατ’ ἀνδρὸς οὐδὲ ὄναρ ἄν ποτε παθεῖν ὑπὸ Δεινοκράτους ταῦτα προσδοκήσαντος.", "st": "Phil. 18.6"}, {"sp": "N", "t": "οἱ δ’ ἐν τῇ πόλει τῇ μὲν ἀγγελίᾳ θαυμαστῶς ἐπαρθέντες ἠθροίζοντο περὶ τὰς πύλας· ὡς δὲ εἶδον ἑλκόμενον τὸν Φιλοποίμενα παρ’ ἀξίαν τῆς τε δόξης καὶ τῶν ἔμπροσθεν ἔργων καὶ τροπαίων, ἠλέησαν οἱ πλεῖστοι καὶ συνήλγησαν, ὥστε καὶ δακρῦσαι καὶ τὴν ἀνθρωπίνην ἐκφλαυρίσαι δύναμιν ὡς ἄπιστον καὶ τὸ μηδὲν οὖσαν. οὕτω δὲ κατὰ μικρὸν εἰς πολλοὺς φιλάνθρωπος ἐχώρει λόγος ὡς μνημονευτέον εἴη τῶν πρόσθεν εὐεργεσιῶν, καὶ τῆς ἐλευθερίας ἣν ἀπέδωκεν αὐτοῖς Νάβιν ἐξελάσας τὸν τύραννον. ὀλίγοι δὲ ἦσαν οἳ τῷ Δεινοκράτει χαριζόμενοι στρεβλοῦν τὸν ἄνδρα καὶ κτείνειν ἐκέλευον ὡς βαρὺν πολέμιον καὶ δυσμείλικτον, αὐτῷ τε Δεινοκράτει φοβερώτερον εἰ διαφύγοι καθυβρισμένος ὑπ’ αὐτοῦ καὶ γεγονὼς αἰχμάλωτος. οὐ μὴν ἀλλὰ κομίσαντες αὐτὸν εἰς τὸν καλούμενον Θησαυρόν, οἴκημα κατάγειον οὔτε πνεῦμα λαμβάνον οὔτε φῶς ἔξωθεν οὔτε θύρας ἔχον, ἀλλὰ μεγάλῳ λίθῳ περιαγομένῳ κατακλειόμενον, ἐνταῦθα κατέθεντο, καὶ τὸν λίθον ἐπιρράξαντες ἄνδρας ἐνόπλους κύκλῳ περιέστησαν.", "st": "Phil. 19.1"}, {"sp": "N", "t": "οἱ δ’ ἱππεῖς τῶν Ἀχαιῶν ἐκ τῆς φυγῆς ἀναλαβόντες αὑτούς, ὡς οὐδαμοῦ φανερὸς ἦν ὁ Φιλοποίμην, ἀλλ’ ἐδόκει τεθνάναι, πολὺν μὲν χρόνον ἐπέστησαν ἀνακαλούμενοι τὸν ἄνδρα καὶ δίδοντες ἀλλήλοις λόγον ὡς αἰσχρὰν σωτηρίαν καὶ ἄδικον σῴζονται προέμενοι τοῖς πολεμίοις τὸν στρατηγόν ἀφειδήσαντα τοῦ ζῆν δι’ αὑτούς, ἔπειτα προϊόντες ἅμα καὶ πολυπραγμονοῦντες ἐπύθοντο τὴν σύλληψιν αὐτοῦ καὶ διήγγελλον εἰς τὰς πόλεις τῶν Ἀχαιῶν, οἱ δὲ συμφορὰν ποιούμενοι μεγάλην ἀπαιτεῖν μὲν ἔγνωσαν τὸν ἄνδρα παρὰ τῶν Μεσσηνίων πρεσβείαν πέμψαντες, αὐτοὶ δὲ παρεσκευάζοντο στρατεύειν.", "st": "Phil. 19.4"}, {"sp": "N", "t": "οὗτοι μὲν οὖν ταῦτα ἔπραττον. ὁ δὲ Δεινοκράτης μάλιστα τὸν χρόνον ὡς σωτήριον τῷ Φιλοποίμενι δεδοικώς καὶ φθάσαι τὰ παρὰ τῶν Ἀχαιῶν βουλόμενος, ἐπεὶ νὺξ ἐπῆλθε καὶ τὸ πλῆθος ἀπεχώρησε τῶν Μεσσηνίων, ἀνοίξας τὸ δεσμωτήριον εἰσέπεμψε δημόσιον οἰκέτην φάρμακον κομίζοντα, προσενεγκεῖν καὶ παραστῆναι μέχρι ἂν ἐκπίῃ κελεύσας. ἔτυχε μὲν οὖν ἐν τῷ χλαμυδίῳ κατακείμενος, οὐ καθεύδων, ἀλλὰ λύπῃ καὶ θορύβῳ κατεχόμενος, ἰδὼν δὲ φῶς καὶ παρεστῶτα πλησίον τὸν ἄνθρωπον ἔχοντα τὴν κύλικα τοῦ φαρμάκου, συναγαγὼν μόλις ἑαυτὸν ὑπ’ ἀσθενείας ἀνεκάθιζε. καὶ δεξάμενος ἠρώτησεν εἴ τι περὶ τῶν ἱππέων καὶ μάλιστα Λυκόρτα πεπυσμένος ἐστίν, εἰπόντος δὲ τἀνθρώπου διαπεφευγέναι τοὺς πολλούς, ἐπένευσε τῇ κεφαλῇ, καὶ διαβλέψας πρᾴως πρὸς τὸν ἄνθρωπον, εὖ λέγεις, εἶπεν, εἰ μὴ πάντα κακῶς πεπράχαμεν. ἄλλο δὲ μηδὲν εἰπὼν μηδὲ φθεγξάμενος ἐξέπιε καὶ πάλιν αὑτὸν ἀπέκλινεν, οὐ πολλὰ πράγματα τῷ φαρμάκῳ παρασχών, ἀλλ’ ἀποσβεσθεὶς ταχὺ διὰ τὴν ἀσθένειαν.", "st": "Phil. 20.1"}, {"sp": "N", "t": "ὡς οὖν ὁ περὶ τῆς τελευτῆς λόγος ἧκεν εἰς τοὺς Ἀχαιούς, τὰς μὲν πόλεις αὐτῶν κοινὴ κατήφεια καὶ πένθος εἶχεν, οἱ δ’ ἐν ἡλικίᾳ μετὰ τῶν προβούλων συνελθόντες εἰς Μεγάλην πόλιν οὐδ’ ἡντινοῦν ἀναβολὴν ἐποιήσαντο τῆς τιμωρίας, ἀλλ’ ἑλόμενοι στρατηγὸν Λυκόρταν εἰς τὴν Μεσσηνίαν ἐνέβαλον καὶ κακῶς ἐποίουν τὴν χώραν, ἄχρι οὗ συμφρονήσαντες ἐδέξαντο τοὺς Ἀχαιούς. καὶ Δεινοκράτης μὲν αὐτὸς αὑτὸν φθάσας διεχρήσατο, τῶν δὲ ἄλλων ὅσοις μὲν ἀνελεῖν ἔδοξε Φιλοποίμενα δι’ αὐτῶν ἀπέθνῃσκον, ὅσοις δὲ καὶ βασανίσαι, τούτους ἐπ’ αἰκίαις ἀπολουμένους συνελάμβανεν ὁ Λυκόρτας. τὸ δὲ σῶμα καύσαντες αὐτοῦ καὶ τὰ λείψανα συνθέντες εἰς ὑδρίαν ἀνεζεύγνυσαν, οὐκ ἀτάκτως οὐδὲ ὡς ἔτυχεν, ἀλλ’ ἐπινίκιόν πομπήν τινα ἅμα ταῖς ταφαῖς μίξαντες. ἦν μὲν γὰρ ἐστεφανωμένους ἰδεῖν, ἦν δὲ τοὺς αὐτοὺς καὶ δακρύοντας, ἦν δὲ τοὺς ἐχθροὺς δεσμίους ἀγομένους, αὐτὴν δὲ τὴν ὑδρίαν ὑπὸ πλήθους ταινιῶν τε καὶ στεφάνων μόλις ὁρωμένην ἐκόμιζεν ὁ τοῦ στρατηγοῦ τῶν Ἀχαιῶν παῖς Πολύβιος καὶ περὶ αὑτὸν οἱ πρῶτοι τῶν Ἀχαιῶν. οἱ δὲ στρατιῶται ὠπλισμένοι μὲν αὐτοί, τοῖς δ’ ἵπποις κεκοσμημένοις ἐπηκολούθουν, οὔτε, οἷον ἐπὶ πένθει τοσούτῳ, κατηφεῖς οὔτε τῇ νίκῃ γαυριῶντες. ἐκ δὲ τῶν διὰ μέσου πόλεων καὶ κωμῶν ἀπαντῶντες, ὥσπερ αὑτὸν ἀπὸ στρατείας ἐπανιόντα δεξιούμενοι, τῆς ὑδρίας ἐφήπτοντο, καὶ συμπροῆγον εἰς Μεγάλην πόλιν. ὡς οὖν συνανεμείχθησαν αὐτοῖς οἱ πρεσβύτεροι μετὰ γυναικῶν καὶ παίδων, ὀλοφυρμὸς ἤδη διὰ παντὸς ἐχώρει τοῦ στρατεύματος εἰς τὴν πόλιν ἐπιποθοῦσαν τὸν ἄνδρα καὶ βαρέως φέρουσαν, οἰομένην συναποβεβληκέναι τὸ πρωτεύειν ἐν τοῖς Ἀχαιοῖς.", "st": "Phil. 21.1"}, {"sp": "N", "t": "ἐτάφη μὲν οὖν, ὡς εἰκὸς, ἐνδόξως, καὶ περὶ τὸ μνημεῖον οἱ τῶν Μεσσηνίων αἰχμάλωτοι κατελεύσθησαν. οὐσῶν δὲ πολλῶν μὲν εἰκόνων αὐτοῦ, μεγάλων δὲ τιμῶν, ἃς αἱ πόλεις ἐψηφίσαντο, Ῥωμαῖος ἀνὴρ ἐν τοῖς περὶ Κόρινθον ἀτυχήμασι τῆς Ἑλλάδος ἐπεχείρησεν ἀνελεῖν ἁπάσας καὶ διώκειν αὐτόν, ἐνδεικνύμενος, ὥσπερ ἔτι ζῶντα, Ῥωμαίοις πολέμιον καὶ κακόνουν γενέσθαι. λόγων δὲ λεχθέντων καὶ Πολυβίου πρὸς τὸν συκοφάντην ἀντειπόντος οὔθ ὁ Μόμμιος οὔτε οἱ πρέσβεις ὑπέμειναν ἀνδρὸς ἐνδόξου τιμὰς ἀφανίσαι, καίπερ οὐκ ὀλίγα τοῖς περὶ Τίτον καὶ Μάνιον ἐναντιωθέντος, ἀλλὰ τῆς χρείας τὴν ἀρετὴν ἐκεῖνοι καὶ τὸ καλὸν, ὡς ἔοικε, τοῦ λυσιτελοῦς διώριζον, ὀρθῶς καὶ προσηκόντως τοῖς μὲν ὠφελοῦσι μισθὸν καὶ χάριν παρὰ τῶν εὖ παθόντων, τοῖς δ’ ἀγαθοῖς τιμὴν ὀφείλεσθαι παρὰ τῶν ἀγαθῶν ἀεὶ νομίζοντες.", "st": "Phil. 21.5"}, {"sp": "N", "t": "ταῦτα περὶ Φιλοποίμενος.", "st": "Phil. 21.5b"}, {"sp": "HDR", "t": "Τίτος Κοΐντιος Φλαμινῖνος"}, {"sp": "N", "t": "ὃν δὲ παραβάλλομεν αὐτῷ, Τίτος Κοΐντιος Φλαμινῖνος, ἰδέαν μὲν ὁποῖος ἦν πάρεστι θεάσασθαι τοῖς βουλομένοις ἀπὸ τῆς ἐν Ῥώμῃ χαλκῆς εἰκόνος, ἣ κεῖται παρὰ τὸν μέγαν Ἀπόλλωνα τὸν ἐκ Καρχηδόνος ἀντικρὺ τοῦ ἱπποδρόμου, γράμμασιν Ἑλληνικοῖς ἐπιγεγραμμένη, τὸ δὲ ἦθος ὀξὺς λέγεται γενέσθαι καὶ πρὸς ὀργὴν καὶ πρὸς χάριν. οὐ μὴν ὁμοίως, ἀλλ’ ἐλαφρὸς μὲν ἐν τῷ κολάζειν καὶ οὐκ ἐπίμονος, πρὸς δὲ τὰς χάριτας τελεσιουργός καὶ τοῖς εὐεργετηθεῖσι διὰ παντὸς ὥσπερ εὐεργέταις εὔνους, καὶ πρόθυμος, ὡς κάλλιστα τῶν κτημάτων, τοὺς ἐν πεπονθότας ὑπ’ αὐτοῦ περιέπειν ἀεὶ καὶ σῴζειν. φιλοτιμότατος δὲ καὶ φιλοδοξότατος ὢν ἐβούλετο τῶν ἀρίστων καὶ μεγίστων πράξεων αὐτουργὸς εἶναι, καὶ τοῖς δεομένοις εὖ παθεῖν μᾶλλον ἢ τοῖς εὖ ποιῆσαι δυναμένοις ἔχαιρε, τοὺς μὲν ὕλην τῆς ἀρετῆς, τοὺς δὲ ὥσπερ ἀντιπάλους πρὸς δόξαν ἡγούμενος.", "st": "Flam. 1.1"}, {"sp": "N", "t": "παιδευθεὶς δὲ παιδείαν τὴν διὰ τῶν ἐθῶν τῶν στρατιωτικῶν, πολλοὺς τότε καὶ μεγάλους τῆς Ῥώμης ἀγωνιζομένης ἀγῶνας καὶ τῶν νέων εὐθὺς ἐξ ἀρχῆς ἐν τῷ στρατεύεσθαι στρατηγεῖν διδασκομένων, πρῶτον μὲν ἐν τῷ πρὸς Ἀννίβαν πολέμῳ χιλίαρχος ὑπατεύοντι Μαρκέλλῳ συνεστρατεύσατο. καὶ Μάρκελλος μὲν ἐνέδρᾳ περιπεσὼν ἐτελεύτησε, Τίτος δὲ τῆς περὶ Τάραντα χώρας καὶ Τάραντος αὐτοῦ τὸ δεύτερον ἡλωκότος ἔπαρχος ἀποδειχθείς εὐδοκίμησεν οὐχ ἧττον ἐπὶ τοῖς δικαίοις ἢ κατὰ τὴν στρατείαν. διὸ καὶ πεμπομένων ἀποίκων εἰς δύο πόλεις, Νάρνειάν τε καὶ Κῶνσαν, ἄρχων ᾑρέθη καὶ οἰκιστής.", "st": "Flam. 1.3"}, {"sp": "N", "t": "τοῦτο δὲ αὑτὸν ἐπῆρε μάλιστα τὰς διὰ μέσου καὶ συνήθεις τοῖς νέοις ἀρχὰς ὑπερβάντα, δημαρχίαν καὶ στρατηγίαν καὶ ἀγορανομίαν, εὐθὺς αὑτὸν ὑπατείας ἀξιοῦν καὶ κατῄει τοὺς ἀπὸ τῶν κληρουχιῶν ἔχων προθύμους. τῶν δὲ περὶ Φούλβιον καὶ Μάνιον δημάρχων ἐνισταμένων καὶ δεινὸν εἶναι λεγόντων ἄνδρα νέον εἰς τὴν μεγίστην ἀρχὴν εἰσβιάζεσθαι παρὰ τοὺς νόμους, οἷον ἀτέλεστον ἔτι τῶν πρώτων ἱερῶν καὶ μυστηρίων τῆς πολιτείας, ἡ μὲν σύγκλητος ἀπέδωκε τῷ δήμῳ τὴν ψῆφον, ὁ δὲ δῆμος ἀπέδειξεν αὑτὸν ὕπατον μετὰ Σέξτου Αἰλίου, καίπερ οὔπω τριάκοντα ἔτη γεγονότα, Κλήρῳ δὲ λαγχάνει τὸν πρὸς Φίλιππον καὶ Μακεδόνας πόλεμον, εὐτυχίᾳ τινὶ τῶν Ῥωμαίων συλλαχὼν πράγμασι καὶ ἀνθρώποις οὐ πάντα πολέμῳ καὶ βίᾳ χρωμένου δεομένοις ἄρχοντος, ἀλλὰ πειθοῖ καὶ ὁμιλίᾳ μᾶλλον ἁλωσίμοις. Φιλίππῳ γὰρ ἦν στόμωμα μὲν εἰς μάχην ἀποχρῶν ἡ Μακεδόνων ἀρχή, ῥώμη δὲ πολέμου τριβὴν ἔχοντος καὶ χορηγία καὶ καταφυγὴ καὶ ὄργανον ὅλως τῆς φάλαγγος ἡ τῶν Ἑλλήνων δύναμις, ὧν μὴ διαλυθέντων ἀπὸ τοῦ Φιλίππου μιᾶς μάχης οὐκ ἦν ἔργον ὁ πρὸς αὑτὸν πόλεμος. ἡ δ’ Ἑλλὰς οὔπω πολλὰ συνενηνεγμένη Ῥωμαίοις, ἀλλὰ τότε πρῶτον ἐπιμιγνυμένη ταῖς πράξεσιν, εἰ μὴ φύσει τε χρηστὸς ἦν ὁ ἄρχων καὶ λόγῳ μᾶλλον ἢ πολέμῳ χρώμενος, ἐντυγχάνοντί τε προσῆν πιθανότης καὶ πρᾳότης ἐντυγχανομένῳ καὶ τόνος πλεῖστος ὑπὲρ τῶν δικαίων, οὐκ ἂν οὕτως ῥᾳδίως ἀντὶ τῶν συνήθων ἀλλόφυλον ἀρχὴν ἠγάπησε. ταῦτα μὲν οὖν ἐπὶ τῶν πράξεων αὐτοῦ δηλοῦται.", "st": "Flam. 2.1"}, {"sp": "N", "t": "πυνθανόμενος δὲ ὁ Τίτος τοὺς πρὸ ἑαυτοῦ στρατηγούς, τοῦτο μὲν Σουλπίκιον, τοῦτο δὲ Πόπλιον, ὀψὲ τῆς ὥρας ἐμβαλόντας εἰς Μακεδονίαν καὶ τοῦ πολέμου βραδέως ἁψαμένους κατατετρῖφθαι τοπομαχοῦντας καὶ διαπληκτιζομένους ἀκροβολισμοῖς ὑπὲρ ὁδῶν καὶ σιτολογίας πρὸς τὸν Φίλιππον, οὐκ ᾤετο δεῖν, ὥσπερ ἐκεῖνοι καταναλώσαντες οἴκοι τὸν ἐνιαυτὸν ἐν τιμαῖς καὶ πολιτείαις ὕστερον ἐξώρμησαν ἐπὶ τὰς στρατείας, οὕτως καὶ αὐτὸς ἐνιαυτὸν ἐπικερδᾶναι τῇ ἀρχῇ, τὸν μὲν ὑπατεύσας, τῷ δὲ πολεμήσας, ἀλλ’ ὁμοῦ φιλοτιμούμενος ἐνεργὸν τῷ πολέμῳ τὴν ἀρχὴν παρασχεῖν, τὰς μὲν ἐν τῇ πόλει τιμὰς καὶ προεδρίας ἀφῆκεν, αἰτησάμενος δὲ παρὰ τῆς βουλῆς τὸν ἀδελφὸν αὑτῷ Λεύκιον ἄρχοντα νεῶν συστρατεύειν, καὶ τῶν μετὰ Σκηπίωνος ἐν Ἰβηρίᾳ μὲν Ἀσδρούβαν, ἐν Λιβύῃ δὲ Ἀννίβαν αὐτὸν καταμεμαχημένων τοὺς ἀκμάζοντας ἔτι καὶ προθύμους ἀναλαβὼν ὥσπερ στόμωμα, τρισχιλίους γενομένους, εἰς τὴν Ἤπειρον ἀσφαλῶς διεπέρασε. καὶ τὸν Πόπλιον εὑρὼν μετὰ τῆς δυνάμεως ἀντιστρατοπεδεύοντα τῷ Φιλίππῳ τὰς περὶ τὸν Ἄψον ποταμὸν ἐμβολὰς καὶ τὰ Στενὰ φυλάττοντι πολὺν ἤδη χρόνον, οὐδὲν δὲ περαίνοντα διὰ τὴν ὀχυρότητα τῶν χωρίων, παρέλαβε τὸ στράτευμα καὶ τὸν Πόπλιον ἀποπέμψας κατεσκέπτετο τοὺς τόπους, εἰσὶ δὲ ὀχυροὶ μὲν οὐχ ἧττον τῶν περὶ τὰ Τέμπη, κάλλη δὲ δένδρων, ὡς ἐκεῖνοι, καὶ χλωρότητα ὕλης καὶ διατριβὰς καὶ λειμῶνας ἡδεῖς οὐκ ἔχουσιν. ὀρῶν δὲ μεγάλων καὶ ὑψηλῶν ἑκατέρωθεν εἰς μίαν φάραγγα μεγίστην καὶ βαθεῖαν συμφερομένων διεκπίπτων ὁ Ἄψος καὶ σχῆμα καὶ τάχος ἐξομοιοῦται πρὸς τὸν Πηνειόν, τὴν μὲν ἄλλην ἅπασαν ἀποκρύπτων ὑπώρειαν, ἐκτομὴν δὲ κρημνώδη καὶ στενὴν παρὰ τὸ ῥεῖθρον ἀπολείπων ἀτραπόν, οὐδὲ ἄλλως ῥᾳδίαν στρατεύματι διελθεῖν, εἰ δὲ καὶ φυλάττοιτο, παντελῶς ἄπορον.", "st": "Flam. 3.1"}, {"sp": "N", "t": "ἦσαν μὲν οὖν οἱ τὸν Τίτον ἄγειν κύκλῳ διὰ τῆς Δασσαρήτιδος κατὰ Λύκον εὔπορον ὁδὸν καὶ ῥᾳδίαν ἐπιχειροῦντες. ὁ δὲ δεδοικώς μὴ πόρρω θαλάττης ἐμβαλὼν ἑαυτὸν εἰς τόπους γλίσχρους καὶ σπειρομένους πονηρῶς τοῦ Φιλίππου φυγομαχοῦντος ἀπορήσῃ σιτίων καὶ πάλιν ἄπρακτος, ὥσπερ ὁ πρὸ αὐτοῦ στρατηγὸς, ἀναχωρεῖν ἀναγκασθῇ πρὸς τὴν θάλασσαν, ἔγνω προσβαλὼν ἀνὰ κράτος διὰ τῶν ἄκρων βιάσασθαι τὴν πάροδον. ἐπεὶ δὲ τὰ ὄρη τοῦ Φιλίππου τῇ φάλαγγι κατέχοντος, ἐκ τῶν πλαγίων πανταχόθεν ἐπὶ τοὺς Ῥωμαίους ἀκοντίων καὶ τοξευμάτων φερομένων, πληγαὶ μὲν ἐγίνοντο καὶ ἀγῶνες ὀξεῖς καὶ νεκροὶ παρ’ ἀμφοτέρων ἔπιπτον, οὐδὲν δὲ τοῦ πολέμου πέρας ἐφαίνετο, προσῆλθον ἄνθρωποι τῶν αὐτόθι νεμόντων φράζοντές τινα κύκλωσιν ἀμελουμένην ὑπὸ τῶν πολεμίων, ᾗ τὸν στρατόν ἄξειν ὑπισχνοῦντο καὶ καταστήσειν μάλιστα τριταῖον ἐπὶ τῶν ἄκρων. γνώστην δὲ τῆς πίστεως παρείχοντο καὶ βεβαιωτὴν Χάροπα τὸν Μαχάτα, πρωτεύοντα μὲν Ἠπειρωτῶν, εὔνουν δὲ Ῥωμαίοις ὄντα καὶ κρύφα φόβῳ τοῦ Φιλίππου συναγωνιζόμενον. ᾧ πιστεύσας ὁ Τίτος ἐκπέμπει χιλίαρχον ἕνα πεζοὺς ἔχοντα τετρακισχιλίους καὶ ἱππεῖς τριακοσίους, ἡγοῦντο δὲ οἱ νομεῖς ἐκεῖνοι δεδεμένοι· καὶ τὰς μὲν ἡμέρας ἀνεπαύοντο κοίλους προβαλλόμενοι καὶ ὑλώδεις τόπους, ὥδευον δὲ νύκτωρ πρὸς τὴν σελήνην καὶ γὰρ ἦν διχόμηνος.", "st": "Flam. 4.1"}, {"sp": "N", "t": "ὁ δὲ Τίτος τούτους ἀποστείλας τὰς μὲν ἄλλας ἡμέρας διανέπαυε τὸν στρατόν ὅσα μὴ περισπᾶν τοῖς ἀκροβολισμοῖς τοὺς πολεμίους, καθ’ ἣν δὲ ἔμελλον ὑπερφανήσεσθαι τῶν ἄκρων οἱ περιϊόντες, ἅμ’ ἡμέρᾳ πᾶν μὲν βαρὺ, πᾶν δὲ γυμνητικὸν ὅπλον ἐκίνει· καὶ τριχῇ νείμας τὴν δύναμιν αὐτὸς μὲν εἰς τὸ στενώτατον παρὰ τὸ ῥεῖθρον ὀρθίας ἀνῆγε τὰς σπείρας βαλλόμενος ὑπὸ τῶν Μακεδόνων καὶ συμπλεκόμενος τοῖς ἀπαντῶσι περὶ τὰς δυσχωρίας, τῶν δὲ ἄλλων ἑκατέρωθεν ἅμα πειρωμένων ἁμιλλᾶσθαι καὶ ταῖς τραχύτησιν ἐμφυομένων προθύμως, ὅ τε ἥλιος ἀνέσχε καὶ καπνὸς οὐ βέβαιος, ἀλλ’ οἷον ὄρειος ὁμίχλη πόρρωθεν ἀνατέλλων καὶ διαφαινόμενος τοὺς μὲν πολεμίους ἐλάνθανε, κατὰ νώτου γὰρ ἦν αὐτοῖς, ἤδη τῶν ἄκρων ἐχομένων, οἱ δὲ Ῥωμαῖοι δόξαν ἔσχον ἀμφίβολον ἐν ἀγῶνι καὶ πόνῳ τὴν ἐλπίδα πρὸς τὸ βουλόμενον λαμβάνοντες. ἐπεὶ δὲ μᾶλλον αὐξανόμενος καὶ διαμελαίνων τὸν ἀέρα καὶ πολὺς ἄνω χωρῶν ἐδηλοῦτο πυρσὸς εἶναι φίλιος, οἱ μὲν ἀλαλάξαντες ἐπέβαινον ἐρρωμένως καὶ συνέστελλον εἰς τὰ τραχύτατα τοὺς πολεμίους, οἱ δὲ ὄπισθεν ἀπὸ τῶν ἄκρων ἀντηλάλαξαν.", "st": "Flam. 4.4"}, {"sp": "N", "t": "φυγὴ μὲν οὖν ἦν εὐθὺς ὀξεῖα πάντων, ἔπεσον δὲ δισχιλίων οὐ πλείους· ἀφῃροῦντο γὰρ αἱ δυσχωρίαι τήν δίωξιν. χρήματα δὲ καὶ σκηνὰς καὶ θεράποντας οἱ Ῥωμαῖοι διαρπάσαντες ἐκράτουν τῶν Στενῶν, καὶ διώδευον τήν Ἤπειρον οὕτω κοσμίως καὶ μετ’ ἐγκρατείας τοσαύτης ὥστε, τῶν πλοίων καὶ τῆς θαλάσσης μακρὰν ὄντας αὐτούς, καὶ τὸν ἐπιμήνιον σῖτον μὴ μεμετρημένους οὐδ’ εὐποροῦντας ἀγορᾶς, ἀπέχεσθαι τῆς χώρας ἀμφιλαφεῖς ὠφελείας ἐχούσης. ὁ γὰρ Τίτος πυνθανόμενος τὸν Φίλιππον, ὡς ὅμοια φεύγοντι τήν Θετταλίαν διερχόμενος τοὺς μὲν ἀνθρώπους ἐκ τῶν πόλεων ἀνίστησιν εἰς τὰ ὄρη, τὰς δὲ πόλεις καταπίμπρησι, τῶν δὲ χρημάτων τὰ λειπόμενα διὰ πλῆθος ἢ βάρος ἁρπαγὴν προτίθεται, τρόπον τινὰ τῆς χώρας ἐξιστάμενος ἤδη Ῥωμαίοις, ἐφιλοτιμεῖτο καὶ παρεκάλει τοὺς στρατιώτας ὥσπερ οἰκείας καὶ παρακεχωρημένης κηδομένους βαδίζειν. καὶ μέντοι καὶ παρεῖχεν αὐτοῖς τὰ γινόμενα τῆς εὐταξίας αἴσθησιν εὐθύς, προσεχώρουν μὲν γὰρ αἱ πόλεις ἁψαμένοις Θετταλίας, οἱ δ’ ἐντὸς Πυλῶν Ἕλληνες ἐπόθουν καὶ διεπτόηντο ταῖς ὁρμαῖς πρὸς τὸν Τίτον, Ἀχαιοὶ δὲ τήν Φιλίππου συμμαχίαν ἀπειπάμενοι πολεμεῖν ἐψηφίσαντο μετὰ ’ Ῥωμαίων πρὸς αὐτόν. Ὀπούντιοι δέ, καίπερ Αἰτωλῶν τότε Ῥωμαίοις συναγωνιζομένων προθυμότατα καὶ τήν πόλιν ἀξιούντων παραλαβεῖν καὶ φυλάττειν, οὐ προσέσχον, ἀλλὰ μεταπεμψάμενοι τὸν Τίτον ἐκείνῳ διεπίστευσαν ἑαυτοὺς καὶ παρέδωκαν.", "st": "Flam. 5.1"}, {"sp": "N", "t": "Πύρρον μὲν οὖν λέγουσιν, ὅτε πρῶτον ἀπὸ σκοπῆς κατεῖδε τὸ στράτευμα τῶν Ῥωμαίων διακεκοσμημένον, εἰπεῖν οὐ βαρβαρικὴν αὐτῷ φανῆναι τήν τῶν βαρβάρων παράταξιν οἱ δὲ Τίτῳ πρῶτον ἐντυγχάνοντες ἠναγκάζοντο παραπλησίας ἀφιέναι φωνάς. ἀκούοντες γὰρ τῶν Μακεδόνων ὡς ἄνθρωπος ἄρχων βαρβάρου στρατιᾶς ἔπεισι δι’ ὅπλων πάντα καταστρεφόμενος καὶ δουλούμενος, εἶτα ἀπαντῶντες ἀνδρὶ τήν τε ἡλικίαν νέῳ καὶ τήν ὄψιν φιλανθρώπῳ, φωνήν τε καὶ διάλεκτον Ἕλληνι καὶ τιμῆς ἀληθοῦς ἐραστῇ, θαυμασίως ἐκηλοῦντο, καὶ τὰς πόλεις ἀπιόντες ἐνεπίμπλασαν εὐνοίας τῆς πρὸς αὐτόν ὡς ἐχούσας ἡγεμόνα τῆς ἐλευθερίας. ἐπεὶ δὲ καὶ Φιλίππῳ δοκοῦντι συμβατικῶς ἔχειν εἰς ταὐτὸν ἐλθὼν προὔτεινεν εἰρήνην καὶ φιλίαν ἐπὶ τῷ τοὺς Ἕλληνας αὐτονόμους ἐᾶν καὶ τὰς φρουρὰς ἀπαλλάττειν, ὁ δὲ οὐκ ἐδέξατο, παντάπασιν ἤδη τότε καὶ τοῖς θεραπεύουσι τὰ τοῦ Φιλίππου παρέστη Ῥωμαίους πολεμήσοντας ἥκειν οὐχ Ἕλλησιν, ἀλλ’ ὑπὲρ Ἑλλήνων Μακεδόσι.", "st": "Flam. 5.5"}, {"sp": "N", "t": "τὰ μὲν οὖν ἄλλα προσεχώρει καθ’ ἡσυχίαν αὐτῷ, τὴν δὲ Βοιωτίαν ἀπολέμως ἐπιπορευομένῳ Θηβαίων ἀπήντησαν οἱ πρῶτοι, φρονοῦντες μὲν τὰ τοῦ Μακεδόνος διὰ Βραχύλλην, ἀσπαζόμενοι δὲ καὶ τιμῶντες τὸν Τίτον, ὡς φιλίας πρὸς ἀμφοτέρους ὑπαρχούσης. ὁ δ’ ἐντυχὼν αὐτοῖς φιλανθρώπως καὶ δεξιωσάμενος προῆγεν ἡσυχῇ καθ’ ὁδόν, τὰ μὲν ἐρωτῶν καὶ πυνθανόμενος, τὰ δὲ διηγούμενος, καὶ παράγων ἐπίτηδες ἄχρι τοὺς στρατιώτας ἀναλαβεῖν ἐκ τῆς πορείας. οὕτω δὲ προάγων συνεισῆλθε τοῖς Θηβαίοις εἰς τὴν πόλιν, οὐ πάνυ μὲν ἡδομένοις, ὀκνοῦσι δὲ κωλύειν, ἐπεὶ στρατιῶται γε μέτριοι τὸ πλῆθος εἵποντο. καὶ μέντοι παρελθὼν ὁ Τίτος, ὡς οὐκ ἔχων τὴν πόλιν, ἔπειθεν ἑλέσθαι τὰ Ῥωμαίων, Ἀττάλου τοῦ βασιλέως συναγορεύοντος αὐτῷ καὶ συνεξορμῶντος τοὺς Θηβαίους, ἀλλ’ Ἄτταλος μὲν, ὡς ἔοικε, τοῦ γήρως προθυμότερον ἑαυτὸν τῷ Τίτῳ ῥήτορα παρασχεῖν φιλοτιμούμενος, ἐν αὐτῷ τῷ λέγειν προσπεσόντος ἰλίγγου τινὸς ἢ ῥεύματος ἄφνω τὴν αἴσθησιν ἐπιληφθεὶς ἔπεσε, καὶ μετ’ οὐ πολὺ ταῖς ναυσὶν εἰς Ἀσίαν ἀποκομισθεὶς ἐτελεύτησεν· οἱ δὲ Βοιωτοὶ προσεχώρησαν τοῖς Ῥωμαίοις.", "st": "Flam. 6.1"}, {"sp": "N", "t": "Φιλίππου δὲ πρέσβεις πέμψαντος εἰς Ῥώμην ἀπέστειλε καὶ ὁ Τίτος παρ’ αὑτοῦ τοὺς πράξοντας ὅπως ἐπιψηφίσηται ἡ σύγκλητος χρόνον αὐτῷ τοῦ πολέμου μένοντος, εἰ δὲ μή, δι’ ἐκείνου τὴν εἰρήνην γενέσθαι, φιλότιμος γὰρ ὧν ἰσχυρῶς ἐδεδίει πεμφθέντος ἐπὶ τὸν πόλεμον ἑτέρου στρατηγοῦ τὴν δόξαν ἀφαιρεθῆναι. διαπραξαμένων δὲ τῶν φίλων αὐτῷ μήτε τὸν Φίλιππον ὧν ἔχρῃζε τυχεῖν καὶ τοῦ πολέμου τὴν ἡγεμονίαν ἐκείνῳ φυλαχθῆναι, δεξάμενος τὸ δόγμα καὶ ταῖς ἐλπίσιν ἐπαρθείς εὐθὺς εἰς Θετταλίαν ἐπὶ τὸν Φιλίππου πόλεμον ὥρμησεν, ὑπὲρ ἑξακισχιλίους καὶ δισμυρίους ἔχων στρατιώτας, ὧν Αἰτωλοὶ πεζοὺς ἑξακισχιλίους καὶ ἱππεῖς τετρακοσίους παρεῖχον. ἦν δὲ καὶ τοῦ Φιλίππου τὸ στράτευμα τῷ πλήθει παραπλήσιον.", "st": "Flam. 7.1"}, {"sp": "N", "t": "ἐπεὶ δὲ βαδίζοντες ἐπ’ ἀλλήλους καὶ γενόμενοι περὶ τὴν Σκοτοῦσαν ἐνταῦθα διακινδυνεύειν ἔμελλον, οὐχ, ὅπερ εἰκὸς ἦν, πρὸς δέους ἔλαβον οἱ στρατοὶ τὴν ἀλλήλων γειτνίασιν, ἀλλὰ καὶ μᾶλλον ὁρμῆς καὶ φιλοτιμίας ἐπληροῦντο, Ῥωμαῖοι μὲν, εἰ Μακεδόνων κρατήσουσιν, ὧν ὄνομα δι’ Ἀλέξανδρον ἀλκῆς καὶ δυνάμεως πλεῖστον ἦν παρ’ αὐτοῖς, Μακεδόνες δὲ Ῥωμαίους Περσῶν ἡγούμενοι διαφέρειν ἤλπιζον, εἰ περιγένοιντο, λαμπρότερον ἀποδείξειν Ἀλεξάνδρου Φίλιππον. ὁ μὲν οὖν Τίτος παρεκάλει τοὺς στρατιώτας ἄνδρας ἀγαθοὺς γενέσθαι καὶ προθύμους, ὡς ἐν τῷ καλλίστῳ θεάτρῳ τῇ Ἑλλάδι μέλλοντας ἀγωνίζεσθαι πρὸς τοὺς ἀρίστους τῶν ἀνταγωνιστῶν ὁ δὲ Φίλιππος, εἴτε ἀπὸ τύχης εἴτε ὑπὸ σπουδῆς παρὰ τὸν καιρὸν ἀγνοήσας, ἦν γάρ τι πολυάνδριον ὑψηλὸν ἔξω τοῦ χάρακος, ἐπὶ τοῦτο προβάς ἤρξατο μὲν, οἷα πρὸ μάχης φιλεῖ, διαλέγεσθαι καὶ παρορμᾶν, ἀθυμίας δὲ δεινῆς πρὸς τὸν οἰωνὸν ἐμπεσούσης διαταραχθεὶς ἐπέσχε τὴν ἡμέραν ἐκείνην.", "st": "Flam. 7.3"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ περὶ τὸν ὄρθρον, ἐκ μαλακῆς καὶ νοτίου νυκτὸς, εἰς ὁμίχλην τῶν νεφῶν τρεπομένων, ἀνεπίμπλατο ζόφου βαθέος πᾶν τὸ πεδίον, καὶ κατῄει παχὺς ἐκ τῶν ἄκρων ἀὴρ εἰς τὸ μεταξὺ τῶν στρατοπέδων, εὐθὺς ἀρχομένης ἡμέρας ἀποκρύπτων τοὺς τόπους, οἱ δὲ ὑπ’ ἀμφοτέρων ἀποσταλέντες ἐφεδρείας ἕνεκα καὶ κατασκοπῆς ἐν πάνυ βραχεῖ περιπεσόντες ἀλλήλοις ἐμάχοντο περὶ τὰς καλουμένας Κυνὸς κεφαλάς, αἳ λόφων οὖσαι πυκνῶν καὶ παραλλήλων ἄκραι λεπταὶ δι’ ὁμοιότητα τὸν σχήματος οὕτως ὠνομάσθησαν. γενομένων δὲ οἷον εἰκὸς ἐν τόποις σκληροῖς μεταβολῶν κατὰ τὰς φυγὰς καὶ διώξεις, ἑκάτεροι τοῖς πονοῦσιν ἀεὶ καὶ ὑποχωροῦσιν ἐπιπέμποντες βοήθειαν ἐκ τῶν στρατοπέδων, καὶ ἤδη τοῦ ἀέρος ἀνακαθαιρομένου καθορῶντες τὰ γινόμενα πανστρατιᾷ συνέβαλον.", "st": "Flam. 8.1"}, {"sp": "N", "t": "τῷ μὲν οὖν δεξιῷ περιῆν ὁ Φίλιππος, ἐκ τόπων καταφερῶν ὅχην ἐπερείσας τὴν φάλαγγα τοῖς Ῥωμαίοις, τὸ βάρος τοῦ συνασπισμοῦ καὶ τὴν τραχύτητα τῆς προβολῆς τῶν σαρισῶν οὐχ ὑπομεινάντων· τοῦ δ’ εὐωνύμου διασπασμὸν ἀνὰ τοὺς λόφους καὶ περίκλασιν λαμβάνοντος, ὁ Τίτος, τὸ μὲν ἡττώμενον ἀπογνούς, πρὸς δὲ θάτερον ὀξέως παρελάσας, προσέβαλε τοῖς Μακεδόσι συστῆναι μὲν εἰς φάλαγγα καὶ πυκνῶσαι τὴν τάξιν εἰς βάθος, ἥπερ ἦν ἀλκὴ τῆς ἐκείνων δυνάμεως, κωλυομένοις διά τὴν ἀνωμαλίαν καὶ τραχύτητα τῶν χωρίων, πρὸς δὲ τὸ κατ’ ἄνδρα συμπλέκεσθαι βαρεῖ καὶ δυσέργῳ χρωμένοις ὁπλισμῷ. ζῴῳ γὰρ ἡ φάλαγξ ἔοικεν ἀμάχῳ τὴν ἰσχύν, ἕως ἕν ἐστι σῶμα καὶ τηρεῖ τὸν συνασπισμὸν ἕν τάξει μιᾷ. διαλυθείσης δὲ καὶ τὴν καθ’ ἕνα ῥώμην ἀπόλλυσι τῶν μαχομένων ἕκαστος διά τε τὸν τρόπον τῆς ὁπλίσεως καὶ ὅτι παντὸς ὅλου τοῖς παρ’ ἀλλήλων μέρεσι μᾶλλον ἢ δι’ αὑτὸν ἰσχύει, τραπομένων δὲ τούτων οἱ μὲν ἐδίωκον τοὺς φεύγοντας, οἱ δὲ τοὺς μαχομένους τῶν Μακεδόνων παρεκδραμόντες ἐκ πλαγίων ἔκτεινον, ὥστε ταχὺ καὶ τοὺς νικῶντας περισπᾶσθαι καὶ φεύγειν τὰ ὅπλα καταβάλλοντας. ἔπεσον μὲν οὖν ὀκτακισχιλίων οὐκ ἐλάττους, ἑάλωσαν δὲ περὶ πεντακισχιλίους. τοῦ δὲ τὸν Φίλιππον ἀσφαλῶς ἀπελθεῖν τὴν αἰτίαν ἔλαβον Αἰτωλοί, περὶ ἁρπαγὴν γενόμενοι καὶ πόρθησιν τοῦ χάρακος ἔτι τῶν Ῥωμαίων διωκόντων, ὥστε μηθὲν εὑρεῖν ἐκείνους ἐπανελθόντας.", "st": "Flam. 8.3"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ἐγένοντο λοιδορίαι καὶ διαφοραὶ πρὸς ἀλλήλους αὐτοῖς· ἐκ δὲ τούτων μᾶλλον ἀεὶ τὸν Τίτον ἐλύπουν ἑαυτοῖς ἀνατιθέντες τὸ νίκημα καὶ τῇ φήμῃ προκαταλαμβάνοντες τοὺς Ἕλληνας, ὥστε καὶ γράφεσθαι καὶ ᾄδεσθαι προτέρους ἐκείνους ὑπὸ ποιητῶν καὶ ἰδιωτῶν ὑμνούντων τὸ ἔργον. ὧν μάλιστα διὰ στόματος ἦν τουτὶ τὸ ἐπίγραμμα·", "st": "Flam. 9.1"}, {"sp": "N", "t": "Ἄκλαυστοι καὶ ἄθαπτοι, ὁδοιπόρε, τῷδ’ ἐπὶ νώτῳ<br>Θεσσαλίης τρισσαὶ κείμεθα μυριάδες,<br>Αἰτωλῶν δμηθέντες ὑπ’ Ἄρεος ἠδὲ Λατίνων,<br>οὓς Τίτος εὐρείης ἤγαγ’ ἀπ’ Ἰταλίης,<br>Ἠμαθίῃ μέγα πῆμα. τὸ δὲ θρασὺ κεῖνο Φιλίππου<br>πνεῦμα θοῶν ἐλάφων ᾤχετ’ ἐλαφρότερον.", "st": "Flam. 9.1b"}, {"sp": "N", "t": "τοῦτο ἐποίησε μὲν Ἀλκαῖος ἐφυβρίζων Φιλίππῳ καὶ τὸν ἀριθμὸν τῶν ἀποθανόντων ἐπιψευσάμενος, λεγόμενον δὲ πολλαχοῦ καὶ ὑπὸ πολλῶν μᾶλλον ἠνία τὸν Τίτον ἢ τὸν Φίλιππον. ὁ μὲν γὰρ ἀντικωμῳδῶν τὸν Ἀλκαῖον τῷ ἐλεγείῳ παρέβαλεν", "st": "Flam. 9.3"}, {"sp": "N", "t": "ἄφλοιος καὶ ἄφυλλος, ὁδοιπόρε, τῷδ’ ἐπὶ νώτῳ<br>Ἀλκαίῳ σταυρὸς πήγνυται ἠλίβατος·", "st": "Flam. 9.3b"}, {"sp": "N", "t": "τὸν δὲ Τίτον φιλοτιμούμενον πρὸς τοὺς Ἕλληνας οὐ μετρίως παρώξυνε τὰ τοιαῦτα, διὸ καὶ τὰ ὑπόλοιπα τῶν πραγμάτων ἔπραττε καθ’ ἑαυτόν, ἐλάχιστα φροντίζων τῶν Αἰτωλῶν. οἱ δὲ ἤχθοντο, καὶ προσδεξαμένου λόγους αὐτοῦ καὶ πρεσβείαν ἐπὶ συμβάσεσι παρὰ τοῦ Μακεδόνος, τοῦτο ἐκεῖνοι περιϊόντες ἐπὶ τὰς ἄλλας πόλεις ἐβόων, πωλεῖσθαι τὴν εἰρήνην Φιλίππῳ, παρὸν ἐκκόψαι τὸν πόλεμον ἄρδην καὶ ἀνελεῖν ἀρχὴν ὑφ’ ἧς πρώτης ἐδουλώθη τὸ Ἑλληνικόν. ταῦτα τῶν Αἰτωλῶν λεγόντων καὶ διαταραττόντων τοὺς συμμάχους, αὐτὸς ὁ Φίλιππος ἐλθὼν πρὸς τὰς διαλύσεις ἀνεῖλε τὴν ὑποψίαν, ἐπιτρέψας τῷ Τίτῳ καὶ Ῥωμαίοις τὰ καθ’ αὑτόν, καὶ οὕτω καταλύεται τὸν πόλεμον ὁ Τίτος· καὶ τὴν μὲν Μακεδονικὴν ἀπέδωκεν αὐτῷ βασιλείαν, τῆς δὲ Ἑλλάδος προσέταζεν ἀποστῆναι, χιλίοις δὲ ταλάντοις ἐζημίωσε, τὰς δὲ ναῦς πάσας παρείλετο πλὴν δέκα, τῶν δὲ παίδων τὸν ἕτερον, Δημήτριον, ὁμηρεύσοντα λαβὼν εἰς Ῥώμην ἀπέστειλεν, ἄριστα τῷ καιρῷ χρησάμενος καὶ προλαβὼν τὸ μέλλον.", "st": "Flam. 9.4"}, {"sp": "N", "t": "Ἀννίβου γὰρ τοῦ Λίβυος, ἀνδρὸς ἐχθίστου τε Ῥωμαίοις καὶ φυγάδος, ἤδη τότε πρὸς Ἀντίοχον ἥκοντος τὸν βασιλέα καὶ παροξύνοντος αὐτὸν εἰς τὸ πρόσθεν προϊέναι τῇ τύχῃ τῆς δυνάμεως εὐροούσης, ἤδη καὶ καθ’ ἑαυτὸν ὑπὸ πραγμάτων μεγάλων, ἃ κατεργασάμενος μέγας ἐπωνομάσθη, πρὸς τὴν ἁπάντων ἡγεμονίαν ἀποβλέποντα, μάλιστα δὲ κατὰ Ῥωμαίων ἀνιστάμενον, εἰ μὴ τοῦτο προϊδὼν ὁ Τίτος ἐμφρόνως ἐνέδωκε πρὸς τὰς διαλύσεις, ἀλλὰ τὸν Φιλιππικὸν ὁ Ἀντιοχικὸς κατειλήφει πόλεμος ἐν τῇ Ἑλλάδι, καὶ συνέστησαν ὑπ’ αἰτιῶν ἀμφότεροι κοινῶν οἱ μέγιστοι τῶν τότε καὶ δυνατώτατοι βασιλέων ἐπὶ τὴν Ῥώμην, ἔσχεν ἂν ἀγῶνας ἐξ ὑπαρχῆς καὶ κινδύνους τῶν πρὸς Ἀννίβαν οὐκ ἐλάττους. νῦν δὲ τῶν πολέμων μέσην κατὰ καιρὸν ἐμβαλὼν τὴν εἰρήνην ὁ Τίτος, καὶ πρὶν ἄρξασθαι τὸν μέλλοντα διακόψας τὸν παρόντα, τοῦ μὲν τὴν ἐσχάτην ἐλπίδα, τοῦ δὲ τὴν πρώτην ὑφεῖλεν.", "st": "Flam. 9.6"}, {"sp": "N", "t": "ἐπεὶ δὲ οἱ δέκα πρέσβεις, οὓς ἡ σύγκλητος ἔπεμψε τῷ Τίτῳ, συνεβούλευον τοὺς μὲν ἄλλους Ἕλληνας ἐλευθεροῦν, Κόρινθον δὲ καὶ Χαλκίδα καὶ Δημητριάδα διατηρεῖν ἐμφρούρους ἕνεκα τῆς πρὸς Ἀντίοχον ἀσφαλείας, ἐνταῦθα δὴ ταῖς κατηγορίαις λαμπροὶ λαμπρῶς τὰς πόλεις ἀνερρήγνυσαν Αἰτωλοί, τὸν μὲν Τίτον κελεύοντες τὰς πέδας τῆς Ἑλλάδος λύειν (οὕτω γὰρ ὁ Φίλιππος εἰώθει τὰς προειρημένας πόλεις ὀνομάζειν), τοὺς δὲ Ἕλληνας ἐρωτῶντες εἰ κλοιὸν ἔχοντες βαρύτερον μὲν, λειότερον δὲ τοῦ πάλαι τὸν νῦν, χαίρουσι, καὶ θαυμάζουσι τὸν Τίτον ὡς εὐεργέτην, ὅτι τοῦ ποδὸς λύσας τὴν Ἑλλάδα τοῦ τραχήλου δέδεκεν. ἐφ’ οἷς ἀχθόμενος ὁ Τίτος καὶ βαρέως φέρων, καὶ δεόμενος τοῦ συνεδρίου, τέλος ἐξέπεισε καὶ ταύτας τὰς πόλεις ἀνεῖναι τῆς φρουρᾶς, ὅπως ὁλόκληρος ἡ χάρις ὑπάρξῃ παρ’ αὐτοῦ τοῖς Ἕλλησιν.", "st": "Flam. 10.1"}, {"sp": "N", "t": "Ἰσθμίων οὖν ἀγομένων πλῆθος μὲν ἀνθρώπων ἐν τῷ σταδίῳ καθῆστο τὸν γυμνικὸν ἀγῶνα θεωμένων, οἷα δὴ διὰ χρόνων πεπαυμένης μὲν πολέμων τῆς Ἑλλάδος ἐπ’ ἐλπίσιν ἐλευθερίας, σαφεῖ δὲ εἰρήνῃ πανηγυριζούσης τῇ σάλπιγγι δὲ σιωπῆς εἰς ἅπαντας διαδοθείσης, προελθὼν εἰς μέσον ὁ κῆρυξ ἀνεῖπεν ὅτι Ῥωμαίων ἡ σύγκλητος καὶ Τίτος Κοΐντιος στρατηγὸς ὕπατος καταπολεμήσαντες βασιλέα Φίλιππον καὶ Μακεδόνας, ἀφιᾶσιν ἀφρουρήτους καὶ ἐλευθέρους καὶ ἀφορολογήτους, νόμοις χρωμένους τοῖς πατρίοις, Κορινθίους, Λοκρούς, Φωκεῖς, Εὐβοέας, Ἀχαιοὺς Φθιώτας, Μάγνητας, Θετταλούς, Περραιβούς. τὸ μὲν οὖν πρῶτον οὐ πάνυ πάντες οὐδὲ σαφῶς ἐπήκουσαν, ἀλλ’ ἀνώμαλος καὶ θορυβώδης κίνησις ἦν ἐν τῷ σταδίῳ θαυμαζόντων καὶ διαπυνθανομένων καὶ πάλιν ἀνειπεῖν κελευόντων· ὡς δὲ αὖθις ἡσυχίας γενομένης ἀναγαγὼν ὁ κῆρυξ τὴν φωνὴν προθυμότερον εἰς ἅπαντας ἐγεγώνει καὶ διῆλθε τὸ κήρυγμα, κραυγὴ μὲν ἄπιστος τὸ μέγεθος διὰ χαρὰν ἐχώρει μέχρι θαλάττης, ὀρθὸν δὲ ἀνειστήκει τὸ θέατρον, οὐδεὶς δὲ λόγος ἦν τῶν ἀγωνιζομένων, ἔσπευδον δὲ πάντες ἀναπηδῆσαι καὶ δεξιώσασθαι καὶ προσειπεῖν τὸν σωτῆρα τῆς Ἑλλάδος καὶ πρόμαχον.", "st": "Flam. 10.3"}, {"sp": "N", "t": "τὸ δὲ πολλάκις λεγόμενον εἰς ὑπερβολὴν τῆς φωνῆς καὶ μέγεθος ὤφθη τότε. κόρακες γὰρ ὑπερπετόμενοι κατὰ τύχην ἔπεσον εἰς τὸ στάδιον. αἰτία δὲ ἡ τοῦ ἀέρος ῥῆξις· ὅταν γὰρ ἡ φωνὴ πολλὴ καὶ μεγάλη φέρηται, διασπώμενος ὑπ’ αὐτῆς οὐκ ἀντερείδει τοῖς πετομένοις, ἀλλ’ ὀλίσθημα ποιεῖ καθάπερ κενεμβατοῦσιν, εἰ μὴ νὴ Δία πληγῇ τινι μᾶλλον ὡς ὑπὸ βέλους διελαυνόμενα πίπτει καὶ ἀποθνῄσκει, δύναται δὲ καὶ περιδίνησις εἶναι τοῦ ἀέρος, οἷον ἑλιγμὸν ἐν πελάγει καὶ παλιρρύμην τοῦ σάλου διὰ μέγεθος λαμβάνοντος.", "st": "Flam. 10.6"}, {"sp": "N", "t": "ὁ δ’ οὖν Τίτος, εἰ μὴ τάχιστα τῆς θέας διαλυθείσης ὑπιδόμενος τὴν φορὰν τοῦ πλήθους καὶ τὸν δρόμον ἐξέκλινεν, οὐκ ἂν ἐδόκει περιγενέσθαι τοσούτων ὁμοῦ καὶ πάντοθεν αὐτῷ περιχεομένων. ὡς δ’ ἀπέκαμον περὶ τὴν σκηνὴν αὐτοῦ βοῶντες ἤδη νυκτὸς οὔσης, αὖθις οὕστινας ἴδοιεν ἢ φίλους ἢ πολίτας ἀσπαζόμενοι καὶ περιπλεκόμενοι, πρὸς δεῖπνα καὶ πότους ἐτρέποντο μετ’ ἀλλήλων. ἐν ᾧ καὶ μᾶλλον, ὡς εἰκὸς, ἡδομένοις ἐπῄει λογίζεσθαι καὶ διαλέγεσθαι περὶ τῆς Ἑλλάδος, ὅσους πολεμήσασα πολέμους διὰ τὴν ἐλευθερίαν οὔπω τύχοι βεβαιότερον οὐδὲ ἥδιον αὐτῆς, ἑτέρων προαγωνισαμένων ὀλίγου δεῖν ἀναίμακτος αὐτὴ καὶ ἀπενθὴς φερομένη τὸ κάλλιστον καὶ περιμαχητότατον ἆθλον. ἦν δ’ ἄρα σπάνιον μὲν ἀνδρεία καὶ φρόνησις ἐν ἀνθρώποις, σπανιώτατον δὲ τῶν ἄλλων ἀγαθῶν ὁ δίκαιος. οἱ γὰρ Ἀγησίλαοι καὶ Λύσανδροι καὶ οἱ Νικίαι καὶ οἱ Ἀλκιβιάδαι πολέμους μὲν εὖ διέπειν καὶ μάχας νικᾶν κατά τε γῆν καὶ θάλασσαν ἄρχοντες ἠπίσταντο, χρῆσθαι δὲ πρὸς χάριν εὐγενῆ καὶ τὸ καλὸν οἷς κατώρθουν οὐκ ἔγνωσαν, ἀλλ’ εἰ τὸ Μαραθώνιόν τις ἔργον ἀφέλοι καὶ τὴν ἐν Σαλαμῖνι ναυμαχίαν καὶ Πλαταιὰς καὶ Θερμοπύλας καὶ τὰ πρὸς Εὐρυμέδοντι καὶ τὰ περὶ Κύπρον Κίμωνος ἔργα, πάσας τὰς μάχας ἡ Ἑλλὰς ἐπὶ δουλείᾳ μεμάχηται πρὸς αὑτήν, καὶ πᾶν τρόπαιον αὐτῆς συμφορὰ καὶ ὄνειδος ἐπ’ αὐτὴν ἕστηκε, τὰ πλεῖστα κακίᾳ καὶ φιλονεικίᾳ τῶν ἡγουμένων περιτραπείσης. ἀλλόφυλοι δὲ ἄνδρες, ἐναύσματα μικρὰ καὶ γλίσχρα κοινωνήματα παλαιοῦ γένους ἔχειν δοκοῦντες, ἀφ’ ὧν καὶ λόγῳ τι καὶ γνώμῃ τῶν χρησίμων ὑπάρξαι τῇ Ἑλλάδι θαυμαστὸν ἦν, οὗτοι τοῖς μεγίστοις κινδύνοις καὶ πόνοις ἐξελόμενοι τὴν Ἑλλάδα δεσποτῶν χαλεπῶν καὶ τυράννων ἐλευθεροῦσι.", "st": "Flam. 11.1"}, {"sp": "N", "t": "ταῦτα δὴ τοὺς Ἕλληνας ὑπῄει· καὶ τὰ τῶν ἔργων ὁμολογοῦντα τοῖς κηρύγμασιν. ἅμα γὰρ ἐξέπεμπεν ὁ Τίτος Λέντλον μὲν εἰς Ἀσίαν Βαργυλιήτας ἐλευθερώσοντα, Στερτίνιον δὲ εἰς Θρᾴκην τὰς αὐτόθι πόλεις καὶ νήσους ἀπαλλάξοντα τῶν Φιλίππου φρουρῶν. Πόπλιος δὲ Οὐίλλιος ἔπλει διαλεξόμενος Ἀντιόχῳ περὶ τῆς τῶν ὑπ’ αὐτὸν Ἑλλήνων ἐλευθερίας. αὐτὸς δὲ ὁ Τίτος εἰς Χαλκίδα παρελθών, εἶτα πλεύσας ἐκεῖθεν ἐπὶ Μαγνησίαν, ἐξῆγε τὰς φρουρὰς καὶ τὰς πολιτείας ἀπεδίδου τοῖς δήμοις. ἀγωνοθέτης δὲ Νεμείων ἀποδειχθεὶς ἐν Ἄργει τήν τε πανήγυριν ἄριστα διέθηκε, καὶ πάλιν ἐκεῖ τοῖς Ἕλλησι τήν ἐλευθερίαν ὑπὸ κήρυκος ἀνεῖπεν. ἐπιφοιτῶν τε ταῖς πόλεσιν εὐνομίαν ἅμα καὶ δίκην πολλὴν ὁμόνοιάν τε καὶ φιλοφροσύνην πρὸς ἀλλήλους παρεῖχε, καταπαύων μὲν τὰς στάσεις, κατάγων δὲ τὰς φυγάς, ἀγαλλόμενος δὲ τῷ πείθειν καὶ διαλλάσσειν τοὺς Ἕλληνας οὐχ ἧττον ἢ τῷ κεκρατηκέναι τῶν Μακεδόνων, ὥστε μικρότατον ἤδη τήν ἐλευθερίαν δοκεῖν ὧν εὐεργετοῦντο.", "st": "Flam. 12.1"}, {"sp": "N", "t": "Ξενοκράτην μὲν οὖν τὸν φιλόσοφον, ὅτε Λυκοῦργος αὐτὸν ὁ ῥήτωρ ὑπὸ τῶν τελωνῶν ἀγόμενον πρὸς τὸ μετοίκιον ἀφείλετο καὶ τοῖς ἄγουσιν ἐπέθηκε δίκην τῆς ἀσελγείας, λέγεται τοῖς παισὶν ἀπαντήσαντα τοῦ Λυκούργου, καλήν γε ὑμῶν, ὦ παῖδες, φάναι, τῷ πατρὶ χάριν ἀποδίδωμι· πάντες γὰρ αὐτὸν ἐπαινοῦσιν ἐφ’ οἷς ἔπραξε, Τίτῳ δὲ καὶ Ῥωμαίοις ὧν τοὺς Ἕλληνας εὐεργέτησαν οὐκ εἰς ἐπαίνους μόνον, ἀλλὰ καὶ πίστιν ἐν πᾶσιν ἀνθρώποις καὶ δύναμιν ἡ χάρις ἀπήντα δικαίως. οὐ γὰρ προσδεχόμενοι μόνον τοὺς ἡγεμόνας αὐτῶν, ἀλλὰ καὶ μεταπεμπόμενοι καὶ καλοῦντες ἐνεχείριζον αὑτούς, οὐδὲ δῆμοι καὶ πόλεις, ἀλλὰ καὶ βασιλεῖς ὑφ’ ἑτέρων ἀδικούμενοι βασιλέων κατέφευγον εἰς τὰς ἐκείνων χεῖρας, ὥστε ἐν βραχεῖ χρόνῳ, τάχα που καὶ θεοῦ συνεφαπτομένου, πάντ’ αὐτοῖς ὑπήκοα γενέσθαι, καὶ αὐτὸς δὲ μέγιστον ἐφρόνησεν ἐπὶ τῇ τῆς Ἑλλάδος ἐλευθερώσει. ἀνατιθεὶς γὰρ εἰς Δελφοὺς ἀσπίδας ἀργυρᾶς καὶ τὸν ἑαυτοῦ θυρεόν ἐπέγραψε·", "st": "Flam. 12.4"}, {"sp": "N", "t": "Ζηνὸς ἰὼ κραιπναῖσι γεγαθότες ἱπποσύναισι<br>κοῦροι, ἰὼ Σπάρτας Τυνδαρίδαι βασιλεῖς,<br>Αἰνεάδας Τίτος ὔμμιν ὑπέρτατον ὤπασε δῶρον.<br>Ἑλλήνων τεύξας παισὶν ἐλευθερίαν.", "st": "Flam. 12.4b"}, {"sp": "N", "t": "ἀνέθηκε δὲ καὶ χρυσοῦν τῷ Ἀπόλλωνι στέφανον ἐπιγράψας.", "st": "Flam. 12.7"}, {"sp": "N", "t": "τόνδε τοι ἀμβροσίοισιν ἐπὶ πλοκάμοισιν ἔοικε<br>κεῖσθαι, Λατοΐδα, χρυσοφαῆ στέφανον,<br>ὃν πόρεν Αἰνεαδᾶν ταγὸς μέγας. ἀλλ’,<br>ἑκάεργε,<br>ἀλκᾶς τῷ θείῳ κῦδος ὄπαζε Τίτῳ.", "st": "Flam. 12.7b"}, {"sp": "N", "t": "τῇ δ’ οὖν Κορινθίων πόλει πρὸς τοὺς Ἕλληνας τὸ αὐτὸ δὶς ἤδη συμβέβηκε· καὶ γὰρ Τίτος ἐν Κορίνθῳ τότε καὶ Νέρων αὖθις καθ’ ἡμᾶς ἐν Κορίνθῳ παραπλησίως Ἰσθμίων ἀγομένων τοὺς Ἕλληνας ἐλευθέρους καὶ αὐτονόμους ἀφῆκαν, ὁ μὲν διὰ κήρυκος, ὡς εἴρηται, Νέρων δὲ αὐτὸς ἐπὶ τῆς ἀγορᾶς ἀπὸ βήματος ἐν τῷ πλήθει δημηγορήσας. ἀλλὰ ταῦτα μὲν ὕστερον.", "st": "Flam. 12.8"}, {"sp": "N", "t": "ὁ δὲ Τίτος τότε καλλίστου καὶ δικαιοτάτου τοῦ πρὸς Νάβιν ἀρξάμενος πολέμου, τὸν Λακεδαιμονίων ἐξωλέστατον καὶ παρανομώτατον τύραννον, ἐν τῷ τέλει διεψεύσατο τὰς τῆς Ἑλλάδος ἐλπίδας, ἑλεῖν παρασχὸν οὐκ ἐθελήσας, ἀλλὰ σπεισάμενος καὶ προέμενος τὴν Σπάρτην ἀναξίως δουλεύουσαν, εἴτε δείσας μὴ τοῦ πολέμου μῆκος λαμβάνοντος ἄλλος ἀπὸ Ῥώμης ἐπελθὼν στρατηγὸς ἀνέληται τὴν δόξαν, εἴτε φιλονεικίᾳ καὶ ζηλοτυπίᾳ τῶν Φιλοποίμενος τιμῶν, ὃν ἔν τε τοῖς ἄλλοις ἅπασιν ἄνδρα δεινότατον τῶν Ἑλλήνων ὄντα καὶ περὶ ἐκεῖνον τὸν πόλεμον ἔργα θαυμαστὰ τόλμης καὶ δεινότητος ἀποδειξάμενον ἴσα τῷ Τίτῳ κυδαίνοντες Ἀχαιοὶ καὶ τιμῶντες ἐν τοῖς θεάτροις ἐλύπουν ἐκεῖνον, οὐκ ἀξιοῦντα Ῥωμαίων ὑπάτῳ προπολεμοῦντι τῆς Ἑλλάδος ἄνθρωπον Ἀρκάδα, μικρῶν καὶ ὁμόρων πολέμων στρατηγόν, ὅμοια θαυμάζεσθαι παρ’ αὐτοῖς. οὐ μὴν ἀλλ’ αὐτὸς ὁ Τίτος ὑπὲρ τούτων ἀπελογεῖτο, καταθέσθαι τὸν πόλεμον ὡς ἑώρα σὺν κακῷ μεγάλῳ τῶν ἄλλων Σπαρτιατῶν ἀπολούμενον τὸν τύραννον·", "st": "Flam. 13.1"}, {"sp": "N", "t": "τῶν δὲ Ἀχαιῶν αὐτῷ πολλὰ πρὸς τιμὴν ψηφισαμένων οὐδὲν ἐδόκει πρὸς τὰς εὐεργεσίας ἐξισοῦσθαι πχὴν μιᾶς δωρεᾶς, ἣν ἐκεῖνος ἀντὶ πάντων ἠγάπησεν. ἦν δὲ τοιάδε. Ῥωμαίων οἱ δυστυχήσαντες ἐν τῷ πρὸς Ἀννίβαν πολέμῳ πολλαχοῦ μὲν ὤνιοι γενόμενοι καὶ διασπαρέντες ἐδούλευον· ἐν δὲ τῇ Ἑλλάδι χίλιοι καὶ διακόσιοι τὸ πλῆθος ἦσαν, ἀεὶ μὲν οἰκτροὶ τῆς μεταβολῆς, τότε δὲ καὶ μᾶλλον, ὡς εἰκός, ἐντυγχάνοντες οἱ μὲν υἱοῖς, οἱ δὲ ἀδελφοῖς, οἱ δὲ συνήθεσιν, ἐλευθέροις δοῦλοι καὶ νικῶσιν αἰχμάλωτοι. τούτους ὁ μὲν Τίτος οὐκ ἀφείλετο τῶν κεκτημένων, καίπερ ἀνιώμενος ἐπ’ αὐτοῖς, οἱ δὲ Ἀχαιοὶ λυτρωσάμενοι πέντε μνῶν ἕκαστον ἄνδρα καὶ συναγαγόντες εἰς ταὐτὸ πάντας ἤδη περὶ πλοῦν ὄντι τῷ Τίτῳ παρέδωκαν, ὥστε αὐτὸν εὐφραινόμενον ἀποπλεῖν, ἀπὸ καλῶν ἔργων καλὰς ἀμοιβὰς καὶ πρεπούσας ἀνδρὶ μεγάλῳ καὶ φιλοπολίτῃ κεκομισμένον· ὃ δὴ δοκεῖ πρὸς τὸν θρίαμβον αὐτῷ πάντων ὑπάρξαι λαμπρότατον. οἱ γὰρ ἄνδρες οὗτοι, καθάπερ ἔθος ἐστὶ τοῖς οἰκέταις ὅταν ἐλευθερωθῶσιν, ξύρεσθαί τε τὰς κεφαλὰς καὶ πιλία φορεῖν, ταῦτα δράσαντες αὐτοὶ θριαμβεύοντι τῷ Τίτῳ παρείποντο.", "st": "Flam. 13.4"}, {"sp": "N", "t": "καλλίω δὲ καὶ τὰ λάφυρα πομπευόμενα παρεῖχεν ὄψιν, Ἑλληνικὰ κράνη καὶ πέλται Μακεδονικαὶ καὶ σάρισαι. τό τε τῶν χρημάτων πλῆθος οὐκ ὀλίγον ἦν, ὡς ἀναγράφουσιν οἱ περὶ Τουδιτανὸν ἐν τῷ θριάμβῳ κομισθῆναι χρυσίου μὲν συγκεχωνευμένου λίτρας τρισχιλίας ἑπτακοσίας δεκατρεῖς, ἀργύρου δὲ τετρακισμυρίας τρισχιλίας διακοσίας ἑβδομήκοντα, Φιλιππείους δὲ χρυσοῦς μυρίους τετρακισχιλίους πεντακοσίους δεκατέσσαρας, χωρὶς δὲ τούτων τὰ χίλια τάλαντα Φίλιππος ὤφειλεν. ἀλλὰ ταῦτα μὲν ὕστερον ἐπείσθησαν Ῥωμαῖοι, μάλιστα τοῦ Τίτου συμπράξαντος, ἀφεῖναι τῷ Φιλίππῳ, καὶ σύμμαχον ἐψηφίσαντο, καὶ τὸν υἱὸν ἀπήλλαξαν αὐτῷ τῆς ὁμηρείας.", "st": "Flam. 14.1"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ Ἀντίοχος εἰς τὴν Ἑλλάδα ναυσὶ πολλαῖς καὶ στρατῷ περαιωθεὶς ἀφίστη τὰς πόλεις καὶ διεστασίαζεν, Αἰτωλῶν αὐτῷ συνεπιλαμβανομένων καὶ πάλαι διακειμένων πρὸς τὸν Ῥωμαίων δῆμον ἐχθρῶς καὶ πολεμικῶς, ὑπόθεσιν τοῦ πολέμου καὶ πρόφασιν διδόντων ἐλευθεροῦν τοὺς Ἕλληνας οὐδὲν δεομένους (ἐλεύθεροι γὰρ ἦσαν), ἀλλ’ εὐπρεπεστέρας αἰτίας ἀπορίᾳ τῷ καλλίστῳ τῶν ὀνομάτων χρῆσθαι διδασκόντων, καὶ σφόδρα δείσαντες οἱ Ῥωμαῖοι τὴν ἀνάστασιν καὶ δόξαν αὐτοῦ τῆς δυνάμεως, στρατηγὸν μὲν ὕπατον τοῦ πολέμου Μάνιον Ἀκίλιον κατέπεμψαν, πρεσβευτὴν δὲ Τίτον διὰ τοὺς Ἕλληνας, ὧν τοὺς μὲν εὐθὺς ὀφθεὶς ἐποίησε βεβαιοτέρους, τοὺς δὲ ἀρχομένους νοσεῖν ὥσπερ τι ἐν καιρῷ φάρμακον ἐνδιδοὺς τὴν πρὸς αὑτὸν εὔνοιαν ἔστησε καὶ διεκώλυσεν ἐξαμαρτεῖν. ὀλίγοι δὲ αὑτὸν ἐξέφυγον ἤδη προκατειλημμένοι καὶ διεφθαρμένοι παντάπασιν ὑπὸ τῶν Αἰτωλῶν, οὓς καίπερ ὀργισθεὶς καὶ παροξυνθεὶς ὅμως μετὰ τὴν μάχην περιεποίησεν. Ἀντίοχος γὰρ ἡττηθεὶς ἐν Θερμοπύλαις καὶ φυγὼν εὐθὺς εἰς Ἀσίαν ἀπέπλευσε, Μάνιος δ’ ὁ ὕπατος τοὺς μὲν αὐτὸς ἐπιὼν τῶν Αἰτωλῶν ἐπολιόρκει, τοὺς δὲ τῷ βασιλεῖ Φιλίππῳ συνεχώρησεν ἐξαιρεῖν. ἀγομένων δὲ καὶ φερομένων ὑπὸ τοῦ Μακεδόνος τοῦτο μὲν Δολόπων καὶ Μαγνήτων, τοῦτο δὲ Ἀθαμάνων καὶ Ἀπεραντῶν, αὐτοῦ δὲ τοῦ Μανίου τὴν μὲν Ἡράκλειαν διαπεπορθηκότος, τὴν δὲ Ναύπακτον Αἰτωλῶν ἐχόντων πολιορκοῦντος, οἰκτείρων τοὺς Ἕλληνας ὁ Τίτος διέπλευσεν ἐκ Πελοποννήσου πρὸς τὸν ὕπατον. καὶ πρῶτον μὲν ἐπετίμησεν εἰ νενικηκὼς αὐτὸς τὰ ἔπαθλα τοῦ πολέμου Φίλιππον ἐᾷ φέρεσθαι, καὶ τριβόμενος περὶ μιᾷ πόλει κάθηται δι’ ὀργήν, ἔθνη δὲ οὐκ ὀλίγα καὶ βασιλείας Μακεδόνες αἱροῦσιν. ἔπειτα τῶν πολιορκουμένων, ὡς εἶδον αὑτὸν, ἀπὸ τοῦ τείχους ἀνακαλούντων καὶ χεῖρας ὀρεγόντων καὶ δεομένων, τότε μὲν οὐδὲν εἰπών, ἀλλὰ στραφεὶς καὶ δακρύσας ἀπῆλθεν, ὕστερον δὲ διαλεχθεὶς τῷ Μανίῳ καὶ καταπαύσας τὸν θυμὸν αὐτοῦ διεπράξατο τοῖς Αἰτωλοῖς ἀνοχὰς δοθῆναι, καὶ χρόνον ἐν ᾧ πρεσβεύσαντες εἰς Ῥώμην μετρίου τινὸς τυχεῖν ἀξιώσουσι.", "st": "Flam. 15.1"}, {"sp": "N", "t": "πλεῖστον δὲ ἀγῶνα καὶ πόνον αὐτῷ παρεῖχον αἱ περὶ Χαλκιδέων δεήσεις πρὸς τὸν Μάνιον, ἐν ὀργῇ γεγονότων διὰ τὸν γάμον ὃν παρ’ αὐτῶν ἔγημεν Ἀντίοχος ἤδη τοῦ πολέμου συνεστῶτος, οὐ καθ’ ὥραν οὐδὲ κατὰ καιρόν, ἀλλ’ ἐρασθεὶς ἀνὴρ πρεσβύτερος κόρης, ἣ θυγάτηρ μὲν ἦν Κλεοπτολέμου, καλλίστη δὲ λέγεται παρθένων γενέσθαι. τοῦτο τοὺς Χαλκιδεῖς ἐποίησε βασιλίσαι προθυμότατα καὶ τὴν πόλιν αὐτῷ πρὸς τὸν πόλεμον ὁρμητήριον παρασχεῖν. ἐκεῖνος μὲν οὖν ὡς τάχιστα μετὰ τὴν μάχην φεύγων προσέμιξε τῇ Χαλκίδι, τήν τε κόρην ἀναλαβὼν καὶ τὰ χρήματα καὶ τοὺς φίλους εἰς Ἀσίαν ἀπέπλευσε· τὸν δὲ Μάνιον εὐθὺς ἐπὶ τοὺς Χαλκιδεῖς σὺν ὀργῇ πορευόμενον ὁ Τίτος παρακολουθῶν ἐμάλαττε καὶ παρῃτεῖτο καί τέλος ἔπεισε καὶ κατεπράϋνεν, αὐτοῦ τε καὶ τῶν ἐν τέλει Ῥωμαίων δεόμενος.", "st": "Flam. 16.1"}, {"sp": "N", "t": "οὕτω διασωθέντες οἱ Χαλκιδεῖς τὰ κάλλιστα καὶ μέγιστα τῶν παρ’ αὐτοῖς ἀναθημάτων τῷ Τίτῳ καθιέρωσαν, ὧν ἐπιγραφὰς ἔστι τοιαύτας ἄχρι νῦν ὁρᾶν ὁ δῆμος Τίτῳ καὶ Ἡρακλεῖ τὸ γυμνάσιον, ἑτέρωθι δὲ πάλιν, ὁ δῆμος Τίτῳ καὶ Ἀπόλλωνι τὸ Δελφίνιον. ἔτι δὲ καὶ καθ’ ἡμᾶς ἱερεὺς χειροτονητὸς ἀπεδείκνυτο Τίτου, καὶ θύσαντες αὐτῷ τῶν σπονδῶν γενομένων ᾄδουσι παιᾶνα πεποιημένον, οὗ τἆλλα διὰ μῆκος ἡμεῖς παρέντες ἀνεγράψαμεν ἃ παυόμενοι τῆς ᾠδῆς λέγουσι·", "st": "Flam. 16.3"}, {"sp": "N", "t": "πίστιν δὲ Ῥωμαίων σέβομεν,<br>τὰν μεγαλευκτοτάταν ὅρκοις φυλάσσειν·<br>μέλπετε κοῦραι,<br>Ζῆνα μέγαν Ῥώμαν τε Τίτον θ’ ἅμα Ῥωμαίων<br>τε πίστιν<br>ἰήϊε Παιάν, ὦ Τίτε σῶτερ.", "st": "Flam. 16.3b"}, {"sp": "N", "t": "ἦσαν δὲ καὶ παρά τῶν ἄλλων Ἑλλήνων τιμαὶ πρέπουσαι, καὶ τὸ τὰς τιμὰς ἀληθινὰς ποιοῦν, εὔνοια θαυμαστὴ δι’ ἐπιείκειαν ἤθους, καὶ γὰρ εἴ τισιν ἐκ πραγμάτων ἢ φιλοτιμίας ἕνεκα, καθάπερ Φιλοποίμενι καὶ πάλιν Διοφάνει στρατηγοῦντι τῶν Ἀχαιῶν, προσέκρουσεν, οὐκ ἦν βαρὺς οὐδ’ εἰς ἔργα διατείνων ὁ θυμός, ἀλλ’ ἐν λόγῳ παρρησίαν τινὰ πολιτικὴν ἔχοντι παυόμενος. πικρὸς μὲν οὖν οὐδενί, πολλοῖς δὲ ὀξὺς ἐδόκει καὶ κοῦφος εἶναι τὴν φύσιν, ἄλλως δὲ συγγενέσθαι πάντων ἥδιστος καὶ εἰπεῖν ἐπίχαρις μετὰ δεινότητος. Ἀχαιούς μὲν γὰρ σφετεριζομένους τὴν Ζακυνθίων νῆσον ἀποτρέπων ἔφη κινδυνεύσειν, ἂν ὥσπερ αἱ χελῶναι πορρωτέρω τὴν κεφαλὴν τῆς Πελοποννήσου προτείνωσι· Φιλίππου δέ, ὁπηνίκα περὶ σπονδῶν καὶ εἰρήνης τὸ πρῶτον εἰς λόγους συνῄεσαν, εἰπόντος μετὰ πολλῶν ἥκειν ἐκεῖνον, αὑτὸν δὲ μόνον, ὑπολαβὼν ὁ Τίτος, αὑτὸν γὰρ, ἔφη, μόνον ἐποίησας ἀποκτείνας τοὺς φίλους καὶ συγγενεῖς. ἐπεὶ δὲ Δεινοκράτης ὁ Μεσσήνιος ἐν Ῥώμῃ παρά πότον μεθυσθεὶς ὠρχήσατο λαβὼν ἱμάτιον γυναικεῖον, τῇ δ’ ὑστεραίᾳ τὸν Τίτον ἠξίου βοηθεῖν αὐτῷ διανοουμένῳ τὴν Μεσσήνην ἀφιστάναι τῶν Ἀχαιῶν, ταῦτα μὲν ἔφη σκέψεσθαι, θαυμάζειν δὲ ἐκεῖνον, εἰ τηλικαύταις ἐπικεχειρηκὼς πράξεσιν ὀρχεῖσθαι δύναται παρά πότον καὶ ᾄδειν. πρὸς δὲ τοὺς Ἀχαιούς τῶν παρά Ἀντιόχου πρέσβεων πλῆθος τι τῆς βασιλικῆς στρατιᾶς καταλεγόντων καὶ καταριθμουμένων πολλὰς προσηγορίας, ὁ Τίτος ἔφη δειπνοῦντος αὐτοῦ παρά τῷ ξένῳ καὶ μεμφομένου τὸ πλῆθος τῶν κρεῶν καὶ θαυμάζοντος πόθεν οὕτω ποικίλης ἀγορᾶς εὐπόρησεν, εἰπεῖν τὸν ξένον, ὡς ὕεια πάντα ἐστί τῇ σκευασίᾳ, διαφέροντα καὶ τοῖς ἡδύσμασι. μὴ τοίνυν, ἔφη, μηδὲ ὑμεῖς, ὦ ἄνδρες Ἀχαιοὶ, θαυμάζετε τὴν Ἀντιόχου δύναμιν λογχοφόρους καὶ ξυστοφόρους καὶ πεζεταίρους ἀκούοντες πάντες γὰρ οὗτοι Σύροι εἰσίν ὁπλαρίοις διαφέροντες.", "st": "Flam. 17.1"}, {"sp": "N", "t": "μετὰ δὲ τὰς Ἑλληνικὰς πράξεις καὶ τὸν Ἀντιοχικὸν πόλεμον ἀπεδείχθη τιμητής, ἥτις ἐστὶν ἀρχὴ μεγίστη καὶ τρόπον τινὰ τῆς πολιτείας ἐπιτελείωσις. καὶ συνῆρχε μὲν αὐτῷ Μαρκέλλου τοῦ πεντάκις ὑπατεύσαντος υἱός, ἐξέβαλον δὲ τῆς βουλῆς τῶν οὐκ ἄγαν ἐπιφανῶν τέσσαρας, προσεδέξαντο δὲ πολίτας ἀπογραφομένους πάντας, ὅσοι γονέων ἐλευθέρων ἦσαν, ἀναγκασθέντες ὑπὸ τοῦ δημάρχου Τερεντίου Κουλέωνος, ὃς ἐπηρεάζων τοῖς ἀριστοκρατικοῖς ἔπεισε τὸν δῆμον ταῦτα ψηφίσασθαι.", "st": "Flam. 18.1"}, {"sp": "N", "t": "τῶν δὲ γνωριμωτάτων κατ’ αὑτὸν ἀνδρῶν καὶ μεγίστων ἐν τῇ πόλει διαφερομένων πρὸς ἀλλήλους, Ἀφρικανοῦ Σκηπίωνος καὶ Μάρκου Κάτωνος, τὸν μὲν προέγραψε τῆς βουλῆς, ὡς ἄριστον ἄνδρα καὶ πρῶτον, Κάτωνι δὲ εἰς ἔχθραν ἦλθε συμφορᾷ τοιαύτῃ χρησάμενος. ἀδελφὸς ἦν Τίτῳ Λεύκιος Φλαμινῖνος, οὔτε τὰ ἄλλα προσεοικὼς ἐκείνῳ τὴν φύσιν ἔν τε ταῖς ἡδοναῖς ἀνελεύθερος δεινῶς καὶ ὀλιγωρότατος τοῦ πρέποντος. τούτῳ συνῆν μειρακίσκος ἐρώμενος, ὃν καὶ στρατιᾶς ἄρχων ἐπήγετο καὶ διέπων ἐπαρχίας εἶχεν ἀεὶ περὶ αὑτόν, ἔν οὖν πότῳ τινὶ θρυπτόμενος πρὸς τὸν Λεύκιον οὕτως ἔφη σφόδρα φιλεῖν αὐτόν ὥστε θέαν μονομάχων ἀπολιπεῖν οὔπω γεγονὼς ἀνθρώπου φονευομένου θεατής, τὸ πρὸς ἐκεῖνον ἡδὺ τοῦ πρὸς αὑτὸν ἐν πλείονι λόγῳ θέμενος. ὁ δὲ Λεύκιος ἡσθείς οὐδὲν, ἔφη, δεινόν· ἰάσομαι γὰρ ἐγώ σου τὴν ἐπιθυμίαν. καὶ κελεύσας ἕνα τῶν καταδίκων ἐκ τοῦ δεσμωτηρίου προαχθῆναι, καὶ τὸν ὑπηρέτην μεταπεμψάμενος, ἐν τῷ συμποσίῳ προσέταξεν ἀποκόψαι τοῦ ἀνθρώπου τὸν τράχηλον. Οὐαλλέριος δὲ Ἀντίας οὐκ ἐρωμένῳ φησίν, ἀλλ’ ἐρωμένῃ τοῦτο χαρίσασθαι τὸν Λεύκιον. ὁ δὲ Λίβιος ἐν λόγῳ Κάτωνος αὐτοῦ γεγράφθαι φησίν, ὡς Γαλάτην αὐτόμολον ἐλθόντα μετὰ παίδων καὶ γυναικὸς ἐπὶ τὰς θύρας δεξάμενος εἰς τὸ συμπόσιον ὁ Λεύκιος ἀπέκτεινεν ἰδίᾳ χειρί τῷ ἐρωμένῳ χαριζόμενος. τοῦτο μὲν οὖν εἰκὸς εἰς δείνωσιν εἰρῆσθαι τῆς κατηγορίας ὑπὸ τοῦ Κάτωνος· ὅτι δὲ οὐκ αὐτόμολον ἤν, ἀλλὰ δεσμώτης ὁ ἀναιρεθεὶς καὶ ἐκ τῶν καταδίκων, ἄλλοι τε πολλοὶ καὶ Κικέρων ὁ ῥήτωρ ἐν τῷ περὶ γήρως αὐτῷ Κάτωνι τὴν διήγησιν ἀναθείς εἴρηκεν.", "st": "Flam. 18.2"}, {"sp": "N", "t": "ἐπὶ τούτῳ Κάτων τιμητὴς γενόμενος καὶ καθαίρων τὴν σύγκλητον ἀπήλασε τῆς βουλῆς τὸν Λεύκιον, ὑπατικοῦ μὲν ἀξιώματος ὄντα, συνατιμοῦσθαι δὲ τοῦ ἀδελφοῦ δοκοῦντος αὐτῷ. διὸ καὶ προελθόντες εἰς τὸν δῆμον ἀμφότεροι ταπεινοὶ καὶ δεδακρυμένοι μέτρια δεῖσθαι τῶν πολιτῶν ἐδόκουν, ἀξιοῦντες αἰτίαν εἰπεῖν τὸν Κάτωνα καὶ λόγον, ᾧ χρησάμενος οἶκον ἔνδοξον ἀτιμίᾳ τοσαύτῃ περιβέβληκεν. οὐδὲν οὖν ὑποστειλάμενος ὁ Κάτων προῆλθε, καὶ καταστὰς μετὰ τοῦ συνάρχοντος ἠρώτησε τὸν Τίτον εἰ γινώσκει τὸ συμπόσιον. ἀρνουμένου δὲ ἐκείνου, διηγησάμενος εἰς ὁρισμὸν προεκαλεῖτο τὸν Λεύκιον εἴ τί φησι τῶν εἰρημένων μὴ ἀληθὲς εἶναι, τοῦ δὲ Λευκίου σιωπήσαντος, ὁ μὲν δῆμος ἔγνω δικαίαν γεγονέναι τὴν ἀτιμίαν καὶ τὸν Κάτωνα προέπεμψε λαμπρῶς ἀπὸ τοῦ βήματος, ὁ δὲ Τίτος τῇ συμφορᾷ τοῦ ἀδελφοῦ περιπαθῶν συνέστη μετὰ τῶν πάλαι μισούντων τὸν Κάτωνα καὶ πάσας μὲν ἃς ἐκεῖνος ἐποιήσατο τῶν δημοσίων ἐκδόσεις καὶ μισθώσεις καὶ ὠνὰς ἠκύρωσε καὶ ἀνέλυσεν ἐν τῇ βουλῇ κρατήσας, πολλὰς δὲ καὶ μεγάλας δίκας κατ’ αὐτοῦ παρεσκεύασεν, οὐκ οἶδε ὅπως εὖ καὶ πολιτικῶς πρὸς ἄρχοντα νόμιμον καὶ πολίτην ἄριστον ὑπὲρ ἀνδρὸς οἰκείου μέν, ἀναξίου δὲ καὶ τὰ προσήκοντα πεπονθότος ἀνήκεστον ἔχθραν ἀράμενος. οὐ μὴν ἀλλὰ τοῦ Ῥωμαίων ποτὲ δήμου θέαν ἔχοντος ἐν τῷ θεάτρῳ καὶ τῆς βουλῆς, ὥσπερ εἴωθε, κόσμῳ προκαθημένης, ὀφθεὶς ὁ Λεύκιος ἐπ’ ἐσχάτοις που καθήμενος ἀτίμως καὶ ταπεινῶς οἶκτον ἔσχε· καὶ τὸ πλῆθος οὐκ ἠνέσχετο τὴν ὄψιν, ἀλλ’ ἐβόων μεταβῆναι κελεύοντες, ἕως μετέβη, δεξαμένων αὐτὸν εἰς ἑαυτοὺς τῶν ὑπατικῶν.", "st": "Flam. 19.1"}, {"sp": "N", "t": "τὸ δὲ οὖν φύσει Τίτου φιλότιμον, ἄχρι μὲν ἱκανὴν εἶχεν ὕλην περὶ τοὺς εἰρημένους πολέμους διατρίβοντος, εὐδοκίμει· καὶ γὰρ ἐχιλιάρχησεν αὖθις μετὰ τὴν ὑπατείαν, οὐδενὸς ἐπείγοντος· ἀπαλλαγεὶς δέ τοῦ ἄρχειν καὶ πρεσβύτερος ὢν ἠλέγχετο μᾶλλον, ἐν οὐκ ἔχοντι πράξεις ἔτι τῷ λοιπῷ βίῳ σπαργῶντα πρὸς δόξαν καὶ νεανίζοντα τῷ πάθει κατέχειν ἑαυτὸν οὐ δυνάμενος. τοιαύτῃ γάρ τινι καὶ τὸ περὶ Ἀννίβαν φορᾷ ἐδόκει πράξας ἐπαχθὴς γενέσθαι τοῖς πολλοῖς. ὁ γὰρ Ἀννίβας οἴκοθεν μὲν ἐκ Καρχηδόνος ὑπεκδρὰς Ἀντιόχῳ συνῆν, ἐκείνου δέ μετὰ τὴν ἐν Φρυγίᾳ μάχην εἰρήνης ἀγαπητῶς τυχόντος, αὖθις φεύγων καὶ πλανηθεὶς πολλά τέλος ἐν τῇ Βιθυνίᾳ κατέστη Προυσίαν θεραπεύων, οὐδενὸς Ῥωμαίων ἀγνοοῦντος, ἀλλὰ παρορώντων ἁπάντων δι’ ἀσθένειαν καὶ γῆρας ὥσπερ ἐρριμμένον ὑπὸ τῆς τύχης. Τίτος δέ πρεσβευτὴς δι’ ἑτέρας δή τινας πράξεις ὑπὸ τῆς βουλῆς πρὸς τὸν Προυσίαν ἀφικόμενος καὶ τὸν Ἀννίβαν ἰδὼν αὐτόθι διαιτώμενον, ἠγανάκτησεν εἰ ζῇ, καὶ πολλά τοῦ Προυσίου δεομένου καὶ λιπαροῦντος ὑπὲρ ἀνδρὸς ἱκέτου καὶ συνήθους οὐ παρῆκε. χρησμοῦ δέ τινος, ὡς ἔοικε, παλαιοῦ περὶ τῆς Ἀννίβου τελευτῆς οὕτως ἔχοντος,", "st": "Flam. 20.1"}, {"sp": "N", "t": "Λίβυσσα κρύψει βῶλος Ἀννίβου δέμας,", "st": "Flam. 20.1b"}, {"sp": "N", "t": "ὁ μὲν ἄρα Λιβύην ὑπενόει καὶ τὰς ἐν Καρχηδόνι ταφάς, ὡς ἐκεῖ καταβιωσόμενος· ἐν δὲ Βιθυνίᾳ τόπος ἐστὶ θινώδης ἐπὶ θαλάσσης καὶ πρὸς αὐτῷ κώμη τις μεγάλη Λίβυσσα καλεῖται, περὶ ταύτην ἔτυχε διατρίβων Ἀννίβας, ἀεὶ δὲ ἀπιστῶν τῇ τοῦ Προυσίου μαλακίᾳ καὶ φοβούμενος τοὺς Ῥωμαίους τὴν οἰκίαν ἔτι πρότερον ἐξόδοις ἑπτὰ καταγείοις συντετρημένην ἐκ τῆς ἑαυτοῦ διαίτης εἶχεν, ἄλλου κατ’ ἄλλο τῶν ὑπονόμων, πόρρω δὲ πάντων ἀδήλως ἐκφερόντων. ὡς οὖν ἤκουσε τότε τὸ πρόσταγμα τοῦ Τίτου, φεύγειν μὲν ὥρμησε διὰ τῶν ὑπονόμων, ἐντυχὼν δὲ φυλακαῖς βασιλικαῖς ἔγνω δι’ αὑτοῦ τελευτᾶν. ἔνιοι μὲν οὖν λέγουσιν ὡς ἱμάτιον τῷ τραχήλῳ περιβαλὼν καὶ κελεύσας οἰκέτην ὄπισθεν ἐρείσαντα κατὰ τοῦ ἰσχίου τὸ γόνυ καὶ σφοδρῶς ἀνακλάσαντα συντεῖναι καὶ περιστρέψαι, μέχρι ἂν ἐκθλίψαι τὸ πνεῦμα, διαφθείρειεν αὑτόν ἔνιοι δέ μιμησάμενον Θεμιστοκλέα καὶ Μίδαν αἷμα ταύρειον πιεῖν· Λίβιος δέ φησι φάρμακον ἔχοντα κεράσαι καὶ τὴν κύλικα δεξάμενον εἰπεῖν ἀναπαύσωμεν ἤδη ποτὲ τὴν πολλὴν φροντίδα Ῥωμαίων, οἳ μακρὸν ἡγήσαντο καὶ βαρὺ μισουμένου γέροντος ἀναμεῖναι θάνατον, οὐ μὴν οὐδὲ Τίτος ἀξιοζήλωτον ἀποίσεται νίκην οὐδὲ τῶν προγόνων ἀξίαν, οἳ Πύρρῳ πολεμοῦντι καὶ κρατοῦντι τὴν μέλλουσαν ὑποπέμψαντες κατεμήνυσαν φαρμακείαν.", "st": "Flam. 20.4"}, {"sp": "N", "t": "οὕτω μὲν τὸν Ἀννίβαν ἀποθανεῖν λέγουσιν. ἀπαγγελθέντων δὲ τούτων πρὸς τὴν σύγκλητον, οὐκ ὀλίγοις ἐπαχθὴς ἔδοξεν ὁ Τίτος καί περιττὸς ἄγαν καί ὠμός, ὥσπερ ὄρνιν ὑπὸ γήρως ἀπτῆνα καί κόλουρον ἀφειμένον ζῆν χειροήθη τὸν Ἀννίβαν ἀποκτείνας, οὐδενὸς ἐπείγοντος, ἀλλὰ διὰ δόξαν, ὡς ἐπώνυμος τοῦ θανάτου γένοιτο. καί τὴν Ἀφρικανοῦ Σκηπίωνος ἐκτιθέντες πρᾳότητα καί μεγαλοψυχίαν ἔτι μᾶλλον ἐθαύμαζον, ὡς ἀήττητον ὄντα καί φοβερὸν ἐν Λιβύῃ καταπολεμήσας Ἀννίβαν οὔτε ἐξήλασεν οὔτε ἐξῃτήσατο παρὰ τῶν πολιτῶν, ἀλλὰ καί πρὸ τῆς μάχης εἰς λόγους ἐλθὼν ἐδεξιώσατο καί μετὰ τὴν μάχην σπενδόμενος οὐδὲν ἐπετόλμησεν οὐδ’ ἐπενέβη τῇ τύχῃ τοῦ ἀνδρός. λέγεται δὲ αὖθις ἐν Ἐφέσῳ συμβαλεῖν αὐτούς· καί πρῶτον μὲν ἐν τῷ συμπεριπατεῖν τοῦ Ἀννίβου τὴν προσήκουσαν ἐν ἀξιώματι τάξιν ἐκείνῳ προλαβόντος ἀνέχεσθαι καί περιπατεῖν ἀφελῶς τὸν Ἀφρικανόν, ἔπειτα λόγου περὶ στρατηγῶν ἐμπεσόντος καί τοῦ Ἀννίβου κράτιστον ἀποφηναμένου γεγονέναι τῶν στρατηγῶν Ἀλέξανδρον, εἶτα Πύρρον, τρίτον δὲ αὑτόν, ἡσυχῇ μειδιάσαντα τὸν Ἀφρικανὸν εἰπεῖν, τί δ’, εἰ μή σε ἐγὼ νενικήκειν; καί τὸν Ἀννίβαν, οὐκ ἂν, ὦ Σκηπίων, φάναι, τρίτον ἐμαυτόν, ἀλλὰ πρῶτον ἐποιούμην τῶν στρατηγῶν.", "st": "Flam. 21.1"}, {"sp": "N", "t": "ταῦτα δὴ τοῦ Σκηπίωνος οἱ πολλοὶ θαυμάζοντες ἐκάκιζον τὸν Τίτον ὡς ἀλλοτρίῳ νεκρῷ προσενεγκόντα τὰς χεῖρας. ἔνιοι δὲ ἦσαν οἱ τὸ πεπραγμένον ἐπαινοῦντες καί τὸν Ἀννίβαν, ἕως ἔζη, πῦρ ἡγούμενοι δεόμενον τοῦ ῥιπίζοντος· μηδὲ γὰρ ἀκμάζοντος αὐτοῦ τὸ σῶμα Ῥωμαίοις καί τὴν χεῖρα φοβεράν, ἀλλὰ τὴν δεινότητα καί τὴν ἐμπειρίαν γεγονέναι μετὰ τῆς ἐμφύτου πικρίας καί δυσμενείας, ὧν οὐδὲν ἀφαιρεῖν τὸ γῆρας,’ ἀλλ’ ὑπομένειν τὴν φύσιν ἐν τῷ ἤθει, τὴν δὲ τύχην οὐ διαμένειν ὁμοίαν, ἀλλὰ μεταπίπτουσαν ἐκκαλεῖσθαι ταῖς ἐλπίσι πρὸς τὰς ἐπιθέσεις τοὺς ἀεὶ τῷ μισεῖν πολεμοῦντας. καί τὰ ὕστερά πως ἔτι μᾶλλον ἐμαρτύρησε τῷ Τίτῳ, τοῦτο μὲν Ἀριστόνικος ὁ τοῦ κιθαρῳδοῦ διὰ τὴν Εὐμενοῦς δόξαν ἐμπλήσας ἅπασαν ἀποστάσεων καί πολέμων τὴν Ἀσίαν, τοῦτο δὲ Μιθριδάτης μετὰ Σύλλαν καί Φιμβρίαν καί τοσοῦτον ὄλεθρον στρατευμάτων καὶ στρατηγῶν αὖθις ἐπὶ Λεύκολλον ἐκ γῆς ὁμοῦ καί θαλάττης ἀναστὰς τηλικοῦτος.", "st": "Flam. 21.5"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ Γαΐου Μαρίου ταπεινότερος Ἀννίβας ἔκειτο, τῷ μὲν γὰρ βασιλεὺς φίλος ὑπῆρχε καί βίος ἦν συνήθης καί διατριβαὶ περὶ ναῦς καί ἵππους καί στρατιωτῶν ἐπιμέλειαν τὰς δὲ Μαρίου τύχας Ῥωμαῖοι γελῶντες ἀλωμένου καί πτωχεύοντος ἐν Λιβύῃ μετὰ μικρὸν ἐν Ῥώμῃ σφαττόμενοι καὶ μαστιγούμενοι προσεκύνουν. οὕτως οὐδὲν οὔτε μικρὸν οὔτε μέγα τῶν παρόντων πρὸς τὸ μέλλον ἐστίν, ἀλλὰ μία τοῦ μεταβάλλειν τελευτὴ καί τοῦ εἶναι. διὸ καί φασιν ἔνιοι Τίτον οὐκ ἀφ’ ἑαυτοῦ ταῦτα πρᾶξαι, πεμφθῆναι δὲ πρεσβευτὴν μετὰ Λευκίου Σκηπίωνος, οὐδὲν ἄλλο τῆς πρεσβείας ἐχούσης ἔργον ἢ τὸν Ἀννίβου θάνατον.", "st": "Flam. 21.7"}, {"sp": "N", "t": "ἐπεὶ δὲ οὐδεμίαν ἔτι τούτων κατόπιν οὔτε πολιτικὴν τοῦ Τίτου πρᾶξιν οὔτε πολεμικὴν ἱστορήκαμεν, ἀλλὰ καί τελευτῆς ἔτυχεν εἰρηνικῆς, ὥρα τὴν σύγκρισιν ἐπισκοπεῖν.", "st": "Flam. 21.7b"}, {"sp": "HDR", "t": "Φιλοποίμενος καὶ Τίτου σύγκρισις"}, {"sp": "N", "t": "μεγέθει μὲν οὖν τῶν εἰς τοὺς Ἕλληνας εὐεργεσιῶν οὔτε Φιλοποίμενα Τίτῳ παραβάλλειν οὔτε πάνυ πολλοὺς τῶν Φιλοποίμενος ἀμεινόνων ἀνδρῶν ἄξιόν ἐστι. τοῖς μὲν γὰρ Ἕλλησι πρὸς Ἕλληνας οἱ πόλεμοι, τῷ δὲ οὐχ Ἕλληνι καὶ ὑπὲρ Ἑλλήνων· καὶ ὅτε Φιλοποίμην ἀμηχανῶν τοῖς ἑαυτοῦ πολίταις ἀμύνειν πολεμουμένοις εἰς Κρήτην ἀπῆρε, τότε νικήσας Τίτος ἐν μέσῃ τῇ Ἑλλάδι Φίλιππον ἠλευθέρου καὶ τὰ ἔθνη καὶ πόλεις ἁπάσας. εἰ δέ τις ἐξετάζοι τὰς μάχας ἑκατέρου, πλείους Ἕλληνας Φιλοποίμην Ἀχαιῶν στρατηγῶν ἢ Μακεδόνας Τίτος Ἕλλησι βοηθῶν ἀνεῖλε.", "st": "Comp. Phil.–Flam. 1.1"}, {"sp": "N", "t": "τὰ τοίνυν ἁμαρτήματα τοῦ μὲν φιλοτιμίας, τοῦ δὲ φιλονεικίας γέγονε, καὶ πρὸς ὀργὴν ὁ μὲν εὐκίνητος, ὁ δὲ καὶ δυσπαραίτητος. Τίτος μὲν γὰρ καὶ Φιλίππῳ τὸ ἀξίωμα τῆς βασιλείας ἐφύλαξε καὶ πρὸς Αἰτωλοὺς εὐγνωμόνησε, Φιλοποίμην δὲ τῆς πατρίδος δι’ ὀργὴν ἀφείλετο τὴν περιοικίδα συντέλειαν. ἔτι δὲ ὁ μὲν τοῖς εὖ παθοῦσιν ἀεὶ βέβαιος, ὁ δὲ θυμῷ λῦσαι χάριν ἕτοιμος. Λακεδαιμονίων γὰρ εὐεργέτης πρότερον ὢν ὕστερον καὶ τὰ τείχη κατέσκαψε καὶ τὴν χώραν περιέκοψε καὶ τέλος αὐτὴν μετέβαλε καὶ διέφθειρε τὴν πολιτείαν. ἐδόκει δὲ καὶ τὸν βίον ὀργῇ προέσθαι καὶ φιλονεικίᾳ, μὴ κατὰ καιρὸν, ἀλλ’ ὀξύτερον τοῦ δέοντος εἰς Μεσσήνην ἐπειχθείς, οὐχ ὥσπερ Τίτος πάντα λογισμῷ καὶ πρὸς ἀσφάλειαν στρατηγήσας.", "st": "Comp. Phil.–Flam. 1.3"}, {"sp": "N", "t": "ἀλλὰ πλήθει γε πολέμων καὶ τροπαίων ἡ Φιλοποίμενος ἐμπειρία βεβαιοτέρα, τῷ μὲν γὰρ τὰ πρὸς Φίλιππον ἐκρίθη δυοῖν ἀγώνοιν, ὁ δὲ μυρίας μάχας κατορθώσας οὐδεμίαν ἀμφισβήτησιν τῇ τύχῃ πρὸς τὴν ἐπιστήμην ἀπολέλοιπεν. ἔτι δὲ ὁ μὲν τῇ Ῥωμαίων ἀκμὴν ἐχούσῃ δυνάμει χρησάμενος, ὁ δὲ τῆς Ἑλλάδος ἤδη φθινούσης ἐπακμάσας, δόξαν ἔσχεν, ὥστε τοῦ μὲν ἴδιον, τοῦ δὲ κοινὸν ἔργον εἶναι τὸ κατορθούμενον ὁ μὲν γὰρ ἦρχεν ἀγαθῶν, ὁ δὲ ἄρχων ἀγαθοὺς ἐποίει. καὶ μὴν τό γε πρὸς Ἕλληνας τούτῳ γενέσθαι τοὺς ἀγῶνας οὐκ εὐτυχῆ μέν, ἰσχυρὰν δὲ τῆς ἀρετῆς ἀπόδειξιν παρεῖχεν οἷς γὰρ ὅμοια τἆλλα, τῷ προὔχειν ἀρετῇ κρατοῦσι. καὶ γὰρ δὴ πολεμικωτάτοις Ἑλλήνων Κρησὶ καὶ Λακεδαιμονίοις πολεμήσας, τῶν μὲν πανουργοτάτων δόλῳ, τῶν δ’ ἀλκιμωτάτων τόλμῃ περιεγένετο.", "st": "Comp. Phil.–Flam. 2.1"}, {"sp": "N", "t": "πρὸς δὲ τούτοις Τίτος μὲν ἐξ ὑποκειμένων ἐνίκα, χρώμενος ὁπλισμοῖς καὶ τάξεσιν αἷς παρέλαβε. Φιλοποίμην δὲ αὐτὸς ἐπεισενεγκὼν καὶ μεταβαλὼν τὸν περὶ ταῦτα κόσμον, ὥστε τὸ νικητικώτατον ὑφ’ οὗ μὲν οὐκ ὂν εὑρῆσθαι, τῷ δὲ ὑπάρχον βοηθεῖν. κατὰ χεῖρα τοίνυν Φιλοποίμενος μὲν ἔργα πολλὰ καὶ μεγάλα, θατέρου δὲ οὐδέν, ἀλλὰ καὶ τῶν Αἰτωλῶν τις αὐτὸν Ἀρχέδημος ἐπέσκωπτεν ὡς, ὅτε αὐτὸς ἐσπασμένος τὴν μάχαιραν ἔθει δρόμῳ πρὸς τοὺς μαχομένους καὶ τοὺς συνεστῶτας τῶν Μακεδόνων, τοῦ Τίτου τὰς χεῖρας εἰς τὸν οὐρανὸν ὑπτίας ἀνατείναντος ἑστῶτος καὶ προσευχομένου.", "st": "Comp. Phil.–Flam. 2.3"}, {"sp": "N", "t": "καὶ μὴν Τίτῳ μὲν ἄρχοντι συνέβη καὶ πρεσβεύοντι πάντα πρᾶξαι τὰ καλά, Φιλοποίμην δὲ οὐ χείρονα παρέσχεν οὐδὲ ἀπρακτότερον ἑαυτὸν ἰδιώτην ἢ στρατηγὸν τοῖς Ἀχαιοῖς. ἰδιώτης μὲν γὰρ ὢν Νάβιν ἐξέβαλεν ἐκ Μεσσήνης καὶ Μεσσηνίους ἠλευθέρωσεν, ἰδιώτης δὲ Διοφάνην τὸν στρατηγὸν καὶ Τίτον ἐπερχομένους ἀπέκλεισε τῆς Σπάρτης καὶ Λακεδαιμονίους διέσωσεν. οὕτως ἡγεμονικὴν φύσιν ἔχων οὐ κατὰ τοὺς νόμους, ἀλλὰ καὶ τῶν νόμων ἄρχειν ἠπίστατο πρὸς τὸ συμφέρον, οὐ δεόμενος παρὰ τῶν ἀρχομένων λαβεῖν τὸ ἄρχειν, ἀλλὰ χρώμενος αὐτοῖς, ὅπου καιρὸς εἴη, τὸν ὑπὲρ αὐτῶν φρονοῦντα μᾶλλον ἢ τὸν ὑπ’ αὐτῶν ᾑρημένον ἡγούμενοις στρατηγόν.", "st": "Comp. Phil.–Flam. 3.1"}, {"sp": "N", "t": "γενναῖα μὲν οὖν Τίτου τὰ πρὸς τοὺς Ἕλληνας ἐπιεικῆ καὶ φιλάνθρωπα, γενναιότερα δὲ Φιλοποίμενος τὰ πρὸς τοὺς Ῥωμαίους ὀχυρὰ καὶ φιλελεύθερα ῥᾷον γὰρ χαρίζεσθαι τοῖς δεομένοις ἢ λυπεῖν ἀντιτείνοντα τοὺς δυνατωτέρους. ἐπεὶ δὲ οὕτως ἐξεταζομένων δυσθεώρητος ἡ διαφορά, σκόπει, μὴ τῷ μὲν Ἕλληνι τὸν ἐμπειρίας πολεμικῆς καὶ στρατηγίας στέφανον, τῷ δὲ Ῥωμαίῳ τὸν δικαιοσύνης καὶ χρηστότητος ἀποδιδόντες οὐ φαύλως διαιτᾶν δόξομεν.", "st": "Comp. Phil.–Flam. 3.3"}], []);})();
